\subsection{Problems with order-preserving preferences}\label{subseccion de order-preserving preferences}
%Next, we introduce the subdomain of problems order-preserving preferences which captures the idea that although an agent's well-being is affected by the coalitions formed by others (i.e., externalities are present), what matters most to the agent is the ranking of the coalitions to which she herself belongs. 
Next, we study problems with order-preserving preferences. These preferences capture the idea that although an agent's well-being is affected by the coalitions formed by others (i.e., externalities are present), what matters most to the agent is the ranking of the coalitions to which she herself belongs. In other words, agents have preferences with externalities, but of a lexicographic nature: they primarily rank their own coalitions and consider the configuration of other coalitions only secondarily.   





 Given a partition $\pi$ and an agent $i$, let $[\pi]_i$ denote the set of all partitions containing coalition $\pi(i)$, i.e. $[\pi]_i=\{\pi'\in \Pi:\pi'(i)=\pi(i)\}.$
\medskip

\noindent\textbf{Order-preserving preferences:}  a preference relation $\succsim_i$ is order-preserving if for each $\pi,\pi'\in \Pi$,
\begin{enumerate}[(i)]
    \item $\pi \sim_i\pi'$ implies $\pi(i)=\pi'(i)$,
    \item $\pi(i)\neq \pi'(i)$ and $\pi \succ_i \pi'$ imply $\widetilde{\pi}\succ_i\widetilde{\pi}'$ for each $\widetilde{\pi}\in [\pi]_i$ and each  $\widetilde{\pi}'\in [\pi']_i$.\footnote{In the literature, order-preserving preferences are also known as preferences with weak externalities or egocentric preferences \citep[see][among others]{sasaki1996two,hong2022core,fonseca2023notes}.}
\end{enumerate} Let $\boldsymbol{\mathcal{R}_{op}}$ denote the domain of problems with order-preserving preferences.

\medskip

Condition (i) says that an agent can be indifferent only between partitions that leave her in the same coalition. Condition (ii) says that given two different partitions, $\pi$ and $ \widetilde{\pi}$ such that  $ \widetilde{\pi} \in  [\pi]_i$, there is no partition $\pi' \notin  [\pi]_i$ such that $\pi \succ_i \pi' \succ_i \widetilde{\pi}$.  This means that each agent is concerned first of all about the coalition she belongs to, and then about the other coalitions. 


Under this framework, effectiveness of the top-partition collection guarantees not only that the stable set is non-empty, but also that it coincides with the core and contains a unique partition. This fact will be shown in Theorem \ref{core=estable}, but in order to do so, we first present two technical lemmata.

The first shows that if the only difference between two partitions is that coalition $S$ is formed in one of them whereas subcoalitions of $S$ are formed in the other, then both partitions cannot be part of the same effective top-partition collection.   

\begin{lemma}\label{remark para que no sea efectivo}
       Let $\left(\mathcal{K},\succsim\right)$ be a problem in  $\mathcal{R}_{op}$, and let $\mathcal{V}$ be a top-partition collection. If $\pi,\pi'\in \mathcal{V}$ and $S\subseteq N$ are such that $S\in \pi$ and $S=D(\pi,\pi')$,  then  $\mathcal{V}$ is not effective.
\end{lemma}
\begin{proof}
Let $\mathcal{V}$ be a top-partition collection and assume that $\pi,\pi'\in \mathcal{V}$ and $S\subseteq N$ are such that $S\in \pi$ and $S=D(\pi,\pi')$. 
%Let $\pi,\pi'\in \mathcal{V}$ and $S\subseteq N$ be such that $S\in \pi$ and $S=D(\pi,\pi')$. 
Then, $\pi'(i)\subsetneq S$ for each $i\in S$ and $\pi(i)=\pi'(i)$ for each $i\in N \setminus S.$ Assume that $\mathcal{V}$ is effective. Thus, $\pi\succ_i\pi'$ for each $i\in S$. Therefore, there is no $S'\subsetneq S$ such that $\pi' \succ_i \pi$ for each $i\in S'$. This contradicts that $\mathcal{V}$ is effective. 
\end{proof}


%\tcr{Si  $|\mathcal{V}|>1$ y $\{N\}\in \mathcal{V}$, entonces $\mathcal{V}$ is not effective. Si $\mathcal{V}$ es effective, entonces $\{N\}\notin \mathcal{V}$ o $|\mathcal{V}|=1$. Si tengo weak exter. $\mathcal{V}$ es effective y $\{N\}\in \mathcal{V}$, entonces $|\mathcal{V}|=1$.}

Notice that the previous result applies to problems with  unrestricted preferences. Lemma \ref{remark para que no sea efectivo} helps us to demonstrate that effective top-partition collections can contain only one element in problems with  order-preserving preferences. Formally,

\begin{lemma}\label{teo V no efectivo}
    Let $\left(\mathcal{K},\succsim\right)$ be a problem in $\mathcal{R}_{op}$. If $\mathcal{V}$ is a top-partition collection  with $|\mathcal{V}|>1$, then $\mathcal{V}$ is not effective.
\end{lemma}
\begin{proof}
    Let $\mathcal{V}$ be a top-partition collection with $|\mathcal{V}|>1$. Assume that $\mathcal{V}$ is effective. Let $\pi,\pi'\in \mathcal{V}$ be such that $\pi\neq \pi'$. Then, there is $S\subseteq D(\pi,\pi')$ such that $S\in \pi$ and $\pi \succ_i \pi'$ for each $i\in S$.
    Note that, for $i\in S$,  $\pi \succ_i \pi'$  and the fact that $\succ_i$ is an order-preserving preference imply that $\widetilde{\pi} \succ_i \widetilde{\pi}'$   for each $\widetilde{\pi} \in [\pi]_i$  and each $\widetilde{\pi}' \in [\pi']_i$. 
Then, $[\pi]_i\subseteq \mathcal{V}$. 
Take any $\pi^{\star}\in [\pi]_i$. There are two cases to consider:
\begin{enumerate}
\item[\textbf{1.}]\textbf{There is 
 a coalition $\boldsymbol{S'\in \pi^{\star}$ such that $S'\cap S=\emptyset$ and $|S'|>1.}$} Then, define $\pi^{\star\star}$ as follows:
$$\pi^{\star\star}(i)=\begin{cases}
    \{i\}& \text{for each }i\in S'\\
    \pi^{\star}(i)&\text{otherwise.}
\end{cases}$$
Note that $S'=D(\pi^\star,\pi^{\star\star})$. Thus, by Lemma \ref{remark para que no sea efectivo}, we have that  $\mathcal{V}$ is not effective, a contradiction. 

\item[\textbf{2.}]\textbf{There is no
 coalition $\boldsymbol{S'\in \pi^{\star}$ such that $S'\cap S=\emptyset$ and $|S'|>1.}$} Then, consider any partition $\pi^{\star\star}\in[\pi]_i$ such that there is a unique non-singleton coalition $S^\star$ with   $S^\star\in \pi^{\star\star}\setminus \pi^\star$. Note that,  $D(\pi^\star,\pi^{\star\star})=S^\star.$ Thus, by Lemma \ref{remark para que no sea efectivo}, we have that  $\mathcal{V}$ is not effective, a contradiction.
\end{enumerate}
Therefore, if $|\mathcal{V}|>1$, then $\mathcal{V}$ is not effective.
\end{proof}

%\begin{theorem}\label{core=estable}
 %   Let $\left(\mathcal{K},\succsim\right)$ be a coalition formation problem defined on domain $\mathcal{R}_{op}$. If the problem has an effective top-partition collection, then $\mathcal{C}=\mathcal{S}.$ Moreover $|\mathcal{S}|=1$.
%\end{theorem}

Now, we are in a position to prove the following result.


\begin{theorem}\label{core=estable}
   Let $\left(\mathcal{K},\succsim\right)$ be a problem in $\mathcal{R}_{op}$. If the problem has an effective top-partition collection $\mathcal{V}$, then there is $\pi^\star\in \Pi$ such that $\{\pi^\star\} = \mathcal{V}=\mathcal{C}=\mathcal{S}.$ 
\end{theorem}
\begin{proof}
   Note that, by definition of  $\mathcal{C}$ and $\mathcal{S},$ we have that $\mathcal{C}\subseteq\mathcal{S}.$
   Assume  that $\mathcal{C}\subsetneq\mathcal{S}$. Then, there exists $\pi\in \mathcal{S}\setminus\mathcal{C}.$ Let $\mathcal{V}$ be an effective top-partition collection. By Lemma \ref{teo V no efectivo}, since $\mathcal{V}$ is effective, it follows that $|\mathcal{V}|=1$.  By Theorem \ref{core=v}, we have $\mathcal{V}=\mathcal{C}$. Since $\pi\notin \mathcal{C}$, it follows that $\pi\notin \mathcal{V}$. Let $\mathcal{V}=\{\pi^{\star}\}$. As $\pi^{\star}\neq \pi$, there exists $C\in \pi^{\star}\setminus \pi$. There are two cases to consider:
   \begin{enumerate}
       \item[\textbf{1.}] \textbf{$\boldsymbol{\pi^{\star}\gg \pi$ via $C}$.} Then, $\pi \notin \mathcal{S}$ which is a contradiction. 
        \item[\textbf{2.}] \textbf{$\boldsymbol{\pi^{\star}\not\gg \pi$ via $C}$.} Let $\widetilde{\pi}$ be such that 
       $$\widetilde{\pi}(i)=\begin{cases}
        C  &  i\in C \\
        \pi(i) & \pi(i)\cap C=\emptyset \\
        \{i\} & \text{otherwise}.
       \end{cases}
       $$

Let $j\in C$. Since $\mathcal{V}=\{\pi^{\star}\}$, we have $\widetilde{\pi}\in [\pi^{\star}]_j$. Moreover, because preferences are order-preserving, it follows that $\widetilde{\pi}\succ_j\pi$. Thus, $\widetilde{\pi}\gg \pi$ via $C$, which implies $\pi \notin \mathcal{S}$, again a contradiction. 
   \end{enumerate}

In both cases, we reach a contradiction, which implies that $\{\pi^\star\} = \mathcal{V}=\mathcal{C}=\mathcal{S}.$  
 \end{proof}

