        $\{12,34\}$ && $\{13,24\}$ && $\{12,34\}$ && $\{13,24\}$ \\ 
        $\{13,2,4\}$&& $\{13,2,4\}$ && $\{13,2,4\}$ &&$\{13,2,4\}$  \\ 
        $\vdots$  && $\vdots$ && $\vdots$ && $\vdots$ \\       \hline
