\section{Introduction}

\bigskip
As it is well-known, front-type solutions for reaction equations are a research area covered by many papers. Quite a wide literature is available on the existence and the properties of {\it traveling wave solutions} (for short t.w.s.'s) for many types of reaction-diffusion equations: monostable or bistable, degenerate or doubly degenerate, with advection or accumulation effects, or with changing-sign diffusivities, governed by the $p$-Laplacian or other type of differential operators (see, e.g. the recent papers \cite{AV1,AV2,BCM,CMP,CMS,GS2,Ga}). 

Such a great variety of the dynamics investigated concerns equations with continuous coefficients, and consequently regular t.w.s.'s. Nevertheless, there are some models involving discontinuous coefficients (see, e.g., \cite{SZW} for a model with a discontinuous diffusivity, and \cite{ARV, DHT, FN, Te, Va} for models with a reaction term depending on the Heaviside function).
This motivates the interest in studying t.w.s.'s for reaction-diffusion equations with discontinuous coefficients.

In \cite{DJKZ} (see also \cite{DZ}) the authors considered the monostable equation
\[u_t+f(u)u_x=(d(u)|u_x|^{p-2}u_x)_x + h(u)\]
with \(p>1\), where the reaction term \(h\) is continuous, but the diffusivity \(d\) is lower-semicontinuous and the convective term \(f\) is piecewise continuous. Both \(d\) and \(f\) may have jump-type discontinuities. The authors proved the existence of infinitely many t.w.s.'s having speed \(c\) in a halfline \([c^*,+\infty)\) and provided an estimate for the unknown threshold value \(c^*\).

According to our knowledge, no papers concern the study of t.w.s.'s for general equations involving discontinuous reaction terms \(h\) too, and this is the main goal of the present paper.


Indeed, 
we consider a very general monostable reaction-diffusion-convection equation involving also a nonlinear accumulation term \(g\), that is,
\begin{equation}
\label{pdeprob}
f(u)u_x + g(u)u_t = (d(u)|u_x|^{p-2}u_x)_x + h(u), \quad (x,t)\in\R^2,
\end{equation}
with $p>1$, where all the coefficients \(f,g,d,h\) are just piecewise continuous functions, having at most a finite number of discontinuities.

More precisely,
let $\hat{C}[0,1]$ [resp., $\hat{C}(0,1)$] be the set of the piecewise continuous functions $\mu:[0,1]\to\R$ [resp., $\mu:(0,1)\to \R$] having a finite set $\D(\mu):=\{\gamma_1,\ldots,\gamma_n\}\subset (0,1)$ of discontinuity points. In what follows, we do not consider removable discontinuities, that is, points $\xi_0\in(0,1)$ such that $\mu(\xi)\to l\in\R$ as $\xi\to\xi_0$ but $l\neq\mu(\xi_0)$, since our solutions will be strictly monotone and the value of a coefficient at a single point does not influence the dynamics. In other words, we will identify  functions which differ, at most, in a finite number of points.

Throughout the paper, we assume that
\begin{enumerate}[label={$({\rm H}_\arabic*)$},ref={${\rm H}_\arabic*$}]
\item\label{ip:hatC} $f,g,h\in\hat{C}[0,1]\cap L^\infty(0,1)$, $d\in \hat C(0,1)$
\item\label{ip:d}  
 \(\dis\inf_{\xi\in[a,b]}d(\xi)>0\) and   \(\dis\sup_{\xi\in[a,b]}d(\xi)<+\infty\) whenever \(0<a<b<1\).
\item\label{ip:acca} 
 $h(0)=h(1)=0$ and 
 \(\dis\inf_{\xi\in[a,b]}h(\xi)>0\)  whenever \(0<a<b<1\).
\item\label{ip:kappa} $\kappa:=d^{\frac{1}{p-1}}h\in L^1(0,1)$.
\end{enumerate}
Notice that \(d\) is allowed to be unbounded near 0 and 1, or to vanish at 0 and 1. When \(d(0^+)=0\) and/or \(d(1^-)=0\), the equation  \eqref{pdeprob} is said {\it degenerate} or {\it doubly degenerate}. Analogously, it is said {\it singular} or {\it doubly singular} if $d(u)\to+\infty$ when $u\to0^+$ and/or $u\to1^-$.

%Concerning the reaction term $h:[0,1]\to\R$, we will suppose that it is of {\it monostable} type, that is $h>0$ in $(0,1)$ and $h(0)=h(1)=0$



When searching  for  t.w.s.'s, that is, solutions $u(x,t):=v(x-ct)$, for some one-variable function \(v\) (the wave profile) and some $c\in\R$  (the wave speed), 
 the wave profile $v=v(z)$ solves the ordinary differential equation
\begin{equation}
\label{odeprob0}
(d(v)|v'|^{p-2}v')'+(cg(v)-f(v))v'+h(v)=0, \quad v\in[0,1].
\end{equation}
More specifically, we are interested in the heteroclinic solutions to \eqref{odeprob0} joining the equilibria $v=1$ and $v=0$, i.e., the solutions to
\begin{equation}
\label{odeprob}
\left\{
\begin{alignedat}{1}
&(d(v)|v'|^{p-2}v')'+(cg(v)-f(v))v'+h(v)=0, \quad v\in[0,1], \\
&v(-\infty)=1,\quad v(+\infty)=0.
\end{alignedat}
\right.
\end{equation}
Due to the presence of possible discontinuities, we cannot expect the solutions of \eqref{odeprob} to be regular everywhere, but we will search for solutions continuously differentiable at each point where \(0<v(z)<1\), with the exception, at most, of the discontinuity points of the diffusivity \(d\), satisfying equation \eqref{odeprob} at the points where all the coefficients are continuous (see Definition \ref{defsol}, Proposition \ref{prop:nec}, and Remark \ref{rem:differ} for a detailed discussion about this matter).





In order to state our main result, we introduce the following notations, by putting
% \beq \kappa(\xi):=d(\xi)^{\frac{1}{p-1}}h(\xi) \quad \mbox{for all} \;\;\xi\in(0,1) \label{def:kappa} \eeq
% and
\begin{equation}
\label{notation}
F_0:=\sup_{\xi\in(0,1)}\fint_0^\xi f(\tau)\dtau, \quad G_0:=\inf_{\xi\in(0,1)}\fint_0^\xi g(\tau)\dtau, \quad  K_0:=\sup_{\xi\in(0,1)}\fint_0^\xi \frac{\kappa(\tau)}{\tau^{\frac{1}{p-1}}}\dtau,
\eeq
\beq
\ell_p:=\liminf_{\xi\to0^+}\frac{\kappa(\xi)^{p-1}}{\xi}\ , \quad L_p:=\limsup_{\xi\to0^+}\frac{\kappa(\xi)^{p-1}}{\xi}.
\label{notation2}
\end{equation}
We will consider the set
\beq \label{def:Gamma-c}
\C:=\{c\in\R: \, \mbox{there exists a t.w.s. of speed } \, c\}.
\eeq

The following theorem is an immediate consequence of Theorems \ref{t:mainthm1} and \ref{t:mainthm2} in Section 5 (see also Remark \ref{finalrmk}).

\begin{thm}
\label{mainthm}
Suppose that $G_0>0$. Then, if 
$\ell_p=+\infty$, no t.w.s. exists. Instead, if \(L_p<+\infty\), then $\C=[c^*,+\infty)$ for some $c^*\in\R$ fulfilling
\begin{equation}
\label{threshold}
\frac{f(0)}{g(0)}+\frac{p'}{g(0)}(p-1)^{\frac{1}{p}}\ell_p^{\frac{1}{p}} \leq c^* \leq \frac{F_0}{G_0}+\frac{p'}{G_0}(p-1)^{\frac{1}{p}}K_0^{\frac{1}{p'}}.
\end{equation}
\end{thm}
Incidentally, we notice that \eqref{threshold} is well defined, since $\displaystyle{g(0)=\lim_{\xi\to0^+}\fint_0^\xi g(\tau)\dtau\geq G_0>0}$. Actually (see Theorems \ref{t:mainthm1} and \ref{t:mainthm2}, as well as Remark \ref{finalrmk}), the assumption $G_0>0$ can be relaxed by supposing $g(0)>0$ and
\begin{equation}
\label{implement1}
\int_0^\xi g(\tau)\dtau\geq0 \quad \mbox{for all} \;\; \xi\in[0,1],
\end{equation}
provided that \eqref{threshold} is replaced by the more general conditions
\begin{equation*}
%\label{implement2}
\begin{aligned}
\inf_{\xi\in(0,1)} \fint_0^\xi (c^*g(\tau)-f(\tau)) \dtau &\leq p'(p-1)^{\frac{1}{p}}\left(\sup_{\xi\in(0,1)} \fint_0^\xi \frac{\kappa(\tau)}{\tau^{\frac{1}{p-1}}}\dtau\right)^{\frac{1}{p'}}, \\
c^* g(0)-f(0) &\geq p'(p-1)^{\frac{1}{p}}\ell_p^{\frac{1}{p}}.
\end{aligned}
\end{equation*}
Finally, if one removes also condition \eqref{implement1}, then it is possible to show that \(\mathcal C\) admits minimum \(c^*\) but in this case we cannot state  \(\mathcal C\) is a half-line (see Theorem \ref{t:mainthm2}).

%\cred{Letturatura.}

%This paper was motivated by \cite{CMP} (see also \cite{M}) and \cite{DJKZ}: the former treats a semi-linear reaction-diffusion-convection equation having continuous coefficients and a general convection term, while the latter deals with \eqref{pdeprob} when $g\equiv 1$ and only $f,d$ may be discontinuous. 

Our results generalize the ones in \cite{DJKZ} in various directions:
\begin{itemize}
\item the generality of the reaction-diffusion equation, which involves also an accumulation term \(g\), possibily discontinuous and not necessarily positive;
\item we allow all the terms to be discontinuous (in particular the reaction term \(h\)), without restrictions on the type of discontinuities;
\item the estimate \eqref{threshold} for the threshold value \(c^*\) is finer that the one in \cite[Theorem 2.1]{DJKZ}, according to Remark \ref{finalrmk};
\item the assumptions required in the existence and non-existence results are more general.
\end{itemize}

\noindent
More in detail, as for the last point, we underline that by requiring assumption \eqref{ip:kappa}, we allow not only the diffusion \(d\), but also the product \(\kappa\) to be unbounded near the equilibrium 1. According to our knowledge, this situation is new even in the classical case.

\medskip
In the present paper we do not investigate the classification of the t.w.s.'s, that is, if they attains the equilibria at finite times (with a non-zero slope), distinguishing between {\it classical} and {\it sharp} ones (see, e.g., \cite{CMP}), since possible discontinuities in the interior of the interval \([0,1]\) do not interfer with the behavior of the t.w.s. at the equilibria.
So, the classification of the t.w.s.'s in the case of discontinuous coefficients does not differ from that of the continuous ones.  Instead, the case when  \(\kappa\), or simply \(d\), is unbounded near 1 is completely new (also for the classical case) and might deserve to be investigated.

% It is worth noticing that \cite{M} partially addresses the first issue, but not the second one. \cblue{Anyway, we highlight that, unlike \cite{CMP}, the present paper does not deal with the classification of t.w.s.'s to \eqref{pdeprob}, which is a topic of independent interest and can be analyzed hopefully arguing as in \cite[Section 5]{CMP}, since each coefficient of \eqref{pdeprob} is continuous near the equilibrium states $0$ and $1$.}

\bigskip

We proceed in this way. After giving, in Section 2, the definition of solution to \eqref{odeprob}, coherently with \cite{CMP} and \cite{DJKZ}, we analyze its main properties and we show how \eqref{odeprob} reduces to a first-order singular boundary value problem (BVP) in Section 3. En passant, we prove a local a priori estimate from below, which is crucial to handle the singularity. Then, in Section 4, we regularize the singular BVP by introducing the concept of $\eps$-regularization, reminiscent of the classical linear interpolation methods. Then, we use the inf-stability of the $\Gamma$-convergence, discussed in the same section, to ensure that the existence conditions in \cite{M}, involving the quantities appearing in \eqref{notation}, are preserved through $\eps$-regularization at the limit $\eps\to0^+$. Finally, in Section 5, we give sufficient conditions ensuring either existence or non-existence of t.w.s.'s; then, assuming also \eqref{implement1}, we present a structure theorem for $\C$.

\section{Solutions and their properties}





\bigskip

This section is devoted to giving the definition of solution to problem \eqref{odeprob} and studying the main properties of the solutions.

First of all, let us introduce the following notation. Set


\begin{equation*}
\Theta:= \D(d)\cup\D(f)\cup\D(g)\cup\D(h) \ \ \text{and} \ \ \Theta^*:=\Theta\cup\{0,1\}. %\label{def:Theta}
\end{equation*}
Notice that if \(v:\R\to [0,1]\) is continuous then both \(v^{-1}(\Theta)\) and \(v^{-1}(\Theta^*)\) are closed, since \(\Theta\) and \(\Theta^*\) are closed.


\begin{defi}\label{defsol}
A continuous function \(v:\R\to [0,1]\) is  a solution of  \eqref{odeprob} if \( v\in C^1(\R\setminus v^{-1}(\Theta^*))\), satisfies the boundary conditions at \(\pm \infty\), and there exists a continuous function \(\Phi_v:\R\to \R\) such that:
\begin{enumerate}[label={{\rm (\roman*)}}]
\item\label{defa}  \(\Phi_v(z)=d(v(z))|v'(z)|^{p-2}v'(z)\) in each open interval where \(v\) is $C^1$;
\item\label{defnew} \(\dis\lim_{z\to \pm \infty} \Phi_v(z)=0\);
\item\label{defb} \(\Phi_v(z)=0\) whenever \(v(z)=0\) or \(v(z)=1\);
\item \label{defc} the following integral formulation of \eqref{odeprob} holds for any \(z_1,z_2\in \R\):
\beq 
\Phi_v(z_2)-\Phi_v(z_1)+\int_{v(z_1)}^{v(z_2)} (cg(\xi)-f(\xi)) \dxi + \int_{z_1}^{z_2} h(v(z)) \dz=0.\label{eq:integr}
\eeq
%where \(F(\xi):=\dis\int_0^\xi f(\tau) \dtau\) and %\(G(\xi):=\dis\int_0^\xi g(\tau) \dtau\).

\end{enumerate}

\end{defi}

\medskip
\noindent
The following result summarizes the main properties of the solutions to problem \eqref{odeprob}.

\medskip

\begin{prop} \label{prop:nec}
Let \(v\) be a solution of problem \eqref{odeprob}. Then, put 

\beq
I_v:=\{z\in \R : \ 0<v(z) <1\}, \label{def:Iv}
\eeq 
we have that \(I_v\) is an open (bounded or unbounded) interval and \(v\) is strictly decreasing in \(I_v\), with \(v'(z)<0\) for every \(z\in I_v\setminus v^{-1}(\Theta)\).
%Moreover,  for every \(z\in  v^{-1}(\Theta)\) the one-sided derivatives \(v'(z^-)\) and \(v'(z^+)\) exist and are finite.

Furthermore, $\Phi_v(z)<0$ for every $z\in I_v$, \(\Phi_v\) is $C^1$ in \(I_v\setminus v^{-1}(\Theta)\), and satisfies \beq
\Phi_v'(z)+(cg(v(z))-f(v(z)))v'(z)+h(v(z))=0 \quad \text{for every } z\in I_v\setminus v^{-1}(\Theta). \label{eq:differ}
\eeq

%Finally, if \(d\) is bounded then and %\(\dis\lim_{z\to \pm \infty} \Phi_v(z)=0\).

\end{prop}

\medskip
\begin{proof}
We split the proof into various steps.

\medskip



\smallskip
\noindent

\medskip
{\bf Claim 1.} The solution \(v\) cannot be constant in any interval \((a,b)\subseteq I_v\).

\smallskip
Indeed, if \(v\) is constant in an interval \((a,b)\subseteq I_v\), then by the definition of solution we have \(\Phi_v(z)=d(v(z))|v'(z)|^{p-2}v'(z)=0\) for each \(z\in (a,b)\), and by \eqref{eq:integr} we derive \(h(v(z))=0\) for every \(z\in (a,b)\), contradicting the positivity of the function \(h\) in \((0,1)\).


\medskip
{\bf Claim 2.} If \(v(z_1)=v(z_2)\) for some \(z_1,z_2 \in I_v\), \(z_1<z_2\), then \(v(z)\ge v(z_1)\) for every \(z\in (z_1,z_2)\cap I_v\).

\smallskip
Let \(z_1,z_2\in I_v\) be such that \(v(z_1)=v(z_2)\). Assume by contradiction that \(v(z^*)<v(z_1)\) for some \(z^*\in (z_1,z_2)\cap I_v\). Since \(\Theta\) is a finite set, there exists a value \(\bar\xi\in (v(z^*),v(z_1))\setminus \Theta\). Put 
\[ \zeta_1:= \sup\{z>z_1 \ : v(\zeta)\ge\bar\xi \ \text{ for every } \zeta\in (z_1,z)\}\]
\[\zeta_2:= \inf\{z<z_2 \ : v(\zeta)\ge \bar\xi \ \text{ for every } \zeta\in (z,z_2)\}.\]
Of course, \(v(\zeta_1)=v(\zeta_2)=\bar\xi\) and  \(\zeta_1<\zeta_2\). Moreover,  since \(\bar\xi \not \in \Theta\), \(v\) is $C^1$ in a neighborhood of \(\zeta_1, \zeta_2\), with \(v'(\zeta_1)\le 0\) and \(v'(\zeta_2)\ge 0\), by the definition of \(\zeta_1,\zeta_2\).
On the other hand, by \eqref{eq:integr}, we have
\begin{align*}
d(\bar\xi) (|v'(\zeta_2)|^{p-2}v'(\zeta_2)-|v'(\zeta_1)|^{p-2}v'(\zeta_1))&= d(v(\zeta_2))|v'(\zeta_2)|^{p-2}v'(\zeta_2) - d(v(\zeta_1))|v'(\zeta_1)|^{p-2}v'(\zeta_1) \\
&= \Phi_v(\zeta_2)-\Phi_v(\zeta_1)=-\int_{\zeta_1}^{\zeta_2} h(v(z)) \dz <0
\end{align*}
implying \(v'(\zeta_2)<v'(\zeta_1)\), a contradiction.


\medskip


%{\bf Claim 3.} If \(v(z_1)=v(z_2)\) for some \(z_1,z_2 \in I_v\) with \(z_1<z_2\), then \(v(z)> v(z_1)\) for every \(z\in (z_1,z_2)\).

%\smallskip
%Assume \(v(z^*)=v(z_1)\) for some \(z^*\in (z_1,z_2)\).By claims 1 and 2 we deduce the existence of \(\zeta_1 \in (z_1,z^*)\) and \(\zeta_2\in (z^*,z_2)\) such that \(v(\zeta_1), v(\zeta_2)> v(z^*)\). Since \(\Theta\) is finite, we can choose a value \(\xi^* \in (0,1)\setminus \Theta\), such that \(v(z^*)<\xi^*<\min\{v(\zeta_1), v(\zeta_2)\}\). So, there exist \(\zeta_1^*\in (\zeta_1,z^*)\) and \(\zeta_2^*\in (z^*,\zeta_2)\) such that \(v(\zeta_1^*)=v(\zeta_2^*)=\xi^*> v(z^*)\), in contradiction with Claim 2.


\medskip
{\bf Claim 3.} The solution \(v\) is strictly decreasing in \(I_v\) and \(I_v\) is an open interval.
\smallskip

Assume, by contradiction, that \(v(z_1)< v(z_2)\) for some 
\(z_1,z_2\in I_v\), with \(z_1<z_2\). Then, since \(v(-\infty)=1\), we infer that there exists a point \(\zeta_1 <z_1\) such that \(v(\zeta_1)=v(z_2)\), in contrast to Claim 2. So, \(v\) is decreasing in \(I_v\). Moreover, by Claim 1 we deduce that \(v\) is strictly decreasing in \(I_v\).
Then, \(I_v\) consists of a unique (open) interval.

\medskip
{\bf Claim 4.} \(\Phi_v\) is \(C^1\) in \(I_v\setminus v^{-1}(\Theta)\) and equation \eqref{eq:differ}
 holds true.
\smallskip

Fix \(z\in I_v\setminus v^{-1}(\Theta)\) and let \(\delta>0\) be such that \(z+\varepsilon\in I_v\setminus v^{-1}(\Theta) \) if \(|\varepsilon|<\delta\) (this is possible since \(I_v\setminus v^{-1}(\Theta)\) is an open set).
So, consider equation \(\eqref{eq:integr}\) with \(z_1=z\) and \(z_2=z+\varepsilon\). Dividing by \(\varepsilon\ne 0\) and passing to the limit as \(\varepsilon\to 0\) we get that \(\Phi_v\) is differentiable at \(z\) and
\[ \Phi_v'(z) + [c(g(v(z))- f(v(z))]v'(z) + h(v(z))=0.\]
Hence, \(\Phi_v\) is \(C^1\) in \(I_v\setminus v^{-1}(\Theta)\).

\medskip
{\bf Claim 5.} For every \(z\in I_v \setminus v^{-1}(\Theta)\) we have \(v'(z)<0\) and \(\Phi_v(z)<0\).
\smallskip

Indeed, assume by contradiction \(v'(z_0)=0\) for some \(z_0\in I_v\setminus v^{-1}(\Theta)\). Then, since $v\in C^1$ in a neighborhood of $z_0$, by equation 
\eqref{eq:differ} we get \(\Phi_v'(z_0)=(d(v(z_0))|v'(z_0)|^{p-2}v'(z_0))'=-h(v(z_0))<0\), with \(\Phi_v(z_0)=0\), so we have \(\Phi_v(z)=d(v(z))|v'(z)|^{p-2}v'(z)>0\) in a left neighborhood of \(z_0\), in contradiction to Claim 3. So, \(v'(z)<0\) and by Definition \ref{defsol}\ref{defa} we also have \(\Phi_v(z)<0\).

% \medskip
% {\bf Claim 6.} for every \(z\in v^{-1}(\Theta)\) there exist, finite, the one-sided derivatives \(v'(z^-), v'(z^+)\).
% \smallskip

% Fix \(z_0\in v^{-1}(\Theta)\). Since \(v\) is strictly decreasing in \(I_v\) and \(\Theta\) is a finite set, we have that \(v\) is differentiable in a punctured neighborhood of \(z_0\). Then
% \[ \lim_{z\to z_0^\pm } v'(z) = -\lim_{z\to z_0^\pm } \left|\frac{\Phi_v(z)}{d(v(z))}\right|^{\frac{1}{p-1}} = -\left|\frac{\Phi_v(z_0)}{d(v(z_0)^\mp)}\right|^{\frac{1}{p-1}} \in \R.\]

\medskip
{\bf Claim 6.} $\Phi_v(z)<0$ for every \(z\in I_v\).

\smallskip
 Since \(\Theta\) is finite, by Claim 3 also $v^{-1}(\Theta)$ is finite. So, Claim 5 ensures \(\Phi_v(z)\le 0\) for every \(z\in \R\). Assume by contradiction \(\Phi_v(z_0)=0\) for some \(z_0\in v^{-1}(\Theta)\). Since \(v\) is strictly decreasing in \(I_v\) and \(\Theta\) is a finite set, we have that \(v\) is $C^1$ in a punctured neighborhood of \(z_0\). Hence,
\[ 0=\Phi_v(z_0)=\lim_{z\to z_0} \Phi_v(z)=-\lim_{z\to z_0^\pm} d(v(z))|v'(z)|^{p-1}. \]
Therefore, since \(\displaystyle{\liminf_{\xi\to v(z_0)}d(\xi)>0}\), we deduce \(v'(z_0^+)=v'(z_0^-)=0\), implying that \(v\) is differentiable at \(z_0\) with \(v'(z_0)=0\). Hence, chosen a number \(\delta>0\) such that \([z_0-\delta, z_0+\delta]\subseteq (0,1)\) and put \(\mu:=\inf_{[z_0-\delta,z_0+\delta]} h(z)>0\), by \eqref{eq:integr} we have
\begin{align*}
\limsup_{\varepsilon \to 0^+} \frac{-\Phi_v(z_0-\varepsilon)}{\varepsilon} &=\limsup_{\varepsilon \to 0^+} \frac{1}{\varepsilon} \left(\Phi_v(z_0)- \Phi_v(z_0-\varepsilon) \right)  \\ 
&= \limsup_{\varepsilon \to 0^+}\frac{1}{\varepsilon} \left( \int_{v(z_0-\varepsilon)}^{v(z_0)} (f(\xi)-c g(\xi))\dxi  -\int_{z_0-\varepsilon}^{z_0} h(v(\zeta)) \dzeta \right) \\ &=\limsup_{\varepsilon \to 0^+}\left(\frac{v(z_0)-v(z_0-\varepsilon)}{\varepsilon}  \fint_{v(z_0-\varepsilon)}^{v(z_0)} (f(\xi)-c g(\xi)) \dxi  -\fint_{z_0-\varepsilon}^{z_0} h(v(\zeta)) \dzeta \right)\\ &\le -\mu<0.
\end{align*}

\noindent
Therefore, \(\Phi(z)>0\) in a left neighborhood of \(z_0\), a contradiction. 

\end{proof}

\begin{rmk} Taking account of the properties proved in the previous proposition, it is  easy to check that  Definition  \ref{defsol} reduces to the classical one when \(\Theta=\emptyset\). Indeed, in this case \(\Theta^*=\{0,1\}\) and then \(v\in C^1(I_v)\). So \(\Phi_v(z) = d(v(z))|v'(z)|^{p-2} v'(z)\) in \(I_v\), with \(\Phi_v\in C^1(I_v)\) and
\[ (d(v(z))|v'(z)|^{p-2} v'(z))'+ (cg(v(z))-f(v(z)))v'(z) + h(v(z)) =0 \]
for every \(z\in I_v\). Finally,
\[ \lim_{z\to \pm \infty} d(v(z))|v'(z)|^{p-2} v'(z)=0. \]
\end{rmk}


\begin{rmk}\label{rem:differ}
 In light of Proposition \ref{prop:nec}, we see that the set \(v^{-1}(\Theta)\) is finite, so there are, at most, a finite number of points where \(v\) is not differentiable. %, with \(v'(z^+), v'(z^-) \le 0\) (cfr. Claim 6 of Proposition \ref{prop:nec}).
However, note that actually \(v\) is $C^1$ in \(I_v\setminus \D(d)\). Indeed, if \(z_0\in I_v\setminus \D(d)\), since \(v\) is $C^1$ in a punctured neighborhood of \(z_0\), by Definition \ref{defsol}\ref{defa} there exists, finite, the limit
\[ \dis  \lim_{z\to z_0} v'(z) = -\lim_{z\to z_0} \left|\frac{\Phi_v(z)}{d(v(z))}\right|^{\frac{1}{p-1}}=-\left|\frac{\Phi_v(z_0)}{d(v(z_0))}\right|^{\frac{1}{p-1}}<0.\]
%Moreover, since  $v'(z)<0$ in $I_v\setminus %v^{-1}(\D(d))$, then by Definition %\ref{defsol}\ref{defa} we have
%\begin{equation}
%\label{Phi}
%\Phi_v(z)=-d(v(z))|v'(z)|^{p-1}.
%\end{equation}

Finally, since \(I_v\) is an interval, we find that 
 if \(v(z_*)=1\) for some \(z_*\in \R\), then \(v(z)=1\) for all \(z\le z_*\); similarly,
 if \(v(z^*)=0\) for some \(z^*\in \R\), then \(v(z)=0\) for all \(z\ge z^*\).

Therefore, put 
\beq \Gamma_v := v^{-1}(\D(d)) \ , \quad  \Gamma_v^\circ = v^{-1}(0)\cup v^{-1}(1), \quad   \Lambda_v:= \Gamma_v\cup \partial\Gamma_v^\circ,
\label{def:Gamma} \eeq
 $\Lambda_v$ is a finite set
and \(v\in C^1(\R\setminus \Lambda_v)\). 
%\label{rem:diff}


\noindent
We underline that if \(v\) attains one or both the values 0 and 1 at finite \(z\), that is if \(\Gamma_v^\circ\ne \emptyset\), then in general \(v\) is not differentiable at such points and the t.w.s. is said to be {\em sharp}. This phenomenon does not depend on the presence of discontinuities of the coefficients of the equation, but it occurs when \(d\) vanishes at 0 or at 1 (degenerate or doubly degenerate equations). As we clarified in the Introduction, we do not investigate this topic in the present paper.
\end{rmk} 

\begin{rmk} \label{rem:AC}
If \(v\) is a solution of problem \eqref{odeprob}, due to the monotonicity proved in Proposition \ref{prop:nec}, we have that \(v'\in L^1_{\text{loc}}(\R)\) so, since \(v\in C^0(\R)\cap C^1(\R\setminus \Lambda_v)\), we deduce \(v\in W^{1,1}_{\text{loc}}(\R)\). 
\newline
Similarly, equation \eqref{eq:differ} 
implies that \(\Phi_v'\in L^1_{\text{loc}}(\R)\) and \(\Phi_v\) is \(C^1\) in \(I_v\setminus v^{-1}(\Theta)\). Hence, also \(\Phi_v\in W^{1,1}_{\text{loc}}(\R)\).
\end{rmk}

\begin{prop}
    If \(d\) is bounded in \((0,1)\), then condition \ref{defnew} in Definition \ref{defsol} is a consequence of the other conditions \ref{defa}, \ref{defb} and \ref{defc}.
\end{prop}

\begin{proof}
First, notice that condition \ref{defnew} has not been used in the proof of Proposition \ref{prop:nec}. 

Put \(a_v:=\inf I_v\) and \(b_v:=\sup I_v\) (see \eqref{def:Iv}). If either \(a_v\) or \(b_v\) is finite, condition \ref{defnew} is a consequence of \ref{defb} and the monotonicity of \(v\). Instead, if \(b_v=+\infty\) then by \eqref{eq:integr} we have, for any \(z_1, z\) with \(z_1<z\),
\[ \Phi_v(z)- \Phi_v(z_1)= 
\int_{v(z)}^{v(z_1)} (cg(\xi)-f(\xi)) \dxi
-\int_{z_1}^z h(v(\zeta)) \dzeta. \]
Therefore, there exists (finite or not) the limit
\[ L:= \lim_{z\to +\infty} \Phi_v(z)= \Phi_v(z_1)+\int_0^{v(z_1)} (cg(\xi)-f(\xi))\dxi-\int_{z_1}^{+\infty} h(v(\zeta)) \dzeta. \]
Since \(\Phi_v(z)<0\) for every \(z\in I_v\), we infer \(L\le 0\). If \(L< 0\) then, put  
\(M:=\dis \sup_{\xi \in (0,1)} d(\xi)\),
 we infer
\[ \limsup_{z\to +\infty} v'(z)= -\liminf_{z\to +\infty} \left|\frac{\Phi_v(z)}{d(v(z))}\right|^{\frac{1}{p-1}}\leq -\left(\frac{|L|}{M}\right)^{\frac{1}{p-1}}<0,\]
in contrast to the boundedness of \(v\). Thus, \(L=0\). The same argument works when \(a_v=-\infty\).
\end{proof}



\section{Reduction to a first-order problem}

As usual in the study of t.w.s.'s, 
problem \eqref{odeprob} can be reduced to a boundary value problem for a singular first-order ODE, as the next result shows.


% From now on we put 
% \beq \kappa(\xi):= h(\xi)d(\xi)^{\frac{1}{p-1}}.
% \label{def:kappa}
% \eeq

\begin{prop}\label{prop:equiv}
Let the function \(\kappa\) be defined in \eqref{ip:kappa}. Then problem \eqref{odeprob} is equivalent to
\begin{equation}
\label{odeprob2}
\left\{
\begin{alignedat}{2}
\dot y &= cg(\xi)-f(\xi)-\frac{\kappa(\xi)}{y^{\frac{1}{p-1}}} \quad &&\mbox{in} \;\; (0,1)\setminus \Theta, \\
y&>0 \quad &&\mbox{in} \;\; (0,1), \\
y(0^+)&=y(1^-)=0,
\end{alignedat}
\right.
\end{equation}
in the following sense:

\begin{itemize}
\item if $v\in C(\R)\cap C^1(\R\setminus\Lambda_v)$ (see \eqref{def:Gamma}) is a solution to \eqref{odeprob}, then $y(\xi):=-\Phi_v(v^{-1}(\xi))$ is in $C(0,1)\cap C^1((0,1)\setminus\Theta)$ and solves \eqref{odeprob2};

\item if $y\in C(0,1)\cap C^1((0,1)\setminus\Theta)$ is a solution to \eqref{odeprob2} then the function $w:(0,1)\to\R$ defined as
$$ w(\xi):=-\int_{\frac{1}{2}}^\xi \left(\frac{d(\tau)}{y(\tau)}\right)^{\frac{1}{p-1}} \dtau \quad \mbox{for all} \;\; \xi\in(0,1) $$
is invertible in a suitable interval $(a,b)$ (possibly unbounded), and its inverse $w^{-1}:(a,b)\to(0,1)$ can be extended to a solution of \eqref{odeprob}.
\end{itemize}
\end{prop}


\begin{proof}
%We set $H(\xi):=cg(\xi)-f(\xi)$ and
%$K(\xi):=D(\xi)h(\xi)$ for all $\xi\in(0,1)$. 
Pick any $v\in C(\R)\cap C^1(\R\setminus\Lambda_v)$ solution to \eqref{odeprob}. Then, for every $\xi\in(0,1)\setminus\Theta$, one has $v^{-1}(\xi)\in I_v\setminus v^{-1}(\Theta)$. Hence, \eqref{eq:differ} with $z=v^{-1}(\xi)$  ensures
$$ \Phi_v'(v^{-1}(\xi))+(cg(\xi)-f(\xi))v'(v^{-1}(\xi))+h(\xi)=0 \quad \mbox{for all}\;\; \xi\in(0,1)\setminus\Theta. $$
Dividing by $-v'(v^{-1}(\xi))$, which is positive, entails
\beq \label{eq:doty} -\frac{\Phi_v'(v^{-1}(\xi))}{v'(v^{-1}(\xi))}-(cg(\xi)-f(\xi))-\frac{h(\xi)}{v'(v^{-1}(\xi))}=0 \quad \mbox{for all}\;\; \xi\in(0,1)\setminus\Theta. \eeq
Setting $y(\xi):=-\Phi_v(v^{-1}(\xi))$ for all $\xi\in(0,1) $, it turns out that $y\in C(0,1)\cap C^1((0,1)\setminus\Theta)$ with $\dot y(\xi)=-\frac{\Phi_v'(v^{-1}(\xi))}{v'(v^{-1}(\xi))}$. Therefore, by \eqref{eq:doty} we get
$$ \dot y(\xi)-(cg(\xi)-f(\xi))+\frac{\kappa(\xi)}{y(\xi)^{\frac{1}{p-1}}}=0 \quad \mbox{for all}\;\; \xi\in(0,1)\setminus\Theta. $$
Moreover, since $\Phi_v(z)<0$ for all $z\in I_v$ (see Proposition \ref{prop:nec}), then $y(\xi)>0$ for all $\xi\in(0,1)$. Finally, by Definition \ref{defsol}\ref{defnew}--\ref{defb}, we have $\Phi_v(v^{-1}(\xi))\to 0$ as $\xi\to 0^+$ (resp., $\xi\to 1^-$), so $y(0^+)=0$ (resp., $y(1^-)=0$).

\medskip
Now let $y\in C(0,1)\cap C^1((0,1)\setminus\Theta)$ be a solution to \eqref{odeprob2}. Since $y(\xi)>0$ for all $\xi\in(0,1)$ and $d^{\frac{1}{p-1}}=\frac{\kappa}{h}\in L^1(\frac{1}{2},\xi)$ for all $\xi\in(0,1)$, due to \eqref{ip:acca} and \eqref{ip:kappa}, then $w$ is well-defined and strictly decreasing in $(0,1)$. Moreover, $w$ is differentiable at every \(\xi\in (0,1)\setminus \D(d)\), with $w'(\xi)=-\left(\frac{d(\xi)}{y(\xi)}\right)^{\frac{1}{p-1}}<0$. 

Set $a:=w(1^-)$ and $b:=w(0^+)$ (which may be one or both infinite), and consider 
\beq \label{eq:inverse} v(z):=w^{-1}(z)\ , \quad \Phi_v(z):= -y(v(z))\ , \quad \text{for all }  z\in(a,b).\eeq 
If either \(a\) or \(b\) is finite, we extend the functions \(v, \Phi_v\) as constants, i.e. we put
\beq v(z)\equiv 1 \ \text{ in } (-\infty,a]; \quad v(z)\equiv 0\ \text{ in } [b,+\infty); \quad \Phi_v(z)\equiv 0 \ \text{ in } \R\setminus (a,b).  \label{eq:exten}\eeq

Of course, $v$ and \(\Phi_v\) are continuous in $\R$ and \(v\) is strictly decreasing in \(I_v:=(a,b)\). Moreover, $v$ is 
differentiable at any $z\in I_v\setminus v^{-1}(\D(d))$, with $v'(z)=-\left(\frac{y(v(z))}{d(v(z))}\right)^{\frac{1}{p-1}}<0$. Hence, we have 
\[\Phi_v(z)= - y(v(z))= -d(v(z))|v'(z)|^{p-1}<0 \quad \text{for every } z \in I_v\setminus v^{-1}(\D(d)).
\]
On the other hand, if \(z\in v^{-1}(\D(d))\), then \(v\) is not \(C^1\) in a neighborhood of  \(z\). Indeed, otherwise we have \(v'(z)\ne 0\) because \(d\) is bounded in a neighborhood of \(v(z)\), and then 
\[ \lim_{\xi \to v(z)} d(\xi)= \lim_{\xi \to v(z)} \frac{|\Phi_v(v^{-1}(\xi))|}{|v'(v^{-1}(\xi))|^{p-1}}=  \frac{|\Phi_v(z)|}{|v'(z)|^{p-1}},\]
contradicting \(v(z)\in \D(d)\) (recall that we do not consider removable discontinuities; see the Introduction).
%\[ |v'(z^+)|^{p-1}=\frac{|\Phi_v(z)|}
%{d(v(z)^-)} \ne \frac{|\Phi_v(z)|}{d(v(z)^+)}= %|v'(z^-)|^{p-1}.\]
So, \(\Phi_v\) satisfies Definition \ref{defsol}\ref{defa}.

Moreover, \(\Phi_v\) is differentiable at every $z\in I_v\setminus v^{-1}(\Theta)$, with \(\Phi_v'(z) = -\dot y(v(z)) v'(z)\). 
Then, since $y$ solves \eqref{odeprob2}, for every $z\in I_v\setminus v^{-1}(\Theta)$ we obtain
\begin{equation}
\label{eq:diffcomp}
\begin{aligned}
\Phi_v'(z)=-\dot y(v(z))v'(z) &= 
-[cg(v(z))-f(v(z))]v'(z) + \frac{d(v(z))^{\frac{1}{p-1}}h(v(z))}{y(v(z))^{\frac{1}{p-1}}}v'(z)
\\
&= -[cg(v(z))-f(v(z))]v'(z) -h(v(z)), \\
\end{aligned}
\end{equation}
i.e., \eqref{eq:differ}.

Finally, 
since \(v\) and \(\Phi_v\) are absolutely continuous in any compact interval (see Remark \ref{rem:AC}), integrating 
\eqref{eq:diffcomp} in a generic interval \([z_1,z_2]\subseteq \overline{I}_v\) produces \eqref{eq:integr} in $\overline{I}_v$. Outside $\overline{I}_v$, \eqref{eq:integr} is straightforward.

The validity of the properties in Definition \ref{defsol}\ref{defnew}--\ref{defb} is a trivial consequence of \eqref{eq:inverse} and \eqref{eq:exten}.

\end{proof}

