The next result provides a necessary condition for the existence of solutions. 

\begin{lemma} If problem \eqref{odeprob2} admits solutions then, put \(\lambda:=\ell_p^\frac{1}{p-1}\) (see \eqref{notation2}), 
 % \[ \dis\lambda:=\liminf_{\xi\to 0^+} \frac{\kappa(\xi)}{\xi^{\frac{1}{p-1}}},\]  
  we have \(\lambda<+\infty\). Moreover, setting \(\eta(t):= t^\frac{p}{p-1} - (cg(0)-f(0))t^\frac{1}{p-1} + \lambda\), we have  \( \dis\min_{t\ge 0}\eta(t) \le 0\).
\label{lem:nuovo}
\end{lemma}

\begin{proof}
Let \(y\) be a solution to \eqref{odeprob2}. 
Put \(\varphi(\xi):=\frac{y(\xi)}{\xi}\), \(\xi\in (0,1)\). We set
$$ L:=\limsup_{\xi\to0^+}\varphi(\xi), \quad M:=\limsup_{\xi\to0^+}\dot y(\xi). $$
Notice that $L\leq M$: indeed, taking any sequence $\xi_n\to 0$ such that $\varphi(\xi_n)\to L$, by the mean value theorem there exists $\zeta_n\to 0$ such that $\dot y(\zeta_n)=\varphi(\xi_n)$ for all $n\in\N$, yielding $M\geq L$.

We have, for all $\xi\in(0,1)\setminus\Theta$,
\beq
(\dot y(\xi)  - (cg(\xi)-f(\xi))) \varphi(\xi)^{\frac{1}{p-1}}= -\frac{\kappa(\xi)}{\xi^{\frac{1}{p-1}}}.
\label{eq:modif}
\eeq
So, if \(\lambda=+\infty\), 
 then 
\beq
\label{eq:limite}
\lim_{\xi\to 0}  (\dot y(\xi)  - (cg(\xi)-f(\xi))) \varphi(\xi)^{\frac{1}{p-1}}=-\infty.
\eeq
On the other hand, if $L=+\infty$ then $M=+\infty$ and, for a suitable sequence $\xi_n\to 0$,
$$(\dot y(\xi_n)  - (cg(\xi_n)-f(\xi_n))) \varphi(\xi_n)^{\frac{1}{p-1}}\geq 0,$$
contradicting \eqref{eq:limite}. Instead, if $L<+\infty$, then $\|\varphi\|_\infty<+\infty$ and we choose $\Lambda>\|\varphi\|_\infty^{\frac{1}{p-1}}\|cg-f\|_\infty$, so that \eqref{eq:limite} furnishes $\delta>0$ (depending on $\Lambda$) such that
$$  (\dot y(\xi)  - (cg(\xi)-f(\xi))) \varphi(\xi)^{\frac{1}{p-1}}<-\Lambda $$
for all $\xi\in(0,\delta)$, whence
$$ \dot y(\xi) \leq -\frac{\Lambda}{\|\varphi\|_\infty^{\frac{1}{p-1}}}+\|cg-f\|_\infty<0, $$
due to the choice of $\Lambda$. This forces $y$ to be negative in $(0,\delta)$, contradicting \eqref{odeprob2}.

Let us now consider the function \(\eta\) and fix a value \(\varepsilon>0\). By the definition of \(\lambda\) and \eqref{eq:modif},  there exists a positive \(\delta=\delta_\varepsilon>0\) such that
\beq(\dot y(\xi)  - (cg(\xi)-f(\xi))) \varphi(\xi)^{\frac{1}{p-1}} +\lambda \le  \varepsilon \quad \text{ for every } \xi \in (0,\delta).\label{eq:dis1}\eeq
Take any sequence $\xi_n\to0^+$ such that $\dot y(\xi_n)\to M$. Up to subsequences, $\varphi(\xi_n)\to k\in[0,+\infty]$. Then \eqref{eq:dis1} rewrites as
\beq(\dot y(\xi_n)  - (cg(\xi_n)-f(\xi_n))) \varphi(\xi_n)^{\frac{1}{p-1}} +\lambda \le  \varepsilon \quad \text{ for every } n\in\N.\label{eq:dis1seq}\eeq
If $k=+\infty$, then $L=M=+\infty$, so letting $n\to\infty$ in \eqref{eq:dis1seq} leads to a contradiction. Hence $k<+\infty$. Now, if $M=+\infty$, then $\dot y(\xi_n)>k$ for any $n$ sufficiently large, so that
$$(k  - (cg(\xi_n)-f(\xi_n))) \varphi(\xi_n)^{\frac{1}{p-1}} +\lambda \le  \varepsilon,$$
whence
$$\eta(k) = \lim_{n\to\infty} (k  - (cg(\xi_n)-f(\xi_n))) \varphi(\xi_n)^{\frac{1}{p-1}} +\lambda \leq \eps,$$
so $\displaystyle{\min_{t\geq 0} \eta(t)\leq \eta(k)\leq 0}$, since $\varepsilon$ was arbitrary. Otherwise, if both $k$ and $M$ are finite, then \eqref{eq:dis1seq} entails $(M-(cg(0)-f(0)))k^{\frac{1}{p-1}}+\lambda\leq\varepsilon$. 
Since \(k\le L\le M\), we have
$$ \eta(k) = (k-(cg(0)-f(0)))k^{\frac{1}{p-1}}+\lambda\leq (M-(cg(0)-f(0)))k^{\frac{1}{p-1}}+\lambda\leq\varepsilon $$
for all $\varepsilon>0$, yielding $\displaystyle{\min_{t\geq 0}\eta(t) \leq \eta(k)\leq 0}$. 
%Otherwise, reasoning as in the previous case, %$M<cg(0)-f(0)$ produces $%\displaystyle{\min_{t\geq 0}\eta(t) \leq \eta(M)\leq 0}$.
\end{proof}


% \cred{fine nuova versione}


We conclude this section with the following result, providing a uniform positive lower bound for the solutions of \eqref{odeprob2} in the compact subsets of \((0,1)\). 

\medskip
\begin{lemma}\label{l:lowboun}
Put \(I_r:=[r,1-r]\) for every \(r\in(0,\frac12)\). Fix \(r_0\in(0,\frac12)\) such that \(\Theta\subset I_{r_0}\).


Then, for every \(r\in (0, \frac12 r_0)\) and every \(m,M>0\), there exists \(\delta=\delta_{r,m,M}>0\) such that if 

\beq \label{ip:lowboun}
\inf_{\xi\in I_r} \kappa(\xi)\ge m \quad \text{ and } \quad
\sup_{\xi\in I_r} |cg(\xi)-f(\xi)|\le M 
\eeq
we have 
\beq
\label{eq:lowerpos}
y(\xi)\ge \delta \quad \text{ for all } \xi\in I_{2r}
\eeq
for every positive solution
\(y\in C(0,1)\cap C^1((0,1)\setminus \Theta)\) of the differential equation in \eqref{odeprob2}. \end{lemma}

\begin{proof} Fix \(r\in(0,\frac12 r_0)\) and \(m,M>0\). Choose
  $\delta=\delta_{r,m,M}<
 \min\left\{(r m)^{\frac{1}{p'}},\left(\frac{m}{p(M+1)}\right)^{p-1}\right\}\).  
Fix an arbitrary \(\xi_0\in I_{2r}\) and set $\varphi(\xi):=(\delta^{p'}-m(\xi-\xi_0))^{\frac{1}{p'}}$ for all $\xi\in [\xi_0,\xi_1]$, with \(\xi_1:=\xi_0+\frac{\delta^{p'}}{m}\). Note that \([\xi_0,\xi_1]\subset I_r\) by the choice of \(\delta\).

Assume that \eqref{ip:lowboun} holds true. Then,
for all \(\xi\in I_r\) and positive \(s<\left(\frac{m}{p(M+1)}\right)^{p-1}\), again by the choice of \(\delta\) we have

\beq
\label{subsol1}
s^{\frac{1}{p-1}}+(cg(\xi)-f(\xi))s^{\frac{1}{p-1}} - \kappa(\xi)< (M+1) s^{\frac{1}{p-1}}- m < -\frac{m}{p'}.
\eeq
Moreover,
$\varphi(\xi)\leq\delta<\left(\frac{m}{p(M+1)}\right)^{p-1}$ for every \(\xi\in [\xi_0,\xi_1]\). So, by \eqref{subsol1} we obtain
\begin{equation}
\label{eq:subsol2}
\dot \varphi(\xi)=-\frac{m}{p'\varphi(\xi)^{\frac{1}{p-1}}} >
1+cg(\xi)-f(\xi) - \frac{\kappa(\xi)}{\varphi(\xi)^{\frac{1}{p-1}}} \quad \text{ for every } \xi \in [\xi_0,\xi_1).
 \end{equation}

Moreover, since \(\varphi(\xi_1)=0<y(\xi_1)\), we can define 
\[\bar \xi:=\inf\{\xi\in[\xi_0,\xi_1]: \varphi(\tau)< y(\tau)\ \text{ for every } \tau\in [\xi,\xi_1] \}.\]
Let us prove that \(\bar\xi=\xi_0\). Indeed, if \(\bar\xi >\xi_0\), then \(\varphi(\bar\xi)=y(\bar\xi)>0\), so \eqref{eq:subsol2} entails
\begin{align*}
\dot \varphi(\bar \xi)&=\lim_{\xi\to \bar\xi^+} \dot \varphi(\xi)\ge 1+\limsup_{\xi \to \bar \xi^+} \left(cg(\xi)-f(\xi) - \frac{\kappa(\xi)}{\varphi(\xi)^{\frac{1}{p-1}}}\right) \\
 &\ge 1+\limsup_{\xi \to \bar \xi^+} \left(cg(\xi)-f(\xi) - \frac{\kappa(\xi)}{y(\xi)^{\frac{1}{p-1}}}\right)=1+ \limsup_{\xi\to\bar\xi^+}\dot y(\xi),
\end{align*}
which is a contradiction since \(\varphi(\bar\xi)=y(\bar\xi)\) and \(\varphi(\xi)<y(\xi)\) in a right neighborhood of \(\bar \xi\).
Therefore, we conclude that \(\bar\xi=\xi_0\), implying 
\(\delta= \varphi(\xi_0)\le y(\xi_0)\). 

The assertion follows from the arbitrariness of \(\xi_0\).

\begin{rmk}\label{r:AC}
As a consequence of Lemma \ref{l:lowboun}, if \(y\) is a solution of \eqref{odeprob2} then \(y\in W^{1,\infty}(I)\) for every closed interval \(I\subset (0,1)\). Therefore, since \(y\in C[0,1]\), we get that \(y\) is absolutely continuous in \([0,1]\).
Moreover, notice  that if problem \eqref{odeprob2} admits a solution then we necessarily have \(c\int_0^1 g(\xi) \dxi > \int_0^1 f(\xi) \dxi\). Indeed, if \(y\) is a solution, then
\[ 0=y(1^-)-y(0^+) = \int_0^1 \dot y(\xi) \dxi < \int_0^1 (cg(\xi)-f(\xi)) \dxi.\]
\end{rmk}

\end{proof}





\section{Regularized approximating problems}



The technique we adopt to prove the main result is
based on the regularization of the discontinuous coefficients of the equation in \eqref{odeprob}, in order to be able to use the known results concerning equations with continuous coefficients.
To this aim, let us introduce the concept of 
$\eps$-regularization of a function belonging to $\hat{C}(0,1)\cap L^1(0,1)$.

\begin{defi}
\label{epsreg}
Let $\phi\in\hat{C}(0,1)\cap L^1(0,1)$ and let \(A\supseteq \D(\phi)\) be a finite set in \((0,1)\), say \(A=\{\gamma_1,\ldots,\gamma_n\}\), being $\gamma_i<\gamma_{i+1}$ for all $i=1,\ldots,n-1$. Put $\gamma_0:=0$ and $\gamma_{n+1}:=1$. Finally, set $\overline{\eps}:=\frac{1}{2}\min\{\gamma_{i+1}-\gamma_i: \, i=0,\ldots,n\}$. 

For any $\eps\in(0,\overline{\eps})$, we call $\eps$-regularization of $\phi$ related to \(A\) the function $\phi_\eps^{(A)}:(0,1)\to\R$ defined as
\begin{equation*}
\phi_\eps^{(A)}(x)=\left\{
\begin{alignedat}{2}
&\phi(\gamma_i-\eps)+\frac{\phi(\gamma_i+\eps)-\phi(\gamma_i-\eps)}{2\eps}(x-(\gamma_i-\eps)) \quad &&\mbox{if} \;\; x\in[\gamma_i-\eps,\gamma_i+\eps], \;\; i=1,\ldots,n, \\
%&\frac{\phi(1-\eps)}{\eps}(1-x) \quad &&\mbox{if} \;\; x\in[1-\eps,1], \\
&\phi(x) \quad &&\mbox{elsewhere}. \\
\end{alignedat}
\right.
\end{equation*}
When \(A=\D(\phi)\) we simply write \(\phi_\varepsilon\).
\end{defi}

\medskip
\begin{rmk}
\label{epsregprops}


By definition, $\phi_\eps^{(A)}\in C(0,1)$ for all $\eps\in(0,\overline{\eps})$ and $\phi_\eps^{(A)}\to\phi$ locally uniformly in $(0,1)\setminus A$ as $\eps\to 0$. Moreover, it is readily seen that $(\alpha\phi)_\eps^{(A)}=\alpha \phi_\eps^{(A)}$ for all \(\alpha\in \R\) and $\eps\in(0,\overline{\eps})$.
Furthermore, if \(\phi,\psi \in \hat{C}(0,1)\cap L^1(0,1)\) and \(\alpha,\beta\in \R\), then for every finite set \(A\supseteq \D(\phi)\cup \D(\psi)\) we have \((\alpha \phi +\beta\psi)_\eps^{(A)} =  \alpha \phi_\eps^{(A)} +\beta\psi_\eps^{(A)}\).

Finally, if $I\subset(0,1)$ is a closed interval such that $\partial I \cap A = \emptyset$ and \(\phi \) is bounded in \(I\), then there exists $\hat{\eps}=\hat{\eps}(I)$ such that
\begin{equation}
\label{supest}
\sup_{I} |\phi_\eps^{(A)}| \le \sup_{I} |\phi|  \quad \mbox{for all} \;\; \eps\in(0,\hat{\eps})
\end{equation}
and
\begin{equation}
\label{infest}
\inf_I \phi_\eps^{(A)} \geq \inf_I \phi \quad \mbox{for all} \;\; \eps\in(0,\hat{\eps}).
\end{equation}
\end{rmk}

\medskip
Thanks to the \(\eps\)-regularization of the functions in \(\hat{C}(0,1)\cap L^1(0,1)\), we can reduce to problem \eqref{odeprob2} with \(f,g,h\) continuous in \([0,1]\) and \(d\) continuous in \((0,1)\) (so that \(\Theta=\emptyset\)). In such a setting, problem \eqref{odeprob2} has been investigated in \cite{M}, where an existence result has been obtained in terms of the infima and suprema of some integral averages involving the coefficients of the equation.
So, we will need  to study the behavior as \(\eps\to 0\) of such infima and suprema. In order to do that, we use  a classical tool from the Calculus of Variations: the \(\Gamma-\)convergence. Recall the following definition (see, e.g., \cite{Bra}).

\begin{defi} \label{def:Gammaconv}
Let $X$ be a topological space, $\{\Phi_n\}$ be a sequence of functions $\Phi_n:X\to[-\infty,+\infty]$, and $\Phi:X\to[-\infty,+\infty]$. We say that $\{\Phi_n\}$ $\Gamma$-converges to $\Phi$, and write $\Phi_n\stackrel{\Gamma}{\to}\Phi$, if for all $x\in X$ the following properties hold true:
\begin{enumerate}[label={(\roman*)}]
\item {\it liminf inequality:} for every $\{x_n\}\subseteq X$ such that $x_n\to x$ one has
$$ \Phi(x)\leq \liminf_{n\to\infty} \Phi_n(x_n), $$
\item {\it limsup inequality:} there exists $\{x_n\}\subseteq X$ such that $x_n\to x$ and
$$ \Phi(x)\geq \limsup_{n\to\infty} \Phi_n(x_n). $$
\end{enumerate}
\end{defi}

The following result, concerning the stability of infima under $\Gamma$-convergence, stems from \cite[Proposition 1.18(i)]{Bra}.
\begin{lemma}
\label{inf-stab}
Let $X$ be a compact topological space and $\{\Phi_n\}$ be a sequence of functions $\Phi_n:X\to[-\infty,+\infty]$ that $\Gamma$-converges to $\Phi:X\to[-\infty,+\infty]$. Then
$$ \inf_X \Phi = \lim_{n\to\infty} \inf_X \Phi_n. $$
\end{lemma}
\begin{proof}
For every $n\in\N$, choose $x_n\in X$ such that
$$ \Phi_n(x_n) < \inf_X \Phi_n + \frac{1}{n}. $$
Since $X$ is compact, then $x_n\to x\in X$, up to sub-sequences. Thus, owing to $\Phi_n\stackrel{\Gamma}{\to}\Phi$,
\begin{equation}
\label{stab1}
\inf_X \Phi \leq \Phi(x)\leq \liminf_{n\to\infty} \Phi_n(x_n) \leq \liminf_{n\to\infty} \inf_X \Phi_n.
\end{equation}
Due to the lower semi-continuity of $\Phi$ (see \cite[Proposition 1.28]{Bra}) and the compactness of $X$, there exists $y\in X$ such that $\Phi(y)=\inf_X \Phi$. Hence, according to the $\Gamma$-convergence of $\{\Phi_n\}$ to $\Phi$, there exists $\{y_n\}$ such that $y_n\to y$ and
\begin{equation}
\label{stab2}
\inf_X \Phi = \Phi(y) \geq \limsup_{n\to\infty} \Phi_n(y_n) \geq \limsup_{n\to\infty} \inf_X \Phi_n.
\end{equation}
Putting \eqref{stab1}--\eqref{stab2} together concludes the proof.
\end{proof}

\bigskip
In light of the previous result, we now prove the following technical lemma, which will allow us to get the \(\Gamma-\)convergence of the integral averages of the \(\varepsilon-\)regularizations.

\begin{lemma}
\label{lem:conv}
Let $\phi\in\hat{C}(0,1)\cap L^1(0,1)$ and let \(A\supseteq \D(\phi)\) be a finite set in \((0,1)\). Consider the $\eps$-regularization of \(\phi\) related to the set \(A\), which we simply denote by  \(\phi_\eps\), for all $\eps\in(0,\overline{\eps})$, being $\overline{\eps}$ as in Definition \ref{epsreg}. 
Assume that \(\phi\) is bounded in \(\bar I=[\bar \eps, 1-\bar\eps]\). 

For every \(x\in (0,1]\) set
\beq \label{def:Phi}
\Phi_0(x):= \fint_0^x\phi(\tau)\dtau,  \quad \Phi_\eps(x):=\fint_0^x\phi_\eps(\tau)\dtau, \quad \text{ for all } \eps\in(0,\overline{\eps}).
\eeq

Then, for every pair of sequences \(\{x_n\}\subset (0,1] \), \(\{\eps_n\}\subset[0,\bar \eps) \), with \(x_n\to \bar x\) and \(\eps_n\to 0\), we have:
\beq \label{eq:conv}
\Phi_{\eps_n}(x_n) \to \Phi_0(\bar x) \qquad \text{ if } \bar x >0
\eeq
and
\beq \label{eq:conv2}
\liminf_{x\to 0^+}\Phi_0(x)\leq \liminf_{n\to\infty}\Phi_{\eps_n}(x_n)\leq\limsup_{n\to\infty}\Phi_{\eps_n}(x_n)\leq\limsup_{x\to 0^+}\Phi_0(x).
\eeq


%In addition, there exists $\{\eps_n\}\subseteq(0,\bar\eps)$ such that, for all $\{x_n\}\subseteq(0,1]$ fulfilling $x_n\to 1$, one has 
%\beq
%\label{eq:conv3}
%\Phi_{\eps_n}(x_n)\to\Phi_0(1).
%\eeq
%\smallskip

\end{lemma}
\begin{proof}
Let us consider the function $\Psi:(0,1]\times[0,\overline{\eps})\to\R$ defined as $\Psi(x,\eps):=\Phi_\eps(x)$. If $\Psi$ is continuous at $(\bar x,0)$ for every $\bar x\in(0,1]$, then \eqref{eq:conv} holds: indeed, given any sequence $\{\eps_n\}\subset[0,\overline{\eps})$ such that $\eps\to 0$, for every $\bar x\in(0,1]$ and every sequence $x_n\to \bar x$ one has
$$ \lim_{n\to\infty} \Phi_{\eps_n}(x_n) = \lim_{n\to\infty} \Psi(x_n,\eps_n) = \Psi(\bar x,0) = \Phi_0(\bar x). $$

To this end, fix any $\bar x\in(0,1]$ and take any $\{(x_n,\eps_n)\}\subseteq (0,1]\times[0,\overline{\eps})$ such that $(x_n,\eps_n)\to(\bar x,0)$ as $n\to\infty$. %If $\bar x=0$, then $\phi_{\eps_n}\equiv \phi$ in $[0,x_n]$ for all $n\in\N$ sufficiently large, and the result is immediate. Thus we suppose $\bar x\neq 0$ and distinguish two cases: $\bar x\neq 1$ and $\bar x=1$. Let us assume $\bar x\neq 1$. 
For each $n\in\N$ we put  $\{\gamma_1,\ldots,\gamma_{m_n}\}=A\cap[0,x_n]$. 


Therefore,  we have
\begin{equation*}
\Psi(x_n,\eps_n) = \frac{1}{x_n} \left[ \int_{[0,x_n]\setminus\cup_{j=1}^{m_n} B_{\eps_n}(\gamma_j)} \phi(\tau)\dtau + \sum_{j=1}^{m_n} \int_{[0,x_n]\cap B_{\eps_n}(\gamma_j)} \phi_{\eps_n}(\tau)\dtau \right],
\end{equation*}
since $B_{\eps_n}(\gamma_i)\cap B_{\eps_n}(\gamma_j)=\emptyset$ for all $i\neq j$, due to $\eps_n<\overline{\eps}$. Notice that the previous equation holds even if \(\eps_n=0\), since in this case \(B_{\eps_n}(\gamma_j)\) is empty, for every \(j=1,\ldots,m_n\).

Put \(\bar K:= \dis\sup_{\xi \in \bar I}|\phi(\xi)|\), for any $j\in\{1,\ldots,m_n\}$ we have
\begin{equation*}
%\label{fundamental}
\begin{aligned}
\int_{[0,x_n]\cap B_{\eps_n}(\gamma_j)} |\phi_{\eps_n}(\tau)| \dtau &\leq \int_{\gamma_j-\eps_n}^{\gamma_j+\eps_n} \left|\phi_{\eps_n}(\tau)\right| \dtau \\
&= \int_{0}^{2\eps_n} \left| \left[\phi(\gamma_j-\eps_n)+\frac{\phi(\gamma_j+\eps_n)-\phi(\gamma_j-\eps_n)}{2\eps_n}t\right] \right| \dt \\
&\leq \eps_n \left[2|\phi(\gamma_j-\eps_n)| + |\phi(\gamma_j+\eps_n)-\phi(\gamma_j-\eps_n)|\right] \leq 4\bar K  \eps_n.
\end{aligned}
\end{equation*}
Accordingly,
\begin{equation*}
\left| \sum_{j=1}^{m_n} \int_{[0,x_n]\cap B_{\eps_n}(\gamma_j)} \phi_{\eps_n}(\tau)\dtau \right| \leq \sum_{j=1}^{m_n} \int_{[0,x_n]\cap B_{\eps_n}(\gamma_j)} \left|\phi_{\eps_n}(\tau)\right| \dtau \leq 4\sharp(A)\bar K \eps_n   \to 0 \quad \text{as } n\to\infty,
\end{equation*}
 where $\sharp(A)$ denotes the cardinality of $A$. Moreover, 
$$\int_{[0,x_n]\setminus\cup_{j=1}^{m_n} B_{\eps_n}(\gamma_j)} \phi(\tau)\dtau \to \int_{[0,\bar x]} \phi(\tau)\dtau \quad \mbox{as} \;\; n\to\infty. $$
We conclude that $\Psi(x_n,\eps_n) \to \Psi(\bar x,0)$ as $n\to\infty$.

Finally, \eqref{eq:conv2} is an immediate consequence of the fact that $\phi_{\eps_n}\equiv \phi$ in $[0,x_n]$ for all $n\in\N$ sufficiently large.


\end{proof}

\bigskip
As a consequence of the previous lemma, we have the following convergence result.

\begin{prop} Under the same assumptions of Lemma \ref{lem:conv}, assume also that \[\dis\liminf_{x\to 0^+} \fint_0^x \phi(\tau) \dtau<+\infty.\]

Then, 
we have
\beq \label{eq:phiconv}
\inf_{x\in (0,1)} \fint_0^x \phi(\tau) \dtau = \lim_{n\to \infty} \inf_{x\in (0,1)} \fint_0^x\phi_{\eps_n} (\tau)\dtau.
\eeq

\noindent
Similarly, if 
\[\dis\limsup_{x\to 0^+} \fint_0^x \phi(\tau) \dtau<+\infty\]
we have
\beq \label{eq:phiconv2}
\sup_{x\in (0,1)} \fint_0^x \phi(\tau) \dtau = \lim_{n\to \infty} \sup_{x\in (0,1)} \fint_0^x\phi_{\eps_n} (\tau)\dtau.
\eeq

\label{pr:Gammac}

\end{prop}

\begin{proof}
As in Lemma \ref{lem:conv}, let us define \(\Phi_0(x)\) and \(\Phi_\eps(x)\) for \(x\in (0,1]\) by \eqref{def:Phi}. Moreover,  put
\beq \Phi_0(0)=\Phi_\eps(0)=\liminf_{x\to 0^+} \Phi_0(x).\label{eq:phi0} \eeq
Fix any sequence \(\{\eps_n\}\subset [0,\bar\eps)\) convergent to 0.

\smallskip
Since \(\phi_\eps\equiv \phi\) in a right neighborhood of 0, we have also \(\Phi_\eps\equiv \Phi_0\) in the same neighborhood. So, 
by \eqref{eq:conv2}, for any sequence \(x_n\to 0\) we have 
\[ \Phi_0(0) \le \liminf_{n \to +\infty} \Phi_0(x_n) = \liminf_{n \to +\infty} \Phi_{\eps_n}(x_n).\]
Moreover, if \(\{\bar x_n\}\) is a sequence such that \(\Phi_0(\bar x_n)\to \Phi_0(0)\), then we get 
also \(\Phi_0(0)\ge \dis\limsup_{n\to +\infty} \Phi_{\eps_n}(\bar x_n)\). 

Therefore, taking also \eqref{eq:conv} into account, we conclude that \(\Phi_{\eps_n} \stackrel{\Gamma}\to \Phi_0 \) in \([0,1]\), so 
from Lemma \ref{inf-stab} we get
\[ \inf_{x\in (0,1)} \fint_0^x \phi(\tau) \dtau =\inf_{x\in [0,1]} \Phi_0(x) = \lim_{n\to \infty} \inf_{x\in [0,1]} \Phi_{\eps_n}(x) = \lim_{n\to \infty} \inf_{x\in (0,1)} \fint_0^x\phi_{\eps_n} (\tau)\dtau,\]
that is, 
\eqref{eq:phiconv}.

The second part is analogous. Indeed, setting
\[ \Phi_0(0)=\Phi_\eps(0)=\limsup_{x\to 0^+} \Phi_0(x)\]
instead of \eqref{eq:phi0}, we have that   \(-\Phi_{\eps_n} \stackrel{\Gamma}\to -\Phi_0 \), from which we deduce the validity of \eqref{eq:phiconv2}.

\end{proof}








