\bigskip

Now we are able to prove our main results concerning the existence of t.w.s.'s.


\begin{thm}
\label{t:mainthm1}  
According to the notations \eqref{notation2}, we have:
\begin{enumerate}[label={{\rm (\arabic*)}}]
\item \label{thm1case1} if $\ell_{p}=+\infty$, then there exist no t.w.s.'s for any $c\in\R$.
\item \label{thm1case3} if $\ell_{p}<+\infty$ and
\begin{equation}
\label{nonexcond}
cg(0)-f(0) < p'[\ell_p(p-1)]^{\frac{1}{p}},
\end{equation}
then there exist no t.w.s.'s having speed $c$;

\item \label{thm1case2} if $L_{p}<+\infty$ and
\begin{equation}
\label{excond}
\inf_{\xi\in(0,1)} \fint_0^\xi (cg(\tau)-f(\tau)) \dtau > p'(p-1)^{\frac{1}{p}}\left(\sup_{\xi\in(0,1)} \fint_0^\xi \frac{\kappa(\tau)}{\tau^{\frac{1}{p-1}}} \dtau\right)^{\frac{1}{p'}},
\end{equation}
where \(\kappa\) is defined by \eqref{ip:kappa}, then there exists a t.w.s. having speed $c$ and it is unique, up to shifts.

\end{enumerate}


\end{thm}

\begin{proof}
The conclusion in case \ref{thm1case1} follows directly from Proposition \ref{prop:equiv} and Lemma \ref{lem:nuovo}. As for 
 the case \ref{thm1case3}, simple calculations show that assumption \eqref{nonexcond} ensures that the function \(\eta(t)\) involved in Lemma \ref{lem:nuovo} is positive for every $t\geq 0$. So, no solutions to problem \eqref{odeprob2} exist.

So, from now on consider 
the case \ref{thm1case2}.  

Let us fix \(c \in \R\) fulfilling \eqref{excond} and set
\[\psi(\tau):= \frac{\kappa(\tau)}{\tau^{\frac{1}{p-1}}}, \quad \tau\in (0,1).\]
By \eqref{ip:hatC} we have \(\psi\in \hat C(0,1)\); moreover, since $L_p<+\infty$, by \eqref{ip:kappa} we get \(\psi\in L^1(0,1)\).
\newline
Moreover, put \(A:=\D(g)\cup \D(f)\), 
let us consider the \(\eps-\)regularizations \(g_\eps^{(A)}\), \(f_\eps^{(A)}\) and \(\psi_\eps\) obtained as in Definition \ref{epsreg}. Set 
$H_\eps(\xi):=cg_\eps^{(A)}(\xi)-f_\eps^{(A)}(\xi)$, for all $\xi\in[0,1]$.
By Remark \ref{epsregprops} we get \(H_\eps(\xi)= (cg(\xi)-f(\xi))_\eps^{(A)}\), as well as
\begin{equation}
\label{locunifconv1}
H_\eps(\xi)\to cg(\xi)-f(\xi) \quad \mbox{and} \quad \psi_\eps\to \psi\quad \mbox{locally uniformly in} \;\; (0,1)\setminus\Theta \quad \text{as } \eps \to 0.
\end{equation}
Furthermore, since \(\kappa\) is bounded in every closed  \(I\subset (0,1)\), the same holds true for \(\psi\). Hence, since $L_p<+\infty$, by Proposition \ref{pr:Gammac} we have


% Notice that $H\in \hat{C}[0,1]\cap L^\infty[0,1]$ by \eqref{ip:hatC}, while \(\kappa\in \hat C(0,1)\), by \eqref{ip:d} and \eqref{ip:kappa}. 
% Moreover, since $L_p<+\infty$, also the map $\psi(\tau):= \frac{\kappa(\tau)}{\tau^{\frac{1}{p-1}}}$ belongs to $\hat C(0,1)\cap L^1(0,1)$.



 %Let us consider the \(\eps-\)regularizations \(H_\eps\) and \(\psi_\eps\) obtained as in Definition \ref{epsreg}. Since \(\D(H)\cup \D(\psi)\subseteq \Theta\), by Remark \ref{epsregprops} we get 


%Since \(L_p<+\infty\), we can apply Proposition \ref{pr:Gammac}, and obtain
\begin{equation*}
%\label{infsup-conv}
\begin{aligned}
\lim_{\eps\to0} \inf_{\xi\in(0,1)} \fint_0^\xi H_\eps(\tau)\dtau &= \inf_{\xi\in(0,1)} \fint_0^\xi (cg(\tau)- f(\tau))\dtau, \\
\lim_{\eps\to0} \sup_{\xi\in(0,1)} \fint_0^\xi \psi_\eps(\tau)\dtau &= \sup_{\xi\in(0,1)} \fint_0^\xi \psi(\tau)\dtau.
\end{aligned}
\end{equation*}
%Taking into account that $\xi\mapsto\fint_0^\xi H(\tau)\dtau$ and $\xi\mapsto\fint_0^\xi\frac{\kappa(\tau)}{\tau^{\frac{1}{p-1}}}\dtau$ are continuous,
Then, by \eqref{excond}, there exists \(\eps^*>0\) such that
\beq \inf_{\xi\in(0,1)} \fint_0^\xi H_\eps(\tau)\dtau > p'(p-1)^{\frac{1}{p}}\left(\sup_{\xi\in(0,1)} \fint_0^\xi \psi_\eps(\tau)\dtau\right)^{\frac{1}{p'}} \quad \text{ for all } \eps\in(0,\eps^*). \label{eq:interm}\eeq
Let us define, for every $\eps\in(0,\eps^*)$,
\[ \tilde \psi_\eps(x):=\begin{cases} 
\min\{\psi_\eps(x), \frac{\psi_\eps(\eps)}{\eps}x\} & \text{ for } 0\le x<\eps, \\
\psi_\eps(x) & \text{ for } \eps\le x\le 1-\eps,  \\   \min\{\psi_\eps(x), \frac{\psi_\eps(1-\eps)}{\eps}(1-x)\} & \text{ for } 1-\eps<x\le 1.  \end{cases}\]
Of course, \(\tilde \psi_\eps\) is continuous in \([0,1]\) with \(\tilde\psi_\eps(0)=\tilde\psi_\eps(1)=0\).
Since \(\tilde \psi_\eps(x)\le \psi_\eps(x)\) for every \(x\in [0,1]\), by \eqref{eq:interm} we have 

\beq \inf_{\xi\in(0,1)} \fint_0^\xi H_\eps(\tau)\dtau > p'(p-1)^{\frac{1}{p}}\left(\sup_{\xi\in(0,1)} \fint_0^\xi \tilde\psi_\eps(\tau)\dtau\right)^{\frac{1}{p'}} \quad \text{ for all } \eps\in(0,\eps^*). \label{eq:final}\eeq

Put now 
\[ \tilde \kappa_\eps(\xi):= \tilde \psi_\eps(\xi) \xi^\frac{1}{p-1}.\]
Of course, \(\tilde \kappa_\eps\) is continuous in \([0,1]\) and, by \eqref{locunifconv1}, \(\tilde \kappa_\eps \to \kappa\)
locally uniformly in \((0,1)\setminus \Theta\) as \(\eps\to 0\).
Therefore, by \eqref{eq:final},
as a consequence of Proposition \ref{p:exten}, for any $\eps\in(0,\eps^*)$ there exists a solution $y_\eps\in C^1(0,1)$ to
\begin{equation}
\label{eq:regodeprob}
\left\{
\begin{alignedat}{2}
\dot y &= cg_\eps^{(A)}(\xi)-f_\eps^{(A)}(\xi)-\frac{\tilde\kappa_\eps(\xi)}{y^{\frac{1}{p-1}}} \quad &&\mbox{in} \;\; (0,1), \\
y&>0 \quad &&\mbox{in} \;\; (0,1), \\
y(0)&=y(1)=0.
\end{alignedat}
\right.
\end{equation}




Let us now prove that the solutions \(y_\eps\) are equi-continuous in any compact interval $I\subset (0,1)$. To this aim, for every \(r\in(0, \frac12) \) put \(I_r:=[r,1-r]\) and let \(r_0<\frac12\) be such that \(\Theta\subset I_{r_0}\).

Let us fix \(r<\frac12 r_0\) and 
put \(M:=\|cg-f\|_\infty\) and \(m_r:=r^{\frac{1}{p-1}}\inf_{I_{r}} \psi\).
By \eqref{supest} we have \(\|H_\eps\|_\infty\le M\), while \eqref{infest} entails \(\inf_{I_r} \psi_\eps\ge \inf_{I_{r}} \psi\).
So, \(\inf_{I_{r}} \tilde\kappa_\eps \ge m_r\).  Hence, 
we can apply Lemma \ref{l:lowboun} to deduce that 
there exists a positive \(\delta_{r}\) such that 
\begin{equation}
\label{eq:lowerbound}
y_\eps(\xi)\geq \delta_{r} \quad \mbox{for all} \;\; \xi\in I_{2r} \;\; \mbox{and} \;\; \eps\in(0,\eps^*).
\end{equation}
Moreover, notice that \(\psi\in L^\infty (I_{2r})\), and
\begin{equation*}
\tilde \kappa_\eps(\xi) < \tilde \psi_\eps(\xi)\le \psi_\eps(\xi) \le \|\psi\|_{L^\infty(I_{2r})} \quad \text{ for every } \xi \in I_{2r}.
%\label{eq:kappa}
\end{equation*}
Thus, 
\begin{equation}
\label{derest}
 %\int_{I_{2r}} |\dot y_\eps(\tau)| \dtau \leq \|%H_\eps\|_\infty+\frac{1}{\delta_r^{\frac{1}
 %{p-1}}}\int_0^1 \tilde \kappa_\eps(\tau) \dtau \leq %M+\frac{\|\psi\|_{L^\infty(I_{2r})} }%{\delta_r^{\frac{1}{p-1}}}.
 |\dot y_\eps(\xi)|\le M+ \frac{\|\psi\|_{L^\infty(I_{2r})} }{\delta_r^{\frac{1}{p-1}}} \quad \text{ for every } \xi \in I_{2r},
\end{equation}
implying that  $\{y_\eps\}$ is equi-continuous in $I_{2r}$ (see Remark \ref{r:AC}).

Moreover,
notice that 
\beq  \label{eq:equiboun} 0\le y_\eps(\xi) = \int_0^\xi \dot y_\eps(\tau) \dtau \le \int_0^\xi H_\eps(\tau)\dtau \le \|H_\eps\|_\infty \xi \le M \quad \mbox{ for any } \xi  \in (0,1),  \eeq
for every \( \eps<\bar \eps\), so $\{y_\eps\}$ is also equi-bounded in $I_{2r}$.
Therefore, up to sub-sequences, Ascoli-Arzelà's Theorem ensures $y_\eps\to \hat y_r$ uniformly in $I_{2r}$ for some $\hat y_r\in C(I_{2r})$. By using a diagonal argument we achieve the existence of $y\in C(0,1)$ such that, up to a subsequence,
\begin{equation}
\label{eq:locunifconv2}
y_\eps\to y \quad \mbox{locally uniformly in} \;\; (0,1).
\end{equation}


Finally, according to \eqref{eq:regodeprob}, \eqref{eq:lowerbound}, and
\eqref{eq:locunifconv2}, 
   for every $\xi_0,\xi\in (0,1)$ we have 
\begin{equation*}
\begin{array}{ll}y(\xi)-y(\xi_0)& =\dis \lim_{\eps\to 0}\left[y_\eps(\xi)-y_\eps(\xi_0)\right] = \dis\lim_{\eps\to 0} \int_{\xi_0}^\xi \left[H_\eps(\tau)-\frac{\tilde\kappa_\eps(\tau)}{y_\eps(\tau)^{\frac{1}{p-1}}}\right] \dtau  \\
  & = \dis \int_{\xi_0}^\xi \left[cg(\tau)-f(\tau)-\frac{\kappa(\tau)}{y(\tau)^{\frac{1}{p-1}}}\right] \dtau. \end{array}
\end{equation*}
Hence, we deduce that $y\in C^1((0,1)\setminus\Theta)$ and it is a solution of the differential equation in \eqref{odeprob2}. Moreover, \eqref{eq:lowerbound} guarantees that \(y(\xi)>0\) in \((0,1)\).

\medskip
As for the boundary conditions, note that by  \eqref{eq:equiboun} we have \(0\le y(\xi)\le M \xi\) for every \(\xi \in (0,1)\), whence \(y(0^+)=0\). Moreover, again by \eqref{eq:equiboun}, for every \(\xi \) sufficiently close to 1 we have
%\[\]
% y(0^+) =
%\lim_{\xi\to 0^+} y(\xi) = \lim_{\xi\to 0^+} %\lim_{\eps\to 0^+} y_\eps(\xi) = \lim_{\eps\to 0^+} \lim_{\xi\to 0^+} y_\eps(\xi) = 0. $$
%\[\left|\frac{\rm d}{{\rm d}\xi} (y_\eps(\xi)^{p'})\right|= p'\left|H_\eps(\xi)y_\eps(\xi)^{\frac{1}{p-1}}-\tilde\kappa_\eps(\xi)\right|\leq p'(\|H\|_\infty^{p'} + \|K\|_\infty)=:M \quad \mbox{ for any } \xi\in (0,1), \eps<\bar\eps.\]
%\le M(1-\xi) \quad \mbox{ for any } \xi\in %(0,1), \ \eps<\bar\eps.  \]
\[\begin{alignedat}{2}  y_\eps(\xi)^{p'} & = \dis \int_\xi^1 \left[-\frac{\rm d}{{\rm d}\tau} (y_\eps(\tau)^{p'})\right] \dtau 
=p' \int_\xi^1 [\tilde \kappa_\eps (\tau) - H_\eps(\tau)y_\eps(\tau)^\frac{1}{p-1}] \dtau \le p'\int_\xi^1 \tilde \kappa_\eps (\tau)\dtau \\
& \le p' \dis\int_\xi^1 \psi_\eps(\tau)\tau^{\frac{1}{p-1}}\dtau\le p'\int_\xi^1 \psi_\eps(\tau)\dtau=p'\int_\xi^1 \psi(\tau)\dtau.
\end{alignedat}\]
Thus, since \(\psi\in L^1(0,1)\),  we  deduce \(y(1^-)=0\). Therefore, $y$ solves \eqref{odeprob2}. 

\medskip
Finally, assume by contradiction the existence of two solutions \(y_1, y_2\) of problem \eqref{odeprob2} and assume, w.r., \(y_1(\xi_0)<y_2(\xi_0)\) for some \(\xi_0\in (0,1)\). Let \((a,b)\) be the maximal interval in \((0,1)\), containing \(\xi_0\), where \(y_1(\xi)<y_2(\xi)\). By the boundary conditions in \eqref{odeprob2}, we deduce that \(y_1(a^+)=y_2(a^+)\) and \(y_1(b^-)=y_2(b^-)\). But

%From the uniqueness of the solution of the differential equation in \eqref{odeprob2} passing through a given point, we deduce \(y_1(\xi)\ne y_2(\xi)\) for every \(\xi\in (0,1)\). So, we can assume w.r. \(y_1(\xi)<y_2(\xi)\) in \((0,1)\). Then, 
\[ \begin{alignedat}{2}
    y_1(b^-)-y_1(a^+)&=\int_a^b \left[ cg(\xi)-f(\xi) - \frac{\kappa(\xi)}{y_1(\xi)^{\frac{1}{p-1}}}\right] \dxi 
    <\int_a^b \left[cg(\xi)-f(\xi) - \frac{\kappa(\xi)}{y_2(\xi)^{\frac{1}{p-1}}}\right] \dxi \\ &= y_2(b^-)-y_2(a^+), \end{alignedat}\]
a contradiction.

\end{proof}

The next result concerns the structure of the set of the admissible wave speeds.
% Let us define
% \beq \label{def:Gamma-c}
% \C:=\{c\in\R: \, \mbox{there exists a t.w.s. of speed } \, c\}.
% \eeq



\begin{thm}
\label{t:mainthm2}
Suppose that $g(0)>0$ and \(L_p<+\infty\).
Then, if \eqref{excond} is satisfied for some \(c\in \R\), the set $\C$ (defined in \eqref{def:Gamma-c}) is non-empty and bounded from below. Moreover, \(\C\) admits minimum $c^*$, which fulfills
\begin{equation}
\label{eq:c*cond1}
\inf_{\xi\in(0,1)} \fint_0^\xi (c^*g(\tau)-f(\tau)) \dtau \leq p'(p-1)^{\frac{1}{p}}\left(\sup_{\xi\in(0,1)} \fint_0^\xi \frac{\kappa(\tau)}{\tau^{\frac{1}{p-1}}}\dtau\right)^{\frac{1}{p'}}
\end{equation}
and
\beq \label{eq:c*cond2}
c^* g(0)-f(0) \geq p'(p-1)^{\frac{1}{p}}\ell_p^{\frac{1}{p}}.
\eeq
%where \(H_c^*(\xi):=c^*g(\xi)-f(\xi)\).

Finally, if $\int_0^\xi g(\tau)\dtau\ge 0$  in $[0,1]$, then $\C=[c^*,+\infty)$.
\end{thm}

\begin{proof}
Since $g(0)>0$, there exists $\hat{c}\in\R$ such that \eqref{nonexcond} is satisfied for all $c<\hat{c}$, so $\C$ is bounded from below by Theorem \ref{t:mainthm1}. Set
\(c^*:=\inf \C\).

First of all, note that \(c^*\) satisfies \eqref{eq:c*cond2}. Indeed, if not, then we would have \eqref{nonexcond} for every \(c\) in a right neighborhood of \(c^*\), implying by Theorem \ref{t:mainthm1} that no t.w.s. having speed \(c\) exist, in contrast with the definition of \(c^*\).

As regards the validity of \eqref{eq:c*cond1}, assume, by contradiction, that for some 
$\eps>0$ we have

\[\inf_{\xi\in(0,1)} \fint_0^\xi (c^*g(\tau)-f(\tau)) \dtau > p'(p-1)^{\frac{1}{p}}\left(\sup_{\xi\in(0,1)} \fint_0^\xi \frac{\kappa(\tau)}{\tau^{\frac{1}{p-1}}} \dtau\right)^{\frac{1}{p'}}+\eps.\]
Then, 
\[\fint_0^\xi (c^*g(\tau)-f(\tau)) \dtau > p'(p-1)^{\frac{1}{p}}\left(\sup_{\xi\in(0,1)} \fint_0^\xi \frac{\kappa(\tau)}{\tau^{\frac{1}{p-1}}} \dtau\right)^{\frac{1}{p'}}+\eps, \quad \text{ for every } \xi\in (0,1).\]
Put \(L:=\dis\sup_{\xi\in (0,1)}\fint_0^\xi g(\tau) \dtau>0\) and set \(\delta:=\eps/L\). Then, for every \(\xi\in (0,1)\) we have 
\[
\begin{aligned}\fint_0^\xi ((c^*-\delta)g(\tau)-f(\tau)) \dtau &= \fint_0^\xi (c^*g(\tau)-f(\tau)) \dtau - \delta\fint_0^\xi g(\tau)\dtau \\ 
&\geq  \fint_0^\xi (c^*g(\tau)-f(\tau)) \dtau - \eps >
p'(p-1)^{\frac{1}{p}}\left(\sup_{\xi\in(0,1)} \fint_0^\xi \frac{\kappa(\tau)}{\tau^{\frac{1}{p-1}}} \dtau\right)^{\frac{1}{p'}}. 
\end{aligned}\]
Hence condition \eqref{excond} is fulfilled for \(c=c^*-\delta\), in contrast with the definition of \(c^*\). So, \eqref{eq:c*cond1} holds true.

\smallskip Let us now prove that \(c^*\in \C\). To this aim, 
let $\{c_n\}\subseteq\C$ be a decreasing sequence converging to $ c^*$ and consider a sequence $\{y_n\}$ of solutions to \eqref{odeprob2} with $c=c_n$, which are given by Theorem \ref{t:mainthm1} and Proposition \ref{prop:equiv}.
Set \(\hat c:=\max |c_n|\). Fix any \(r\in(0,\frac14)\) such that \(\Theta \subset (2r,1-2r)\), and put \(M:=\|f\|_\infty +\hat c\|g\|_\infty\). By virtue of Lemma \ref{l:lowboun} we deduce that there exists a positive
 \(\delta_{r}\) such that 
\beq \label{eq:lowerbound2}
y_n(\xi) \ge \delta_{r} \quad \text{ for every } \xi \in I_{2r}:=[2r,1-2r] \text{ and } n\in \N.
\eeq  
Therefore, we have
\begin{equation*}
|\dot y_n(\xi)|\le \hat c\|g\|_\infty+ \|f\|_\infty+ \frac{1}{\delta_r^{\frac{1}{p-1}}}\int_0^1 \kappa(\tau)\dtau \quad \text{ for every } \xi\in I_{2r}.
%\label{derest2}
\end{equation*}

%for any $\xi_1,\xi_2\in I_r$ we have
%\begin{equation}
%\label{derest2}
%|y_n(\xi_1)-y_n(\xi_2)| \leq \int_{I_r} |\dot y_n(\tau)|\dtau \leq \hat c\|g\|_\infty+ \|f\|_\infty+ \frac{1}{\delta_r^{\frac{1}{p-1}}}\int_0^1 \kappa(\tau)\dtau.
%\end{equation}
Thus, reasoning as for \eqref{derest} and \eqref{eq:equiboun}, we get the compactness of $\{y_n\}$ in $C(I_{2r})$ via Ascoli-Arzelà's theorem. Then $y_n\to \hat y_r$ uniformly in $I_{2r}$ for some $\hat y_r\in C(I_{2r})$. Finally, a diagonal argument provides a function $y^*\in C(0,1)$ such that, up to a subsequence, $y_n\to y^*$ locally uniformly in $(0,1)$, with   \(y^*(\xi)>0\) in \((0,1)\) from \eqref{eq:lowerbound2}. 
So, for each fixed \(\xi_0,\xi\in (0,1)\), the sequence \(\{y_n\}\) uniformly converges to \(y^*\) in \([\xi_0,\xi]\), implying 
\[
\begin{aligned}
y^*(\xi)-y^*(\xi_0) &= \lim_{n\to\infty} \left[y_n(\xi)-y_n(\xi_0)\right] = \lim_{n\to\infty} \int_{\xi_0}^{\xi} \left[c_n g(\tau)- f(\tau) - \frac{\kappa(\tau)}{y_n(\tau)^{\frac{1}{p-1}}}\right] \dtau \\
&= \int_{\xi_0}^\xi \left[c^*g(\tau)-f(\tau)-\frac{\kappa(\tau)}{y^*(\tau)^{\frac{1}{p-1}}}\right] \dtau.
\end{aligned}
\]
Therefore, \(y^*\in C^1((0,1)\setminus \Theta)\) and is a solution of the differential equation in \eqref{odeprob2}. Moreover,
arguing as in Theorem \ref{t:mainthm1}, we can prove that \(y^*(0^+)=y^*(1^-)=0\), so that $y^*$  solves \eqref{odeprob2} with $c=c^*$, implying that \(c^*\in \C\).

\smallskip
Finally, let us assume $\int_0^\xi g(\tau)\dtau\geq 0$ for all $\xi\in[0,1]$ and prove that \(\C=[c^*,+\infty)\). To this aim, fix a speed $\bar c>c^*$. 


Observe that for every \(\xi \in (0,1)\) we have
\[  y_{c^*}(\xi)=\int_0^\xi \left[c^*g(\tau)-f(\tau)-\frac{\kappa(\tau)}{y_{c^*}(\tau)^{\frac{1}{p-1}}}\right]\dtau \leq \int_0^\xi \left[\bar c g(\tau)-f(\tau)-\frac{\kappa(\tau)}{y_{c^*}(\tau)^{\frac{1}{p-1}}}\right]\dtau=:\gamma(\xi).\]
So, 
\begin{equation*}
%\label{eq:ycsotto}
\dot\gamma(\xi) = \bar c g(\xi)-f(\xi)-\frac{\kappa(\xi)}{y_{c^*}(\xi)^{\frac{1}{p-1}}} \le  \bar c g(\xi)-f(\xi)-\frac{\kappa(\xi)}{\gamma(\xi)^{\frac{1}{p-1}}} \quad \text{ for every } \xi\in (0,1)\setminus \Theta.
\end{equation*}

%Note that \(\gamma\) is not a solution of the equation in \eqref{odeprob2} for \(c=c^*\), in any interval \(J\subset (0,1)\). In fact, otherwise, by \eqref{eq:ycsotto} we would have \(y_c^*(\xi)=\gamma(\xi)\) in such an interval, implying that \(y_{c^*}\) is a solution of differential equation also for \(c=\bar c\), a contradiction since 


Take an increasing sequence \(\{\xi_n\}\) converging to \(1\), with \(\xi_1>\max \Theta\), and  consider, for each \(n \in \N\), the (unique) solution \(y_n\) of the equation in \eqref{odeprob2} with \(c=\bar c\), passing through \((\xi_n , \gamma(\xi_n))\), defined in its maximal existence interval \((\alpha_n, \beta_n)\).

We have \(y_n(\xi)\le \gamma(\xi)\) in \((\alpha_n, \xi_n)\)
  and \(y_n(\xi)\ge \gamma(\xi)\) in \((\xi_n,\beta_n)\).
 Indeed, if  \(y_n(\xi^*)> \gamma(\xi^*)\) for some \(n\in \N\) and \(\xi^*\in (\alpha_n,\xi_n)\) then, put \[\bar \xi:= \sup\{\xi>\xi^*: y_n(\tau)>\gamma(\tau) \text{ for every } \tau\in [\xi^*,\xi]\},\] we have 
 \(y_n(\bar \xi)=\gamma(\bar \xi)\) and
 \begin{equation*}
\begin{alignedat}{2}
 y_n(\bar \xi) - y_n(\xi^*)&=\int_{\xi^*}^{\bar \xi} \dot y_n(\tau)\dtau = \int_{\xi^*}^{\bar \xi} \left(\bar c g(\tau)-f(\tau) - \frac{\kappa(\tau)}{y_n(\tau)^{\frac{1}{p-1}}}\right) \dtau \\
 &> \int_{\xi^*}^{\bar \xi} \left(\bar c g(\tau)-f(\tau) - \frac{\kappa(\tau)}{\gamma(\tau)^{\frac{1}{p-1}}}\right) \dtau \ge \int_{\xi^*}^{\bar \xi} \dot \gamma(\tau)\dtau=\gamma(\bar \xi)-\gamma(\xi^*),    
\end{alignedat}
\end{equation*}
so \(y_n(\xi^*)<\gamma(\xi^*)\), a contradiction. The proof of the inequality in \((\xi_n,\beta_n)\) is analogous.

Therefore, 
\(\alpha_n=0\) and \(y_n(0^+)=0\) for each \(n\): indeed, if \(\alpha_n>0\) for some \(n\) then $y(\alpha_n^+)=0$ and, by the equation in \eqref{odeprob2}, we derive \(\dot y_n(\alpha_n^+)=-\infty\),  a contradiction.
Moreover,  \(\beta_n=1\) and \(y_n(1^-)\ge \gamma(1)\), for every \(n\in \N\). Indeed, if \(\beta_n<1\) for some \(n\) then by the equation in \eqref{odeprob2} we derive \(\dot y_n(\beta_n^-)\leq cg(\beta_n)-f(\beta_n)<+\infty\), with \(y(\beta_n^+)=+\infty\),  a contradiction.


From  Lemma \ref{l:lowboun} we deduce that for every 
\(r\) sufficiently small  there exists \(\delta_r>0 \) such that \(y_n(\xi)\ge \delta_r\) for every \(\xi\in I_{2r}\) and every \(n\in \N\) (see \eqref{eq:lowerpos}). Hence, reasoning as above, the sequence \(\{y_n\}\) is equi-continuous and equi-bounded in each compact interval in \((0,1)\). So, for each \(I\subset (0,1)\) we find a subsequence of \(\{y_n\}\) uniformly convergent in \(I\) to a solution \(y_{\bar c}\) of the equation in \eqref{odeprob2}, and a diagonal argument allows us to extend the solution \(y_{\bar c}\) to the whole interval \((0,1)\). Of course, \(y_{\bar c}(0^+)=0\) and \(y_{\bar c}(\xi)>0\) in \((0,1)\). 

If \(y_{\bar c}(1^-)=0\), then the proof is concluded. Otherwise, if \(y_{\bar c}(1^-)>0\), let us consider a decreasing sequence \(\{\zeta_n\}\) converging to 0, with \(\zeta_1<y_{\overline{c}}(1)\), and the (unique) solution \(\upsilon_n\) of the equation in \eqref{odeprob2} satisfying \(\upsilon_n(1)=\zeta_n\). Similarly to what we observed above, each solution \(\upsilon_n\) is defined in \((0,1]\). By the uniqueness of the solution of the equation \eqref{odeprob2} passing  through a given point in \((0,1)\times (0,+\infty)\), we deduce that \(0<\upsilon_{n+1}(\xi)< \upsilon_n(\xi)<y_{\bar c}(\xi)\) for every \(\xi\in (0,1)\). 
Moreover, by Lemma \ref{l:lowboun} we infer that 
the sequence is also equi-continuous in any compact \(I\subset (0,1)\). So, the sequence is locally uniformly convergent to a function \(\upsilon_{\bar c}\), which is positive in \((0,1)\) by Lemma \ref{l:lowboun}, and is a solution of problem \eqref{odeprob2}.
\end{proof}

\begin{rmk}
\label{finalrmk}
It is worth pointing out that \eqref{eq:c*cond1}--\eqref{eq:c*cond2} imply the estimates \eqref{threshold}, since
$$ \inf_{\xi\in(0,1)} \fint_0^\xi (c^*g(\tau)-f(\tau)) \dtau \geq c^*\inf_{\xi\in(0,1)} \fint_0^\xi g(\tau) \dtau - \sup_{\xi\in(0,1)} \fint_0^\xi f(\tau) \dtau. $$

%an argument analogous to the one at the beginning of \cite[Section 3.1]{DJKZ} leads to

%$$c^*>\frac{\int_0^1 f(\tau)\dtau}{\int_0^1 %g(\tau)\dtau},$$
%which reduces to $c^*>\int_0^1 f(\tau)\dtau$ when %$g\equiv 1$. 
This inequality, joint to what we observed in Remark \ref{r:AC}, shows that our estimates on $c^*$ are finer than the ones in \cite[Theorem 2.1]{DJKZ}. \\
We also highlight that a dual version of Theorem \ref{t:mainthm2} holds when $g(0)<0$: it suffices to change the sign to both the terms \(c\) and \(g\).
\end{rmk}

