\section{Regularized approximating problems}



The technique we adopt to prove the main result is
based on the regularization of the discontinuous coefficients of the equation in \eqref{odeprob}, in order to be able to use the known results concerning equations with continuous coefficients.
To this aim, let us introduce the concept of 
$\eps$-regularization of a function belonging to $\hat{C}(0,1)\cap L^1(0,1)$.

\begin{defi}
\label{epsreg}
Let $\phi\in\hat{C}(0,1)\cap L^1(0,1)$. Let  $\D(\phi)=\{\gamma_1,\ldots,\gamma_n\}$, being $\gamma_i<\gamma_{i+1}$ for all $i=1,\ldots,n-1$, and put $\gamma_0:=0$ and $\gamma_{n+1}:=1$. Finally, set $\overline{\eps}:=\frac{1}{2}\min\{\gamma_{i+1}-\gamma_i: \, i=0,\ldots,n\}$. 

For any $\eps\in(0,\overline{\eps})$, we call $\eps$-regularization of $\phi$ the function $\phi_\eps:(0,1]\to\R$ defined as
\begin{equation*}
\phi_\eps(x)=\left\{
\begin{alignedat}{2}
&\phi(\gamma_i-\eps)+\frac{\phi(\gamma_i+\eps)-\phi(\gamma_i-\eps)}{2\eps}(x-(\gamma_i-\eps)) \quad &&\mbox{if} \;\; x\in[\gamma_i-\eps,\gamma_i+\eps], \;\; i\in\{1,\ldots,n\}, \\
&\frac{\phi(1-\eps)}{\eps}(1-x) \quad &&\mbox{if} \;\; x\in[1-\eps,1], \\
&\phi(x) \quad &&\mbox{elsewhere}. \\
\end{alignedat}
\right.
\end{equation*}
\end{defi}

\medskip
\begin{rmk}
\label{epsregprops}
By definition, $\phi_\eps\in C(0,1]$ for all $\eps\in(0,\overline{\eps})$ and $\phi_\eps\to\phi$ locally uniformly in $(0,1)\setminus\D(\phi)$ as $\eps\to 0$. Moreover, it is readily seen that $(-\phi)_\eps=-\phi_\eps$ for all $\eps\in(0,\overline{\eps})$ and
\begin{equation}
\label{supest}
\|\phi_\eps\|_\infty\leq \|\phi\|_\infty \quad \mbox{for all} \;\; \eps\in(0,\overline{\eps}).
\end{equation}
Furthermore, if $I\subseteq[0,1]$ is an interval such that $\partial I \cap \D(\phi) = \emptyset$, then there exists $\hat{\eps}=\hat{\eps}(I)$ such that
\begin{equation}
\label{infest}
\inf_I \phi_\eps \geq \inf_I \phi \quad \mbox{for all} \;\; \eps\in(0,\hat{\eps}).
\end{equation}
\end{rmk}

\medskip
Thanks to the \(\eps\)-regularization of the functions in \(\hat{C}(0,1)\cap L^1(0,1)\), we can reduce to problem \eqref{odeprob2} with \(d,f,g,h\) continuous in \([0,1]\) (so that \(\Theta=\emptyset\)). In such a setting, problem \eqref{odeprob2} has been investigated in \cite{M}, where an existence result has been proved involving the integral averages of the coefficients of the equation. 
So, we will need  to study the behavior as \(\eps\to 0\) of the integral averages. The following result is just about this topic.

\begin{lemma}
\label{lem:conv}
Let $\phi\in\hat{C}(0,1)\cap L^1(0,1)$ and consider, for all $\eps\in(0,\overline{\eps})$, its $\eps$-regularization \(\phi_\eps\), being $\overline{\eps}$ as in Definition \ref{epsreg}. Set 
\beq \label{def:Phi}
\Phi_0(x):=\fint_0^x\phi(\tau)\dtau  \ , \quad  \Phi_\eps(x):=\fint_0^x\phi_\eps(\tau)\dtau \ , \quad \text{ for all } \eps\in(0,\overline{\eps}).
\eeq
Then, for every \(\bar x\in (0,1)\) and every pair of sequences \(\{x_n\}\subseteq (0,1] \), \(\{\eps_n\}\subseteq(0,\bar \eps) \), with \(x_n\to \bar x\) and \(\eps_n\to 0\), we have
\beq \label{eq:conv}
\Phi_{\eps_n}(x_n) \to \Phi_0(\bar x).
\eeq
Moreover,
\beq \label{eq:conv2}
\liminf_{x\to 0^+}\Phi_0(x)\leq \liminf_{n\to\infty}\Phi_{\eps_n}(x_n)\leq\limsup_{n\to\infty}\Phi_{\eps_n}(x_n)\leq\limsup_{x\to 0^+}\Phi_0(x)
\eeq
for all pair of sequences \(\{x_n\}\subseteq (0,1] \), \(\{\eps_n\}\subseteq(0,\bar \eps) \), with \(x_n\to 0\) and \(\eps_n\to 0\).

In addition, there exists $\{\eps_n\}\subseteq(0,\bar\eps)$ such that, for all $\{x_n\}\subseteq(0,1]$ fulfilling $x_n\to 1$, one has 
\beq
\label{eq:conv3}
\Phi_{\eps_n}(x_n)\to\Phi_0(1).
\eeq
\smallskip

\end{lemma}
\begin{proof}
Let us consider the function $\Psi:(0,1]\times(0,\overline{\eps})\to\R$ defined as $\Psi(x,\eps):=\Phi_\eps(x)$. If $\Psi$ is continuous at $(x,0)$ for every $x\in(0,1)$, then \eqref{eq:conv} holds. Indeed, given any sequence $\{\eps_n\}\subseteq(0,\overline{\eps})$ such that $\eps\to 0$, for every $\bar x\in(0,1)$ and every sequence $x_n\to \bar x$ one has
$$ \lim_{n\to\infty} \Phi_{\eps_n}(x_n) = \lim_{n\to\infty} \Psi(x_n,\eps_n) = \Psi(\bar x,0) = \Phi_0(\bar x). $$

To this end, fix any $\bar x\in(0,1)$ and take any $\{(x_n,\eps_n)\}\subseteq (0,1)\times(0,\overline{\eps})$ such that $(x_n,\eps_n)\to(\bar x,0)$ as $n\to\infty$. %If $\bar x=0$, then $\phi_{\eps_n}\equiv \phi$ in $[0,x_n]$ for all $n\in\N$ sufficiently large, and the result is immediate. Thus we suppose $\bar x\neq 0$ and distinguish two cases: $\bar x\neq 1$ and $\bar x=1$. Let us assume $\bar x\neq 1$. 
For each $n\in\N$ we put  $\{\gamma_1,\ldots,\gamma_{m_n}\}=\D(\phi)\cap[0,x_n]$. 
Therefore, 
\begin{equation*}
\Psi(x_n,\eps_n) = \frac{1}{x_n} \left[ \int_{[0,x_n]\setminus\cup_{j=1}^{m_n} B_{\eps_n}(\gamma_j)} \phi(\tau)\dtau + \sum_{j=1}^{m_n} \int_{[0,x_n]\cap B_{\eps_n}(\gamma_j)} \phi_{\eps_n}(\tau)\dtau \right],
\end{equation*}
since $B_{\eps_n}(\gamma_i)\cap B_{\eps_n}(\gamma_j)=\emptyset$ for all $i\neq j$, due to $\eps_n<\overline{\eps}$. Notice that, by \eqref{supest}, for any $j\in\{1,\ldots,m_n\}$ we have
\begin{equation}
\label{fundamental}
\begin{aligned}
\int_{[0,x_n]\cap B_{\eps_n}(\gamma_j)} |\phi_{\eps_n}(\tau)| \dtau &\leq \int_{\gamma_j-\eps_n}^{\gamma_j+\eps_n} \left|\phi_{\eps_n}(\tau)\right| \dtau \\
&= \int_{0}^{2\eps_n} \left| \left[\phi(\gamma_j-\eps_n)+\frac{\phi(\gamma_j+\eps_n)-\phi(\gamma_j-\eps_n)}{2\eps_n}t\right] \right| \dt \\
&\leq \eps_n \left[2|\phi(\gamma_j-\eps_n)| + |\phi(\gamma_j+\eps_n)-\phi(\gamma_j-\eps_n)|\right] \leq 4\|\phi\|_\infty \eps_n.
\end{aligned}
\end{equation}
Accordingly,
\begin{equation*}
\left| \sum_{j=1}^{m_n} \int_{[0,x_n]\cap B_{\eps_n}(\gamma_j)} \phi_{\eps_n}(\tau)\dtau \right| \leq \sum_{j=1}^{m_n} \int_{[0,x_n]\cap B_{\eps_n}(\gamma_j)} \left|\phi_{\eps_n}(\tau)\right| \dtau \leq 4\|\phi\|_\infty \sharp(\D(\phi)) \eps_n \to 0
\end{equation*}
as $n\to\infty$, where $\sharp(\D(\phi))$ denotes the cardinality of $\D(\phi)$. Moreover, 
$$\int_{[0,x_n]\setminus\cup_{j=1}^{m_n} B_{\eps_n}(\gamma_j)} \phi(\tau)\dtau \to \int_{[0,\bar x]} \phi(\tau)\dtau \quad \mbox{as} \;\; n\to\infty. $$
We conclude that $\Psi(x_n,\eps_n) \to \Psi(\bar x,0)$ as $n\to\infty$.

Notice that \eqref{eq:conv2} is an immediate consequence of the fact that $\phi_{\eps_n}\equiv \phi$ in $[0,x_n]$ for all $n\in\N$ sufficiently large.

Now let us prove \eqref{eq:conv3}. Notice that
\beq
\label{eq:hyp1}
\liminf_{x\to 1^-} |\phi(x)|(1-x) = 0.
\eeq
Indeed, otherwise, there exist $\delta,\sigma>0$ such that $|\phi(x)|>\frac{\sigma}{1-x}$ for all $x\in(1-\delta,1)$, contradicting $\phi\in L^1(0,1)$. Thus, owing to \eqref{eq:hyp1}, there exists $\{\eps_n\}\subseteq(0,\bar\eps)$ such that
\beq
\label{eq:epsnchoice}
\lim_{n\to\infty} \phi(1-\eps_n)\eps_n=0.
\eeq
Using the notation above, for any $n$ sufficiently large we have $1-\eps_n<x_n$, so $\D(\phi)\subseteq[0,x_n]$ and
\begin{equation*}
\Psi(x_n,\eps_n) = \frac{1}{x_n} \left[ \int_{[0,1-\eps_n]\setminus\cup_{\gamma\in\D(\phi)} B_{\eps_n}(\gamma)} \phi(\tau)\dtau + \sum_{\gamma\in\D(\phi)} \int_{[0,x_n]\cap B_{\eps_n}(\gamma)} \phi_{\eps_n}(\tau)\dtau + \int_{1-\eps_n}^{x_n} \phi_{\eps_n}(\tau)\dtau \right].
\end{equation*}
Reasoning as for \eqref{eq:conv}, we get
$$ \int_{[0,1-\eps_n]\setminus\cup_{\gamma\in\D(\phi)} B_{\eps_n}(\gamma)} \phi(\tau)\dtau \to \int_{[0,\bar x]} \phi(\tau)\dtau \quad \mbox{and} \quad \left|\sum_{\gamma\in\D(\phi)} \int_{[0,x_n]\cap B_{\eps_n}(\gamma)} \phi_{\eps_n}(\tau)\dtau\right|\to 0 $$
as $n\to\infty$. On the other hand,
\begin{equation*}
\begin{aligned}
\left|\int_{1-\eps_n}^{x_n} \phi_{\eps_n}(\tau)\dtau\right| = \frac{\phi(1-\eps_n)}{\eps_n}\int_{1-\eps_n}^{x_n} (1-\tau)\dtau = \frac{\phi(1-\eps_n)}{2\eps_n}\left[\eps_n^2-(1-x_n)^2\right] \leq \frac{\phi(1-\eps_n)}{2}\eps_n,
\end{aligned}
\end{equation*}
so that $\int_{1-\eps_n}^{x_n} \phi_{\eps_n}(\tau)\dtau\to 0$ as $n\to\infty$, due to \eqref{eq:epsnchoice}.
\end{proof}

\bigskip

The convergence proved in Lemma \ref{lem:conv} leads us to consider a classical tool from the Calculus of Variations: the \(\Gamma-\)convergence. Recall the following definition (see, e.g., \cite{B}).

\begin{defi} \label{def:Gammaconv}
Let $X$ be a topological space, $\{\Phi_n\}$ be a sequence of functions $\Phi_n:X\to[-\infty,+\infty]$, and $\Phi:X\to[-\infty,+\infty]$. We say that $\{\Phi_n\}$ $\Gamma$-converges to $\Phi$, and write $\Phi_n\stackrel{\Gamma}{\to}\Phi$, if for all $x\in X$ the following properties hold true:
\begin{enumerate}[label={(\roman*)}]
\item {\it liminf inequality:} for every $\{x_n\}\subseteq X$ such that $x_n\to x$ one has
$$ \Phi(x)\leq \liminf_{n\to\infty} \Phi_n(x_n), $$
\item {\it limsup inequality:} there exists $\{x_n\}\subseteq X$ such that $x_n\to x$ and
$$ \Phi(x)\geq \limsup_{n\to\infty} \Phi_n(x_n). $$
\end{enumerate}
\end{defi}

The following result, concerning the stability of infima under $\Gamma$-convergence, stems from \cite[Proposition 1.18(i)]{B}.
\begin{lemma}
\label{inf-stab}
Let $X$ be a compact topological space and $\{\Phi_n\}$ be a sequence of functions $\Phi_n:X\to[-\infty,+\infty]$ that $\Gamma$-converges to $\Phi:X\to[-\infty,+\infty]$. Then
$$ \inf_X \Phi = \lim_{n\to\infty} \inf_X \Phi_n. $$
\end{lemma}
\begin{proof}
For every $n\in\N$, choose $x_n\in X$ such that
$$ \Phi_n(x_n) < \inf_X \Phi_n + \frac{1}{n}. $$
Since $X$ is compact, then $x_n\to x\in X$, up to sub-sequences. Thus, owing to $\Phi_n\stackrel{\Gamma}{\to}\Phi$,
\begin{equation}
\label{stab1}
\inf_X \Phi \leq \Phi(x)\leq \liminf_{n\to\infty} \Phi_n(x_n) \leq \liminf_{n\to\infty} \inf_X \Phi_n.
\end{equation}
Due to the lower semi-continuity of $\Phi$ (see \cite[Proposition 1.28]{B}) and the compactness of $X$, there exists $y\in X$ such that $\Phi(y)=\inf_X \Phi$. Hence, according to the $\Gamma$-convergence of $\{\Phi_n\}$ to $\Phi$, there exists $\{y_n\}$ such that $y_n\to y$ and
\begin{equation}
\label{stab2}
\inf_X \Phi = \Phi(y) \geq \limsup_{n\to\infty} \Phi_n(y_n) \geq \limsup_{n\to\infty} \inf_X \Phi_n.
\end{equation}
Putting \eqref{stab1}--\eqref{stab2} together concludes the proof.
\end{proof}

\medskip
\begin{rmk}
Let $\phi\in\hat{C}(0,1)\cap L^1(0,1)$ such that there exists $\displaystyle{\phi(0^+):=\lim_{x\to 0^+}\phi(x)}$ and it is finite. Then it is readily seen that $\displaystyle{\lim_{x\to 0^+}\Phi_0(x)=\phi(0^+)}$. Hence, due to Lemma \ref{lem:conv}, there exists $\{\eps_n\}\subseteq(0,\bar\eps)$, $\eps_n\to 0$, such that $\Phi_{\eps_n}\stackrel{\Gamma}{\to}\Phi_0$ in $[0,1]$ (considering the continuous extensions of $\Phi_{\eps_n},\Phi_0$ in $[0,1]$). So, thanks to Lemma \ref{inf-stab} we infer $\displaystyle{\inf_{[0,1]} \Phi_0 = \lim_{n\to\infty} \inf_{[0,1]} \Phi_{\eps_n}}$. Thus, since $\Phi_{\eps_n},\Phi_0$ are continuous functions, then
\beq \label{eq:phiconv}
\inf_{x\in (0,1)} \fint_0^x \phi(\tau) \dtau = \lim_{n\to \infty} \inf_{x\in (0,1)} \fint_0^x\phi_{\eps_n} (\tau)\dtau.
\eeq
\end{rmk}

\medskip
\begin{rmk}
\label{gammaconv2}
Note that for every \(\phi\in \hat C(0,1)\) such that \(\psi(x):=\frac{\phi(x)}{x^{\frac{1}{p-1}}}\in L^1(0,1)\), we can also define the \(\eps\)-regularization \(\psi_\eps\)  of \(\psi\) as $\psi_\eps(x):=\frac{\phi_\eps(x)}{x^{\frac{1}{p-1}}}$ for all $x\in(0,1]$, being $\phi_\eps$ the $\eps$-regularization introduced in Definition \ref{epsreg}, and
% all we observed in Remark \ref{epsregprops} remains true. In particular, the inequalities in \eqref{supest} and \eqref{infest} are satisfied since, for any $i\in\{1,\ldots,n\}$ and $x\in [\gamma_i-\eps,\gamma_i+\eps]$,
% $$ \psi_\eps'(x) = \frac{1}{x^2}\left[x\phi_\eps'(x)-\phi_\eps(x)\right] = \frac{1}{2\eps x^2} \left[(\gamma_i-\eps)\phi(\gamma_i+\eps)-(\gamma_i+\eps)\phi(\gamma_i-\eps)\right] $$
% has constant sign in $[\gamma_i-\eps,\gamma_i+\eps]$, so that the extrema of $\psi_\eps$ are attained at points where $\psi_\eps$ agrees with $\psi$. Moreover, also 
the assertion of Lemma \ref{lem:conv} remains valid. Indeed, for every $j\in\{1,\ldots,m_n\}$   in \eqref{fundamental} one has
\begin{equation*}
\begin{aligned}
\int_{\gamma_j-\eps_n}^{\gamma_j+\eps_n} \left|\frac{\phi_{\eps_n}(\tau)}{\tau^{\frac{1}{p-1}}}\right| \dtau &\leq \left(\frac{2}{\gamma_1}\right)^{\frac{1}{p-1}} \int_{\gamma_j-\eps_n}^{\gamma_j+\eps_n} \left|\phi_{\eps_n}(\tau)\right| \dtau,
\end{aligned}
\end{equation*}
since $\eps_n<\overline{\eps}<\frac{\gamma_1}{2}$ for all $n\in\N$. Moreover, put $\Psi_\eps(x):=\fint_0^x \psi_\eps(\tau)\dtau$ and $\Psi_0(x):=\fint_0^x \psi(\tau)\dtau$ for all $x\in(0,1]$, there exists $\{\eps_n\}\subseteq(0,\bar\eps)$ such that $\eps_n\to0$ and
\begin{equation}
\label{eq:partialreg}
\inf_{(0,1)}\Psi_0 \leq \liminf_{n\to\infty}\inf_{(0,1)}\Psi_{\eps_n}\leq \limsup_{n\to\infty}\sup_{(0,1)}\Psi_{\eps_n}\leq\sup_{(0,1)}\Psi_0.
\end{equation}
Indeed, we reason as follows. Thanks to Lemma \ref{lem:conv}, we choose $\eps_n\to0^+$ such that $\Psi_{\eps_n}\stackrel{\Gamma}{\to}\Psi_0$ in $(0,1]$. Then, reasoning as in the first part of the proof of Lemma \ref{inf-stab}, we choose $\{x_n\}\subseteq(0,1)$ such that
$$ \Psi_{\eps_n}(x_n)<\inf_{(0,1)}\Psi_{\eps_n}+\frac{1}{n} \quad \mbox{for all} \;\; n\in\N. $$
Up to subsequences, $x_n\to \bar x\in[0,1]$. If $\bar x\neq0$, then the $\Gamma$-convergence of $\{\Psi_{\eps_n}\}$ yields $\displaystyle{\Psi_0(\bar x)\leq \liminf_{n\to\infty} \Psi_{\eps_n}(x_n)}$, so that (taking into account the continuity of $\Psi_0$)
$$ \inf_{(0,1)} \Psi_0 \leq \Psi_0(\bar x) \leq \liminf_{n\to\infty} \Psi_{\eps_n}(x_n) = \liminf_{n\to\infty} \inf_{(0,1)} \Psi_{\eps_n}. $$
Otherwise, if $x=0$, then $\Psi_{\eps_n}(x_n)=\Psi_0(x_n)$ for all $n$ sufficiently large, whence
$$ \inf_{(0,1)} \Psi_0 \leq \liminf_{x\to 0^+}\Psi_0(x) \leq \liminf_{n\to\infty} \Psi_0(x_n) = \liminf_{n\to\infty} \Psi_{\eps_n}(x_n) = \liminf_{n\to\infty} \inf_{(0,1)} \Psi_{\eps_n}. $$
A dual arguments leads to the inequality for supremums.
\end{rmk}






