%
%\begin{main}\label{th:cot_01}
%For any $p \in \R_{\geq 1} \sqcup \{ \infty \}$, the COT representation (see \S~\ref{sec:cot_zero} for the definition) of line fields of $\mathcal{L}^0(\mathbb{S}^2)$ is a finite complete invariant. 
%\end{main}

Denote by $\mathcal{L}^1_{i}(M)$ the subspace of levelable foliation in $\mathcal{L}^*_{i}(M) \setminus \mathcal{L}^0(M)$ whose prong connection diagram is of coheight-one (see Definition~\ref{dec:levelable_top} for the definition of coheight). 
We demonstrate the existence of ``generic'' intermediate structures as follows. 

\begin{main}\label{th:stability04}
The following statements hold for for any compact surface $M$ and any positive integer $i \geq 2$: 
\\
{\rm(1)} The subspace $\mathcal{L}^1_{i}(M)$ is an open dense subset of $\mathcal{L}^*_{i} \setminus \mathcal{L}^0(M)$. 
\\
{\rm(2)} Every levelable foliation in $\mathcal{L}^1_{i}(M)$ is structurally stable in $\mathcal{L}^*_{i} \setminus \mathcal{L}^0(M)$. 
\end{main}

Note that the previous results can imply a conversion from ``generic'' time evaluations of a levelable foliation to walks on a graph. 
%
As the ``generic'' intermediate structures of Hamiltonian vector fields on a compact surface are characterized using the multi-saddle connection diagrams, ``generic'' intermediate structures of levelable foliations can be characterized using the prong connection diagrams. 
% (see \S~\ref{sec:separatrix} for the definition). 
We call any connected component of the prong connection diagram a prong connection.
Moreover, we characterize ``generic'' structures and ``generic'' intermediate structures as follows. 

\begin{main}\label{main:char_0}
The following statements hold for any levelable foliation $\F$ on a compact surface $M$ with finitely many pronged singular points: 
\\
{\rm(1)} $\F \in \mathcal{L}^0(M)$ if and only if the prong connection diagram $D(\F)$ of $M$ consists of coheight-zero prong connections. 
\\
{\rm(2)} A prong connection in $D(\F)$ is coheight-zero if and only if it is contained in Figure~\ref{self_connected_prong} as a topological graph.
\end{main}


\begin{main}\label{main:char}
The following statements hold for any levelable foliation $\F$ on a compact surface $M$ with finitely many pronged singular points: 
\\
{\rm(1)} $\F \in \mathcal{L}^1(M)$ if and only if the prong connection diagram $D(\F)$ of $M$ consists of coheight-zero prong connections and a coheight-one prong connection. 
\\
{\rm(2)} A prong connection in $D(\F)$ is coheight-one if and only if it is contained in Figures~\ref{b_prong}, \ref{c_prong}, \ref{h_unstable_prong_connection}, and \ref{h_unstable_prong_transition} as a topological graph. 
\end{main}

In addition, we have the following complete invariants for generic (i.e. coheight-zero) levelable foliations and generic intermediate (i.e. coheight-one) foliations between them on a sphere and a disk. 

\begin{main}\label{th:cot_02}
For any $p \in \R_{\geq 1} \sqcup \{ \infty \}$, the COT representation (see \S~\ref{sec:cot_zero}--\ref{sec:cot_one}
 for the definition)
for line fields of $\mathcal{L}^0(\mathbb{S}^2) \sqcup \mathcal{L}^1(\mathbb{S}^2)$ with root components is a finite complete invariant. 
\end{main}

\subsubsection{Contents}

The present paper consists of seventeen sections.
We define a topology on the set of line fields corresponding to the $C^0$ topology of the set of flows and demonstrate the absence of structurally stable line fields in \S~2--7, and discuss ``Hamiltonian'' (i.e. levelable) foliations for line fields in \S~8--15. 
In fact, in the next section, we provide preliminaries by recalling fundamental concepts.
In \S 3, we introduce topologies on the space of one-dimensional foliations to describe ``generic'' singularities and structural stability of singular foliations on surfaces. 
In \S 4, we state the fundamental properties (e.g. persistence of non-existence/existence of singularities, invariance of closed transverse subsets). 
In \S 5, the properties of the line field (i.e. one-dimensional singular foliations) on surfaces are discussed. 
%the non-existence of structural stability of singular foliations on surfaces with respect to ``cone'' topologies is described unless an ``incompressible'' condition is met. 
In \S 6, the invariance of line fields is described. 
In \S 7, we demonstrate Theorem~\ref{non-existence_structural_stability}, the absence of structural stability for general line fields on surfaces. 
In \S 8, an analogous concept of ``incompressible'' for line fields is introduced and studied.
% such a property is discussed. 
In \S 9, ``Hamiltonian'' (i.e. levelable) foliations for line fields are introduced, and such properties are discussed. 
In \S 10, we define the topologies of the set of levelable foliations. 
In \S 11, we define the coheight of levelable foliations, and the structural stability of levelable foliations on surfaces is demonstrated. 
In particular, Theorem~\ref{main:char_0} is shown.
In \S 12, the properties with respect to the topology $\mathcal{O}^p_{w,W,\mathcal{L}(M)}$ is discussed. In particular, Theorem~\ref{th:stability03-} and Theorem~\ref{th:stability03} are demonstrated. 
In \S 13, we characterize coheight-one elements in the space of levelable foliations on surfaces and show Theorem~\ref{th:stability04} and Theorem~\ref{main:char}. 
In \S 14--15, we introduce COT representations, which are complete invariants, for generic (i.e. coheight-zero) levelable foliations and generic intermediate foliations between them on a sphere and a disk. 
In particular, we show Theorem~\ref{th:cot_02}. 
In \S 16, various examples of foliations are constructed. 
In particular, some examples illustrate the necessity and non-liftability to flows. 
In the final section, we discuss line fields, such as Voronoi partitions, and remark on line fields on non-compact surfaces.


\section{Preliminaries}\label{sec:prel}

\subsection{Notion of topology and combinatorics}

By a {\bf surface}, we mean a connected two-dimensional Riemannian manifold possibly with boundary.
%
The {\bf double} of a manifold $M$ with boundary is the resulting manifold $M\times \{0,1\}/\mathop{\sim} $, where $(x,0)\sim (x,1)$ if $x\in \partial M$, see Figure \ref{pic01}. 
%
%From now on, assume that any Riemannian metric on a non-compact manifold with boundary is lifted to a Riemannian metric on the double. 

For any subsets $A, B, C$, the union $A \cup B$ is denoted by $A \sqcup_C B$ when $A \cap B = C$.  


\subsubsection{Curves, arcs, and loops}
A {\bf curve} is a continuous mapping $C: I \to X$ to a topological space $X$, where $I$ is a non-degenerate connected subset of a circle $\mathbb{S}^1$.
A curve is {\bf simple} if it is injective.
We also denote by $C$ the image of a curve $C$.
Denote by $\partial C := C(\partial I)$ the boundary of a curve $C$ if $C$ can be extended into a continuous map whose domain is $I \cup \partial I$, where $\partial I$ is the boundary of $I \subset \mathbb{S}^1$. 
Put $\mathop{\mathrm{int}} C := C \setminus \partial C$ if $\partial C$ is defined. 
A simple curve is a {\bf simple closed curve} if its domain is $\mathbb{S}^1$ (i.e. $I = \mathbb{S}^1$).
A simple closed curve is also called a {\bf loop}. 
An {\bf arc} is a simple curve with a non-degenerate interval domain. 

A $C^{q-1}$ curve $C \colon I \to M$ on a manifold $M$ is of {\bf piecewise $\bm{C^q}$} if there are finite subset $J \subset I$ such that the restriction $C \vert_{I - J }$ is of $C^q$ and that, for any point $t_0 \in J$, there the one-sieded limits 
\[
\lim_{s \to t_0+} \dfrac{C^{(q-1)}(s) - C^{(q-1)}(t_0)}{s - t_0}
\]
and 
\[
\lim_{s \to t_0-} \dfrac{C^{(q-1)}(s) - C^{(q-1)}(t_0)}{s - t_0}
\]
exist, where $C^{(q-1)}$ is the $(q-1)$-th derivative of $C$. 

