%For any nonempty subset $A \subseteq X$ and any number $r \geq 0$, put $\bm{B(A,r)} := \bigcup_{x \in A} B_r(x)$, called the {\bf $\bm{r}$-neighborhood} of $A$ in $X$. 


\subsubsection{Hausdorff distance}

Let $(X,d)$ be a metric space. 
For any point $x$ on a metric space $X$ and any number $r \geq 0$, put 
\[
\bm{B_r(x)} = \bm{B(x,r)} := \{ y \in M \mid d(x,y) \leq r \}
\]
called the closed {\bf $\bm{r}$-ball} centered at $x$ in $X$. 
For any subset $A \subseteq X$ and a non-negative number $r \geq 0$, define the closed  {\bf $\bm{r}$-neighborhood} $B_r(A)$ as follows: 
\[
\bm{B_r(A)} := \bigcup_{a \in A} \{ x \in X \mid d(a,x) \leq r \} = \bigcup_{a \in A} B_r(a) 
\]
%Then $B(A,r) = \bigcup_{x \in A} B_r(x)$ for any nonempty subset $A \subseteq X$ and a non-negative number $r \geq 0$. 
For any nonempty subset $A \subseteq X$ and any point $x \in X$, define $d(x, A)$ as follows: 
\[
d(x, A) := \inf_{a \in A} d(x,a)
\]
Write $d(x, \emptyset) := \infty$ for any point $x \in X$. 

The {\bf Hausdorff distance} $d_H(A,B)$ between nonempty subsets $A, B \subseteq X$ is defined as follows: 
\[
\bm{d_H(A,B)} := \inf \{ r \geq 0 \mid A \subseteq B_r(B), B \subseteq B_r(A) \}
\]

Notice that the Hausdorff distance is a pseudo-metric but need not be a metric. 



\subsubsection{Distances and volumes on a Riemannian manifold}

The {\bf distance} $\bm{d_g}$ between two points on a Riemannian manifold $(M,g)$ is inferior to the length of the piecewise $C^1$-curves between them. 
%
Notice that $d_g(x,y) = \infty$ for any points $x,y \in M$ which are contained in different connected components. 
%
%
Write the Riemannian volume form $d \mathrm{vol}_g := {\star }(1)$, where $\star$ is the Hodge star. 
 Denote by $\mathrm{vol}_g(U) := \int_U d \mathrm{vol}_g$ the volume for any Borel sets $U \subseteq M$. 


\subsubsection{Diameter}

Let $(X,d)$ be a metric space. 
The {\bf diameter} $\bm{{\mathrm{diam}(A)}}$ of a subset $A \subseteq X$ is defined by the superior $\sup_{x,y \in A}d(x,y)$ of distances of pair of two points in $A$. 
Notice that $\mathrm{diam}(\emptyset) = 0$. 


