We identify tangent vectors $V \in T_x M$ as the closed unit intervals 
\[
\bm{[0_x, V]} := \{ s V \mid s \in [0,1]\} \subset T_x M
\]
 between the origin $0_x$ and $V$ in $T_x M$. 
Define $T_x M_{\pm}$ by 
\[
\bm{T_x M_{\pm}} := \{ \{ V, W \} \mid V,W \in T_x M \}
\]
and put $\bm{TM_\pm} := \bigsqcup_{y \in M} T_y M_\pm$. 
Then the set $T_x M_{\pm}$ is the set of two-point or one-point sets of tangent vectors of $T_x M$. 
Moreover, we also identify the two-point or one-point sets $\{ V, W \} \in T_x M_{\pm}$ with the unions $[0_x, V] \cup [0_x, W]$, which is called a {\bf polyline}.
Notice that these identifications of two-point sets preserve the Hausdorff distance between them. 
More precisely, we have that 
\[
d_H(\{V, W\}, \{V', W'\}) = d_H([0,V] \cup [0,W], [0,V'] \cup [0,W'])
\]
for any tangent vectors $V,W,V',W' \in T_x M \cong \R^n$, where $d_H$ is the Hausdorff distance on $T_x M$ with respect to the Riemannian distance $d_g$ and $[0,V] := \{ sV \mid s \in [0,1] \}$ for any $V \in \{V,W,V',W' \}$. 


\subsubsection{Some notations related to foliated manifolds}

Denote by $T^1 M \subseteq TM$ the set of unit tangent vectors and by $T\F \subseteq TM$ the subbundle tangent to the leaves. 
Define $\bm{TM/\mathop{\pm}}$ by the quotient space by identifying any tangent vectors $V \in \bigsqcup_{x\in M}T_xM = TM$ and its inverses $-V \in T_xM$. 

\subsubsection{``Directed fields'' induced by regular foliations}

%From now on, assume that any singular foliation on a Riemannian manifold is one-dimensional and satisfies that the leaves are piecewise $C^1$ unless otherwise stated.  
%
%Let $(M,g)$ be a Riemannian manifold. 
Let $\F$ be a $C^1$ regular foliation on $M$. 
Recall that the associated directed field 
\[
X_{\F} \colon M \to (T\F \cap T^1 M)/\pm \subset TM/\pm
\]
of $\F$ is the canonical section. 
%, where $T^1 M$ is the subset of unit tangent vectors and $TM/\pm$ is the quotient space by identifying any tangent vectors $V \in \bigsqcup_{x\in M}T_xM = TM$ and its inverses $-V \in T_xM$. 
Therefore the associated directed field $X_{\F}$ can be considered with the set $\{ \{-V_x, V_x \} \mid x \in M, V_x \in T_x\F \cap T_x^1 M \} \subset T_x M_\pm$ of pairs of the unit tangent vectors along leaves of $\F$. 
%Moreover, identifying tangent vectors $V_x \in T_x M$ as the closed unit intervals $[0_x, V_x] := \{ s V_x \mid s \in [0,1]\}$ between the origin $0_x$ and $V_x$ in $T_x M$, the two-point sets $X_{\F}(x)$ are identified with the unions $[0_x, V_x] \cup [0_x, -V_x]$, which are polylines. 

Similarly, let $\F$ be a regular foliation on $M$ whose leaves are of piecewise $C^1$. 
Define the associated directed field $X_{\F}$ as follows. 

\begin{definition}
A mapping 
\[
X_{\F} \colon M \to \{ \{X_{\F_-}(x), X_{\F_+}(x) \} \mid x \in M, X_{\F_-}(x), X_{\F_+}(x) \in  T_x^1 M \}  \subset TM_\pm
% \subset T_x M_\pm
\] 
defined by $x \mapsto \{X_{\F_-}(x), X_{\F_+}(x) \} \in T_x M_\pm$ is called the {\bf associated directed field} of the regular foliation $\F$, where the pairs $\{X_{\F_-}(x), X_{\F_+}(x) \}$ of the distinct unit tangent vectors at any point $x \in M - \partial_{\pitchfork \F}$ of leaf arcs such that there are non-degenerate arc-length $C^1$ leaf arcs $C_{x,-}, C_{x,+} \colon [t_0,t_1] \to M$ starting from $x = C_{x,+}(t_0) = C_{x,+}(t_0)$ with 
\[
X_{\F_-}(x) = \lim_{s \to t_0+} \dfrac{C_{x,-}(s) - C_{x,-}(t_0)}{s - t_0} \in T_x M
\]
and 
\[
X_{\F_+}(x) = \lim_{s \to t_0+} \dfrac{C_{x,+}(s) - C_{x,+}(t_0)}{s - t_0} \in T_x M
\]
% whose domain are closed intervals and whose starting points are $x$
as in Figure~\ref{fig:ass_dir_vf}, and the singleton $\{X_{\F_-}(x), X_{\F_+}(x) \} = \{X_{\F_-}(x) \}$ of the unit tangent vector at any point $x \in \partial_{\pitchfork \F}$ of a leaf arc such that there is an non-degenerate arc-length $C^1$ leaf arc $C_{x,-} \colon [t_0,t_1] \to M$ starting from $x = C_{x,-}(t_0)$ satisfying the following equality:  
\[
X_{\F_-}(x) = \lim_{s \to t_0+} \dfrac{C_{x,-}(s) - C_{x,-}(t_0)}{s - t_0} \in T_x M
\]
\end{definition}

