\subsubsection{Distance between regular foliations and their topology}

We define the following concepts. 

\begin{definition}
For any $p \in \R_{\geq 1}$ and any pair of two regular foliations $\F$ and $\mathcal{G}$, define the superior distance $\bm{D(\F, \mathcal{G})}$ and the $L^p$-distance $\bm{D^p(\F, \mathcal{G})}$ between them with respect to $(r, \alpha)$ as follows:  
\[
D(\F, \mathcal{G}) = D^\infty(\F, \mathcal{G}) := \sup_{x \in M} d_H(X_{\F}(x), X_{\G}(x))
\]
\[
D^p(\F, \mathcal{G}) := \left(\dfrac{1}{\mathrm{vol}_g(M)}  \int_M d_H(X_{\F}(x), X_{\G}(x))^p d \mathrm{vol}_g \right)^{1/p}
\]
%where $d_H$ is the Hausdorff distance on $M$ with respect to the distance $d$. 
\end{definition}

\begin{definition}
For any $p \in \R_{\geq 1}$, any $\delta \in \R_{> 0}$, and a regular foliation $\F$ on a  manifold $M$, define the {\bf open $\delta$-ball} $\bm{B^p_{D}(\F,\delta)}$ centered at $\F$ as follows:  
\[
B^p_{D}(\F,\delta) := \{ \mathcal{G} \in \F_{\mathrm{reg}}(M) \mid D^p(\F, \mathcal{G}) < \delta \}
\]
\end{definition}

\begin{definition}
We define the set $\mathcal{B}^p_{\F_{\mathrm{reg}}(M)}$ of open balls as follows: 
\[
\mathcal{B}^p_{\F_{\mathrm{reg}}(M)} := \{ B^p_{D}(\F,\delta) \mid  \delta \in \R_{> 0}, \F \in \F_{\mathrm{reg}}(M) \}
\]
\end{definition}

\begin{definition}
For any $p \in \R_{\geq 1} \sqcup \{ \infty \}$, the smallest topology on $\F_{\mathrm{reg}}(M)$ which contains the set $\mathcal{B}^p_{\F_{\mathrm{reg}}(M)} $ of open balls is called the {\bf topology induced by the local Hausdorff $L^p$-distance} and denoted by $\bm{\mathcal{O}^p_{\F_{\mathrm{reg}}^q(M)}}$. 
\end{definition}

Then the set $\mathcal{B}^p_{\F_{\mathrm{reg}}(M)} $ is a subbase of the topology $\mathcal{O}^p_{\F_{\mathrm{reg}}^q(M)}$. 
Notice that we can define a distance $D^\infty$ (resp. $D^p$) between $k$-dimensional singular foliations by the supremum (resp. integral) of the Hausdorff distances between the normed squares tangent to leaves as well as one between one-dimensional singular foliations. 
These constructions will be addressed in future work.

\subsection{Topologies on the space of singular foliations}

To extend the topologies on the space of regular foliations to those for singular foliations, we define a weight function for singularities.

\subsubsection{Weight for singularities}

To define ``directed fields'' induced by singular foliations, we define the weight for singularities as follows. 

\begin{definition}
A non-decreasing continuous function $w \colon [0,\infty] \to [0,1]$ is a {\bf distance weight} if $w^{-1}(0) = \{ 0 \}$ and $w(\infty) = 1$. 
\end{definition}

Note that any distance weight is uniformly continuous because it is bounded, monotone increasing, and continuous. 

\begin{definition}
For a distance weight $w \colon [0,\infty] \to [0,1]$, 
% and a singular foliation $\F$, 
the {\bf weight} $\bm{\rho_{w}} \colon M \times \F(M) \to [0,1]$ with respect to $w$ is defined as follows:
\[
\rho_{w}(x, \F) = w(d_g(x, \mathop{\mathrm{Sing}}(\F)))
\]
\end{definition}

Put $\rho_{w,\F} := \rho_{w}(\cdot, \F) \colon M \to [0,1]$. 
Note that $\rho_{w}(\cdot, \F) \equiv 1$ for any regular foliation $\F$ and any distance weight $w$. 

\subsubsection{Associated ``directed fields'' of singular foliations}

Let $\F$ be a singular foliation on a Riemannian manifold $(M,g)$ whose leaves are of piecewise $C^1$. 
Since $\F_{\mathrm{reg}} := \F\vert_{\F - \mathop{\mathrm{Sing}}(\F)}$ is a regular foliation on a Riemannian manifold $M - \mathop{\mathrm{Sing}}(\F)$, denote by 
\[
X_{\F_{\mathrm{reg}}} \colon M  - \mathop{\mathrm{Sing}}(\F) \to \{ [0_x, X_{\F_-}(x)] \cup [0_x, X_{\F_{+}}(x)] \mid x \in M  - \mathop{\mathrm{Sing}}(\F) \} \subset TM_\pm
\]
the associated directed field of $\F_{\mathrm{reg}}$, where 
\[
X_{\F_{-}}(x) := X_{\F_{\mathrm{reg}-}}(x) \text{ and } X_{\F_{+}}(x) := X_{\F_{\mathrm{reg}+}}(x)
\]
for any $x \in M - \mathop{\mathrm{Sing}}(\F)$. 
%$\F_- := \F_{\mathrm{reg}-}$ and $\F_+ := \F_{\mathrm{reg}+}$. 
For any $x \in \mathop{\mathrm{Sing}}(\F)$, put $X_{\F_{-}}(x)  = X_{\F_{+}}(x)  := 0 \in T_x M$. 
Define the associated directed field $X_{\F} \colon M \to TM_\pm$ of the foliation $\F$ by $X_{\F}\vert_{\mathop{\mathrm{Sing}}(\F)} \equiv 0$ and 
\[
X_{\F}(x) := X_{\F_{\mathrm{reg}}}(x) = [0_x, X_{\F_-}(x)] \cup [0_x, X_{\F_+}(x)],
\]
which need not be continuous. 
Notice that the polyline $X_{\F}(x) = [0_x, X_{\F_-}(x)] \cup [0_x, X_{\F_+}(x)]$ is identified with $\{X_{\F_-}(x), X_{\F_+}(x)\}$ for any $x \in M$. 

For the weight $\rho_{w,\F} \colon M \to [0,1]$ of a distance weight $w \colon [0,\infty] \to [0,1]$, put 
\[
X_{w,\F_-}(x) :=  \rho_{w,\F}(x)X_{\F_-}(x)
\hspace{20pt}
X_{w,\F_+}(x) :=  \rho_{w,\F}(x)X_{\F_+}(x)
\]
for any $x \in M$. 
We define the continuous associated directed field of $\F$ with respect to the weight $\rho_{w,\F} \colon M \to [0,1]$ as follows. 

\begin{definition}
Define the {\bf continous associated directed field} $X_{w,\F} \colon M \to TM_\pm$ of $\F$ with respect to the weight $\rho_{w,\F} \colon M \to [0,1]$ by 
\[
\begin{split}
X_{w,\F}(x) := \rho_{w,\F}(x) X_{\F}(x) & = \{ \rho_{w,\F}(x) X_{\F_-}(x), \rho_{w,\F}(x) X_{\F_+}(x)\}
\\
& = \{ X_{w,\F_-}(x), X_{w,\F_+}(x) \} 
\end{split}
\]
for any $x \in M$.
\end{definition}
By definition, any continuous associated directed field is continuous. 
Moreover, we obtain that $X_{w,\F}(x) = \{ 0_x \}$ for any $x \in \mathop{\mathrm{Sing}}(\F)$, where $0_x \in T_x M$ is the zero tangent vector, and that 
\[
\begin{split}
X_{w,\F}(x) = \rho_{w,\F}(x) X_{\F}(x) &= [0_x, \rho_{w,\F}(x)X_{\F_-}(x)] \cup [0_x, \rho_{w,\F}(x)X_{\F_+}(x)]
\\
&= [0_x, X_{w,\F_-}(x)] \cup [0_x, X_{w,\F_+}(x)]
\end{split}
\]
for any $x \in M - \mathop{\mathrm{Sing}}(\F)$.

\subsubsection{Distance between singular foliations and their topology}

Fix a distance weight $w \colon [0,\infty] \to [0,1]$. 
We define a distance as follows. 

\begin{definition}
Define the wighted metric $\bm{D_{w}} \colon \F(M) \times \F(M) \to [0, \infty]$, called the {\bf locally wighted Hausdorff superior distance} on the set $\F(M)$ of singular foliations on a  manifold $M$ for an ordered field $[0, \infty]$: 
\[
\begin{split}
\bm{D_{w}(\F, \mathcal{G})} = D^\infty_{w}(\F, \mathcal{G}) &:= \sup_{x \in M} d_H(X_{w,\F}(x), X_{w,\G}(x))
\end{split}
\]
\end{definition}

%where $d_H$ is the Hausdorff distance on $M$ with respect to the distance $d$. 
Notice that $2 \geq \sup_{x \in M} d_H(X_{w,\F}(x), X_{w,\G}(x))$ for any  singular foliations $\F, \G$ on $M$ whose leaves are of piecewise $C^1$, and that $D_{w}(\F, \mathcal{G}) = D(\F, \mathcal{G})$ for any regular foliations $\F, \mathcal{G} \in \F_{\mathrm{reg}}(M)$. 
% and any $r \in \R_{> 0}$. 
%
Similarly, we define distances for any $p \in \R_{\geq 1}$ as follows. 

\begin{definition}
For any $p \in \R_{\geq 1}$,  
% and any $\delta \in \R_{> 0}$, 
and for a regular foliation $\F$ on a  manifold $M$, define the wighted metric $\bm{D^p_{w}} \colon \F(M) \times \F(M) \to [0, \infty]$, called the {\bf locally wighted Hausdorff $L^p$-distance} on the set $\F(M)$ of singular foliations on a  manifold $M$ for an ordered field $[0, \infty]$: 
\[
\bm{D^p_{w}(\F, \mathcal{G})}:= \left(\dfrac{1}{\mathrm{vol}_g(M)}  \int_M d_H(X_{w,\F}(x), X_{w,\G}(x))^p d \mathrm{vol}_g \right)^{1/p}
\]
\end{definition}


\subsubsection{Open $\delta$-balls for singular foliations and its topology}
Fix a distance weight $w \colon [0,\infty] \to [0,1]$ and any number $p \in \R_{\geq 1} \sqcup \{ \infty \}$. 
We define open balls with respect to $w$ and $p$ as follows. 

\begin{definition}
For any $\delta \in \R_{> 0}$ and any $p \in \R_{\geq 1} \sqcup \{ \infty \}$, and a singular foliation $\F$ on a  manifold $M$, define the {\bf open $\delta$-ball} $\bm{B_{D^p_{w}}(\F,\delta)}$ centered at $\F$ with respect to $w$ as follows:  
\[
B_{D^p_{w}}(\F,\delta) := \{ \mathcal{G} \in \F(M) \mid D^p_{w}(\F, \mathcal{G}) < \delta \}
\]
\end{definition}

Moreover, we define the set $\bm{\mathcal{B}^p_{w,\F(M)}}$ of open balls with respect to $w$ as follows: 
\[
\mathcal{B}^p_{w,\F(M)} := \{ B_{D^p_{w}}(\F,\delta) \mid \delta \in \R_{> 0}, \F \in \F(M) \}
\]

\subsubsection{Topologies for singular foliations}

We define a topology on the set $\F(M)$ of one-dimensional singular foliations on a Riemannian manifold $M$. 

\begin{definition}\label{def:topology}
For any distance weight $w \colon [0,\infty] \to [0,1]$ and any $p \in \R_{\geq 1} \sqcup \{ \infty \}$, 
the smallest topology on $\F^q(M)$ which contains the set $\mathcal{B}^p_{w,\F(M)} $ of open balls  with respect to $w$ is called the {\bf topology induced by the local Hausdorff distance} with respect to $w$ and denoted by $\bm{\mathcal{O}^p_{w,\F^q(M)}}$. 
\end{definition}

Then the set $\mathcal{B}^p_{w,\F(M)} $ is a subbase of the topology $\mathcal{O}^p_{w,\F^q(M)}$. 


