\[
\varepsilon'_w(x_0) := \inf \{ \rho_{w,\F}(x) \mid x \in B(x_0,\delta(x_0)) \}
\]
for any $x_0 \in M - \mathop{\mathrm{Sing}}(\F)$. 

\begin{claim}\label{claim:20}
$2 \varepsilon_w = \varepsilon'_w$. 
\end{claim}

\begin{proof}[Proof of Claim~\ref{claim:20}]
For any $x_0 \in \mathop{\mathrm{Sing}}(\F)$, by $\rho_{w,\F}(x_0) = w(d_g(x_0, \mathop{\mathrm{Sing}}(\F)))$ and $\delta(x) = d(x,\mathop{\mathrm{Sing}}(\F))/2$, 
assertion (1) implies the following equality: 
