We observe the non-existence of singular points outside of \nbds of singular points under perturbations as follows.

\begin{corollary}\label{cor:nonexistence_sing}
For any distance weight $w \colon [0,\infty] \to [0,1]$ and any positive number $\delta_0 > 0$, there is a positive number $\varepsilon_0>0$ satisfying the following relation: 
\[
\bigcup_{\mathcal{G} \in B_{D^\infty_{w}}(\F,\varepsilon_0)}  \mathop{\mathrm{Sing}}(\mathcal{G}) \subseteq B_{\delta_0}(\mathop{\mathrm{Sing}}(\F)))
\]
\end{corollary}


\begin{proof}
Fix any distance weight $w \colon [0,\infty] \to [0,1]$ and any $\delta_0 > 0$. 
%
Put $\varepsilon_0 := w(\delta_0/2)/3$. 
Fix any $x_0 \in M - B_{\delta_0}(\mathop{\mathrm{Sing}}(\F))$. 
%Let $\varepsilon_w, \delta_w \colon M \to \R_{\geq 0}$ be continuous functions before the previous lemma.
Then the following inequalities hold: 
\[
\delta_w(x_0) = d(x_0,\mathop{\mathrm{Sing}}(\F))/2 \geq \delta_0/2
\]  
\[
\begin{split}
\varepsilon_w(x_0) & = \min \{ \rho_{w,\F}(x) \mid x \in B(x_0,\delta_w(x_0)) \}/2 
\\
& \geq w(d(x_0,\mathop{\mathrm{Sing}}(\F))/2)/2
\\
& = w(\delta_w(x_0))/2 \geq w(\delta_0/2)/2 > \varepsilon_0
\end{split}
\]

By Lemma~\ref{lem:open_reg_pt},  we have 
\[
B(x_0,\delta_w(x_0)) \cap \bigcup_{\mathcal{G} \in B_{D^\infty_{w}}(\F,\varepsilon_0)}  \mathop{\mathrm{Sing}}(\mathcal{G}) = \emptyset
\] 
and so 
\[
\bigcup_{x \in M - B_{\delta_0}(\mathop{\mathrm{Sing}}(\F))} B(x,\delta_w(x)) \cap \bigcup_{\mathcal{G} \in B_{D^\infty_{w}}(\F,\varepsilon_0)}  \mathop{\mathrm{Sing}}(\mathcal{G}) = \emptyset
\] 
%$x_0 \notin \bigcup_{\mathcal{G} \in B_{D^\infty_{w}}(\F,\varepsilon_0)}  \mathop{\mathrm{Sing}}(\mathcal{G})$. 
This implies the following equality: 
\[
(M - B_{\delta_0}(\mathop{\mathrm{Sing}}(\F))) \cap \bigcup_{\mathcal{G} \in B_{D^\infty_{w}}(\F,\varepsilon_0)}  \mathop{\mathrm{Sing}}(\mathcal{G}) = \emptyset
\]
Therefore, the assertion holds. 
\end{proof}

The local non-existence of singular leaves persists with respect to $\mathcal{O}^p_{w,\F^q(M)}$ ($p \in \R_{\geq 1}$) as follows. 

\begin{lemma}\label{lem:open_reg_pt_03}
%Let $\F$ be a singular foliation on a Riemannian manifold $M$ with or without boundary, 
%$x_0 \in M - \mathop{\mathrm{Sing}}(\F)$ a point, 
Let $p \in \R_{\geq 1}$ be a number. 
Suppose that the volume of $M$ is finite. 
% and $r, \alpha \in \R_{> 0}$ positive numbers. 
For any distance weight $w \colon [0,\infty] \to [0,1]$, there are continuous functions $\varepsilon_1, \delta_1 \colon M \to \R_{\geq 0}$ with $\varepsilon_1^{-1}(0) = \delta_1^{-1}(0) = \mathop{\mathrm{Sing}}(\F)$ satisfying the following equation for any $x_0 \in M - \mathop{\mathrm{Sing}}(\F)$: 
\[
B(x_0,\delta_1(x_0)) \cap \bigcup_{\mathcal{G} \in B_{D^p_{w}}(\F,\varepsilon_1(x_0))}  \mathop{\mathrm{Sing}}(\mathcal{G}) = \emptyset
\] 
\end{lemma}

\begin{proof}
If $M$ has a boundary, then fix an extension $M'$ of $M$, which is an open manifold containing $M$ in the interior. 
Fix any distance weight $w \colon [0,\infty] \to [0,1]$.
For any $x \in \mathop{\mathrm{Sing}}(\F)$, define $\varepsilon_1(x) = \delta_1(x) := 0$. 
%
Lemma~\ref{lem:open_reg_pt} implies that the continuous functions $\varepsilon_w, \delta_w \colon M \to \R_{\geq 0}$ with $\varepsilon_w^{-1}(0) = \delta_w^{-1}(0) = \mathop{\mathrm{Sing}}(\F)$ satisfy the following equation for any $x_0 \in M - \mathop{\mathrm{Sing}}(\F)$: 
\[
B(x_0,\delta_w(x_0)) \cap \bigcup_{\mathcal{G} \in B_{D^\infty_{w}}(\F,\varepsilon_w(x_0))}  \mathop{\mathrm{Sing}}(\mathcal{G}) = \emptyset
\] 
Then the functions $\delta_w/n \colon M \to \R_{\geq 0}$ are continuous for any $n \in \Z_{>1}$. 
For any integer $n \in \Z_{>1}$ and any $x_0 \in M - \mathop{\mathrm{Sing}}(\F)$, define positive numbers 
\[
d_{n}(x_0) := \inf_{x \in B(x_0,\delta_w(x_0)/n)} d_g(x,\mathop{\mathrm{Sing}}(\mathcal{F})) \geq  \delta_w(x_0) (n-1)/n > 0
\]
and $w_n(x_0) := w(d_{n}(x_0)) > 0$. 
For any integer $n \in \Z_{>1}$, putting $w_n \vert_{\mathop{\mathrm{Sing}}(\mathcal{F})} := 0$, by constructions of $d_n$ and $w_n$, the extended function $w_n \colon M \to \R_{\geq 0}$ is continuous. 

\begin{claim}\label{claim:01a}
For any point $x_0 \in M - \mathop{\mathrm{Sing}}(\F)$, there is a positive number $\delta_{1,x_0}$ such that $\inf_{x \in B(x_0,\delta_{1,x_0})} d_H(X_{w,\F}(x), X_{w,\G}(x)) >\sup_{x \in B(x_0,\delta_{1,x_0})} \rho_{w,\F}(x)/4$ for any $\mathcal{G} \in \mathcal{F}(M)$ with $\mathop{\mathrm{Sing}}(\mathcal{G}) \cap B(x_0,\delta_{1,x_0}) \neq \emptyset$. 
\end{claim}

\begin{proof}[Proof of Claim~\ref{claim:01a}]
Fix a point $x_0 \in M - \mathop{\mathrm{Sing}}(\F)$. 
Then we have $\lim_{n \to \infty} w_n(x_0) = w(d_g(x_0, \mathop{\mathrm{Sing}}(\F))) = \rho_{w,\F}(x_0) > 0$. 
Moreover, we have the following inequalities for any $n \in \Z_{>1}$: 
\[
\begin{split}
\inf_{x \in B(x_0,\delta_w(x_0)/n)} \vert X_{w,\F}(x) \vert & = \inf_{x \in B(x_0,\delta_w(x_0)/n)} \vert \rho_{w,\F}(x) \vert 
\\
& = \inf_{x \in B(x_0,\delta_w(x_0)/n)} w(d_g(x, \mathop{\mathrm{Sing}}(\F))) = w_n(x_0)
\end{split}
\]
Since $\lim_{n \to \infty} \sup_{x \in B(x_0,\delta_w(x_0)/n)} \rho_{w,\F}(x)/2 = \rho_{w,\F}(x_0)/2 <  \lim_{n \to \infty} w_n(x_0)$, there is a positive integer $N_1(x_0)$ such taht 
\[
\inf_{x \in B(x_0,\delta_w(x_0)/n)} \vert X_{w,\F}(x) \vert > \sup_{x \in B(x_0,\delta_w(x_0)/n)} \dfrac{\rho_{w,\F}(x)}{2} > 0
\]
for any $n \in \Z_{>N_1(x_0)}$. 
%
On the other hand, define a positive constant $M(n,x_0)$ as follows: 
\[
M(n,x_0) := \sup_{\mathcal{G} \in \F(M) \text{ with } \mathop{\mathrm{Sing}}(\mathcal{G}) \cap B(x_0,\delta_w(x_0)/n) \neq \emptyset} \sup_{x \in B(x_0,\delta_w(x_0)/n)} \vert X_{w,\G}(x) \vert
\] 
Since the norm $\vert X_{w,\G}(x) \vert$ for any $\mathcal{G} \in \F(M)$ and for any $x \in M$ satisfies $\vert X_{\G}(x) \vert = \vert \rho_{w,\G}(x) \vert$, we have the following equality: 
\[
\begin{split}
\lim_{n \to \infty} M(n,x_0) = & \lim_{n \to \infty} \sup_{\mathcal{G} \in \F(M) \text{ with } \mathop{\mathrm{Sing}}(\mathcal{G}) \cap B(x_0,\delta_w(x_0)/n) \neq \emptyset} \sup_{x \in B(x_0,\delta_w(x_0)/n)} \vert X_{w,\G}(x) \vert
\\
= & \lim_{n \to \infty} \sup_{\mathcal{G} \in \F(M) \text{ with } \mathop{\mathrm{Sing}}(\mathcal{G}) \cap B(x_0,\delta_w(x_0)/n) \neq \emptyset} \sup_{x \in B(x_0,\delta_w(x_0)/n)} \vert \rho_{w,\G}(x) \vert 
\\
 = & \, \, 0
\end{split}
\]
By $\lim_{r \to \infty} w(1/r)=0$, since $\lim_{n \to \infty} \inf_{x \in B(x_0,\delta_w(x_0)/n)} \rho_{w,\F}(x) = \rho_{w,\F}(x_0) > 0$, there is a positive integer $N_2(x_0) \geq N_1(x_0)$ such taht 
\[
\inf_{x \in B(x_0,\delta_w(x_0)/n)} \dfrac{\rho_{w,\F}(x_0)}{4} > M(n,x_0)
\]
for any $n \in \Z_{>N_2(x_0)}$. 
Fix a positive integer $n(x_0) \in \Z_{>N_2(x_0)}$. 
Put $\delta_{1,x_0} :=\delta(x_0)/n(x_0)$. 
Then the following inequalities holds for any $\mathcal{G} \in \mathcal{F}(M)$ with $\mathop{\mathrm{Sing}}(\mathcal{G}) \cap B(x_0,\delta_{1,x_0}) \neq \emptyset$:  
\[
\begin{split}
 \inf_{x \in B(x_0,\delta_{1,x_0})} \vert X_{w,\F}(x) \vert > \sup_{x \in B(x_0,\delta_{1,x_0})} \dfrac{\rho_{w,\F}(x)}{2} & > \inf_{x \in B(x_0,\delta_{1,x_0})} \dfrac{\rho_{w,\F}(x)}{4} 
 \\
 & > M(n(x_0),x_0) 
 \\
 & \geq \sup_{x \in B(x_0,\delta_{1,x_0})} \vert X_{w,\G}(x) \vert
\end{split}
\]
Therefore, we have the following inequality for any $\mathcal{G} \in \mathcal{F}(M)$ with $\mathop{\mathrm{Sing}}(\mathcal{G}) \cap B(x_0,\delta_{1,x_0}) \neq \emptyset$: 
\[
\inf_{x \in B(x_0,\delta_{1,x_0})} d_H(X_{w,\F}(x), X_{w,\G}(x)) > \sup_{x \in B(x_0,\delta_{1,x_0})} \rho_{w,\F}(x)/4
\]
\end{proof}

By the paracompactness of $M$ and the closedness of $\mathop{\mathrm{Sing}}(\F)$, there is a locally finite open cover $\{\mathop{\mathrm{int}} B(x_{0,\lambda},\delta_{1,x_{0,\lambda}}) \}_{\lambda \in \Lambda}$ of $M - \mathop{\mathrm{Sing}}(\F)$. 
For any $x \in M - \mathop{\mathrm{Sing}}(\F)$, the subset $\Lambda_x := \{ \lambda \in \Lambda \mid x \in \mathop{\mathrm{int}} B(x_{0,\lambda}, \delta_{1,x_{0,\lambda}}) \}$ is finite. 
Therefore, define a function $\delta_1 \colon M \to \R_{\geq 0}$ by $\delta^{-1}(0) = \mathop{\mathrm{Sing}}(\F)$ and 
\[
\delta_1(x) := \max \{ \delta_{1,x_{0,\lambda}} - d(x_{0,\lambda}, x) \mid \lambda \in \Lambda_x \}
\]
 for any $x \in M - \mathop{\mathrm{Sing}}(\F)$. 

\begin{claim}\label{claim:03a}
$\inf_{x \in B(x_0,\delta_1(x_0))} d_H(X_{w,\F}(x), X_{w,\G}(x)) \geq \rho_{w,\F}(x_{0})/4$ for any $x_0 \in M - \mathop{\mathrm{Sing}}(\F)$.
\end{claim}

\begin{proof}[Proof of Claim~\ref{claim:03a}]
By construction, the function $\delta_1$ is continuous. 
For any point $x_0 \in M - \mathop{\mathrm{Sing}}(\F)$, there is an index $\lambda \in \Lambda_{x_0} \subseteq \Lambda$ such that $B(x_0,\delta_1(x_0)) \subseteq B(x_{0,\lambda}, \delta_{1,x_{0,\lambda}})$ and so 
\[
\begin{split}
& \inf_{x \in B(x_0,\delta_1(x_0))} d_H(X_{w,\F}(x), X_{w,\G}(x)) 
\\
\geq & \inf_{x \in B(x_{0,\lambda}, \delta_{1,x_{0,\lambda}})} d_H(X_{w,\F}(x), X_{w,\G}(x))
\\
\geq & \sup_{x \in B(x_{0,\lambda}, \delta_{1,x_{0,\lambda}})} \rho_{w,\F}(x)/4 \geq \rho_{w,\F}(x_{0})/4
\end{split}
\]
because of Claim~\ref{claim:01a}.
\end{proof}
%
Define a continuous function $\varepsilon_1 \colon M \to [0,1/5]$ as follows: 
\[
\varepsilon_1(x_0) := \dfrac{\rho_{w,\F}(x_0)}{5} \left(\dfrac{1}{\mathrm{vol}_g(M)} \mathrm{vol}_g(B(x_0,\delta_1(x_0))) \right)^{1/p} 
\]

\begin{claim}\label{claim:02a}
For any point $x_0 \in M - \mathop{\mathrm{Sing}}(\F)$ and any $\mathcal{G} \in \mathcal{F}(M)$ with $\mathop{\mathrm{Sing}}(\mathcal{G}) \cap B(x_0,\delta_1(x_0)) \neq \emptyset$, the following relation holds:  
\[
\mathcal{G} \notin B_{D^p_{w}}(\F,\varepsilon_1(x_0)))
\] 
\end{claim}

\begin{proof}[Proof of Claim~\ref{claim:02a}]
%Inedeed, f
Fix any point $x_0 \in M - \mathop{\mathrm{Sing}}(\F)$ and any singular foliation $\mathcal{G} \in \mathcal{F}(M)$ with $\mathop{\mathrm{Sing}}(\mathcal{G}) \cap B(x_0,\delta_1(x_0)) \neq \emptyset$. 
Then Claim~\ref{claim:03a} implies  
\[
\begin{split}
& D^p_{w}(\F, \mathcal{G}) \\
= & \left(\dfrac{1}{\mathrm{vol}_g(M)}  \int_M d_H(X_{w,\F}(x), X_{w,\G}(x))^p d \mathrm{vol}_g \right)^{1/p}\\
\geq & \left(\dfrac{1}{\mathrm{vol}_g(M)}  \int_{B(x_0,\delta_1(x_0))} d_H(X_{w,\F}(x), X_{w,\G}(x))^p d \mathrm{vol}_g \right)^{1/p}
\\
\geq & \left(\dfrac{1}{\mathrm{vol}_g(M)}  \int_{B(x_0,\delta_1(x_0))} \left( \dfrac{\rho_{w,\F}(x_0)}{4} \right)^p d \mathrm{vol}_g \right)^{1/p} \\
\geq & \dfrac{\rho_{w,\F}(x_0)}{4} \left(\dfrac{1}{\mathrm{vol}_g(M)}  \int_{B(x_0,\delta_1(x_0))}  d \mathrm{vol}_g \right)^{1/p} \\
= & \dfrac{\rho_{w,\F}(x_0)}{4} \left(\dfrac{1}{\mathrm{vol}_g(M)} \mathrm{vol}_g(B(x_0,\delta_1(x_0))) \right)^{1/p} > \varepsilon_1(x_0)
\end{split}
\]
because of $\varepsilon_1(x_0) = \dfrac{\rho_{w,\F}(x_0)}{5} \left(\dfrac{1}{\mathrm{vol}_g(M)} \mathrm{vol}_g(B(x_0,\delta_1(x_0))) \right)^{1/p}$. 
This means $\mathcal{G} \notin B_{D^p_{w}}(\F,\varepsilon_1(x_0)))$. 
\end{proof}
This completes the proof. 
\end{proof}


\subsubsection{Persistence of regular foliations}

We have the following persistence of regular foliations. 

\begin{lemma}\label{lem:open_reg}
%Let $\F$ be a regular foliation on a Riemannian manifold $M$. 
%Suppose that $\F$ is regular. 
%If $\mathop{\inf_{x \in M}} \vert X_{w,\F}(x) \vert > 0$, 
If $\F$ is regular, then there is an open neighborhood of $\F$ in $\F(M)$ which consists of regular foliations with respect to the topology $\mathcal{O}^p_{w,\F^q(M)}$ for any $p \in \R_{\geq 1} \sqcup \{ \infty \}$. 
\end{lemma}

\begin{proof}
Fix any distance weight $w \colon [0,\infty] \to [0,1]$ and any number $p \in \R_{\geq 1}$. 
By $\lim_{r \to \infty} w(1/r) = 0$, there is a positive number $\varepsilon> 0$ such that $w(\varepsilon) < 1/2$. 
Fix a positive number $\delta := (\mathrm{vol}_g(B(x_0,\varepsilon))/\mathrm{vol}_g(M))^{1/p}/3$.
The regularity of $\F$ implies that $\rho_{\omega,\F} = 1$ is a constant function. 
Then $d_H(X_{w,\F}(x), \{ 0_x \} )= 1$ for any $x \in M$. 

Fix a singular foliation $\mathcal{G}$ with a point $x_0 \in \mathop{\mathrm{Sing}}(\G)$. 
%By definition of cones of points on singular leaves, we have that 
Then $\{ 0_{x_0} \} = X_{\G}(x) = X_{w,\G}(x)$. 
Therefore $D^\infty_{w}(\F, \mathcal{G}) \geq d_H(X_{\F,x_0}, X_{w,\G}(x_0)) = d_H(X_{\F,x_0}, \{ 0_{x_0} \}) = 1 > 1/2$. 
This means that $B_{D^\infty_{w}}(\F,1/2)$ consists of regular foliations. 
%For any $p \in \R_{\geq 1}$, we have that 
We have that 
\[
\begin{split}
& D^p_{w}(\F, \mathcal{G}) \\
= & \left(\dfrac{1}{\mathrm{vol}_g(M)}  \int_M d_H(X_{w,\F}(x), X_{w,\G}(x))^p d \mathrm{vol}_g \right)^{1/p}\\
\geq & \left(\dfrac{1}{\mathrm{vol}_g(M)}  \int_{B(x_0,\varepsilon)} d_H(X_{w,\F}(x), X_{w,\G}(x))^p d \mathrm{vol}_g \right)^{1/p}\\
\geq & \left(\dfrac{1}{\mathrm{vol}_g(M)}  \int_{B(x_0,\varepsilon)} \left(\dfrac{1}{2}\right)^p d \mathrm{vol}_g \right)^{1/p}\\
\geq & \dfrac{1}{2} \left(\dfrac{1}{\mathrm{vol}_g(M)}  \int_{B(x_0,\varepsilon)} d \mathrm{vol}_g \right)^{1/p} =\dfrac{1}{2} \left(\dfrac{\mathrm{vol}_g(B(x_0,\varepsilon))}{\mathrm{vol}_g(M)} \right)^{1/p} > \delta 
\end{split}
\]
and so that $B_{D^p_{w}}(\F,\delta)$ consists of regular foliations. 
\end{proof}

The previous lemma implies the following openness. 

\begin{corollary}\label{cor:open_reg}
For any $p \in \R_{\geq 1} \sqcup \{ \infty \}$, the subset of regular foliations on $M$ is open in $\F(M)$ with respect to the topology $\mathcal{O}^p_{w,\F^q(M)}$.
\end{corollary}

