\[
\begin{split}
D^\infty_{w}(\F, \mathcal{G}) & = \sup_{x \in M} d_H(X_{w,\F}(x), X_{w,\G}(x))  \\
& \geq \sup_{x \in B(x,\varepsilon/n)} d_H(X_{w,\F}(x), X_{w,\G}(x)) \\
& \geq \left( w \left(\dfrac{(n-1)\varepsilon}{n} \right) - w \left(\dfrac{\varepsilon}{n} \right) \right)  > \delta 
\end{split}
\]
and 
\[
\begin{split}
D^p_{w}(\F, \mathcal{G}) = & \left(\dfrac{1}{\mathrm{vol}_g(M)}  \int_M d_H(X_{w,\F}(x), X_{w,\G}(x))^p d \mathrm{vol}_g \right)^{1/p}\\
\geq  & \left(\dfrac{1}{\mathrm{vol}_g(M)}  \int_{B(x,\varepsilon/n)} d_H(X_{w,\F}(x), X_{w,\G}(x))^p d \mathrm{vol}_g \right)^{1/p}\\
\geq  & \left(\dfrac{1}{\mathrm{vol}_g(M)}  \int_{B(x,\varepsilon/n)} \left( w \left(\dfrac{(n-1)\varepsilon}{n} \right) - w \left(\dfrac{\varepsilon}{n} \right) \right)^p  d \mathrm{vol}_g \right)^{1/p}\\
= & \left( w \left(\dfrac{(n-1)\varepsilon}{n} \right) - w \left(\dfrac{\varepsilon}{n} \right) \right)  \left(\dfrac{\mathrm{vol}_g(B(x,\varepsilon/n))}{\mathrm{vol}_g(M)} \right)^{1/p}  > \delta 
\end{split}
\]
if $p \in \R_{\geq 1}$. 
The previous inequalities contradict to $\mathcal{G} \in B_{D^p_{w}}(\F,\delta)$. 
%\end{proof}
Thus $B(x,\varepsilon) \cap \mathop{\mathrm{Sing}(\G)} \neq \emptyset$ for any $\mathcal{G} \in B_{D^p_{w}}(\F,\delta)$. 
\end{proof}


\subsection{Descriptions near singular points}

We describe the behaviors near singular points to characterize the instability of some kinds of singular points. 

\begin{lemma}\label{lem:singular_pt_nbd03}
%Fix any $r, \alpha \in \R_{> 0}$. 
For any positive number $\varepsilon >0$, there is a positive number $\delta > 0$ satisfying the following inequality: 
%for any point $x_0 \in \mathop{\mathrm{Sing}}(\F)$
\[ 
\sup_{x_0 \in \mathop{\mathrm{Sing}}(\F)} \sup_{x \in B(x_0,\delta)}d_H(X_{w,\F}(x), \{ 0_{x} \}) \leq \varepsilon
\]
\end{lemma}

\begin{proof}
Fix a positive number $\varepsilon >0$. 
%Put $\gamma_x := X_{w,\F}(x)$ for any $x \in M$. 
Then $X_{w,\F}(x) = \{ 0_x \}$ for any $x \in \SF$. 
By $\lim_{r \to \infty} \sup_{x \in B(x_0,1/r)} \vert X_{w,\F}(x) \vert = 0$, there is a positive number $\delta \in (0, \varepsilon/2)$ such that $X_{w,\F}(x) \subseteq B(0_x, \varepsilon)$ for any $x_0 \in \mathop{\mathrm{Sing}}(\F)$ and any point $x \in B(x_0, \delta) $. 
On the other hand, we have $\{ 0_{x} \} \subset B(X_{w,\F}(x), \varepsilon)$ for any $x_0 \in \mathop{\mathrm{Sing}}(\F)$ and any $x \in B(x_0, \delta)$. 
This means that the assertion holds. 
\end{proof}

\begin{lemma}\label{lem:singular_pt_nbd02}
 Let $\mathcal{G} := \{ \{x \} \mid x \in M\}$ be the $0$-dimensional foliation on $M$. 
%Fix any $r, \alpha \in \R_{> 0}$. 
For any positive number $\varepsilon >0$, there is a positive number $\delta > 0$ satisfying the following inequality: 
\[ 
\sup_{x \in B(\mathop{\mathrm{Sing}}(\F),\delta)}d_H(X_{w,\F}(x), X_{w,\G}(x)) < \varepsilon
\]
Moreover, if $M = B(\mathop{\mathrm{Sing}}(\F),\delta)$, then $D^p_{w}(\F, \mathcal{G}) < \varepsilon$ for any $p \in \R_{\geq 1} \sqcup \{ \infty \}$. 
\end{lemma}

\begin{proof}
Fix a positive number $\varepsilon >0$. 
For any point $x \in M$, we obtain that $X_{w,\G}(x) = \{ 0_x \}$. 
Choose a positive number $\delta >0$ as in Lemma~\ref{lem:singular_pt_nbd03}. 
%
Fix a point $x \in B(\mathop{\mathrm{Sing}}(\F), \delta)$. 
If $x$ is singular, then $X_{w,\F}(x) = \{ 0_x \} = X_{w,\G}(x)$ and so $d_H(X_{w,\F}(x), X_{w,\G}(x)) = 0$. 
%
Thus we may assume that $x$ is not singular. 
By the choice of $\delta$, we obtain that $d_H(X_{w,\F}(x), X_{w,\G}(x)) = d_H(X_{w,\F}(x), \{ 0_x \}) < \varepsilon$. 

Suppose that $M = B(\mathop{\mathrm{Sing}}(\F),\delta)$. 
By defintion of $D^\infty_{w}$, we obtain that $D^\infty_{w}(\F, \mathcal{G}) < \varepsilon$. 
For any $p \in \R_{\geq 1}$, we have the following inequality: 
\[
\begin{split}
& D^p_{w}(\F, \mathcal{G}) \\
= & \left(\dfrac{1}{\mathrm{vol}_g(M)}  \int_M d_H(X_{w,\F}(x), X_{w,\G}(x))^p d \mathrm{vol}_g \right)^{1/p}\\
\leq & \left(\dfrac{1}{\mathrm{vol}_g(M)} \int_M \varepsilon^p d \mathrm{vol}_g \right)^{1/p} = \varepsilon \left(\dfrac{1}{\mathrm{vol}_g(M)} \mathrm{vol}_g(M) \right)^{1/p} = \varepsilon
\end{split}
\]
\end{proof}


\subsubsection{Transversality for singular foliations}

Recall that a subset $S$ is {\bf transverse} to a singular $C^1$-foliation $\F$ on a manifold $M$ if $T_x S + T_x \F = T_x M$ for any $x \in S$, where $T_x \F$ is the tangent space of a leaf of $\F$ at $x$. 
An arc is a {\bf transverse arc} to a codimension one foliation if it is transverse to the foliation. 

Although the transversality can be similarly defined for singular piecewise $C^1$-foliations on surfaces, we provide the details in Appendix~\ref{def:trans} due to its technical nature.
%since it is a bit technical, we explain it in Appendix~\ref{def:trans}.

We define a transverse boundary of a trivial fibered chart as follows. 

\begin{definition}
Let $\F$ be a one-dimensional foliation on a manifold $M$. 
A connected transverse subset $T$ is a {\bf transverse boundary} of a trivial fibered chart $\varphi \colon V \to U_\tau \times U_\pitchfork = (-1,1) \times (-1,1)^{n-1}$ with respect to $\F$ if the trivial fibered chart $\varphi$ can be extended to a trivial fibered chart $\hat{\varphi} \colon \hat{V} \to (-1-\varepsilon,1+\varepsilon) \times U_\pitchfork$ for some positive number $\varepsilon$ such that $T = \hat{\varphi}^{-1}(\{-1,1\} \times U_\pitchfork)$. 
Then put $\partial_{\pitchfork} V := T$, $\partial_{\pitchfork}^-V := \hat{\varphi}^{-1}(\{-1\} \times U_\pitchfork)$, and $\partial_{\pitchfork}^+V := \hat{\varphi}^{-1}(\{1\} \times U_\pitchfork)$. 
\end{definition}

We define the first return to the transverse boundary of the trivial fibered chart. 

\begin{definition}
Let $V$ be a trivial fibered chart. 
The map $\partial_{\pitchfork}^-V \to \partial_{\pitchfork}^+V$ which maps the first returns of points in $\partial_{\pitchfork}^-V$ to points in $\partial_{\pitchfork}^+V$ along the leaf arcs in $V \sqcup \partial_{\pitchfork} V$ is called the {\bf first return with respect to the trivial fibered chart $V$}. 
\end{definition}



\subsubsection{Assumptions on the boundary}

In this paper, following the standard framework of foliation theory, we assume that every boundary component of a singular foliation is either transverse to the foliation or a union of leaves. 
More general settings  will be addressed in future work.



\subsection{Invariance of closed transverse subsets}

By definition of topologies, we have the following observations. 

\begin{lemma}\label{lem:trans}
Any closed transverse subset for a singular foliation on a Riemannian manifold $M$ is invariant under small perturbations with respect to $\mathcal{O}^\infty_{w,\F^q(M)}$. 
% for any $p \in \R_{\geq 1} \sqcup \{ \infty \}$. 
\end{lemma}

\begin{proof}
By definition of $\mathcal{O}^\infty_{w,\F^q(M)}$, the transversality of closed transverse subsets is invariant under small perturbations with respect to $\mathcal{O}^\infty_{w,\F^q(M)}$. 
\end{proof}

Notice that the previous lemma does not holds for any $p \in \R_{\geq 1}$ even for the restriction $\mathcal{O}^p_{\F_{\mathrm{reg}}^q(M)}$. 
More precisely, we have the following observation. 

\begin{lemma}
For any singular foliation $\F$ on a Riemannian manifold $M$ with a closed transverse subset $T$ such that $\dim M > \dim T$, any $p \in \R_{\geq 1}$, and any positive number $\varepsilon > 0$, 
%neighborhood $B_{D^p_{w}}(\F,\delta)$ of $\F$ with respect to $\mathcal{O}^p_{\F^q(M)}$, 
there is a foliation $\mathcal{G}$ in $B_{D^p_{w}}(\F,\varepsilon)$ with $\mathop{\mathrm{Sing}}(\F) = \mathop{\mathrm{Sing}}(\G)$ which is obtain by a replacement of a small neighborhood $U$ of $T$ such that $\G$ is tangent to $T$ at a point in $T$. 
%, where $B_{D^p_{w}}(\F,\delta)$ of $\F$ is a $\delta$-ball with respect to $\mathcal{O}^p_{\F^q(M)}$. 
\end{lemma}

\begin{proof}
Fix a positive number $\varepsilon > 0$. 
Choose a neighborhood $U$ of $T$ with $\mathrm{vol}_g(U) < (\varepsilon/2)^p \mathrm{vol}_g(M)$. 
By $2 \geq \sup_{x \in M} d_H(X_{w,\F}(x), X_{w,\G}(x))$, the arbitrarily deformation on $U$ implies the following inequality for the resulting foliation $\mathcal{G}$: 
\[
\begin{split}
& D^p_{w}(\F, \mathcal{G}) \\
= & \left(\dfrac{1}{\mathrm{vol}_g(M)}  \int_M d_H(X_{w,\F}(x), X_{w,\G}(x))^p d \mathrm{vol}_g \right)^{1/p}\\
= & \left(\dfrac{1}{\mathrm{vol}_g(M)}  \int_U d_H(X_{w,\F}(x), X_{w,\G}(x))^p d \mathrm{vol}_g \right)^{1/p}\\
\leq & \left(\dfrac{1}{\mathrm{vol}_g(M)}  \int_U 2^p d \mathrm{vol}_g \right)^{1/p} = 2 \left(\dfrac{\mathrm{vol}_g(U)}{\mathrm{vol}_g(M)} \right)^{1/p} < \varepsilon
\end{split}
\]
%because of $X_{w,\F}(x) \subseteq X_{\F}(x) \subseteq B_{\mathrm{geod}}\left(x,\sqrt{1+\alpha^2}r \right)$ and the same inclusion for $\mathcal{G}$. 
Since the deformation on $U$ is an arbitrary replacement, we may assume that $\mathcal{G}$ has a tangency on the closed transverse subset. 
\end{proof}

Therefore, we use the topology $\mathcal{O}^\infty_{w,\F^q(M)}$ to discuss the structural stability of singular foliations on surfaces below. 


\section{Singular foliations on surfaces}

In this section, we discuss singular foliations on surfaces. 
%Let $\F$ be a singular foliation on a surface $M$. 

\subsection{Line fields}

We define line fields as follows.
\begin{definition} 
A singular foliation $\F$ is a {\bf line field}  if $\dim \F=1$. 
\end{definition} 
A line field is also called {\bf fields of line elements} (cf. \cite{Hopf1989diff}), {\bf director field} in nematic liquid crystals, and {\bf orientation field} in fingerprint recognition systems. 

From now on, let $\F$ be a line field on a surface $M$ unless otherwise stated. 


\subsubsection{Types of leaves on codimension one singular foliations}

A leaf of a singular foliation on $M$ is {\bf proper} if it is an embedded submanifold in $M$, {\bf locally dense} if its closure has the nonempty interior, and {\bf exceptional} if it is neither proper nor locally dense. 

\subsubsection{Types of leaves on dimension one singular foliations}

As in the flow case (see \S~\ref{sec:flow} in Appendix), we define the following concepts. 

\begin{definition} 
A singular leaf of a singular foliation is a {\bf singularity} or a {\bf singular point} if it is a singleton (i.e. the dimension of the leaf is zero). 
\end{definition} 

\begin{definition} 
A leaf is {\bf periodic} if it is homeomorphic to a circle. 
\end{definition} 

Denote by $\bm{\mathop{\mathrm{Per}}(\F)}$ the union of periodic leaves. 

\begin{definition} 
A leaf is {\bf closed} if it is a singular or periodic leaf. 
\end{definition} 

Note that a leaf that is a closed interval on a closed disk is not a closed leaf. 
%
Moreover, any closed proper regular leaves on dimension one singular foliations on closed surfaces are periodic because any connected closed $1$-dimensional manifold is a circle.  
%
We define isolated property as follows. 

\begin{definition}
A singular point $x$ is {\bf isolated} if there is an open \nbd $U$ of $x$ with $U \cap \mathop{\mathrm{Sing}}(\F) = \{ x \}$. 
Then $U$ is called an isolated \nbd of $x$. 
\end{definition}


%\begin{definition} 
%A singular point is {\bf isolated} if there is a neighborhood of it that intersects no singular points except itself.
%\end{definition} 

%A singular leaf is {\bf isolated} if there is its neighborhood which intersects no singular leaves except it.

%Moreover, a leaf is {\bf periodic} if it is homeomorphic to a circle. 

\subsubsection{The complement of the singular leaf set}

