The index of a $k$-prong 
%outside of the boundary $\partial S$
 is $-(k -2)/2$. 
%\\
%{\rm(2)} The index of a $k$-prong on the boundary $\partial S$ is $-(k -1)/2$. 
\end{lemma}

Denote by $\bm{\mathop{\mathrm{Sing}}_{-}(\F)}$ the set of singular points whose indices are negative.

\subsubsection{Indices of disks}\label{sec:index_disk}

We define the index of a disk with respect to a line field as follows. 

\begin{definition}
Let $D$ be a disk whose boundary is transverse to a line field $\F$ except finitely many tangencies. 
Then the {\bf index} $\mathop{\mathrm{ind}_{\F}} (D)$ of $D$ of the line field is determined by $(2 + n_{\mathrm{in}} - n_{\mathrm{out}})/2$, where $n_{\mathrm{in}}$ (resp. $n_{\mathrm{out}}$) is the number of inner (resp. outer) tangencies of the loop $\partial D$ which is transverse at all but finitely many points. 
\end{definition}

\begin{definition}
Let $D$ be a disk and $C \subset \partial D \cap \partial M$ a nonempty open arc such that $\partial D - C$ is transverse to a line field $\F$ except finitely many tangencies in $\mathop{\mathrm{int}}M$. 
%
The {\bf index} $\mathop{\mathrm{ind}_{\F}} (D, C)$ of the disk $D$ and the arc $C$ is half of the index of $\widetilde{D}$ of $\widetilde{\F}$, where $\widetilde{D}$ is the lift of $D$ to the double $\widetilde{M}$ of $M$ and $\widetilde{\F}$ is the lift of the line field $\F$ to $\widetilde{M}$. 
\end{definition}

Notice that the boundary $\partial \widetilde{D}$ in the previous definition is transverse to the line field $\F$ except finitely many tangencies. 










\subsubsection{Separatrices of singular points}\label{sec:separatrix}

As a flow case, we define some kinds of separatrices as follows. 

\begin{definition}
A regular leaf is {\bf separatrix} if one of the connected components of the boundary of the leaf is a singular point. 
\end{definition}

\begin{definition}
A separatrix $L$ is a {\bf semi-prong separatrix} if one of the connected components of the difference $\overline{L} - L$ is a prong. 
\end{definition}

\begin{definition}
A separatrix $L$ is a {\bf prong separatrix} if the difference $\overline{L} - L$ consists of prongs. 
\end{definition}

The union of prongs and semi-prong separatrices is called the {\bf prong connection diagram}. 
A connected component of the prong connection diagram is called a {\bf prong connection}. 
Notice that the prong connection diagram and prong connections are analogous to the multi-saddle connection diagram and multi-saddle connections, respectively. 

\subsubsection{Orientability and transverse orientability for regular foliations on surfaces}

To define local orientability for prongs, recall the orientability of regular foliations as follows. 

\begin{definition}[cf. Definition~2.3.1(i) in \cite{HH1986A}]
A regular foliation on a surface is {\bf transversely orientable} if there is a foliated atlas whose restrictions of transition maps to the transverse directions are orientation-preserving. 
\end{definition}

\begin{definition}[cf. Definition~2.3.1(ii) in \cite{HH1986A}]
A regular foliation on a surface is {\bf (leafwise) orientable} if there is a foliated atlas whose restrictions of transition maps to the tangential directions are orientation-preserving. 
% (cf. \cite[Definition~2.3.1(ii)]{HH1986A}). 
\end{definition}

Note that a $C^q$ regular foliation is leafwise (resp. transverse) orientable if and only if the tangent (resp. normal) bundle of the foliation is orientable. 
%
It is known that a regular foliation on a surface is orientable if and only if there is a flow on the surface whose set of orbits is the foliation (cf. \cite[Remark~2.3.2]{HH1986A}). 
Moreover, if the base surface of an orientable regular foliation is compact, then the flow is topologically equivalent to a $C^1$-foliation defined by Gutierrez's smoothing theorem~\cite{gutierrez1978structural}.



\subsubsection{Tangential orientable covering of a singular foliation on a surface}

Let $\F$ be a singular foliation on a surface $M$ with finitely many singular points and $\F_{\mathrm{reg}}$ the regular foliation on a surface $M_{\mathrm{reg}} = M - \mathop{\mathrm{Sing}}(\F)$. 
We define the tangent orientation branched covering $\pi \colon M^* \to M$ of $M$ with respect to $\F$ and the tangent orientation lift of $\F$ as follows.

As \cite[\S~2.3.5]{HH1986A}, we define a germ of the tangential orientation of the regular foliation $\F_{\mathrm{reg}}$ as follows. 

\begin{definition}
For any point $p \in M_{\mathrm{reg}}$, define an equivalence relation $\sim$ for fibered charts around $p$ as follows: 
Two fibered charts around $p$ are equivalent if the transition map locally preserves the orientations of the plaques of $\F$. 

Then each equivalent class is called a {\bf germ of the tangential orientation of $\bm{\F_{\mathrm{reg}}}$ at $\bm{p}$}. 
\end{definition}

Note that any fibered chart $(U,\varphi)$ of $\F_{\mathrm{reg}}$ determines exactly one germ $U^{\varphi,p,*}$ of the tangential orientation of $\F_{\mathrm{reg}}$ at a point $p \in U$. 
Notice that $\{ U^{\varphi,p,*} \mid p \in U \}$ is canonically homeomorphic to $U$. 
Moreover, for an nonempty open subset $U \in M_{\mathrm{reg}}$, the family $U^* := \{ U^{\varphi,p,*} \mid (U,\varphi) : \text{ fibered chart}, p \in U \}$ is the set of germs at points in $U$. 

For any foliated atlas $\{ (U_\lambda,\varphi_\lambda)\}_{\lambda \in \Lambda}$ of $\F_{\mathrm{reg}}$, the set $\{ U^*_\lambda \}_{\lambda \in \Lambda}$ form a basis for a topology on the set  $M_{\mathrm{reg}}^* := \bigcup_{\lambda \in \Lambda} U^*_\lambda$ of germs of the tangential orientation of $\F_{\mathrm{reg}}$. 
By construction, we have the following observation.

\begin{lemma}
The map $\pi \colon M_{\mathrm{reg}}^* \to M_{\mathrm{reg}}$, assigning to a germ of the tangential orientation of $\F_{\mathrm{reg}}$ at $p \in M - \mathop{\mathrm{Sing}}(\F)$ the point $p$, is a $2$-fold covering, called the {\bf tangent orientation branched covering} of $M_{\mathrm{reg}}$ with respect to $\F_{\mathrm{reg}}$. 
\end{lemma}

By \cite[Proposition~2.3.6]{HH1986A}, the lift $\F_{\mathrm{reg}}^*$ of $\F_{\mathrm{reg}}$ to the surface $M_{\mathrm{reg}}^*$ is a tangential orientable foliation. 
By definition of $M_{\mathrm{reg}}$ and by construction of the $2$-fold covering $\pi \colon M_{\mathrm{reg}}^* \to M_{\mathrm{reg}}$, adding finitely many points to $M_{\mathrm{reg}}^*$, we can extend $\pi$ to a map $\pi \colon M^* \to M$ from the resulting surface $M^*$. 
By construction, we have the following observations.

\begin{lemma}
The map $\pi \colon M^* \to M$ is the double covering of $M$ with ramification points contained in $\mathop{\mathrm{Sing}}(\F)$, called the {\bf tangent orientation branched covering} of $M$ with respect to $\F$. 
\end{lemma}

\begin{lemma}
The resulting decomposition on $M^*$ from $\F_{\mathrm{reg}}^*$ adding finitely many singular points is a singular foliation, denoted by $\bm{\F^*}$ and called the {\bf tangent orientation lift} of $\F$, such that the branched covering $\pi \colon M^* \to M$ maps leaves of $\F^*$ to leaves of $\F$.
%The lift of $\F$ to the branched covering $M^*$ is denoted by $\bm{\F^*}$ and called the {\bf tangent orientation lift} of $\F$. 
\end{lemma}

