Then any singular foliation with singular points on a surface is not structurally stable in $\mathcal{F}^q(M)$ with respect to the topology $\mathcal{O}^p_{w,\F^q(M)}$. 
\end{lemma}

\begin{proof}
Let $\F$ be a singular foliation with singular points on a surface $M$. 
Lemma~\ref{lem:no_sing_leaf_int-} implies that we may assume that $\mathrm{int}(\mathop{\mathrm{Sing}}(\mathcal{\F})) = \emptyset$. 
Fix any distance weight $w \colon [0,\infty] \to [0,1]$ and any positive number $\varepsilon >0$. 

\begin{claim}\label{claim:07}
There is a singular foliation $\G$ with $D^p_{w}(\F, \mathcal{G}) < \varepsilon$ and $\mathrm{int}(\mathop{\mathrm{Sing}}(\mathcal{\mathcal{G}})) \neq \emptyset$. 
\end{claim}

\begin{proof}[Proof of Claim~\ref{claim:07}]
By Lemma~\ref{lem:singular_pt_nbd02}, there is a positive number $\delta > 0$ satisfying the following inequality for any singular foliation $\G_1$ on $M$ with $B(\mathop{\mathrm{Sing}}(\F),\delta) \subseteq \mathop{\mathrm{Sing}}(\G_1)$ and for any singular foliation $\G_2$ on $M$:
\[
\sup_{x \in B(\mathop{\mathrm{Sing}}(\F),\delta)}d_H(X_{w,\F}(x), X_{w,\G_1}(x)) < \varepsilon/2
\]
\[
\sup_{x \in B(\mathop{\mathrm{Sing}}(\F),\delta)}d_H(X_{w,\G_2}(x), X_{w,\G_1}(x)) < \varepsilon/2
\]
Therefore, we have 
\[
\sup_{x \in B(\mathop{\mathrm{Sing}}(\F),\delta)}d_H(X_{w,\F}(x), X_{w,\G}(x)) < \varepsilon
\]
for any singular foliation $\G$ on $M$. 
Taking $\delta >0$ small if necessary,  by the uniform continuity of $w$, we may assume that $\vert w(r_1) - w(r_2) \vert < \varepsilon$ for any $r_1, r_2 \in [0,\infty)$ with $\vert r_1 - r_2 \vert \leq \delta$. 
Choose a singular foliation $\G$ on $M$ with 
\[
B(\mathop{\mathrm{Sing}}(\F),\delta/2) \subseteq \mathop{\mathrm{Sing}}(\G) \subset B(\mathop{\mathrm{Sing}}(\F), \delta)
\]
and $X_\F \vert_{M - B(\mathop{\mathrm{Sing}}(\F),\delta)} = X_\mathcal{G}\vert_{M - B(\mathop{\mathrm{Sing}}(\F),\delta)}$. 
Then 
\[
\sup_{x \in B(M - \mathop{\mathrm{Sing}}(\F),\delta))} (d_g(x, \mathop{\mathrm{Sing}}(\F)) - d_g(x, \mathop{\mathrm{Sing}}(\G))) \in [\delta/2,\delta]
\]
and 
$\mathrm{int}(\mathop{\mathrm{Sing}}(\mathcal{\mathcal{G}})) \neq \emptyset$. 
The equality $X_\F \vert_{M - B(\mathop{\mathrm{Sing}}(\F),\delta)} = X_\mathcal{G}\vert_{M - B(\mathop{\mathrm{Sing}}(\F),\delta)}$ implies the following inequality: 
\[
\begin{split}
& \sup_{x \in B(M - \mathop{\mathrm{Sing}}(\F),\delta))} d_H(X_{w,\F}(x), X_{w,\G}(x))
\\
= & \sup_{x \in B(M - \mathop{\mathrm{Sing}}(\F),\delta))} (\rho_{w,\F}(x) - \rho_{w,\G}(x))
\\
= & \sup_{x \in B(M - \mathop{\mathrm{Sing}}(\F),\delta))} (w(d_g(x, \mathop{\mathrm{Sing}}(\F))) - w(d_g(x, \mathop{\mathrm{Sing}}(\G))))
\\ < & \varepsilon
\end{split}
\]
This implies $D^\infty_{w}(\F, \mathcal{G}) < \varepsilon$. 
On the other hand, 
\[
\begin{split}
&D^p_{w}(\F, \mathcal{G})\\ 
%=& \left(\dfrac{1}{\mathrm{vol}_g(M)}  \int_M d_H(X_{w,\F}(x), X_{w,\G}(x))^p d \mathrm{vol}_g \right)^{1/p}\\
=& \left(\dfrac{1}{\mathrm{vol}_g(M)}  \int_{B(\mathop{\mathrm{Sing}}(\F),\delta)} d_H(X_{w,\F}(x), X_{w,\G}(x))^p d \mathrm{vol}_g \right)^{1/p}\\
< & \left(\dfrac{1}{\mathrm{vol}_g(M)}  \int_{B(\mathop{\mathrm{Sing}}(\F),\delta)} \varepsilon^p d \mathrm{vol}_g \right)^{1/p} = \varepsilon \left(\dfrac{\mathrm{vol}_g(B(\mathop{\mathrm{Sing}}(\F),\delta))}{\mathrm{vol}_g(M)}\right)^{1/p} \leq \varepsilon
\end{split}
\]
if $p < \infty$. 
\end{proof}

By $\mathrm{int}(\mathop{\mathrm{Sing}}(\mathcal{\mathcal{G}})) \neq \emptyset$ and $\mathrm{int}(\mathop{\mathrm{Sing}}(\mathcal{\F})) = \emptyset$, the singular foliations $\mathcal{G}$ and $\F$ are not topologically equivalent. 
This means that $\mathcal{F}$ is not structurally stable in $\mathcal{F}^q(M)$ with respect to the topology $\mathcal{O}^p_{w,\F^q(M)}$ for any $p \in \R_{\geq 1} \sqcup \{ \infty \}$. 
\end{proof}

\begin{lemma}\label{lem:limit_cycle}
The boundary of any connected component of the interior $\mathrm{int} (\mathop{\mathrm{Per}}(\mathcal{\F}))$ of the union of periodic leaves of a regular foliation $\F$ on a closed surface consists of periodic leaves. 
\end{lemma}

\begin{proof}
Let $C$ be a connected component of the interior $\mathrm{int} (\mathop{\mathrm{Per}}(\mathcal{\F}))$ of the union of periodic leaves of a regular foliation $\F$ on a closed surface $M$. 
Take a boundary component $\partial_C \subseteq \partial C$ of $C$. 

It suffices to show that $\partial_C$ is a periodic leaf. 
%
Indeed, by the existence of fibered charts, the compactness of $C$ implies that there are finitely many fibered charts $U_1, \ldots , U_k$ centered at points in $C$ such that $C \subset \bigcup_{i=1}^k U_i$. 
By the compactness of $C$, there is an invariant periodic annulus $A \subseteq C \cap \bigcup_{i=1}^k U_i$ such that $\partial_C$ is a boundary component of $A$.  
Then the intersections $A \cap U_i$ consist of closed leaf arcs. 
Fix a transverse closed arc $T \subset \partial_C \sqcup A \subseteq \overline{A}$. 
% which intersects a point in $C$. 
Then the first return map on the interval $T \cap A = T \setminus \partial_C$ with any direction is identical. 
By the existence of fibered charts that cover $C$, the boundary component $\partial_C$ is a finite union of closed leaf arcs. 
From the existence of the identical first return map on the interval $T \cap A$, the finite union $\partial_C$ is a loop, which is a periodic leaf.  
\end{proof}

