\subsubsection{Weight for non-periodic leaves}

%A non-decreasing continuous function $w \colon [0,\infty] \to [0,1]$ is a {\bf distance weight} if $w^{-1}(0) = \{ 0 \}$ and $w(\infty) = 1$. 
We define the weight for non-periodic leaves.

\begin{definition}
For a distance weight $W \colon [0,\infty] \to [0,1]$, 
% and a singular foliation $\F$, 
the {\bf weight} $\bm{\sigma_{W}} \colon M \times \mathcal{L}(M) \to [0,1]$ with respect to $W$ and $\mathop{\mathrm{Per}}(\F)$ is defined by 
\[
\sigma_{W}(x, \F) := W(d_g(x, M - \mathop{\mathrm{Per}}(\F)))
\]
\end{definition}

Put $\sigma_{W,\F} := \sigma_{W}(\cdot, \F) \colon M \to [0,1]$. 
%Note that $\rho_{w}(\cdot, \F) \equiv 1$ for any regular foliation $\F$ and any distance weight $w$. 
%
For the weight $\sigma_{W,\F} \colon M \to [0,1]$ with respect to a distance weight $W \colon [0,\infty] \to [0,1]$ and $\F$, put 
\[
X_{W_{\mathrm{per}},\F_-}(x) :=  \sigma_{W,\F}(x)X_{\F_-}(x)
\hspace{20pt}
X_{W_{\mathrm{per}},\F_+}(x) :=  \sigma_{W,\F}(x)X_{\F_+}(x)
\]
for any $x \in M$. 
We define the continuous associated directed field of $\F$ with respect to the weight $\sigma_{W,\F} \colon M \to [0,1]$ as follows. 

\begin{definition}
Define the {\bf continous associated directed field} $X_{W_{\mathrm{per}},\F} \colon M \to TM_\pm$ of $\F$ with respect to the weight $\sigma_{W,\F} \colon M \to [0,1]$ by 
\[
\begin{split}
X_{W_{\mathrm{per}},\F}(x) := \sigma_{W,\F}(x) X_{\F}(x) &= [0_x, \sigma_{W,\F}(x)X_{\F_-}(x)] \cup [0_x, \sigma_{W,\F}(x)X_{\F_+}(x)]
\\
&= [0_x, X_{W_{\mathrm{per}},\F_-}(x)] \cup [0_x, X_{w,\F_+}(x)]
\end{split}
\]
for any $x \in M$.
\end{definition}

Notice the continous associated directed field $X_{W_{\mathrm{per}},\F} \colon M \to TM_\pm$ of the levelable foliation $\F$ is $\{ \{ X_{W_{\mathrm{per}},\F_-}(x), X_{W_{\mathrm{per}},\F_+}(x) \} \mid x \in M \}$, which consists of two/one-point sets, such that $X_{W_{\mathrm{per}},\F}\vert_{M - \mathop{\mathrm{Per}}(\F)} \equiv \{ 0 \}$. 


\subsubsection{Distance between singular foliations and their topology}

Fix a distance weight $w,W \colon [0,\infty] \to [0,1]$. 
%For any $r \in \R_{> 0}$, 

\begin{definition}
Define the wighted metric $\bm{D_{W_{\mathrm{per}}}}$, called the {\bf locally wighted levelable Hausdorff superior distance} for periodic leaves on the set $\mathcal{L}(M)$ of singular foliations on a  manifold $M$ for an ordered field $[0, \infty]$: 
\[
\begin{split}
\bm{D_{W_{\mathrm{per}}}(\F, \mathcal{G})} = D^{\infty}_{W_{\mathrm{per}}}(\F, \mathcal{G}) &:= \sup_{x \in M} d_H(X_{W_{\mathrm{per}},\F}(x), X_{W_{\mathrm{per}},\G}(x))
\end{split}
\]
where $d_H$ is the Hausdorff distance on $M$ with respect to the distance $d$. 
\end{definition}


We define the following distance. 

\begin{definition}
Define the wighted metric $\bm{D_{w,W}}$, called the {\bf locally wighted levelable Hausdorff superior distance} on the set $\mathcal{L}(M)$ of singular foliations on a  manifold $M$: 
\[
\begin{split}
\bm{D_{w,W}(\F, \mathcal{G})} = D^{\infty}_{w,W}(\F, \mathcal{G}) &:= D(\F, \mathcal{G}) + D_{W_{\mathrm{per}}}(\F, \mathcal{G})
\end{split}
\]
\end{definition}

Similarly, we define the following distance. 

\begin{definition}
For any $p \in \R_{\geq 1}$, any $r \in \R_{> 0}$, and any $\delta \in \R_{> 0}$ and a regular foliation $\F$ on a  manifold $M$, define the wighted metrics $\bm{D^{p}_{W_{\mathrm{per}}}}$ and $\bm{D^{p}_{w,W}}$, which is called the {\bf locally wighted levelable Hausdorff $L^p$-distance}, on the set $\mathcal{L}(M)$ of singular foliations on a  manifold $M$ for an ordered field $[0, \infty]$: 
\[
\begin{split}
\bm{D^{p}_{W_{\mathrm{per}}}(\F, \mathcal{G})} := & \left(\dfrac{1}{\mathrm{vol}_g(M)}  \int_M (d^+_{w,W}(\F, \mathcal{G})(x))^p d \mathrm{vol}_g \right)^{1/p}
\end{split}
\]
\[
\begin{split}
\bm{D^{p}_{w,W}(\F, \mathcal{G})} := & D^p_{w}(\F, \mathcal{G}) + D^{p}_{W_{\mathrm{per}}}(\F, \mathcal{G})
\end{split}
\]
\end{definition}

\subsubsection{Open $\delta$-balls for levelable singular foliations on manifolds and their topology}
Fix distance weights $w, W \colon [0,\infty] \to [0,1]$. 

\begin{definition}
For any $p \in \R_{\geq 1} \sqcup \{ \infty \}$, any $\delta \in \R_{> 0}$, and a levelable singular foliation $\F$ on the manifold $M$, define the {\bf open $\delta$-ball} $\bm{B_{D^{p}_{w,W}}(\F,\delta)}$ centered at $\F$ with respect to $(w, W)$ as follows:  
\[
B_{D^{p}_{w,W}}(\F,\delta) := \{ \mathcal{G} \in \mathcal{L}(M) \mid D^{p}_{w,W}(\F, \mathcal{G}) < \delta \}
\]
\end{definition}


%
By definitions, we have $B_{D^{p}_{w,W}}(\F,\delta) \subseteq B_{D^{p}_{W_{\mathrm{per}}}}(\F,\delta)$. 
Moreover, we set the following notation. 

\begin{definition}
Define the set $\mathcal{B}^{p}_{w,W,\mathcal{L}(M)}$ of open balls with respect to the distance weights $(w, W)$ as follows: 
\[
\mathcal{B}^{p}_{w,W,\mathcal{L}(M)} := \{ B_{D^{p}_{w,W}}(\F,\delta) \mid \delta \in \R_{> 0}, \F \in \mathcal{L}(M) \}
\]
\end{definition}

\subsubsection{Topologies for levelable singular foliations on surfaces}


\begin{definition}\label{dec:levelable_top}
For any $p \in \R_{\geq 1} \sqcup \{ \infty \}$ and any distance weight $w, W \colon [0,\infty] \to [0,1]$, the smallest topology on $\mathcal{L}(M)$ which contains the set $\mathcal{B}^{p}_{w,W,\mathcal{L}(M)} $ of open balls  with respect to $w$ is called the {\bf topology induced by the local Hausdorff distance} with respect to $w$ and $W$, and is denoted by $\mathcal{O}^p_{w,W,\mathcal{L}(M)}$. 
\end{definition}


Then the set $\mathcal{B}^{p}_{w,W,\mathcal{L}(M)} $ is a subbase of the topology $\mathcal{O}^p_{w,W,\mathcal{L}(M)}$. 
