\section{Generic coheight-zero levelable foliationswith finitely many pronged singular points on surfaces}


Let $\F$ be a levelable foliation with finitely many pronged singular points on a surface $M$.  

Recall that a {\bf bouquet} of $k$ circles for any $k \in \Z_{\geq 0}$ is a topological graph that consists of one vertex and $k$ loops. 
We have the following observation.

\begin{lemma}\label{lem:betti}
The first betti number $b_1(G)$ of a connected finite graph $G = (V,E)$ is $1 - \vert V \vert + \vert E \vert$.   
\end{lemma}

\subsection{Coheight of levelable foliations}

To define the coheight of levelable foliations, we define coheights with respect to heteroclinic separatrices and with respect to the degeneracy of singular points. 


\subsubsection{Coheights of prong connections of levelable foliations}

We have the following observation. 

\begin{lemma}
Let 
%$\F$ be a levelable foliation with finitely many pronged singular points on a surface $M$ and 
$D(\F)$ be the prong connection diagram.  
Then $D(\F)$ is a topological graph whose degrees of vertices are one or three such that every connected component $C$ of $D(\F)$ is homotopic to a bouquet of $b_1(C)$ circles such that $b_1(C) = 1 - n_{V}(C) + n_{E}(C)$, where $n_{V}(C)$ is the number of prongs in $C$ and $n_{E}(C)$ is the number of prong separatrices in $C$. 
% for some $k \in \Z_{\geq 0}$. 
\end{lemma}
%Then we call such $k$ the number of holes of prong connections. 


We define coheights with respect to heteroclinic separatrices as follows. 

\begin{definition}
Define the {\bf coheight} $\bm{\mathrm{coheight}_{\mathrm{h},\F}(C)}$ of a prong connection $C$ with respect to heteroclinic separatrices as follows: 
\[
\mathop{\mathrm{coheight}_{\mathrm{h},\F}}(C) := n_{V_-}(C) - b_1(C)
\]
where $n_{V_-}(C) := \vert \mathop{\mathrm{Sing}_{-}}(\F) \cap C \vert$ is the number of prongs in $C$ whose indices are negative. 
\end{definition}

\begin{definition}
The {\bf coheight} $\bm{\mathrm{coheight}_{\mathrm{h}}(\F)}$ of $\F$ with respect to heteroclinic separatrices is defined as follows: 
\[
\begin{split}
\mathrm{coheight}_{\mathrm{h}}(\F) := \, &  \sum_{C:\text{prong connection}} \hspace{-5pt} \mathop{\mathrm{coheight}_{\mathrm{h},\F}}(C) 
\\
= \, &  n_{V_-}(\F)  - b_1(D(\F))
\\
= \, & n_{V_-}(\F) +  n_{V}(\F) - n_{E}(\F) -n_{CC}(\F) 
\end{split}
\]
where $n_{V_-}(\F) := \vert \mathop{\mathrm{Sing}_{-}}(\F) \vert$ is the number of prongs of $\F$ whose indices are negative, $n_{V}(\F) := \vert \mathop{\mathrm{Sing}}(\F) \vert$ is the number of prongs of $\F$, $n_{E}(\F)$ is the number of prong separatrices of $\F$, and $n_{CC}(\F)$ is the number of connected components of the prong connection diagram $D(\F)$ 
\end{definition}

\subsubsection{Coheights of singular points of levelable foliations}

We define coheights with respect to the degeneracy of singular points as follows. 

\begin{definition}
The {\bf coheight} $\bm{\mathrm{coheight}_{\mathrm{p},\F}(y)}$ of a center $y$ with respect to degeneracy of singular points is one. 
\end{definition}

\begin{definition}
The {\bf coheight} $\bm{\mathrm{coheight}_{\mathrm{p},\F}(y)}$ of a fake prong $y$ outside of the boundary with respect to the degeneracy of singular points is zero. 
\end{definition}

\begin{definition}
The {\bf coheight} $\bm{\mathrm{coheight}_{\mathrm{p},\F}(y)}$ of a $1$-prong $y$ with respect to degeneracy of singular points is zero. 
\end{definition}

\begin{definition}
The {\bf coheight} of $k$-prong $y$ ($k \geq 3$) outside of the boundary with respect to degeneracy of singular points is $\bm{\mathrm{coheight}_{\mathrm{p},\F}(y)} := 2(k-3) = -2(1 + 2 \mathop{\mathrm{ind}_{\F}}(y)) \geq 0$, because $\mathop{\mathrm{ind}_{\F}}(y) = -(k-2)/2$.
\end{definition}

\begin{definition}
The {\bf coheight} $\bm{\mathrm{coheight}_{\mathrm{p},\F}(y)}$ of a fake prong $y$ on the boundary with respect to the degeneracy of singular points is two. 
\end{definition}

\begin{definition}
The {\bf coheight} of $k$-prong $y$ ($k \geq 3$) on the boundary with respect to degeneracy of singular points is $\bm{\mathrm{coheight}_{\mathrm{p},\F}(y)} := 2(k-3) = -2(1 + 2 \mathop{\mathrm{ind}_{\F}}(y)) \geq 0$. 
\end{definition}

\begin{definition}
The {\bf coheight} $\bm{\mathrm{coheight}_{\mathrm{p,\F}}(C)}$ of a prong connection $C$ of $\F$ with respect to degeneracy of singular points is defined as follows: 
\[
\begin{split}
\mathrm{coheight}_{\mathrm{p,\F}}(C) := & \sum_{y \in \mathop{\mathrm{Sing}}(\F) \cap C} \mathrm{coheight}_{\mathrm{p},\F}(y)
\end{split}
\]
\end{definition}

\begin{definition}
The {\bf coheight} $\bm{\mathrm{coheight}_{\mathrm{p}}(\F)}$ of $\F$ with respect to degeneracy of singular points is defined as follows: 
\[
\begin{split}
\mathrm{coheight}_{\mathrm{p}}(\F) := & \sum_{y \in \mathop{\mathrm{Sing}}(\F)} \mathrm{coheight}_{\mathrm{p},\F}(y)
\end{split}
\]
\end{definition}

Notice that $\mathrm{coheight}_{\mathrm{p,\F}}$ is non-negative for any of a prong, a prong connection, or a line field. 

\subsubsection{Coheights of prong connections of levelable foliations}

We define coheights of prong connections of levelable foliations as follows. 

\begin{definition}
The {\bf coheight} $\bm{\mathrm{coheight}_{\F}(C)}$ of a prong connection $C$ of $\F$ 
%a levelable foliation $\F$ with finitely many pronged singular points on a surface $M$ 
is defined as follows: 
\[
\begin{split}
& \mathrm{coheight}_{\F}(C) \\
:= \, &  n_{\partial}(C) + n_{\mathrm{fake}}(C) + \mathop{\mathrm{coheight}_{\mathrm{h},\F}}(C) +  \mathrm{coheight}_{\mathrm{p,\F}}(C)
\\
= \, & n_{\partial}(C) + n_{\mathrm{fake}}(C) + n_{V_-}(C)  - b_1(C) + \sum_{y \in \mathop{\mathrm{Sing}}(\F) \cap C} \mathrm{coheight}_{\mathrm{p},\F}(y)
\\
= \, & n_{\partial}(C) + n_{\mathrm{fake}}(C) + n_{V_-}(C)  +  n_{V}(C) - n_{E}(C) -1 + \sum_{y \in \mathop{\mathrm{Sing}}(\F) \cap C} \mathrm{coheight}_{\mathrm{p},\F}(y)
\\
= \, & n_{\partial}(C) + n_{\mathrm{fake}}(C) + n_{V_-}(C)  - n_{E}(C) -1 + \sum_{y \in \mathop{\mathrm{Sing}}(\F) \cap C} (1 + \mathrm{coheight}_{\mathrm{p},\F}(y))
\end{split}
\]
where $n_{\partial}(C)$ is the number of boundary components of $M$ intersecting $C$, and $n_{\mathrm{fake}}(C)$ is the number of fake prongs in $C$. 
\end{definition}

\subsubsection{Coheights of levelable foliations}

We define coheights of levelable foliations as follows. 

\begin{definition}
The {\bf coheight} $\bm{\mathrm{coheight}(\F)}$ of $\F$ 
%of a levelable foliation $\F$ with finitely many pronged singular points on a surface $M$ 
is defined as follows: 
\[
\begin{split}
& \mathrm{coheight}(\F)\\
 :=  & \sum_{C:\text{prong connection}} \mathrm{coheight}_{\F}(C) 
\\
 =  \, & n_{\partial}(\F) + n_{\mathrm{fake}}(\F) +  \mathop{\mathrm{coheight}_{\mathrm{h}}}(\F) + \mathrm{coheight}_{\mathrm{p}}(\F)
\\
% :=  & n_{\mathrm{fake}}(\F) + \sum_{C:\text{prong connection}} \mathop{\mathrm{coheight}_{\mathrm{h},\F}}(C) + \sum_{y \in \mathop{\mathrm{Sing}}(\F)} \mathrm{coheight}_{\mathrm{p},\F}(y)
%\\
= \, & n_{\partial}(\F) + n_{\mathrm{fake}}(\F) + n_{V_-}(\F) - b_1(D(\F)) + \sum_{y \in \mathop{\mathrm{Sing}}(\F)} \mathrm{coheight}_{\mathrm{p},\F}(y)
%\\
%= & \vert \mathop{\mathrm{Sing}_{-}}(\F) \vert + n_{\mathrm{fake}}(\F) - \sum_{C:\text{prong connection}} b_1(C) + \sum_{y \in \mathop{\mathrm{Sing}}(\F)} \mathrm{coheight}_{\mathrm{p},\F}(y)
\\
= \, & n_{\partial}(\F) + n_{\mathrm{fake}}(\F) + n_{V_-}(\F) +  n_{V}(\F) - n_{E}(\F) -n_{CC}(\F) + \sum_{y \in \mathop{\mathrm{Sing}}(\F)} \hspace{-7pt} \mathrm{coheight}_{\mathrm{p},\F}(y)
\\
= \, & n_{\partial}(\F) + n_{\mathrm{fake}}(\F) + n_{V_-}(\F) - n_{E}(\F) -n_{CC}(\F) + \sum_{y \in \mathop{\mathrm{Sing}}(\F)} (1 + \mathrm{coheight}_{\mathrm{p},\F}(y))
\end{split}
\]
where $n_{\partial}(\F)$ is the number of boundary components of $M$ intersecting the prong connection diagram $D(\F)$ and $n_{\mathrm{fake}}(\F)$ is the number of fake prongs of $\F$. 
\end{definition}

