\subsubsection{Properties of $\mathop{\mathrm{coheight}_{\mathrm{h},\F}}$ and $\mathop{\mathrm{coheight}_{\mathrm{h},\F}} + \mathop{\mathrm{coheight}_{\mathrm{p},\F}}$}

We have the following positivities. 

\begin{lemma}
For a prong connection $C$ each of whose prongs is either a $1$-prong and a $3$-prong, we have $\mathop{\mathrm{coheight}_{\mathrm{h},\F}}(C) \geq 0$. 
\end{lemma}

\begin{proof}
Fix any prong connection $C$ each of whose prongs is either a $1$-prong or a $3$-prong. 
Then $C$ contains at least two prongs. 
Since any prong in $C$ is either a $1$-prong and a $3$-prong, we have $n_{E}(C) = (n_{V_+}(C) + 3n_{V_-}(C))/2 = n_{V}(C)/2 + n_{V_2}(C)$. 
Lemma~\ref{lem:betti} implies that 
\[
\begin{split}
b_1(C) &= 1 - n_{V}(C) + n_{E}(C) 
\\
&= 1 - n_{V}(C) + n_{V}(C)/2 + n_{V_-}(C) = 1 - n_{V}(C)/2 + n_{V_-}(C)
\end{split}
\]
where $n_{V}(C)$ is the number of prongs in $C$ and $n_{E}(C)$ is the number of prong separatrices in $C$. 
By definition of the coheight $\mathop{\mathrm{coheight}_{\mathrm{h},\F}}$, we obtain the following equality: 
\[
\begin{split}
\mathop{\mathrm{coheight}_{\mathrm{h},\F}}(C) &= n_{V_-}(C) - b_1(C) 
\\
&= n_{V_-}(C) - \left(1 - \dfrac{n_{V}(C)}{2} + n_{V_-}(C) \right) = \dfrac{n_{V}(C)}{2} - 1
\end{split}
\]
Since $C$ contains at least two prongs, we have $\mathop{\mathrm{coheight}_{\mathrm{h},\F}}(C) = n_{V}(C)/2 - 1 \geq 0$. 
\end{proof}

\begin{lemma}\label{lem:1_3_prongs}
For a prong connection $C$, we have 
\[
\mathop{\mathrm{coheight}_{\mathrm{h},\F}}(C) + \mathop{\mathrm{coheight}_{\mathrm{p},\F}}(C) \geq n_0(C) +  \sum_{k \geq 3} (k-3) n_k(C) \geq 0
\]
where $n_k(C)$ is the number of $k$-prongs in $C$ for any $k \in \Z_{\geq 0}$. 
Moreover, if $C$ has no centers, then there is a prong connection $C'$ with $n_{\partial}(C) = n_{\partial}(C')$ and $n_{\mathrm{fake}}(C) = n_{\mathrm{fake}}(C')$ and 
\[
n_V(C') - n_V(C) = n_{V_-}(C') - n_{V_-}(C) = \sum_{k \geq 3} (k-3) n_k(C)
\]
such that 
\[
\begin{split}
\mathop{\mathrm{coheight}_{\mathrm{h},\F}}(C) + \mathop{\mathrm{coheight}_{\mathrm{p},\F}}(C) =  \mathop{\mathrm{coheight}_{\mathrm{h},\F}}(C') &+ \mathop{\mathrm{coheight}_{\mathrm{p},\F}}(C') 
\\
& + \sum_{k \geq 3} (k-3) n_k(C)
\end{split}
\]
where $n_{\partial}(C)$ is the number of boundary components of the surface $M$ intersecting $C$, and $n_{\mathrm{fake}}(C)$ is the number of fake prongs in $C$. 
\end{lemma}

\begin{proof}
If the prong connection $C$ consists of one center, then $\mathop{\mathrm{coheight}_{\mathrm{h},\F}}(C) = 0 - 0 =0$ and $\mathop{\mathrm{coheight}_{\mathrm{p},\F}}(C) = 1$, which implies the assertion. 
%
Thus we may assume that $C$ consists of non-central (i.e. non-zero) prongs. 
Applying the Whitehead moves to $k$-prongs for any $k >0$, we can deform $C$ into a prong connection $C'$ which is homotopy equivalent to $C$ and each of whose prongs is either a $1$-prong and a $3$-prong such that $n_{\partial}(C) = n_{\partial}(C')$ and $n_{\mathrm{fake}}(C) = n_{\mathrm{fake}}(C')$.
Then $b_1(C) = b_1(C')$. 
Put $l := \sum_{k \geq 3} (k-3) n_k(C) = n_{V_-}(C') - n_{V_-}(C) \geq 0$.  
Therefore, we have $\mathop{\mathrm{coheight}_{\mathrm{h},\F}}(C) - \mathop{\mathrm{coheight}_{\mathrm{h},\F}}(C') = (n_{V_-}(C) - b_1(C)) - (n_{V_-}(C') - b_1(C')) = -l$.  
%
By definition of $\mathop{\mathrm{coheight}_{\mathrm{p},\F}}$, we obtain $\mathop{\mathrm{coheight}_{\mathrm{p},\F}}(C) - \mathop{\mathrm{coheight}_{\mathrm{p},\F}}(C') = 2l$.   
From Lemma~\ref{lem:1_3_prongs}, we have $\mathop{\mathrm{coheight}_{\mathrm{h},\F}}(C') \geq 0$. 
Therefore, we have the following inequality: 
\[
\begin{split}
\mathop{\mathrm{coheight}_{\mathrm{h},\F}}(C) + \mathop{\mathrm{coheight}_{\mathrm{p},\F}}(C) &= \mathop{\mathrm{coheight}_{\mathrm{h},\F}}(C') -l + \mathop{\mathrm{coheight}_{\mathrm{p},\F}}(C') + 2l
\\
&=  \mathop{\mathrm{coheight}_{\mathrm{h},\F}}(C') + \mathop{\mathrm{coheight}_{\mathrm{p},\F}}(C') + l
\\
&\geq 0 + l = \sum_{k \geq 3} (k-3) n_k(C)  \geq 0
\end{split}
\]
\end{proof}


\subsection{Coheight-zero prong connections}\label{sec:sscpc}

We define the types of prong connections as follows. 

\begin{definition}
A prong connection $C$ is $p_o$ if it contains one $1$-prong, one $3$-prong $x$, one heteroclinic separatrix, and one homoclinic separatrix $\gamma$ such that the prongs are $3$-prongs and that there is a closed disk $B$ which does not contain $C$ and that $\partial B =  \{x \} \sqcup \gamma$.
\end{definition}

\begin{definition}
A prong connection $C$ is $p_i$ if it contains one $1$-prong, one $3$-prong $x$, one heteroclinic separatrix, and one homoclinic separatrix $\gamma$ such that the prongs are $3$-prongs and that there is a closed disk $B$ containing $C$ with $\partial B =  \{x \} \sqcup \gamma$.
\end{definition}

\begin{definition}
A prong connection $C$ is $b_\theta$ if it contains two prongs and three heteroclinic separatrices.
\end{definition}

\begin{definition}
A prong connection $C$ is $b_o$ if it contains two prongs, one heteroclinic separatrix $\gamma$, and two homoclinic separatrices such that the prongs are $3$-prongs, the set difference $C - \gamma$ is disconnected,  and there is no closed annulus $A$ containing $C$ with $\partial A =  C - \gamma$.
\end{definition}

\begin{definition}
A prong connection $C$ is $b_i$ if it contains two prongs, one heteroclinic separatrix $\gamma$, and two homoclinic separatrices such that the prongs are $3$-prongs and that there is a closed annulus $A$ containing $C$ with $\partial A =  C - \gamma$.
\end{definition}

\begin{definition}
A prong connection is {\bf semi-self-connected} if it of coheight-zero (i.e. isomorphic to one of Figure~\ref{self_connected_prong} as a topological planar graph, because of Lemma~\ref{lem:ch_codim_zero_01} below). 
\end{definition}

