\subsubsection{Characterization of coheight-zero prong connections of levelable foliations}

The definition of coheight of prong connections implies the following observation. 

\begin{lemma}\label{lem:ch_codim_zero}
Let $\F$ be a levelable foliation with finitely many pronged singular points on a surface $M$ and $D(\F)$ the prong connection diagram.  
Then each connected component $C$ of $D(\F)$ is coheight-zero if and only if there are no centers and any prongs in $C$ are $1$-prongs and $3$-prongs outside of the boundary $\partial M$ such that $n_{V_-}(C) = b_1(C)$.
%
%it satisfies the following conditions:
%\\
%{\rm(1)} $D(\F) \cap \partial M = \emptyset$. 
%\\
%{\rm(2)} Any prongs in $D(\F)$ are $1$-prongs and $3$-prongs. 
%%The prong connection diagram $D(\F)$ contains no fake prongs. 
%\\
%{\rm(3)} $n_{V_-}(C) = b_1(C)$.
%%\\
%%{\rm(4)} Any prongs in $D(\F)$ are $1$-prongs and $3$-prongs. 
\end{lemma}

We have the following characterization of coheight-zero prong connections. 

\begin{proposition}\label{lem:ch_codim_zero_01}
Let $\F$ be a levelable foliation with finitely many pronged singular points on a surface $M$ and $D(\F)$ the prong connection diagram.  
Then each connected component $C$ of $D(\F)$ is of coheight-zero if and only if $C$ is one of Figure~\ref{self_connected_prong} as a topological graph. 
\end{proposition}

\begin{proof}
If a connected component $C$ of $D(\F)$ is one of Figure~\ref{self_connected_prong} as a topological graph, then Lemma~\ref{lem:ch_codim_zero} implies that $C$ is of coheight-zero. 

Conversely, suppose that a connected component $C$ of $D(\F)$ is of coheight-zero. 
By Lemma~\ref{lem:ch_codim_zero}, any prongs in $C$ are $1$-prongs and $3$-prongs outside of the boundary $\partial M$ such that $n_{V_-}(C) = b_1(C)$ because of $\mathop{\mathrm{coheight}_{\mathrm{h},\F}}(C) = 0$. 
If $C$ has no $3$-prongs, then $C$ is of type $\sigma$. 
Thus we may assume that $C$ has $3$-prongs (i.e. $n_{V_-}(C) > 0$). 

\begin{claim}\label{claim:12}
$b_1(C) = 1 + (\vert \{ 3\text{-prong in } C \} \vert - \vert \{ 1\text{-prong in } C \} \vert) / 2 $. 
\end{claim}

\begin{proof}[Proof of Claim~\ref{claim:12}]
By $n_{E}(C) = \sum_{v \in \mathop{\mathrm{Sing}}(\F) \cap C} \deg (v)/2$, we have the following equality: 
\[
\begin{split}
b_1(C) = & 1 - n_{V}(C) + n_{E}(C) 
\\
= & 1 - n_{V}(C) + \sum_{v \in \mathop{\mathrm{Sing}}(\F) \cap C} \deg (v)/2 
\\
= & 1 + \sum_{v \in \mathop{\mathrm{Sing}}(\F) \cap C} \left( \dfrac{\deg (v)}{2} -1 \right) 
\\
= & 1 + (\vert \{ 3\text{-prong in } C \} \vert - \vert \{ 1\text{-prong in } C \} \vert) / 2 
\end{split}
\]
\end{proof}


\begin{claim}\label{claim:11}
$C$ has at most two $3$-prongs 
\end{claim}

\begin{proof}[Proof of Claim~\ref{claim:11}]
Assume $n_{V_-}(C) \geq 3$. 
Then 
\[
\begin{split}
b_1(C) = & 1 + (\vert \{ 3\text{-prong in } C \} \vert - \vert \{ 1\text{-prong in } C \} \vert) / 2 
\\
\leq & 1 + \vert \{ 3\text{-prong in } C \} \vert  / 2  = 1 + n_{V_-}(C)/2 < n_{V_-}(C) = b_1(C)
\end{split}
\]
which is a contradiction. 
\end{proof}


Suppose that $C$ has exactly one $3$-prong $x$. 
Then $b_1(C) = n_{V_-}(C) = 1$. 
From $b_1(C) = 1$, Claim~\ref{claim:12} implies that the prong connection $C$ has exactly one $1$-prong. 
Since all prongs except $x$ are $1$-prongs, each prong separatrix of $C$ either is a separatrix from and to $x$ or connects to a $1$-prong. 
From $b_1(C) = n_{V_-}(C) = 1$, the prong connection $C$ is of type either $p_o$ or $p_i$. 

Suppose that $C$ has at least two $3$-prong $x$. 
By Claim~\ref{claim:11}, we may assume that $C$ has exactly two $3$-prongs $x$ and $y$. 
Then $b_1(C) = n_{V_-}(C) = 2$. 
From $b_1(C) = 2$, Claim~\ref{claim:12} implies that the prong connection $C$ has no $1$-prongs. 
Then each prong separatrix of $C$ is a separatrix from and to the two-point set $\{ x, y \}$. 
%Note $b_1(C) = n_{V_-}(C) = 2$. 
If $C$ contains a separatrix from and to a $3$-prong, then $C$ is of type either $b_o$ or $b_i$. 
Thus we may assume that any separatrix connects $x$ and $y$. 
Then $C$ is of type $b_\theta$. 
\end{proof}


The previous proposition implies Theorem~\ref{main:char_0}. 
Moreover, the previous proposition and Theorem~\ref{cor:tree_rep} imply the following statement. 

\begin{theorem}\label{th:tree_rep_codim_zero}
Let $S$ be a compact surface contained in a sphere $\mathbb{S}^2$ and $\F$ a coheight-zero levelable foliation. 
% tangent to the boundary $\partial S$. 
Then the Reeb graph of the height function of $\F$ on $S$ is a finite directed tree whose vertices of degree one are either a prong connection of type $\sigma$ or a periodic leaf on the boundary $\partial \mathbb{S}^2$, and whose vertrice of degree non-one are either $p_o$, $p_i$, $b_\theta$, $b_o$, or $b_i$. 
\end{theorem}




\section{Properties with respect to the topology $\mathcal{O}^p_{w,W,\mathcal{L}(M)}$}

We describe the behaviors near non-periodic leaves to characterize the instability of some kinds of non-periodic points of levelable foliations. 

Recall that the union of periodic leaves of any levelable foliation on a surface is open and the union of non-periodic leaves is closed because of Lemma~\ref{lem:periodic_noncompact} 
Therefore we have the following similar statements to Lemma~\ref{lem:open_reg_pt}, Lemma~\ref{lem:open_reg_pt_03}, and Lemma~\ref{lem:singular_pt_nbd03}. 

\subsection{Properties for levelable singular foliations}

Fix any distance weights $w,W \colon [0,\infty] \to [0,1]$. 
Let $\F$ be a levelable singular foliation with finitely many pronged singular points on a surface $M$ with or without boundary in this subsection. 

\subsubsection{Persistence of the local non-existence of non-periodic leaves}

By replacing $\mathop{\mathrm{Sing}}(\F)$ with $M - \mathop{\mathrm{Per}}(\F)$ in the proofs of Lemma~\ref{lem:open_reg_pt} and Lemma~\ref{lem:open_reg_pt_03}, the same argument in the proofs implies that the local non-existence of non-periodic leaves persists as follows. 

\begin{lemma}\label{lem:open_periodic_pt}
%Let $\F$ be a levelable singular foliation on a surface $M$ with or without boundary, and 
For any $p \in \R_{\geq 1} \sqcup \{ \infty \}$, there are continuous functions $\varepsilon, \delta \colon M \to \R_{\geq 0}$ with $\varepsilon^{-1}(0) = \delta^{-1}(0) = M - \mathop{\mathrm{Per}}(\F)$ satisfying the following equations for any $x_0 \in \mathop{\mathrm{Per}}(\F)$: 
\[
B(x_0,\delta(x_0)) \cap \bigcup_{\mathcal{G} \in B_{D^{p}_{W_{\mathrm{per}}}}(\F,\varepsilon(x_0))}  M - \mathop{\mathrm{Per}}(\mathcal{G}) = \emptyset
\] 
and so 
\[
B(x_0,\delta(x_0)) \cap \bigcup_{\mathcal{G} \in B_{D^{p}_{w,W}}(\F,\varepsilon(x_0))}  M - \mathop{\mathrm{Per}}(\mathcal{G}) = \emptyset
\] 
\end{lemma}


\subsubsection{Descriptions near non-periodic points}

By replacing $\mathop{\mathrm{Sing}}(\F)$ with $M - \mathop{\mathrm{Per}}(\F)$ in the proof of Lemma~\ref{lem:singular_pt_nbd03}, the same argument in the proof implies the following statements. 

\begin{lemma}\label{lem:non-periodic_pt_nbd}
%Fix any $r, \alpha \in \R_{> 0}$ and any distance weight $W \colon [0,\infty] \to [0,1]$. 
%Let $\F$ be a levelable singular foliation on a surface $M$. 
For any positive number $\varepsilon >0$, there is a positive number $\delta > 0$ satisfying the following inequality: 
\[ 
\sup_{x_0 \in M - \mathop{\mathrm{Per}}(\F)} \sup_{x \in B(x_0,\delta)}d_H(X_{w,\F}(x), \{ 0_{x} \}) \leq \varepsilon
\]
\end{lemma}


\subsubsection{Persistence of periodic leaves of a levelable singular foliation on a surface}


Lemma~\ref{lem:open_periodic_pt} implies the following statements. 

\begin{lemma}\label{lem:per_persistence}
%Let $\F$ be a levelable singular foliation on the surface $M$. 
For any $p \in \R_{\geq 1} \sqcup \{ \infty \}$, any periodic leaf $L \in \F$, an open transverse arc $T \subset M$ intersecting $L$ at a point $x$, and any positive number $\varepsilon>0$, there are a positive number $\delta > 0$ and closed sub-arcs $T',T'',T''' \subset T$ with $x \in T''' \subseteq T'' \subseteq T' \subseteq T \subset B_\varepsilon (T')$ and $\F(T'') \subseteq B_\varepsilon(L)$  satisfying the following statements for any foliation $\mathcal{G} \in B_{D^{p}_{w,W}}(\F,\delta)$: 
\\
{\rm(1)} $T' \subset \mathop{\mathrm{Per}}(\mathcal{\mathcal{G}})$. 
\\
{\rm(2)} If $L$ is transversely orientable {\rm(resp.} transversely non-orientable{\rm)}, then the saturation $\F(T'')$ is an periodic annulus {\rm(resp.} M{\"o}bius band{\rm)} with respect to $\F$ and the saturation $\G(T''')$ is an periodic annulus {\rm(resp.} M{\"o}bius band{\rm)} with respect to $\G$ such that $\F(x) \subset \G(T''') \subseteq \F(T'')$. 
\\
{\rm(3)} There is a point $y \in T'''$ such that the leaf $\G(y)$ is isotopic to $\F(x)$ in $\G(T''')$. 
\end{lemma}

We recall the following concepts. 
%\subsubsection{Two-sided leaves and one-sided leaves}
\begin{definition}
A leaf $L$ of $\F$ is {\bf two-sided} if it has an open small neighborhood $U$ which is an annulus such that $U - L$ is a disjoint union of two open annuli. 
\end{definition}

\begin{definition}
A leaf of $\F$ is {\bf one-sided} if it is not two-sided. 
\end{definition}

\begin{definition}
The {\bf leaf space} $M/\F$ is the quotient space $M/\mathop{\sim_{\F}}$ by $x \sim_{\F} y$ if $\F(x) = \F(y)$. 
\end{definition}

Notice that any periodic leaves on the boundary are one-sided. 
Moreover, for any periodic leaf $L$ such that any small neighborhood of $L$ contains a neighborhood which is a M{\"o}bius band, the leaf $L$ is one-sided. 
We have the following properties. 

\begin{lemma}\label{lem:per_persistence_03}
%Let $\F$ be a levelable singular foliation on the surface $M$. 
For any $p \in \R_{\geq 1} \sqcup \{ \infty \}$ and any periodic leaf $L \in \F$, there are a positive number $\delta > 0$ satisfying the following property for any foliation $\mathcal{G} \in B_{D^{p}_{w,W}}(\F,\delta)$: 
\\
{\rm(1)} If $L$ is transversely orientable, then there is a closed periodic annulus with respect to $\G$ whose interior contains $L$ and which is contained in a closed periodic annulus with respect to $\F$ in $B_\varepsilon(L)$. 
\\
{\rm(2)} If $L$ is transversely non-orientable, then there is a closed periodic M{\"o}bius band with respect to $\G$ whose interior as a subset of $M$ contains $L$ and which is contained in a closed periodic M{\"o}bius band with respect to $\F$ in $B_\varepsilon(L)$. 
\end{lemma}

\begin{proof}
Let $L \in \F$  be a periodic leaf. 
By the compactness of $L$, Lemma~\ref{lem:open_periodic_pt} implies that the constants $\varepsilon := \min_{x \in L} \varepsilon(x)$ and $\delta := \min_{x \in L} \delta(x)$ are positive, and that there are finite points $x_1, \ldots, x_k \in L$ with $L \subset \bigcup_{i=1}^k B(x_i, \delta)$ satisfying the following equality: 
\[
\left( \bigcup_{i=1}^k B(x_i,\delta) \right) \cap \bigcup_{\mathcal{G} \in B_{D^{p}_{W_{\mathrm{per}}}}(\F,\varepsilon)}  M - \mathop{\mathrm{Per}}(\mathcal{G}) = \emptyset
\] 
%where $\delta := \min_{x \in L} \delta(x)$. 
Then there is a positve number $\delta' \in (0, \delta)$ such that $B(L,\delta') \subset \bigcup_{i=1}^k B(x_i, \delta)$. 
Therefore we have 
\[
B(L,\delta') \cap \bigcup_{\mathcal{G} \in B_{D^{p}_{W_{\mathrm{per}}}}(\F,\varepsilon)}  M - \mathop{\mathrm{Per}}(\mathcal{G}) = \emptyset
\] 
and so the following relation holds: 
\[
B(L,\delta') \subseteq  \bigcap_{\mathcal{G} \in B_{D^{p}_{W_{\mathrm{per}}}}(\F,\varepsilon)}   \mathop{\mathrm{Per}}(\mathcal{G})
\] 
Fix an open transverse arc $T$ intersecting $x$ such that $\F(T) \subset B_\varepsilon(L)$ is a periodic annulus with respect to $\F$. 
Lemma~\ref{lem:per_persistence} implies that there is a closed sub-arcs $T''',T'' \subset T$ with $x \in T''' \subseteq T''$ such that 
%$\G(T''')$ is an periodic annulus with respect to $\G$ such that 
$\F(x) \subset \G(T''') \subset \F(T'') \subset B_\varepsilon(L)$. 
Moreover, if $L$ is transversely orientable (resp. non-orientable), then we may assume that $\G(T''')$ is a closed periodic annulus (resp. M{\"o}bius band) with respect to $\G$ whose interior contains $L$ and which is contained in the closed periodic annulus  (resp. M{\"o}bius band) $\F(T'')$ with respect to $\F$ in $B_\varepsilon(L)$. 
Therefore, the assertion holds. 
\end{proof}

\begin{lemma}\label{lem:per_persistence_04}
%Let $\F$ be a levelable singular foliation on the surface $M$ and 
Let $G_{H_{\F}}$ be the Reeb graph of the height function $H_{\F}$ of the levelable singular foliation $\F$, which is an acyclic finite directed graph. 
There is a set $\{ L_1, \ldots, L_k \}$ of distinct periodic leaves contained in the interiors of edges of $G_{H_{\F}}$ satisfying the following properties: 
\\
{\rm(1)} Every connected component of $G_{H_{\F}} - \{ L_1, \ldots, L_k \}$ contains exactly one vertex of the end-completion of $G_{H_{\F}}$. 
\\
{\rm(2)} There is a positive number $\delta > 0$ such that, for any foliation $\mathcal{G} \in B_{D^{p}_{w,W}}(\F,\delta)$, there are $\mathcal{G}$-invariant closed periodic annuli $\mathbb{A}_i$ which contains $L_i$ for any $i \in \{ 1, \ldots, k\}$ such that $V_{\G,j} \subseteq V_{\F,j}$ for any $j \in \{ 1, \ldots, l \}$, where $\{ V_{\F,1}, \ldots, V_{\F,l} \}$ is the set of connected components of $M - \bigsqcup_{i=1}^k L_i$ and $V_{\G,j}$ is the connected component of $M - \bigsqcup_{i=1}^k \mathbb{A}_i$ intersecting $V_{\F,j}$.
\end{lemma}

\begin{proof}
For any edge of the Reeb graph $G_{H_{\F}}$, choose exactly one periodic leaf in the interior of the edge. 
The set of such periodic leaves is denoted by $\{ L_1, \ldots, L_k \}$, which implies assertion (1). 
By Lemma~\ref{lem:per_persistence_03}, there are $\mathcal{G}$-invariant closed periodic annuli $\mathbb{A}_i$ which contains $L_i$ for any $i \in \{ 1, \ldots, k\}$. 
Let $V_{\G,j}$ be the connected component of $M - \bigsqcup_{i=1}^k \mathbb{A}_ i$ intersecting $V_{\F,j}$. 
By construction, we have $V_{\G,j} \subseteq V_{\F,j}$ for any $j \in \{ 1, \ldots, l \}$. 
\end{proof}


\subsection{Local maximality of coheights}

We have the following observation.


\begin{lemma}\label{lem:codim_max}
Let $M$ be a surface. 
For any $\F \in \mathcal{L}^*_{i}(M)$, there is a positive number $\delta > 0$, the following statements hold for any $\G \in \mathcal{L}^*_{i}(M)$ near $\F$:
\\
{\rm(1)} $n_{\partial}(\G) \leq n_{\partial}(\F)$. 
\\
{\rm(2)} $n_{V_-}(\G) - n_{E}(\G) + n_{0}(\G) = n_{V_-}(\F) - n_{E}(\F) + n_{0}(\G)$, where $n_{0}(\F')$ is the number of centers of $\F'$. 
\\
{\rm(3)} $- n_{CC}(\G) \leq - n_{CC}(\F)$. 
\\
{\rm(4)} $\sum_{y \in \mathop{\mathrm{Sing}}(\G)} (1 + \mathrm{coheight}_{\mathrm{p},\G}(y)) \leq \sum_{y \in \mathop{\mathrm{Sing}}(\F)} (1 + \mathrm{coheight}_{\mathrm{p},\F}(y))$. 
\\
{\rm(5)} $\mathrm{coheight}(\G) \leq \mathrm{coheight}(\F)$.  
\end{lemma}

\begin{proof}
Fix a line field $\G \in \mathcal{L}^*_{i}(M)$ near $\F$. 
By Proposition~\ref{prop:inv_index}, assertion (1) holds and $n_{V_-}(\G) \geq n_{V_-}(\F)$. 
Lemma~\ref{lem:per_persistence_04} implies assertion (3).

From the invariance of the sum of positive indices of singular leaves, the sum of negative indices of singular leaves is invariant in $\mathcal{L}^*_{i}(M)$. 
This implies that any $1$-prong is invariant under small perturbations and that any center either is preserved or becomes two $1$-prongs under small perturbations. 
The invariance of the sum of positive indices of singular leaves implies assertion (2). 

Notice that $\sum_{y \in \mathop{\mathrm{Sing}}(\F)} (1 + \mathrm{coheight}_{\mathrm{p},\F}(y))$ is invariant under  any small perturbations near $p$, which either preserves $p$ or split $p$ into two $1$-prongs.  
From the definition of $\mathrm{coheight}_{\mathrm{p},\F}$, by the invariance of the sum of negative indices of singular leaves, Lemma~\ref{lem:inv_index_prong} implies 
%the following inequality: 
 \[
 \begin{split}
 \sum_{y \in \mathop{\mathrm{Sing}}(\G)} (1 + \mathrm{coheight}_{\mathrm{p},\G}(y)) &\leq 
n_{V_-}(\G) - n_{V_-}(\F) + \sum_{y \in \mathop{\mathrm{Sing}}(\G)} (1 + \mathrm{coheight}_{\mathrm{p},\G}(y)) 
\\
&= \sum_{y \in \mathop{\mathrm{Sing}}(\F)} (1 + \mathrm{coheight}_{\mathrm{p},\F}(y))
 \end{split}
\]
because of $0 \leq n_{V_-}(\G) - n_{V_-}(\F)$. 
By assertion (1)--(4), the non-existence of fake prongs implies assertion (5). 
\end{proof}
















