\begin{lemma}\label{lem:stability04+}
Suppose that $M$ is compact. 
For any $i \in \Z_{>1}$,  the subspace $\mathcal{L}^{0}_{i}(M)$ is open dense in the space $\mathcal{L}^*_{i}(M)$ with respect to the relative topology of the topology $\mathcal{O}^p_{w,W,\mathcal{L}(M)}$. 
% and consists of structurally stable ones in $\mathcal{L}^*_{i}(M)$. 
\end{lemma}


\begin{proof}
Lemma~\ref{lem:stability03} implies the density. 
%
Without loss of generality, we may assume that $M$ is connected.
Let $\F \in \mathcal{L}^{0}_{i}(M)$ be a levelable foliation on $M$. 
Then, any prong connections of $\F$ consist of prong separatrices and two prongs, which are $1$-prongs and $3$-prongs. 
By Lemma~\ref{lem:periodic}, the complement of the prong connection diagram of $\F$ is a finite union of annuli which is an open subset of $M$ and is the union of periodic leaves. 
From Lemma~\ref{lem:per_persistence_04}, there are periodic leaves $L_1 , \ldots, L_k$ and $V_{\F,1}, \ldots, V_{\F,l}$ connected components of $M - \bigsqcup_{j=1}^k L_j$ as in Lemma~\ref{lem:per_persistence_04}. 
Then all connected components $V_{\F,j}$ are disks, annuli, and two-punctured disks. 
By Poincar{\'e}-Hopf theorem for one-dimensional singular foliations with finitely many singular points on a surface \cite[p.113 Thoerem~2.2]{Hopf1989diff}, if such a connected component $V_{\F,j}$ is a disk (resp. annulus, two-punctured disk) then it contains exactly two singular leaves which consists of two $1$-prongs (resp, one $1$-prong and one $3$-prong, two $3$-prongs).
%
Let $i_{\F,j'} \in \{ 0,1\}$ be the sum of positive indices of singular leaves of $\F$ in $V_{\F,j'}$. 
Then $i = \sum_{j'=1}^l i_{\F,j'}$. 
Lemma~\ref{lem:per_persistence_04} implies that there is a positive number $\delta > 0$ such that, for any foliation $\mathcal{G} \in B_{D^{p}_{w,W}}(\F,\delta)$, there are $\mathcal{G}$-invariant closed periodic annuli $\mathbb{A}_j$ which contains $L_j$ for any $j \in \{ 1, \ldots, k\}$ such that $V_{\G,j'} \subseteq V_{\F,j'}$ for any $j' \in \{ 1, \ldots, l \}$, where $V_{\G,j'}$ is the connected component of $M - \bigsqcup_{j=1}^k \mathbb{A}_{j'}$ intersecting $V_{\F,j}$. 
This implies that all connected components $V_{\G,j'}$ are disks, annuli, and two-punctured disks. 

Let $i_{\G,j'} \in \Z_{\geq 0}$ be the sum of positive indices of singular leaves of $\G$ in $V_{\G,j'} \subset V_{\F,j'}$. 
Lemma~\ref{lem:singular_pt_nbd} implies that $i_{\G,j'} \geq i_{\F,j'}$ for any $j' \in \{ 1, \ldots, l \}$, and that the numbers $n_{\G,j'}$ contained in singular leaves of $\G$ in $V_{\G,j'}$ is more than or equal to those $n_{\F,j'}$ of $\F$ in $V_{\G,j'}$.
By $\sum_{j'=1}^l i_{\F,j'} = i = \sum_{j'=1}^l i_{\G,j'}$, we obtain $i_{\G,j'} = i_{\F,j'}$ and $n_{\F,j'} = n_{\G,j'}$ for any $j' \in \{ 1, \ldots, l \}$. 
Since the indices of $k$-prongs are $1 - k/2$, Poincar{\'e}-Hopf theorem implies that the indices of any singular leaves of $\G$ are $1/2$ and $-1/2$. 
This means that all singular leaves of $\G$ are $1$-prongs and $3$-prongs. 
Therefore each connected component $V_{\G,j}$ which is a disk (resp. annulus, two-punctured disk) contains exactly two singular leaves which consist of two $1$-prongs (resp, one $1$-prong and one $3$-prong, two $3$-prongs).
All possible prong connections with exactly two prongs which are $1$-prongs and $3$-prongs are semi-self-connected as shown in Figure~\ref{self_connected_prong}. 
This means that $\mathcal{L}^{0}_{i}(M)$ is open. 
\end{proof}


\subsubsection{Structural stability of levelable foliations}

To demonstrate the structural stability, we define the canonical local structures as follows.


\begin{figure}[t]
\begin{center}
\includegraphics[scale=.5]{stdd_loc_str.pdf}
\end{center} 
\caption{The partition $\F_{D_1}$ on the disk $D_1$, the partition $\F_{D_3}$ on the disk $D_3$, and the partition $\F_{D_A}$ on the annulus $A_3$.}
\label{fig:stdd_loc_str}
\end{figure} 

\begin{definition}
Set $D_1 := \{ (x,y) \mid x \in [-1,1], y \in [0, \sqrt{1 - x^2} + 1] \}$ $p_1 := (0,1)$, and $l_0 := \{0\} \times [0,1) \subset D_1$. 
Define 
\[
l_r := \{ p \in D_1 \mid d(p, \{p_1 \} \sqcup l_0) = r \}
\]
for any $r \in (0,1]$. 
Then $\{ \{ p_1 \} \} \sqcup \{ l_r \mid r \in [0,1] \}$ is a partition and denote by $\F_{D_1}$ as in the left in Figure~\ref{fig:stdd_loc_str}. 
Moreover, the transverse arc $[-1,1] \times \{0 \} \subset D_1$ is called the {\bf core transverse arc} of $D_1$, and the periodic orbit intersecting the boundary of the core transverse arc is called the {\bf core periodic orbit} for $D_1$. 
\end{definition}

\begin{definition}
Set $p_3 := (0,1)$, $l_{0,2} := \{0 \} \times [0,1)$, 
\[
\begin{split}
l_{0,1} &:= (\{-1\} \times [0,1)) \sqcup \{(x,y) \mid x \in [-1,0), y = \sqrt{1/4 - (x+1/2)^2} + 1 \}
\\
l_{0,3} &:= (\{1\} \times [0,1)) \sqcup \{(x,y) \mid x \in (0,1], y = \sqrt{1/4 - (x-1/2)^2} + 1 \}
\end{split}
\]
and $D_3 := (\R \times \R_{\geq 0}) \cap B_{1/3}(l_0)$. 
Define 
\[
l_r := \{ p \in D_3 \mid d(p, \{p_3 \} \sqcup l_{0,1} \sqcup l_{0,2} \sqcup l_{0,3}) = r \}
\]
for any $r \in (0,1]$. 
Then $l_r$ for any $r \in (0,1]$ consists of three closed arcs $l_{r,1},l_{r,2}$, and $l_{r,3}$. 
Then $\{\{p_3\} \} \sqcup \{ l_{r,i} \mid r \in [0,1/3], i \in \{1,2,3\} \}$ is a partition and denote by $\F_{D_3}$ as in the middle in Figure~\ref{fig:stdd_loc_str}. 
Moreover, the transverse arcs $[-4/3,-2/3] \times \{0 \}, [-1/3,1/3] \times \{0 \}, [2/3,4/3] \times \{0 \} \subset D_3$ are called the {\bf core transverse arcs} of $D_3$ and the periodic orbits intersecting the boundaries of the core transverse arcs are called the {\bf core periodic orbit} for $D_3$. 
\end{definition}

\begin{definition}\label{def:disk2anuulus}
Consider the partition $\F_{D_3}$ on $D_3$. 
Set $T_- := [-4/3,-2/3] \times \{0 \}$, $T_0 := [-1/3,1/3] \times \{0 \}$, and $T_+ := [2/3,4/3] \times \{0 \}$.
Then $D_3 \cap (\R \times \{ 0 \} = T_- \sqcup T_0 \sqcup T_+$. 
Define an equivalence relation $\sim_{A_3}$ on $D_3$ as follows: 
\[
\begin{split}
(x,y) \sim_{A_3} (x',y') \text{ if } & \text{ either } (x,y) = (x',y') 
\\
& \text{ or } \left( x+x' = y = y' = 0 \text{ and } (x,y) \in T_- \sqcup T_+ \right)
\end{split}
\]
The quotient space $A_3 := D_3/\mathop{\sim_{A_3}}$ is a closed annulus, and the induced partition is denoted by $\F_{A_3}$ as in the right in Figure~\ref{fig:stdd_loc_str}. 
Moreover, the transverse arcs $\pi([-4/3,-2/3] \times \{0 \}), \pi([-1/3,1/3] \times \{0 \}) \subset A_3$ is called the {\bf core transverse arcs} of $A_3$ and the periodic orbits intersecting the boundaries of the core transverse arcs are called the {\bf core periodic orbit} for $A_3$, where $\pi \colon D_3 \to A_3$ is the quotient map. 
\end{definition}

Using these partitions, we define the following types. 

\begin{definition}
A partition on a disk $D$ is of {\bf type $\bm{\sigma/2}$} if it is locally topologically equivalent to the partition $\F_{D_1}$.
Then $D$ is called a disk of  {\bf type $\bm{\sigma/2}$}. 
\end{definition}

\begin{definition}
A partition on a disk $D$ is of {\bf type $\bm{b_{o/i}/2}$} if it is locally topologicaly equivalent to the partition $\F_{D_1}$. 
Then the disk $D$ is called a domain of  {\bf type $\bm{b_{o/i}/2}$}. 
\end{definition}

\begin{definition}
A partition on an annulus $A$ is of  {\bf type $\bm{b_\theta/2}$} if it is locally topologically equivalent to the partition $\F_{A_1}$. 
Then the annulus $A$ is called a domain of  {\bf type $\bm{b_\theta/2}$}. 
\end{definition}

We characterize the local structures as follows.

\begin{lemma}\label{lem:char_local_prongs}
Let $\F$ be a levelable foliation with finitely many pronged singular points on a surface $M$ and $D \subset M$ a disk which contains no prong except one $1$-prong $q_1$ and whose boundary consists of one closed leaf arc $C$ and one closed transverse arc $T$ such that the intersection $C \cap T = \partial C = \partial T$ consists of two points. 
Then the restriction $\F\vert_{D}$ is of type $\sigma/2$.
%locally topologicaly equivalent to the partition $\F_{D_1}$. 
\end{lemma}

\begin{figure}[t]
\begin{center}
\includegraphics[scale=.5]{semi-disk.pdf}
\end{center} 
\caption{A disk $D_1$ which contains no prong except one $1$-prong and whose boundary consists of one closed leaf arc $C$ and one closed transverse arc $T$, a disk $D_3$ which contains no prong except one $3$-prong and whose boundary consists of three closed leaf arcs and three closed transverse arcs, and an anulus $A_3$ which contains no prong except one $3$-prong and whose boundary consists of two boundary components such that one of them consists of one closed leaf arc and one closed transverse arc and another is a periodic leaf.}
\label{fig:semi_disk}
\end{figure} 

\begin{proof}
Since any leaf of the levelable foliation $\F$ is closed in $M - \mathop{\mathrm{Sing}}(\F)$, the semi-prong separatrix $L$ of $q_1$ intersects the interior of $T$. 
Let $l \subset D$ be the closed leaf arc between $q_1$ and the point $q \in L \cap T$, which is the first hitting point to $T$ from $q_1$ by $L$ as on the left in Figure~\ref{fig:semi_disk}. 
Then the complement $T - \{ q\}$ is the disjoint union of two intervals $T_-$ and $T_+$. 

\begin{claim}\label{claim:17}
For any point $p \in D - (\{q_1\} \sqcup l)$, the element $\F\vert_D(p)$ of the restriction $\F\vert_D$ is closed. 
\end{claim}

\begin{proof}[Proof of Claim~\ref{claim:17}]
Fix any point $p \in D - (\{q_1\} \sqcup l)$. 
By Lemma~\ref{lem:regularity_proper}, for any point $p \in D - (\{q_1\} \sqcup l)$, the set difference $\overline{\F(p)} - \F(p)$ consists of singular points and so $(\overline{\F(p)} - \F(p)) \cap D \subset \{ q_1 \}$.  
Assume that $q_1 \in \overline{\F\vert_D(p)}$. 
Since $D$ is closed, by $\overline{\F\vert_D(p)} \subset \overline{\F(p)} \cap D$, we have $\overline{\F\vert_D(p)} = \F\vert_D(p) \sqcup \{ q_1 \}$. 
Then there is a connected component $\gamma$ of $\F\vert_D(p) - \{ p \} \subset D - l$ which is an open arc whose closure is a closed arc $\gamma \sqcup \{p, q_1\}$. 
This means that $q_1$ is not a $1$-prong because $l \cap \gamma = \emptyset$ and $\overline{l} \cap \overline{\gamma} = q_1$. 
Thus $q_1 \notin \overline{\F\vert_D(p)}$ and so $(\overline{\F\vert_D(p)} - \F\vert_D(p)) \cap D = \emptyset$, which implies the assertion.  
\end{proof}
If there is a periodic leaf in $D$, then Poincar{\'e}-Hopf theorem implies that $D$ contains a singular point which is not $q_1$, which contradicts the hypothesis. 
Thus any elements of $\F\vert_D(p)$ for any point $p \in D - (\{q_1\} \sqcup l)$ are closed intervals between $T$. 
Since $T$ has no tangencies, each element of $\F\vert_D(p)$ for any point $p \in D - (\{q_1\} \sqcup l)$ connect a point in $T_-$ and a point in $T_+$. 
This means that the assertion holds. 
\end{proof}


\begin{lemma}\label{lem:char_local_prongs_02}
Let $\F$ be a levelable foliation with finitely many pronged singular points on a surface $M$ and $D \subset M$ a disk which contains no prong except one $3$-prong $q_3$ and whose boundary consists of pairwise disjoint three closed leaf arc $C_1,C_2,C_3$ and pairwise disjoint three closed transverse arcs $T_1,T_2,T_3$ such that $(C_i \sqcup C_{i+1}) \cap T_i = \partial T_i$ and  $(T_i \sqcup T_{i+1}) \cap T_{i+1} = \partial T_i$ for any $i \in \{1,2,3\}$, where $C_4 := C_1$ and $T_4 := T_1$. 
Then the restriction $\F\vert_{D}$ is of type $b_\theta/2$. 
%locally topologicaly equivalent to the partition $\F_{D_3}$. 
\end{lemma}

\begin{proof}
Let $D$ be a disk as above, as on the right in Figure~\ref{fig:semi_disk}. 
Assume there is a prong separatrix of $q_3$ in $D$. 
Then the disk in $D$ whose boundary consists of the prong separatrix and $q_3$ contains a disk whose boundary is a periodic leaf. 
Therefore, Poincar{\'e}-Hopf theorem implies that $D$ contains a singular point which is not $q_1$, which contradicts the hypothesis. 

Thus there are no prong separatrix of $q_3$ in $D$.
Let $l_1,l_2,l_3$ be the elements of the restriction $\F\vert_D$ each of whose closures contains $q_3$. 
Since any leaf of the levelable foliation $\F$ is closed in $M - \mathop{\mathrm{Sing}}(\F)$, each semi-prong separatrix of $q_3$ intersects $\mathrm{int} T_i$ for some $i \in \{ 1,2,3 \}$. 
Because $T_1 \sqcup T_2 \sqcup T_3$ has no tangencies, the three elements $l_1,l_2$, and $l_3$ intersects distinct connected components of $T_1 \sqcup T_2 \sqcup T_3$. 
By renaming $T_i$ if neccesary, we may assume that $T_i$ intersects $l_i$ for any $i \in \{ 1,2,3 \}$. 
As the same argument in the proof of Claim~\ref{claim:17} and the subsequent explanation,  for any point $p \in D - (\{q_3\} \sqcup l_1 \sqcup l_2 \sqcup l_3)$, the element $\F\vert_D(p)$ of the restriction $\F\vert_D$ is a closed intervals between $T_1 \sqcup T_2 \sqcup T_3$. 
Since each $T_i$ has no tangencies, each element of $\F\vert_D(p)$ for any point $p \in D - (\{q_3\} \sqcup l_1 \sqcup l_2 \sqcup l_3)$ connect points in different connected components of $T_1 \sqcup T_2 \sqcup T_3$. 
This means that the assertion holds. 
\end{proof}


\begin{lemma}\label{lem:char_local_prongs_03}
Let $\F$ be a levelable foliation with finitely many pronged singular points on a surface $M$ and $A \subset M$ an annulus which contains no prong except one $3$-prong $q_3$ and whose boundary consists of two boundary components $\partial_1$ and $\partial_2$ such that $\partial_1$ consists of one closed leaf arc $C$ and one closed transverse arc $T$ with $C \cap T = \partial C = \partial T$ and that $\partial_2$ is a periodic leaf. 
Suppose that there is a closed transverse between $\partial_1$ and $\partial_2$. 
Then the restriction $\F\vert_{A}$ is type $b_{o/i}/2$.
%locally topologicaly equivalent to the partition $\F_{A_3}$. 
\end{lemma}

\begin{proof}
Cutting the closed transverse arc $T$ into two closed intervals $T_-$ and $T_+$, the resulting space $D$ is a disk as in Lemma~\ref{lem:char_local_prongs_02}. 
By Lemma~\ref{lem:char_local_prongs_02}, the resulting partition $\F_D$ of $\F$ is locally topologicaly equivalent to the partition $\F_{D_3}$. 
The existence of the height function $H_\F$ of $\F$ implies that the restriction $H_\F\vert_T$ on the interval is strictly monotonic. 
Since $\F$ can be considered with the resulting partition on the quotient space as in Definition~\ref{def:disk2anuulus}, the restriction $\F\vert_{A}$ is locally topologically equivalent to the partition $\F_{A_3}$.
\end{proof}

For any element $\F$ of $\mathcal{L}^{0}(M)$ and for any prong connection $C$ of $\F$, by Lemmas~\ref{lem:char_local_prongs}--\ref{lem:char_local_prongs_03}, we can choose an invariant closed \nbd $D_- \sqcup_T D_+$ of $C$ which is a union of two domains $D_-$ and $D_+$ of type $\sigma/2$, $b_\theta/2$, or $b_{o/i}/2$ such that $T$ is both the union of core transverse arcs of $D_-$ intersecting $D_+$ and one of $D_+$ intersecting $D_-$, and that the core periodic orbits intersecting $D_-$ coincide the periodic orbits intersecting $D_+$. 
Then the union of the core transverse arcs in $D_-$ and $D_+$ and core periodic orbits intersecting $D_-$ is called the {\bf core component} of $D_- \sqcup_T D_+$. 
%
Choosing one core component for any prong connection, the union of such core components is called a {\bf core} of $\F$. 
We have the following completeness. 

\begin{proposition}\label{prop:com_inv_02}
For any elements $\F$ and $\G'$ of the subspace $\mathcal{L}^{0}(M)$, if there are cores of elements $\F$ and $\G'$ which are isomorphic as a surface graph, then the prong connection diagrams of $\F$ and $\G$ are isomorphic as a surface graph. 
\end{proposition}

\begin{proof}
Let $D(\F)$ be the prong connection diagram of $\F$ and $H_\F$ the height function of $\F$. 
%Suppose that there is $C(\F)$ (resp. $C(\G)$) be a core of $\F$ (resp. $\G$) such that $C(\F)$ and $C(\G)$ are isomorphic as a surface graph. 
Fix a core component $C(D_- \sqcup_T D_+)$ of $\F$. 
Then $D_-$ (resp. $D_+$) is a domain of type $\sigma/2$, $b_\theta/2$, or $b_{o/i}/2$, and so they contain exactly one prong $q_-$ (resp. $q_+$), which is either a $1$-prong or a $3$-prong because of $\F \in \mathcal{L}^{0}(M)$. 
Since the union $D_- \sqcup_T D_+$ is a closed invariant subset, the intersection $D(\F) \cap (D_- \sqcup_T D_+)$ is a finite graph which intersects $T$ finitely many times. 
Because that the union $D_- \sqcup_T D_+$ is a closed invariant subset, by Lemma~\ref{lem:regularity_proper}, for any non-closed leaf $L$ in $D_- \sqcup_T D_+$, the leaf $L$ is a prong connection whose closure $\overline{L}$ is a closed curve between prongs with $\overline{L} - L \subseteq \{ q_- , q_+ \}$, and so any semi-prong separatrix intersecting $D_- \sqcup_T D_+$ is a prong separatrix among $\{ q_- , q_+ \}$. 
Since both prongs $q_-$ and $q_+$ have an odd number of separatrices, there is a prong separatrix connecting $q_-$ and $q_+$. 
Therefore, we obtain $H_\F(q_-) = H_\F(q_+)$. 
Then $C := D(\F) \cap (D_- \sqcup_T D_+)$ is the prong connection containing $q_-$ such that $D - C \subseteq \mathop{\mathrm{Per}}(\F)$. 
By the existence of a prong separatrix connecting $q_-$ and $q_+$, the prong connection $C$ is type $\sigma$ (resp. $b_o$ or $b_i$) if $\F\vert_{D_-}$ and $\F\vert_{D_+}$ are of type $\sigma/2$ (resp. $b_{o/i}$). 
Moreover, the prong connection $C$ is type $p_o$ or $p_i$ if $\F\vert_{D_-}$ and $\F\vert_{D_+}$ are of type $\sigma/2$ and $b_{o/i}$. 

\begin{claim}\label{claim:19}
The prong connection $C$ is type $b_\theta$ if $\F\vert_{D_-}$ and $\F\vert_{D_+}$ are of type $b_{\theta}/2$.
\end{claim}

\begin{proof}[Proof of Claim~\ref{claim:19}]
Suppose that $\F\vert_{D_-}$ and $\F\vert_{D_+}$ are of type $b_{\theta}/2$.
Assume that there are elements $l_- \in \F\vert_{D_-}$ with $q_- \in \overline{l_-} - l_-$ and $l_+ \in \F\vert_{D_+}$ with $q_+ \in \overline{l_+} - l_+$ such that $l_-$ and $l_+$ intersect a same connected component $T'$ of $T$ and that $l_- \cap l_+ = \emptyset$. 
Denote by $t'_- \in T'$ the point with $\{ t'_- \} = l_- \cap T'$ and by $t'_+ \in T'$ the point with $\{ t'_+ \} = l_+ \cap T'$. 
Let $[t'_-, t'_+] \subset T'$ be the sub-arc whose bounary is $\{ t'_-, t'_+ \}$. 
Since there is a small \nbd $I_-$ (resp. $I_+$) of $t'_-$ (resp. $t'_+$) in $[t'_-, t'_+] \subset T'$ consists of periodic points except $t'_-$ (resp. $t'_+$) in $T'$, the restriction $H_\F \vert_{I_-}$ (resp. $H_\F \vert_{I_+}$) is strictly monotonic. 
This implies the extrema $t'_0$ in an open interval $[t'_-, t'_+] - \{ t'_-, t'_+ \}$ of $H_\F$ with $H_\F(t'_0) \neq H_\F(t'_-) = H_\F(t'_+)$. 
Therefore, the point $t'_0 \in D_- \sqcup_T D_+$ is contained in a prong connection $C' \neq C$, which contradicts $C = D(\F) \cap (D_- \sqcup_T D_+)$. 
Thus $C$ is type $b_\theta$. 
\end{proof}
Therefore, any core component determines the unique prong connection, and so any core determines the unique prong connection diagram. 
In addition, if the cores of elements of $\mathcal{L}^{0}(M)$ are isomorphic as a surface graph, then their prong connection diagrams are isomorphic as a surface graph. 
\end{proof}


\begin{lemma}\label{prop:com_inv}
%Suppose that $M$ is compact. 
The following are equivalent for any $\F, \G \in \mathcal{L}^{0}(M)$:
\\
{\rm(1)} The prong connection diagrams of elements $\F$ and $\G$ are isomorphic as a surface graph.  
\\
{\rm(2)} The elements $\F$ and $\G$ are topologically equivalent. 
\end{lemma}

\begin{proof}
By definition of topologically equivalence, assertion (2) implies assertion (1). 
Conversely, by definition of prong connection diagram, each connected component of the complement of the prong connection diagram of a foliation in $\mathcal{L}^*_{i}(M)$ is either an annulus, a M{\"o}bius band, or a Klein bottle. 
On the other hand, because the leaf spaces of any foliations on such an invariant annulus (resp. M{\"o}bius band, Klein bottle) which is tangent to the boundary and consists of periodic leaves are topologicaly equivalent are intervals, such foliations on the annulus (resp. M{\"o}bius band, Klein bottle) are topologically equivalent respectively. 
Therefore, $\F$ is topologically equivalent to $\G$. 
\end{proof}


