\begin{definition}
The prong connection diagram of a levelable foliation on a surface is $b$-unstable (resp. $c$-unstable, $f$-unstable, $h$-unstable) if it contains exactly one $b$-unstable (resp. $c$-unstable, $f$-unstable, $h$-unstable) prong connection and any prong connections except the coheight-one prong connection are coheight-zero. 
\end{definition}


\subsubsection{Characterization of $p$-unstable levelable foliations}

Let $n_{V_+}(C)$ be the number of prongs in $C$ whose indices are positive. 
Then $n_{V_+}(C) = n_{V}(C) - n_{V_-}(C)$. 
%
We have the following observation. 

\begin{lemma}\label{lem:ch_p-unstable}
%Let $\F$ be a levelable foliation with finitely many pronged singular points on a surface $M$ and $D(\F)$ the prong connection diagram.  
%Then e
Each $p$-unstable prong connection is isomorphic to one of Figure~\ref{p_unstable_prong_connection} as a topological graph. 
\end{lemma}

\begin{proof}
Let $C$ be a $p$-unstable prong connection. 
From $D(\F) \cap \partial M = \emptyset$, any prongs in $C$ are outside of the boundary $\partial M$. 
By $\mathrm{coheight}_{\mathrm{p,\F}}(C) = 2$, since the coheight of $k$-prong $y$ ($k \geq 3$) with respect to degeneracy of singular points is $\mathrm{coheight}_{\mathrm{p},\F}(y) = 2(k-3)$, the prong connection $C$ contains exactly one $4$-prong and any prongs except the $4$-prong are $1$-prongs and $3$-prongs. 
%
Let $l$ be the number of $3$-prongs in $C$. 
Then $n_{V_-}(C) = 1 + l$ and so $n_{V_+}(C) = n_{V}(C) - n_{V_-}(C) = n_{V}(C) - (1+l)$. 
%Moreover, the difference $n_{V_-}(C) - (1 + l)$ is the number of $1$-prongs in $C$.

\begin{claim}\label{claim:14}
%We claim that 
$l = 0$. 
\end{claim}

\begin{proof}[Proof of Claim~\ref{claim:14}]
%Indeed, t
By $n_{E}(C) = \sum_{v \in \mathop{\mathrm{Sing}}(\F) \cap C} \deg (v)/2$, from Lemma~\ref{lem:betti}, we have the following equality: 
\[
\begin{split}
n_{V_-}(C) + 1 = b_1(C) = & 1 - n_{V}(C) + n_{E}(C) 
\\
= & 1 - n_{V}(C) + \sum_{v \in \mathop{\mathrm{Sing}}(\F) \cap C} \deg (v)/2 
\\
= & 1 + \sum_{v \in \mathop{\mathrm{Sing}}(\F) \cap C} \left( \dfrac{\deg (v)}{2} -1 \right) 
\\
= & 2 + (\vert \{ 3\text{-prong in } C \} \vert - \vert \{ 1\text{-prong in } C \} \vert) / 2 
\\
= & 2 + (\vert \{ 3\text{-prong in } C \} \vert - n_{V_+}(C)) / 2 
\\
= & 2 + (l - (n_{V_-}(C) - (1 + l))) / 2
\\
= & l + (5 - n_{V_-}(C))/2 
\end{split}
\]
Then $1 + l = n_{V_-}(C)  = 1 + 2l/3$ and so $l = 0$. 
\end{proof}

Thus $C$ consists of one $4$-prong and $1$-prongs. 
By the definition of $p$-instability, we have $b_1(C) = n_{V_-}(C) + 1 = 1 + 1 = 2$. 
From $2 = b_1(C) = 2 - \vert \{ 1\text{-prong in } C \} \vert / 2$, the prong connection  $C$ consists of the $4$-prong and two homoclinic separatrices. 
\end{proof}

