\begin{lemma}\label{lem:plus_zero}
Notice that every prong connection $C$ is either $c$-unstable or $p$-unstable if and only if $\mathrm{coheight}_{\mathrm{h},\F}(C) + \mathrm{coheight}_{\mathrm{p},\F}(C) = \mathop{\mathrm{coheight}_{\F}}(C) = 1$. 
In any case, we have $n_{\partial}(C) = n_{\mathrm{fake}}(C) = 0$. 
\end{lemma}

\begin{proof}
By the definition of $c$-unstable prong connection, we have the following equality: 
\[
\mathrm{coheight}_{\mathrm{h},\F}(C) + \mathrm{coheight}_{\mathrm{p},\F}(C) = 0+ 1 = 1 = \mathop{\mathrm{coheight}_{\F}}(C)
\] 
By the definition of $p$-unstable prong connection, we have the following equality: 
\[
\mathrm{coheight}_{\mathrm{h},\F}(C) + \mathrm{coheight}_{\mathrm{p},\F}(C) = 0+ 1 = 1 = \mathop{\mathrm{coheight}_{\F}}(C)
\]

Conversely, suppose that $\mathrm{coheight}_{\mathrm{h},\F}(C) + \mathrm{coheight}_{\mathrm{p},\F}(C) = \mathop{\mathrm{coheight}_{\F}}(C) = 1$. 
By definition of coheight, we have $n_{\partial}(C) = n_{\mathrm{fake}}(C) = 0$. 
If $C$ is $c$-unstable, then the assertion holds. 
Thus we may assume that $C$ is not $c$-unstable and so has centers. 
Then $n_{V_-}(C) \geq 1$. 
From Lemma~\ref{lem:1_3_prongs}, the prong connection $C$ has a $4$-prong and there is a coheight-zero prong connection $C'$ with $n_V(C') - n_V(C) = n_{V_-}(C') - n_{V_-}(C) = 1$. 
Then $n_{V_-}(C') \geq 2$.
By Proposition~\ref{lem:ch_codim_zero_01}, the prong connection is of type either $b_o$, $b_i$, or $b_\theta$ and so $2 = n_{V_-}(C') = n_{V_-}(C')$.  
Therefore, we have $1 = n_{V_-}(C) = n_{V_-}(C)$. 
Since $C$ has a $4$-prong, the prong connection $C$ consists of one $4$-prong and two self-connected prong separatrices and so is $p$-unstable.
\end{proof}

\begin{proposition}\label{lem:ch_codim_one_00}
%Let $\F$ be a levelable foliation with finitely many pronged singular points on a surface $M$ and $D(\F)$ the prong connection diagram.  
%Then e
Each connected component $C$ of $D(\F)$ is coheight-one if and only if it satisfies exactly one ofthe following conditions:
\\
{\rm(1)} The prong connection $C$ is $b$-unstable. 
\\
{\rm(2)} The prong connection $C$ is $c$-unstable. 
\\
{\rm(3)} The prong connection $C$ is $f$-unstable. 
\\
{\rm(4)} The prong connection $C$ is $h$-unstable. 
%\\
%{\rm(4)} Any prongs in $D(\F)$ are $1$-prongs and $3$-prongs. 
\end{proposition}

\begin{proof}
Let $ C$ be a prong connection of $\F$. 
Notice that every prong connection $C$ is $b$-unstable (resp. $f$-unstable, $h$-unstable) if and only if $n_{\partial}(\F)  = \mathop{\mathrm{coheight}_{\F}}(C) = 1$ (resp. $n_{\mathrm{fake}}(\F) = \mathop{\mathrm{coheight}_{\F}}(C) = 1$, $\mathop{\mathrm{coheight}_{\mathrm{h},\F}}(C)  = \mathop{\mathrm{coheight}_{\F}}(C) = 1$). 
By Lemma~\ref{lem:plus_zero}, every prong connection $C$ is either $c$-unstable or $p$-unstable if and only if $\mathrm{coheight}_{\mathrm{h},\F}(C) + \mathrm{coheight}_{\mathrm{p},\F}(C) = \mathop{\mathrm{coheight}_{\F}}(C) = 1$. 
Thus if $C$ is either $b$-unstable, $c$-unstable, $f$-unstable, and $h$-unstable, then $\mathop{\mathrm{coheight}_{\F}}(C) = 1$. 

Conversely, suppose that $\mathop{\mathrm{coheight}_{\F}}(C) = 1$. 
Then $1 = \mathrm{coheight}_{\F}(C) =  n_{\partial}(C) + n_{\mathrm{fake}}(C) + \mathop{\mathrm{coheight}_{\mathrm{h},\F}}(C) +  \mathrm{coheight}_{\mathrm{p,\F}}(C)$. 
Since the right-hand side of the previous equality consists of non-negative integers $n_{\partial}(C)$, $n_{\mathrm{fake}}(C)$, and $\mathop{\mathrm{coheight}_{\mathrm{h},\F}}(C) +  \mathrm{coheight}_{\mathrm{p,\F}}(C)$, the prong connection $C$ is either $b$-unstable, $c$-unstable, $f$-unstable, and $h$-unstable. 
\end{proof}

The previous proposition implies Theorem~\ref{main:char}. 
Moreover, Proposition~\ref{lem:ch_codim_one_00} and Theorem~\ref{cor:tree_rep} imply the following statement. 

\begin{theorem}\label{th:tree_rep_codim_one}
Let $S$ be a compact surface contained in a sphere $\mathbb{S}^2$ and $\F$ a coheight-one levelable foliation. 
% tangent to the boundary $\partial S$. 
Then the Reeb graph of the height function of $\F$ on $S$ is a finite directed tree whose vertices of degree one are either a prong connection of type $\sigma$, a prong connection of type $\sigma_3$, or a periodic leaf on the boundary $\partial \mathbb{S}^2$, and whose vertrice of degree non-one are either $p_o$, $p_i$, $b_\theta$, $b_o$, $b_i$, or one of prong connections in Figure~\ref{fig:list_self_connected_prong}. 
\end{theorem}


\subsection{Open dense property and structural stability in the space of levelable foliations on  compact surfaces}

Denote by $\mathcal{L}^1_{i}(M)$ the subspace of levelable foliation in $\mathcal{L}^*_{i}(M) - \mathcal{L}^0_{i}(M)$ whose prong connection diagram is of coheight-one. 
Since any elements of $\mathcal{L}^*_{i}(M)$ contain no fake prongs, the prong connection diagrams of any elements of $\mathcal{L}^*_{i}(M)$ are either $b$-unstable, $c$-unstable, $p$-unstable, or $h$-unstable. 
We state generic intermediate graphs as follows. 


