\section{Examples of singular foliations on surfaces}

We have the following examples of singular foliations on surfaces. 

\begin{example}\label{ex:liftable}
{\rm
Let $\mathbb{K} := ([0,1]\times \mathbb{S}^1)/\mathop{\sim}$ be a Klein bottle where $\mathbb{S}^1 = \R/\Z$ and $(x,y) \sim (x',y')$ if $\{x, x' \} = \{ 0,1\}$ and $1-y \equiv y' \pmod 1$. 
The smooth foliation $\F_{\mathbb{K}} := \{ \{ [t]\} \times \mathbb{S}^1 \mid t \in [0,1) \}$ is a non-orientable foliation. 
Then we have the following observation. 

\begin{lemma}
The foliation $\F_{\mathbb{K}}$  is not liftable to a flow. 
\end{lemma}
\begin{proof}
Assume that $\F_{\mathbb{K}}$ is liftable to a flow. 
Then there is a foliation $(M, f, \theta)$ in the sense of Bronstein and Nikolaev. 
Since $\F_{\mathbb{K}}$ has no singularities, by definition of foliation in the sense of Bronstein and Nikolaev, the involution $\theta$ is a homeomorphism between Klein bottles. 
This implies that the set of orbits of the restriction $f$ to a Klein bottle is $\F_{\mathbb{K}}$. 
Therefore, $\F_{\mathbb{K}}$ is orientable, which contradicts that it is non-orientable. 
\end{proof}
}
\end{example}

\begin{example}\label{ex:liftable02}
{\rm
Let $\mathcal{G}$ be a smooth foliation on a torus $\mathbb{T} := (\R/\Z)^2$ defined by the set of orbits of a Hamiltonian vector field as shown on the left in Figure~\ref{disk_Hamiltonian}. 
\begin{figure}[t]
\begin{center}
\includegraphics[scale=0.375]{disk_Hamiltonian.pdf}
\end{center} 
\caption{Left, a smooth foliation $\mathcal{G}$ on a torus defined by the set of orbits of a Hamiltonian vector field; right, a non-orientable foliation $\F_{\T^2}$ whose lift along a covering of degree $4$ is the foliation $\mathcal{G}$. }
\label{disk_Hamiltonian}
\end{figure}
Taking a $(\Z_2)^2$-action on $\mathbb{T}^2$ generated by $1/2$-rotations with respect to the $x$-axis and the $y$-axis, the quotient space $\left( \R/\left(\frac{1}{2}\Z \right) \right)^2$, which is also a torus, has the induced non-orientable foliation $\F_{\T^2}$ as shown on the right in Figure~\ref{disk_Hamiltonian}.  
%
Then we have the following observation. 
\begin{lemma}
The foliation $\F_{\T^2}$ is not liftable to a flow. 
\end{lemma}

\begin{proof}
The non-orientable foliation $\F_{\T^2}$ has exactly two singular points, which are a center and a saddle (i.e. $4$-prong). 
Therefore, $\F_{\T^2}$ has no non-orientable singularities. 
%
Assume that $\F_{\T^2}$ is liftable to a flow. 
Then, there is a foliation $(M, f, \theta)$ in the sense of Bronstein and Nikolaev. 
Since $\F_{\T^2}$ has no singularities, by definition of foliation in the sense of Bronstein and Nikolaev, the involution $\theta$ is a homeomorphism between tori. 
This implies that the set of orbits of the restriction $f$ to a torus is $\F_{\T^2}$. 
Therefore, $\F_{\T^2}$ is orientable, which contradicts that it is non-orientable. 
\end{proof}
}
\end{example}



\begin{example}
{\rm
Let $\F_{\theta}$ be a regular foliation on a torus $\T^2 := \R^2/\Z^2$ which is the set of orbits of a vector field $X = (1,\theta)$ on $\T^2$. 
Equip $\T^2$ with the induced Riemannian metric from the standard Riemannian metric on $\R^2$. 
For any convergence sequence $(\theta_n)$ of real numbers to $\theta_\infty \in \R$, the sequence $(\F_{\theta_n})$ of regular foliations converges to the foliation $\F_{\theta_\infty}$. 
This implies that the regular foliation $\F_{\theta}$ on a torus $\T^2$ for any $\theta \in \R$ is not structurally stable. 
}
\end{example}


\begin{example}\label{ex:nonHam}
{\rm
Let $\mathbb{K} := ([0,1]\times \mathbb{S}^1)/\mathop{\sim}$ be a Klein bottle where $\mathbb{S}^1 = \R/\Z$ and $(x,y) \sim (x',y')$ if $\{x, x' \} = \{ 0,1\}$ and $1-y \equiv y' \pmod 1$. 
The vector field $X = (1,0)$ on $\mathbb{K}$ is not a Hamiltonian vector field, but the set of orbits is a levelable foliation that is not transversely orientable. 
}
\end{example}


\begin{example}\label{ex:rot_disk}
{\rm
Let $p \colon \R/\Z \times [-1,1] \to D := \{(x,y) \in \R^2 \mid x^2 + y^2 \leq 1\}$ be a branched covering with two ramification points of degree $2$ such that $p(t, \pm 1) = (\cos 2\pi t, \sin 2\pi t)$ as in Figure~\ref{disk_2prongs02}, and $\F_D$ a foliation on $D$ as in Figure~\ref{disk_2prongs02}. 
