\section{Flows and vector fields}\label{sec:flow}

\subsection{Flows}

Recall that a {\bf flow} on a manifold is a continuous $\R$-action on it.
Let $f \colon \R \times M \to M$ be a flow on a manifold $M$.
For $t \in \R$, define $f^t \colon X \to X$ by $f^t := f(t, \cdot )$.
For a point $x$ of $X$, we denote by $O(x)$ the orbit of $x$, $O^+(x)$ the positive orbit (i.e. $O^+(x) := \{ f^t(x) \mid t > 0 \}$), and $O^-(x)$ the negative orbit (i.e. $O^-(x) := \{ f^t(x) \mid t < 0 \}$).
A point $x$ of $X$ is {\bf singular} if $x = f^t(x)$ for any $t \in \R$, and is {\bf periodic} if there is a positive number $T > 0$ such that $x = f^T(x)$ and $x \neq f^t(x)$ for any $t \in (0, T)$.

\subsubsection{Non-wandering flows}

A point of a flow $f$ is {\bf wandering} if there are its neighborhood $U$ and a positive number $N$ such that $f^t(U) \cap U = \emptyset$ for any $t > N$. 
Such $U$ is called a {\bf wandering domain}. 

\begin{definition}\label{def:nw}
A point is {\bf non-wandering} if it is not wandering (i.e. for any its neighborhood $U$ and for any positive number $N$, there is a number $t \in \mathbb{R}$ with $|t| > N$ such that $f^t(U) \cap U \neq \emptyset$).
\end{definition}

Denote by $\Omega (f)$ the set of non-wandering points, called the non-wandering set. 
A flow is {\bf non-wandering} if the non-wandering set is the whole space. 

\subsection{Vector fields on surfaces}


\subsubsection{Divergence-free vector fields and Hamiltonian vector fields}
%A $C^r$ vector field $X$ for any $r \in \Z_{>0}$ on a surface is {\bf area-preserving} if the area form $\mu$ is preserved under pullback (i.e. $v_t^*(\mu) = \mu$) by homeomorphisms $v_t$ for any $t \in R$, where $v$ is the flow generated by $X$. 
Recall the following concepts. 

\begin{definition}A $C^r$ vector field $X$ for any $r \in \Z_{>0}$ on a surface with a Riemannian metric $g$ is {\bf divergence-free} if $\mathrm{div} X = 0$, where $\mathrm{div}X := \mathop{*} d \mathop{*} g(X, \cdot )$. 
\end{definition}

\begin{definition}\label{def:df}
A flow {\bf divergence-free} if it is topologically equivalent to a flow generated by a smooth divergence-free vector field. 
\end{definition}
%Note that the divergence $\mathrm{div} X$ can also be determined by a condition $\mathrm{div}X \mu = L_X \mu$ where $L_X$ is the Lie derivative along $X$. 
%Liouville's theorem implies the following observation.

\begin{definition}\label{def:Ham_vf}
A $C^r$ vector field $X$ for any $r \in \Z_{\geq0}$ on an orientable surface $S$ is {\bf Hamiltonian} if there is a $C^{r+1}$ function $H \colon S \to \mathbb{R}$, called a {\bf Hamiltonian},  such that $dH= \omega(X, \cdot )$ as a one-form, where $\omega$ is a volume form of $S$.
\end{definition}

In other words, locally, the Hamiltonian vector field $X$ is defined by $X = (\partial H/ \partial x_2, - \partial H/ \partial x_1)$ for any local coordinate system $(x_1,x_2)$ of a point $p \in S$.

\begin{definition}
A flow is {\bf Hamiltonian} if it is topologically equivalent to a flow generated by a smooth 
\end{definition}

Hamiltonian vector field.
Note that a volume form on an orientable surface is a symplectic form.


\section{Transversality for singular piecewise $C^1$-foliations}\label{def:trans}

Let $\F$ be a singular piecewise $C^1$-foliation on a surface $S$. 
We define transversality as follows.  

\begin{definition}
A curve $C$ is {\bf transverse} to $\F$ at a point $p \in C \setminus \partial S$ if there are a small neighborhood $U$ of $p$ and a homeomorphism $h:U \to [-1,1]^2$ with $h(p) = 0$ such that $h^{-1}([-1,1] \times \{t \})$ for any $t \in [-1, 1]$ is contained in a leaf of $\F$ and $h^{-1}(\{0\} \times [-1,1]) = C \cap U$. 
\end{definition}

When $S$ has the boundary, denote by $\hat{S}$ the double of $S$ and by $\hat{\mathcal F}$ the induced foliation on $\hat{S}$ from $\F$.
Recall that $\hat{S} = S \times \{0,1\}/\mathop{\sim}$ where $(x,0)\sim (x,1)$ if $x\in \partial M$. 

\begin{definition}
A curve $C$ is {\bf transverse} to $\F$ at a point $p \in C \cap \partial S$ if there is a curve $\widetilde{C} \subset \hat{S}$ transverse to $\hat{\F}$ such that the restriction $\pi \vert_{\widetilde{C}} \colon \widetilde{C} \to C$ is homeomorphic, where $\pi \colon \hat{S}= S \times \{0,1\}/\mathop{\sim} \to S$ is the canonical quotient map define by $p(x,0) = p(x,1) = x$.  
\end{definition}

A simple curve $C$ is transverse to $\F$ if it is transverse at any point in $C$.  
A simple curve $C$ which is transverse to $\F$ is called a {\bf transverse arc}.
A simple closed curve is a {\bf closed transversal} if it transverses $\F$.


