To demonstrate that the $\v$-number can be arbitrarily
larger than the degree of the $h$-polynomial, we describe a special construction of a graph built from a collection of graphs. We will then apply this construction to $n$ copies of the graph $G$ of \Cref{fig:11vertex}.

\noindent \textbf{Construction 1.} 
Let $G_1,\ldots,G_n$ be $n$ simple graphs. For each 
$1\leq i\leq n$, let $A_i\subseteq V(G_i)$ be such that
$\alpha(G_i)-\alpha(G_i\setminus A_i)=t_i\geq 1$ 
is odd and $\deg(G_i)-\deg(G_i\setminus A_i)=t_i-1$, 
where $\deg(G_i):=\deg(h_{R_i/I(G_i)}(t))$ with 
$R_i=\mathbb{K}[V(G_i)]$. Moreover, we assume that all the 
leading coefficients of the $h$-polynomials of 
$G_1,\ldots,G_n, G_1\setminus A_1,\ldots,G_n\setminus A_n$ are of the same sign, i.e., either all positive or all negative. Using the graphs $G_1,\ldots,G_n$ and the subsets of vertices $A_1,\ldots,A_n$, we construct a new graph $H_n$ as follows:
\begin{enumerate}
    \item[$\bullet$] $V(H_n)=V(G_1)\cup\cdots\cup V(G_n)\cup\{y_1,\ldots,y_n\}$.
    \item[$\bullet$] $E(H_n)=E(G_1)\cup\cdots\cup E(G_n)\cup\{\{y_{i},x\}\mid x\in A_i, i\in [n]\}\cup \{\{y_i,y_j\}\mid i\neq j\}$.
\end{enumerate}

\begin{lemma}\label{lem:deg}
    Let $H_n$ be the graph as in Construction 1 and $R=\mathbb{K}[V(H_n)]$. Then
    $$\dim(R/I(H_n))=\sum_{i=1}^{n}\alpha(G_i) \text{ and } \deg(h_{R/I(H_n)}(t))=1 + \sum_{i=1}^{n}\deg(h_{R_{i}/I(G_i)}(t)).$$
\end{lemma}
\begin{proof}
    For simplicity, we use the notation introduced in 
    Construction 1. We first prove the dimension formula. 

    Let $A$ be a maximal independent set of $H_n$ such that $\alpha(H_n)=\vert A\vert$, i.e., $\dim(R/I(H_n))=\vert A\vert$. Since there is no edge from $G_i$ to $G_j$ ($i\neq j$), a union of independent sets of $G_1,\ldots,G_n$ will also be an independent set in $H_n$. Thus, $\vert A\vert \geq \sum_{i=1}^{n}\alpha(G_i)$. 

    If $A\cap \{y_1,\ldots,y_n\}=\emptyset$, 
    then $\vert A\cap V(G_i)\vert\leq\alpha(G_i)$ for 
    each $1\leq i\leq n$. In this case, 
    $A\cap V(G_1),\ldots,A\cap V(G_n)$ forms
    a partition of $A$, and thus, 
    $\vert A\vert\leq\sum_{i=1}^{n}\alpha(G_i)$, thus
    giving the desired conclusion. On the
    other hand, suppose 
    $A\cap \{y_1,\ldots,y_n\}\neq \emptyset$. 
    Since the induced subgraph on $\{y_1,\ldots,y_n\}$ is
    a complete graph, and since $A$ is an independent set, we have $\vert A\cap\{y_1,\ldots,y_n\}\vert=1$. 
    Without loss of generality, we assume $y_1\in A$. 
    Since $\{y_1,x\}\in E(H_n)$ for every $x\in A_1$, 
    $A\cap V(G_1)=A\cap V(G_1\setminus A_1)$. Note that 
    $\vert (A\cap V(G_1))\cup\{y_1\}\vert =\vert A\cap 
    V(G_1\setminus A_1)\vert+1\leq
    \alpha(G_1\setminus A_1)+1\leq \alpha(G_1)$ 
    by our construction. In this case, the sets 
    $(A\cap V(G_1))\cup\{y_1\}, A\cap V(G_2),\ldots,
    A\cap V(G_n)$ forms a partition of $A$. Therefore, 
    $\vert A\vert\leq \sum_{i=1}^{n}\alpha(G_i)$, which 
    gives the desired conclusion in this case.  The
    formula for the dimension thus holds.

    We now prove the formula for the degree of the
    $h$-polynomial.  Recall that we write
    $\deg(G)$ for $\deg(h_{R/I(G)}(t))$. We also write $c(G)$ for the leading coefficient of  $h_{R/I(G)}(t)$. We now prove by 
    induction that $\deg(H_n)=1+\sum_{i=1}^{n}\deg(G_i)$ and the sign of $c(H_n)$ is positive (or negative)  if $c(G_i)$ and $c(G_i\setminus A_i)$ are all positive (or negative) for all $1\leq i\leq n$.


    For $n=1$, consider the following short exact sequence:
    $$0\rightarrow (R/I(H_1):(y_1))(-1)
    \stackrel{\times y_1}{\longrightarrow} R/I(H_1)\rightarrow R/(I(H_1)+(y_1))\rightarrow 0.$$
    Note that $I(H_1):(y_1)=(A_1)+I(G_1\setminus A_1)$ and $I(H_1)+(y_1)=(y_1)+I(G_1)$. Therefore, by the additivity of the Hilbert series on the above short exact sequence, we get
     \begin{align*}
        H_{R/I(H_1)}(t)&=t\cdot H_{R/I(H_1):(y_1)}(t)+H_{R/(I(H_1)+(y_1))}(t)\\
        &=\frac{t\cdot h_{R/I(G_1\setminus A_1)}(t)}{(1-t)^{1+\alpha(G_1\setminus A_1)}}+\frac{h_{R/I(G_1)}(t)}{(1-t)^{\alpha(G_1)}}\\
        &=\frac{t\cdot (1-t)^{t_1-1}\cdot h_{R/I(G_1\setminus A_1)}(t)+h_{R/I(G_1)}(t)}{(1-t)^{\alpha(G_1)}}.
    \end{align*}
    For the last equality, we are using the
    fact that $1 + \alpha(G_1\setminus A_1) +(t_1-1) =\alpha(G_1)$
    from our construction. Now $\deg(G_1\setminus A_1) +
    t_1 = \deg(G_1)+1$, by our construction's assumption.
    Therefore, from the above equation, we have 
    $\deg(H_1)=\deg(G_1)+1$. Since $t_1-1$ is even, 
    the leading coefficient of $(1-t)^{t_1-1}$ is positive
    (in fact, it is $1$), and so we 
    have $c(H_1)=c(G_1\setminus A_1)$. Hence, 
    the base case of the induction is true. 

    Now, for any $n\geq 2$, we consider the following 
    short exact sequence:
    \begin{equation}\label{eq1}
        0\rightarrow (R/I(H_n):(y_n))(-1)
        \stackrel{\times y_n}{\longrightarrow} R/I(H_n)\rightarrow R/(I(H_n)+(y_n))\rightarrow 0.
    \end{equation}
    Note that $$I(H_n):(y_n)=(y_1,\ldots,y_{n-1})+
    (A_n)+I(G_n\setminus A_n)+I(G_1)+\cdots+I(G_{n-1}).$$ 
    Then we have 
    $$\dim(R/I(H_n):(y_n))=1+
    \alpha(G_n\setminus A_n)+\sum_{i=1}^{n-1}\alpha(G_i)=
    1-t_n+\sum_{i=1}^{n}\alpha(G_i).$$ 
    By \Cref{lem:reg-deg-v} (iii) and by the conditions 
    of the construction
    $$\deg(h_{R/I(H_n):(y_n)}(t))=
    1-t_n+\sum_{i=1}^{n}\deg(G_i).$$ 
    Now, consider the ideal 
    $I(H_n)+(y_n)=I(H_{n-1})+I(G_n)+(y_n)$. 
    Then, we have 
    $\mathrm{dim}(R/(I(H_n)+(y_n))) = \sum_{i=1}^{n}\alpha(G_i)$. 
    Also, by the induction hypothesis and \Cref{lem:reg-deg-v} (iii), it follows that 
    $$\deg(h_{R/(I(H_n)+(y_n))}(t))=1+\sum_{i=1}^{n}\deg(G_i).$$
    Using the additivity of the Hilbert series 
    on the short exact sequence \eqref{eq1}, we get
     \begin{align*}
        H_{R/I(H_n)}(t)&=t\cdot H_{R/I(H_n):(y_n)}(t)+H_{R/(I(H_n)+(y_n))}(t)\\
        &=\frac{t\cdot h_{R/I(H_n):(y_n)}(t)}{(1-t)^{1-t_n+\sum_{i=1}^{n}\alpha(G_i))}}+\frac{h_{R/(I(H_n)+(y_n))}(t)}{(1-t)^{\sum_{i=1}^{n}\alpha(G_i)}}\\
        &=\frac{t\cdot (1-t)^{t_n-1}\cdot h_{R/I(H_n):(y_n)}(t)+h_{R/(I(H_n)+(y_n))}(t)}{(1-t)^{\sum_{i=1}^{n}\alpha(G_i)}}.
    \end{align*}

    By the given condition on the sign of the leading 
    coefficient of the $h$-polynomials, we can verify that 
    the sign of the leading coefficients of both 
    $h_{R/I(H_n):(y_n)}(t)$ and $h_{R/(I(H_n)+(y_n))}(t)$ 
    are the same (either positive or negative). Also, it 
    is given that $t_n-1$ is even. Therefore, using the 
    above equation and the formulas of the $h$-polynomials 
    of $R/I(H_n):(y_n$) and $R/(I(H_n)+(y_n))$, we obtain 
    $\deg(H_n)=1+\sum_{i=1}^{n}\deg(G_i)$ (the fact that the leading coefficients have the same sign ensures that the top coefficient is not canceled, so that the degree of the $h$-polynomial can be computed from 
    the displayed equation above). The claim for 
    $c(H_n)$ follows immediately. This now completes
    the induction proof.
\end{proof}

\noindent 
\textbf{Construction 2.} Let $G_1,\ldots,G_n$ be $n$ simple non-empty graphs. For each $1\leq i\leq n$, let $A_i\subseteq V(G_i)$ be such that $\v(I(G_i))\geq 1+\v(I(G_i\setminus A_i))$. Using the graphs $G_1,\ldots,G_n$ and the subsets of vertices $A_1,\ldots,A_n$, we construct a new graph $H_n$ as follows:
\begin{enumerate}
    \item[$\bullet$] $V(H_n)=V(G_1)\cup\cdots\cup V(G_n)\cup\{y_1,\ldots,y_n\}$.
    \item[$\bullet$] $E(H_n)=E(G_1)\cup\cdots\cup E(G_n)\cup\{\{y_{i},x\}\mid x\in A_i, i\in [n]\}\cup \{\{y_i,y_j\}\mid i\neq j\}$.
\end{enumerate}

\begin{lemma}\label{lem:v-num}
    Let $H_n$ be the graph as in Construction 2. Then for $n\geq 2$
    $$\v(I(H_n))=\min_{1\leq i\leq n} \left\{1+\v(I(G_i\setminus A_i))+\sum_{j\in [n]\setminus \{i\}}\v(I(G_j))\right\}.$$
\end{lemma}

\begin{proof}
    Fix any $i\in [n]$. For each 
    $j\in [n]\setminus \{i\}$, choose an 
    independent set $B_j$ of $G_j$ such that 
    $\vert B_j\vert=\v(I(G_j))$ and $N_{G_j}(B_j)$ is a 
    minimal vertex cover of $G_j$, i.e.,  
    $I(G_j):(\mathbf{x}_{B_j}) = (N_{G_j}(B_j))$. 
    Again, choose an independent set $B_i$ of 
    $G_i\setminus A_i$ such that 
    $N_{G_i\setminus A_i}(B_i)$ is a minimal vertex cover 
    of $G_i\setminus A_i$ with $\vert B_i\vert=\v(I(G_i\setminus A_i))$. 

    We now take $B=\{y_i\}\cup B_1\cup\cdots\cup B_n$. 
    It follows from Construction 2  that in the graph $H_n$
    the set $B$ is an independent set of $H_n$, and 
    $N_{H_n}(B_n)$ is a minimal vertex cover of $H_n$. 
    In particular, $I(H_n):(\mathbf{x}_{B})=(N_{H_n}(B))$, and thus, we have 
    $$\v(I(H_n))\leq 1+\v(I(G_i\setminus A_i))+\sum_{j\in [n]\setminus \{i\}}\v(I(G_j)).$$
    Since $i$ was chosen arbitrarily from $[n]$, it follows that 
    $$\v(I(H_n))\leq \min_{1\leq i\leq n} \left\{1+\v(I(G_i\setminus A_i))+\sum_{j\in [n]\setminus \{i\}}\v(I(G_j))\right\}.$$

    For the reverse inequality, suppose $B'$ is an 
    independent set of $H_n$ such that $N_{H_n}(B')$ is a minimal vertex cover of $H_n$ and 
    $\vert B'\vert=\v(I(H_n))$. 
    If $B'\cap \{y_1,\ldots,y_n\}=\emptyset$, then 
    $\vert B'\cap V(G_i)\vert\geq \v(I(G_i))$ for each 
    $1\leq i\leq n$ because 
    $B'\cap V(G_i)$ is an independent 
    set of $G_i$ and $N_{G_i}(B'\cap V(G_i))$ is a vertex 
    cover of $G_i$. Since it is given that 
    $\v(I(G_i))\geq 1+\v(I(G_i\setminus A_i))$ for each 
    $i\in [n]$, we have $$\vert B'\vert \geq \min_{1\leq i\leq n} \left\{1+\v(I(G_i\setminus A_i))+\sum_{j\in [n]\setminus \{i\}}\v(I(G_j))\right\},$$
    thus finishing the proof in this case. 

    Now, let us assume 
    $A\cap \{y_1,\ldots,y_n\}\neq \emptyset$. 
    Then $\vert B'\cap \{y_1,\ldots,y_n\}\vert=1$ because 
    the induced graph
    on $\{y_1,\ldots,y_n\}$ is a complete graph and 
    $B'$ is an independent set. Without loss of 
    generality, we may assume $B'\cap\{y_1,\ldots,y_n\}=\{y_1\}$. 
    Now, consider the ideal $I(H_n):(y_1)=(A_1)+ (y_2,\ldots,y_n)+I(G_1\setminus A_1)+I(G_2)+\cdots+I(G_n)$.
    By Lemma \ref{lem:reg-deg-v} (iv) 
    %\textcolor{blue}{(or
    %\cite[Proposition 3.8]{v-edge},
    %\cite[Proposition 3.9]%{ssvmon22})}\textbf{I think we should omit this}, 
    we have $$\v(I(H_n):(y_1))=\v(I(G_1\setminus A_1))+\sum_{j=2}^{n}\v(I(G_j)).$$ Because 
    each $G_i$ is a non-empty graph, we have $\v(I(H_n))>1$. Thus, from the proof of \cite[Proposition 3.12(c)]{v-edge} (or \cite[Proposition 3.13(iii)]{ssvmon22}) it follows that $$\v(I(H_n))\geq 1+\v(I(H_n):(y_1))=1+\v(I(G_1\setminus A_1))+\sum_{j=2}^{n}\v(I(G_j)).$$ Consequently, we have 
    $$\v(I(H_n))\geq \min_{1\leq i\leq n} \left\{1+\v(I(G_i\setminus A_i))+\sum_{j\in [n]\setminus \{i\}}\v(I(G_j))\right\}.$$
    This completes the proof.
    \end{proof}


The previous lemmas now allow us to prove the first major result of this section.

\begin{theorem}\label{Thm:d<v}
    For every positive integer $n$, there exists a connected graph $H$ such that 
    $$\mathrm{v}(I(H))-\mathrm{deg}(h_{R/I(H)}(t))=n.$$
\end{theorem}

\begin{proof}
    For every positive integer $n$, let us construct a new 
    graph $H_n$ using $n$ copies of the graph $G$ given 
    in \Cref{fig:11vertex} and a complete graph $K_n$ 
    on $n$ vertices. Let $G_{i}$ be the graph isomorphic 
    to $G$ with $V(G_i)=\{x^{(i)}_1,\ldots, x^{(i)}_{11}\}$
    and using the isomorphism $x^{(i)}_j$ goes to $x_j$. 
    Now we define $H_n$ as follows:
    \begin{enumerate}
    \item[$\bullet$] $V(H_n)=V(G_1)\cup\cdots\cup V(G_n)\cup\{y_1,\ldots,y_n\}$, and
    \item[$\bullet$] $E(H_n)=E(G_1)\cup\cdots\cup E(G_n)\cup\{\{y_{i},x^{(i)}_j\}\mid j\in[5], i\in [n]\}\cup \{\{y_i,y_j\}\mid i\neq j\}$.
\end{enumerate}
Observe that we are attaching each $y_i$ to the five
vertices $\{x_1^{(i)},x_2^{(i)},x_3^{(i)},x_4^{(i)},x_5^{(i)}\}$ 
in each copy of $G$ in \Cref{fig:11vertex}.

Note that for the edge ideal of a graph, the degree of 
the corresponding $h$-polynomial and the $\v$-number 
does not depend on the characteristic of the base field.
If we let $A = \{x_1,\ldots,x_5\}$,
then  one can check using {\it Macaulay2} that 
the reduced Hilbert series of $\mathbb{K}[V(G)]/I(G)$ and 
$\mathbb{K}[V(G\setminus A)]/I(G\setminus A)$
are given by
$$H_{\mathbb{K}[V(G)]/I(G)}(t) = \frac{1+8t+11t^2}{(1-t)^3}
~~\mbox{and}~~
H_{\mathbb{K}[V(G\setminus A)]/I(G\setminus A)}(t) 
=\frac{1+4t+t^2}{(1-t)^2}.$$
Thus  $\alpha(G)=3$, $\alpha(G\setminus A)=2$, 
$\deg(G)=2$, 
$\deg(G\setminus A)=2$,
and also the leading coefficients of
the $h$-polynomial of 
$\mathbb{K}[V(G)]/I(G)$ and $\mathbb{K}[V(G\setminus A)]/I(G\setminus A)$ have the same
sign. We also use {\it Macaulay2} to 
compute
$\v(I(G))=3$ 
and $\v(I(G\setminus A))=2$. 
Therefore, by considering 
$A_i = \{x^{(i)}_1,\ldots,x^{(i)}_5\}$, we have $\alpha(G_i)-\alpha(G_i\setminus A_i)=1$, $\deg(G_i)-\deg(G_i\setminus A_i)=0=1-1$, and $3=\v(I(G_i))\geq 1+\v(I(G_i\setminus A_i))=3$. 

Hence, the graph $H_n$ satisfies the conditions given in both Construction 1 and Construction 2. 
%In other words, the graph $H_n$ can be viewed as a graph described in both Construction 1 and Construction 2. 
Thus, by \Cref{lem:deg} and \Cref{lem:v-num}, it follows that
$$\v(I(H_n))=3n \text{ and } \deg(H_n)=1+2n.$$
Thus for  any integer $n \geq 1$,
 $H=H_{n+1}$ satisfies $\mathrm{v}(I(H))-\mathrm{deg}(h_{R/I(H)}(t))=n$.
    \end{proof}

For the next main result, we need to know the Hilbert series of complete graphs and star graphs. A 
{\it star graph} on $n$ vertices, denoted by $K_{1,n-1}$, is a graph in which, after relabeling the vertices, we have $V(K_{1,n-1})=\{x_1,\ldots,x_n\}$ and $E(K_{1,n-1})=\{\{x_1,x_i\}\mid 2\leq i\leq n\}$. The Hilbert series of edge ideals for complete and star graphs are likely well-established or can be inferred as direct consequences of earlier works. However, due to the absence of a suitable reference, we include 
a short proof.

\begin{proposition}\label{prop:hilb-complete-star}
    The Hilbert series of the edge ideals of complete and star graphs are:
    \begin{enumerate}
    \item[(i)] $H_{R/I(K_n)}(t)=\frac{1+(n-1)t}{(1-t)}$, and
    \item[(ii)] $H_{R/I(K_{1,n-1})}(t)=\frac{1+t(1-t)^{n-2}}{(1-t)^{n-1}}$.
\end{enumerate}
\end{proposition}

\begin{proof}
    For a simple graph $G$, there is a nice combinatorial interpretation of $H_{R/I(G)}(t)$ in terms of the independent sets of $G$ due to Stanley \cite{stanley96}, which is given by
    \begin{equation}\label{eq:stanleyform}
H_{R/I(G)}(t)=\sum_{i=0}^{\alpha(G)}\frac{f_{i-1}t^{i}}{(1-t)^{i}},
\end{equation}
where $f_{i-1}$ denotes the number of independent sets of cardinality $i$ in $G$ (by convention $f_{-1} = 1$). For the complete graph $K_n$, we have $f_{-1}=1$, $f_0=n$, and $f_{i}=0$ for $i\geq 1$, and 
for $K_{1,n}$ we have $f_{-1}=1$, $f_0 = n$, and $f_{i} 
=\binom{n-1}{i+1}$ for $i=1,\ldots,n-2$. The formulas
in the statement are followed by using \eqref{eq:stanleyform}
and these specific values.
\end{proof}


We now prove our second main result that for any non-negative integer $m$, there exists a connected graph $G$ with $\deg(h_{R/I(G)}(t)) - \v(I(G))=m$. In fact, we prove the stronger result that for all $1 \leq v \leq d$, there is a connected graph $G$ with $(v,d) = (\v(I(G)),\deg(h_{R/I(G)}(t)))$. We 
require the following construction.

\noindent 
\textbf{Construction 3.}  For any integers $1 \leq v \leq d$, define the graph $G = H(v,d)$ to be the graph with the vertex set
$V(G) = \{x_i,y_i,w_i ~|~ 1 \leq i \leq v\} \cup
\{z_1,\ldots,z_{d-v}\}$
and edge set
\begin{eqnarray*}
E(G) &=& \{\{x_i,y_i\},\{y_i,w_i\},\{w_i,x_i\} ~|~ 1 \leq
i \leq v\} \cup \{\{x_1,x_i\} ~|~ 2 \leq i \leq v\} \\
& & \cup ~\{\{w_1,z_j\} ~|~ 1 \leq j \leq d-v\}.
\end{eqnarray*}
In other words, $G$ consists of $v$ triangles,
a $K_{1,v-1}$ on the vertices $\{x_1,\ldots,x_v\}$,
and  $d-v$ leaves attached to the vertex $w_1$.
The graph $H(4,7)$ is given in Figure \ref{fig(v,d)}.


