\begin{theorem}\label{thm:v<=d}
    For all integers $1 \leq v \leq d$, there exists a connected graph $G$
    with $(v,d) = (\v(I(G)),\deg(h_{R/I(G)}(t)))$.
\end{theorem}

\begin{proof}
Let $G = H(v,d)$ be the graph of Construction 3.  We 
will show that this graph satisfies $(v,d) = (\v(I(G)),\deg(h_{R/I(G)}(t)))$. 

We first show that $\v(I(G))=v$. Consider the set of 
vertices $A=\{y_1,x_2,\ldots,x_v\}$. 
Then from the construction of $G$, one can see
that $A$ is an independent set of $G$ and 
$N_{G}(A)$ is a minimal vertex cover of $G$. Thus, 
$I(G):(\mathbf{x}_{A})=(N_G(A))$.  Since 
$\vert A\vert =v$, it follows that $\v(I(G))\leq v$.   

Now let $B$ be an independent set of $G$ such that 
$N_G(B)$ is a minimal vertex cover of $G$, i.e., 
$I(G):(\mathbf{x}_{B})=(N_G(B))$. 
Since $N_G(B)$ is a minimal vertex cover of $G$, 
it must contain at most two elements of $\{x_i,y_i,w_i\}$
for each $1 \leq i \leq v$.  Indeed, if $N_G(B)$ contained
all three vertices $\{x_i,y_i,w_i\}$ 
for some $i$, we can remove $y_i$ and still have a
vertex cover, contradicting the minimality of $N_G(B)$.
Consequently, $\{x_i,y_i,w_i\}\cap B\neq \emptyset$ 
for each $1\leq i\leq v$. 
Because these $v$ sets are all disjoint, 
it follows that $|B| \geq v$.  
Since $B$ was chosen arbitrarily from 
$\mathcal{A}_{G}$, we have $\v(I(G))\geq v$, 
and consequently, $\v(I(G))=v$.

We now verify that $\deg(h_{R/I(G)}(t))=d$. 
Consider the following short exact sequence:
$$0\longrightarrow (R/I(G):(x_1))(-1) 
\stackrel{\times x_1}{\longrightarrow} 
R/I(G)\longrightarrow R/(I(G)+(x_1))\longrightarrow 0.$$
By the additivity of the Hilbert series on the short exact sequence, we get 
    \begin{align}\label{eq2}
        H_{R/I(G)}(t)=t\cdot H_{R/I(G):(x_1)}(t)+H_{R/(I(G)+(x_1))}(t).
    \end{align}

    The ideal $I(G):(x_1)=(x_2,\ldots,x_v,y_1,w_1)+I(G')$, 
    where $G'$ is a disjoint union of the graphs 
    $H_1,\ldots, H_v$ where $H_1$ is the graph of
    the isolated vertices $\{z_1,\ldots,z_{d-v}\}$ and 
    $H_i$ is the graph of the edge $\{y_i,w_i\}$ 
    for $2 \leq i \leq v$. In other words, $H_i 
    \cong K_2$ for $2 \leq i \leq v$.
    Thus, $\dim(R/I(G):(x_1))=1+(d-v)+(v-1)=d$, and by \Cref{lem:reg-deg-v} (ii) and \Cref{prop:hilb-complete-star}, we have
    \begin{align*}
        H_{R/I(G):(x_1)}(t)&=\frac{1}{(1-t)^{d-v+1}}\cdot \underbrace{\frac{1+t}{1-t}\,\,\cdots\,\,  \frac{1+t}{1-t}}_{(v-1) \text{ times}}=\frac{(1+t)^{v-1}}{(1-t)^{d}}.
    \end{align*}
    From the above expression, we see that $\deg(h_{R/I(G):(x_1)}(t))=v-1$ and the leading coefficient of $h_{R/I(G):(x_1)}(t)$ is $1$. 

    The ideal $I(G)+(x_1)= 
    I(G'') + (x_1)$, 
    where $G''$ is a disjoint union of the graphs $L_1,\ldots, L_v$ 
    where $L_1$ is the induced graph on $\{y_1,w_1,
    z_1,\ldots,z_{d-v}\}$ and $L_i$ the induced
    graph on $\{x_i,y_i,w_i\}$ for $2 \leq i \leq v$.
    Note that $L_1 \cong K_{1,d-v+1}$ and $L_i
    \cong K_3$ for $2 \leq i \leq v$.
    Thus, $\dim(R/I(G)+(x_1))=(d-v+1)+(v-1)=d$. Again, by \Cref{lem:reg-deg-v} (ii) and \Cref{prop:hilb-complete-star}, 
    \begin{align*}
        H_{R/(I(G)+(x_1))}(t)&=\frac{t(1-t)^{d-v}+1}{(1-t)^{d-v+1}}\cdot \underbrace{\frac{1+2t}{1-t}\,\,\cdots\,\,  \frac{1+2t}{1-t}}_{(v-1) \text{ times}}\\
        &=\frac{t(1+2t)^{v-1}(1-t)^{d-v}+(1+2t)^{v-1}}{(1-t)^{d}}.
    \end{align*}
From the above expression, we see that 
$\deg(h_{R/(I(G)+(x_1))}(t))=d$ as $v-1<d$ and the 
leading coefficient of $h_{R/(I(G)+(x_1))}(t)$ is $(-1)^{d-v}\cdot 2^{v-1}$. 

Now, for $v<d$, it follows directly from \eqref{eq2} that $\deg(h_{R/I(G)}(t))=d$. Suppose $v=d$.  In this
case both polynomials that appear in the numerator
of \eqref{eq2} have degree $d$.
By comparing the leading coefficients of $t\cdot h_{R/I(G):(x_1)}(t)$ and $h_{R/I(G):(x_1)}(t)$, the top coefficients
do not cancel, and thus \eqref{eq2} implies 
that $\deg(h_{R/I(G)}(t))=d$.
\end{proof}

