In the next four examples, we make use of the graph of \Cref{fig:11vertex} to construct our examples.

\begin{example}[{$d=r<v$ and $d<v=r$}]\label{ex:5.7}{\rm
    Consider the graph $G$ as shown in \Cref{fig:11vertex}. Then, using {\it Macaulay2}, we get $d=2$ and $v=3$ as mentioned in the proof of \Cref{Thm:d<v}. Also, taking $\mathbb{K}=\mathbb{Q}$ and using {\it Macaulay2}, one can verify that $r=2$. Thus, in this case, we have $d=r<v$. Again, if we consider $\K=\ZZ/2\ZZ$, then we have $r=3$, and the $d$ and $v$ will be the same as they do not depend upon the characteristics of the base field. Thus, in this case, we have $d<v=r$.   This example originally came from
    work of Jaramillo and Villarreal \cite{v-edge}.
    }
\end{example}

\begin{example}[{$r<d=v$}]\label{ex:5.8}{\rm
    Consider the graph $G$ as shown in \Cref{fig:11vertex}. Now construct a graph $H$ such that 
    \begin{enumerate}
        \item[$\bullet$] $V(H)=V(G)\cup\{y\}$, and 
        \item[$\bullet$] $E(H)=E(G)\cup \{\{x_1,y\},\{x_2,y\},\{x_3,y\},\{x_4,y\}\}$.
    \end{enumerate}
   Then, using {\it Macaulay2} we find
   $\deg(h_{R/I(H)}(t))=\v(I(H))=3$ and $\reg(R/I(H))=2$, where $R=\mathbb{Q}[V(H)]$. Consequently, 
   we have $r<d=v$ in this case.
    }
\end{example}

\begin{example}[{$r<v<d$}]\label{ex:5.9}{\rm
    Again, let $G$ be as in  \Cref{fig:11vertex}
    and consider the graph $H$ defined as follows:
    \begin{enumerate}
        \item[$\bullet$] $V(H)=V(G)\cup \{y_1,y_2\}$, and 
        \item[$\bullet$] $E(H)=E(G)\cup \{\{x_i,y_1\},\{x_i,y_2\}\mid 1\leq i\leq 4\}$.
    \end{enumerate}
    Then we can use {\it Macaulay2} to find that 
    $$\reg(R/I(H))=2<\v(I(H))=3<\deg(h_{R/I(H)}(t))=4,$$ where $R=\mathbb{Q}[V(H)]$. Therefore, we have $r<v<d$ in this case.
    }
\end{example}

\begin{example}[{$r<d<v$ and $d<v<r$}]\label{ex:5.10}{\rm
     Let us construct a graph $H_n$ using $n$ copies of the graph $G$ given in Figure \ref{fig:11vertex}. Let $G_{i}$ be the graph isomorphic to $G$ with $V(G_i)=\{x^{(i)}_1,\ldots, x^{(i)}_{11}\}$ and the isomorphism $x^{(i)}_j$ goes to $x_j$. Now we define $H_n$ as follows:
     \begin{enumerate}
    \item[$\bullet$] $V(H_n)=V(G_1)\cup\cdots\cup V(G_n)\cup\{y_1,\ldots,y_n\}$,
    \item[$\bullet$] $E(H_n)=E(G_1)\cup\cdots\cup E(G_n)\cup\{\{y_{i},x^{(i)}_j\}\mid j\in [11], i\in [n]\}\cup \{\{y_i,y_j\}\mid i\neq j\}$.
\end{enumerate}
\noindent Recall that $[m] = \{1,\ldots,m\}$ for a positive integer $m$.

\noindent\textbf{Claim:} For every $n\geq 1$, we have $\deg(h_{R/I(H_n)}(t))=2n+1$, $\v(I(H_n))=3n-2$, and 
$$\reg(R/I(H_n))=
\begin{cases}
    2n \quad\text{ if } \mathbb{K=Q},\\
    3n \quad\text{ if } \mathbb{K=Z}/2\mathbb{Z}.
\end{cases}
$$ 
\textit{Proof of the claim.} 
For a square-free monomial ideal, 
the degree of the $h$-polynomial and the $\v$-number does not 
depend upon the characteristic of the base field. Thus, one can 
easily check using {\it Macaulay2} that $\alpha(G)=3$, 
$\alpha(G\setminus \{x_1,\ldots,x_{11}\})=0$, $\deg(G)=2$, 
$\deg(G\setminus \{x_1,\ldots,x_{11}\})=0$, $\v(I(G))=3$, 
$\v(I(G\setminus \{x_1,\ldots,x_{11}\}))=0$.
As shown in the proof of Theorem \ref{Thm:d<v}, the 
leading coefficient of $h_{R/I(G)}(t)$ is positive.  
Also, since $G \setminus \{x_1,\ldots,x_n\}$ is empty, 
the associated $h$-polynomial is $1$, whose leading coefficient is clearly positive. Therefore, by considering $A_i=\{x^{(i)}_1,\ldots,x^{(i)}_{11}\}$, we have $\alpha(G_i)-\alpha(G_i\setminus A_i)=3$, 
$\deg(G_i)-\deg(G_i\setminus A_i)=2=3-1$, and 
$3=\v(I(G_i))\geq 1+\v(I(G_i\setminus A_i))=1$. Hence, 
the graph $H_n$ can be viewed as a graph described in both 
Construction 1 and Construction 2. Thus, by \Cref{lem:deg} and 
\Cref{lem:v-num}, it follows that 
$\deg(h_{R/I(H_n)}(t))=1+n\cdot\deg(G)=2n+1$ and $\v(I(H_n))=1+0+3(n-1)=3n-2$.

Now, we prove $\reg(R/I(H_n))=2n$ if $\mathbb{K=Q}$. The base case $n=1$ can be verified directly using {\it Macaulay2}. Let us consider the 
following short exact sequence
$$0\rightarrow (R/I(H_n):(y_n))(-1)
\stackrel{\times y_n}{\longrightarrow} R/I(H_n)\rightarrow R/(I(H_n)+(y_n))\rightarrow 0.$$
    From the description of $I(H_n):(y_n)$ and $I(H_n)+(y_n)$ as given earlier in the proof of \Cref{lem:deg} and using the induction hypothesis, we have $\reg(R/I(H_n):(y_n))=2n-2$ and $\reg(R/(I(H_n)+(y_n)))=2n$. Since $\reg(R/I(H_n))\geq\reg(R/(I(H_n)+(y_n)))$, it follows that $\reg(R/I(H_n))= 2n$ by the regularity lemma
    (see \cite[Theorem 4.6]{CHHVT}). The case $\mathbb{K=Z}/2\mathbb{Z}$ is similar, but we make use of the fact that in the base case,
     $\reg(R/I(H_1)) = 3$.
}

Because of the claim, for $n \geq 4$, we have $r < d < v$ if 
$\mathbb{K} = \mathbb{Q}$, and $d < v < r$ if $\mathbb{K}=
\mathbb{Z}/2\mathbb{Z}$.
\end{example}


