\subsection{Local zeta integrals of Godement--Jacquet} % (fold)
\label{sub:local_zeta_integrals_of_godement_jacquet}

Finally we briefly recall the theory of local zeta integrals developed by Godement--Jacquet \cite{MR342495}. Let $\left(\pi, V\right)$ be an irreducible representation of $G_n$. For a complex variable $s\in\C$, a test function $\varphi\in\calS\left(M_{n,n}\right)$ and a matrix coefficient $f$ of $\pi$, one can define the zeta integral
\[
    Z\left(s,\varphi,f\right) = \int_{G_n}\varphi\left(g\right) f\left(g\right)|\det g|^{s+\frac{n-1}{2}}\, dg,
\]
where $dg$ is a fixed Haar measure of $G_n$. This integral is absolutely convergent when ${\rm Re}\left(s\right)$ is sufficiently large, and admits a meromorphic continuation to the whole complex plane $\C$. Indeed, one knows that $Z\left(s,\varphi,f\right)$ is a rational function in $\C\left(q^{-s}\right)$. Let $\varphi$ and $f$ vary. Then all these zeta integrals form a finitely generated fractional ideal of $\C\left[q^s,q^{-s}\right]$. Godement and Jacquet showed that there exists a \textit{greatest common divisor} of all these zeta integrals, which is of the form
\[
    L\left(s,\pi\right) = \frac{1}{P\left(q^{-s}\right)},
\]
with $P\left(X\right)$ a polynomial in $X$ independent of $\varphi$ or $f$, and the constant term of $P\left(X\right)$ equals to $1$. This $L\left(s,\pi\right)$ is the so called (local) Godement--Jacquet L-function associated to $\pi$. We need the following results  \cite[Prop. 3.5, Cor. 3.6, Prop. 5.11]{MR342495} for later proofs.

\begin{Prop}\label{P:GJLfunction}
Suppose that $\pi = LQ\left(\St\left(\Delta_1\right)\times\St\left(\Delta_2\right)\times\cdots\times\St\left(\Delta_r\right)\right)$, with $\Delta_i=\left[x_i,y_i\right]_{\rho_i}$. 

\begin{enumerate}
    \item We have
\[
    L\left(s,\pi\right) = \prod_{i=1}^{r} L\left(s+x_i,\rho_i\right),
\]
where
\[
    L\left(s,\rho_i\right) = \begin{cases}
       \frac{1}{1-\rho_i\left(\varpi\right)q^{-s}} \quad & \textit{if $\rho_i$ is a unramified character of $G_1$};\\[10pt]

       1 \quad & \textit{otherwise}. 
    \end{cases}
\]

\vskip 5pt

\item For any irreducible subquotient $\pi'$ of $\St\left(\Delta_1\right)\times\St\left(\Delta_2\right)\times\cdots\times\St\left(\Delta_r\right)$, the fraction $L\left(s,\pi'\right)/L\left(s,\pi\right)$ is an entire function.
\end{enumerate}
\end{Prop}

\vskip 10pt
% subsection local_zeta_integrals_of_godement_jacquet (end)




\section{The Weil representation} % (fold)
\label{sec:the_weil_representation}

Recall that we have defined the Weil representation $\omega_{n,m}$ of $G_n\times H_m$ in (\ref{E:DefWeilRep}). In this section we take a closer look at this representation, and collect some useful results to study this representation.

\vskip 5pt

\subsection{MVW-involution as Fourier transformation} % (fold)
\label{sub:mvw_involution_as_fourier_transformation}

In Section \ref{sub:mvw_involution_of_general_linear_groups} we have introduced the functor of MVW-involution. This functor can be extended to the category of representations of $G_n\times H_m$. Consider the outer automorphism
\[
    c: G_n\times H_m \lra G_n\times H_m, \quad \left(g,h\right) \longmapsto \left(w_n{}^{t}g^{-1} w_n^{-1}, w_m{}^{t}h^{-1} w_m^{-1}\right).
\]
Here as before, the superscript ``$t$'' means transpose, and $w_n$ (resp. $w_m$) is a (longest) Weyl group element of $G_n$ (resp. $H_m$). This outer automorphism induces a functor
\[
    c: \calM\left(G_n\times H_m\right) \lra \calM\left(G_n\times H_m\right), \quad \pi \longmapsto \pi^c.
\]
Sometimes we would like to write $\pi^{MVW}$ for $\pi^c$. The point here is that for the Weil representation $\omega_{n,m}$, the MVW-involution can be alternatively realized as Fourier transformation.

\begin{Lem}\label{L:MVW4rier}
As representations of $G_n\times H_m$, we have
\[
    \omega_{n,m}^{MVW} \simeq \omega_{n,m}.
\]   
\end{Lem}

\vskip 5pt

\begin{proof}
This is \cite[Lem. 4.3]{MR3930015}; the isomorphism is given by the Fourier transformation
\begin{align*}
    \calS\left(M_{n,m}\right) &\lra \calS\left(M_{n,m}\right),
\end{align*}  
sending a test function $\varphi\in\calS\left(M_{n,m}\right)$ to 
\[
    X\longmapsto \int_{M_{n,m}}\varphi\left(Y\right)\psi_F\left({\rm tr}_m\left({}^tX\cdot Y\right)\right)dY.
\]
Here $\psi_F$ is a non-trivial additive character of $F$, and ${\rm tr}_m$ is the trace map of $M_{m,m}$.

\end{proof}

\vskip 5pt

Consequently, we deduce that:

\begin{Cor}\label{C:ExtvsMVW}
For any representation $\pi$ of $G_n$, we have
\[
    \Ext_{G_n}^i\left(\omega_{n,m},\pi^c\right)_{sm} \simeq \Ext_{G_n}^i\left(\omega_{n,m},\pi\right)^c_{sm}
\] 
as representations of $H_m$, for all $i\geq 0$.  
\end{Cor}

\vskip 5pt

\begin{proof}
Using the previous lemma, one can check by hand that
\[
    \Hom_{G_n}\left(\omega_{n,m},-\right)_{sm}\circ c \simeq c \circ \Hom_{G_n}\left(\omega_{n,m},-\right)_{sm}
\]
as functors from $\calM\left(G_n\right)$ to $\calM\left(H_m\right)$. The desired conclusion then follows from deriving both sides of above. 

\end{proof}

\vskip 5pt

% subsection mvw_involution_as_fourier_transformation (end)

\subsection{The rank filtration on the Weil representation} % (fold)
\label{sub:the_rank_filtration}

Since the Weil representation is realized on the space of Schwartz functions on the matrices, there is a natural filtration induced by ranks of matrices. To be more precise, we have a $G_n\times H_m$-invariant filtration on $\calS\left(M_{n,m}\right)$:

\[
    0=R_{a+1} \subset R_a \subset R_{a-1} \subset \cdots \subset R_0 = \calS\left(M_{n,m}\right).
\]
Here $a=\min\left\{n,m\right\}$, and for each $0\leq k\leq a$, $R_k$ is the space of Schwartz functions supported on the matrices in $M_{n,m}$ of rank greater than or equal to $k$. Let $\Omega_k$ be the set of matrices in $M_{n,m}$ of rank $k$. Then as vector spaces, we have
\[
    R_k/R_{k+1} \simeq \calS\left(\Omega_k\right).
\]
We shall denote by $\tau_k$ the action of $G_n\times H_m$ on $R_k/R_{k+1}$ inherited from $\omega_{n,m}$. According to \cite[Sect. 2]{MR2504432} (or \cite[Sect. 5.1]{MR3753906}), this representation $\tau_k$ can be described as follows.

\begin{Lem}\label{L:rank-filtration}
Let $P_k$ be the standard parabolic subgroup of $G_n$ with Levi component $G_k\times G_{n-k}$, and $Q_k$ the standard parabolic subgroup of $H_m$ with Levi component $H_k\times H_{m-k}$. Denote by $\overline{Q}_k$ the parabolic subgroup of $H_m$ opposite to $Q_k$. Then we have
\[
    \tau_k \simeq \Ind_{P_k\times \overline{Q}_k}^{G_n\times H_m} \left(\omega^\natural_k\otimes\xi_k\right),
\]
where the parabolic induction is normalized, and:
\begin{itemize}
     \item $\omega^\natural_k$ is the natural geometric action of $G_k\times H_k$ on $\calS\left(G_k\right)$, namely
     \[
        \left(\omgn_k\left(g,h\right)\varphi\right) \left(X\right) = \varphi\left(g^{-1}Xh\right)
     \]
     for $\left(g,h\right)\in G_k\times H_k$, $\varphi\in\calS\left(G_k\right)$ and $X\in G_k$;

     \vskip 5pt

     \item $\xi_k$ is a character of the standard Levi subgroup of $P_k\times \overline{Q}_k$, given by
     \[  \xi_k = 
     \begin{cases}
       |\det|^{\frac{k-n-m}{2}}  \quad & \textit{on } G_{k} ; \\[10pt]

       |\det|^{\frac{k-m}{2}}  \quad & \textit{on } G_{n-k} ; \\[10pt]

       |\det|^{\frac{n+m-k}{2}}  \quad & \textit{on } H_{k} ; \\[10pt]

       |\det|^{\frac{n-k}{2}}  \quad & \textit{on } H_{m-k}.
     \end{cases}
     \]
\end{itemize} 
\end{Lem}

\vskip 5pt

Using this filtration, Adams--Prasad--Savin showed that for any irreducible representation $\pi$ of $G_n$ and any $*\geq 0$, $\Ext_{G_n}^*\left(\omega_{n,m},\pi\right)_{sm}$ is a finite length representation of $H_m$, hence $\EP_{G_n}\left(\omega_{n,m},\pi\right)_{sm}$ is well-defined in the Grothendieck group. We refer readers to \cite[Prop. 1.1, Prop. 5.17]{MR3753906} for more details.


\vskip 5pt

% subsection the_rank_filtration (end)


\subsection{Jacquet modules of the Weil representation} % (fold)
\label{sub:kudla_s_filtration}

In our later computations, we often need to deal with Jacquet modules of the Weil representation. The \textit{Kudla's filtration} \cite[Prop. 3.2]{MR2504432} provides a fruitful description of these Jacquet modules. For each $0\leq k\leq n$, again we let $P_k$ be the standard parabolic subgroup of $G_n$ with Levi component $M_k = G_k\times G_{n-k}$.

\begin{Prop}\label{P:KudlaFiltration}
The normalized Jacquet module $\Jac_{P_k}\omega_{n,m}$ of $\omega_{n,m}$ has an $M_k\times H_m$-invariant filtration
\[
    0= J_{k+1}\subset J_k \subset J_{k-1} \subset \cdots \subset J_0 = \Jac_{P_k}\omega_{n,m},
\]
and for each $0\leq i \leq k$, the successive quotient $\lambda_i=J_i/J_{i+1}$ is given by
\[
    \lambda_i \simeq \Ind_{P_{k-i,i}\times G_{n-k} \times Q_i}^{M_k\times H_m}\left(\mu_{k,i}\otimes \omgn_i\otimes\omega_{n-k,m-i}\right).
\]
Here:
\begin{itemize}
    \item $P_{k-i,i}$ is the standard parabolic subgroup of $G_k$ with Levi component $G_{k-i}\times G_i$;

    \vskip 5pt

    \item $Q_i$ is the standard parabolic subgroup of $H_m$ with Levi component $H_{i}\times H_{m-i}$; if $Q_i$ does not exists, then $\lambda_i$ is interpreted to be zero;

    \vskip 5pt

    \item $\omgn_i$ is the natural geometric action of $G_i\times H_i$ on $\calS\left(G_i\right)$;

    \vskip 5pt

    \item $\omega_{n-k,m-i}$ is the Weil representation associated to $G_{n-k}\times H_{m-i}$;

    \vskip 5pt

    \item $\mu_{k,i}$ is a character of the standard Levi subgroup of $P_{k-i,i}\times G_{n-k} \times Q_i$, given by
    \[  \mu_{k,i} = 
     \begin{cases}
       |\det|^{\frac{m-n+k-i}{2}}  \quad & \textit{on } G_{k-i} ; \\[10pt]

       |\det|^{\frac{m-n+2k-i}{2}}  \quad & \textit{on } G_{i} ; \\[10pt]

       |\det|^{\frac{k-i}{2}}  \quad & \textit{on } G_{n-k} ; \\[10pt]

       |\det|^{\frac{n-m-2k+i}{2}}  \quad & \textit{on } H_{i} ; \\[10pt]

       |\det|^{\frac{i-k}{2}}  \quad & \textit{on } H_{m-i}.
     \end{cases}
     \]
\end{itemize}
\end{Prop}

\vskip 5pt

We end up this section with a standard application of the Kudla's filtration. Let $\Delta = \left[x,y\right]_\rho$ be a segment. Assume that $\St\left(\Delta\right)$ is an irreducible representation of $G_k$.

\begin{Cor}\label{C:KudlaIndCompatible}
Suppose that either $\rho\not\simeq\mathbbm{1}_1$, or $y\neq \frac{1+m-n}{2}$. Then for any representation $\pi_0$ of $G_{n-k}$, and any $i\geq 0$, we have
\[
    \Ext_{G_n}^i\left(\omega_{n,m}, \St\left(\Delta\right)\times\pi_0\right)_{sm} \simeq \St\left(\Delta\right)\times \Ext_{G_{n-k}}^i\left(\omega_{n-k,m-k}, \pi_0\right)_{sm} 
\]
as representations of $H_m$.
\end{Cor}

\vskip 5pt

\begin{proof}
The proof is similar to that of \cite[Prop. 5.2]{MR3714507}. By the Frobenius reciprocity (see Lemma \ref{L:IndJacAdj}(1)), we have
\[
    \Ext_{G_n}^i\left(\omega_{n,m}, \St\left(\Delta\right)\times\pi_0\right)_{sm} \simeq \Ext_{G_k\times G_{n-k}}^i\left(\Jac_{P_k}\omega_{n,m}, \St\left(\Delta\right)\boxtimes\pi_0\right)_{sm}.
\]
To compute the right hand side, we appeal to the Kudla's filtration. For all $0\leq j\leq k-1$ and $*\geq 0$, we have
\[
    \Ext_{G_k\times G_{n-k}}^*\left(\lambda_j, \St\left(\Delta\right)\boxtimes\pi_0\right)_{sm}
\]
\begin{align*}
     &\simeq \Ind_{Q_j}^{H_m}\left(\Ext_{G_k\times G_{n-k}}^*\left(\Ind_{P_{k-j,j}\times G_{n-k}}^{G_k\times G_{n-k}}\left(\mu_{k,j}\otimes\omgn_j\otimes\omega_{n-k,m-j}\right), \St\left(\Delta\right) \boxtimes \pi_0\right)\right).
\end{align*} 
Then by the second adjointness (see Lemma \ref{L:IndJacAdj}(2)), the latter is isomorphic to
\begin{equation}\label{E:IndExt}
    \Ind_{Q_j}^{H_m}\left(\Ext_{G_{k-j}\times G_j\times G_{n-k}}^*\left(\mu_{k,j}\otimes\omgn_j\otimes\omega_{n-k,m-j}, \Jac_{\overline{P}_{k-j,j}}\left(\St\left(\Delta\right)\right)\boxtimes \pi_0\right)\right).
\end{equation}
Now, suppose that 
\[
    \Jac_{\overline{P}_{k-j,j}}\left(\St\left(\Delta\right)\right) = \delta_1\boxtimes\delta_2,
\]
where $\delta_1$ and $\delta_2$ are essentially discrete series of $G_{k-j}$ and $G_j$, respectively. If $\rho\not\simeq\mathbbm{1}_1$, then by Lemma \ref{L:ExtSteinberg} and \cite[Thm. 2]{Duality}, as representations of $G_{k-j}$, there is no Hom or Ext between $\delta_1$ and $\mu_{k,j}$. On the other hand, if $\rho\simeq\mathbbm{1}_1$ but $y\neq \frac{1+m-n}{2}$, by Proposition \ref{P:JacSeg} we have
\[
    \delta_1 = \St\left(\Delta_{II}^{(j)}\right),
\]
where $\Delta_{II}^{(j)} = \left[y+k-j-1,y\right]_{\mathbbm{1}_1}$.
In this case easy to see that the central character of $\delta_1$ is different from that of $\mu_{k,j}$. Therefore under our assumption, the Ext space in (\ref{E:IndExt}) is always zero. This implies that
\begin{align*}
\Ext_{G_k\times G_{n-k}}^i\left(\Jac_{P_k}\omega_{n,m}, \St\left(\Delta\right)\boxtimes\pi_0\right)_{sm} &\simeq \Ext_{G_k\times G_{n-k}}^i\left(\lambda_k, \St\left(\Delta\right)\boxtimes\pi_0\right)_{sm}\\
&\simeq \St\left(\Delta\right) \times \Ext_{G_{n-k}}^i\left(\omega_{n-k,m-k}, \pi_0\right)_{sm}
\end{align*}
as desired. This completes the proof.

\end{proof}

\vskip 10pt

% subsection kudla_s_filtration (end)


% section the_weil_representation (end)

\section{Proof of the main theorem I} % (fold)
\label{sec:proof_of_the_main_theorem_i}

This section is devoted to the proof of the main result I: Theorem \ref{T:Main-1}. So in this section, we assume that $n\leq m$. In particular, we have $\frac{1+m-n}{2}>0$.

\vskip 5pt

\subsection{Holomorphicity of the L-function implies Ext-vanishing} % (fold)
\label{sub:holomorphicity_of_the_l_function_implies_ext_vanishing}

We start with an easy computation of the local L-function. Let
\begin{equation}\label{E:ProofMain-IpiLQ}
    \pi = LQ\left(\St\left(\Delta_1\right)\times\St\left(\Delta_2\right)\times\cdots\times\St\left(\Delta_r\right)\right)
\end{equation} 
be an irreducible representation of $G_n$, with $\Delta_i=\left[x_i,y_i\right]_{\rho_i}$ for $1\leq i \leq r$. Let $\check\Delta_i=\left[-y_i,-x_i\right]_{\rho_i^\vee}$. Then we have
\[
    \pi^\vee = LQ\left(\St\left(\check\Delta_r\right)\times \cdots\times \St\left(\check\Delta_2\right)\times \St\left(\check\Delta_1\right)\right).
\]
By Proposition \ref{P:GJLfunction}(1), the L-function associated to $\pi^\vee$ is 
\[
    L\left(s,\pi^\vee\right) = \prod_{i=1}^{r} L\left(s-y_i,\rho_i^\vee\right).
\]
It follows that $L\left(s,\pi^\vee\right)$ is holomorphic at $s=\frac{1+m-n}{2}$ if and only if for any $1\leq i \leq r$, either $\rho_i\not\simeq\mathbbm{1}_1$, or $y_i\neq \frac{1+m-n}{2}$. Note that this condition is exactly the one appears in Corollary \ref{C:KudlaIndCompatible}! Therefore for all $*>0$ we have
\[
    \Ext_{G_n}^*\left(\omega_{n,m},\St\left(\Delta_1\right)\times\St\left(\Delta_2\right)\times\cdots\times\St\left(\Delta_r\right)\right)_{sm}
\]
\[
    \simeq \St\left(\Delta_1\right)\times\St\left(\Delta_2\right)\times\cdots\times\St\left(\Delta_r\right) \times \Ext_{G_0}^*\left(\omega_{0,m-n},\mathbbm{1}_0\right)_{sm} = 0,
\]
since the trivial group $G_0$ is compact. Based on this computation, we deduce that:

\begin{Prop}\label{P:Holo-L-vanish-Ext}
Suppose that $n\leq m$, and either $L\left(s,\pi\right)$ or $L\left(s,\pi^\vee\right)$ is holomorphic at $s=\frac{1+m-n}{2}$. Then
\[
    \Ext_{G_n}^*\left(\omega_{n,m},\pi\right)_{sm}=0
\] 
for all $*> 0$.  

\end{Prop}

\vskip 5pt

\begin{proof}
Let $\pi$ be of the form as in (\ref{E:ProofMain-IpiLQ}), and we fix a degree $*>0$. We first assume that $L\left(s,\pi^\vee\right)$ is holomorphic at $s=\frac{1+m-n}{2}$. Consider the short exact sequence
\[
    0 \lra \varkappa \lra \Pi \xlongrightarrow[\quad]{p} \pi \lra 0,
\]
where $\Pi=\St\left(\Delta_1\right)\times\St\left(\Delta_2\right)\times\cdots\times\St\left(\Delta_r\right)$, the map $p$ is the natural projection, and $\varkappa$ is the kernel of $p$. Applying the functor $\Hom_{G_n}\left(\omega_{n,m},-\right)_{sm}$ to it, the associated long exact sequence reads
\[
    \cdots\lra\Ext_{G_n}^*\left(\omega_{n,m},\Pi\right)_{sm} \lra \Ext_{G_n}^*\left(\omega_{n,m},\pi\right)_{sm} \lra \Ext_{G_n}^{*+1}\left(\omega_{n,m},\varkappa\right)_{sm}\lra\cdots.
\]
As in the discussion before this proposition, we have shown that the holomorphicity of $L\left(s,\pi^\vee\right)$ implies that
\[
    \Ext_{G_n}^*\left(\omega_{n,m},\Pi\right)_{sm} = 0.
\]
Therefore in order to prove the desired conclusion it suffices to show that for any irreducible subquotient $\pi'$ of $\varkappa$, we have 
\begin{equation*}%\label{P:Main-IExtvanishshift1}
    \Ext_{G_n}^{*+1}\left(\omega_{n,m},\pi'\right)_{sm} = 0.
\end{equation*}
Now note that by Proposition \ref{P:GJLfunction}(2), the L-function $L\left(s,\left(\pi'\right)^\vee\right)$ is still holomorphic at the point $s=\frac{1+m-n}{2}$. So we can repeat this procedure, and eventually we can reduce the desired conclusion to showing that
\begin{equation}\label{E:Main-IExtvanishshift1}
    \Ext_{G_n}^{*+n}\left(\omega_{n,m},\pi''\right)_{sm} = 0
\end{equation}
for all $\pi''$ in a certain finite set of irreducible representations. By \cite[Pg. 98, Sect. 4.2]{BNote}, we do know that (\ref{E:Main-IExtvanishshift1}) holds, as the degree $*+n$ is greater than the split rank of $G_n$.

\vskip 5pt

Next we assume that $L\left(s,\pi\right)$ is holomorphic at $s=\frac{1+m-n}{2}$ but $L\left(s,\pi^\vee\right)$ is not. %\zjl{Next we assume that $L\left(s,\pi\right)$ is holomorphic at $s=\frac{1+m-n}{2}$}
Consider the MVW-involution of $\pi$. It follows from Corollary \ref{C:ExtvsMVW} that
\[
    \Ext_{G_n}^*\left(\omega_{n,m},\pi\right)_{sm} \simeq \left(\Ext_{G_n}^*\left(\omega_{n,m},\pi^\vee\right)_{sm} \right)^c .
\]
Then by the discussion above, we know that 
\[
    \Ext_{G_n}^*\left(\omega_{n,m},\pi^\vee\right)_{sm} = 0
\]
for all $*>0$. Therefore in this case the desired conclusion still holds.

\end{proof}

\vskip 5pt

% subsection holomorphicity_of_the_l_function_implies_ext_vanishing (end)


\subsection{Zeta integrals in non-equal rank cases} % (fold)
\label{sub:zeta_integrals_in_the_non_equal_rank_case}

Now we modify the zeta integral to non equal rank cases. By using the decomposition $M_{n,m}\simeq M_{n,n}\times M_{n,m-n}$, we can write any element $\tilde{X}\in M_{n,m}$ as a block matrix
\[
    \big(X_0 ~|~ X_1\big),
\]
where $X_0\in M_{n,n}$, and $X_1\in M_{n,m-n}$. Let $\varphi\in \calS\left(M_{n,m}\right)$, we set $\varphi^\flat\in\calS\left(M_{n,n}\right)$ to be the function
\begin{equation}\label{E:Schwartzfunction-flat}
    \varphi^\flat\left(X\right) = \varphi\left(X~|~0\right)
\end{equation}
for $X\in M_{n,n}$. Then for a given $\varphi \in \calS\left(M_{n,m}\right)$ and a matrix coefficient $f$ of $\pi$, we can consider the integral
\begin{align*}
Z^\flat\left(s,\varphi,f\right)  \coloneqq{}&  Z\left(s,\varphi^\flat, f\right) \\
 ={}& \int_{G_n} \varphi\left(X~|~0\right) f\left(g\right) |\det g|^{s+\frac{n-1}{2}}\,dg.
\end{align*}
By \cite{MR342495}, we know that this integral is absolutely convergent when ${\rm Re}\left(s\right)$ is sufficiently large, and admits a meromorphic continuation to the whole plane. Moreover, the fraction
\[
    Z^\natural\left(s,\varphi,f\right) \coloneqq \frac{Z^\flat\left(s,\varphi,f\right)}{L\left(s,\pi\right)}
\]
is an entire function. Therefore we get a well-defined map
\begin{equation}\label{E:non-equal-rank-Zeta}
%Z^\natural\left(s,-,-\right): \omega_{n,m} \lra \pi|\det|^{s-\frac{1+m-n}{2}}\boxtimes \pi^\vee|\det|^{-s+\frac{1}{2}}.
Z^\natural\left(s,-,-\right): \omega_{n,m} \lra \pi\boxtimes\pi^\vee.
\end{equation}

\begin{Lem}\label{L:construction-non-equal-rank-Zeta}
This map (\ref{E:non-equal-rank-Zeta}) is $G_n\times \overline{Q}_{n}$-equivariant and non-zero. Here: 

\begin{itemize}
    \item $Q_n$ is the standard parabolic subgroup of $H_m$ whose Levi component is $H_n \times H_{m-n}$, and $\overline{Q}_n$ is the parabolic subgroup of $H_m$ opposite to $Q_n$;

    \vskip 5pt

    \item $G_n\times \overline{Q}_{n}$ acts on the left hand side of this map by $\omega_{n,m}$;

    \vskip 5pt

    \item $G_n$ acts on the right hand side of this map by $\pi|\det|^{s-\frac{1+m-n}{2}}$;

    \vskip 5pt

    \item the action of $\overline{Q}_n$ on the right hand side factor through the Levi component $H_n \times H_{m-n}$, the factor $H_n$ acts by $\pi^\vee|\det|^{-s+\frac{1}{2}}$, and $H_{m-n}$ acts by the character $|\det|^{\frac{n}{2}}$.
\end{itemize}
\vskip 5pt
In particular, by the Frobenius reciprocity, this map (\ref{E:non-equal-rank-Zeta}) gives rise to a non-zero element in the Hom space
\[
    \Hom_{G_n\times H_m}\left(\omega_{n,m}, \pi|\det|^{s-\frac{1+m-n}{2}}\boxtimes \Ind_{\overline{Q}_n}^{H_m}\left(\pi^\vee|\det|^{-s+\frac{1+m-n}{2}}\boxtimes\mathbbm{1}_{m-n}\right)\right).
\]

\end{Lem}

\vskip 5pt

\begin{proof}
The equivariant property follows from the definition of $Z^\flat\left(s,-,-\right)$ directly. To see that the map is non-zero, one just needs to note that $\varphi \mapsto \varphi^\flat$ is surjective.

\end{proof}

\vskip 5pt

Specializing this construction to $s=\frac{1+m-n}{2}$, we get a non-zero element $Z^\natural\left(\frac{1+m-n}{2},-,-\right)$ in the Hom space
\[
    \Hom_{G_n\times H_m}\left(\omega_{n,m}, \pi\boxtimes \Ind_{\overline{Q}_n}^{H_m}\left(\pi^\vee\boxtimes\mathbbm{1}_{m-n}\right)\right).
\]
Note that if $\pi = LQ\left(\St\left(\Delta_1\right)\times\St\left(\Delta_2\right)\times\cdots\times\St\left(\Delta_r\right)\right)$, with $\Delta_i=\left[x_i,y_i\right]_{\rho_i}$ and they are properly arranged according to their exponents, then $\Ind_{\overline{Q}_n}^{H_m}\left(\pi^\vee\boxtimes\mathbbm{1}_{m-n}\right) \simeq \mathbbm{1}_{m-n} \times \pi^\vee$ is indeed a subrepresentation of the parabolic induction
\[
    |\cdot|^{-\frac{m-n-1}{2}}\times\cdots\times |\cdot|^{\frac{m-n-1}{2}}\times \St\left(\Delta_1\right)^\vee\times\St\left(\Delta_2\right)^\vee\times\cdots\times\St\left(\Delta_r\right)^\vee
\]
occurring in Theorem \ref{T:HoweDuality}(2).
By the Howe duality and the multiplicity one property of the Langlands quotient, we know that there exists two subrepresentations $\Sigma_0\subset\Sigma_1$ of $\Ind_{\overline{Q}_n}^{H_m}\left(\pi^\vee\boxtimes\mathbbm{1}_{m-n}\right)$, such that:
\begin{itemize}
    \item the quotient $\Sigma_1/\Sigma_0$ is isomorphic to $\theta_{n,m}\left(\pi\right)$;

    \vskip 5pt

    \item any subquotient of $\Ind_{\overline{Q}_n}^{H_m}\left(\pi^\vee\boxtimes\mathbbm{1}_{m-n}\right)/\Sigma_1$ and $\Sigma_0$ is not isomorphic to $\theta_{n,m}\left(\pi\right)$.
\end{itemize}
\vskip 5pt
A priori we do not know that whether $\Sigma_0$ and $\Sigma_1$ are unique. Nevertheless we have the following simple observation.

\begin{Prop}
The map $Z^\natural\left(\frac{1+m-n}{2},-,-\right)$ indeed gives rise to a non-zero element in the Hom space
\[
    \Hom_{G_n\times H_m}\left(\omega_{n,m}, \pi\boxtimes \theta_{n,m}\left(\pi\right)\right),
\]  
in the sense that:

\begin{itemize}
    \item $Z^\natural\left(\frac{1+m-n}{2},-,-\right)$ lies in the subspace
    \[
        \Hom_{G_n\times H_m}\left(\omega_{n,m}, \pi\boxtimes \Sigma_1\right) \hookrightarrow \Hom_{G_n\times H_m}\left(\omega_{n,m}, \pi\boxtimes \left(\mathbbm{1}_{m-n} \times \pi^\vee\right) \right);
    \]

    \vskip 5pt

    \item the image of $Z^\natural\left(\frac{1+m-n}{2},-,-\right)$ under the natural map
    \[
        \Hom_{G_n\times H_m}\left(\omega_{n,m}, \pi\boxtimes \Sigma_1\right) \lra \Hom_{G_n\times H_m}\left(\omega_{n,m}, \pi\boxtimes \Sigma_1/\Sigma_0\right) 
    \]
    is non-zero.
\end{itemize}
\end{Prop}

\vskip 5pt

\begin{proof}
The proposition simply follows from Theorem \ref{T:HoweDuality}(1).

\end{proof}

\vskip 5pt

With this observation at hand, finally we can mimic the argument of Fang--Sun--Xue \cite[Thm. 1.3]{FSX} to complete the proof of Theorem \ref{T:Main-1}. Let $\Omega_n$ be the set of matrices in $M_{n,m}$ of rank $n$, which is stable under the action of $G_n\times H_m$. We denote by $\omega^0_{n,m}$ the subrepresentation of $\omega_{n,m}$ with the underlying vector space $\calS\left(\Omega_n\right)$. 

\begin{Prop}\label{P:Holo-L-vanish-boundary}
Suppose that the L-function $L\left(s,\pi\right)$ is holomorphic at $s=\frac{1+m-n}{2}$. Then we have 
\[
    \Hom_{G_n}\left(\omega_{n,m}/\omega^0_{n,m},\pi\right) = 0.
\]    
\end{Prop}

\vskip 5pt

\begin{proof}
We first claim that: under the holomorphicity assumption of the L-function $L\left(s,\pi\right)$, we have $\Sigma_1 = \Ind_{\overline{Q}_n}^{H_m}\left(\pi^\vee\boxtimes\mathbbm{1}_{m-n}\right)$,
%\begin{equation}%\label{E:Sigma_1EqualsFullInd}
    %\Sigma_1 = \Ind_{\overline{Q}_n}^{H_m}\left(\pi^\vee\boxtimes\mathbbm{1}_{m-n}\right),
%\end{equation}   
and $\Sigma_0$ is the unique maximal subrepresentation of $\Sigma_1$. Moreover, the natural map
\begin{equation*}%\label{E:non-zero-of-reduction-map}
    \mathscr{R}_{\theta}: \Hom_{G_n\times H_m}\left(\omega_{n,m},\pi\boxtimes\theta_{n,m}\left(\pi\right)\right) \lra \Hom_{G_n\times H_m}\left(\omega_{n,m}^0,\pi\boxtimes\theta_{n,m}\left(\pi\right)\right)
\end{equation*}   
induced by the inclusion $\omega^0_{n,m}\hookrightarrow\omega_{n,m}$ is non-zero.

\vskip 5pt

To proof our claim, consider the restriction of $Z^\natural\left(\frac{1+m-n}{2},-,-\right)$ to $\omega^0_{n,m}$, namely, the image of $Z^\natural\left(\frac{1+m-n}{2},-,-\right)$ under the map
\begin{equation*}%\label{E:non-equal-rank-FSX-argument}
 \mathscr{R}_{ind}: \Hom_{G_n\times H_m}\left(\omega_{n,m}, \pi\boxtimes \Ind_{\overline{Q}_n}^{H_m}\left(\pi^\vee\boxtimes\mathbbm{1}\right)\right) \lra \Hom_{G_n\times H_m}\left(\omega^0_{n,m}, \pi\boxtimes \Ind_{\overline{Q}_n}^{H_m}\left(\pi^\vee\boxtimes\mathbbm{1}\right)\right).   
\end{equation*}
For any $\varphi\in\calS\left(\Omega_n\right)$, we have $\varphi^\flat\in\calS\left(G_n\right)$, and $\varphi\mapsto\varphi^\flat$ induces a surjection $\calS\left(\Omega_n\right) \twoheadrightarrow \calS\left(G_n\right)$.
Hence for any matrix coefficient $f$ of $\pi$, the integral $Z^\flat\left(s,\varphi,f\right) = Z\left(s,\varphi^\flat,f\right)$ is absolutely convergent and holomorphic for all $s\in\C$.
Since the L-function $L\left(s,\pi\right)$ is holomorphic at $s=\frac{1+m-n}{2}$, the restriction of $Z^\natural\left(\frac{1+m-n}{2},-,-\right)$ to $\omega^0_{n,m}$ is non-zero. This implies that the map $\mathscr{R}_{ind}$ is non-zero.

\vskip 5pt

Now note that the target of $\mathscr{R}_{ind}$ can be rewritten as
\begin{align*}
\Hom_{G_n\times H_m}\left(\omega^0_{n,m}, \pi\boxtimes \Ind_{\overline{Q}_n}^{H_m}\left(\pi^\vee\boxtimes\mathbbm{1}\right)\right) & \simeq \Hom_{H_m}\left(\left(\omega^0_{n,m}\otimes\pi^\vee\right)_{G_n} , \Ind_{\overline{Q}_n}^{H_m}\left(\pi^\vee\boxtimes\mathbbm{1}\right)\right) \\
& \simeq \Hom_{H_m}\left(\Ind_{\overline{Q}_n}^{H_m}\left(\pi^\vee\boxtimes\mathbbm{1}\right) , \Ind_{\overline{Q}_n}^{H_m}\left(\pi^\vee\boxtimes\mathbbm{1}\right)\right).
\end{align*}
It is known that this parabolic induction $\Ind_{\overline{Q}_n}^{H_m}\left(\pi^\vee\boxtimes\mathbbm{1}_{m-n}\right) \simeq \mathbbm{1}_{m-n} \times \pi^\vee$ is \textit{socle irreducible} (namely, its socle is irreducible and occurs with multiplicity one, see \cite[Def. 2.3, Def. 4.3, Cor. 4.9]{MR3573961}), thus any non-zero element in the Hom space
\[
    \Hom_{H_m}\left(\Ind_{\overline{Q}_n}^{H_m}\left(\pi^\vee\boxtimes\mathbbm{1}_{m-n}\right) , \Ind_{\overline{Q}_n}^{H_m}\left(\pi^\vee\boxtimes\mathbbm{1}_{m-n}\right)\right)
\]
is indeed an isomorphism. Therefore, if we re-interpret $Z^\natural\left(\frac{1+m-n}{2},-,-\right)$ as a map
\[
    Z^\natural_{n,m}:\omega_{n,m}\otimes\pi^\vee \lra \Ind_{\overline{Q}_n}^{H_m}\left(\pi^\vee\boxtimes\mathbbm{1}_{m-n}\right),
\]
then this map is surjective, as its restriction to $\omega^0_{n,m}\otimes\pi^\vee$ is already surjective. The surjectivity of $Z^\natural_{n,m}$ implies that $\Sigma_1 = \Ind_{\overline{Q}_n}^{H_m}\left(\pi^\vee\boxtimes\mathbbm{1}_{m-n}\right)$, and the Howe duality then implies that $\Sigma_0$ is the unique maximal subrepresentation of $\Sigma_1$. Moreover, it follows from the surjectivity of $Z^\natural_{n,m}\,\big|_{\omega^0_{n,m}\otimes\pi^\vee}$ that the map $\mathscr{R}_{\theta}$ is non-zero. This completes the proof of our claims.

\vskip 5pt

The rest of the proof of this proposition is identical with the proof of \cite[Lem. 2.3]{FSX}. Suppose on the contrary that $\Hom_{G_n}\left(\omega_{n,m}/\omega^0_{n,m},\pi\right) \neq 0$, then there must be an irreducible representation $\sigma$ of $H_m$, such that
\[
    \Hom_{G_n\times H_m}\left(\omega_{n,m}/\omega^0_{n,m},\pi\boxtimes\sigma\right) \neq 0.
\]
By the Howe duality, we must have $\sigma\simeq \theta_{n,m}\left(\pi\right)$. Consider the exact sequence
\[
    \Hom_{G_n\times H_m}\left(\omega_{n,m}/\omega^0_{n,m},\pi\boxtimes\sigma\right) \hookrightarrow \Hom_{G_n\times H_m}\left(\omega_{n,m},\pi\boxtimes\sigma\right) \xrightarrow{\mathscr{R}_\theta} \Hom_{G_n\times H_m}\left(\omega^0_{n,m},\pi\boxtimes\sigma\right).
\]
Here the first arrow is injective by the left exactness of the Hom functor, and the second arrow $\mathscr{R}_\theta$ is non-zero by our claims. It follows that
\[
    \dim\Hom_{G_n\times H_m}\left(\omega_{n,m},\pi\boxtimes\sigma\right) \geq 2,
\]
which is ridiculous since it violates the multiplicity one result Theorem \ref{T:HoweDuality}(1). Therefore we must have $\Hom_{G_n}\left(\omega_{n,m}/\omega^0_{n,m},\pi\right) = 0$ as desired.

\end{proof}

\vskip 5pt

\begin{Rmk}
The advantage of this zeta integral argument we employed is that it can be adapted to the Archimedean case, see the next subsection for a brief discussion. In fact, this proposition can also be proved in a more straightforward way by using the rank filtration of the Weil representation (Lemma \ref{L:rank-filtration}). Suppose that
\[
    \pi = LQ\left(\St\left(\Delta_1\right)\times\St\left(\Delta_2\right)\times\cdots\times\St\left(\Delta_r\right)\right),
\]
with $\Delta_i=\left[x_i,y_i\right]_{\rho_i}$ for $1\leq i \leq r$. Applying the MVW-contragredient trick, we have 
\[
    \pi \hookrightarrow \St\left(\Delta_r\right)\times\St\left(\Delta_{r-1}\right)\times\cdots\times\St\left(\Delta_1\right).
\]
For each $0\leq k \leq n-1$, the graded piece $\tau_k$ of the rank filtration contributes
\begin{align*}
    \Hom_{G_n}\left(\tau_k,\pi\right)_{sm}  \hookrightarrow &\Hom_{G_n}\left(\tau_k,\St\left(\Delta_r\right)\times\St\left(\Delta_{r-1}\right)\times\cdots\times\St\left(\Delta_1\right)\right)_{sm} \\ 
     \simeq &\Ind_{\overline{Q}_k}^{H_m}\left(\Hom_{G_k\times G_{n-k}}\left(\omega_k^\natural\otimes\xi_k, \Jac_{\overline{P}_k}\left(\St\left(\Delta_r\right)\times\cdots\times\St\left(\Delta_1\right)\right)\right)_{sm}\right).
\end{align*}
By the geometric lemma, we know that the Jacquet module on the right hand side admits a filtration, such that each graded piece is of the form $\delta_\alpha\boxtimes \kappa_\alpha$, where $\alpha=\left(\alpha_1,\alpha_2,\cdots,\alpha_r\right)$ is an ordered partition of $n-k$, and
\[
    \kappa_\alpha = \St\left(\left[x_r,x_r-\alpha_r+1\right]_{\rho_r}\right)\times\cdots \times \St\left(\left[x_2,x_2-\alpha_2+1\right]_{\rho_2}\right)\times \St\left(\left[x_1,x_1-\alpha_1+1\right]_{\rho_1}\right).  
\]
Recall that we have assumed the L-function $L\left(s,\pi\right)$ to be holomorphic at $s=\frac{1+m-n}{2}$, which means that for all $1\leq i \leq r$, either $\rho_i\not\simeq \mathbbm{1}_1$ or $x_i\neq -\frac{1+m-n}{2}$ holds. It follows that
\[
    \Hom_{G_{n-k}}\left(\xi_k, \kappa_\alpha\right) = 0
\]
for all ordered partitions $\alpha$ of $n-k$. Then by the K\"unneth formula Theorem \ref{T:Kunneth}, we have
\[
    \Hom_{G_k\times G_{n-k}}\left(\omega_k^\natural\otimes\xi_k, \Jac_{\overline{P}_k}\left(\St\left(\Delta_r\right)\times\cdots\times\St\left(\Delta_1\right)\right)\right)_{sm} =0.
\]
This implies that $\Hom_{G_n}\left(\tau_k,\pi\right)_{sm} = 0$ for all $0\leq k \leq n-1$, hence the proposition holds.

\end{Rmk}

\vskip 5pt
%\begin{proof}[Proof of Theorem \ref{T:Main-1}]

Now back to the proof of our main result I. Let $\pi$ be an irreducible representation of $G_n$ satisfied the assumption in Theorem \ref{T:Main-1}, namely $L\left(s,\pi\right)$ or $L\left(s,\pi^\vee\right)$ is holomorphic at $s=\frac{1+m-n}{2}$. We have already seen in Proposition \ref{P:Holo-L-vanish-Ext} that the Ext-vanishing assertion in Theorem \ref{T:Main-1} holds. To complete the proof of Theorem \ref{T:Main-1} it only remains to compute $\Theta_{n,m}\left(\pi\right)$. We first assume that $L\left(s,\pi\right)$ is holomorphic at $s=\frac{1+m-n}{2}$. Consider the short exact sequence of $G_n\times H_m$ representations
\[
    0 \lra \omega^0_{n,m} \lra \omega_{n,m} \lra  \omega_{n,m}/\omega^0_{n,m} \lra 0.
\]
Applying the functor $\Hom_{G_n}\left(-,\pi\right)_{sm}$ we obtain the exact sequence
\[
    0 \lra \Hom_{G_n}\left(\omega_{n,m}/\omega^0_{n,m},\pi\right)_{sm} \lra \Hom_{G_n}\left(\omega_{n,m},\pi\right)_{sm} \xrightarrow{~\mathscr{R}~} \Hom_{G_n}\left(\omega^0_{n,m},\pi\right)_{sm}.
\]
By Proposition \ref{P:Holo-L-vanish-boundary}, the contribution of the boundary $\Hom_{G_n}\left(\omega_{n,m}/\omega^0_{n,m},\pi\right)_{sm}$ is zero. Hence the map $\mathscr{R}$ is an injection. Moreover, by Proposition \ref{P:Holo-L-vanish-Ext} and Theorem \ref{T:APS-EP-fomula} we know that $\Hom_{G_n}\left(\omega_{n,m},\pi\right)_{sm}$ and $\Hom_{G_n}\left(\omega^0_{n,m},\pi\right)_{sm}$ have the same semi-simplification. Therefore the map $\mathscr{R}$ is an isomorphism, and
\[
    \Hom_{G_n}\left(\omega_{n,m},\pi\right)_{sm} \xrightarrow[~\mathscr{R}~]{\sim} \Hom_{G_n}\left(\omega^0_{n,m},\pi\right)_{sm} \simeq \mathbbm{1}_{m-n}\times \pi.
\]
In this case the desired formula for $\Theta_{n,m}\left(\pi\right)$ follows from taking contragredients of both sides of above.

\vskip 5pt

Next we assume that $L\left(s,\pi^\vee\right)$ is holomorphic at $s=\frac{1+m-n}{2}$ but $L\left(s,\pi\right)$ is not. Consider the MVW-involution of $\pi$. It follows from Corollary \ref{C:ExtvsMVW} that in this case
\[
    \Theta_{n,m}\left(\pi\right) \simeq \Theta_{n,m}\left(\pi^\vee\right)^c\simeq \pi^\vee\times\mathbbm{1}_{m-n}
\]
as desired. This completes the proof of Theorem \ref{T:Main-1}.
%\end{proof}

\vskip 5pt

% subsection zeta_integrals_in_the_non_equal_rank_case (end)


\subsection{Digression: the Archimedean case} % (fold)
\label{sub:digression_the_archimedean_case}

In this subsection we briefly discuss on extending Theorem 1.4 to the Archimedean case. So in contrast with the main body of this paper, only in this subsection we assume that $F$ is an Archimedean local field, i.e. $F=\R$ or $\C$, and we will work in the setting of \textit{Schwartz analysis} as in \cite{MR4211018}. In particular, by ``representations'' of a linear Nash group, what we actually mean is ``smooth Fr\'echet representations of moderate growth''.

\vskip 5pt

Under this setting our Weil representation is now defined on the space of Schwartz functions $\calS\left(M_{n,m}\right)$. Thanks to \cite{MR985172}, the Howe duality Theorem \ref{T:HoweDuality}(1) is still valid. Recall that in the proof of Theorem \ref{T:Main-1} we have made use of two tools: 

\begin{itemize}
    \item the Jacquet module: some arguments in our proof involves the computation of Jacquet modules of some specific representations;

    \vskip 5pt

    \item the zeta integral: we use the zeta integral to explicitly construct a non-zero element in certain Hom space.  
\end{itemize}
\vskip 5pt
While the Jacquet module becomes much more complicated in the Archimedean case, the theory of zeta integral is still available \cite[Thm. 8.7]{MR342495}. Therefore we can play the same game as in Section \ref{sub:zeta_integrals_in_the_non_equal_rank_case}. More precisely, we have the following analogy of Lemma \ref{L:construction-non-equal-rank-Zeta}.

\begin{Lem}
Suppose that $n\leq m$. Let $\pi$ be an irreducible representation of $G_n$. Then there exists a family of continuous map
\[
    Z^\natural_s : \omega_{n,m} \lra \pi\boxtimes\pi^\vee,
\] 
which is holomorphic in $s\in\C$, and satisfies the following conditions:

\begin{itemize}
     \item when the real part of $s$ is sufficiently large, then $Z^\natural_s$ is given by
     \[
        Z^\natural\left(s,\varphi,f\right) = \frac{Z\left(s,\varphi^\flat,f\right)}{L\left(s,\pi\right)},
     \]
     where $\varphi\in\omega_{n,m}$, $\varphi^\flat$ is defined in the same manner as (\ref{E:Schwartzfunction-flat}), and $f$ is a matrix coefficient of $\pi$;

     \vskip 5pt

     \item for each $s\in\C$, the map $Z_s^\natural$ gives rise to a non-zero element in the Hom space
     \[
        \Hom_{G_n\times\overline{Q}_n}\left(\omega_{n,m}, \pi|\det|^{s-\frac{1+m-n}{2}}\boxtimes\left(\pi^\vee|\det|^{-s+\frac{1}{2}}\boxtimes|\det|^{\frac{n}{2}}\right)\right),
     \]
     where $Q_n$ is the standard parabolic subgroup of $H_m$ with the Levi component $H_n\times H_{m-n}$, and $\overline{Q}_n$ is the opposite parabolic subgroup.
\end{itemize} 
\end{Lem}
\vskip 5pt
By the Frobenius reciprocity, we can regard $Z^\natural_s$ as an non-zero element in
\[
     \Hom_{G_n\times H_m}\left(\omega_{n,m}, \pi|\det|^{s-\frac{1+m-n}{2}}\boxtimes \Ind_{\overline{Q}_n}^{H_m}\left(\pi^\vee|\det|^{-s+\frac{1+m-n}{2}}\boxtimes\mathbbm{1}_{m-n}\right)\right).
\]
The most favorable case would be that $\pi$ is \textit{unitary}. In this case, $\Ind_{\overline{Q}_n}^{H_m}\left(\pi^\vee\boxtimes\mathbbm{1}_{m-n}\right)\simeq \mathbbm{1}_{m-n}\times \pi^\vee$ is irreducible, and the argument in Proposition \ref{P:Holo-L-vanish-boundary} (or, \cite[Lem. 2.3]{FSX}) still works with some mild modifications. Let $\Omega_n$ be the set of matrices in $M_{n,m}$ of rank $n$, and denote by $\omega^0_{n,m}$ the subrepresentation of $\omega_{n,m}$ with the underlying vector space $\calS\left(\Omega_n\right)$. We conclude that:

\begin{Thm}
In the context of this subsection, suppose that $n\leq m$. Let $\pi$ be an irreducible unitary representation of $G_n$. If $L\left(s,\pi\right)$ or $L\left(s,\pi^\vee\right)$ is holomorphic at $s=\frac{1+m-n}{2}$, then 
\[
    \Hom_{G_n}\left(\omega_{n,m}/\omega^0_{n,m},\pi\right) = 0,
\]
and moreover the big theta lift
\[
    \Theta_{n,m}\left(\pi\right) \simeq \pi^\vee \times \mathbbm{1}_{m-n}
\]
is irreducible.
\end{Thm}

\vskip 5pt

We highlight that if $\pi$ is irreducible, unitary and tempered, then $L\left(s,\pi\right)$ is holomorphic in the right half plane ${\rm Re}\left(s\right)>0$. Thus the theorem above holds for $\pi$.


% subsection digression_the_archimedean_case (end)


\vskip 10pt

% section proof_of_the_main_theorem_i (end)


\section{Proof of the main theorem II} % (fold)
\label{sec:proof_of_the_main_theorem_ii}

This section is devoted to the proof of the main result II: Theorem \ref{T:Main-2}, and also the complementary result Theorem \ref{T:Main-2-complement}.

\vskip 5pt

\subsection{Piece-wise computations} % (fold)
\label{sub:piece_wise_computations}

We first compute contributions of each piece in the rank filtration of the Weil representation. We shall retain the notations in Section \ref{sub:the_rank_filtration}: recall that for each $0\leq k\leq \min\left\{n,m\right\}$, $\Omega_k$ is the set of matrices in $M_{n,m}$ of rank $k$, and the action of $G_n\times H_m$ on $\calS\left(\Omega_k\right)$ inherited from $\omega_{n,m}$ is denoted by $\tau_k$. Lemma \ref{L:rank-filtration} gives a description of this piece
\[
    \tau_k \simeq \Ind_{P_k\times \overline{Q}_k}^{G_n\times H_m} \left(\omega^\natural_k\otimes\xi_k\right).
\]

\begin{Lem}\label{L:ExtGradedPiecesRankFil}
Let $\eta=|\det|^x$ be a character of $G_n$, where $x\in\frac{1}{2}\Z$. Then the Ext spaces associated to each graded piece of the rank filtration and $\eta$ are as follows.
\begin{enumerate}
    \item Suppose that $0\leq k < \min\left\{n,m\right\}$. Then
\[
    \Ext_{G_n}^*\left(\tau_k,\eta\right)_{sm} \simeq 
    \begin{cases}
        \Ind_{\overline{Q}_k}^{H_m}\left(|\det|^{\frac{n-m+k}{2}}\boxtimes |\det|^{\frac{k-n}{2}}\right) \quad & \textit{if } x=k-\frac{m}{2} \textit{ and } * = 0, 1; \\[10pt]

       0  \quad & \textit{otherwise}.
     \end{cases}
\]

\vskip 5pt

\item Suppose that $k=\min\left\{n,m\right\}$. Then 
\[
    \Ext_{G_n}^*\left(\tau_k,\eta\right)_{sm} \simeq 
    \begin{cases}
        \Ind_{\overline{Q}_n}^{H_m}\left(|\det|^x\boxtimes\mathbbm{1}_{m-n}\right) \quad & \textit{if } n\leq m \textit{ and } * = 0; \\[10pt]

        |\det|^{\frac{n}{2}} \quad & \textit{if } n>m \textit{, } x=\frac{m}{2} \textit{ and } * = 0, 1; \\[10pt]

       0  \quad & \textit{otherwise}.
     \end{cases}
\]
\end{enumerate}
\end{Lem}

\vskip 5pt

\begin{proof}
We first prove (1). For each $*\geq 0$, we have
\begin{align*}
    \Ext_{G_n}^*\left(\tau_k,\eta\right)_{sm} & \simeq \Ind_{\overline{Q}_k}^{H_m} \Ext^*_{G_n}\left(\Ind_{P_k}^{G_n}\left(\omega^\natural_k\otimes\xi_k\right) , \eta\right)_{sm} \\
    & \simeq \Ind_{\overline{Q}_k}^{H_m} \Ext^*_{G_k\times G_{n-k}}\left(\omega^\natural_k\otimes\xi_k , |\det|^{x+\frac{n-k}{2}}\boxtimes |\det|^{x-\frac{k}{2}}\right)_{sm}.
\end{align*}
Here in the last equality, we have made use of the second adjointness (see Lemma \ref{L:IndJacAdj}(2)) and the fact that $\Jac_{\overline{P}_k} \eta = |\det|^{x+\frac{n-k}{2}}\boxtimes |\det|^{x-\frac{k}{2}}$. If $k<n$, then by comparing the central characters of $G_{n-k}$-actions on $\xi_k$ and $|\det|^{x-\frac{k}{2}}$, one can see immediately that the Ext space above vanishes unless
\[
    |\det|^{\frac{k-m}{2}} = |\det|^{x-\frac{k}{2}},
\]
or equivalently $x=k-\frac{m}{2}$. In this case, by the K\"unneth formula Theorem \ref{T:Kunneth} and the projectivity of $\omega_k^\natural$ (as a $G_k$-module), we have  
\[
    \Ind_{\overline{Q}_k}^{H_m} \Ext^*_{G_k\times G_{n-k}}\left(\omega^\natural_k\otimes\xi_k , |\det|^{x+\frac{n-k}{2}}\boxtimes |\det|^{x-\frac{k}{2}}\right)_{sm}
\]
\[
    \simeq \Ind_{\overline{Q}_k}^{H_m} \left(\Hom_{G_k}\left(\omega^\natural_k\otimes\xi_k , |\det|^{x+\frac{n-k}{2}}\right)_{sm}\otimes \Ext^*_{G_{n-k}}\left(|\det|^{x-\frac{k}{2}},|\det|^{x-\frac{k}{2}}\right)\right).
\]
Then the rest follows from Lemma \ref{L:ExtSteinberg} easily. The proof for (2) is similar and we omit the details here. 

\end{proof}

\vskip 5pt

The computation above shows that the case $n>m$ is extremely simple: there is at most one graded piece can have non-zero Ext spaces with $\eta$. As a direct consequence, we can complete the proof of Theorem \ref{T:Main-2-complement}.

\vskip 5pt

\begin{proof}[Proof of Theorem \ref{T:Main-2-complement}]
If $\eta \neq |\det|^{k-\frac{m}{2}}$ for any integer $0\leq k\leq m$, then by the previous lemma there is no graded piece (of the rank filtration of the Weil representation) has non-zero Ext spaces with $\eta$, thus
\[
    \Ext_{G_n}^*\left(\omega_{n,m},\eta\right)_{sm} = 0.
\] 
If $\eta=|\det|^{k-\frac{m}{2}}$ for some integer $0\leq k\leq m$, then by the previous lemma and a standard argument of homological algebra we have 
\[
    \Ext_{G_n}^*\left(\omega_{n,m},\eta\right)_{sm} \simeq \Ext_{G_n}^*\left(\tau_k,\eta\right)_{sm}.
\]
Note that under the assumption $n>m$, we know that
\[
    \Ind_{\overline{Q}_k}^{H_m}\left(|\det|^{\frac{n-m+k}{2}}\boxtimes |\det|^{\frac{k-n}{2}}\right) \simeq |{\det}_{m-k}|^{\frac{k-n}{2}}\times|{\det}_k|^{\frac{n-m+k}{2}}
\]
is indeed irreducible. The theorem then follows from the previous lemma.

\end{proof}

\vskip 5pt


% subsection piece_wise_computations (end)

\subsection{Gluing graded pieces} % (fold)
\label{sub:gluing_graded_pieces}

Next we shall focus on the case that $n\leq m$. Thanks to Theorem \ref{T:Main-1}, we only need to consider the case that $n\geq 2$, $m\leq 2n-2$ and those characters $\eta$ of the form 
\[
    \eta = |\det|^{k-\frac{m}{2}}
\]
for some integer $1+m-n \leq k \leq n-1$. The computation in Lemma \ref{L:ExtGradedPiecesRankFil} shows that there are exactly two graded pieces of the rank filtration can have non-zero Ext spaces with $\eta$. The main goal of this subsection is to use some long exact sequences to ``glue'' these Ext spaces associated to graded pieces and $\eta$.

\vskip 5pt

We recall that the rank filtration on $\omega_{n,m}$ is a descending sequence of $G_n\times H_m$-modules
\[
    0 \subset R_n \subset R_{n-1} \subset \cdots \subset R_0 = \omega_{n,m},
\]
and for each $0\leq i\leq n$, we have $\tau_i\simeq R_i/R_{i+1}$. By Lemma \ref{L:ExtGradedPiecesRankFil}, only $\Ext_{G_n}^*\left(\tau_k,\eta\right)_{sm}$ and $\Ext_{G_n}^*\left(\tau_n,\eta\right)_{sm}$ can be non-zero. Therefore it is natural to consider the short exact sequence
\begin{equation}\label{E:SES-glue-rank-fil}
    0 \lra R_{k+1} \lra \omega_{n,m} \lra \omega_{n,m}/R_{k+1} \lra 0,
\end{equation}
since this exact sequence separates $\tau_k$ and $\tau_n$. 

\begin{Lem}
In the context of above discussions, the Ext spaces associated to $R_{k+1}$ and $\eta$ are
\[
    \Ext_{G_n}^*\left(R_{k+1},\eta\right)_{sm} \simeq \begin{cases}
        \mathbbm{1}_{m-n}\times|\det_n|^{k-\frac{m}{2}} \quad & \textit{if } * = 0; \\[10pt]
       0  \quad & \textit{otherwise}.
     \end{cases}
\]   
Likewise, the Ext spaces associated to $\omega_{n,m}/R_{k+1}$ and $\eta$ are
\[
    \Ext_{G_n}^*\left(\omega_{n,m}/R_{k+1},\eta\right)_{sm} \simeq \begin{cases}
        |{\det}_{m-k}|^{\frac{k-n}{2}}\times|{\det}_k|^{\frac{n-m+k}{2}} \quad & \textit{if } * = 0, 1; \\[10pt]
       0  \quad & \textit{otherwise}.
     \end{cases}
\]  
%Here we use $\det_d$ to denote the determinant character of $G_d$. 
\end{Lem}

\vskip 5pt

\begin{proof}
Again, by appealing to Lemma \ref{L:ExtGradedPiecesRankFil}, we know that 
\[
    \Ext_{G_n}^*\left(R_{k+1},\eta\right)_{sm} \simeq \Ext_{G_n}^*\left(\tau_n,\eta\right)_{sm}.
\]
Note that $\Ind_{\overline{Q}_n}^{H_m}\left(|\det|^{k-\frac{m}{2}}\boxtimes\mathbbm{1}_{m-n}\right)\simeq \mathbbm{1}_{m-n}\times|\det_n|^{k-\frac{m}{2}}$. This implies the desired formula for $\Ext_{G_n}^*\left(R_{k+1},\eta\right)_{sm}$. The computation of $\Ext_{G_n}^*\left(\omega_{n,m}/R_{k+1},\eta\right)_{sm}$ is similar and we shall not repeat.

\end{proof}

\vskip 5pt

Now apply the functor $\Hom_{G_n}\left(-,\eta\right)_{sm}$ to the short exact sequence (\ref{E:SES-glue-rank-fil}), we get a long exact sequence
\begin{flushleft}
$0 \lra |{\det}_{m-k}|^{\frac{k-n}{2}}\times|{\det}_k|^{\frac{n-m+k}{2}} \lra \Hom_{G_n}\left(\omega_{n,m},\eta\right)_{sm} \xrightarrow{~\mathscr{I}_k~} \mathbbm{1}_{m-n}\times|\det_n|^{k-\frac{m}{2}}$
\end{flushleft}
\begin{flushright}
$\lra  |{\det}_{m-k}|^{\frac{k-n}{2}}\times|{\det}_k|^{\frac{n-m+k}{2}}  \lra \Ext^1_{G_n}\left(\omega_{n,m},\eta\right)_{sm} \lra 0,$   
\end{flushright}
and also
\[
    \Ext^*_{G_n}\left(\omega_{n,m},\eta\right)_{sm} = 0
\]
for all $* \geq 2$. Therefore, to prove Theorem \ref{T:Main-2} it only remains to show that the map $\mathscr{I}_k$ is zero. Recall that $1+m-n\leq k \leq n-1$, so the segment corresponding to $\mathbbm{1}_{m-n}$ is strictly contained in the segment corresponding to $|\det_n|^{k-\frac{m}{2}}$. It follows that $\mathbbm{1}_{m-n}\times|\det_n|^{k-\frac{m}{2}}$ is irreducible. Moreover, by Theorem \ref{T:IndSeg}(2), we have 
\[
    {\rm soc}\left(\Hom_{G_n}\left(\omega_{n,m},\eta\right)_{sm}\right) = {\rm soc}\left(|{\det}_{m-k}|^{\frac{k-n}{2}}\times|{\det}_k|^{\frac{n-m+k}{2}}\right) = \mathbbm{1}_{m-n}\times|{\det}_n|^{k-\frac{m}{2}}.
\]
%\zjl{The first isomorphism ?}
Observe that if we can show that $\Hom_{G_n}\left(\omega_{n,m},\eta\right)_{sm}$ is a socle irreducible representation of $H_m$ (i.e. its socle is irreducible and occurs with multiplicity one), then the map $\mathscr{I}_k$ must be zero; otherwise  
$\mathbbm{1}_{m-n}\times|{\det}_n|^{k-\frac{m}{2}}$
will appear in $\Hom_{G_n}\left(\omega_{n,m},\eta\right)_{sm}$ twice. So to complete the proof of Theorem \ref{T:Main-2} it suffices to show the following lemma.% that $\Hom_{G_n}\left(\omega_{n,m},\eta\right)_{sm}$ is socle irreducible.
%boundary map $\mathscr{B}$ in the long exact sequence is non-zero. 

\vskip 5pt

\iffalse%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
We shall prove that $\mathscr{B} \neq 0$ by contradiction. Suppose on the contrary that $\mathscr{B} = 0$. Then we get a short exact sequence 
\[
    0 \lra |{\det}_{m-k}|^{\frac{k-n}{2}}\times|{\det}_k|^{\frac{n-m+k}{2}} \lra \Hom_{G_n}\left(\omega_{n,m},\eta\right)_{sm} \lra \mathbbm{1}_{m-n}\times|{\det}_n|^{k-\frac{m}{2}} \lra 0
\]
from the long exact sequence above. We claim that this short exact sequence is indeed \textit{split}: consider the first extension group
