\[
    \simeq \Ext^1_{H_{m-k}\times H_k}\left(\Jac_{Q_{m-k}}\left(\mathbbm{1}_{m-n}\times|{\det}_n|^{k-\frac{m}{2}}\right), |{\det}_{m-k}|^{\frac{k-n}{2}}\boxtimes|{\det}_k|^{\frac{n-m+k}{2}}\right),
