\begin{Lem}
Suppose that $n\geq 2$, $n\leq m\leq 2n-2$. Let $\eta = |{\det}_n|^{k-\frac{m}{2}}$ be a character of $G_n$, where $1+m-n\leq k\leq n-1$ is a positive integer. Then 
\[
    \Hom_{G_n}\left(\omega_{n,m},\eta\right)_{sm}
\]    
is socle irreducible.
\end{Lem}

\vskip 5pt

\begin{proof}
We shall prove the lemma by induction on $n\in\Z_{>0}$. The basic case is that $n=m=2$, and $\eta=\mathbbm{1}_2$ is the trivial character of $G_2$. In this case, there is an embedding $\eta\hookrightarrow|\cdot|^{-\frac{1}{2}}\times|\cdot|^{\frac{1}{2}}$. Hence
\begin{align*}
 \Hom_{G_2}\left(\omega_{2,2},\eta\right)_{sm} \hookrightarrow &\Hom_{G_2}\left(\omega_{2,2},|\cdot|^{-\frac{1}{2}}\times|\cdot|^{\frac{1}{2}}\right)_{sm} 
 \simeq  |\cdot|^{-\frac{1}{2}}\times |\cdot|^{\frac{1}{2}}.
\end{align*}
Here in the last identity we have made use of Corollary \ref{C:KudlaIndCompatible} and Theorem \ref{T:Main-1}. Since $|\cdot|^{-\frac{1}{2}}\times |\cdot|^{\frac{1}{2}}$ is socle irreducible, we know that $\Hom_{G_2}\left(\omega_{2,2},\eta\right)_{sm}$ is also socle irreducible. 

\vskip 5pt

Suppose now the lemma holds for all $n'<n$, we prove it also holds for $n$. Let $\eta = |{\det}_n|^{k-\frac{m}{2}}$. Similar to the basic case, one can consider the embedding
\[
    \eta \hookrightarrow |\cdot|^{k+\frac{1-n-m}{2}} \times |{\det}_{n-1}|^{k-\frac{m-1}{2}}.
\]
Note that $k+\frac{1-n-m}{2} < \frac{1+m-n}{2}$. Hence we can apply Corollary \ref{C:KudlaIndCompatible}, it follows that
\[
    \Hom_{G_n}\left(\omega_{n,m},\eta\right)_{sm}\hookrightarrow |\cdot|^{k+\frac{1-n-m}{2}} \times \Hom_{G_{n-1}}\left(\omega_{n-1,m-1},|{\det}_{n-1}|^{k-\frac{m-1}{2}}\right)_{sm}.
\]
To show the representation $\Hom_{G_n}\left(\omega_{n,m},\eta\right)_{sm}$ is socle irreducible, it suffices to show that the socle of $\Hom_{G_n}\left(\omega_{n,m},\eta\right)_{sm}$, namely $\mathbbm{1}_{m-n}\times|{\det}_n|^{k-\frac{m}{2}}$, appears in
\[
   \Pi \coloneqq |\cdot|^{k+\frac{1-n-m}{2}} \times \Hom_{G_{n-1}}\left(\omega_{n-1,m-1},|{\det}_{n-1}|^{k-\frac{m-1}{2}}\right)_{sm}
\]
with multiplicity one. We shall do it by computing some Jacquet modules. Let $d\in\Z_{>0}$, and $Q_{1,d-1}$ %\zjl{Compare with the notation in Proposition \ref{P:KudlaFiltration}. Suggest replace all the notation $P_k$ and $Q_k$ by $P_{i,j}$ and $Q_{i,j}$ } 
be the standard parabolic subgroup of $H_d$ with Levi component $H_1\times H_{d-1}$. For a finite length representation $\pi$ of $H_d$ and a real number $x\in\R$, if the semi-simplified Jacquet module of $\pi$ along $Q_{1,d-1}$ takes the form
\[
    s.s.\Jac_{Q_{1,d-1}}\pi = \sum_\alpha \kappa_\alpha\boxtimes \sigma_\alpha
\]
for some characters $\kappa_\alpha$ of $H_1$ and irreducible representations $\sigma_\alpha$ of $H_{d-1}$, then we set 
\[
    \Jac_{x}\pi = \sum_{\left\{\alpha\,:\,\kappa_\alpha=|\cdot|^x\right\}} \sigma_\alpha,
\]
which is a finite length semi-simple representation of $H_{d-1}$. Note that $k+\frac{1-n-m}{2} < \frac{1-m+n}{2}$. Hence on the one hand by Proposition \ref{P:JacSeg} and the geometric lemma we have 
\[
     \Jac_{k+\frac{1-n-m}{2}}\left(\mathbbm{1}_{m-n}\times|{\det}_n|^{k-\frac{m}{2}}\right) = \mathbbm{1}_{m-n}\times|{\det}_{n-1}|^{k-\frac{m-1}{2}}
\]
is non-zero and irreducible. On the other hand, again by the geometric lemma, we have 
\begin{flushleft}
$\Jac_{k+\frac{1-n-m}{2}} \Pi = \Hom_{G_{n-1}}\left(\omega_{n-1,m-1},|{\det}_{n-1}|^{k-\frac{m-1}{2}}\right)_{sm} + $
\end{flushleft}
\begin{flushright}
    $|\cdot|^{k+\frac{1-n-m}{2}} \times \Jac_{k+\frac{1-n-m}{2}}\Hom_{G_{n-1}}\left(\omega_{n-1,m-1},|{\det}_{n-1}|^{k-\frac{m-1}{2}}\right)_{sm}.$
\end{flushright}
There are two cases depending on the positive integer $k$, and now we discuss case by case.

\vskip 5pt

$\bullet$ \textit{Case 1}: if $1+m-n\leq k\leq n-2$, then by the induction hypothesis the representation $\Hom_{G_{n-1}}\left(\omega_{n-1,m-1},|{\det}_{n-1}|^{k-\frac{m-1}{2}}\right)_{sm}$ is socle irreducible. Therefore by above discussions, Theorem \ref{T:Main-2} holds for $|{\det}_{n-1}|^{k-\frac{m-1}{2}}$, namely
\[
    \Hom_{G_{n-1}}\left(\omega_{n-1,m-1},|{\det}_{n-1}|^{k-\frac{m-1}{2}}\right)_{sm} \simeq |{\det}_{m-k-1}|^{\frac{k-n+1}{2}}\times|{\det}_k|^{\frac{n-m+k}{2}}.
\]
So once again by Proposition \ref{P:JacSeg} and the geometric lemma we have
\[
    \Jac_{k+\frac{1-n-m}{2}}\Hom_{G_{n-1}}\left(\omega_{n-1,m-1},|{\det}_{n-1}|^{k-\frac{m-1}{2}}\right)_{sm}
\]
\[
    =\left(\Jac_{k+\frac{1-n-m}{2}}|{\det}_{m-k-1}|^{\frac{k-n+1}{2}}\right)\times|{\det}_k|^{\frac{n-m+k}{2}} + |{\det}_{m-k-1}|^{\frac{k-n+1}{2}}\times \left(\Jac_{k+\frac{1-n-m}{2}}|{\det}_k|^{\frac{n-m+k}{2}}\right)
\]
vanishes. Combining these together we get
\[
    \Jac_{k+\frac{1-n-m}{2}} \Pi \simeq |{\det}_{m-k-1}|^{\frac{k-n+1}{2}}\times|{\det}_k|^{\frac{n-m+k}{2}}.
\]
According to Theorem \ref{T:IndSeg}(2), the degenerate principal series on the right hand side of above is of length two, with non-isomorphic sub and quotient. Hence $\mathbbm{1}_{m-n}\times|{\det}_n|^{k-\frac{m}{2}}$ can only appear in $\Pi$ once.

\vskip 5pt

$\bullet$ \textit{Case 2}: if $k=n-1$, then by Proposition \ref{P:GJLfunction} the L-function $L\left(s,|{\det}_{n-1}|^{k-\frac{m-1}{2}}\right)$ is holomorphic at $s=\frac{1+m-n}{2}$. So we are in a situation that Theorem \ref{T:Main-1} is applicable, we have 
\[
    \Hom_{G_{n-1}}\left(\omega_{n-1,m-1},|{\det}_{n-1}|^{k-\frac{m-1}{2}}\right)_{sm} \simeq \mathbbm{1}_{m-n}\times |{\det}_{n-1}|^{k-\frac{m-1}{2}}.
\]
Similar to the previous case, it follows that
\[
    \Jac_{k+\frac{1-n-m}{2}}\Hom_{G_{n-1}}\left(\omega_{n-1,m-1},|{\det}_{n-1}|^{k-\frac{m-1}{2}}\right)_{sm}
\]
\[
    =\left(\Jac_{k+\frac{1-n-m}{2}}\mathbbm{1}_{m-n}\right)\times|{\det}_{n-1}|^{k-\frac{m-1}{2}} + \mathbbm{1}_{m-n}\times \left(\Jac_{k+\frac{1-n-m}{2}}|{\det}_{n-1}|^{k-\frac{m-1}{2}}\right)
\]
vanishes. Combining these together we get
\[
    \Jac_{k+\frac{1-n-m}{2}} \Pi \simeq \mathbbm{1}_{m-n}\times |{\det}_{n-1}|^{k-\frac{m-1}{2}}.
\]
According to Theorem \ref{T:IndSeg}, the degenerate principal series on the right hand side of above is either irreducible, or of length two with non-isomorphic sub and quotient. Hence $\mathbbm{1}_{m-n}\times|{\det}_n|^{k-\frac{m}{2}}$ can only appear in $\Pi$ once.

\vskip 5pt

This shows that the lemma also holds for $n$, hence completes the proof.

\end{proof}

\vskip 5pt

As we have explicated, the vanishing of the map $\mathscr{I}_k$ is a direct consequence of this lemma, and Theorem \ref{T:Main-2} then follows from the vanishing of $\mathscr{I}_k$.

\vskip 5pt

\begin{Rmk}
In the special case $n=m=2$ and $k=1$, Xue showed this map $\mathscr{I}_1=0$ \cite[Prop. 2.9]{xue2023full} using a completely different way. His idea is to consider the Haar measure (twisted by determinant) $D$ on $G_2$, which gives rise to an invariant distribution on $\Omega_2$. Given this $D$, he constructed a particular extension $\widetilde{D}$ to $M_{2,2}$ by considering the constant term of the Laurent expansion of the zeta integral. This $\widetilde{D}$ is generalized semi-invariant but not invariant, because of the pole of the zeta integral. Then he showed that there is no invariant extension of $D$ using this particular extension $\widetilde{D}$: suppose such an invariant extension $\widetilde{D}'$ exists, then 
\[
    \widetilde{D}- \widetilde{D}'
\]
yields a generalized semi-invariant distribution supported on $M_{2,2}\backslash \Omega_2$; but on $M_{2,2}\backslash \Omega_2$ generalized semi-invariance implies invariance, so $\widetilde{D} = \widetilde{D}' + \left(\widetilde{D} - \widetilde{D}'\right)$ is also invariant, this leads to a contradiction. This implies that $D$ is not in the image of $\mathscr{I}_k$, so $\mathscr{I}_k=0$.

\vskip 5pt

It would be interesting if one can adapt Xue's argument to $2\leq n\leq m$, or to the Archimedean case.

\end{Rmk}

