\section{Proof of the main theorem III} % (fold)
\label{sec:proof_of_the_main_theorem_iii}

Throughout this section we assume that $n\leq m$. Our main purpose is to prove the main result III: Theorem \ref{T:Main-3}. By Theorem \ref{T:Main-2}, we only need to show that if $m\geq 2n-1$, then $\omega_{n,m}$ is projective. 
After showing this, we will give an upper bound of the \textit{projective dimension} of the $K$-fixed part $\omega_{n,m}^K$ of the Weil representation when $n\leq m\leq 2n-2$, where $K$ is an open compact subgroup of $H_m$.

\vskip 5pt

\subsection{Locally finiteness of the Weil representation} % (fold)
\label{sub:locally_finiteness_of_the_weil_representation}

We first show that, given an open compact subgroup $K$ of $H_m$, then the ``level $K$'' Weil representation, i.e. $\omega_{n,m}^K$, is a so called \textit{locally finite} representation of $G_n$, as defined in \cite[Def. 5.2]{MR4054816}. The tool that we shall use is the rank filtration (Lemma \ref{L:rank-filtration}). By the definition of locally finite representations, it suffices to show that (the ``level $K$'' part of) each graded piece of the rank filtration
\[
    \tau_i^K \simeq \left(\Ind_{P_i\times \overline{Q}_i}^{G_n\times H_m} \left(\omega^\natural_i\otimes\xi_i\right)\right)^K
\]
is actually a locally finite representation of $G_n$. %Fix a maximal compact subgroup $K_H$ of $H_m$ with the property that we have the Iwasawa decomposition $H_m = \overline{Q}_i\cdot K_H$. 
Since here we are mainly concerned about the $G_n$-module structure, we can rewrite the right hand side of above as 
\begin{equation}\label{E:LocallyFiniteLevelK}
    \left(\Ind_{P_i\times \overline{Q}_i}^{G_n\times H_m} \left(\omega^\natural_i\otimes\xi_i\right)\right)^K \simeq \bigoplus_{x\,\in \,\overline{Q}_i\backslash H_m /K} \left(\Ind_{P_i}^{G_n}\left(\omega^\natural_i\otimes\xi_i\right)\right)^{\overline{Q}_i\,\cap\, x\cdot K\cdot x^{-1}}.
\end{equation}
Here the isomorphism is given by sending a function
\[
    f\in \left(\Ind_{P_i\times \overline{Q}_i}^{G_n\times H_m} \left(\omega^\natural_i\otimes\xi_i\right)\right)^K \simeq \left(\Ind_{\overline{Q}_i}^{H_m}\left(\Ind_{P_i}^{G_n}\left(\omega^\natural_i\otimes\xi_i\right)\right)\right)^K
\]
to its values at a set of representatives of the double coset $\overline{Q}_i\backslash H_m /K$. Note that the double coset $\overline{Q}_i\backslash H_m /K$ is finite. Therefore we only need to show that each summand appearing on the right hand side of (\ref{E:LocallyFiniteLevelK}) is locally finite. Let $K_x$ be an open compact subgroup of $H_i$, such that $K_x\subset \overline{Q}_i\cap x\cdot K\cdot x^{-1}$. Then
\[
    \left(\Ind_{P_i}^{G_n}\left(\omega^\natural_i\otimes\xi_i\right)\right)^{\overline{Q}_i\,\cap\, x\cdot K\cdot x^{-1}} \subset \Ind_{P_i}^{G_n}\left(\left(\omega^\natural_i\right)^{K_x}\otimes\xi_i\right).
\]
Easy to see that $\left(\omega^\natural_i\right)^{K_x}\otimes\xi_i$ is a locally finite representation of the Levi subgroup $G_i\times G_{n-i}$ of $P_i$. Since the parabolic induction functor preserves locally finiteness, we know that the representation $\Ind_{P_i}^{G_n}\left(\left(\omega^\natural_i\right)^{K_x}\otimes\xi_i\right)$ is locally finite. Therefore by the Noetherian property of the category $\calM\left(G\right)$, its subrepresentation $\left(\Ind_{P_i}^{G_n}\left(\omega^\natural_i\otimes\xi_i\right)\right)^{\overline{Q}_i\,\cap\, x\cdot K\cdot x^{-1}}$ is also locally finite.

\vskip 5pt

This completes the proof of the locally finiteness of $\omega_{n,m}^K$.

\vskip 5pt

% subsection locally_finiteness_of_the_weil_representation (end)


\subsection{Zelevinsky's classification and Ext-vanishing} % (fold)
\label{sub:zelevinsky_s_classification_and_ext_vanishing}

Secondly, we shall prove that the ``level $K$'' part of the Weil representation $\omega_{n,m}^K$ is projective as a representation of $G_n$ when $m\geq 2n-1$. Since we already know that $\omega_{n,m}^K$ is locally finite, by the result of Chan--Savin \cite[Thm. A.1]{MR3910471}, it suffices to show that 
\begin{equation}\label{E:ExtVanishingLevelK}
    \Ext_{G_n}^*\left(\omega_{n,m}^K,\pi\right) = 0
\end{equation}
for all irreducible smooth representation $\pi$ of $G_n$ and all $* >0$. By the proof of \cite[Lem. 5.14]{MR3753906}, one knows that
\[
    \Ext_{G_n}^*\left(\omega_{n,m}^K,\pi\right) \simeq \Ext_{G_n}^*\left(\omega_{n,m},\pi\right)^K.
\]
Therefore the desired Ext-vanishing result (\ref{E:ExtVanishingLevelK}) follows from the following lemma.

\begin{Prop}\label{P:AlmostStableRangeExtVanishing}
Suppose that $m\geq 2n-1$. Then for any irreducible representation $\pi$ of $G_n$ and any $*>0$, we have
\[
    \Ext_{G_n}^*\left(\omega_{n,m},\pi\right)_{sm} = 0.
\]  
\end{Prop}

\vskip 5pt

\begin{proof}
We shall prove this proposition by induction on $n$. The desired conclusion for $n=1$ is already shown in \cite[Lem. 6.1]{MR3753906}, so we assume that $n\geq 2$, and the desired conclusion holds for all $n'<n$. Given an irreducible representation $\pi$ of $G_n$. If $\pi$ is supercuspidal, consider the rank filtration of the Weil representation (see Lemma \ref{L:rank-filtration}). For any $0\leq i <n$ and any $*\geq 0$, by the supercuspidality of $\pi$ we have
\[
    \Ext_{G_n}^*\left(\tau_i, \pi\right)_{sm} \simeq \Ind_{\overline{Q}_i}^{H_m} \Ext_{G_i\times G_{n-i}}^*\left(\omega_{i}^\natural\otimes\xi_i, \Jac_{\overline{P}_i}\pi\right)_{sm} = 0.
\]
Therefore it follows that
\[
    \Ext_{G_n}^*\left(\tau_i, \pi\right)_{sm} \simeq \Ind_{\overline{Q}_n}^{H_m}\left(\Ext_{G_n}^*\left(\omega_n^\natural, \pi\right)_{sm}\otimes\xi_n\right)
\]
for all $*>0$. If $\pi$ is not supercuspidal, then by the \textit{Zelevinsky's classification} \cite[Thm. 6.1]{ZeleII}, we can write $\pi$ as a quotient
\[
    \Speh\left(\Delta_1\right) \times \Speh\left(\Delta_2\right) \times \cdots \times \Speh\left(\Delta_r\right) \twoheadrightarrow \pi,  
\]
where $\Delta_i = \left[x_i,y_i\right]_{\rho_i}$, and $x_1+y_1 \leq x_2+y_2 \leq \cdots \leq x_r+y_r$. Note that by Corollary \ref{C:ExtvsMVW}, without loss of generality we can assume that the central exponent of $\pi$ is non-positive. Under this assumption we have
\[
    x_1+ y_1\leq 0.
\]
On the other hand, suppose that $\rho_i$ is an irreducible supercuspidal representation of $G_{k_i}$, then $G_{k_1(x_1-y_1+1)}\times G_{k_2(x_2-y_2+1)} \times \cdots\times G_{k_r(x_r-y_r+1)}$ is a Levi subgroup of $G_n$, in particular
\[
    k_1\left(x_1-y_1+1\right) \leq n.
\]
These two inequalities, together with the assumption $m\geq 2n-1$, imply that
\[
    x_1 \leq \frac{n-1}{2} < \frac{1+m-n}{2}.
\]
Now let $\Pi = \Speh\left(\left[x_1-1,y_1\right]_{\rho_1}\right) \times \Speh\left(\Delta_2\right) \times \cdots \times \Speh\left(\Delta_r\right)$, so $\pi$ is a quotient of $\rho_1|\det|^{x_1}\times\Pi$, and we complete this quotient map to a short exact sequence  
\[
    0 \lra \varkappa \lra \rho_1|\det|^{x_1}\times\Pi \lra \pi \lra 0.
\]
Here $\varkappa$ is a finite length representation of $G_n$. Applying the functor $\Hom_{G_n}\left(\omega_{n,m},-\right)$ to this short exact sequence, we get 
\[
    \cdots\ra\Ext_{G_n}^*\left(\omega_{n,m},\rho_1|\det|^{x_1}\times\Pi\right)_{sm} \lra \Ext_{G_n}^*\left(\omega_{n,m},\pi\right)_{sm} \lra \Ext_{G_n}^{*+1}\left(\omega_{n,m},\varkappa\right)_{sm}\ra\cdots
\]
Since $x_1 < \frac{1+m-n}{2}$, we may invoke Corollary \ref{C:KudlaIndCompatible}, which gives
\[
    \Ext_{G_n}^*\left(\omega_{n,m},\rho_1|\det|^{x_1}\times\Pi\right)_{sm} \simeq \rho_1|\det|^{x_1}\times \Ext_{G_n}^*\left(\omega_{n-k_1,m-k_1},\Pi\right)_{sm} = 0.
\]
Here in the second equality, we have made use of our induction hypothesis. Therefore in order to prove the proposition it only remains to show that for any irreducible representation $\pi$, we have 
\begin{equation*}%\label{P:Main-IExtvanishshift1}
    \Ext_{G_n}^{*+1}\left(\omega_{n,m},\pi\right)_{sm} = 0.
\end{equation*}
Repeating this argument, eventually we can reduce the desired conclusion to showing that
\begin{equation*}%\label{E:Main-IExtvanishshift1}
    \Ext_{G_n}^{*+n}\left(\omega_{n,m},\pi\right)_{sm} = 0
\end{equation*}
for all irreducible representation $\pi$, which simply follows from \cite[Pg. 98, Sect. 4.2]{BNote}. Hence the proposition also holds for $n$.

\end{proof}

\vskip 5pt

Thirdly, we pass from the ``level $K$'' part $\omega_{n,m}^K$ to the whole $\omega_{n,m}$. Fix an open compact subgroup $K$ of $H_m$. Then we can decompose $\omega_{n,m}$ into a direct sum
\[
    \omega_{n,m} = \bigoplus_{\sigma\in\Irr\left(K\right)} \omega_\sigma,
\]
where each $\omega_\sigma \simeq \Hom_{K}\left(\sigma,\omega_{n,m}\right)\boxtimes\sigma$ is the $\sigma$-isotypic component of $\omega_{n,m}$; it is a $G_n\times K$-submodule of $\omega_{n,m}$. For each $\sigma\in\Irr\left(K\right)$, since $\sigma$ is finite dimensional, there exists an open compact subgroup $K_0$ of $K$, such that all vectors in $\omega_\sigma$ is fixed by $K_0$. It follows that $\omega_\sigma$ is a direct summand of
\[
    \omega_{n,m}^{K_0} = \bigoplus_{\sigma'\in\Irr\left(K\right)} \omega_{\sigma'}^{K_0}.
\]
Since we have proved that $\omega_{n,m}^{K_0}$ is a projective $G_n$-module, its direct summand $\omega_\sigma$ is also a projective $G_n$-module. Therefore, being a direct sum of projective modules $\omega_\sigma$, $\omega_{n,m}$ is itself projective.

\vskip 5pt

% subsection zelevinsky_s_classification_and_ext_vanishing (end)

\subsection{Projective dimension of the Weil representation} % (fold)
\label{sub:projective_dimension_of_the_weil_representation}

In this subsection, we assume that $m\leq 2n-2$; so by Theorem \ref{T:Main-2}, the Weil representation $\omega_{n,m}$ is \textit{not} projective as a $G_n$-module. As usual, given an open compact subgroup $K$ of $H_m$, one can consider the projective dimension of $\omega_{n,m}^K$: if 
\[
    0 \lra \calP_d \lra \calP_{d-1} \lra \cdots \lra \calP_1 \lra\calP_0 \lra 0
\]
is a projective resolution of $\omega_{n,m}^K$ in the category $\calM\left(G_n\right)$ of minimal length, then one sets
\[
    {\rm proj.}\dim \omega_{n,m}^K = d.
\]
Likewise, one can also consider projective dimension of $\omega_{n,m}$ itself, which is defined in the same manner. The advantage of working with $\omega_{n,m}^K$ instead of $\omega_{n,m}$ is that $\omega_{n,m}^K$, as we have already seen in Section \ref{sub:locally_finiteness_of_the_weil_representation}, is a locally finite representation of $G_n$. The main purpose of this subsection is to prove the following result.

\begin{Prop}\label{P:BoundExtVanishingDegree}
Suppose that $n\geq 2$, and $n\leq m\leq 2n-2$. Then for any open compact subgroup $K$ of $H_m$, we have
\[
    {\rm proj.}\dim \omega_{n,m}^K \leq \left\lceil n - \frac{m+1}{2}\right\rceil.
\]  
Here for $x\in\R$, we denote by $\left\lceil x \right\rceil$ the smallest integer greater than or equal to $x$. 
\end{Prop}

\vskip 5pt

\begin{proof}
Since $\omega_{n,m}^K$ is locally finite, by some elementary homological algebra argument, we know that ${\rm proj.}\dim \omega_{n,m}^K \leq \left\lceil n - \frac{m+1}{2}\right\rceil$ if and only if 
\[
    \Ext_{G_n}^*\left(\omega_{n,m}^K,\pi\right) = 0
\]
holds for all irreducible representation $\pi$ of $G_n$ and all $*>\left\lceil n - \frac{m+1}{2}\right\rceil$. Let $K$ varies. Then these Ext spaces vanish for all $K$ if and only if
\begin{equation}\label{E:BoundingProjDim}
    \Ext_{G_n}^*\left(\omega_{n,m},\pi\right)_{sm} = 0.
\end{equation}
So next we shall prove (\ref{E:BoundingProjDim}) by induction on $n$.

\vskip 5pt

The basic case is when $n=m=2$. In this case, one can check that there is only one representation $\pi$ of $G_2$ such that both $L\left(s,\pi\right)$ and $L\left(s,\pi^\vee\right)$ are not holomorphic at $s=1/2$, namely the trivial representation $\mathbbm{1}_2$. Hence for non-trivial irreducible representation $\pi$ of $G_2$, by Theorem \ref{T:Main-1} all these Ext spaces vanish when $*>0$. Moreover, all Ext spaces associated to $\omega_{2,2}$ and $\mathbbm{1}_2$ have been computed in Theorem \ref{T:Main-2}. Hence the desired conclusion can be checked by hand.

\vskip 5pt

Suppose now the desired conclusion (\ref{E:BoundingProjDim}) has been proved for all $n'<n$. Let $\pi$ be an irreducible representation of $G_n$. If $\pi$ is supercuspidal, then by the same argument as in the proof of Proposition \ref{P:AlmostStableRangeExtVanishing}, we know that (\ref{E:BoundingProjDim}) holds for $\pi$. If $\pi$ is not supercuspidal, then there exists a positive integer $0<k<n$, an irreducible supercuspidal representation $\rho$ of $G_k$ and an irreducible representation $\pi_0$ of $G_{n-k}$, such that there is a surjection
\[
    \rho\times\pi_0 \twoheadrightarrow \pi.
\]
By a standard degree shifting argument, to show that (\ref{E:BoundingProjDim}) holds for $\pi$, it suffices to show that
\begin{equation}\label{E:BoundingExtDegIndRep}
    \Ext_{G_n}^*\left(\omega_{n,m}, \rho\times\pi_0\right)_{sm} = 0
\end{equation}
for all $*>\left\lceil n - \frac{m+1}{2}\right\rceil$. If $k\neq 1$, or $\rho\not\simeq|\cdot|^{\frac{1+m-n}{2}}$, then the desired conclusion follows from the combination of Corollary \ref{C:KudlaIndCompatible} and the induction hypothesis. On the other hand, if $k=1$ and $\rho\simeq|\cdot|^{\frac{1+m-n}{2}}$, we shall appeal to the Kudla's filtration directly. Let $P_1$ be the standard parabolic subgroup of $G_n$ with Levi component $G_1\times G_{n-1}$. Then by the Frobenius reciprocity we have
\[
    \Ext_{G_n}^*\left(\omega_{n,m}, \rho\times\pi_0\right)_{sm} \simeq \Ext_{G_1\times G_{n-1}}^*\left(\Jac_{P_1}\omega_{n,m}, \rho\boxtimes\pi_0\right)_{sm}.
\]
By Proposition \ref{P:KudlaFiltration}, there is a two-step filtration on $\Jac_{P_1}\omega_{n,m}$:
\[
    0 = J_2 \subset J_1 \subset J_0 = \Jac_{P_1}\omega_{n,m},
\]
whose successive quotient $\lambda_i = J_i/J_{i+1}$ can be described as follows:
\[
    \lambda_0 \simeq |\cdot|^{\frac{1+m-n}{2}} \boxtimes \omega_{n-1,m},
\]
and 
\[
    \lambda_1 \simeq \Ind_{Q_1}^{H_m}\left(\omega_1^\natural\boxtimes\omega_{n-1,m-1}\right).
\]
Applying the functor $\Hom_{G_n}\left(\omega_{n,m},-\right)_{sm}$ to this short exact sequence
\[
    0 \lra \lambda_1 \lra \Jac_{P_1}\omega_{n,m} \lra \lambda_0 \lra 0,
\]
we obtain the long exact sequence
\[
    \cdots\ra\Ext^*_{G_n}\left(\lambda_0, \rho\boxtimes\pi_0\right)_{sm} \lra \Ext^*_{G_n}\left(\Jac_{P_1}\omega_{n,m}, \rho\boxtimes\pi_0\right)_{sm} \lra \Ext^{*}_{G_n}\left(\lambda_1, \rho\boxtimes\pi_0\right)_{sm}\ra\cdots
\]
By the K\"unneth formula Theorem \ref{T:Kunneth}, we have
\begin{align*}
 \Ext^*_{G_n}\left(\lambda_0, \rho\boxtimes\pi_0\right)_{sm} = \Ext_{G_{n-1}}^{*-1}\left(\omega_{n-1,m},\pi_0\right)_{sm} \oplus \Ext_{G_{n-1}}^{*}\left(\omega_{n-1,m},\pi_0\right)_{sm}.
\end{align*}
Both two Ext spaces on the right hand side of above vanish when $*>\left\lceil n - \frac{m+1}{2}\right\rceil$ by the induction hypothesis. Moreover, we always have
\[
    \Ext^{*}_{G_n}\left(\lambda_1, \rho\boxtimes\pi_0\right)_{sm} \simeq \rho\times \Ext^{*}_{G_{n-1}}\left(\omega_{n-1,m-1}, \pi_0\right)_{sm},
\]
which also vanishes when $*>\left\lceil n - \frac{m+1}{2}\right\rceil$ by the induction hypothesis. Therefore (\ref{E:BoundingExtDegIndRep}) holds, and it follows that (\ref{E:BoundingProjDim}) holds for $n$. This completes the proof of the proposition.

\end{proof}

\vskip 5pt

Unfortunately, this bound is not sharp. For example, when $n=m=4$, $\left\lceil n - \frac{m+1}{2}\right\rceil=2$. However, with a bit more effort, one can show that
\begin{equation}\label{E:G4Ext2vanish}
    \Ext_{G_4}^*\left(\omega_{4,4},\pi\right)_{sm} =0
\end{equation} 
for all irreducible representation $\pi$ of $G_4$ and all $*>1$. Indeed, by a standard degree shifting argument, to show (\ref{E:G4Ext2vanish}), it suffices to show that: for any irreducible representation $\pi$ of $G_4$, there exists a finite length representation $\Pi$ of $G_4$, such that $\pi$ is a quotient of $\Pi$, and
\[
    \Ext_{G_4}^2\left(\omega_{4,4}, \Pi\right)_{sm} = 0.
\] 
We now check this when $\pi$ belongs to the principal Bernstein block (i.e. the Bernstein block corresponding to the cuspidal component $\left[T_4, \mathbbm{1}_{T_4}\right]$, where $T_4$ is the diagonal torus of $G_4$, and $\mathbbm{1}_{T_4}$ is the trivial representation of $T_4$). For other Bernstein blocks, the proof is similar (and easier). So we can take $\Pi= \chi_1\times\chi_2\times\chi_3\times\chi_4$ to be a principal series representation such that there is a surjection
\[
    \chi_1\times\chi_2\times\chi_3\times\chi_4 \twoheadrightarrow \pi.
\]
Similar to the proof of Proposition \ref{P:BoundExtVanishingDegree}, by using the Frobenius reciprocity and the Kudla's filtration we obtain an exact sequence
\begin{flushleft}
$\cdots \lra \Ext_{G_1\times G_3}^2\left(|\cdot|^{\frac{1}{2}}\boxtimes\omega_{3,4},\chi_1\boxtimes\left(\chi_2\times\chi_3\times\chi_4\right)\right)_{sm} $
\end{flushleft}
\begin{flushright}
$\lra\Ext_{G_4}^2\left(\omega_{4,4},\chi_1\times\chi_2\times\chi_3\times\chi_4\right)_{sm} \lra \chi_1\times\Ext_{G_3}^2\left(\omega_{3,3}, \chi_2\times\chi_3\times\chi_4\right)_{sm} \lra \cdots$   
\end{flushright}
It follows from Proposition \ref{P:BoundExtVanishingDegree} that
\[
    \Ext_{G_3}^2\left(\omega_{3,3}, \chi_2\times\chi_3\times\chi_4\right)_{sm} =0.
\]
On the other hand, by the K\"unneth formula Theorem \ref{T:Kunneth} and also Proposition \ref{P:BoundExtVanishingDegree} we have
\begin{flushleft}
    $\Ext_{G_1\times G_3}^2\left(|\cdot|^{\frac{1}{2}}\boxtimes\omega_{3,4},\chi_1\boxtimes\left(\chi_2\times\chi_3\times\chi_4\right)\right)_{sm}$
\end{flushleft}
\begin{flushright}
    $\simeq \Ext^1_{G_1}\left(|\cdot|^{\frac{1}{2}},\chi_1\right)\otimes\Ext_{G_3}^1\left(\omega_{3,4}, \chi_2\times\chi_3\times\chi_4\right)_{sm}$.
\end{flushright}
There are three cases.

\vskip 5pt

$\bullet$ \textit{Case 1}: if $\chi_1\not\simeq|\cdot|^{\frac{1}{2}}$, then by Lemma \ref{L:ExtSteinberg}, we have
\[
    \Ext^1_{G_1}\left(|\cdot|^{\frac{1}{2}},\chi_1\right)=0.
\]

\vskip 5pt

$\bullet$ \textit{Case 2}: if $\chi_1\simeq|\cdot|^{\frac{1}{2}}$ but $\chi_2\not\simeq |\cdot|^1$, then by Corollary \ref{C:KudlaIndCompatible}, we have
\[
    \Ext_{G_3}^1\left(\omega_{3,4}, \chi_2\times\chi_3\times\chi_4\right)_{sm} \simeq \chi_2 \times \Ext_{G_2}^1\left(\omega_{2,3}, \chi_3\times\chi_4\right)_{sm}.
\]
Thanks to Theorem \ref{T:Main-3}, we have $\Ext_{G_2}^1\left(\omega_{2,3}, \chi_3\times\chi_4\right)_{sm}=0$, since $\omega_{2,3}$ is projective.

\vskip 5pt

$\bullet$ \textit{Case 3}: if $\chi_1\simeq|\cdot|^{\frac{1}{2}}$ and $\chi_2\simeq |\cdot|^1$, then 
\[
    \chi_1\times\chi_2\simeq \chi_2\times\chi_1.
\]
Therefore we can exchange the role of $\chi_1$ and $\chi_2$ by exchanging the induction order in $\Pi$, and reduce this case to Case 1 above.

\vskip 5pt

In conclusion, we always have
\[
    \Ext_{G_1\times G_3}^2\left(|\cdot|^{\frac{1}{2}}\boxtimes\omega_{3,4},\chi_1\boxtimes\left(\chi_2\times\chi_3\times\chi_4\right)\right)_{sm} = 0.
\]
This implies that $\Ext_{G_4}^2\left(\omega_{4,4},\Pi\right)_{sm}=0$ as desired. Combining Proposition \ref{P:BoundExtVanishingDegree} with these computations, we get the following consequence.

\begin{Cor}
Suppose that $n\leq 4$, and $n\leq m$. Then for any open compact subgroup $K$ of $H_m$, we have
\[
    {\rm proj.}\dim \omega_{n,m}^K \leq 1.
\]   
\end{Cor}

\vskip 5pt

\begin{Rmk}
It is worth noting that, among all examples we have computed, there is no irreducible representation $\pi$ of $G_n$ such that $\Ext_{G_n}^2\left(\omega_{n,m},\pi\right)_{sm}\neq 0$. It is interesting to ask: do we always have
\[
    {\rm proj.}\dim \omega_{n,m}^K \leq 1?
\] 
Also, throughout this subsection we only consider the ``level $K$'' part $\omega_{n,m}^K$. One can also ask what is the relation between ${\rm proj.}\dim \omega_{n,m}$ and ${\rm proj.}\dim \omega_{n,m}^K$. For example, do we have
\[
    {\rm proj.}\dim \omega_{n,m} = \sup_K\left\{{\rm proj.}\dim \omega_{n,m}^K\right\}?
\]
We do not know the answer.
\end{Rmk}

% subsection projective_dimension_of_the_weil_representation (end)

\vskip 10pt

% section proof_of_the_main_theorem_iii (end)


\section{Further evidence for the speculation: low rank examples} % (fold)
\label{sec:speculation_ext_spaces_versus_l_functions}

In this section we provide further evidences for our speculations Question \ref{Q:ExtcontrolLfunction}. %and Question \ref{Speculation-2:ExtGGPandRakinSelberg} by computing some examples.
%\vskip 5pt
%\subsection{Zeta integrals of non-irreducible representations} % (fold)
%\label{sub:zeta_integrals_of_non_irreducible_representations}
The main goal is to prove Proposition \ref{P:leq3computation}. Before we begin the proof, we briefly describe the idea. Suppose that $n=m$, and $\pi$ is an irreducible representation of $G_n$ such that both $L\left(s,\pi\right)$ and $L\left(s,\pi^\vee\right)$ have poles at $s=1/2$. If we can show that $\Hom_{G_n}\left(\omega_{n,n},\pi\right)_{sm}$ is not irreducible, then by Theorem \ref{T:APS-EP-fomula} there must exist some $*>0$ such that
\[
    \Ext_{G_n}^*\left(\omega_{n,n},\pi\right)_{sm} \neq 0,
\]
which completes the proof. Our idea to show the reducibility of $\Hom_{G_n}\left(\omega_{n,n},\pi\right)_{sm}$ is as follows. Suppose that we can find a \textit{length two} representation $\Pi$, such that: 
\begin{itemize}
    \item $\Pi$ fits into a short exact sequence
    \[
        0 \lra \pi \lra \Pi \lra \pi' \lra 0,
    \]
    which is \textit{non-split}, and $\pi\not\simeq \pi'$;

    \vskip 5pt

    \item the assertions in \cite[Thm. 3.3(1)-(3)]{MR342495} hold for $\Pi$, and $L\left(s,\Pi\right) = L\left(s,\pi\right)$;

    \vskip 5pt

    \item the ratio of the L-functions
    $L\left(s,\pi'\right)/L\left(s,\pi\right)$
    has a \textit{zero} at $s=1/2$.
\end{itemize}
\vskip 5pt
Given such a representation $\Pi$, the zeta integral of $\Pi$ then yields a non-zero map
\[
    \frac{Z\left(\frac{1}{2},-,-\right)}{L\left(\frac{1}{2},\Pi\right)}: \Pi \lra \Hom_{G_n}\left(\omega_{n,n}, \Pi\right)_{sm}.
\]
Since we have assumed that $L\left(s,\pi'\right)/L\left(s,\pi\right)$ has a zero at $s=1/2$, easy to check this map factors through the inclusion
\[
    \Hom_{G_n}\left(\omega_{n,n}, \pi\right)_{sm} \hookrightarrow \Hom_{G_n}\left(\omega_{n,n}, \Pi\right)_{sm},
\]
Hence we get a non-zero map
\[
    \Pi \lra \Hom_{G_n}\left(\omega_{n,n}, \pi\right)_{sm}.
\]
Note that by the Howe duality Theorem \ref{T:HoweDuality}, this map must be injective. Therefore the Hom space $\Hom_{G_n}\left(\omega_{n,n},\pi\right)_{sm}$ is not irreducible. As an example, when $n=m=2$ and $\pi=\mathbbm{1}_2$ is the trivial representation, $\Pi = |\cdot|^{-\frac{1}{2}}\times|\cdot|^{\frac{1}{2}}$ satisfies these requirements. 

\vskip 5pt

Now back to the proof of Proposition \ref{P:leq3computation}. As explicated in Section \ref{sub:speculation_i}, it only remains to check the case $n=m=3$. There are several subcases, we consider them separately.

\vskip 5pt

$\bullet$ \textit{Subcase 1}: $\pi\simeq|\det|^{\pm\frac{1}{2}}$ is a character. We have already proved in Theorem \ref{T:Main-2} that $\Hom_{G_3}\left(\omega_{3,3},\pi\right)_{sm}$ is not irreducible. 

\vskip 5pt

$\bullet$ \textit{Subcase 2}: $\pi\simeq \chi\times\mathbbm{1}_2$ for some character $\chi\in\Irr\left(G_1\right)\backslash\left\{|\cdot|^{\pm\frac{3}{2}}\right\}$. By Corollary \ref{C:ExtvsMVW}, without loss of generality we may assume that $\chi\not\simeq|\cdot|^{\frac{1}{2}}$. Applying Corollary \ref{C:KudlaIndCompatible}, we get
\[
    \Hom_{G_3}\left(\omega_{3,3},\pi\right)_{sm} \simeq \chi \times \Hom_{G_2}\left(\omega_{2,2},\mathbbm{1}_2\right)_{sm}.
\]
Since $\Hom_{G_2}\left(\omega_{2,2},\mathbbm{1}_2\right)_{sm}$ is not irreducible, $\Hom_{G_3}\left(\omega_{3,3},\pi\right)_{sm}$ is also not irreducible.

\vskip 5pt

$\bullet$ \textit{Subcase 3}: $\pi\simeq LQ\left(\St\left(\Delta_+\right)\times |\cdot|^{-\frac{1}{2}}\right)$ or $\pi \simeq LQ\left(|\cdot|^{\frac{1}{2}}\times\St\left(\Delta_-\right)\right)$, where the segment $\Delta_+=\left[\frac{3}{2},\frac{1}{2}\right]_{\mathbbm{1}_1}$ and $\Delta_-=\left[-\frac{1}{2},-\frac{3}{2}\right]_{\mathbbm{1}_1}$.
In this subcase we can simply take
\[
    \Pi = |\cdot|^{-\frac{1}{2}}\times\St\left(\Delta_+\right) \quad \textit{or} \quad \Pi= \St\left(\Delta_-\right) \times |\cdot|^{\frac{1}{2}},
\]
depending on the representation $\pi$. Then by Theorem \ref{T:IndSeg}, $\Pi$ satisfies desired properties. Therefore we have an injection
\[
    \Pi\hookrightarrow \Hom_{G_3}\left(\omega_{3,3},\pi\right)_{sm},
\]
and it follows that $\Hom_{G_3}\left(\omega_{3,3},\pi\right)_{sm}$ is not irreducible.

\vskip 5pt

Hence we have verified in all subcases that $\Hom_{G_3}\left(\omega_{3,3},\pi\right)_{sm}$ is not irreducible. In conclusion, Proposition \ref{P:leq3computation} holds.

