\section{Appendix}
\subsection{Metrics for Geometry Optimization}
\label{app: geometry optimization metrics}
\textbf{Average Energy Minimization Percentage.} This metric evaluates the extent to which the energy is reduced by the MLIP-optimized structure when compared to the DFT-optimized geometry:
\begin{align}
    \overline{\mathrm{pct}}_T = \frac{1}{|\mathcal{D}_{\text{opt}}|} \sum_{c \in \mathcal{D}_{\text{opt}}} \mathrm{pct}(c_T),
\end{align}
where the individual percentage improvement \( \mathrm{pct}(c_T) \) is calculated as:
\begin{align}
    \mathrm{pct}(c_T) = 100\% \cdot \frac{E_{c_0}^{\mathrm{DFT}} - E_{c_T}^{\mathrm{DFT}}}{E_{c_0}^{\mathrm{DFT}} - E_{c_{\mathrm{gt}}}^{\mathrm{DFT}}}.
\end{align}
Here, \( c_0 \), \( c_T \), and \( c_{\mathrm{gt}} \) correspond to the starting conformer, the structure optimized by MLIP, and the ground truth DFT-optimized conformer, respectively. The notation \( E^{\mathrm{DFT}}_{(\cdot)} \) refers to the DFT-calculated energy at a given geometry. When calculating this metric, we only consider optimized conformers with $E_{c_T}^{\mathrm{DFT}}$ lower than $E_{c_0}^{\mathrm{DFT}}$. If $E_{c_T}^{\mathrm{DFT}}$ is lower than $E_{c_{\mathrm{gt}}}^{\mathrm{DFT}}$, we only consider it when the force calculated by DFT is within the threshold, indicating that the model confidently finds a conformer with lower energy than DFT-based relaxation.

\textbf{Chemical Accuracy Success Rate.} This metric quantifies the proportion of MLIP-relaxed geometries that achieve a residual energy below the standard threshold of 1 kcal/mol:
\begin{align}
    \mathrm{pct}_{\text{success}} = \frac{1}{|\mathcal{D}_{\text{opt}}|} \sum_{c \in \mathcal{D}_{\text{opt}}} I\left[ E^{\mathrm{res}}(c_T) < 1 \right],
\end{align}
where the residual energy is defined as:
\begin{align}
    E^{\mathrm{res}}(c_T) = E_{c_T}^{\mathrm{DFT}} - E_{c_{\mathrm{gt}}}^{\mathrm{DFT}}.
\end{align}

\textbf{Divergence Rate.} This metric, denoted as $\mathrm{pct}_{\text{div}}$, captures the fraction of cases where the DFT single-point energy evaluation fails or the energy of the optimized structure exceeds that of the initial geometry.

\textbf{Force Convergence Rate.} This metric determines how often the MLIP-relaxed conformers meet the force convergence criterion, specifically having the maximum atomic force fall below 0.05 eV/\AA:
\begin{align}
    \mathrm{pct}_{\text{FwT}} = \frac{1}{|\mathcal{D}_{\text{opt}}|} \sum_{c \in \mathcal{D}_{\text{opt}}} I\left[ \max(F(c_T)) < 0.05 \right].
\end{align}

