\section{Wave functions in reciprocal space}\label{AppA}


In the case of one-dimensional wave functions in quantum wires formed by effective potentials,
the reciprocal space emission profiles are given the Fourier transform of the real space wave function.
For even states the reciprocal space wave function reads
\begin{align}
    \tilde{\Psi}_+(k) = \frac{\sin((q-k)d)} {q-k} + \frac{\sin((q+k)d)} {q+k} + \nonumber \\
    \cos(qd) \left[ \frac{\exp(ikd)} {\varkappa - ik } + \frac{\exp(-ikd)}  {\varkappa + ik } \right]
\end{align}

For odd states the reciprocal space wave function reads
\begin{align}
    \tilde{\Psi}_-(k) = i\frac{\sin((q+k)d)}{q+k} - i\frac{\sin((q-k)d)}{q-k} +  \nonumber \\
    \sin(qd) \left[ \frac{\exp(-ikd)}{\varkappa + ik } - \frac{\exp(ikd)}{\varkappa - ik } \right]
\end{align}



In the case of radially symmetric wave functions in annular effective potential traps,
the reciprocal space emission profiles are given the 2D Fourier transform of the real space wave function (7) in the main text:
\begin{equation}
    \tilde{\Psi}_l (k,\varphi_k) = {1 \over 2 \pi} \int_0^\infty \rho d\rho \Psi_\rho(\rho) \int_0^{2\pi} e^{il\varphi} e^{-ik\rho\cos(\varphi-\varphi_k)}d\varphi
\end{equation}
Using the Hansen-Bessel formula and the Lommel integral, one can compute:
\begin{align}
    \tilde{\Psi}(k,\varphi) = -e^{il(\varphi_k-{\pi/2})} \left[ I_A(k) + I_B(k) + I_C(k) + I_D(k) \right], \\
    I_A = {A \rho_1 \over k^2 + \varkappa^2} \left[ k J_{l+1}(k\rho_1) I_l(\varkappa\rho_1) + \varkappa I_{l+1}(\varkappa\rho_1)J_l(k\rho_1) \right],\\
    I_B = {B \over k^2 - q^2} \left[ k \rho_2 J_{l+1}(k\rho_2) J_l(q\rho_2) - q \rho_2 J_{l+1}(q\rho_2)J_l(k\rho_2) - \right. \nonumber \\
    \left. - k\rho_1 J_{l+1}(k\rho_1)J_l(q\rho_1) + q\rho_1 J_{l+1}(q\rho_1)J_l(k\rho_1) \right],\\
    I_C = {C \over k^2 - q^2} \left[ k \rho_2 J_{l+1}(k\rho_2) Y_l(q\rho_2) - q \rho_2 Y_{l+1}(q\rho_2)J_l(k\rho_2) - \right. \nonumber \\
    \left. - k\rho_1 J_{l+1}(k\rho_1)Y_l(q\rho_1) + q\rho_1 Y_{l+1}(q\rho_1)J_l(k\rho_1) \right],\\
    I_D = -{D \rho_2 \over k^2 + \varkappa^2} \left[ k J_{l+1}(k\rho_2) K_l(\varkappa\rho_2) + \varkappa K_{l+1}(\varkappa\rho_2)J_l(k\rho_2) \right],
\end{align}



