\begin{document}

\begin{abstract}
In this paper, we shall study  $k$-Galois LCD constacyclic group codes over finite commutative chain rings with identity. In particular, we shall characterize Galois LCD constacyclic codes over finite commutative chain ring with identity in terms of its idempotent generators and the classical involution using the twisted group ring structures and find some good LCD codes. %Finally, we shall construct new good quantaum codes from twisted group rings.
\end{abstract} 
\maketitle


\section{Introduction}

Linear codes with complementary duals (abbreviated LCD) are linear codes whose intersection with their dual is trivial. When they are binary, they play an important role in armoring implementations against side-channel attacks and fault injection attacks. 

Linear complementary dual codes have importance in data storage, communications systems and security too.

These codes have been studied for improving the security of information on sensitive devices against side-channel attacks (SCA) and fault non-invasive attacks, see \cite{CC}, and have found use in data storage and communications systems.

Carlet and Guilley, in \cite{CG}, also investigated the application of binary LCD codes against side-channel attacks (SCA) and fault tolerant injection attacks (FIA). Also, in \cite{TD}, the authors constructed explicity LCD codes and have explicit efficient encoding and decoding algorithms .

In \cite{FZ}, Fan and Zhang, introduced the concept of \textit{k-Galois form}, which is a generalization of Euclidean and Hermitian inner products and Liu, Fan and Liu, in \cite{LFL}, studied $k$-Galois LCD codes. Also, in \cite{ZL}, Liu introduced the {\textit{generalized Galois inner product}} for commutative rings.

%Finally, Liu, Liu and Yu, in \cite{LLY}, constructed some quantum codes from Galois LCD codes.

So, this paper is devoted to classify the $k$-Galois LCD constacyclic codes over finite commutative chain rings in terms of idempotents in twisted group algebras of cyclic groups. %and give an applications to quantum codes.

%From now on, let $R$ be a finite commutative ring with identity. 

Let $R$ be a finite commutative ring with identity, $\CC$ be a linear code over $R^{n}$, that is, $\CC$ is a $R$-submodule of $R^{n}$ and let $\lambda$ be an element of ${\mathcal{U}}(R)$, the group of units of $R$. We say that $\CC$ is a \textit{$\lambda$-constacyclic code} if 

\begin{center}
$(c_{0}, c_{1}, \cdots, c_{n-1}) \in \CC \Longrightarrow (\lambda c_{n-1}, c_{0}, \cdots, c_{n-2}) \in \CC $
\end{center}


\noindent for all $(c_{0}, c_{1}, \cdots, c_{n-1}) \in \CC$.

When $\lambda=1$, we have so called \textit{cyclic codes} and, when $\lambda=-1$, we have \textit{negacyclic codes}. Thus, constacyclic codes are generalization of cyclic and negacyclic codes and they have been studied for many authors (\cite{BR}, \cite{CDLW}, \cite{D}). Also, constacyclic codes can be realized as ideals in polynomial factor ring $\displaystyle\frac{R[x]}{\left\langle x^{n}-\lambda\right\rangle}$. %In this paper, we shall consider $char$ Explicar caracter\'\i stica.


Given $x=(x_{0}, x_{1}, \cdots, x_{n-1})$ and $y=(y_{0}, y_{1}, \cdots, y_{n-1})$ two elements of a linear code  $\CC$, the \textit{Hamming distance} between $x$ and $y$ is the number

\begin{center}
	$d_{H}(x,y)=|\{i: \, x_{i}\neq y_{i}, \,\, 0\leq i\leq n-1\}|$.
\end{center}

\noindent and the \textit{weight} of $x$ is 

\begin{center}
	$w_{H}(x)=d(x,0)=|\{i: \, x_{i}\neq 0, \,\, 0\leq i\leq n-1\}|$.
\end{center}

It is well-known that, for a linear code $\CC$, we have $d_{H}(x,y)=w_{H}(x-y)$, for all $x,y \in \CC$.

%Recently, Ginosar and Moreno, in \cite{GM}, have classified \textit{isometries}, mappings which preserve Hamming distance, between \textit{crossed products}. In this paper, we shall generalize some results obtained by Ginosar and Moreno, in \cite{GM} and by Chen, Fan, Lin, Liu in \cite{CFLL}. 


Let $G$ be a group and $A$ be an abelian group. A map

\begin{center}
$\alpha: G\times G \longrightarrow A$
\end{center}

\noindent is a 2-\textit{cocycle} if , for all $x,\,y$ and $z$ in $G$, we have

\begin{center}
$\alpha(x,y)\alpha(xy,z)=\alpha(y,z)\alpha(x,yz)$.
\end{center}

\noindent and a map $t:G\times G \longrightarrow A$ is a 2-\textit{coboundary} if there is a map $\delta:G \longrightarrow A $ such that

\begin{center}
$t(x,y)=\delta(x)\delta(y)\delta(xy)^{-1}$.
\end{center}

As usual, the set of all 2-cocycles will be denoted by $Z^{2}(G,A)$ and the set of all 2-coboundary will be denoted by $B^{2}(G,A)$. Finally, we say that a 2-cocycle $\alpha$ is \textit{normalized} if $\alpha(x,1)=\alpha(1,x)=\alpha(1,1)=1$, for all $x \in G$. Notice that, since $\alpha$ is a 2-cocycle, we can replace $\alpha$ by $\alpha'$ given by 

\begin{center}
$\alpha'(x,y)=\displaystyle\frac{\alpha(x,y)}{\alpha(1,1)}$
\end{center}

\noindent which is a normalized 2-cocycle.  From now on, we assume that all 2-cocycles are normalized.


Let $R$ be a commutative ring and $G$ be a group. The \textit{twisted group ring $R^{\gamma}G$ of G over} $R$ is the associative $R$-algebra with basis $\overline{G}=\{\overline{g}, \, g\in G\}$, which is a copy of $G$, and the multiplication is defined on the basis as

\begin{center}
$\overline{g}\cdot \overline{h}=\gamma(g,h)\overline{gh}$
\end{center}

\noindent where $\gamma(g,h)$ is an element of ${\mathcal{U}}(R)$, the group of units of $R$.

The mapping $\gamma:G\times G \longrightarrow {\mathcal{U}}(R)$ is called \textit{twisting} and there are many different possibilities for $R^{\gamma}G$ depending on the choice of the twisting. For instance, the group ring $RG$ of $G$ over $R$ is a twisted group ring with $\gamma(g,h)=1$. Furthermore, the associative condition on the multiplication implies that

\begin{center}
$\gamma(g,h)\gamma(gh,k)=\gamma(h,k)\gamma(g,hk)$
\end{center}

\noindent and, for this reason, $\gamma$ is a 2-cocycle. %and we say $\gamma$ is \textit{normalized} if $\gamma(x,1)=\gamma(1,x)=1$, for all $x\in G$. 

When $G=C_{n}=\left\langle g\right\rangle$, a cyclic group of order $n$ and $R$ a commutative, we have the following


 \begin{thrm}\label{lem1}  {\rm{\cite [Theorem 2.3 ]{ARP}}} 
 	Let $C_n = \langle g \rangle$ be a cyclic group of order $n$ and R be a commutative ring. Then, the twisted group ring $R^{\gamma}C_{n}$ is isomorphic to $R^{\gamma_{\lambda}}C_{n}$ where

	\begin{equation*}
 		\gamma_\lambda(g^i, g^j) = \begin{cases}
 			1, \quad i+j<n\\
 			\lambda, \quad i+j \ge n
 		\end{cases}
 	\end{equation*}


 \end{thrm} 


It is possible make a \textit{diagonal} change of basis by replacing each $\overline{g}$ by $\widetilde{g}=\delta(g)\overline{g}$ for some $\delta(g) \in {\mathcal{U}}(R)$ and, with this change of basis, $R^{\gamma}G$ is realized in a second way as a twisted group ring of $G$ over $R$ with twisting

\begin{center}
$\widetilde{\gamma}(g,h)=\delta(g)\delta(h)\delta(gh)^{-1}\gamma(g,h)$.
\end{center}

In this case, we say that $\gamma$ and $\widetilde{\gamma}$ are \textit{cohomologous}.

\begin{lem} \label{1.1} {\rm{\cite [Lemma 2.1]{PA}}}
The following relations hold in $R^{\gamma}G$

\begin{enumerate}
	\item [i.] $1=\gamma(1,1)^{-1}\overline{1}$
	\item [ii.] For all $g \in G$,

\begin{center}
$\overline{g}^{-1}=\gamma(g,g^{-1})^{-1}\gamma(1,1)^{-1}\overline{g^{-1}}=\gamma(g^{-1},g)^{-1}\gamma(1,1)^{-1}\overline{g^{-1}}$
\end{center}

\end{enumerate}

\end{lem}


Let $C_{n}=\left\langle g \mid g^{n}=1\right\rangle$ be a cyclic group of order $n$, $R$ be a finite commutative ring and $R^{\gamma}C_{n}$ the twisted group algebra with 

\begin{center}
		$\gamma_{\lambda}(g^{j},g^{k})= \left\{
		\begin{array}{lll}
			\lambda,    & {\rm{if}} \,\, j+k\geq n\\
			1, &  {\rm{if}} \,\, j+k < n
		\end{array}
		\right.$
\end{center}

\noindent where $\lambda$ is a unity of $R$. Thus, $\overline{g}^{2}=\overline{g}\cdot\overline{g}=\gamma(g,g)\overline{g^{2}}$, so we can make a diagonal change of basis and replace $\overline{g^{k}}$ by $\overline{g}^{k}$, for all $k, \,\, 1\leq k\leq n$. Thus, there exists a unity $a \in R$  such that $\overline{g}^{n}=a\cdot 1$ which implies that $R^{\gamma}C_{n}$ is a commutative ring.

In \cite{SA}, Assuena gave an explicit proof that $\lambda$-constacyclic codes can be also realized as ideals in twisted group algebras $R^{\gamma_{\lambda}}C_{n}$ of cyclic group over a finite commutative ring where

\begin{center}
		$\gamma_{\lambda}(g^{j},g^{k})= \left\{
		\begin{array}{lll}
			\lambda,    & {\rm{if}} \,\, j+k\geq n\\
			1, &  {\rm{if}} \,\, j+k < n.
		\end{array}
		\right.$
\end{center}

\noindent for some $\lambda \in {\mathcal{U}}(R)$. Thus, we say that any ideal $\CC$ of a twisted group algebra $R^{\gamma}G$ of a finite group $G$ over a finite ring $R$ is a \textit{twisted group code}.

In this paper, we shall consider twisted group rings $R^{\gamma_{\lambda}}C_{n}$ of commutative local rings $R$ over finite cyclic groups $C_{n}$ such that $char(R/J(R))$ does not divide $n$, where $J(R)$ denotes the Jacobson radical of $R$. 


\section{Some basic results}


In this section, we shall give definitions and some known results which have elementary proofs in twisted group algebras language.

Let $R$ be a finite commutative ring with identity with $p^{n}$ elements, where $p$ is a rational prime, $G$ be a finite group and $R^{\gamma}G$ the twisted group ring of $G$ over $R$. Let $\sigma$ be an automorphism of $R$ with order $m$. Given $\alpha=\displaystyle\sum_{g \in G}\alpha_{g}\overline{g}$, $\beta=\displaystyle\sum_{g \in G}\beta_{g}\overline{g}$ two elements  of $R^{\gamma}G$, for each $k$, $0\leq k< m$, we define the \textit{generalized k-Galois form} on $R^{\gamma}G$ as 

\vr

\begin{center}
$[\alpha,\beta]_{k}=\displaystyle\sum_{g \in G}\alpha_{g}\sigma^{k}(\beta_{g})$.
\end{center}

\vr

It is not difficult to see that generalized $k$-Galois form is just the Euclidean inner product if $k=0$ and it is a sequilinear $k$-form (see \cite{ZL}). Thus, given a twisted group code $\CC$, we can define the \textit{generalized k-Galois dual code of} $\CC$ as

\begin{center}
$\CC^{\perp_{k}}=\{\beta \in R^{\gamma}G \mid [\alpha,\beta]_{k}=0, \, \forall \, \alpha \in \CC \}$.
\end{center}


Given two non-zero elements $\lambda$ and $\beta$ of $\F_{q}$, we say that a linear code $\CC$ is a $\lambda-\beta$-\textit{constacyclic} if $\CC$ is a $\lambda-$constacyclic and a $\beta$-constacyclic. Dinh, in \cite{D1}, proved if $\lambda\neq \beta$, the only $\lambda-\beta$-constacyclic codes are $\{0\}$ and $\F_{q}^{n}$.

We can generalize this result in terms of twisted group algebras. 

\begin{lem} \label{L2} {\rm{\cite [Proposition ]{D1}}}
Let $R$ be a finite commutative ring and let $C_{n}=\left\langle g \mid g^{n}=1\right\rangle$ be a cyclic group of order $n$ and $\lambda, \, \beta$ elements of ${\mathcal{U}}(R)$. Consider the twisted group algebras $R^{\gamma_{\lambda}}C_{n}$ and $R^{\gamma_{\beta}}C_{n}$ where

\vr

\begin{center}
		$\gamma_{\lambda}(g^{j},g^{k})= \left\{
		\begin{array}{lll}
			\lambda,    & {\rm{if}} \,\, j+k\geq n\\
			1, &  {\rm{if}} \,\, j+k < n.
		\end{array}
		\right.$
		$\gamma_{\beta}(g^{j},g^{k})= \left\{
		\begin{array}{lll}
			\beta,    & {\rm{if}} \,\, j+k\geq n\\
			1, &  {\rm{if}} \,\, j+k < n.
		\end{array}
		\right.$
	\end{center}

\vr	

If $\CC$ is a non-zero $\lambda$-constacyclic and also $\beta$-constacyclic code, then $\lambda=\beta$.	
\end{lem}

\begin{proof}
Let $c=\displaystyle\sum_{i=0}^{n-1}c_{i}\overline{g}^{i}$ be a non-zero element of $\CC$. Since, by hypothesis, $\CC$ is $\lambda$-constacyclic and also $\beta$-constacyclic code, we have that

\vr

$\overline{g}\cdot c= c_{0}\overline{g}\cdot\overline{1}+c_{1}\overline{g}\cdot \overline{g}+\cdots+c_{n-1}\overline{g}\cdot\overline{g^{n-1}}$

$\hspace{0.7cm}=c_{0}\cdot \overline{g}+c_{1}\overline{g^{2}}+\cdots+c_{n-1}\lambda\cdot \overline{1}$

$\hspace{0.7cm}=c_{0}\cdot \overline{g}+c_{1}\overline{g^{2}}+\cdots+c_{n-1}\beta\cdot \overline{1}$

so, $\lambda=\beta$ since the set $\{\overline{g}, g \in C_{n}\}$ is a basis of $R^{\gamma_{\lambda}}C_{n}$ and $R^{\gamma_{\beta}}C_{n}$.
\end{proof}


\begin{prop} \label{P1} %{\rm{\cite [Lemma 4.3 ]{FZ}}}
Let $R$ be a finite commutative ring with $p^{m}$ elements, $C_{n}=\left\langle g, \, g^{n}=1\right\rangle$ be a cyclic group of order n and $R^{\gamma_{\lambda}}C_{n}$ the twisted group ring of $C_{n}$ over $R$ where

\begin{center}
		$\gamma_{\lambda}(g^{j},g^{k})= \left\{
		\begin{array}{lll}
			\lambda,    & {\rm{if}} \,\, j+k\geq n\\
			1, &  {\rm{if}} \,\, j+k < n.
		\end{array}
		\right.$
\end{center}		

Then, if $\CC$ is a $\lambda$-constacyclic code, its k-Galois dual $\CC^{\perp_{k}}$ is a $\sigma^{m-k}(\lambda^{-1})$-constacyclic code.
\end{prop}


\begin{proof}
Let $R^{\gamma_{\sigma^{k-m}(\lambda^{-1})}}C_{n}$ be the twisted group algebra with twisting defined by


\begin{center}
		$\gamma_{\sigma^{m-k}(\lambda^{-1})}(g^{j},g^{k})= \left\{
		\begin{array}{lll}
			\sigma^{m-k}(\lambda^{-1}),    & {\rm{if}} \,\, j+k\geq n\\
			1, &  {\rm{if}} \,\, j+k < n.
		\end{array}
		\right.$
\end{center}		


Let $\CC$ be a $\lambda$-constacyclic code and, given any element $c=\displaystyle\sum_{i=0}^{n-1}c_{i}\overline{g}^{i}$ of the code $\CC$ and $x=\displaystyle\sum_{i=0}^{n-1}x_{i}\overline{g}^{i}$ an element of $\CC^{\perp_{k}}$ , we have
\vr

$[c,\overline{g}x]_{k}=c_{0}\sigma^{k}(x_{n-1}\sigma^{m-k}(\lambda^{-1}))+c_{1}\sigma^{k}(x_{0})+c_{2}\sigma^{k}(x_{1})+\cdots +c_{n-1}\sigma^{k}(x_{n-2})$

$\hspace{1.15cm}=c_{0}\lambda^{-1}\sigma^{k}(x_{n-1})+c_{1}\sigma^{k}(x_{0})+c_{2}\sigma^{k}(x_{1})+\cdots +c_{n-1}\sigma^{k}(x_{n-2})$

%$\hspace{1.15cm}=c_{1}x_{0}^{p^{k}}+c_{2}x_{1}^{p^{k}}+\cdots+\lambda^{-1}c_{0}x_{n-1}^{p^{k}}$

$\hspace{1.15cm}=[\overline{g}^{-1}c,x]_{k}=0$.

\vr

Then, $\overline{g}x \in \CC^{\perp_{k}}$ and the proof is completed.
\end{proof}

\begin{definition}
Let $\CC$ be a twisted group code over a finite commutative ring R. We say that $\CC$ is a linear complementary k-Galois dual code (k-Galois LCD code for shorty) if $\CC \cap \CC^{\perp_{k}}=\{0\}$.
\end{definition}

By Lemma \ref{L2} and Proposition \ref{P1}, we get

\begin{cor} {\rm{\cite [Corollary 3.3]{LFL}}} \label{OT}
If $\sigma^{m-k}(\lambda^{-1})\neq \lambda$, then any $\lambda$-constacyclic code $\CC$ over R is a k-Galois LCD code.
\end{cor}

Now, let $R$ be a finite commutative ring. We say $R$ is a {\textit{chain ring}} if the set of all ideals of $R$ is a chain under set-theoretic inclusion. Futhermore, the following conditions are equivalent

(i) $R$ is a local ring and the maximal ideal $M$ of $R$ is principal,

(ii) $R$ is a local principal ideal ring,

(iii) $R$ is a chain ring.

Finally, if $R$ is a finite commutative chain ring, we have that for any $k$-Galois LCD twisted group code, $|\CC|\cdot |\CC^{\perp_{k}}|=|R|^{n}$ and $\CC$ is free with $\CC \oplus \CC^{\perp_{k}}=R^{\gamma}G$ which implies $rank_{R}(\CC) + rank_{R}(\CC^{\perp_{k}})=|G|=n$. See, for example, \cite{BBBFM} Theorem 2.


%\section{The classical involution}

Let $R$ be a commutative ring with identity and let $G$ be a group. Consider the following mapping $^{\ast} : R^{\gamma}G \longrightarrow R^{\gamma}G $ given by $\left(\displaystyle\sum_{g \in G} \alpha_{g}\overline{g}\right)^{\ast}=\displaystyle\sum_{g \in G} \alpha_{g}\overline{g}^{-1}$. 


\begin{definition}
Let R be a commutative ring with identity and let G be a group. The mapping $^{\ast} : R^{\gamma}G \longrightarrow R^{\gamma}G $ given by $\left(\displaystyle\sum_{g \in G} \alpha_{g}\overline{g}\right)^{\ast}=\displaystyle\sum_{g \in G} \alpha_{g}\overline{g}^{-1}$ with $\gamma(g,h)^{2}=1$, is called the classical involution of $R^{\gamma}G$.
\end{definition}


\begin{lem} \label{L1}
Let $R$ be a finite commutative chain ring with characteristc $p$, $C_{n}=\left\langle g, \, g^{n}=1\right\rangle$ be a cyclic group of order n and $R^{\gamma_{\lambda}}C_{n}$ the twisted group algebra of $C_{n}$ over $R$ where

\begin{center}
		$\gamma_{\lambda}(g^{j},g^{k})= \left\{
		\begin{array}{lll}
			\lambda,    & {\rm{if}} \,\, j+k\geq n\\
			1, &  {\rm{if}} \,\, j+k < n.
		\end{array}
		\right.$
\end{center}		

Given two arbitrary elements $\alpha=\displaystyle\sum_{i=0}^{n-1}\alpha_{i}\overline{g}^{i}$ and $\beta=\displaystyle\sum_{i=0}^{n-1}\beta_{i}\overline{g}^{i}$ of $R^{\gamma_{\lambda}}C_{n}$, let us denote by $\sigma^{k}(\beta)$ the element $\displaystyle\sum_{i=0}^{n-1}\sigma^{k}(\beta_{i})\overline{g}^{i}$. If $\alpha\left(\sigma^{k}(\beta)\right)^{\ast}=0$ and $\lambda^{2}=1$, then $[\alpha,\beta]_{k}=0$.
\end{lem}

\begin{proof}
It is not difficult to see, the coefficient of $1=\overline{1}$ in the product $\alpha\left(\sigma^{k}(\beta)\right)^{\ast}$ is exactly $[\alpha,\beta]_{k}$. Since, by hypothesis, $\alpha\left(\sigma^{k}(\beta)\right)^{\ast}=0$, we have $[\alpha,\beta]_{k}=0$. 
\end{proof}


\section{Euclidean Constacyclic LCD codes.}


In this section, we shall characterize constacyclic LCD codes in terms of its idempotent generator with respect to Euclidean inner product.

Let $R$ be a finite commutative chain ring with $p^{m}$ elements, $C_{n}=\left\langle g, \, g^{n}=1\right\rangle$ be a cyclic group of order $n$ and $R^{\gamma_{\lambda}}C_{n}$ the twisted group algebra of $C_{n}$ over $R$ where

\begin{center}
		$\gamma_{\lambda}(g^{j},g^{k})= \left\{
		\begin{array}{lll}
			\lambda,    & {\rm{if}} \,\, j+k\geq n\\
			1, &  {\rm{if}} \,\, j+k < n.
		\end{array}
		\right.$
\end{center}		

\noindent for some unit of R. Given $\alpha=\displaystyle\sum_{g \in C_{n}}\alpha_{g}\overline{g}$, $\beta=\displaystyle\sum_{g \in C_{n}}\beta_{g}\overline{g}$ two elements  of $R^{\gamma_{\lambda}}C_{n}$, we define the \textit{Euclidean inner product} on $R^{\gamma_{\lambda}}C_{n}$ as 

\vr

\begin{center}
$[\alpha,\beta]=\displaystyle\sum_{g \in G}\alpha_{g}\beta_{g}$.
\end{center}

Let $\CC$ be a constacyclic code over $R^{\gamma}C_{n}$, that is, an ideal of $R^{\gamma_{\lambda}}C_{n}$ . It is well-known that the set $\CC^{\perp}=\{x \in R^{\gamma}C_{n} \mid [x,\alpha]=0, \forall \alpha \in \CC\}$ is an ideal in the twisted group algebra $R^{\gamma_{\lambda^{-1}}}C_{n}$ where


\begin{center}
		$\gamma_{\lambda^{-1}}(g^{j},g^{k})= \left\{
		\begin{array}{lll}
			\lambda^{-1},    & {\rm{if}} \,\, j+k\geq n\\
			1, &  {\rm{if}} \,\, j+k < n.
		\end{array}
		\right.$
\end{center}		

\begin{definition}
Let $\CC$ be a constacyclic code over a finite commutative ring $R$. We say that $\CC$ is a linear complementary dual code (LCD code for shorty) if $\CC \cap \CC^{\perp}=\{0\}$.
\end{definition}

Notice that, if $\lambda^{2}\neq 1$, the Corollary \ref{OT} shows us any $\lambda$-constacyclic code is a LCD code. 

\begin{prop} \label{LCDE}
Let $R$ be a finite commutative chain ring with $p^{m}$ elements, with p rational prime, $C_{n}=\left\langle g, \, g^{n}=1\right\rangle$ be a cyclic group of order n and $R^{\gamma_{\lambda}}C_{n}$ the twisted group algebra of $C_{n}$ over $R$ where

\begin{center}
		$\gamma_{\lambda}(g^{j},g^{k})= \left\{
		\begin{array}{lll}
			\lambda,    & {\rm{if}} \,\, j+k\geq n\\
			1, &  {\rm{if}} \,\, j+k < n.
		\end{array}
		\right.$
\end{center}		

\noindent for some unit of R. If $\lambda^{2}=1$, then $\CC$ is a $\lambda$-constacyclic LCD code if, and only if, $\CC$ is generated by an idempontent e such that $e=e^{\ast}$.
\end{prop}

\begin{proof}
First of all, if $\CC$ is a $\lambda$-constacyclic code which is also LCD, we have the following decomposition of ideals $R^{\gamma_{\lambda}}C_{n}=\CC \oplus \CC^{\perp}$ since $\lambda^{2}=1$. So , it is well-know, there exist idempotents $e$ and $f$ such that $1=e+f$, $e\cdot f=0$, $\CC=\left\langle e\right\rangle$ and $\CC^{\perp}=\left\langle f\right\rangle$. 

Since $[e,1-e]=0$, we have that $[1,e^{\ast}(1-e)]=0$. Now, given $a=\displaystyle\sum_{i=0}^{n-1}a_{i}\overline{g}^{i}$ and $b=\displaystyle\sum_{i=0}^{n-1}b_{i}\overline{g}^{i}$ two arbitrary elements of $R^{\gamma_{\lambda}}C_{n}$, then

\begin{center}
$[\overline{g}a,\overline{g}b]=a_{0}b_{0}+a_{1}b_{1}+\cdots+a_{n-2}b_{n-2}+(a_{n-1}\lambda)(b_{n-1}\lambda)=[a,b]$
\end{center} 

So $[\overline{g},\overline{g}e^{\ast}(1-e)]=0$, for all $g \in G$. Since the Euclidean inner product is non-degenerated, we get that $e^{\ast}(1-e)=0$ and $e^{\ast}=e^{\ast}e$, which implies that $e=(e^{\ast})^{\ast}=(e^{\ast}e)^{\ast}=e^{\ast}e=e^{\ast}$. %  $e^{\ast}=(ee^{\ast})^{\ast}=ee^{\ast}=e$.

On the other hand, if $e$ is an idempotent such that $e=e^{\ast}$ and $\CC=\left\langle e\right\rangle$, then, $e(1-e)^{\ast}=e(1-e^{\ast})=e(1-e)=0$ and, by Lemma \ref{L1}, $[e,1-e]=0$. Writing $1=e+(1-e)$ we have $R^{\gamma_{\lambda}}C_{n}=\CC \oplus R^{\gamma_{\lambda}}C_{n}(1-e)$. Since $[e,1-e]=0$ and  $rank_{R}(\CC) + rank_{R}(R^{\gamma_{\lambda}}C_{n}(1-e))=n$, we conclude that $\CC^{\perp}=R^{\gamma_{\lambda}}C_{n}(1-e)$.

Thus, $\CC$ is a $\lambda$-constacyclic LCD code. 
\end{proof}

Thus, we obtain, as a corollary, the Theorem 3.1 in \cite{CW}.

\begin{cor} \label{C1} %{\rm{\cite [Theorem 3.1 ]{CW}}}
Let $R$ be a finite commutative chain ring with $p^{m}$ elements, $C_{n}=\left\langle g, \, g^{n}=1\right\rangle$ be a cyclic group of order n. A cyclic code $\CC$ is a LCD code with respect to Euclidean inner product, if, and only if,  $\CC=\left\langle e \right\rangle$ such that $e^{2}=e$ and $e=e^{\ast}$.
\end{cor}



\section{Hermitian LCD constacyclic codes over $\Z_{p^{2m}}$}

In this section, we shall characterize constacyclic LCD codes over the finite chain ring $\Z_{p^{2m}}$  in terms of its idempotent generator with respect to Hermitian inner product. In this case, the automorphism group of $\Z_{p^{2m}}$ is generated by the Frobenius automorphism.

Let $R=\Z_{p^{2m}}$ be a finite commutative chain ring with $p^{2m}$ elements, $C_{n}=\left\langle g, \, g^{n}=1\right\rangle$ be a cyclic group of order $n$ and $R^{\gamma_{\lambda}}C_{n}$ the twisted group algebra of $C_{n}$ over $R$ where

\begin{center}
		$\gamma_{\lambda}(g^{j},g^{k})= \left\{
		\begin{array}{lll}
			\lambda,    & {\rm{if}} \,\, j+k\geq n\\
			1, &  {\rm{if}} \,\, j+k < n.
		\end{array}
		\right.$
\end{center}		

\noindent for some unit of R. Given $\alpha=\displaystyle\sum_{g \in C_{n}}\alpha_{g}\overline{g}$, $\beta=\displaystyle\sum_{g \in C_{n}}\beta_{g}\overline{g}$ two elements  of $R^{\gamma_{\lambda}}C_{n}$, we define the \textit{Hermitian inner product} on $R^{\gamma_{\lambda}}C_{n}$ by 

\vr

\begin{center}
$[\alpha,\beta]_{m}=\displaystyle\sum_{g \in G}\alpha_{g}\beta^{p^{m}}_{g}$.
\end{center}

Let $\CC$ be a constacyclic code over $R^{\gamma}C_{n}$, that is, an ideal of $R^{\gamma_{\lambda}}C_{n}$ . It is well-known that the set $\CC^{\perp}=\{x \in R^{\gamma}C_{n} \mid [x,\alpha]_{m}=0, \forall \alpha \in \CC\}$ is an ideal in the twisted group algebra $R^{\gamma_{\lambda^{-p^{m}}}}C_{n}$ where


\begin{center}
		$\gamma_{\lambda^{-p^{m}}}(g^{j},g^{k})= \left\{
		\begin{array}{lll}
			\lambda^{-p^{m}},    & {\rm{if}} \,\, j+k\geq n\\
			1, &  {\rm{if}} \,\, j+k < n.
		\end{array}
		\right.$
\end{center}		

\begin{definition}
Let $\CC$ be a constacyclic code over a finite commutative ring $R$. We say that $\CC$ is a linear complementary dual code (LCD code for shorty) if $\CC \cap \CC^{\perp_{m}}=\{0\}$.
\end{definition}

Notice that, if $\lambda^{p^{m}+1}\neq 1$, the Corollary \ref{OT} shows us any $\lambda$-constacyclic code is a LCD code. Also, if we take $\lambda$ with $\lambda^{2}=1$, $p$ has to be an odd prime. If $p=2$, both conditions $\lambda^{2}=1$ and $\lambda^{p^{m}+1}=1$ imply $\lambda=1$. So, in this case the 2-cocycle is trivial then $R^{\gamma_{\lambda}}C_{n}$ is the ordinary group algebra.

\begin{thrm} \label{T1} 
Let $R$ be a finite commutative chain ring with $p^{2m}$, $C_{n}=\left\langle g, \, g^{n}=1\right\rangle$ be a cyclic group of order n and $R^{\gamma_{\lambda}}C_{n}$ the twisted group algebra of $C_{n}$ over $R$ where

\begin{center}
		$\gamma_{\lambda}(g^{j},g^{k})= \left\{
		\begin{array}{lll}
			\lambda,    & {\rm{if}} \,\, j+k\geq n\\
			1, &  {\rm{if}} \,\, j+k < n.
		\end{array}
		\right.$
\end{center}		

Let e be an idempotent of $R^{\gamma_{\lambda}}C_{n}$ and $\lambda^{2}=1$. Then $e=e(e^{(p^{m})})^{\ast}$ if, and only if $[e,1-e]_{m}=0$. %Furthermore, if $\lambda^{p^{k}}=\lambda^{-1}$, then $[e,1-e]_{k}=0$ implies that $e=e(e^{(p^{k})})^{\ast}$.
\end{thrm}


\begin{proof}
Suppose that $e$ is an idempotent such that $e=e(e^{(p^{m})})^{\ast}$. Then,\\ $0=e-e(e^{(p^{m})})^{\ast}=e(1-(e^{(p^{m})})^{\ast})=e\left((1-e)^{(p^{m})}\right)^{\ast}$ and, by Lemma \ref{L1}, \\ $[e,1-e]_{m}=0$.

On the other hand, if $[e,1-e]_{m}=0$, we have that $[1,e^{\ast}(1-e)^{(p^{m})}]=0$. Now, given $a=\displaystyle\sum_{i=0}^{n-1}a_{i}\overline{g}^{i}$ and $b=\displaystyle\sum_{i=0}^{n-1}b_{i}\overline{g}^{i}$ two arbitrary elements of $R^{\gamma_{\lambda}}C_{n}$, since $\lambda^{p^{m}}=\lambda^{-1}$, then 

\vr

$[\overline{g}a,\overline{g}b]_{m}=a_{0}b_{0}^{p^{m}}+a_{1}b_{1}^{p^{m}}+\cdots+a_{n-2}b_{n-2}^{p^{m}}+(a_{n-1}\lambda)(b_{n-1}^{p^{m}}\lambda^{p^{m}})=[a,b]_{}$

\vr

So $[\overline{g},\overline{g}e^{\ast}(1-e)^{(p^{m})}]=0$, for all $g \in G$. Since the Hermitian form is non-degenerated, we get that $e^{\ast}(1-e)^{(p^{m})}=0$ so $e^{\ast}=e^{\ast}e^{(p^{m})}$. Then, $e=(e^{\ast})^{\ast}=(e^{\ast}e^{(p^{m})})^{\ast}=e(e^{(p^{m})})^{\ast}$. 
\end{proof}


Now, we have the following


\begin{prop} \label{LCDH}
Let $R$ be a finite commutative chain ring with identity and $p^{2m}$, with p a rational prime, $C_{n}=\left\langle g, \, g^{n}=1\right\rangle$ be a cyclic group of order n and $R^{\gamma_{\lambda}}C_{n}$ the twisted group algebra of $C_{n}$ over $R$ where

\begin{center}
		$\gamma_{\lambda}(g^{j},g^{k})= \left\{
		\begin{array}{lll}
			\lambda,    & {\rm{if}} \,\, j+k\geq n\\
			1, &  {\rm{if}} \,\, j+k < n.
		\end{array}
		\right.$
\end{center}		

If $\lambda^{2}=1$, then $\CC$ is a $\lambda$-constacyclic code  generated by an idempontent e such that $e=e(e^{(p^{m})})^{\ast}$ if, and only if $\CC$ is Hermitian LCD code.
\end{prop}

\begin{proof}
First of all, if $\CC$ is a $\lambda$-constacyclic code which is also $k$-Galois LCD, we have the following decomposition of ideals $R^{\gamma}C_{n}=\CC \oplus \CC^{\perp_{k}}$ since $\lambda^{1+p^{m}}=1$.

It is well-know that there exist idempotents $e$ and $f$ such that $1=e+f$, $e\cdot f=0$, $\CC=\left\langle e\right\rangle$ and $\CC^{\perp_{m}}=\left\langle f\right\rangle$. Then, writing $f=1-e$, we get $[e,1-e]_{m}=0$, so, by Theorem \ref{T1}, the equality $e=e(e^{(p^{m})})^{\ast}$ holds. 

If $\CC$ is generated by an idempontent $e$ such that $e=e(e^{(p^{m})})^{\ast}$, by Theorem \ref{T1}, we have $[e,1-e]_{m}=0$. Then, writing $1=e+(1-e)$ we have $R^{\gamma}C_{n}=\CC \oplus R^{\gamma}C_{n}(1-e)$. Since $[e,1-e]_{m}=0$ and  $rank_{R}(\CC) + rank_{R}(R^{\gamma}C_{n}(1-e))=n$, we conclude that $\CC^{\perp_{m}}=R^{\gamma}C_{n}(1-e)$. Thus, $\CC$ is a $\lambda$-constacyclic Hermitian LCD code. 
\end{proof}

\begin{prop}
Let $R$ be a finite commutative chain ring with identity and $p^{2m}$ elements, with p a rational prime, $C_{n}=\left\langle g, \, g^{n}=1\right\rangle$ be a cyclic group of order n and $R^{\gamma_{\lambda}}C_{n}$ the twisted group algebra of $C_{n}$ over $R$ where

\begin{center}
		$\gamma_{\lambda}(g^{j},g^{k})= \left\{
		\begin{array}{lll}
			\lambda,    & {\rm{if}} \,\, j+k\geq n\\
			1, &  {\rm{if}} \,\, j+k < n.
		\end{array}
		\right.$
\end{center}		

Suppose that $\lambda^{2}=1$ and  $\CC$ is a $\lambda$-constacyclic code  generated by an idempontent e. Then, $C \subset C^{\perp_{m}}$ if, and only if, $e(e^{(p^{m})})^{\ast}=0$.
\end{prop}


\begin{proof}
Let $\CC$ be $\lambda$-constacyclic code such that $\lambda^{2}=1$ and $\CC=\left\langle e \right\rangle$ with $e^{2}=e$. If $C \subset C^{\perp_{m}}$, then $0=[e,e]_{m}=[1,e^{\ast}(e^{(p^{m})})]_{m}$. Thus, $[\overline{g},\overline{g}e^{\ast}(e^{(p^{m})})]_{m}=0$, for all $g \in C_{n}$. It implies $e^{\ast}(e^{(p^{m})})=0$ and $e(e^{(p^{m})})^{\ast}=(e^{\ast}(e^{(p^{m})}))^{\ast}=0$.

On the other hand, if $e(e^{(p^{m})})^{\ast}=0$, then $[\overline{g}e, \overline{h}e]_{m}=[\overline{g},\overline{h}e^{\ast}(e^{(p^{m})})]_{m}=0$, for all $\overline{g}$, $\overline{h} \in C_{n}$. So, $[\alpha,\beta]_{m}=0$, for all $\alpha$ and $\beta \in \CC$ and the proof is completed.
\end{proof}

