\section{k-Galois constacyclic LCD codes}

In this section, we shall prove some results about $k$-Galois constacyclic LCD codes over a commutative chain ring $R$ with characteristic $p$. Let $\sigma$ be an automorphism of $R$ of order $m$.

\begin{thrm} \label{T1}
Let $R$ be a finite commutative chain ring with characteristic p, $C_{n}=\left\langle g, \, g^{n}=1\right\rangle$ be a cyclic group of order n and $R^{\gamma_{\lambda}}C_{n}$ the twisted group algebra of $C_{n}$ over $R$ where

\begin{center}
		$\gamma_{\lambda}(g^{j},g^{k})= \left\{
		\begin{array}{lll}
			\lambda,    & {\rm{if}} \,\, j+k\geq n\\
			1, &  {\rm{if}} \,\, j+k < n.
		\end{array}
		\right.$
\end{center}		

Let e be an idempotent of $R^{\gamma_{\lambda}}C_{n}$ and $\lambda^{2}=1$. Then $e=e(\sigma^{k}(e))^{\ast}$ if, and only if $[e,1-e]_{k}=0$. %Furthermore, if $\lambda^{p^{k}}=\lambda^{-1}$, then $[e,1-e]_{k}=0$ implies that $e=e(e^{(p^{k})})^{\ast}$.
\end{thrm}


\begin{proof}
Suppose that $e$ is an idempotent such that $e=e(\sigma^{k}(e))^{\ast}$. Then,

$0=e-e(\sigma^{k}(e))^{\ast}=e(1-(\sigma^{k}(e))^{\ast})=e\left(\sigma^{k}((1-e)\right)^{\ast}$ and, by Lemma \ref{L1}, $[e,1-e]_{k}=0$.

On the other hand, if $[e,1-e]_{k}=0$, we have that $[1,e^{\ast}\sigma^{k}(1-e)]=0$. Now, given $a=\displaystyle\sum_{i=0}^{n-1}a_{i}\overline{g}^{i}$ and $b=\displaystyle\sum_{i=0}^{n-1}b_{i}\overline{g}^{i}$ two arbitrary elements of $R^{\gamma_{\lambda}}C_{n}$, since $\sigma^{m-k}(\lambda)=\lambda$, then 

$[\overline{g}a,\overline{g}b]_{k}=a_{0}\sigma^{k}(b_{0})+a_{1}\sigma^{k}(b_{1})+\cdots+a_{n-2}\sigma^{k}(b_{n-2})+(a_{n-1}\lambda)(\sigma^{k}(b_{n-1}\lambda))$

\hspace{1.15cm} $=[a,b]_{k}$

So $[\overline{g},\overline{g}e^{\ast}\sigma^{k}(1-e)]=0$, for all $g \in G$. Since the $k$-Galois form is non-degenerated, we get that $e^{\ast}\sigma^{k}(1-e)=0$ so $e^{\ast}=e^{\ast}\sigma^{k}(e)$. Then, $e=(e^{\ast})^{\ast}=(e^{\ast}\sigma^{k}(e))^{\ast}=e(\sigma^{k}(e))^{\ast}$. 
\end{proof}


Notice that, if $\sigma^{m-k}(\lambda^{-1})\neq \lambda$, the Corollary \ref{OT} shows us any $\lambda$-constacyclic code is a LCD code. Also, if $\lambda^{2}=1$ and $\sigma^{m-k}(\lambda)\neq \lambda$, any $\lambda$-constacyclic code is a LCD code.   

%Notice that, Corollary \ref{OT}, we have $\sigma^{m-k}(\lambda^{-1})=\sigma^{m-k}(\lambda)=\sigma^{k}(\lambda)=\lambda$ since $\lambda^{2}=1$.

Now, for the next result, we shall consider $\lambda^{2}=1$ and $\sigma^{m-k}(\lambda)=\lambda$.% have the following


\begin{prop} \label{GL}
Let $R$ be a finite commutative chain ring with identity and characteristic p, a rational prime, $C_{n}=\left\langle g, \, g^{n}=1\right\rangle$ be a cyclic group of order n and $R^{\gamma_{\lambda}}C_{n}$ the twisted group algebra of $C_{n}$ over $R$ where

\begin{center}
		$\gamma_{\lambda}(g^{j},g^{k})= \left\{
		\begin{array}{lll}
			\lambda,    & {\rm{if}} \,\, j+k\geq n\\
			1, &  {\rm{if}} \,\, j+k < n.
		\end{array}
		\right.$
\end{center}		

If $\lambda^{2}=1$, then $\CC$ is a $\lambda$-constacyclic code  generated by an idempontent e such that $e=e(\sigma^{k}(e))^{\ast}$ if, and only if $\CC$ is k-Galois LCD code.
\end{prop}

\begin{proof}
If $\CC$ is a $\lambda$-constacyclic code which is also $k$-Galois LCD, we have $\sigma^{m-k}(\lambda^{-1})=\sigma^{m-k}(\lambda)=\sigma^{k}(\lambda)=\lambda$ since $\lambda^{2}=1$.

%we have the following decomposition of ideals $R^{\gamma}C_{n}=\CC \oplus \CC^{\perp_{k}}$ since $\sigma^{m-k}(\lambda)=\sigma^{k}(\lambda)=\lambda$.

It is well-know that there exist idempotents $e$ and $f$ such that $1=e+f$, $e\cdot f=0$, $\CC=\left\langle e\right\rangle$ and $\CC^{\perp_{k}}=\left\langle f\right\rangle$. Then, writing $f=1-e$, we get $[e,1-e]_{k}=0$, so, by Theorem \ref{T1}, the equality $e=e(\sigma^{k}(e))^{\ast}$ holds. 

If $\CC$ is generated by an idempontent $e$ such that $e=e(\sigma^{k}(e))^{\ast}$, by Theorem \ref{T1}, we have $[e,1-e]_{k}=0$. Then, writing $1=e+(1-e)$ we have $R^{\gamma}C_{n}=\CC \oplus R^{\gamma}C_{n}(1-e)$. Since $[e,1-e]_{k}=0$ and  $rank_{R}(\CC) + rank_{R}(R^{\gamma}C_{n}(1-e))=n$, we conclude that $\CC^{\perp_{k}}=R^{\gamma}C_{n}(1-e)$. Thus, $\CC$ is a $\lambda$-constacyclic $k$-Galois LCD code. 
\end{proof}

\begin{prop}
Let $R$ be a finite commutative chain ring with identity and characteristic p, an rational prime, $C_{n}=\left\langle g, \, g^{n}=1\right\rangle$ be a cyclic group of order n and $R^{\gamma_{\lambda}}C_{n}$ the twisted group algebra of $C_{n}$ over $R$ where

\begin{center}
		$\gamma_{\lambda}(g^{j},g^{k})= \left\{
		\begin{array}{lll}
			\lambda,    & {\rm{if}} \,\, j+k\geq n\\
			1, &  {\rm{if}} \,\, j+k < n.
		\end{array}
		\right.$
\end{center}		

Suppose that $\lambda^{2}=1$ and  $\CC$ is a $\lambda$-constacyclic code  generated by an idempontent e. Then, $C \subset C^{\perp_{k}}$ if, and only if, $e(\sigma^{k}(e))^{\ast}=0$.
\end{prop}


\begin{proof}
Let $\CC$ be $\lambda$-constacyclic code such that $\lambda^{2}=1$ and $\CC=\left\langle e \right\rangle$ with $e^{2}=e$. If $C \subset C^{\perp_{k}}$, then $0=[e,e]_{k}=[1,e^{\ast}(\sigma^{k}(e))]$. Thus, $[\overline{g},\overline{g}e^{\ast}(\sigma^{k}(e))]=0$, for all $g \in C_{n}$. It implies $e^{\ast}(\sigma^{k}(e))=0$ and $e(\sigma^{k}(e))^{\ast}=(e^{\ast}(\sigma^{k}(e)))^{\ast}=0$.

On the other hand, if $e(\sigma^{k}(e))^{\ast}=0$, then \\ $[e, \sigma^{k}(e)]=0$, so $[\overline{g}e, \overline{h}e]_{k}=[\overline{g},\overline{h}e^{\ast}(\sigma^{k}(e))]=0$ for all $\overline{g}$, $\overline{h} \in C_{n}$. So, $[\alpha,\beta]_{k}=0$, for all $\alpha$ and $\beta \in \CC$ and the proof is completed.
\end{proof}


%then $[\overline{g}e, \overline{h}e]_{k}=[\overline{g},\overline{h}e^{\ast}(\sigma^{k}(e))]_{k}=0$, for all $\overline{g}$, $\overline{h} \in C_{n}$. So, $[\alpha,\beta]_{k}=0$, for all $\alpha$ and $\beta \in \CC$ and the proof is completed.
%\end{proof}


\begin{cor}
Let $\CC$ be $\lambda$-constacyclic code such that $\lambda^{2}=1$ and $\CC=\left\langle e \right\rangle$ with $e^{2}=e$. Then, $C \subset C^{\perp}$ if, and only if, $ee^{\ast}=0$.
\end{cor}


{\textit{Example:}}  Let $R=\F_{4}+u\F_{4}$ be a commutative local ring with $u^{2}=0$, where $\F_{4}=\{0,1,\omega, \omega + 1\}$ is the finite field with 4 elements, $C_{5}$ be the cyclic group of order 5 and $R^{\gamma}C_{5}$ be the twisted group ring where

\vr

\begin{center}
		$\gamma(g^{j},g^{k})= \left\{
		\begin{array}{lll}
			1+\omega \cdot u,    & {\rm{if}} \,\, j+k\geq 5\\
			1, &  {\rm{if}} \,\, j+k < 5.
		\end{array}
		\right.$
\end{center}		

So, in this case, we have $\overline{g}^{5}=1+\omega\cdot u$. Notice that $(1+\omega\cdot u)^{2}=1+\omega^{2}\cdot u^{2}=1$. Taking $\sigma(a+b\cdot u)=a^{2}+b^{2}(\omega + 1)\cdot u$, by \cite{YA} Proposition 1 for commutative case,  the mapping $\sigma$ is an automorphism of $R$ and $\sigma(1+\omega\cdot u)=1+\omega\cdot u$.

Now, consider the element $e=\overline{g}^{4}+ (1+\omega\cdot u)\overline{g}^{3}+ \overline{g}^{2} + (1+\omega\cdot u)\overline{g}+1$, thus

\vr

$e^{2}=\overline{g}^{8}+ (1+\omega\cdot u)^{2}\overline{g}^{6}+ \overline{g}^{4} + (1+\omega\cdot u)^{2}\overline{g}^{2}+1$

\vr

\hspace{0.3cm} $=(1+\omega\cdot u)\overline{g}^{3}+ (1+\omega\cdot u)\overline{g}+\overline{g}^{4}+\overline{g}^{2}+1 =e$ 

\vr

$e^{\ast}=(1+\omega\cdot u)\overline{g}+ \overline{g}^{2}+ (1+\omega\cdot u)\overline{g}^{3} + \overline{g}^{4} + 1=e$

%\hspace{0.3cm} $=(1+\omega\cdot u)\overline{g}^{3}+ (1+\omega\cdot u)\overline{g}+\overline{g}^{4}+\overline{g}^{2}+1$

%\hspace{0.3cm} $=e$ 

\vr

$\sigma(e)=\sigma(1)\overline{g}^{4}+ \sigma(1+\omega\cdot u)\overline{g}^{3}+ \sigma(1)\overline{g}^{2} + \sigma(1+\omega\cdot u)\overline{g}+\sigma(1)=e$

%\hspace{0.65cm} $=e$

\vr

\noindent since $\sigma(1+\omega\cdot u)=1+\omega \cdot u$. By Proposition \ref{GL}, the code $\CC=\left\langle e\right\rangle$ is $k$-Galois LCD code with respect the generalized $k$- Galois form.

Again using SageMath to compute the minimum distance, the code generated by $\vartheta(e)=\overline{g}^{4}+\overline{g}^{3}+ \overline{g}^{2} + \overline{g}+1$ over $\F_{4}$ is a [5,1,5] MDS code, so the code $\CC$ generated by $e$ is also MDS code over $R$. Also, the $k$-Galois dual code $\CC^{\perp_{k}}$ is a [5,4,2] MDS over $R$.  

