\section{New lower bounds for constant dimension codes}\label{Sec-Result}

In this section, we compare our lower
bounds for CDCs derived from Theorems \ref{T-BPM-CDC} and \ref{T-SPar-CDC} with the best-known lower bounds for CDCs in \cite{ParllelMixed}.

\begin{corollary}\label{2-12}
Let $h$ be a positive integer. Then
\begin{align*}
    A_2(12+h,4,\{4\}) &\geq 4801\cdot 2^{12+3h} + 327 \cdot 2^{9+3h} \\& \quad +(1+(2^{(8+h)}-1)\cdot 35)\\& \quad + \sum_{i=0}^2 \sum_{j=0}^{\min\{1,\lfloor \frac{h-1}{2} \rfloor\}}2^{\min\{7-2i,h+1-2j\}+8+h-2i-2j}.
\end{align*} 
\end{corollary}
\begin{proof}
    Let $q=2$, $n=12+h$, $n_1=8$, $n_2=4+h$, $k=4$, $\delta=2$, and $T_1=\{4,3\}$. Obviously, $n_1+k-T_1^{\min} \leq n-k$. Set $\theta_1=2$ and $\theta_2=\min\{1, \lfloor \frac{h-1}{2} \rfloor\}$. Let $\Lambda_1^i =7-2i$, $\Lambda_3^j= 1+h-2j$, $\Gamma^i=2$, and $d_1^{(i,j)}=d_2^{(i,j)}=1$ for $0 \leq i \leq \theta_1$ and $0 \leq j \leq  \theta_2$. If we take the $(8,4,3,\{4,3\})_2$ MDDC from Example \ref{E-Alg}, then by Theorem \ref{T-SPar-CDC}, the conclusion follows.
\end{proof}

\begin{corollary}\label{2-18}
    Let $h$ be an integer with $h \geq 0$. Then
    \begin{align*}
        A_2(18+h, 4, \{4\}) &\geq 4801 \cdot 2^{30+3h}+327 \cdot 2^{27+3h} \\&\quad +4801 \cdot (1+35(2^{10+h}-1) ) +327\cdot(1+35(2^{9+h}-1))\\&\quad +  \sum_{i=0}^2 \sum_{j=0}^{\min\{3,\lfloor \frac{5+h}{2} \rfloor \}}  2^{\min\{7-2i, 7-2j+h\}+14+h-2i-2j}.
    \end{align*}
\end{corollary}
\begin{proof}
    Let $q=2$, $n=18+h$, $n_1=8$, $n_2=10+h$, $n_3=8$, $k=4$, $\delta=2$, $T_1=\{4,3\}$, and $T_2=\{4,3\}$. It is easy to verify that  $n_1+k-T_1^{\min} \leq n-n_3+T_2^{\min}-k$.  Set $\mu_1=9$, $\mu_2=9$, $\mu_3=h$, $\omega_1=\omega_2=2$, $\theta_1=2$, and $\theta_2=\min\{3,\lfloor \frac{5+h}{2} \rfloor\}$. Let $\Lambda_1^i=7-2i$, $\Lambda_3^j=7-2j+h$, $\Gamma_1^i=\Gamma_3^j=2$, and $d_1^{(i,j)}=d_2^{(i,j)}=1$ for $0 \leq i \leq \theta_1$, $0 \leq j \leq  \theta_2$. If we take the $(8,4,3,\{4,3\})_2$ MDDC from Example \ref{E-Alg}, then by Theorem \ref{T-BPM-CDC}, the conclusion follows.
\end{proof}

The following theorem gives a lower bound for the size of $(n,2\delta,\delta+1)_q$ MDDCs, which is useful for our constructions of CDCs.
\begin{theorem}[\cite{MixDD}]\label{Constr-MDDC}
    Let $n$, $k$, and $\delta$ be integers with $\delta \geq 2$ and $n > k \geq 2\delta-1$. Let $\cC_0$ be an $(n, |\cC_0|, 2\delta, \{k\})_q$ CDC, and \[ N= \left\lfloor 
     \frac{[\begin{smallmatrix}
         n\\ k-\delta+1
     \end{smallmatrix}]_q - |\cC_0|[\begin{smallmatrix}
         k\\\delta-1
         \end{smallmatrix}]_q}{\sum_{i=0}^{\delta-1}q^{i^2}[\begin{smallmatrix}
             k-\delta+1\\i
         \end{smallmatrix}]_q [\begin{smallmatrix}
             n-(k-\delta+1)\\ i
         \end{smallmatrix}]_q} \right\rfloor.\]
         Then there exists an $(n, 2\delta, \delta+1)_q$ MDDC $\cC$ with $\eta_k(\cC) = |\cC_0|$ and $\eta_{k-\delta+1}(\cC)= \max\{N,0\}$.
\end{theorem}
In the following corollaries, 
we denote \[N_q(x,y,z)= \left\lfloor 
    \frac{[\begin{smallmatrix}
         x\\ z-y+1
     \end{smallmatrix}]_q - S_q(x,2y,z)[\begin{smallmatrix}
         z\\ y-1
         \end{smallmatrix}]_q}{\sum_{i=0}^{y-1}q^{i^2}[\begin{smallmatrix}
             z-y+1\\ i
         \end{smallmatrix}]_q [\begin{smallmatrix}
             x-(z-y+1)\\ i
         \end{smallmatrix}]_q} \right\rfloor,\]
where $S_q(x,2y,z)$ represents the best-known size of the $(x,2y, \{z\})_q$ CDC.

With the help of Theorem \ref{Constr-MDDC}, we can obtain general results of Corollaries \ref{2-12} and \ref{2-18}.

\begin{corollary}\label{q-18}
    Let $h$ be an integer with $h \geq 0$. Then
    \begin{align*}
        A_q(18+h,4,\{4\}) 
  &\geq A_q(8,4,\{4\}) \cdot q^{30+3h}+N_q(8,2,4) \cdot q^{27+3h} \\& \quad + A_q(8,4,\{4\}) \cdot (1+(q^{10+h}-1)(q^2+1) (q^2+q+1))\\& \quad +N_q(8,2,4)\cdot(1+(q^{9+h}-1)(q^2+1)(q^2+q+1))\\& \quad+  \sum_{i=0}^2 \sum_{j=0}^{ \min\{3,\lfloor\frac{5+h}{2} \rfloor \}} q^{\min\{7-2i, 7-2j+h\}+14+h-2i-2j}.
    \end{align*}
\end{corollary}
\begin{proof}
The proof of the Corollary \ref{q-18} is similar to the proof of Corollary \ref{2-18}. Construct the $(8,4,3,\{4,3\})_q$ MDDC from Theorem \ref{Constr-MDDC}, and then the conclusion follows by Theorem \ref{T-BPM-CDC}.
\end{proof}


\begin{corollary}\label{q-12}
Let $\delta \geq 2$ and $h \geq \delta-1$ be two integers. \\
Set $d^{(i,j)}_1 =\begin{cases}
    \lceil \frac{\delta}{2} 
    \rceil & ~\text{if}~j-i \geq \frac{h+2}{\delta}-4;\\
    \lfloor \frac{\delta}{2} 
    \rfloor &~\text{otherwise},
\end{cases}$ and  $d^{(i,j)}_2=\delta-d^{(i,j)}_1$ for $0 \leq i \leq 2$ and $0 \leq j \leq  \min\{1,\lfloor \frac{h+1}{\delta} 
\rfloor -1\}$. If $N_q(4\delta,\delta,2\delta) > 0$, then 
\begin{align*} A_q(6\delta+h,2\delta,\{2\delta\}) &\geq A_q(4\delta,2\delta,\{2\delta\})\cdot q^{(2\delta+h)(\delta+1)}\\&\quad+N_q(4\delta,\delta,2\delta)\cdot q^{\max\{\delta+h+1,2\delta\}(\min\{\delta+h+1,2\delta\}-\delta+1)} \\&\quad +(1+\left[\begin{smallmatrix}
    2\delta\\ \delta
\end{smallmatrix}\right]_q \cdot (q^{4\delta+h}-1)) \\& \quad +\sum_{i=0}^2 \sum_{j=0}^{\min\{1,\lfloor \frac{h+1}{\delta} \rfloor-1\}} [q^{\min\{((4-i)\delta-1)d_2^{(i,j)},(h+1-j\delta)d_1^{(i,j)}\}} \\&\quad \cdot q^{(4-i)\delta+h-j\delta}].
\end{align*}
\end{corollary}
\begin{proof}
    Set $n=6\delta+h$, $n_1=4\delta$, $n_2=2\delta+h$, $k=2\delta$, $d=2\delta$, and $T_1=\{2\delta,\delta+1\}$. Since $h \geq \delta-1$, it is obvious that $n_1+k-T_1^{\min} \leq n-k$. Set $\theta_1=2$ and $\theta_2=\min\{1,\lfloor \frac{h+1}{\delta} \rfloor -1\}$. Set $\Lambda_1^i=(4-i)\delta-1$, $\Gamma^i=\delta$,  for $0 \leq i \leq \theta_1$, and $\Lambda_3^j=h+1-j\delta$ for $0 \leq j \leq \theta_2$. If we construct the $(4\delta,2\delta,\delta+1, T_1)_q$ MDDC from Theorem \ref{Constr-MDDC}, then the conclusion follows by Theorem 
\ref{T-SPar-CDC}.
\end{proof} 

\begin{example}
    To illustrate the difference between our constructions and the parallel mixed dimension codes in \cite{ParllelMixed}, take $h=2$ and $\delta=2$ in Corollary \ref{q-12}. By the parallel mixed dimension construction, we have
    \begin{align*}
        A_q(14,4,\{4\})\geq A_q(8,4,\{4\}) \cdot q^{18}+N_q(8,2,4) \cdot q^{15}+(1+\left[\begin{smallmatrix}
    4\\ 2
\end{smallmatrix}\right]_q \cdot (q^{10}-1)).
    \end{align*}
    While from our construction, we have 
    \begin{align*}
        A_q(14,4,\{4\})&\geq A_q(8,4,\{4\}) \cdot q^{18}+N_q(8,2,4) \cdot q^{15}+(1+\left[\begin{smallmatrix}
    4\\ 2
\end{smallmatrix}\right]_q \cdot (q^{10}-1))\\&
+q^{13}+q^{11}+q^9.
    \end{align*}
Here, $\left[\begin{smallmatrix}
    4\\ 2
\end{smallmatrix}\right]_q=(q^2+1)(q^2+q+1)$. 
    Therefore, 
    \begin{align*}
       A_q(14,4,\{4\}) &\geq  A_q(8,4,\{4\}) \cdot q^{18}+N_q(8,2,4) \cdot q^{15}+q^{14} + 2q^{13} \\&+ 2q^{12} + 2q^{11} + q^{10} + q^9 - q^4 - q^3 - 2q^2 - q.
    \end{align*}
\end{example}

Corollaries \ref{2-12}, \ref{2-18}, \ref{q-18}, and \ref{q-12}
provide many new CDCs with larger sizes
than those of the previously best-known codes in \cite{ParllelMixed}. We list some of our new lower bounds in Table \ref{NewBound}. Overall at least $49$ new lower bounds are provided. Table \ref{NewBound1} shows some examples of these new lower bounds.


