	\maketitle {\flushleft\bf Abstract:} {\small  A constructive characterization of the class of uniformly $4$-connected graphs is presented. The characterization is based on the application of graph operations to appropriate vertex and edge sets in uniformly $4$-connected graphs, that is, any uniformly $4$-connected graph can be obtained from $C_5^2$ or $C_6^2$ by a number of $\Delta_1^+$ or $\Delta_2^+$-operations to quasi $4$-compatible sets.}

	{\flushleft\bf Keywords}:
	uniformly $4$-connectivity; $\Delta_1^+$-operation; $\Delta_2^+$-operation; quasi 4-compatibility

	\section{Introduction}
	\hspace*{1.3em} In this paper, we only consider finite simple undirected graphs, with graph theoretic terminology used here                                                                                                                                                                                                                                                                                                                                                                                 following \cite{Bondy}.

	The class of $3$-connected graphs has been characterized by Tutte~\cite{Tutte} in his famous Wheel Theorem. A construction characterization of the class of minimally $3$-connected graphs was given by Dawes~\cite{Dawes}. In addition, the class of $4$-connected graphs has been characterized by Qin and Ding~\cite{Qin}. Yin~\cite{Yin} also gave a recursive construction method for $4$-connected graphs. Su et al.~\cite{Su} gave a construction method for $k$-connected graphs.

	A graph is said to be \emph{uniformly $k$-connected} if between any pair of vertices the maximum number of internally-disjoint paths is exactly $k$. The study of uniformly connected graphs originated with Beineke et al.~\cite{Beineke}, who first derived some properties of uniformly connected graphs and defined different operations to yield infinite families of uniformly connected graphs, but they by no means construct all such graphs. Subsequently, G\"{o}ring et al.~\cite{Goring} gave a construction characterization of the class of uniformly $3$-connected graphs, which requires the set of all $3$-connected and $3$-regular graphs as a starting set. Recently, Xu~\cite{Xu} improved the construction method for uniformly $3$-connected graphs, which requires only the graph $K_4$ as the staring set. 


	In this paper, we will give a constructive characterization of the class of uniformly $4$-connected graphs. The Section $2$ of this paper presents several definitions and basic lemmas that will be used in the proof of the main result, which is determined in Section~$3$.



	\section{Preliminaries}

	\hspace*{1.3em} For a graph $G$, let $V(G)$ and $E(G)$ denote the vertex set and the edge set of $G$, respectively. Let $N_G(x)$ denote the \emph{neighborhood} of $x$ in $G$ where $x\in V(G)$, and let $V(e)$ denote the set of \emph{endpoints} of $e$ where $e\in E(G)$. For a $k$-connected graph $G$ and a minimum vertex cut $T$ of $G$, the union of the vertex sets of at least one but not of all components of $G-T$ is called a \emph{$T$-fragment}(or briefly a \emph{fragment}) of $G$. A fragment of $G$ is called an \emph{end} of $G$ if any of its proper subsets is not a fragment of $G$.

	\begin{definition}\label{def1}
		A path $p$ is a \emph{quasi $3$-circuit chording path}, if between the endpoints of a subpath $p^{\prime}$ of $p$, there exist three internally-disjoint paths except for $p^{\prime}$, and the three paths intersect $p$ only at the endpoints of $p^{\prime}$.
		A path is an \emph{$e^{+}$-quasi $3$-circuit chording path}, if it is not a quasi $3$-circuit chording path, but becomes one after adding the edge $e$.
		A \emph{quasi chord} of a cycle is a path $p$ which connects two non-adjacent vertices of the cycle where $p$ intersects the cycle only at the endpoints of $p$.   
	\end{definition}

	\begin{definition}\label{def2}
		Let $H$ be a $4$-connected graph. Let $X=\{a,b,c\}\subset V(H)$ and $Y=\{d,e,f\}\subset V(H)$ such that $\vert X\cap Y\vert \leqslant 2$ and $E(H[X]), E(H[Y])\neq \emptyset$. The \emph{$\Delta_1^{+}$-operation} and \emph{$\Delta_2^{+}$-operation} are defined as follows:


		\noindent \emph{$\Delta_1^{+}$-operation}. $\Delta_1^{+}(H)=(H-E_{X})+x+\{xp|p\in X\cup \{y\}\}$, where $x\notin V(H)$, $y\in V(H)\setminus X$, 

		\noindent\hspace{2.55cm} $E_X \subseteq E(H[X])$ and $E_X \neq \emptyset$ such that $\kappa(H-E_{X})=\kappa(\Delta_1^{+}(H)-x)\geqslant 3$.

		\noindent \emph{$\Delta_2^{+}$-operation}. $\Delta_2^{+}(H)=(H-E_{X}-E_{Y})+x+y+xy+\{xp|p\in X\}+\{yq|q\in Y\}$, where 

		\noindent\hspace{2.55cm} $x,y\notin V(H)$, $E_X \subseteq E(H[X])$, $E_Y \subseteq E(H[Y])$ and $E_X, E_Y \neq \emptyset$ such that

		\noindent\hspace{2.55cm} $\kappa(H-E_{X}-E_{Y})=\kappa(\Delta_2^{+}(H)-x-y)\geqslant 2$, moreover, if $\kappa(H-E_{X}-E_{Y})=$

		\noindent\hspace{2.55cm} $\kappa(\Delta_2^{+}(H)-x-y)= 2$, any end of $H-E_{X}-E_{Y}$ contains both a vertex 

		\noindent\hspace{2.55cm} in $X$ and a vertex in $Y$. 
	\end{definition}

	\begin{definition}\label{def3}
		Let $H$ be a $4$-connected graph. Let $X=\{a,b,c\}\subset V(H), y\in V(H)\setminus X$ and $Y=\{d,e,f\}\subset V(H)$ such that $\vert X\cap Y\vert \leqslant 2$ and $E(H[X]), E(H[Y])\neq \emptyset$. Let $E_X \subseteq E(H[X])$ and $E_Y \subseteq E(H[Y])$ such that $E_X, E_Y \neq \emptyset$. Let $K_X$ denote a triangle defined by the vertices $a,b,c$ and let $K_Y$ denote a triangle defined by the vertices $d,e,f$. Then a set $S$ of vertices and edges of $H$ is \emph{quasi $4$-compatible} if it conforms to one of the following two types:

		\noindent Type $(1)$. $S=\{v,e\vert v\in X\cup \{y\}, e\in E_X\}$, where no $uv$-path is a quasi $3$-circuit chording 

		\noindent\hspace{1.75cm} path of $H-E_X$ for $u\in X, v=y$ or $u, v\in V(e)$ where $u\neq v$ and $e\in E(K_X)\setminus E_X$.

		\noindent Type $(2)$. $S=\{v,e\vert v\in X\cup Y, e\in E_X\cup E_Y\}$, where $S$ conforms to the following two 

		\noindent\hspace{1.75cm} conditions simultaneously:

		\noindent\hspace{1.75cm} (i) No $uv$-path is a quasi $3$-circuit chording path of $H-E_X-E_Y$ for $u\in X-$ 

		\noindent\hspace{2.35cm} $Y, v\in Y-X$ or $u, v\in V(e)$ where $u\neq v$ and $e\in (E(K_X)\setminus E_X)\cup (E(K_Y)\setminus$

		\noindent\hspace{2.35cm} $E_Y)$, moreover, if $\vert X\cap Y\vert =2$, no $uv$-path is a quasi chord of any cycle of 

		\noindent\hspace{2.35cm} $H-E_X-E_Y$ for $u,v\in X\cap Y$ where $u\neq v$.

		\noindent\hspace{1.75cm} (ii) No $uv$-path is an $e^{+}$-quasi $3$-circuit chording path of $H-E_X-E_Y$ for $u$,

		\noindent\hspace{2.45cm} $v\in V(e_1), e\in (E(K_{Y})\setminus E(H[Y]))\cup E_{Y}$ where  $u\neq v$ and $e_{1}\in E(K_{X})\setminus E_X$,

		\noindent\hspace{2.45cm} or $u,v\in V(e_2), e\in (E(K_{X})\setminus E(H[X]))\cup E_{X}$ where $u\neq v$ and $e_{2}\in E(K_{Y})\setminus$ 

		\nopagebreak
		\noindent\hspace{2.45cm} $E_Y$.
	\end{definition}

	Yin~\cite{Yin} defined removable edges in $4$-connected graphs and proved the following results.


	\begin{definition}\label{def4}
		An edge $e$ of a $4$-connected graph $G$ is said to be a \emph{removable edge} if $G\ominus e$ is still $4$-connected, where $G\ominus e$ denotes the graph obtained from $G$ by deleting e to get $G-e$, and for any endpoint of $e$ with degree $3$ in $G-e$, say $x$, deleting $x$ and then adding edges between any pair of non-adjacent vertices in $N_{G-e}(x)$.
	\end{definition}

	\begin{lem}(\cite{Yin})\label{lem1}
		Let $G$ be a $4$-connected graph of order at least $7$  and $e=xy\in E(G)$. Then $e$ is non-removable if and only if there exists $S\subseteq V(G)$ with $\vert S\vert=3$ such that $G-e-S$ has exactly two components $A, B$ with $\vert A\vert \geqslant 2$ and $\vert B\vert \geqslant 2$, moreover $x\in A, y\in B$.
	\end{lem} 

	\begin{lem}(\cite{Yin})\label{lem2}
		A $4$-connected graph without removable edges is either $C_5^2$ or $C_6^2$.
	\end{lem}

	For $k$-connected graphs, the following result was given in Su et al.~\cite{Su}.
	\begin{lem}(\cite{Su})\label{lem3}
		Let $H$ be a $k$-connected graph with $k\geqslant 3$, let $X=\{x_1,x_2,\cdots,x_{k-1}\}\subset V(H)$ and $Y=\{y_1,y_2,\cdots,y_{k-1}\}\subset V(H)$.

		(i) If $H[X]\cong K_{k-1}$, then $G_X=(H-E_{X})+x+\{xx_i|i=1,2,\cdots,k-1\}+xy$ is $k$-connected if and only if $\kappa(H-E_{X})=\kappa(G_X-x)\geqslant k-1$, where $E_X\subseteq E(H[X]), x\notin V(H), y\in V(H)-X$;

		(ii) If $H[X]\cong K_{k-1}$ and $H[Y]\cong K_{k-1}$, then $G_{XY}=(H-E_{X}-E_{Y})+x+y+xy+\{xx_i|i=1,2,\cdots,k-1\}+\{yy_i|i=1,2,\cdots,k-1\}$ is $k$-connected if and only if $\vert X\cap Y\vert \leqslant k-2, \kappa(H-E_{X}-E_{Y})=\kappa(G_{XY}-x-y)\geqslant k-2$, and, if $\kappa(H-E_{X}-E_{Y})=\kappa(G_{XY}-x-y)= k-2$, any end of $H-E_{X}-E_{Y}$ contains both a vertex in $X$ and a vertex in $Y$, where $E_X\subseteq E(H[X]), E_Y\subseteq E(H[Y])$, $x,y\notin V(H)$.

	\end{lem}

	For removable edges of $4$-connected graphs, we have the following two conclusions. 

	\begin{lem}\label{lem4}
		Let $G$ be a $4$-connected graph with $\vert V(G)\vert \geqslant 7$ and let $R$ be a triangle of $G$. If $x\in V(R)$ with $d_G(x)\geqslant 5$, then there exists $y\in V(R)\setminus\{x\}$ such that $xy$ is removable.
	\end{lem}

	\begin{proof}
		Let $V(R)\setminus\{x\}=\{y_1,y_2\}$. Suppose $xy_1$ and $xy_2$ are both non-removable. Then by Lemma~\ref{lem1}, there exists $S\subseteq V(G)$ with $\vert S\vert=3$ such that $G-xy_1-S$ has exactly two components $A, B$ with $\vert A\vert \geqslant 2$ and $\vert B\vert \geqslant 2$, by symmetry we assume that $x\in A$ and $y_1\in B$. Moreover, there exists $T\subseteq V(G)$ with $\vert T\vert=3$ such that $G-xy_2-T$ has exactly two components $C, D$ with $\vert C\vert \geqslant 2$ and $\vert D\vert \geqslant 2$, by symmetry we assume that $x\in C$ and $y_2\in D$.

		Since $R$ is a triangle of $G$, we have $y_1\in T$ and $y_2\in S$. Now we observe that $x\in A\cap C, y_1\in B\cap T, y_2 \in S\cap D$. Let $X_1=(S\cap C)\cup (S\cap T)\cup (A\cap T), X_2=(A\cap T)\cup (S\cap T)\cup (S\cap D), X_3=(B\cap T)\cup (S\cap T)\cup (S\cap D), X_4=(S\cap C)\cup (S\cap T)\cup (B\cap T)$.

		{\bf Claim 1.} $\vert X_1\vert \geqslant 3$.

		For otherwise, since $d_G(x)\geqslant 5$, we have $A\cap C\neq \{x\}$. Note that $N_G((A\cap C)\setminus \{x\})=X_1\cup \{x\}$, which implies that $X_1\cup \{x\}$ is a $k$-cut of $G$ where $k\leqslant 3$, contradicting that $G$ is $4$-connected.

		{\bf Claim 2.} $A\cap T\neq \emptyset, S\cap C\neq \emptyset$.

		We show that $A\cap T\neq \emptyset$. For otherwise, by Claim $1$, we have $\vert (S\cap C)\cup (S\cap T)\vert \geqslant 3$, contradicting that $\vert S\vert=3$. By the similar arguments, we have $S\cap C\neq \emptyset$.

		{\bf Claim 3.} $S\cap T\neq \emptyset$.

		For otherwise, we assume that $S\cap T= \emptyset$. If $\vert S\cap C\vert =2$, then $\vert S\cap D\vert =1$ and $\vert X_2\vert, \vert X_3\vert \leqslant 3$, which implies that $A\cap D=B\cap D=\emptyset$, contradicting that $\vert D\vert \geqslant 2$. Hence we can assume that $\vert S\cap C\vert =1$. By Claim 1, we observe that $\vert A\cap T\vert =2$, then $\vert X_3\vert=3$ and $\vert X_4\vert=2$, which implies that $B\cap D=B\cap C=\emptyset$, contradicting that $\vert B\vert \geqslant 2$.

		Now we complete the proof of Lemma~\ref{lem4}. By Claims $2$ and $3$, we have that $\vert S\cap C\vert=\vert S\cap T\vert=\vert S\cap D\vert=\vert A\cap T\vert=\vert B\cap T\vert=1$. This implies that $A\cap D=B\cap D=\emptyset$, contradicting that $\vert D\vert \geqslant 2$.
	\end{proof}

	\begin{lem}\label{lem5}
		Let $G$ be a uniformly $4$-connected graph except for $C_5^2$ and $C_6^2$. Let $e=xy$ be a removable edge of $G$ with $d_G(x)=4$ and $d_G(y)\geqslant5$. Suppose $N_G(x)\setminus \{y\}=X=\{a,b,c\}$ such that $\vert E(G[X])\vert\leqslant1$. Let $H=G\ominus e$ such that $H$ is not uniformly $4$-connected with $\vert V(H)\vert \geqslant 7$. Then $X\subset V(H)$ and there exists an edge $e\in E(H[X])\setminus E(G[X])$ such that $e$ is a removable edge of $H$.
	\end{lem}

	\begin{proof}
		By Definition \ref{def4}, we have $X\subset V(H)$ obviously. It remains to show that there exists an edge $e$ of $H$ with the required properties. It follows that $H$ is $4$-connected and $H[X]\cong K_3$ by Definition \ref{def4}. Since $H$ is $4$-connected and not uniformly $4$-connected, it follows that there exists a pair of vertices which are $5$-connected in $H$, say $u$ and $v$. We can clearly observe that $u,v\in V(G)$ as well.

		At first we consider the case that $\vert E(G[X])\vert=1$, say $E(G[X])=\{ac\}$. Observe that $u$ and $v$ are $5$-connected in $H$, which implies that there exist at least five internally-disjoint paths between $u$ and $v$ in $H$. Now we show that $b\in \{u,v\}$. By contradiction, we assume that $b\notin \{u,v\}$. If neither $ab$ nor $bc$ lies on any of these paths, then $u$ and $v$ are $5$-connected in $G$ obviously, contradicting that $G$ is uniformly $4$-connected. If either $ab$ or $bc$ lies on one of these paths, say $P_1$, where $ab\in E(P_1)$ and $bc\notin E(P_1)$, then we can replace the edge $ab$ by $axb$, as the vertex $x$, the edges $ax$ and $bx$ do not exist in $H$. Thus we can define at least five internally-disjoint paths between $u$ and $v$ in $G$, a contradiction. Consequently, both $ab$ and $bc$ lie on one of these paths. Since $b\notin \{u,v\}$, it follows that both $ab$ and $bc$ lie on the same path, as these paths are internally-disjoint. Thus, we can replace the subpath $abc$ by $axc$, as the vertex $x$, the edges $ax$ and $bx$ do not exist in $H$. Hence we can define at least five internally-disjoint paths between $u$ and $v$ in $G$, a contradiction. Consequently, $b\in \{u,v\}$, which implies $d_H(b)\geqslant 5$. Since $\vert V(H)\vert \geqslant 7$ and $H[X]\cong K_3$, $ba$ or $bc$ is removable in $H$ by Lemma \ref{lem4}. Observe that $ba,bc\in E(H[X])\setminus E(G[X])$, thus there exists an edge $e\in E(H[X])\setminus E(G[X])$ such that $e$ is a removable edge of $H$.

		Next we consider the case that $E(G[X])=\emptyset$. By the arguments similar to those of the above case, we can obtain that $\{a,b,c\}\cap\{u,v\}\neq\emptyset$. Then there exists a vertex $w\in \{a,b,c\}$ such that $d_H(w)\geqslant 5$. Hence there exists an edge $e\in \{ab,ac,bc\}$ is removable in $H$. Observe that $\{ab,ac,bc\}=E(H[X])\setminus E(G[X])$, thus there exists an edge $e\in E(H[X])\setminus E(G[X])$ such that $e$ is a removable edge of $H$.
	\end{proof}

	The following lemma follows straightforwardly from Lemma~\ref{lem3}.
	\begin{lem}\label{lem6}
		Let $H$ be a $4$-connected graph. Let $G$ be constructed by applying $\Delta_1^+$ or $\Delta_2^+$-operation to a set $S$ of vertices and edges of $H$. Then $G$ is $4$-connected. 
	\end{lem} 


	\section{The main result}
	\hspace*{1.3em} We will now demonstrate that quasi $4$-compatibility is both necessary and sufficient to guarantee that applying the $\Delta_1^+$ or $\Delta_2^+$-operation to a quasi $4$-compatible set in a uniformly $4$-connected graph results in a graph that remains uniformly $4$-connected.

	\begin{lem}\label{lem7}
		Let $H$ be a uniformly $4$-connected graph. Let $G$ be constructed by applying the $\Delta_1^+$-operation to a set $S$ of vertices and edges of $H$. Then $G$ is uniformly $4$-connected if and only if $S$ is a quasi $4$-compatible set in $H$. 
	\end{lem}


	\begin{proof}
		First, we suppose that $G$ is a uniformly $4$-connected graph, and that $S$ is not a quasi $4$-compatible set in $H$. We will give a detailed proof only for $H[X]\cong K_3$ and $E_X=\{ac\}$. We observe that $S=\{a,b,c,y,ac\}$(see Fig. \ref{Fig1}) by Definition \ref{def3}. Since $S$ is not quasi $4$-compatible in $H$, there must exist a $uv$-path where $u\in X, v= y$ or $u=a, v= b$ or $u=b, v=c$ which is a quasi $3$-circuit chording path in $H-ac$. However, in $G$, the endpoints of the subpath of that quasi $3$-circuit chording path are $5$-connected, which contradicts that $G$ is uniformly $4$-connected. Therefore, $S$ must be a quasi $4$-compatible set in $H$.

		\begin{figure}[H]
