%------
$$(\Delta_0\vdash s_0) \rightsquigarrow^{\theta_0}_{\theory{R,E}} (\Delta_1 \vdash s_1) \rightsquigarrow^{\theta_1}_{\theory{R,E}}  \ldots \rightsquigarrow^{\theta_{n-1}}_{\theory{R,E}} (\Delta_n \vdash s_n) $$
