%			&& R+A \ar[dl]^{[mr_1,1_A]}\ar[ul]_{[mr_2,1_A]}\\
%			& A
%		}
%	\]
	Easy calculations shows that the diagram
	\[
		\xymatrix@C=15ex@R=8ex{
			& A\\
			(R\times_{\langle r_2,r_1\rangle}R +R)+(R+A)
			\ar[rr]^-{[\iota_1[\tau,1_R],1_{R+A}]} 
			\ar[dr]|{[[mr_1\pi_1,mr_1],[mr_1,1_A]]}
			\ar[ur]|{[[mr_2\pi_2,mr_2],[mr_2,1_A]]}
			&& R+A \ar[dl]^{[mr_1,1_A]}\ar[ul]_{[mr_2,1_A]}\\
			& A
		}
	\]
	commutes, $\overline r_1 \overline \pi_1 \tilde e =[[mr_1\pi_1,mr_1],[mr_1,1_A]]$ and 
 $\overline r_2 \overline \pi_2 \tilde e=[[mr_2\pi_2,mr_2],[mr_2,1_A]]$.
It now follows that the diagram 
	\[
		\xymatrix{
			(R\times_{\langle r_2,r_1\rangle}R +R)+(R+A) \ar[r]^-{\tilde e} \ar[d]|{e[\iota_1[\tau,1_R],1_{R+A}]} &  \bar R\times_{\langle \bar r_2,\bar r_1\rangle} \bar R \ar[d]|{ \langle \bar r_1\pi_2,\bar r_2\pi_2\rangle} \ar@{-->}[dl]_{\tilde \tau}\\
	\bar R \ar[r]_{\langle \bar r_1,\bar r_2\rangle} & A\times A
}
\]
	(ignoring the dotted arrow) commutes, and hence since $\tilde e$ is a regular epimorphisms, and $\langle \bar r_1, \bar r_2 \rangle$ is 
	a monomorphism, that there exits a morphism $\tilde \tau$, as shown with a dotted arrow above, making the diagram commute.
\end{proof}
\begin{proposition}\label{prop:stab_reg}
Let $\C$ be an exact category satisfying Condition \ref{conditions}.
The category $\C$ admits pushouts of monomorphisms along regular epimorphisms, 
which are pullbacks. Monomorphisms are stable under
pushout along regular epimorphisms in $\C$.
\end{proposition}
\begin{proof}
Let $e:S\to T$ be a regular epimorphism and let $m:S\to A$ be a monomorphism.
	Writing $(R,r_1,r_2)$ for the kernel pair of $e$, Proposition \ref{proposition:7} implies 
	that the reflexive closure of $(R,mr_1,mr_2)$ is an equivalence relation.
	Writing $p:A\to B$ for the coequalizer of this equivalence relation, one can easily check
	that $p$ is also the coequalizer of $mr_1,mr_2:R\to A$ and hence there exists
	$n:T\to B$ such that the diagram
	\[
		\xymatrix{
		S\ar[r]^{e}\ar[d]_{m} & T\ar[d]^{n}\\
		A\ar[r]_{p} & B
	}
	\]
	is a pushout. Next consider the diagram
	\begin{equation}
\label{star}
\tag{*}
\vcenter{
		\xymatrix{
			R+S \ar[d]_{1_A+m} \ar@<0.5ex>@/^6ex/[rr]^{[r_1,1_S]}\ar@<-0.5ex>@/^6ex/[rr]_{[r_2,1_S]} \ar[r]^{u} & R\ar[d]^{\tilde m} \ar@<0.5ex>[r]^{r_1} \ar@<-0.5ex>[r]_{r_2} & S\ar[r]^{e}\ar[d]_{m} & T\ar[d]^{n}\\
		R+A \ar@<0.5ex>@/_6ex/[rr]^{[mr_1,1_A]}\ar@<-0.5ex>@/_6ex/[rr]_{[mr_2,1_A]} \ar[r]^{v}&  \bar R \ar@<0.5ex>[r]^{\bar r_1} \ar@<-0.5ex>[r]_{\bar r_2}& A\ar[r]_{p} & B
	}
}
	\end{equation}
 which commutes reasonably.
	Since for $i=1$ or $i=2$ the two squares of the left hand diagram
\[
		\xymatrix{
			R+S \ar[d]_{1_A+m} \ar@/^6ex/[rr]^{[r_i,1_S]} \ar[r]^{r_i+1_S} & S+S\ar[d]^{1+m} \ar[r]^{[1_S,1_S]}  & S\ar[d]_{m} & 
			R+S \ar[d]_{1_A+m} \ar@/^6ex/[rr]^{[r_i,1_S]} \ar[r]^{u} & R\ar[d]^{\tilde m} \ar[r]^{r_i}  & S\ar[d]_{m}\\
		R+A \ar@/_6ex/[rr]^{[mr_i,1_A]} \ar[r]^{r_i+1_A}&  S+A \ar[r]^{[m,1_S]}& A &
		R+A \ar@/_6ex/[rr]^{[mr_i,1_A]} \ar[r]^{v}&  \bar R \ar[r]^{\bar r_i}& A
	}
	\]
are feeble pullbacks it follows that the outer arrows on the left and hence on the right
(because they are the same) 
form a feeble pullbacks. Therefore, since $v$ is regular epimorphism it follows that right hand commutative square is a feeble pullback.
        However since $\tilde m$ is a monomorphism this means it is a pullback.
 From this we conclude that the right hand square of \eqref{star} is a pullback.
\end{proof}
\begin{proposition}\label{prop:stab_cod_incl}
Let $\C$ be a category satisfying Condition \ref{conditions}.
$\C$ admits pushouts of monomorphisms along coproduct inclusions, which are pullbacks. Monomorphisms are stable under
pushout along coproduct inclusions in $\C$.
\end{proposition}
\begin{proof}
Let $\iota_2: S \to A+S$ be a coproduct inclusion and $n:S\to B$ 
a monomorphism. Noting
the diagrams
\[
\xymatrix{
0 \ar[r]\ar[d] & 0 \ar[d] & S \ar[r]^{n}\ar[d]_{1_S} & B\ar[d]^{1_B}\\
A\ar[r]_{1_A} & A & S \ar[r]_{n} & B
}
\]
are pullbacks it follows that their binary coproduct 
\[
\xymatrix{
S \ar[r]^{n} \ar[d]_{\iota_2} & B\ar[d]^{\iota_2}\\
A+S \ar[r]_{1+n} & A+B
}
\]
is a pullback. It is also a pushout. Note that $1+n$ is a monomorphism since 
each of its kernel pair projections will be the coproduct of the respective
kernel pair projections of $1$ and $n$.
\end{proof}
\begin{proposition}
Let $\C$ be an exact category satisfying Condition \ref{conditions}.
The pushout of a monomorphism along an arbitrary morphism exists and produces a pullback in $\C$. Monomorphisms are pushout stable in $\C$.
\end{proposition}
\begin{proof}
Just note that an arbitrary morphism $f:A\to B$ factors as
\[
\xymatrix{
A \ar[r]^-{\iota_1} & A+B \ar[r]^-{[f,1]} & B,
}
\]
and successively apply Proposition \ref{prop:stab_cod_incl} and \ref{prop:stab_reg}.
\end{proof}
\begin{corollary}
Let $\C$ be an exact category satisfying Condition \ref{conditions}.
Monomorphisms are regular in $\C$, and $\C$ is balanced and coregular as soon as 
it has pushouts of regular epimorphisms along regular epimorphisms. 
\end{corollary}
Since the cokernel pair of an arbitrary morphism can be constructed as the pushout
of its regular image along itself we have:
\begin{corollary}
An exact category satisfying Condition \ref{conditions} admits cokernel pairs of arbitrary morphisms.
\end{corollary}
\begin{proposition}
Let $\C$ be an exact category satisfying Condition \ref{conditions}.
Every reflexive corelation in $\C$ is an co-effective-equivalence-relation.
$\C$ is coexact as soon as it admits pushouts of regular epimorphisms along
themselves.
\end{proposition}
\begin{proof}
	Suppose that $[q_1,q_2]: A+A\to Q $ is a reflexive corelation in $\C$, that is $[q_1,q_2]$ is an epimorphism such that there exists $e: Q\to A$ such that $e[q_1,q_2]=[1_A,1_A]$. Let $m:S\to A$ be equalizer of $q_1$ and $q_2$. 
Since each of the squares in the diagrams
\[
\xymatrix{
A+S \ar[r]^{1+m} \ar[d]_{1+m} & A+A \ar[d]^{1+q_2} & S+A \ar[r]^{m+1} \ar[d]_{m+1} & A+A \ar[d]^{q_1+1}\\
A+A \ar[r]_{1+q_1} \ar[d]_{[1,1]} & A+Q \ar[d]^{[q_1,1]} & A+A \ar[r]_{q_2+1} \ar[d]_{[1,1]} & Q+A \ar[d]^{[1,q_2]}\\
A\ar[r]_{q_1} & Q & A\ar[r]_{q_2} & Q
}
\]
are pullbacks it follows that their composite are pullbacks and hence the left
hand square in the diagram
	\[
		\xymatrix@C=12ex{
			(A+S)+(S+A) \ar[r]^-{(1_A+m)+(m+1_A)}\ar[d]_{[1_A,m]+[m,1_A]} & (A+A)+(A+A)\ar[d]^{[q_1,q_2]+[q_1,q_2]} \ar[r]^{[1,1]} & A+A\ar[d]^{[q_1,q_2]} \\
			A+A \ar[r]_{q_1+q_2}& Q+Q \ar[r]_{[1,1]}  & Q 
		}
	\]
is a pullback so that its composite is feeble pullback. 
That is the diagram
	\[
		\xymatrix@C=12ex{
			(A+S)+(S+A) \ar[r]^-{[1_A+m,m+1_A]}\ar[d]_{[1_A,m]+[m,1_A]} & A+A\ar[d]^{[q_1,q_2]} \\
			A+A \ar[r]_{[q_1,q_2]} & Q 
		}
	\]
	is a feeble pullback. Since $[q_1,q_2]$ is a regular epimorphism it also the coequalizer of $[1_A,m]+[m+1_A]$ and $[1_A+m,m+1_A]$. Since the morphisms $\iota_1+\iota_2 : A+ A \to (A+S)+(S+A)$ and $\iota_1\iota_2, \iota_2\iota_1 : S \to (A+S)+(S+A)$ are jointly epimorphic and  $([1_A,m]+[m+1_A]) (\iota_1+\iota_2) = 1_{A+A}$ and $([1_A+m,m+1_A])(\iota_1+ \iota_2)=1_{A+A}$, $([1_A,m]+[m+1_A])(\iota_1\iota_2)=\iota_1 m$ and $([1_A+m,m+1_A])(\iota_1\iota_2)=\iota_2m$, and $([1_A,m]+[m+1_A])(\iota_2\iota_1)=\iota_2m$ and $([1_A+m,m+1_A])(\iota_2\iota_1)=\iota_1m$, it follows that $[q_1,q_2]$ is the coequalizer of $\iota_1m$ and $\iota_2m$. It immediately follows that $(Q,q_1,q_2)$ is the pushout of $m$ along $m$.
\end{proof}
Combining the various results we obtain:
\begin{theorem}\label{theorem:1}
Let $\C$ be an exact category satisfying Condition \ref{conditions}.
If $\C$ has finite colimits, then $\C$ is coexact.
\end{theorem}
On the other hand we have:

\begin{theorem}\label{theorem:2}
Let $\C$ be an exact category satisfying Condition \ref{conditions}.
$\C$ is coprotomodular.
\end{theorem}
\begin{proof}
	As explained in the introduction (and dualizing) it is sufficient to show that for 
	a diagram
	\[
		\xymatrix@C=2ex@R=3ex{
			&& A'\ar[rrr]^{q'} &&& Q'\ar[rrr]^{m'} &&& C'\\ 
			A\ar[urr]^{f} \ar[rrr]^(0.75){q} &&& Q \ar[urr]^{g} \ar[rrr]^(0.7){m} &&& C \ar[urr]^{h}\\
			\\
			&B\ar[uul]^{\alpha} \ar[uuur]_(0.4){\alpha'}\ar[rrr]^{p}& && S \ar[uul]^{\rho} \ar[uuur]_(0.4){\rho'}\ar[rrr] &&& 1\ar[uul]^{\sigma}\ar[uuur]_{\sigma'}\\
		}
	\]
	in which $\alpha$ and $\alpha'$ are monomorphisms, $\sigma$ and $\sigma'$ are obtained by pushing out $\alpha$ and $\alpha'$ along $B\to 1$, and $f$ is an epimorphism, if $h$ is an isomorphism, then $f$ is an isomorphism. The remaining objects and arrows in the diagram can be obtained by taking the (regular epi-mono)-factorizations of the horizontal morphisms (or equivalently by taking the (regular epi,mono)-factorization $B\to 1$ and pushing out $\alpha$ and $\alpha'$ along $p$ to obtain $\rho$ and $\rho'$, respectively, and then pushing out these morphisms along $S\to 1$ to complete the diagram). It easily follows that $g$ is an isomorphism and the kernel pair $(R,r_1,r_2)$ of $q$ is the smallest equivalence relation containing $(B\times B, \alpha\pi_1, \alpha\pi_2)$. By Proposition \ref{proposition:7}  it follows that there is a regular epimorphism $e: (B\times B) + A \to R$ making the diagram
\[
\xymatrix{
(B\times B) + A \ar[dr]|{\langle [\alpha \pi_1,1_A], [\alpha \pi_2,1_A]\rangle} \ar[rr]^{e} && R \ar[dl]^{\langle r_1,r_2\rangle}\\
	& A\times A
}
\]
	commute. Let $(T,t_1,t_2)$ be the kernel pair of $f$. Since $g$ is a isomorphism it follows that $qt_1 = qt_2$ and hence there exists $u: T \to R$ such that $r_i u = t_i$. Since the right hand square
	and the outer arrows of the diagram
	\[
		\xymatrix{
			B \ar@/^3ex/[rr]^{\nu}\ar@{-->}[r]_{\tilde \alpha}\ar[d]_{\langle 1,1\rangle} & T \ar[r]_{\tilde f}\ar[d]^{\langle t_1,t_2 \rangle} & A'\ar[d]^{\langle 1,1\rangle}\\
			B\times B \ar@/_3ex/[rr]_{\alpha'\times \alpha'}\ar[r]^{\alpha\times \alpha} & A\times A \ar[r]^{f\times f} & A'\times A'
		}
	\]
	are pullbacks it follows that the left hand square is too. Therefore, since the
	diagram
	\[
		\xymatrix{
			B \ar[r]^{\nu}\ar[d]_{\langle 1,1\rangle} & T \ar[d]^{u} \ar@/^5ex/[ddr]^{\langle t_1,t_2\rangle}\\
			B\times B \ar[r]^{e\iota_1} \ar@/_5ex/[drr]_{\alpha\times \alpha} & R\ar[dr]^{\langle r_1,r_2\rangle}\\
			& & A\times A
		}
	\]
	commutes and $\langle r_1,r_2\rangle$ is a monomorphism it follows that the square
	in the previous diagram is a pullback. It follows that both squares in the diagram
	\[
		\xymatrix{
			B+A\ar[d]_{\langle 1,1\rangle + 1} \ar[r]^{\nu + s} & T+T \ar[r]^{[1,1]}\ar[d]^{u+1} & T\ar[d]^{u}\\
			(B\times B) + A \ar[r]_{e\iota_1+s} & R+ T \ar[r]_{[1,u]} & R
		}
	\]
	are pullbacks, and hence we obtain a pullback:
	\[
		\xymatrix{
			B+A \ar[d]_{\langle 1,1\rangle+1} \ar[r]^{[\nu,s]} & T \ar[d]^{u}\\
			(B\times B) + A \ar[r]_-{e} & R.
		}
	\]
	Since $\iota_1$ and $\iota_2$ are jointly epimorphic and $[\nu,s]$ is an epimorphism
	it follows that $\nu$ and $s$ are jointly epimorphic. Therefore, since $t_1\nu=\alpha=t_2\nu$
	and $t_1s=1_T=t_2s$ 
	it follows that $t_1=t_2$ and hence $f$ is an isomorphism.
\end{proof}
Recall that a Mal'tsev category is arithmetical \cite{PEDICCHIO:1996} if 
equivalence relation lattices of an object in it, are distributive.
\begin{theorem}\label{main-theorem}
	The opposite category of a pretopos with finite colimits is arithmetical and ideally exact.
\end{theorem}
\begin{proof}
	Combining Theorems \ref{theorem:1} and \ref{theorem:2} we need only show that the unique morphism from $0\to 1$ in 
	a pretopos is a monomorphism and that each lattice of co-equivalence-relations of an object in a pretopos is distributive. The former is well-known and latter follows immediately from the fact that
	for each object $A$ the
lattice of co-equivalence-relation on $A$ is in bijection with the subobject lattice of $A$, which is distributive as explained above.
\end{proof}

