\centering
\includegraphics[width=\columnwidth]{fig1.pdf}
%\includegraphics[width=\columnwidth]{fig1.pdf}
\caption{Examples of the energy spreading process: trajectories $x_i(t)$ of particles vs time for three values of parameter $a$: panel (a) $a=0$; panel (b) $a=0.25$; panel (c) $a=0.5$. }
\label{fig:1}
