	%\phantomsection\addcontentsline{toc}{section}{Introduction}
	\section{Introduction}%\pagenumbering{arabic}
	In geometric topology, a central goal is to classify geometric objects up to continuous deformation. This often involves the study of invariants. \com{Other examples: plane curves, spherical curves}A classical and well-studied setting is knot theory, which analyzes embeddings of the circle $ \S^1 $ into $ \R^3 $. Another rich domain is the study of knotted surfaces, such as embeddings of the two-sphere $ \S^2 $ into $ \R^4 $, both of which yield intricate and diverse families of inequivalent embeddings.

	In the space of embeddings of $ \S^2 $ into $ \R^3 $, however, every embedded sphere can be deformed to a standard round sphere of the same orientation \cite{Alexander_EmbSpheres}. Even allowing for self-intersections does not yield more components: the space of immersed spheres in $ \R^3 $ forms a single regular homotopy class \cite{Smale_SE}. This foundational result by Smale sparked interest in \textit{sphere eversions}---regular homotopies between embedded spheres of opposite orientation.
	A result by Max and Banchoff first revealed an interesting structure of self-intersections in the space of immersed spheres.
	\begin{defn}
		An $ n $\emph{-tuple point} of a map $ f:X\to Y $ between sets is a point $ y\in Y $ whose preimage $ f^{-1}(\{y\}) $ contains at least $ n $ points.
	\end{defn}
	\begin{theorem*}{\cite{MB_SE}}\label{thm_SEquad}
		Every sphere eversion has at least one quadruple point.
	\end{theorem*}
	Alternative proofs can be found in \cite{Hughes_SE,Gor_Local}.
	This shows that removing immersions with quadruple points divides the space of immersed spheres into two or more components.
	The proof in \cite{MB_SE} yields a map 
	$$ \{f\in \Imm(\S^2,\R^3) \setsep f \text{ has no quadruple points} \} \to \Z/2\Z, $$ 
	which is invariant under regular homotopies. This is an example of a \textit{local invariant}.
	Such invariants have further been studied for arbitrary oriented surfaces in \cite{Gor_Local,Nowik_Quad, Nowik_AutoQInv,Nowik_qInv}. They are special cases of \textit{finite order} invariants, originally introduced in knot theory by Vassiliev \cite{Vass_Cohom} (cf.\ \cite{CDM_VassilievKnotInv}) and later extended to immersed surfaces in \cite{Nowik_OrderOne,Nowik_HigherOrder}. They define a large class of invariants that provide insight into the structure of the space of immersed surfaces.

	However, the classification of all finite order invariants in \cite{Nowik_HigherOrder} shows that such invariants cannot separate any triple-point-free immersion from \emph{both} standard embedded spheres by triple or quadruple points.
	We present an invariant that serves this purpose for triple points; it is therefore necessarily not of finite order.

	The paper is organized as follows. The invariant and its properties are stated in Section~\ref{sec_intro_main} whereas in Sections~\ref{sec_intro_Immn} and~\ref{sec_intro_Willmore} some applications are discussed. Section~\ref{sec_prelim} fixes notation and introduces necessary background. In Section~\ref{sec_tree} each immersed sphere without triple points is associated to a directed tree which encodes its double point structure. Section~\ref{sec_treeEH} contains the classification of modifications that a regular homotopy can induce on such trees. Finally, Sections~\ref{sec_Invariant} and~\ref{sec_image} contain the proofs of the main Theorems~\ref{thm_Invariant} and~\ref{thm_imageF}, respectively.

	\subsection{Main Results}\label{sec_intro_main}
	We denote by $ \Imm(\S^2,\R^3) $ the space of smooth immersions $\S^2\to\R^3$ and for $ n\geq 2 $
	\begin{equation*}
		\Imm_{<n}(\S^2,\R^3):=\{f\in \Imm(\S^2,\R^3)\ | \ \text{f has no } n \text{-tuple points}\}
	\end{equation*}
	denotes the set of immersed spheres without $ n $-tuple points.
	The invariant is first defined on generic immersions and then extended to all immersions in $ \Imm_{<3}(\S^2,\R^3) $ (see Proposition~\ref{prop_extension}). Given a generic immersion $ f\in \Imm_{<3}(\S^2,\R^3) $, we associate to it a directed tree $ G_f=(V_f,E_f) $ and a topological degree $ \delta_f:V_f\to\Z $ as described in Section~\ref{sec_tree}. For a vertex $ v\in V_f $ we denote by $ \deg^-(v) $ the \textit{indegree} of $ v $, that is, the number of edges that point into $ v $.
	\begin{defn}
		We define
		\begin{equation*}
			F:\Imm_{<3}(\S^2,\R^3)\to \Z^\Z,\qquad f\mapsto \left[\sum_{v\in \delta_f^{-1}(\{k\})} \left( 1-\deg^-(v)\right)\right]_{k\in\Z}.
		\end{equation*}
	\end{defn}
	\begin{theorem}\label{thm_Invariant}
		$ F $ is invariant under regular homotopies in $ \Imm_{<3}(\S^2,\R^3) $.
	\end{theorem}
	\begin{theorem}\label{thm_imageF}
	The image of $ F $ is given by
	%	Let $ h=(h_k)_{k\in\Z} \in \Z^\Z $. Then, there exists $ f\in I(T) $ with $ F(f)=h $ if and only if $ h $ satisfies all of the following
		%\begin{enumerate}[label=\roman*)]
	%		\item $ h_{2k} = 0 $ for all $k\in\Z $.
	%		\item $ \sum_{k\in\Z} |h_k|<\infty $.
	%		\item $ \sum_{k\in\Z} h_k = 1 $.
	%	\end{enumerate}
		\begin{align*}
			\left\{ (h_k)_{k\in\Z} \in \Z^\Z \ \middle| \ h_{2k} = 0 \text{ for all } k\in\Z \text{ and }\sum_{k\in\Z} |h_k|<\infty \text{ and } \sum_{k\in\Z} h_k = 1 \right\}.
		\end{align*}
	\end{theorem}
	Interestingly, the image is entirely realized by surfaces of revolution (see Section~\ref{sec_image}).

	\begin{rem}
		Recall that the space of diffeomorphisms $ \text{Diff}(\S^2) $ has two homotopy classes which contain the orientation-preserving and -reversing diffeomorphisms \cite{Smale_DiffS2}. With Lemma~\ref{lem_delta-f}~\ref{lem_delta-f_-f}, the invariant $ F $ restricts to $ \Imm_{<3}(\S^2,\R^3) / \text{Diff}(\S^2) \to \Z^{\Z}/\sim $ by identifying $ (h_k)_{k\in\Z} \sim (l_k)_{k\in\Z} $ if $ h_k = l_{\m k} $.
	\end{rem}

	\subsection{The Space of Immersed Spheres without $ n $-tuple Points}\label{sec_intro_Immn}

	It is unknown whether the invariant $ F $ is complete. However, Theorem~\ref{thm_imageF} shows that it already divides the space $ \Imm_{<3}(\S^2,\R^3) $ into infinitely many components. Previously, it was known---via the invariant of \cite{MB_SE}---that this space has at least two components. Table~\ref{tab_RHCNtuple} provides an overview of the number of components of the space of immersed spheres without $ n $-tuple points.

