	Any regular homotopy $ H $ can be slightly perturbed such that $ H_t $ is generic for all but finitely many times $ t_1,\dots,t_k $ at which it is contained in one of the codimension one strata $ E $, $ H $, $ T $ or $ Q $. We call such a regular homotopy \textit{generic}.

	\section{The Double Point Tree of a Generic Immersed Sphere without Triple Points}\label{sec_tree}
	Throughout this section let $ f\in\Imm_{<3}(\S^2,\R^3) $ be generic.
	Consider the double point set
	\begin{equation*}
		X_2(f):=\left\{ x\in\R^3 \ \mid\ f^{-1}(\{x\}) \textit{ has exactly two elements} \right\}.
	\end{equation*}
	Locally around a point $ x\in X_2(f) $, the image of $ f $ is, up to ambient isotopy, the intersection of two coordinate planes. Together with the assumption that $ f $ has no triple points, this implies the following.
	The preimage of each connected component of $ X_2(f) $ consists of two circles.
	Let $ \alpha_i,\beta_i $ with $ i=1,\dots,m $ be pairs of parametrizations $ \alpha_i,\beta_i:\S^1\to\S^2 $ of these circles such that $ f\circ \alpha_i = f\circ \beta_i$. We call $ \alpha_i,\beta_i $ and also their images the \textit{double point curves} of $ f $, and we refer to $ \beta_i $ as the \textit{conjugate} of $ \alpha_i $.
	Self-conjugate curves do not exist in the absence of triple points (see the lemma in \cite[p.\ 411]{Banch_TPSurgery}).
	This yields a finite collection of pairwise disjoint double point curves on $ \S^2 $.

	We define a graph $ G_f=(V_f,E_f) $ where the vertices $ V_f $ are the connected components of $ \S^2 $ with the double point curves removed. The set of edges $ E_f $ contains all pairs of components whose boundaries have nonempty intersection. Since the double point curves are disjoint, a common boundary between two components always consists of a single double point curve. Therefore, we can identify $ E_f $ with the set of double point curves. %$ E_f=\{\alpha_i,\beta_i\ | \ i=1,\dots,m\}. $
	\begin{defn}
		A map $ P:X\to X $ on a set $ X $ is called a \textit{pairing} if $ P \circ P=\id $ and $ P(x)\neq x $ for all $ x\in X $.\com{short: fixed-point-free involution}
	\end{defn}
	We observe that $ G_f $ is a tree with a pairing $ P_f:E_f\to E_f $ defined by $ P_f(\alpha_i):=\beta_i $. 

	\begin{rem}
	Such tree representations are the higher dimensional analogue for Gauss codes of self-intersecting curves \cite{Rosenstiehl_GaussCodes}. 
	A natural question is the classification of \textit{realizable} trees---those that represent the self-intersections of an actual immersion. There is a classification of realizable trees with a pairing \cite{Lippner,Kalmar_DoublePointsKnottedSpheres}. For the general case of generic immersed spheres (with triple points) the classification of realizable graphs remains open (see \cite{Nowik_DissectingS2,Borbely}).
	\end{rem}

	We want to endow the tree $ G_f $ with additional information in two steps. First, we turn it into a \textit{directed} tree, using the pairing:
	A pair of double point curves $ (\alpha_i,\beta_i) $ divides $ \S^2 $ into two disk components and one annulus component. Hence, each edge connects a component contained in one of the disks to a component contained in the annulus. We orient the edge toward the disk component. In the tree, hence, each edge is directed away from its conjugate edge along the unique path connecting the pair.

	Second, we introduce a function $ \delta_f:V_f\to\Z $ which we call the \textit{(local) topological degree} of $ f $. Let us first associate to each connected component $ C $ of $ \R^3\setminus f(\S^2) $ its topological degree. Pick any point $ p\in C $ and consider the radial projection of $ f $ onto $ \partial_1 B(p)\simeq \S^2 $, i.e. $ f_p(x)  = \frac{f(x)-p}{|f(x)-p|} $. This is a differentiable map $ f_p:\S^2\to\S^2 $ and we set
	$$ \deg_f C:= \deg f_p, $$
	where $ \deg $ denotes the topological degree (cf.\ \cite{Bred}). This is well-defined since $ f_p $ and $ f_q $ are homotopic for all $ p,q\in C $, i.e.\ take a path $ c:[0,1]\to C $ from $ p $ to $ q $ and the homotopy $ t\mapsto f_{c(t)} $.
	For $ v\in V_f $ the image set $ f(v) $ has exactly two adjacent connected components $ C_1,C_2 $ of $ \R^3\setminus f(\S^2) $ and we set 
	$$ \delta_f(v):= \deg_f C_1 + \deg_f C_2. $$
	\com{The degree $ \delta_f $ is not to be confused with the topological degree of the normal of $ f $ which is always $ 1 $ since all immersed spheres in $ \R^3 $ are regularly homotopic, i.e.\ all normal maps are homotopic.}

	\begin{defn}\label{def_tree}
		A \textit{double point tree} is a triple $ (G,P,\delta) $ of a directed tree $ G=(V,E) $, a pairing $ P:E\to E $, and a map $ \delta:V\to\Z $.
		The \textit{double point tree} of a generic immersion $ f\in \Imm_{<3}(\S^2,\R^3) $ is the double point tree $ (G_f,P_f,\delta_f) $.
	\end{defn}

	\begin{lem}\label{lem_delta-f}
		For generic $ f\in \Imm_{<3}(\S^2,\R^3) $ we have for all $ v\in V_f $ and $ (v,w)\in E_f $
		\begin{enumerate}[label=\roman*)]
			\item $ \delta_f(v) $ is odd,\label{lem_delta-f_odd}
			\item $ \delta_f(w) = \delta_f(v)\pm 2 $,\label{lem_delta-f_pm2}
			\item $ \delta_{-f} = -\delta_f $.\label{lem_delta-f_-f}
		\end{enumerate}
	\end{lem}
	\begin{proof}
		\ref{lem_delta-f_odd} The functions $ f_p:\S^2\to\S^2 $ are differentiable, so the degree can be computed by counting the preimages of a regular value with orientation (cf.\ \cite{Bred}). If $ p $ passes through one sheet of the image of $ f $, then by this definition the degree of $ f_p $ changes by $ \pm 1 $. It follows that $ \delta_f $ has odd values. \\
		\ref{lem_delta-f_pm2} Now, take some point $ q $ on $ f(v) $ and let $ \nu(q) $ denote the normal of $ f $ in $ q $. For small $ \eps>0 $ we have $ \delta_f(v) = \deg f_{q+\eps\nu(q)} + \deg f_{q-\eps\nu(q)} $. If we move $ q $ on the image of $ f $ into $ f(w) $, it passes through a sheet of $ f $ and by the same argument as above, the degrees of  $ f_{q+\eps\nu(q)} $ and $ f_{q-\eps\nu(q)} $ both increase by $ 1 $ or both decrease by $ 1 $.\\
		\ref{lem_delta-f_-f} We identify the images of $ f $ and $ -f $ by the map $ x\mapsto -x $. As $ -f $ has opposite orientation to $ f $, the degrees of the connected components of $ \R^3\setminus (-f)(\S^2) $ and $ \R^3 \setminus f(\S^2) $ satisfy $ \deg_{-f} -C = - \deg_f C $.
	\end{proof}

	\begin{ex}\label{ex_eTree}
