	\begin{prop}\label{prop_classTreeMod}
		Let $ J:\S^2\times[0,1]\to\R^3$ be a generic regular homotopy without triple points such that $ J_t $ is generic for all $ t\in[0,1]\setminus \{t_0\} $ and $ J_{t_0}\in I_1 $. Denote $ f:=J_0 $ and $ g:=J_1 $. Then, up to interchanging $ f $ and $ g $, the double point tree of $ G_g $ is constructed from $ G_f $ in one of the following ways
		\begin{enumerate}[label=\roman*)]
			\item \label{enum_treeModE}Type $ E $: 
			$ G_g $ has two additional vertices $ w_1, w_2 $ and two edges $ (v_1,w_1),(v_2,w_2) $ for some $ v_1,v_2\in V_f $ with $ \delta(v_1)-\delta(v_2) \in \{-2,0,2\}$. It holds $ P_g((v_1,w_1))=P_g((v_2,w_2)) $, $ \delta(w_i)=\delta(v_i)\pm 2 $ and $ \abs{\delta(\{v_1,v_2,w_1,w_2\})}=2 $.
			\item \label{enum_treeModH}Type $ H $: 
			For a pair of edges $ a_1=(v_1,w_1),a_2=(v_2,w_2)\in E_f $ with $ P_f(a_1)=a_2 $ and $ \abs{\delta(\{v_1,v_2,w_1,w_2\})}=2 $, the double point tree $ G_g $ is obtained from $ G_f $ by an $ \text{H}_p $- or $ \text{H}_s $-split on $ a_1 $ and an $ \text{H}_p $- or $ \text{H}_s $-split on $ a_2 $. The two added edges define a new pair.
		\end{enumerate} 
