	\begin{prop}\label{prop_extension}
		The invariant $ F $ extends uniquely onto $ \Imm_{<3}(\S^2,\R^3) $ such that $ F $ is invariant under regular homotopies without triple points.
	\end{prop}
	\begin{proof}
		Let $ f\in \Imm(\S^2,\R^3) $ be without triple points. Then, in $ C^k $-topology a neighborhood of $ f $ does not have triple points and a slight perturbation $ \tilde{f} $ of $ f $ yields a generic immersion with $ F(\tilde f) $ defined. We set $ F(f):=F(\tilde f) $. This is well defined since any two generic perturbations of $ f $ are joined by a regular homotopy without triple points. Furthermore, this is the unique extended invariant since $ \tilde{f} $ was obtained from $ f $ by a regular homotopy without triple points.
	\end{proof}
	We denote by $ e_i:=(\delta_{ik})_{k\in\Z} $ the standard basis vectors of $ \Z^\Z $.
	\begin{ex}\label{ex_Fej}
		Let $ j $ be as in Figure~\ref{fig_sketchJ} with outer normal and recall the standard embedding $ e:\S^2\to\R^3 $. We compute directly with Lemma~\ref{lem_delta-f} and Examples~\ref{ex_eTree} and~\ref{ex_jTree}
		\begin{align*}
			F(-j) = e_{\m 3},\quad F(-e) = e_{\m 1},\quad F(e)=e_1,\quad F(j) = e_3.
		\end{align*}
	\end{ex}

