	\begin{lem}\label{lem_UinImF}
		For every $ h\in U $, there exists a surface of revolution $ i_h\in \Imm_{<3}(\S^2,\R^3) $ with $ F(i_h)=h $.
	\end{lem}
	\begin{proof}
		Let us first describe a special connected sum for two surfaces of revolution whose oriented normal at the poles points into the unbounded component of $ \R^3\setminus f(\S^2) $. Consider the generating curves for the two surfaces and replace neighborhoods of the south pole of the first and the north pole of the second, by a joining neck (see Figure~\ref{fig_FSORGlue}).
		\begin{figure}[H]
			\centering
			\begin{tikzpicture}
				\def\dd{0.04*\textwidth};

				\node[anchor=south] at (-0.25*\dd,0) {		\includegraphics[width=0.6\textwidth]{SORglue}};

