		\end{figure}
		Let $ f  \#  g $ describe this connected sum. Then the double point tree of $ f \# g $ is just both double point trees of $ f $ and $ g $ glued together along extremal vertices (representing one of the poles) of topological degree $ \delta=1 $. Therefore, we have
		\begin{equation}\label{eq_FSORGlue}
			F(f \#  g) = F(f) + F(g) - e_1.
		\end{equation}
		Let $ h\in U $. Since $ h $ has finitely many nonzero entries whose sum is equal to one, there exists $ n:=\sum\limits_{k\in\Z} \max\{0,h_k\}$ and functions $ a:\{1,\dots,n\}\to\Z,\ b:\{1,\dots,n-1\}\to\Z $ with
		$$ h=\sum_{l=1}^{n} e_{a(l)} -  \sum_{l=1}^{n-1} e_{b(l)}. $$
		We then construct a surface of revolution from gluing together the surfaces $ f_k $ and $ g_k $ from Examples~\ref{ex_Fek} and~\ref{ex_F2e1-ek}. We construct the connected sum
		\begin{align*}
			i_h:=f_{a(1)}  \#  g_{b(1)}  \#  f_{a(2)}  \#  g_{b(2)}  \#  \dots  \#  f_{a(n-1)}  \#  g_{b(n-1)}  \#  f_{a(n)}.
		\end{align*}
		We obtain with \eqref{eq_FSORGlue}
		\begin{align*}
			F(i_h) &= \sum_{l=1}^{n} F(f_{a(l)}) +  \sum_{l=1}^{n-1} F(g_{b(l)}) -(2n-2)e_1\\
			&= \sum_{l=1}^{n} e_{a(l)} -  \sum_{l=1}^{n-1} e_{b(l)} = h. \qedhere
		\end{align*}
	\end{proof}
	\begin{proof}[Proof of Theorem~\ref{thm_imageF}]
		Together with Lemma~\ref{lem_UinImF}, it remains to show $ \im(F)\subseteq U $. 
		Let $ f\in \Imm_{<3}(\S^2,\R^3) $ and $ h:=F(f) $. By Lemma~\ref{lem_delta-f}~\ref{lem_delta-f_odd}, we have $ h_{2k}=0 $ for all $ k\in\Z $. Furthermore, $ f $ has only finitely many double point curves, hence $ G_f $ is a finite tree and thus $ \sum_{k\in\Z} |h_k|<\infty $. The last condition
		$$ 1 = \sum_{k\in\Z} h_k = \sum_{v\in V_f} (1-\deg^-(v)) $$ 
		is satisfied by every directed tree since 
		\begin{equation*}
			\sum_{v\in V_f} (1-\deg(v)^-) = |V_f| - \sum_{v\in V_f} \deg(v)^- = |V_f|-|E_f| = 1. \qedhere
		\end{equation*}
	\end{proof}

