\section{Multipartite causal correlations: equivalence between the different definitions}
\label{app:def_causal_correl}


\subsection{Abbott \emph{et al.}'s definition}

In Ref.~\cite{Abbott16} Abbott \emph{et al.}~proposed the following recursive definition for causal correlations:
an $N$-partite probability distribution $p(\vec a|\vec x)$ is causal if and only if $N=1$, or it has a decomposition as
\begin{align}
    p(\vec a|\vec x) = \sum_{k_1} q_{k_1} \, p_{k_1}(a_{k_1}|x_{k_1}) \, p_{\mathcal{N}\backslash k_1,x_{k_1},a_{k_1}}(\vec a_{\mathcal{N}\backslash k_1}|\vec x_{\mathcal{N}\backslash k_1}), 
        \label{eq:def_causal_p_recursive}
\end{align}
with $q_{k_1}\ge 0$, $\sum_{k_1}q_{k_1}=1$, where for each $k_1\in\mathcal{N}$, $p_{k_1}(a_{k_1}|x_{k_1})$ is a probability distribution for the single party $A_{k_1}$, and where for each $k_1,x_{k_1},a_{k_1}$, $p_{\mathcal{N}\backslash k_1,x_{k_1},a_{k_1}}(\vec a_{\mathcal{N}\backslash k_1}|\vec x_{\mathcal{N}\backslash k_1})$ is a conditional probability distribution for the remaining $N-1$ parties in $\mathcal{N}\backslash k_1$, which is itself causal (according to the present definition).

\bigskip

Our definition in Eq.~\eqref{eq:def_causal_p} can be seen as an ``unravelling'' of this definition. Let us indeed prove by induction that the two are equivalent.
This is clearly the case for $N=1$ (they are both trivial); let us then assume they are equivalent for $N-1 \ (\ge 1)$:

\begin{itemize}

    \item \underline{Proof that \eqref{eq:def_causal_p_recursive} $\Rightarrow$ \eqref{eq:def_causal_p}:} Assume Eq.~\eqref{eq:def_causal_p_recursive}. Since $p_{\mathcal{N}\backslash k_1,x_{k_1},a_{k_1}}(\vec a_{\mathcal{N}\backslash k_1}|\vec x_{\mathcal{N}\backslash k_1})$ is required to be an $(N-1)$-partite causal distribution according to Abbott \emph{et al.}'s definition, then by the induction hypothesis, it is also causal according to our definition in the main text, i.e., it has a decomposition of the form of Eq.~\eqref{eq:def_causal_p}, with permutations $\pi'=(k_2,\ldots,k_N)$ of $\mathcal{N}\backslash k_1$:
    \begin{align}
        & p_{\mathcal{N}\backslash k_1,x_{k_1},a_{k_1}}(\vec a_{\mathcal{N}\backslash k_1}|\vec x_{\mathcal{N}\backslash k_1}) = \sum_{\pi'=(k_2,\ldots,k_N)} p_{\mathcal{N}\backslash k_1,x_{k_1},a_{k_1}}\big(\pi'=(k_2,\ldots,k_N),\vec a_{\mathcal{N}\backslash k_1}\big|\vec x_{\mathcal{N}\backslash k_1}\big) \notag \\
        & \text{s.t.} \ \forall\, n = 1,\ldots,N-1, \ \forall\, (k_2,\ldots,k_n,k_{n+1}), \notag \\
        & \hspace{5mm} p_{\mathcal{N}\backslash k_1,x_{k_1},a_{k_1}}\big((k_2,\ldots,k_n,k_{n+1}),\vec a_{k_2,\ldots,k_n}\big|\vec x_{\mathcal{N}\backslash k_1}\big) \text{ does not depend on } \vec x_{\mathcal{N}\backslash k_1\backslash\{k_2,\ldots,k_n\}}.  \label{eq:def_rec_proof2}
    \end{align}
    Defining $p\big((k_1,\ldots,k_N),\vec a\big|\vec x\big) \coloneqq q_{k_1} \, p_{k_1}(a_{k_1}|x_{k_1}) \, p_{\mathcal{N}\backslash k_1,x_{k_1},a_{k_1}}\big((k_2,\ldots,k_N),\vec a_{\mathcal{N}\backslash k_1}\big|\vec x_{\mathcal{N}\backslash k_1}\big)$, the combination of Eq.~\eqref{eq:def_causal_p_recursive} with Eq.~\eqref{eq:def_rec_proof2} then readily provides the decomposition
    \begin{align}
        p(\vec a|\vec x) & = \sum_{k_1} q_{k_1} \, p_{k_1}(a_{k_1}|x_{k_1}) \, \sum_{\pi'=(k_2,\ldots,k_N)} p_{\mathcal{N}\backslash k_1,x_{k_1},a_{k_1}}\big(\pi'=(k_2,\ldots,k_N),\vec a_{\mathcal{N}\backslash k_1}\big|\vec x_{\mathcal{N}\backslash k_1}\big), \notag \\
        & = \sum_{\pi=(k_1,\ldots,k_N)} p\big(\pi=(k_1,\ldots,k_N),\vec a|\vec x\big),
    \end{align}
    in terms of a valid probability distribution $p\big(\pi,\vec a|\vec x\big)$ which can be shown to satisfy Eq.~\eqref{eq:def_causal_p}: indeed, for any $n = 1,\ldots,N-1$ and any $(k_1,\ldots,k_n,k_{n+1})$, 
    \begin{align}
        p\big((k_1,\ldots,k_n,k_{n+1}),\vec a_{k_1,\ldots,k_n}\big|\vec x\big) = q_{k_1} \, p_{k_1}(a_{k_1}|x_{k_1}) \, p_{\mathcal{N}\backslash k_1,x_{k_1},a_{k_1}}\big((k_2,\ldots,k_n,k_{n+1}),\vec a_{k_2,\ldots,k_n}\big|\vec x_{\mathcal{N}\backslash k_1}\big)
    \end{align}
    does not, according to Eq.~\eqref{eq:def_rec_proof2} above, depend on $\vec x_{\mathcal{N}\backslash\{k_1,\ldots,k_n\}}$; while for $n = 0$ and any $k_1$, $p\big((k_1)\big|\vec x\big) =q_{k_1}$ does not depend on $\vec x$.

    \item \underline{Proof that \eqref{eq:def_causal_p} $\Rightarrow$ \eqref{eq:def_causal_p_recursive}:} Assume Eq.~\eqref{eq:def_causal_p}. The probability distribution $p(\pi,\vec a|\vec x)$ in the decomposition of $p(\vec a|\vec x)$ satisfies in particular, for $n=0$ and $n=1$, that for any $k_1$, $p\big((k_1)\big|\vec x\big) = p\big((k_1)\big)$ is independent of $\vec x$, and $p\big((k_1),a_{k_1}\big|\vec x\big) = p\big((k_1),a_{k_1}\big|x_{k_1}\big)$ only depends on $x_{k_1}$, and not on all the other inputs.
    Defining%
    \footnote{We assume for simplicity, in these definitions, that the denominators $q_{k_1}$ and $p\big((k_1),a_{k_1}\big|x_{k_1}\big)$ are nonzero. The terms for which these are zero do not contribute to the argument; some (irrelevant) values can always be given to $p_{k_1}(a_{k_1}|x_{k_1})$ and $p_{\mathcal{N}\backslash k_1,x_{k_1},a_{k_1}}(\vec a_{\mathcal{N}\backslash k_1}|\vec x_{\mathcal{N}\backslash k_1})$ in those cases, to make these valid and causal distributions. \label{ftn:nul_denom}}
    \begin{align}
        & q_{k_1}\coloneqq p\big((k_1)\big), \quad p_{k_1}(a_{k_1}|x_{k_1})\coloneqq p\big((k_1),a_{k_1}\big|x_{k_1}\big) \big/ q_{k_1}, \notag \\[1mm]
        & p_{\mathcal{N}\backslash k_1,x_{k_1},a_{k_1}}\big((k_2,\ldots,k_N),\vec a_{\mathcal{N}\backslash k_1}\big|\vec x_{\mathcal{N}\backslash k_1}\big)\coloneqq p\big((k_1,k_2,\ldots,k_N),\vec a\big|\vec x\big) \big/ p\big((k_1),a_{k_1}\big|x_{k_1}\big) \notag \\[1mm]
        \text{and} \quad & p_{\mathcal{N}\backslash k_1,x_{k_1},a_{k_1}}(\vec a_{\mathcal{N}\backslash k_1}|\vec x_{\mathcal{N}\backslash k_1})\coloneqq \sum_{(k_2,\ldots,k_N)} p_{\mathcal{N}\backslash k_1,x_{k_1},a_{k_1}}\big((k_2,\ldots,k_N),\vec a_{\mathcal{N}\backslash k_1}\big|\vec x_{\mathcal{N}\backslash k_1}\big), \label{eq:def_rec_proof1}
    \end{align}
    the decomposition of Eq.~\eqref{eq:def_causal_p} can then be written in exactly the same form as in Eq.~\eqref{eq:def_causal_p_recursive}.

    Clearly $q_{k_1}\ge 0$, $\sum_{k_1}q_{k_1}=1$, and $p_{k_1}(a_{k_1}|x_{k_1})$ is a valid (nonnegative and normalised) probability distribution. It remains to verify that $p_{\mathcal{N}\backslash k_1,x_{k_1},a_{k_1}}(\vec a_{\mathcal{N}\backslash k_1}|\vec x_{\mathcal{N}\backslash k_1})$ is a causal $(N-1)$-partite probability distribution (according to Abbott \emph{et al.}'s definition).

    To see this, notice that the last line in Eq.~\eqref{eq:def_rec_proof1} above gives precisely a decomposition of $p_{\mathcal{N}\backslash k_1,x_{k_1},a_{k_1}}(\vec a_{\mathcal{N}\backslash k_1}|\vec x_{\mathcal{N}\backslash k_1})$ of the form of Eq.~\eqref{eq:def_causal_p} for $(N-1)$-partite distributions, with a sum over all permutations $\pi'=(k_2,\ldots,k_n)$ of $\mathcal{N}'\coloneqq\mathcal{N}\backslash k_1$. Consider some $n\in \{1,\ldots,N-1\}$ and some subsequence $(k_2,\ldots,k_{n+1})$ of $\mathcal{N}'$. One then has
    \begin{align}
        p_{\mathcal{N}\backslash k_1,x_{k_1},a_{k_1}}\big((k_2,\ldots,k_n,k_{n+1}),\vec a_{k_2,\ldots,k_n}\big|\vec x_{\mathcal{N}'}\big) = p\big((k_1,k_2,\ldots,k_n,k_{n+1}),\vec a_{k_1,k_2,\ldots,k_n}\big|\vec x\big) \big/ p\big((k_1),a_{k_1}\big|x_{k_1}\big).
    \end{align}
    According to Eq.~\eqref{eq:def_causal_p}, which we assumed for $p(\vec a|\vec x)$, the numerator in the right-hand-side above does not depend on $\vec x_{\mathcal{N}\backslash\{k_1,k_2,\ldots,k_n\}}$ (and neither does the denominator). Hence, the left-hand-side does not depend on $\vec x_{\mathcal{N}\backslash\{k_1,k_2,\ldots,k_n\}} = \vec x_{\mathcal{N}'\backslash\{k_2,\ldots,k_n\}}$, so that $p_{\mathcal{N}\backslash k_1,x_{k_1},a_{k_1}}(\vec a_{\mathcal{N}\backslash k_1}|\vec x_{\mathcal{N}\backslash k_1})$ satisfies the constraint of Eq.~\eqref{eq:def_causal_p} for $(N-1)$-partite distributions. It is thus causal according to that definition, and therefore, by our induction hypothesis, it is causal according to Abbott \emph{et al.}'s definition, as required.

\end{itemize}


\subsection{Oreshkov and Giarmatzi's definition}

The first general definition for multipartite causal correlations that appeared in the literature was in fact proposed earlier by Oreshkov and Giarmatzi~\cite{Oreshkov16}. It says that causal correlations are those compatible with a causal structure described as a Strict Partial Order (SPO), rather than a full permutation as in our definition of Eq.~\eqref{eq:def_causal_p}.

\medskip

More specifically: an SPO between $N$ parties $A_i$ ($i\in \mathcal{N} \coloneqq \{1,\ldots,N\}$) is a binary relation $\prec$ which is irreflexive, transitive and antisymmetric. An SPO can in general be defined by the (consistent\footnote{Some consistency constraints are implied by the irreflexivity, transitivity and antisymmetry of the SPO. E.g., the pairwise relations $A_1 \prec A_2$, $A_2 \prec A_3$, $A_3 \prec A_1$ would be inconsistent.}) list of all pairwise relations for all $i \neq j$:%
\footnote{When writing such pairwise relations between $A_i$ and $A_j$, we will always assume $i \neq j$, without necessarily specifying it explicitly.}
either $A_i \prec A_j$ (understood as $A_i$ being in the causal past of $A_j$), $A_j \prec A_i$ ($A_j$ being in the causal past of $A_i$), or $A_i \nprec\nsucc A_j$ (neither party being in the causal past of the other one). We shall generically denote by $\kappa = \kappa(\mathcal{N})$ an SPO for the parties in $\mathcal{N}$. Note that any such SPO $\kappa(\mathcal{N})$ induces an SPO $\kappa(\mathcal{K})$ on any subset $\mathcal{K}$ of $\mathcal{N}$.

Rephrasing it slightly, Oreshkov and Giarmatzi's definition (Definition~2.3 in~\cite{Oreshkov16}) states that a correlation $p(\vec a|\vec x)$ is causal if and only if
\begin{align}
    \exists\, p(\kappa,\vec a|\vec x) \text{ s.t. } & p(\vec a|\vec x) = \sum_\kappa p(\kappa,\vec a|\vec x) \notag \\[-1mm]
    & \text{and} \ \forall\, \mathcal{K} \subsetneq \mathcal{N}, \ \forall\, \ell \in \mathcal{N}\backslash \mathcal{K}, \ \forall\, \bar{\kappa}=\bar{\kappa}(\mathcal{K}\cup\{\ell\}) \text{ for which } A_\ell\stackrel{\forall}{\nprec}\mathcal{K}, \notag \\[1mm]
    & \hspace{40mm} p\big(\bar{\kappa}(\mathcal{K}\cup\{\ell\}),\vec a_{\mathcal{K}}\big|\vec x\big) \text{ does not depend on } x_\ell,
    \label{eq:def_causal_p_OG}
\end{align}
where $p(\kappa,\vec a|\vec x)$ is a probability distribution (so that $p(\kappa,\vec a|\vec x)\ge 0$, $\sum_{\kappa,\vec a} p(\kappa,\vec a|\vec x)=1$) in which the random variable $\kappa = \kappa(\mathcal{N})$ takes values in all possible SPOs on $\mathcal{N}$, where the shorthand notation $A_\ell\stackrel{\forall}{\nprec}\mathcal{K}$ means $A_\ell \nprec A_k$ (i.e., $A_k \prec A_\ell$ or $A_k \nprec\nsucc A_\ell$) for all $k\in\mathcal{K}$, and where the last line involves the marginal distributions $p\big(\bar{\kappa}(\mathcal{K}\cup\{\ell\}),\vec a_{\mathcal{K}}\big|\vec x\big)$ obtained from $p(\kappa,\vec a_{\mathcal{K}}|\vec x)$ ($=\sum_{\vec a_{\mathcal{N}\backslash\mathcal{K}}}p(\kappa,\vec a_{\mathcal{K}},\vec a_{\mathcal{N}\backslash\mathcal{K}}|\vec x)$) by summing over all SPOs $\kappa=\kappa(\mathcal{N})$ which induce the SPO $\bar{\kappa}(\mathcal{K}\cup\{\ell\})$ on the subset $\mathcal{K}\cup\{\ell\}$: that is, $p\big(\bar{\kappa}(\mathcal{K}\cup\{\ell\}),\vec a_{\mathcal{K}}\big|\vec x\big) \coloneqq \sum_{\kappa(\mathcal{N})\text{ s.t. }\kappa(\mathcal{K}\cup\{\ell\}) = \bar{\kappa}(\mathcal{K}\cup\{\ell\})} p\big(\kappa(\mathcal{N}),\vec a_{\mathcal{K}}\big|\vec x\big)$.

\bigskip

That this definition is equivalent to that of Abbott \emph{et al.}, Eq.~\eqref{eq:def_causal_p_recursive} above, was in fact already proven by Oreshkov and Giarmatzi in~\cite{Oreshkov16}. 
Let us for convenience propose here a new version of this proof.

\begin{itemize}

    \item \underline{Proof that \eqref{eq:def_causal_p_recursive} $\Rightarrow$ \eqref{eq:def_causal_p_OG} [or \eqref{eq:def_causal_p} $\Rightarrow$ \eqref{eq:def_causal_p_OG}]:} Assume Eq.~\eqref{eq:def_causal_p_recursive}. We have just shown in the previous subsection that this is equivalent to assuming that $p(\vec a|\vec x)$ has a decomposition as in Eq.~\eqref{eq:def_causal_p}.
    Now, clearly a total order defined by some permutation $\pi$ is a particular case of an SPO $\kappa$, defined by the pairwise relations $A_i \prec A_j$ iff $i$ comes before $j$ in $\pi$ (for all $i\neq j$). Hence, the decomposition $p(\vec a|\vec x) = \sum_\pi p(\pi,\vec a|\vec x)$ is of the form $p(\vec a|\vec x) = \sum_\kappa p(\kappa,\vec a|\vec x)$, with $p(\kappa,\vec a|\vec x) = 0$ as soon as $\kappa$ contains a pairwise relation of the form $A_i \nprec\nsucc A_j$. It then remains to prove that the second and third lines of Eq.~\eqref{eq:def_causal_p_OG} are indeed satisfied.

    Consider $\mathcal{K} \subsetneq \mathcal{N}$, $\ell \in \mathcal{N}\backslash \mathcal{K}$, and some SPO $\bar{\kappa}=\bar{\kappa}(\mathcal{K}\cup\{\ell\})$ for which $A_\ell\stackrel{\forall}{\nprec}\mathcal{K}$. If $\bar{\kappa}$ contains any relation of the form $A_i \nprec\nsucc A_j$, then so does any SPO $\kappa(\mathcal{N})$ that induces $\bar{\kappa}(\mathcal{K}\cup\{\ell\})$ on the subset $\mathcal{K}\cup\{\ell\}$, and hence $p\big(\bar{\kappa}(\mathcal{K}\cup\{\ell\}),\vec a_{\mathcal{K}}\big|\vec x\big) = 0$, so that the last line of Eq.~\eqref{eq:def_causal_p_OG} is trivially satisfied. Otherwise, if $\bar{\kappa}$ contains no relation of the form $A_i \nprec\nsucc A_j$, then it can be equivalently described as a permutation $(k_1,\ldots,k_n,\ell)$ of $\mathcal{K}\cup\{\ell\}$ (where $n$ is the cardinality of $\mathcal{K}$, and noting that $A_\ell\stackrel{\forall}{\nprec}\mathcal{K}$ implies that $\ell$ must necessarily come last). The SPOs $\kappa=\kappa(\mathcal{N})$ that contribute to the decomposition $p(\vec a|\vec x) = \sum_\kappa p(\kappa,\vec a|\vec x)$ and that induce $\bar{\kappa}\equiv(k_1,\ldots,k_n,\ell)$ on the subset $\mathcal{K}\cup\{\ell\}$ are then the permutations $\pi$ of $\mathcal{N}$ that contain $(k_1,\ldots,k_n,\ell)$ as a subsequence---which we write $\pi \supset (k_1,\ldots,k_n,\ell)$---so that
    \begin{align}
        & p\big(\bar{\kappa}(\mathcal{K}\cup\{\ell\}),\vec a_{\mathcal{K}}\big|\vec x\big) = \sum_{\pi \supset (k_1,\ldots,k_n,\ell)} p(\pi,\vec a_{\mathcal{K}}|\vec x) \notag \\
        & \qquad = \hspace{-3mm}\sum_{\substack{(i_1,\ldots,i_m,\ell)\\ \quad\supset (k_1,\ldots,k_n,\ell)}} \hspace{-2mm} p\big((i_1,\ldots,i_m,\ell),\vec a_{\mathcal{K}}\big|\vec x\big) \ = \hspace{-2mm} \sum_{\substack{(i_1,\ldots,i_m,\ell)\\ \quad\supset (k_1,\ldots,k_n,\ell)}} \sum_{\substack{a_i:\\ \forall\,i\in\{i_1,\ldots,i_m\}\backslash\mathcal{K}}} p\big((i_1,\ldots,i_m,\ell),\vec a_{i_1,\ldots,i_m}\big|\vec x\big),
    \end{align}
    where the second sum above is over all supersequences $(i_1,\ldots,i_m,\ell)$ of $(k_1,\ldots,k_n,\ell)$ (with $n\le m<N$), and the last sum is over the outcomes $a_i$ of all parties with indices $i\in\{i_1,\ldots,i_m\}$ that were not already in $\mathcal{K}$.
    The assumption of Eq.~\eqref{eq:def_causal_p} implies that each probability in the last sums above do not depend on $x_\ell$, which implies that $p\big(\bar{\kappa}(\mathcal{K}\cup\{\ell\}),\vec a_{\mathcal{K}}\big|\vec x\big)$ itself does not depend on $x_\ell$---which indeed means that the last line of Eq.~\eqref{eq:def_causal_p_OG} is satisfied.


    \item \underline{Proof that \eqref{eq:def_causal_p_OG} $\Rightarrow$ \eqref{eq:def_causal_p_recursive}:}
    We prove this by induction on $N$. This clearly holds for $N=1$ (both conditions are trivial); let us then assume that Eq.~\eqref{eq:def_causal_p_OG} implies Eq.~\eqref{eq:def_causal_p_recursive} for $(N-1)$-partite distributions (with $N-1\geq 1$), and consider an $N$-partite distribution $p(\vec a|\vec x)$ that admits a decomposition $p(\vec a|\vec x) = \sum_\kappa p(\kappa,\vec a|\vec x)$ satisfying Eq.~\eqref{eq:def_causal_p_OG}.

    The first task, for each SPO $\kappa$ that appears in the decomposition, is to identify which party $A_{k_1}$ can be ``taken to come first'', so as to provide a decomposition as in Eq.~\eqref{eq:def_causal_p_recursive}. For this let us denote, for any given $\kappa = \kappa(\mathcal{N})$, by $\mathcal{S}_\kappa^\textsc{I}$ the (nonempty) set of parties that have no other party in their causal past---the ``first consecutive set'' according to the terminology of Ref.~\cite{Oreshkov16}.
    We will first show that the independence condition of Eq.~\eqref{eq:def_causal_p_OG} also holds when one further restricts the probabilities to SPOs with a given first consecutive set $\mathcal{S}$, i.e.:%
    \footnote{Here we adopt the notation that, for a given property $[\cdot]$ that a SPO may or may not satisfy, we write $p([\cdot],\vec a|\vec x) = \sum_{\kappa\text{ s.t.}\,[\cdot]} \,p(\kappa,\vec a|\vec x)$. E.g.\ in Eq.~\eqref{eq:lemma_proof_OG_equiv}, $p(\mathcal{S}_\kappa^\textsc{I}=\mathcal{S},\bar{\kappa}(\mathcal{K}\cup\{\ell\}),\vec a_{\mathcal{K}}|\vec x) = \sum_{\kappa\text{ s.t.}\,\mathcal{S}_\kappa^\textsc{I}=\mathcal{S}, \kappa(\mathcal{K}\cup\{\ell\})=\bar{\kappa}(\mathcal{K}\cup\{\ell\})} \,p(\kappa,\vec a_{\mathcal{K}}|\vec x)$. \\
    In the proof that follows, the notation $\mathcal{S}\stackrel{\exists}{\prec} A_j$ means that $\exists\,i\in\mathcal{S}$, $A_i\prec A_j$; the notation $\mathcal{S}\stackrel{\forall}{\nprec} A_j$ means that $\forall\,i\in\mathcal{S}$, $A_i\nprec A_j$.}
    \begin{align}
        & \forall\, \mathcal{S} \subseteq \mathcal{N}, \ \forall\, \mathcal{K} \subsetneq \mathcal{N}, \ \forall\, \ell \in \mathcal{N}\backslash \mathcal{K}, \ \forall\, \bar{\kappa}=\bar{\kappa}(\mathcal{K}\cup\{\ell\}) \text{ for which } A_\ell\stackrel{\forall}{\nprec}\mathcal{K}, \notag \\
        & \hspace{40mm} p\big(\mathcal{S}_\kappa^\textsc{I}=\mathcal{S},\bar{\kappa}(\mathcal{K}\cup\{\ell\}),\vec a_{\mathcal{K}}\big|\vec x\big) \text{ does not depend on } x_\ell. \label{eq:lemma_proof_OG_equiv}
    \end{align}

    \emph{Proof of Eq.~\eqref{eq:lemma_proof_OG_equiv}:}

    If $\ell\in\mathcal{S}$, then using the inclusion–exclusion principle one can write:%
    \footnote{More specifically, we use the fact that for some events $E$ and $\{F_j\}_{j\in\mathcal{I}}$ (for some finite set of indices $\mathcal{I}$), one has
    \begin{align}
        p\Big(E, \bigwedge_{j\in\mathcal{I}} F_j \Big) 
        = p\big(E\big) - p\Big(E, \bigvee_{j\in\mathcal{I}} (\neg F_j) \Big) 
        & = p\big(E\big) - p\Big(\bigvee_{j\in\mathcal{I}} (E\wedge \neg F_j) \Big) \notag \\
        & = p\big(E\big) - \sum_{\emptyset\neq \mathcal{J}\subseteq \mathcal{I}} (-1)^{|\mathcal{J}|-1}\, p\Big(\bigwedge_{j\in\mathcal{J}} (E\wedge \neg F_j) \Big) = \sum_{\mathcal{J}\subseteq \mathcal{I}} (-1)^{|\mathcal{J}|}\, p\Big(E,\bigwedge_{j\in\mathcal{J}} (\neg F_j) \Big), \notag
    \end{align}
    where the first equality on the second line is a direct application of the inclusion–exclusion principle.}
    \begin{align}
        p\big(\mathcal{S}_\kappa^\textsc{I}=\mathcal{S},\bar{\kappa}(\mathcal{K}\cup\{\ell\}),\vec a_{\mathcal{K}}\big|\vec x\big) & = p\Bigg(\bigwedge_{i,i'\in\mathcal{S}} \!\! \big(A_i\nprec\nsucc A_{i'}\big), \bigwedge_{j\in\mathcal{N}\backslash\mathcal{S}} \!\!\! \Big(\mathcal{S}\stackrel{\exists}{\prec} A_j\Big), \bar{\kappa}(\mathcal{K}\cup\{\ell\}),\vec a_{\mathcal{K}}\Bigg|\vec x\Bigg) \notag \\
        & = \sum_{\mathcal{J}\subseteq \mathcal{N}\backslash\mathcal{S}} (-1)^{|\mathcal{J}|}\ p\Bigg(\bigwedge_{i,i'\in\mathcal{S}} \!\! \big(A_i\nprec\nsucc A_{i'}\big), \bigwedge_{j\in\mathcal{J}} \Big(\mathcal{S}\stackrel{\forall}{\nprec} A_j\Big), \bar{\kappa}(\mathcal{K}\cup\{\ell\}),\vec a_{\mathcal{K}}\Bigg|\vec x\Bigg) \notag \\
        & = \sum_{\mathcal{J}\subseteq \mathcal{N}\backslash\mathcal{S}} (-1)^{|\mathcal{J}|} \sum_{\substack{\bar{\bar{\kappa}}(\mathcal{S}\cup\mathcal{J}\cup\mathcal{K})\text{ s.t. }\\[-1mm] \bigwedge_{i,i'\in\mathcal{S}} (A_i\nprec\nsucc A_{i'}), \bigwedge_{j\in\mathcal{J}} \big(\mathcal{S}\stackrel{\forall}{\nprec} A_j\big),\\ \bar{\bar{\kappa}}(\mathcal{K}\cup\{\ell\})=\bar{\kappa}(\mathcal{K}\cup\{\ell\})}} p\big(\bar{\bar{\kappa}}(\mathcal{S}\cup\mathcal{J}\cup\mathcal{K}),\vec a_{\mathcal{K}}\big|\vec x\big).
    \end{align}
    Now, recalling that $\ell\in\mathcal{S}$ here, one can see that $\bigwedge_{i,i'\in\mathcal{S}} (A_i\nprec\nsucc A_{i'})$ and $\bigwedge_{j\in\mathcal{J}} \big(\mathcal{S}\stackrel{\forall}{\nprec} A_j\big)$ imply that $A_\ell\stackrel{\forall}{\nprec}(\mathcal{S}\backslash\ell)$ and $A_\ell\stackrel{\forall}{\nprec}\mathcal{J}$, respectively. The constraint that $\bar{\bar{\kappa}}(\mathcal{K}\cup\{\ell\})=\bar{\kappa}(\mathcal{K}\cup\{\ell\})$ implies that the condition $A_\ell\stackrel{\forall}{\nprec}\mathcal{K}$, which was imposed on $\bar{\kappa}$, also holds for $\bar{\bar{\kappa}}$. Hence all the $\bar{\bar{\kappa}}$'s considered in the sum above satisfy $A_\ell\stackrel{\forall}{\nprec}(\mathcal{S}\cup\mathcal{J}\cup\mathcal{K}\backslash\ell)$.
    From Eq.~\eqref{eq:def_causal_p_OG} (with $\mathcal{K} \to \mathcal{S}\cup\mathcal{J}\cup\mathcal{K}\backslash\ell$, after marginalising over some of the outputs $a_k$) it then follows that the terms $p\big(\bar{\bar{\kappa}}(\mathcal{S}\cup\mathcal{J}\cup\mathcal{K}),\vec a_{\mathcal{K}}\big|\vec x\big)$ that appear in the sum, and therefore $p\big(\mathcal{S}_\kappa^\textsc{I}=\mathcal{S},\bar{\kappa}(\mathcal{K}\cup\{\ell\}),\vec a_{\mathcal{K}}\big|\vec x\big)$ itself, do not depend on $x_\ell$.

    \medskip

    Otherwise if $\ell\in\mathcal{N}\backslash\mathcal{S}$, then using again the inclusion–exclusion principle one can write:
    \begin{align}
        p\big(\mathcal{S}_\kappa^\textsc{I}=\mathcal{S},\bar{\kappa}(\mathcal{K}\cup\{\ell\}),\vec a_{\mathcal{K}}\big|\vec x\big) & = p\Bigg(\bigwedge_{i,i'\in\mathcal{S}} \!\! \big(A_i\nprec\nsucc A_{i'}\big), \Big(\mathcal{S}\stackrel{\exists}{\prec} A_\ell\Big), \bigwedge_{j\in\mathcal{N}\backslash\mathcal{S}\backslash\ell} \!\!\! \Big(\mathcal{S}\stackrel{\exists}{\prec} A_j\Big), \bar{\kappa}(\mathcal{K}\cup\{\ell\}),\vec a_{\mathcal{K}}\Bigg|\vec x\Bigg) \notag \\
        & = \sum_{\mathcal{J}\subseteq \mathcal{N}\backslash\mathcal{S}\backslash\ell} (-1)^{|\mathcal{J}|}\ p\Bigg(\bigwedge_{i,i'\in\mathcal{S}} \!\! \big(A_i\nprec\nsucc A_{i'}\big), \Big(\mathcal{S}\stackrel{\exists}{\prec} A_\ell\Big), \bigwedge_{j\in\mathcal{J}} \Big(\mathcal{S}\stackrel{\forall}{\nprec} A_j\Big), \bar{\kappa}(\mathcal{K}\cup\{\ell\}),\vec a_{\mathcal{K}}\Bigg|\vec x\Bigg) \notag \\
        & = \sum_{\mathcal{J}\subseteq \mathcal{N}\backslash\mathcal{S}\backslash\ell} (-1)^{|\mathcal{J}|} \hspace{-7mm} \sum_{\substack{\bar{\bar{\kappa}}(\mathcal{S}\cup\mathcal{J}\cup\mathcal{K}\cup\{\ell\})\text{ s.t. }\\ \bigwedge_{i,i'\in\mathcal{S}} (A_i\nprec\nsucc A_{i'}), \big(\mathcal{S}\stackrel{\exists}{\prec} A_\ell\big), \bigwedge_{j\in\mathcal{J}} \big(\mathcal{S}\stackrel{\forall}{\nprec} A_j\big),\\ \bar{\bar{\kappa}}(\mathcal{K}\cup\{\ell\})=\bar{\kappa}(\mathcal{K}\cup\{\ell\})}} \hspace{-7mm} p\big(\bar{\bar{\kappa}}(\mathcal{S}\cup\mathcal{J}\cup\mathcal{K}\cup\{\ell\}),\vec a_{\mathcal{K}}\big|\vec x\big).
    \end{align}
    Now, one can see that $\bigwedge_{i,i'\in\mathcal{S}} (A_i\nprec\nsucc A_{i'})$ and $\big(\mathcal{S}\stackrel{\exists}{\prec} A_\ell\big)$ together imply that $A_\ell\stackrel{\forall}{\nprec}\mathcal{S}$, and that $\big(\mathcal{S}\stackrel{\exists}{\prec} A_\ell\big)$ and $\bigwedge_{j\in\mathcal{J}} \big(\mathcal{S}\stackrel{\forall}{\nprec} A_j\big)$ together imply that $A_\ell\stackrel{\forall}{\nprec}\mathcal{J}$.
    The constraint that $\bar{\bar{\kappa}}(\mathcal{K}\cup\{\ell\})=\bar{\kappa}(\mathcal{K}\cup\{\ell\})$ again implies that the condition $A_\ell\stackrel{\forall}{\nprec}\mathcal{K}$ also holds for $\bar{\bar{\kappa}}$. Hence all the $\bar{\bar{\kappa}}$'s considered in the sum above satisfy $A_\ell\stackrel{\forall}{\nprec}(\mathcal{S}\cup\mathcal{J}\cup\mathcal{K})$.
    From Eq.~\eqref{eq:def_causal_p_OG} (with now $\mathcal{K} \to \mathcal{S}\cup\mathcal{J}\cup\mathcal{K}$, after marginalising over some of the outputs $a_k$) it then follows that the terms $p\big(\bar{\bar{\kappa}}(\mathcal{S}\cup\mathcal{J}\cup\mathcal{K}\cup\{\ell\}),\vec a_{\mathcal{K}}\big|\vec x\big)$ that appear in the sum, and therefore $p\big(\mathcal{S}_\kappa^\textsc{I}=\mathcal{S},\bar{\kappa}(\mathcal{K}\cup\{\ell\}),\vec a_{\mathcal{K}}\big|\vec x\big)$ itself, do not depend on $x_\ell$---which concludes the proof of Eq.~\eqref{eq:lemma_proof_OG_equiv}.

    \bigskip

    Now that we have this in place, let us introduce some arbitrary choice function $\underline{k}_\textsc{I}$ which, to each nonempty subset $\mathcal{S}\subseteq\mathcal{N}$, assigns one of its elements, $\underline{k}_\textsc{I}(\mathcal{S})\in\mathcal{S}$ (which will be ``taken to come first''); and for any SPO $\kappa$, let us define $\underline{k}_{\textsc{I},\kappa}\coloneqq \underline{k}_\textsc{I}(\mathcal{S}_\kappa^\textsc{I})$ (where $\mathcal{S}_\kappa^\textsc{I}$ is the ``first consecutive set'' of $\kappa$, as introduced above).

    Notice that for $\mathcal{K}=\emptyset$, Eq.~\eqref{eq:lemma_proof_OG_equiv} implies that $\forall\, \mathcal{S} \subseteq \mathcal{N}$, $p\big(\mathcal{S}_\kappa^\textsc{I}=\mathcal{S}\big|\vec x\big)$ does not depend on any $x_\ell$, i.e., it does not depend on $\vec x$ at all; and that for $\mathcal{K}=\{k_1\}\subseteq\mathcal{S}$ (so that $\mathcal{S}_\kappa^\textsc{I}=\mathcal{S}$ implies $A_\ell\nprec A_{k_1}$ for any $\ell\neq k_1$), Eq.~\eqref{eq:lemma_proof_OG_equiv} implies that $\forall\, \mathcal{S} \subseteq \mathcal{N}$, $\forall\, k_1\in\mathcal{S}$, $p\big(\mathcal{S}_\kappa^\textsc{I}=\mathcal{S},a_{k_1}\big|\vec x\big)$ does not depend on any $x_\ell$ with $\ell\neq k_1$, i.e., it only depends on $x_{k_1}$.
    It then follows that for any given $k_1\in\mathcal{N}$,
    \begin{alignat}{2}
        p\big(\underline{k}_{\textsc{I},\kappa}=k_1\big|\vec x\big) & = \sum_{\mathcal{S} \text{ s.t. } \underline{k}_\textsc{I}(\mathcal{S})= k_1} p\big(\mathcal{S}_\kappa^\textsc{I}=\mathcal{S}\big|\vec x\big) && \quad \text{ does not depend on } \vec x \notag \\
        \text{and} \quad p\big(\underline{k}_{\textsc{I},\kappa}=k_1,a_{k_1}\big|\vec x\big) & = \sum_{\mathcal{S} \text{ s.t. } \underline{k}_\textsc{I}(\mathcal{S})= k_1} p\big(\mathcal{S}_\kappa^\textsc{I}=\mathcal{S},a_{k_1}\big|\vec x\big) && \quad \text{ only depends on } x_{k_1}.
    \end{alignat}
    One can then define%
    \footnote{Again we assume for simplicity, in these definitions, that the denominators are nonzero. The terms for which these are zero do not contribute to the argument (see Footnote~\ref{ftn:nul_denom}).}
    \begin{align}
        & q_{k_1}\coloneqq p\big(\underline{k}_{\textsc{I},\kappa}=k_1\big), \quad p_{k_1}(a_{k_1}|x_{k_1})\coloneqq \frac{p\big(\underline{k}_{\textsc{I},\kappa}=k_1,a_{k_1}\big|x_{k_1}\big)}{q_{k_1}}, \notag \\[1mm]
        \text{for any SPO } \kappa'(\mathcal{N}\backslash k_1), \quad & p_{\mathcal{N}\backslash k_1,x_{k_1},a_{k_1}}(\kappa'(\mathcal{N}\backslash k_1),\vec a_{\mathcal{N}\backslash k_1}|\vec x_{\mathcal{N}\backslash k_1})\coloneqq \frac{p\big(\underline{k}_{\textsc{I},\kappa}=k_1,\kappa'(\mathcal{N}\backslash k_1),\vec a\big|\vec x\big)}{p\big(\underline{k}_{\textsc{I},\kappa}=k_1,a_{k_1}\big|x_{k_1}\big)}, \notag \\[1mm]
        \text{and} \quad & p_{\mathcal{N}\backslash k_1,x_{k_1},a_{k_1}}(\vec a_{\mathcal{N}\backslash k_1}|\vec x_{\mathcal{N}\backslash k_1})\coloneqq \sum_{\kappa'(\mathcal{N}\backslash k_1)} p_{\mathcal{N}\backslash k_1,x_{k_1},a_{k_1}}(\kappa'(\mathcal{N}\backslash k_1),\vec a_{\mathcal{N}\backslash k_1}|\vec x_{\mathcal{N}\backslash k_1}),
    \end{align}
    so that the decomposition $p(\vec a|\vec x) = \sum_\kappa p(\kappa,\vec a|\vec x)$ can be written as
    \begin{align}
        p(\vec a|\vec x) & = \sum_{k_1} p(\underline{k}_{\textsc{I},\kappa}=k_1,\vec a|\vec x) = \sum_{k_1} q_{k_1}\, p_{k_1}(a_{k_1}|x_{k_1}) \,p_{\mathcal{N}\backslash k_1,x_{k_1},a_{k_1}}(\vec a_{\mathcal{N}\backslash k_1}|\vec x_{\mathcal{N}\backslash k_1}),
    \end{align}
    i.e., in exactly the same form as in Eq.~\eqref{eq:def_causal_p_recursive}.
    Clearly $q_{k_1}\ge 0$, $\sum_{k_1}q_{k_1}=1$, and $p_{k_1}(a_{k_1}|x_{k_1})$ is a valid probability distribution. It remains to verify that each $(N-1)$-partite probability distribution $p_{\mathcal{N}\backslash k_1,x_{k_1},a_{k_1}}(\vec a_{\mathcal{N}\backslash k_1}|\vec x_{\mathcal{N}\backslash k_1})$ is causal (according to Abbott \emph{et al.}'s definition).

    To see this, consider $\mathcal{K}' \subsetneq \mathcal{N}'\coloneqq\mathcal{N}\backslash k_1$, $\ell \in \mathcal{N}'\backslash \mathcal{K}'$, and $\bar{\kappa}'=\bar{\kappa}'(\mathcal{K}'\cup\{\ell\})$ for which $A_\ell\stackrel{\forall}{\nprec}\mathcal{K}'$. Defining $\mathcal{K}\coloneqq\{k_1\}\cup\mathcal{K}'$, one has
    \begin{align}
        & p_{\mathcal{N}\backslash k_1,x_{k_1},a_{k_1}}\big(\bar{\kappa}'(\mathcal{K}'\cup\{\ell\}),\vec a_{\mathcal{K}'}\big|\vec x_{\mathcal{N}\backslash k_1}\big) \ = \ \frac{p\big(\underline{k}_{\textsc{I},\kappa}=k_1,\bar{\kappa}'(\mathcal{K}'\cup\{\ell\}),\vec a_{\mathcal{K}}\big|\vec x\big)}{p\big(\underline{k}_{\textsc{I},\kappa}=k_1,a_{k_1}\big|x_{k_1}\big)} \notag \\
        & \hspace{30mm} = \sum_{\substack{\mathcal{S} \text{ s.t. } \underline{k}_\textsc{I}(\mathcal{S})= k_1, \\ \bar{\kappa}(\mathcal{K}\cup\{\ell\}) \text{ s.t. } \bar{\kappa}(\mathcal{K}'\cup\{\ell\}) = \bar{\kappa}'(\mathcal{K}'\cup\{\ell\})}} \hspace{-5mm} p\big(\mathcal{S}_\kappa^\textsc{I}=\mathcal{S},\bar{\kappa}(\mathcal{K}\cup\{\ell\}),\vec a_{\mathcal{K}}\big|\vec x\big) \Bigg/ p\big(\underline{k}_{\textsc{I},\kappa}=k_1,a_{k_1}\big|x_{k_1}\big).
    \end{align}
    Now, $\bar{\kappa}(\mathcal{K}'\cup\{\ell\}) = \bar{\kappa}'(\mathcal{K}'\cup\{\ell\})$ implies that $\bar{\kappa}(\mathcal{K}\cup\{\ell\})$ is also such that $A_\ell\stackrel{\forall}{\nprec}\mathcal{K}'$. Furthermore, if $\mathcal{S}_\kappa^\textsc{I}=\mathcal{S}$, with $\underline{k}_\textsc{I}(\mathcal{S})= k_1$, then $k_1\in\mathcal{S}_\kappa^\textsc{I}$ and therefore $A_\ell\nprec A_{k_1}$ for all $\bar{\kappa}(\mathcal{K}\cup\{\ell\})$ that contribute to the sum. 
    All in all, these thus satisfy $A_\ell\stackrel{\forall}{\nprec}\{k_1\}\cup\mathcal{K}'=\mathcal{K}$.
    From Eq.~\eqref{eq:lemma_proof_OG_equiv} it follows that the terms $p\big(\mathcal{S}_\kappa^\textsc{I}=\mathcal{S},\bar{\kappa}(\mathcal{K}\cup\{\ell\}),\vec a_{\mathcal{K}}\big|\vec x\big)$ in the sum above do not depend on $x_\ell$; given that the same holds for the denominator $p\big(\underline{k}_{\textsc{I},\kappa}=k_1,a_{k_1}\big|x_{k_1}\big)$, we obtain that the term $p_{\mathcal{N}\backslash k_1,x_{k_1},a_{k_1}}\big(\bar{\kappa}'(\mathcal{K}'\cup\{\ell\}),\vec a_{\mathcal{K}'}\big|\vec x_{\mathcal{N}\backslash k_1}\big)$ itself does not depend on $x_\ell$, i.e., $p_{\mathcal{N}\backslash k_1,x_{k_1},a_{k_1}}(\vec a_{\mathcal{N}\backslash k_1}|\vec x_{\mathcal{N}\backslash k_1})$ satisfies Eq.~\eqref{eq:def_causal_p_OG}. By our induction hypothesis, it also satisfies Eq.~\eqref{eq:def_causal_p_recursive}, i.e., it is causal according to Abbott \emph{et al.}'s definition---which concludes the proof that Oreshkov and Giarmatzi's definition is equivalent to that of Abbott \emph{et al.}

\end{itemize}

\medskip

By unravelling our inductive proof that \eqref{eq:def_causal_p_OG} $\Rightarrow$ \eqref{eq:def_causal_p_recursive} above, one can see that each SPO $\kappa$ gets extended to a total order (a permutation) $\pi_\kappa$ of $\mathcal{N}$ that is ``compatible'' with $\kappa$, i.e., that preserves all pairwise relations of the form $A_i\prec A_j$.
Specifically, $\pi_\kappa=(k_1,k_2,\ldots,k_N)$ is obtained inductively as follows, using the choice function $\underline{k}_\textsc{I}$: $k_1=\underline{k}_\textsc{I}(\mathcal{S}_{\kappa(\mathcal{N})}^\textsc{I})$, $k_2=\underline{k}_\textsc{I}(\mathcal{S}_{\kappa(\mathcal{N}\backslash\{k_1\})}^\textsc{I})$, $k_3=\underline{k}_\textsc{I}(\mathcal{S}_{\kappa(\mathcal{N}\backslash\{k_1,k2\})}^\textsc{I})$, etc. It can be seen that the decomposition $p(\vec a|\vec x) = \sum_\kappa p(\kappa,\vec a|\vec x)$ thus provides a new decomposition
\begin{align}
    p(\vec a|\vec x) = \sum_\kappa p(\kappa,\vec a|\vec x) = \sum_\pi \sum_{\kappa\text{ s.t. }\pi_\kappa=\pi} p(\kappa,\vec a|\vec x) = \sum_\pi p(\pi,\vec a|\vec x), \label{eq:decomp_extend_SPO}
\end{align}
with $p(\pi,\vec a|\vec x)\coloneqq \sum_{\kappa\text{ s.t. }\pi_\kappa=\pi} p(\kappa,\vec a|\vec x)$ satisfying Eq.~\eqref{eq:def_causal_p} (as it follows from the proof that \eqref{eq:def_causal_p_recursive} $\Rightarrow$ \eqref{eq:def_causal_p} in the previous subsection).

Note that compatible extensions of a given SPO to a total order are in general not unique. 
For the proof above to work, one could however not just take any arbitrary extension, independently for each SPO $\kappa$. Indeed it was important that the choice of the ``first party'' (when $\mathcal{S}_\kappa^\textsc{I}$ was not a singleton) only depended on the set $\mathcal{S}_\kappa^\textsc{I}$, rather than on $\kappa$ directly---i.e., for two SPOs $\kappa,\kappa'$ with the same first consecutive set $\mathcal{S}_\kappa^\textsc{I}=\mathcal{S}_{\kappa'}^\textsc{I}$, the (otherwise arbitrary) choice of the first party $\underline{k}_{\textsc{I},\kappa^{(\prime)}}$ must be the same. (That choice could also be probabilistic, but with probabilities that do not depend on the settings $\vec x$.) Otherwise one can construct counterexamples, for which extending each SPO independently to a total order leads to a decomposition $p(\vec a|\vec x) = \sum_\pi p(\pi,\vec a|\vec x)$ as in Eq.~\eqref{eq:decomp_extend_SPO} that does not satisfy Eq.~\eqref{eq:def_causal_p}.%
\footnote{For an explicit such counterexample: consider for instance 3 parties $A,B,C$ with the two SPOs $\kappa_0 = (A\nprec\nsucc B,A\prec C,B\nprec\nsucc C)$ and $\kappa_1 = (A\nprec\nsucc B,A\prec C,B\prec C)$, which both have the same first consecutive set $\mathcal{S}_{\kappa_0}^\textsc{I}=\mathcal{S}_{\kappa_1}^\textsc{I}=\{A,B\}$, and the distribution (with no output for any party and only an input $x=0,1$ for $A$) $p(\kappa|x)=\delta_{\kappa,\kappa_x}$, which satisfies Eq.~\eqref{eq:def_causal_p_OG}. 
If one were to extend $\kappa_0$ to $\pi_{\kappa_0} = (A,B,C)$ and $\kappa_1$ to $\pi_{\kappa_1} = (B,A,C)$, i.e.\ with different choices for the first party, then this would result in $p(\pi|x)=\left\{\begin{array}{ll}
    \delta_{\pi,(A,B,C)} & \text{if}\ x=0 \\
    \delta_{\pi,(B,A,C)} & \text{if}\ x=1
\end{array}\right.$, which does not satisfy Eq.~\eqref{eq:def_causal_p} (as for instance $p((k_1)=(A)|x) = \delta_{x,0}$ then depends on $x$).}


\subsection{Two more equivalent characterisations of causal correlations}
\label{app:more_causal_charact}

Here we provide two additional equivalent characterisations of multipartite causal correlations. The first one is that a correlation $p(\vec a|\vec x)$ is causal if and only if it can be decomposed in terms of (well-defined, normalised) probability distributions $\tilde{p}\big((k_n),a_{k_n}\big|(k_1,\ldots,k_{n-1}),\vec x_{k_1,\ldots,k_n},\vec a_{k_1,\ldots,k_{n-1}}\big)$ as
\begin{align}
    & p(\vec a|\vec x) = \sum_\pi p(\pi,\vec a|\vec x) \notag \\[-4mm]
    & \hspace{10mm} \text{with} \quad p\big(\pi=(k_1,\ldots,k_N),\vec a\big|\vec x\big) = \prod_{n=1}^N \tilde{p}\big((k_n),a_{k_n}\big|(k_1,\ldots,k_{n-1}),\vec x_{k_1,\ldots,k_n},\vec a_{k_1,\ldots,k_{n-1}}\big), \notag  \\
    & \hspace{20mm} \text{s.t. } \forall\,n, \ \sum_{a_{k_n}} \tilde{p}\big((k_n),a_{k_n}\big|(k_1,\ldots,k_{n-1}),\vec x_{k_1,\ldots,k_n},\vec a_{k_1,\ldots,k_{n-1}}\big) \text{ does not depend on } x_{k_n}. \label{eq:def_causal_p_v4}
\end{align}

\medskip

The last characterisation we provide is that a correlation $p(\vec a|\vec x)$ is causal if and only if it can be decomposed in terms of (well-defined, normalised) probability distributions $\hat{p}\big((k_{n+1}),a_{k_n}\big|(k_1,\ldots,k_n),\vec x_{k_1,\ldots,k_n},\vec a_{k_1,\ldots,k_{n-1}}\big)$---which reduce to just $\hat{p}\big((k_1)\big)$ for $n=0$ and to $\hat{p}\big(a_{k_N}\big|(k_1,\ldots,k_N),\vec x,\vec a_{\N\backslash k_N}\big)$ for $n=N$---as
\begin{align}
    & p(\vec a|\vec x) = \sum_\pi p(\pi,\vec a|\vec x) \notag \\[-4mm]
    & \hspace{10mm} \text{with} \quad p\big(\pi=(k_1,\ldots,k_N),\vec a\big|\vec x\big) = \prod_{n=0}^N \hat{p}\big((k_{n+1}),a_{k_n}\big|(k_1,\ldots,k_n),\vec x_{k_1,\ldots,k_n},\vec a_{k_1,\ldots,k_{n-1}}\big). \label{eq:def_causal_p_v5}
\end{align}

\bigskip

Each term $\tilde{p}\big((k_n),a_{k_n}\big|(k_1,\ldots,k_{n-1}),\vec x_{k_1,\ldots,k_n},\vec a_{k_1,\ldots,k_{n-1}}\big)$ in Eq.~\eqref{eq:def_causal_p_v4} corresponds to the probability for the ``next'' ($n^\text{th}$) party to be $A_{k_n}$ and to output $a_{k_n}$, given that the previous parties were (in that order) those labelled $(k_1,\ldots,k_{n-1})$, given all previous parties' as well as $A_{k_n}$'s inputs $\vec x_{k_1,\ldots,k_n}$, and given all previous parties' outputs $\vec a_{k_1,\ldots,k_{n-1}}$. Somewhat analogously, each term $\hat{p}\big((k_{n+1}),a_{k_n}\big|(k_1,\ldots,k_n),\vec x_{k_1,\ldots,k_n},\vec a_{k_1,\ldots,k_{n-1}}\big)$ in Eq.~\eqref{eq:def_causal_p_v5} corresponds to the probability that party $A_{k_n}$ outputs $a_{k_n}$ and that the next ($(n+1)^\text{th}$) party will be $A_{k_{n+1}}$, given that the order of the parties so far was $(k_1,\ldots,k_n)$, given all of those parties' inputs $\vec x_{k_1,\ldots,k_n}$, and given all previous parties' outputs $\vec a_{k_1,\ldots,k_{n-1}}$.
Both decompositions thus translate---in two slightly different manners---the idea that the causal order can be established step by step, with each of the parties' outputs and the choice of the ``next'' party depending on all previous available information (the order of the previous parties, all inputs so far, and all previous outputs).

As we will see, the characterisation of Eq.~\eqref{eq:def_causal_p_v4} will be useful in particular in our proofs that QC-QCs only generate causal correlations, and reciprocally that any causal correlation can be obtained from a QC-QC; see Appendices~\ref{app:corr_QC-QC} and~\ref{app:obtaining_any_causal_correl}.

\medskip

\begin{itemize}

    \item \underline{Proof that \eqref{eq:def_causal_p_v4} $\Rightarrow$ \eqref{eq:def_causal_p}:} For a distribution $p\big(\pi=(k_1,\ldots,k_N),\vec a\big|\vec x\big)$ that factorises as in Eq.~\eqref{eq:def_causal_p_v4}, one easily obtains, recursively (from $n=N-1$ down to $n=0$), that 
    \begin{align}
        & p\big((k_1,\ldots,k_n,k_{n+1}),\vec a_{k_1,\ldots,k_n}\big|\vec x\big) \notag \\[-1mm]
        & = \Big( \prod_{j=1}^n \tilde p\big((k_j),a_{k_j}\big|(k_1,\ldots,k_{j-1}),\vec x_{k_1,\ldots,k_j},\vec a_{k_1,\ldots,k_{j-1}}\big) \Big) \, \tilde p\big((k_{n+1})\big|(k_1,\ldots,k_n),\vec x_{k_1,\ldots,k_{n+1}},\vec a_{k_1,\ldots,k_n}\big) . \label{eq:proof_causal_p_v4}
    \end{align}
    Clearly the first product within brackets does not depend on $\vec x_{\mathcal{N}\backslash\{k_1,\ldots,k_n\}}$; the last term%
    \footnote{In order to lighten the notations we sometimes write $\tilde p\big((k_{n+1}),a_{k_{n+1}}\big|\cdot,\cdot,\cdot\big)$ for $\tilde p\big((k_{n+1}),a_{k_{n+1}}\big|(k_1,\ldots,k_n),\vec x_{k_1,\ldots,k_{n+1}},\vec a_{k_1,\ldots,k_n}\big)$.}
    $\tilde p\big((k_{n+1})\big|\cdot,\cdot,\cdot\big) \coloneqq \sum_{a_{k_{n+1}}} \tilde p\big((k_{n+1}),a_{k_{n+1}}\big|\cdot,\cdot,\cdot\big)$ also clearly does not depend on $\vec x_{\mathcal{N}\backslash\{k_1,\ldots,k_{n+1}\}}$, and is further required (from Eq.~\eqref{eq:def_causal_p_v4}) not to depend on $x_{k_{n+1}}$. All in all, $p\big((k_1,\ldots,k_n,k_{n+1}),\vec a_{k_1,\ldots,k_n}\big|\vec x\big)$ does not depend on $\vec x_{\mathcal{N}\backslash\{k_1,\ldots,k_n\}}$, as required in Eq.~\eqref{eq:def_causal_p}. 

    \item \underline{Proof that \eqref{eq:def_causal_p} $\Rightarrow$ \eqref{eq:def_causal_p_v4}:} From a decomposition as in Eq.~\eqref{eq:def_causal_p}, one can define $\tilde{p}\big((k_1),a_{k_1}\big|x_{k_1}\big) \coloneqq p\big((k_1),a_{k_1}\big|\vec x\big)$ (which indeed only depends on $x_{k_1}$) and (for $n=2,\ldots,N$)%
    \footnote{We once again assume for simplicity that the denominators are nonzero; the terms for which these are zero do not contribute to the decomposition of $p(\vec a|\vec x)$.}
    $\tilde{p}\big((k_n),a_{k_n}\big|(k_1,\ldots,k_{n-1}),\vec x_{k_1,\ldots,k_n},\vec a_{k_1,\ldots,k_{n-1}}\big) \coloneqq p\big((k_1,\ldots,k_n),\vec a_{k_1,\ldots,k_n}\big|\vec x\big)/p\big((k_1,\ldots,k_{n-1}),\vec a_{k_1,\ldots,k_{n-1}}\big|\vec x\big)$ (which indeed only depends on the inputs $\vec x_{k_1,\ldots,k_n}$). It is easy to see that these are normalised probability distributions whose product gives $p\big(\pi=(k_1,\ldots,k_N),\vec a\big|\vec x\big)$ as in the second line of Eq.~\eqref{eq:def_causal_p_v4}, and such that (for each $n$) $\sum_{a_{k_n}} \tilde{p}\big((k_n),a_{k_n}\big|\cdot,\cdot,\cdot\big)$ does not depend on $x_{k_n}$.

\end{itemize}

The proofs that \eqref{eq:def_causal_p_v5} $\Rightarrow$ \eqref{eq:def_causal_p} and \eqref{eq:def_causal_p} $\Rightarrow$ \eqref{eq:def_causal_p_v5} are quite similar: from Eq.~\eqref{eq:def_causal_p_v5} one easily obtains recursively that $p\big((k_1,\ldots,k_n,k_{n+1}),\vec a_{k_1,\ldots,k_n}\big|\vec x\big) = \prod_{j=0}^n \hat{p}\big((k_{j+1}),a_{k_j}\big|(k_1,\ldots,k_j),\vec x_{k_1,\ldots,k_j},\vec a_{k_1,\ldots,k_{j-1}}\big)$, which clearly does not depend on $\vec x_{\mathcal{N}\backslash\{k_1,\ldots,k_n\}}$; from Eq.~\eqref{eq:def_causal_p}, one can define the normalised probability distributions $\hat{p}\big((k_1)\big) \coloneqq p\big((k_1)\big|\vec x\big)$ (which indeed does not depend on $\vec  x$), $\hat{p}\big((k_{n+1}),a_{k_n}\big|(k_1,\ldots,k_n),\vec x_{k_1,\ldots,k_n},\vec a_{k_1,\ldots,k_{n-1}}\big) \coloneqq p\big((k_1,\ldots,k_n,k_{n+1}),\vec a_{k_1,\ldots,k_n}\big|\vec x\big) / p\big((k_1,\ldots,k_n),\vec a_{k_1,\ldots,k_{n-1}}\big|\vec x\big)$ (which indeed only depends on the inputs $\vec x_{k_1,\ldots,k_n}$), and $\hat{p}\big(a_{k_N}\big|(k_1,\ldots,k_N),\vec x,\vec a_{\N\backslash k_N}\big) \coloneqq p\big((k_1,\ldots,k_N),\vec a\big|\vec x\big) / p\big((k_1,\ldots,k_N),\vec a_{\N\backslash k_N}\big|\vec x\big)$, whose product reproduces Eq.~\eqref{eq:def_causal_p_v5}. 



\subsection{Equivalent definitions for correlations with non-influenceable causal orders}
\label{app:subsec:equiv_def_NIO}

Recall that we defined correlations with non-influenceable causal order (Eq.~\eqref{eq:def_NIO}) by referring to our definition of causal correlations based on decompositions of the form $p(\vec a|\vec x) = \sum_\pi p(\pi,\vec a|\vec x)$.

One could however also refer to Oreshkov and Giarmatzi's definition, namely by defining correlations with NIO as those with a decomposition of the form $p(\vec a|\vec x) = \sum_\kappa p(\kappa,\vec a|\vec x)$, as in \eqref{eq:def_causal_p_OG}, which further satisfies
\begin{align}
    \forall\, \kappa, \ p(\kappa|\vec x)\ \text{does not depend on } \vec x. \label{eq:def_NIO_OG}
\end{align}

It is however easy to see, following the previous subsection, that the two definitions are equivalent. Indeed a total order $\pi$ is a particular case of an SPO $\kappa$, so that if a decomposition of the form $p(\vec a|\vec x) = \sum_\pi p(\pi,\vec a|\vec x)$ (satisfying Eq.~\eqref{eq:def_causal_p}) with $p(\pi|\vec x)$ being independent of $\vec x$ exists, then this readily provides a decomposition of the form $p(\vec a|\vec x) = \sum_\kappa p(\kappa,\vec a|\vec x)$ (satisfying Eq.~\eqref{eq:def_causal_p_OG}, as we have seen before) with $p(\kappa|\vec x)$ that does not depend on $\vec x$.
Conversely, if a decomposition of the form $p(\vec a|\vec x) = \sum_\kappa p(\kappa,\vec a|\vec x)$ (satisfying Eq.~\eqref{eq:def_causal_p_OG}) exists, then we have just seen above how to extend each SPO $\kappa$ to a total order $\pi$, and obtain a decomposition $p(\vec a|\vec x) = \sum_\pi p(\pi,\vec a|\vec x)$ as in Eq.~\eqref{eq:decomp_extend_SPO}, with $p(\pi,\vec a|\vec x)= \sum_{\kappa\text{ s.t. }\pi_\kappa=\pi} p(\kappa,\vec a|\vec x)$ satisfying Eq.~\eqref{eq:def_causal_p}; if $p(\kappa|\vec x)$ does not depend on $\vec x$, then neither does the distribution $p(\pi|\vec x)$ thus obtained.


\section{Tripartite causal correlations}

\subsection{The ``simplest'' tripartite scenario with dynamical causal order}
\label{app:simplest_N3}

Consider a tripartite scenario in which the three parties $A,B,C$ have binary inputs $x,y,z=0,1$, party $A$ has no output, while parties $B$ and $C$ have a binary output $b,c=0,1$ only when their input is 1 ($B$ and $C$ are in the so-called ``lazy scenario''). This scenario is simple enough that the polytopes of causal correlations ($\mathcal{P}_{\textup{causal}}$), of correlations with static causal order ($\mathcal{P}_{\textup{convFO}}$), as well as of all valid probability distributions ($\mathcal{P}_{\textup{all}}$) can be fully characterised:
\begin{itemize}
    \item The causal polytope $\mathcal{P}_{\textup{causal}}$ has 144 vertices: 112 of them are compatible with a fixed causal order---of the form $p(b,c|x,y,z) = \delta_{b,y\beta_x}\delta_{c,z\gamma_{x,y}}$ or $p(b,c|x,y,z) = \delta_{b,y\beta_{x,z}}\delta_{c,z\gamma_x}$, or both, for some $\beta_{x(,z)}, \gamma_{x(,y)}=0,1$---and 32 of them feature dynamical causal order---of the form $p(b,c|x,y,z) = \delta_{x,0}\delta_{b,y\beta_0}\delta_{c,z\gamma_{0,y}} + \delta_{x,1}\delta_{b,y\beta_{1,z}}\delta_{c,z\gamma_1}$ or $p(b,c|x,y,z) = \delta_{x,1}\delta_{b,y\beta_1}\delta_{c,z\gamma_{1,y}} + \delta_{x,0}\delta_{b,y\beta_{0,z}}\delta_{c,z\gamma_0}$, with $\beta_{x,z}$ and $\gamma_{x,y}$ having a nontrivial dependence on $z$ and $y$, resp.

    Solving the facet enumeration problem, we find that $\mathcal{P}_{\textup{causal}}$ has 8 facets of the ``Lazy Guess Your Neighbour's Input'' (LGYNI)~\cite{branciard16} form%
\footnote{Here we only write explicitly a single representative for each type of facet. The other facets ``of the same form'' are obtained by exchanging the parties $B$ and $C$, by flipping $A$'s input $x$, and/or by flipping $B$ and/or $C$'s outputs when their input is 1.}
    \begin{align}
        p(b=c=yz|x) \underset{\text{causal}}{\leq} \frac34
    \end{align}
    (for some fixed value $x$, with $p(b=c=yz|x) \coloneqq \frac14\sum_{y,z} p(b=c=yz|x,y,z)$), in addition to 8 trivial facets of the form $p(b|x,y=1,z) \ge 0$ and 8 trivial facets of the form $p(b,c|x,y=z=1) \ge 0$.

    \item The polytope $\mathcal{P}_{\textup{convFO}}$ only has the 112 vertices compatible with a fixed order given above.
    We find that it has the same facets as $\mathcal{P}_{\textup{causal}}$, plus 8 facets of the form
    \begin{align}
        I_3 \coloneqq p\big(x=0, c=yz\big) + p\big(x=1, b=yz\big) \underset{\text{convFO}}{\leq} \frac78,
    \end{align}
    as in Eqs.~\eqref{eq:def_I3}--\eqref{eq:bnd_I3_FO} of the main text.

Let us present here a direct proof of the latter inequality.
Consider a fixed order in which $B$ comes before $C$, so that $p(b|x,y,z)$ does not depend on $z$: we shall write $p(b|x,y,z) = p(b|x,y,\cancel{z})$. We then have
\begin{align}
    I_3 & \coloneqq \underbrace{p\big(x=0, c=yz\big)}_{\leq p(x=0)=\frac12} + \underbrace{p\big(x=1, b=yz\big)}_{=\frac18\sum_{yz}p(b=yz|x=1,y,z)} \notag \\
    & \leq \frac12 + \frac18 \sum_{z=0,1} \big[ \underbrace{p\big(b=0|x=1,y=0,\cancel{z}\big)}_{\leq 1} + p\big(b=z|x=1,y=1,\cancel{z}\big) \big] \leq \frac12 + \frac14 + \frac18 = \frac78.
\end{align}
The same bound holds, by symmetry, for any fixed order in which $C$ comes before $B$, and by linearity, for any convex combination of fixed orders: $I_3 \underset{\text{convFO}}{\leq} \frac{7}{8}$.

    \item The polytope $\mathcal{P}_{\textup{all}}$ of all valid probability distributions is only delimited by the 16 trivial facets of the form $p(b|x,y=1,z) \ge 0$ and $p(b,c|x,y=z=1) \ge 0$.
    Solving the vertex enumeration problem, we find that it has the same 144 vertices as $\mathcal{P}_{\textup{causal}}$, plus 112 non-causal vertices that feature 2-way signalling, of the form $p(b,c|x,y,z) = \delta_{b,y\beta_{x,z}}\delta_{c,z\gamma_{x,y}}$, with both $\beta_{0,z}$ and $\gamma_{0,y}$, and/or both $\beta_{1,z}$ and $\gamma_{1,y}$, having a nontrivial dependence on $z$ and $y$, resp.

\end{itemize}

\bigskip

Notice that the scenario considered here is the ``smallest'' one---in the sense of minimising the number of parties and the number of inputs and outputs for each party \emph{individually}%
\footnote{Note however that one could also consider even ``smaller'' scenarios where certain \emph{combinations} of inputs, for the different parties, are further restricted. In fact, the expression $I_3$ does not involve (in any nontrivial way) terms with $(x,z)=(0,0)$, nor with $(x,y)=(1,0)$. Hence one can already distinguish dynamical orders in scenarios where these combinations of inputs never appear.\label{ftn:even_smaller}}---that can feature dynamical causal order. With two parties causal correlations indeed reduce to convex mixtures of the two possible orders as in Eq.~\eqref{eq:causal_N_2}; if one of the three parties had no input then it could always be considered to come last,%
\footnote{More specifically: if one party, say $A_N$, has no input, then starting from a probability distribution $p\big(\pi=(k_1,\ldots,k_N),\vec a\big|\vec x\big)$ one can define $p'\big(\pi=(k_1,\ldots,k_{N-1},N),\vec a\big|\vec x\big)\coloneqq \sum_{i=1}^N p\big(\pi=(k_1,\ldots,k_{i-1},N,k_i,\ldots,k_{N-1}),\vec a\big|\vec x\big)$, such that party $A_N$ always comes last in $\pi=(k_1,\ldots,k_{N-1},N)$.
\\
Similarly, if one party, say $A_1$, has no output, then starting from $p\big(\pi=(k_1,\ldots,k_N),\vec a\big|\vec x\big)$ one can define $p'\big(\pi=(1,k_2,\ldots,k_N),\vec a\big|\vec x\big)\coloneqq \sum_{i=1}^N p\big(\pi=(k_2,\ldots,k_i,1,k_{i+1},\ldots,k_N),\vec a\big|\vec x\big)$, such that party $A_1$ always comes first in $\pi=(1,k_2,\ldots,k_N)$.
\\
One can verify that in both cases, if the original distribution $p(\pi,\vec a|\vec x)$ satisfies the causal constraints of Eq.~\eqref{eq:def_causal_p}, then so does $p'(\pi,\vec a|\vec x)$; if $p(\pi,\vec a|\vec x)$ satisfies the NIO constraints of Eq.~\eqref{eq:def_NIO}, then so does $p'(\pi,\vec a|\vec x)$; and if $p(\pi,\vec a|\vec x)$ satisfies the NIO$'$ constraints of Eq.~\eqref{eq:def_NIO'}, then so does $p'(\pi,\vec a|\vec x)$. \label{ftn:no_IO}}
and causal correlations would reduce to convex mixtures of the two possible orders for the other two parties; and if a second party had no output then all probability distributions (for just the single remaining output) could be obtained causally, with the two parties with no output coming first.
It is in fact rather remarkable that the dynamical property appears already in a tripartite scenario where one of the parties has no output.


\subsection{$\mathcal{P}_{\textup{NIO}}$ and $\mathcal{P}_{\textup{NIO}'}$ reduce to $\mathcal{P}_{\textup{convFO}}$ for $N = 3$}
\label{app:NIO_convFO_N3}

While, as just seen, a tripartite scenario can exhibit dynamical causal order, we show here that it cannot exhibit ``dynamical but non-influenceable causal order''---that is, correlations with non-influenceable causal order (in $\mathcal{P}_{\textup{NIO}}$) reduce to convex mixtures of correlations with fixed orders (i.e., they are in $\mathcal{P}_{\textup{convFO}}$).

To see this, notice that for $N=3$, the causality conditions of Eq.~\eqref{eq:def_causal_p} imply in particular that for all $\pi=(k_1,k_2,k_3)$,%
\footnote{Notice that the following argument does not work in general for $N\ge 4$---unless one party has no input or one party has no output, using the observation made in the previous footnote---because $p\big((k_1,k_2),a_{k_1}\big|\vec x\big)$ cannot be readily identified with $p(\pi,a_{k_1}|\vec x)$ as we do in Eq.~\eqref{eq:causal_p_N3}, and the terms $p(\vec a|\vec x,\pi)$ in Eq.~\eqref{eq:convex_decomp_pi_N3} are in general not compatible with the causal order $\pi$. \\
As an explicit counter-example, one can take for instance the NIO correlation in Eq.~\eqref{eq:saturate_NIO} of the next appendix, with its causal decomposition as proposed just below Eq.~\eqref{eq:saturate_NIO}. For these one gets $p(a,b,c,d|x,y,z,t,\pi{=}(A,B,C,D)) = \delta_{a=b=xy}\,\delta_{c,0}\,\delta_{d,zt}$ and 
$p(a,b,c,d|x,y,z,t,\pi{=}(A,B,D,C)) = \delta_{a,x\bar{y}}\,\delta_{b,\bar{x}y}\,\delta_{d,0}\,\delta_{c,zt}$ (with $\bar{x}\coloneqq 1-x$, $\bar{y}\coloneqq 1-y$), which are not compatible with any fixed causal order.\label{ftn:NIO_N3}}
\begin{align}
    & p\big((k_1,k_2),a_{k_1}\big|\vec x\big) = p(\pi,a_{k_1}|\vec x) \ \text{does not depend on } \vec x_{k_2,k_3} \notag \\
    \text{and}\ & p\big((k_1,k_2,k_3),a_{k_1},a_{k_2}\big|\vec x\big) = p(\pi,a_{k_1},a_{k_2}|\vec x) \ \text{does not depend on } x_{k_3}.
 \label{eq:causal_p_N3}
\end{align}
Assuming the non-influenceability condition of Eq.~\eqref{eq:def_NIO} and writing
\begin{align}
    p(\vec a|\vec x) = \sum_\pi p(\pi,\vec a|\vec x) = \sum_\pi p(\pi) \, p(\vec a|\vec x,\pi), \label{eq:convex_decomp_pi_N3}
\end{align}
we then have that, for $\pi=(k_1,k_2,k_3)$, 
\begin{align}
    & p(a_{k_1}|\vec x,\pi) = \frac{p(\pi,a_{k_1}|\vec x)}{p(\pi)} \ \text{does not depend on } \vec x_{k_2,k_3}, \notag \\
    & p(a_{k_1},a_{k_2}|\vec x,\pi) = \frac{p(\pi,a_{k_1},a_{k_2}|\vec x)}{p(\pi)} \ \text{does not depend on } x_{k_3}, 
\end{align}
so that $p(\vec a|\vec x,\pi)$ is compatible with the fixed causal order defined by $\pi$, and Eq.~\eqref{eq:convex_decomp_pi_N3} indeed provides a convex decomposition of $p(\vec a|\vec x)$ onto correlations compatible with fixed causal orders.

\medskip

We further note that for $N=3$, the ``non-influenceable coarse-grained order'' condition of Eq.~\eqref{eq:def_NIO'} reduces to the mere ``non-influenceable order'' condition of Eq.~\eqref{eq:def_NIO} (since Eq.~\eqref{eq:def_NIO'} implies that $p\big((k_1,k_2,k_3)\big|\vec x\big) = p\big((k_1,k_2)\big|\vec x\big) = p\big((\{k_1\},k_2)\big|\vec x\big)$ does not depend on $\vec x$). Hence, $\mathcal{P}_{\textup{NIO}'}$ also reduces in the tripartite case to $\mathcal{P}_{\textup{convFO}}$.


\section{Proofs of the different causal bounds on $I_4 \coloneqq p\big(a=b=xy , d=zt\big) + p\big(\neg(a=b=xy) , c=zt\big)$}
\label{app:proofs_bounds}

We prove in this Appendix the various causal bounds on the expression $I_4$ that we introduced in the main text to distinguish between correlations in $\mathcal{P}_{\textup{convFO}}$, $\mathcal{P}_{\textup{NIO}}$, $\mathcal{P}_{\textup{NIO}'}$ and $\mathcal{P}_{\textup{causal}}$.

Recall that we consider here a 4-partite scenario with parties denoted $A,B,C,D$, with binary inputs $x,y,z,t=0,1$, each party having a trivial output $a,b,c,d=0$ if their input is 0, or a binary output $a,b,c,d=0,1$ if their input is 1 (the so-called ``lazy scenario'').
This is the ``smallest'' scenario (with the minimal number of parties, and of inputs and outputs for each party individually\footnote{Note, as in Footnote~\ref{ftn:even_smaller}, that one can in fact still further restrict the number of allowed \emph{combinations} of inputs for the different parties. E.g., the expression $I_4$ does not involve (in any nontrivial way) terms with $(z,t)=(0,0)$, nor with $(x,y,z,t)=(0,0,1,0)$. Hence one can already distinguish correlations with dynamical but non-influenceable causal order in scenarios where these combinations of inputs never appear.
Restricting to such smaller spaces of correlations (and perhaps also restricting to the probabilities of certain combinations of outputs only, e.g. only those that appear nontrivially in $I_4$), may help to get a better characterisation of the different polytopes of correlations under consideration.}) in which one can find correlations with dynamical but non-influenceable causal order: if one of the four parties has no output or no input at all, then using the observation from Footnote~\ref{ftn:no_IO}, a similar argument to that for $N=3$ parties (just above) shows that correlations in $\mathcal{P}_{\textup{NIO}}$ and $\mathcal{P}_{\textup{NIO}'}$ are necessarily convex combinations of correlations with fixed order (cf also Footnote~\ref{ftn:NIO_N3}).

\subsection{For (convex mixtures of) fixed orders: $I_4 \leq_{\text{convFO}} \frac{15}{16}$}
\label{app:proof_convFO_bound}

By linearity and convexity, to obtain the bound on $I_4$ for correlations in $\mathcal{P}_{\textup{convFO}}$, it is sufficient to calculate the bound for each possible fixed order independently.
Consider therefore a correlation $p(a,b,c,d|x,y,z,t)$ compatible with a given fixed order $\pi$ (described as a permutation of the parties).
We will first distinguish whether $C$ comes before or after $D$ in $\pi$:

\begin{itemize}

    \item if $C$ comes before $D$ in $\pi$, then let us write
    \begin{align}
        I_4 & = p\big(a=b=xy , d=zt\big) + p\big(\neg(a=b=xy) , c=zt\big) \notag \\
        & \leq p\big(a=b=xy\big) + p\big(\neg(a=b=xy) , c=zt\big) \notag \\
        & \qquad = \frac{1}{16}\sum_{x,y,z,t=0,1} \Big[ p\big(a=b=xy\big|x,y,z,t\big) + p\big(\neg(a=b=xy) , c=zt\big|x,y,z,t\big) \Big] \notag \\
        & \qquad = \frac{1}{16}\sum_{x,y,t} \Big[ p\big(a=b=xy\big|x,y,z=0,t\big) + p\big(\neg(a=b=xy) , \cancel{c=0}\big|x,y,z=0,t\big) \notag \\[-3mm]
        & \hspace{25mm} + p\big(a=b=xy\big|x,y,z=1,t\big) + p\big(\neg(a=b=xy) , c=t\big|x,y,z=1,t\big) \Big] \notag \\
        & \qquad = \frac{1}{16}\sum_{x,y,t} \Big[ 1 + p\big(a=b=xy\big|x,y,z=1,t\big) + p\big(\neg(a=b=xy) , c=t\big|x,y,z=1,t\big) \Big], \label{eq:proof_FO_C_before_D}
    \end{align}
    where we used the fact that for an input $0$ (here, $z=0$), the output is necessarily $0$ ($c=0$).

    Let us further distinguish here the different cases according to which party comes last in $\pi$:
    \begin{itemize}
        \item If $D$ comes last in $\pi$, then%
        \footnote{In the proofs we shall indicate that a probability does not depend on a given input, according to some causality condition, by striking out the corresponding input; on the subsequent lines we will simply not write that input anymore.}
        \begin{align}
            I_4 & \leq \frac{1}{16}\sum_{x,y,t} \Big[ 1 + p\big(a=b=xy\big|x,y,z=1,\cancel{t}\big) + p\big(\neg(a=b=xy) , c=t\big|x,y,z=1,\cancel{t}\big) \Big] \notag \\
            & \qquad = \frac{1}{16}\sum_{x,y} \Big[ 2 + 2\,p\big(a=b=xy\big|x,y,z=1\big) + p\big(\neg(a=b=xy)\big|x,y,z=1\big) \Big] \notag \\
            & \qquad = \frac{1}{16}\sum_{x,y} \Big[ 3+p\big(a=b=xy\big|x,y,z=1\big) \Big] = \frac14 \Big(3 + \frac14\sum_{x,y} p\big(a=b=xy\big|x,y,z=1\big) \Big) \leq \frac14 \Big(3 + \frac34 \Big) = \frac{15}{16}, \label{eq:proof_FO_C_before_D_Dlast}
        \end{align}
        where the last inequality just follows from the LGYNI inequality~\cite{branciard16} for $A$ and $B$ (for which conditioning on the input $z=1$ of another party does not change the causal bound).
        \item If $B$ comes last in $\pi$, then
        \begin{align}
            I_4 & \leq \frac{1}{16}\sum_t \Big[ 4 + \underbrace{p\big(a=b=0\big|x=y=0,z=1,t\big)}_{1} + \underbrace{p\big(\neg(a=b=0) , c=t\big|x=y=0,z=1,t\big)}_{0} \notag \\
        & \hspace{15mm} + p\big(a=b=0\big|x=0,y=1,z=1,t\big) + \underbrace{p\big(\neg(a=b=0) , c=t\big|x=0,y=1,z=1,t\big)}_{\leq \,p(\neg(a=b=0)|x=0,y=1,z=1,t)} \notag \\
        & \hspace{15mm} + \underbrace{p\big(a=b=0\big|x=1,y=0,z=1,t\big)}_{p(a=0|x=1,\cancel{y=0},z=1,t)} + \underbrace{p\big(\neg(a=b=0) , c=t\big|x=1,y=0,z=1,t\big)}_{p(a=1 , c=t|x=1,\cancel{y=0},z=1,t)} \notag \\
        & \hspace{15mm} + \underbrace{p\big(a=b=1\big|x=y=1,z=1,t\big) + p\big(\neg(a=b=1) , c=t\big|x=y=1,z=1,t\big)}_{p(a=b=1, c=\bar{t}|x=y=1,z=1,t) + p(c=t|x=\cancel{y}=1,z=1,\cancel{t})} \Big] \notag \\
        & \leq \frac{1}{16}\sum_t \Big[ 6 + p\big(a=0\big|x=z=1,t\big) + p\big(a=1,c=t\big|x=z=1,t\big) \notag \\[-3mm]
        & \hspace{20mm} + \underbrace{p\big(a=b=1,c=\bar{t}\big|x=y=z=1,t\big)}_{\leq \,p(a=1,c=\bar{t}|x=\cancel{y}=z=1,t)} + \,p\big(c=t\big|x=z=1\big) \Big] \notag \\
        & \leq \frac{1}{16}\sum_t \Big[ 7 + p\big(c=t\big|x=z=1\big) \Big]  = \frac{15}{16} \label{eq:proof_FO_C_before_D_Blast}
        \end{align}
        (where we used the notation $\bar{t}\coloneqq 1-t$).
        \item If $A$ comes last in $\pi$, then by symmetry (with respect to $A \leftrightarrow B$), we also get the bound $I_4 \leq \frac{15}{16}$.
    \end{itemize}

    \item if $D$ comes before $C$ in $\pi$, then let us write (considering the case where $x=y=0$ separately, and noting that $a=b=xy$ always holds in this case):
    \begin{align}
        I_4 & = p\big(a=b=xy , d=zt\big) + p\big(\neg(a=b=xy) , c=zt\big) \notag \\
        & = \frac{1}{16} \Bigg[ \sum_{z,t=0,1} p\big(d=zt\big|x=y=0,\cancel{z},t\big) \notag \\[-2mm]
        & \hspace{10mm} + \sum_{\substack{x,y,z,t=0,1: \\ (x,y)\neq(0,0)}} \Big[ \underbrace{p\big(a=b=xy , d=zt\big|x,y,z,t\big) + p\big(\neg(a=b=xy) , c=zt\big|x,y,z,t\big)}_{\leq \, 1} \Big] \Bigg] \notag \\
        & \leq \frac{1}{16} \Big[ \underbrace{{\textstyle \sum_z} \,p\big(d=0\big|x=y=0,t=0\big)}_{2} + \underbrace{{\textstyle \sum_z} \,p\big(d=z\big|x=y=0,t=1\big)}_{1} + 12 \Big] = \frac{15}{16}. \label{eq:proof_FO_D_before_C}
    \end{align}

\end{itemize}

All in all, for any fixed causal order, and by linearity for any convex combination of fixed causal orders, we obtained the bound
\begin{align}
    I_4 \underset{\text{convFO}}{\leq} \frac{15}{16},
\end{align}
as in Eq.~\eqref{eq:bnd_I4_FO}.

This bound can be reached for instance by the correlation (compatible with any fixed order where $C$ comes before $D$) $p(a,b,c,d|x,y,z,t) = \delta_{a,0}\,\delta_{b,0}\,\delta_{c,0}\,\delta_{d,zt}$.

\subsection{For correlations with non-influenceable causal orders: $I_4 \leq_{\text{NIO}} \frac{31}{32}$}
\label{app:proof_NIO_bound}

Consider a causal correlation $p(\vec a|\vec x)$, for which there exists $p(\pi,\vec a|\vec x)$ that satisifes Eq.~\eqref{eq:def_causal_p}. One can then write
\begin{align}
    I_4 = \sum_\pi I_\pi \quad \text{with} \quad I_\pi \coloneqq p\big(\pi,a=b=xy , d=zt\big) + p\big(\pi,\neg(a=b=xy) , c=zt\big) . \label{eq:def_I_pi}
\end{align}
Following similar calculations as in the different cases with fixed order above, we see that:
\begin{itemize}
    \item If $C$ comes before $D$ in $\pi$, then (similarly to Eq.~\eqref{eq:proof_FO_C_before_D})
    \begin{align}
        I_\pi & \leq \frac{1}{16}\sum_{x,y,t} \Big[ p\big(\pi\big|x,y,z=0,t\big) + p\big(\pi,a=b=xy\big|x,y,z=1,t\big) + p\big(\pi,\neg(a=b=xy) , c=t\big|x,y,z=1,t\big) \Big].
    \end{align}
    \begin{itemize}
        \item If $D$ comes last in $\pi$, then it follows from the causality constraints of Eq.~\eqref{eq:def_causal_p} that $p(\pi,a,b,c|x,y,z,t)$, and hence $p(\pi,a,b|x,y,z,t)$ and $p(\pi|x,y,z,t)$, do not depend on $t$. We then have (similarly to Eq.~\eqref{eq:proof_FO_C_before_D_Dlast})
        \begin{align}
            I_\pi & \leq \frac{1}{16}\sum_{x,y,t} \Big[ p\big(\pi\big|x,y,z=0,\cancel{t}\big) + p\big(\pi,a=b=xy\big|x,y,z=1,\cancel{t}\big) + p\big(\pi,\neg(a=b=xy) , c=t\big|x,y,z=1,\cancel{t}\big) \Big] \notag \\
                & \qquad = \frac{1}{16}\sum_{x,y} \Big[ 2\,p\big(\pi\big|x,y,z=0\big) + p\big(\pi\big|x,y,z=1\big) + p\big(\pi,a=b=xy\big|x,y,z=1\big) \Big] \notag \\
                & \qquad = \frac{1}{8}\sum_{x,y,z} p\big(\pi\big|x,y,z\big) - \frac{1}{16}\sum_{x,y} p\big(\pi,\neg(a=b=xy)\big|x,y,z=1\big).
        \end{align}
        If, in addition, $A$ comes before $B$ in $\pi$, then we have that
        \begin{align}
            & \sum_{x,y} p\big(\pi,\neg(a=b=xy)\big|x,y,z=1\big) \notag \\
            & \quad = p\big(\pi,a=1\big|x=1,y=0,z=1\big) + \underbrace{p\big(\pi,b=1\big|x=0,y=1,z=1\big)}_{\ge 0} + \underbrace{p\big(\pi,\neg(a=b=1)\big|x=1,y=1,z=1\big)}_{\ge p(\pi,a=0|x=1,y=1,z=1)} \notag \\[-2mm]
            & \quad \ge \sum_y p\big(\pi,a=\bar{y}\big|x=1,y,z=1\big),
        \end{align}
        so that
        \begin{align}
            I_\pi & \leq \frac{1}{8}\sum_{x,y,z} p\big(\pi\big|x,y,z\big) - \frac{1}{16}\sum_y p\big(\pi,a=\bar{y}\big|x=1,y,z=1\big).
        \end{align}
        Similarly, if $B$ comes before $A$ in $\pi$ instead (still in addition to $D$ coming last), then
        \begin{align}
            I_\pi & \leq \frac{1}{8}\sum_{x,y,z} p\big(\pi\big|x,y,z\big) - \frac{1}{16}\sum_x p\big(\pi,b=\bar{x}\big|x,y=1,z=1\big).
        \end{align}

        \item If $B$ comes last in $\pi$, then $p(\pi,a,c|x,y,z,t)$ does not depend on $y$ and we have (similarly to Eq.~\eqref{eq:proof_FO_C_before_D_Blast})
        \begin{align}
            I_\pi & \leq \frac{1}{16}\sum_t \Big[ p\big(\pi\big|x=0,\cancel{y=0},z=0,t\big) + p\big(\pi\big|x=0,\cancel{y=0},z=1,t\big) \notag \\[-3mm]
            & \hspace{15mm} + p\big(\pi\big|x=0,\cancel{y=1},z=0,t\big) + p\big(\pi\big|x=0,\cancel{y=1},z=1,t\big) \notag \\
            & \hspace{15mm} + p\big(\pi\big|x=1,\cancel{y=0},z=0,t\big) + p\big(\pi,a=0\big|x=1,\cancel{y=0},z=1,t\big) + p\big(\pi,a=1,c=t\big|x=1,\cancel{y=0},z=1,t\big) \notag \\
            & \hspace{15mm} + p\big(\pi\big|x=1,\cancel{y=1},z=0,t\big) + p\big(\pi,a=1,c=\bar{t}\big|x=1,\cancel{y=1},z=1,t\big) + p\big(\pi,c=t\big|x=1,\cancel{y=1},z=1,t\big) \Big] \notag \\
            & \qquad = \frac{1}{16}\sum_t \Big[ 2\,p\big(\pi\big|x=z=0,t\big) + 2\,p\big(\pi\big|x=0,z=1,t\big) + 2\,p\big(\pi\big|x=1,z=0,t\big) \notag \\[-3mm]
            & \hspace{80mm} + p\big(\pi\big|x=z=1,t\big) + p\big(\pi,c=t\big|x=z=1,t\big) \Big] \notag \\
            & \qquad = \frac{1}{8}\sum_{x,z,t} p\big(\pi\big|x,z,t\big) - \frac{1}{16}\sum_t p\big(\pi,c=\bar{t}\big|x=z=1,t\big).
        \end{align}

        \item If $A$ comes last in $\pi$, then by symmetry the same bound holds (just replacing $x$ by $y$ in the above expression):
        \begin{align}
            I_\pi & \leq \frac{1}{8}\sum_{y,z,t} p\big(\pi\big|y,z,t\big) - \frac{1}{16}\sum_t p\big(\pi,c=\bar{t}\big|y=z=1,t\big).
        \end{align}
    \end{itemize}

    \item If $D$ comes before $C$ in $\pi$, then (similarly to Eq.~\eqref{eq:proof_FO_D_before_C})
    \begin{align}
        I_\pi & \leq \frac{1}{16} \Big[ \sum_{z=0,1} \big[ p\big(\pi\big|x=y=0,z,t=0\big) + p\big(\pi,d=z\big|x=y=0,z,t=1\big) \big] + \sum_{\substack{x,y,z,t=0,1: \\ (x,y)\neq(0,0)}} p\big(\pi\big|x,y,z,t\big) \Big] \notag \\
        & \qquad = \frac{1}{16} \sum_{x,y,z,t} p\big(\pi\big|x,y,z,t\big) - \frac{1}{16} \sum_{z} p\big(\pi,d=\bar{z}\big|x=y=0,z,t=1\big).
    \end{align}
    Now, it follows from the causality constraints of Eq.~\eqref{eq:def_causal_p} that $p(\pi{:}D{\prec}C,d|x,y,z,t) \coloneqq \sum_{\pi{:}D{\prec}C} p(\pi,d|x,y,z,t)$ and $p(\pi{:}D{\prec}C|x,y,z,t) \coloneqq \sum_{\pi{:}D{\prec}C} p(\pi|x,y,z,t)$ do not depend on $z$.%
    \footnote{As indicated by the conditions `$\pi{:}D{\prec}C$', the sums $\sum_{\pi{:}D{\prec}C}$ are over all permutations in which $D$ comes before $C$. To see that $p(\pi{:}D{\prec}C,d|x,y,z,t)$ does not depend on $z$, one can write $p(\pi{:}D{\prec}C,d|x,y,z,t) = p\big((k_1,k_2,k_3)=(A,B,D),d\big|x,y,\cancel{z},t\big) + p\big((k_1,k_2,k_3)=(B,A,D),d\big|x,y,\cancel{z},t\big) + p\big((k_1,k_2)=(A,D),d\big|x,\cancel{y},\cancel{z},t\big) + p\big((k_1,k_2)=(B,D),d\big|\cancel{x},y,\cancel{z},t\big) + p\big((k_1)=(D),d\big|\cancel{x},\cancel{y},\cancel{z},t\big)$, where all independencies (struck-out inputs) follow from Eq.~\eqref{eq:def_causal_p}.}
    We then have (again, similarly to Eq.~\eqref{eq:proof_FO_D_before_C})
    \begin{align}
        \sum_{\pi{:}D{\prec}C} I_\pi & \leq \frac{1}{16} \sum_{x,y,z,t} p\big(\pi{:}D{\prec}C\big|x,y,\cancel{z},t\big) - \frac{1}{16} \sum_{z} p\big(\pi{:}D{\prec}C,d=\bar{z}\big|x=y=0,\cancel{z},t=1\big) \notag \\
        & \qquad = \frac{1}{8} \sum_{x,y,t} p\big(\pi{:}D{\prec}C\big|x,y,t\big) - \frac{1}{16} p\big(\pi{:}D{\prec}C\big|x=y=0,t=1\big).
    \end{align}

\end{itemize}

All in all, we obtain
\begin{align}
I_4 = & \sum_\pi I_\pi = \sum_{\substack{\pi:D\text{ last}, \\ A\prec B}} I_\pi + \sum_{\substack{\pi:D\text{ last}, \\ B\prec A}} I_\pi + \sum_{\substack{\pi{:}C{\prec}D, \\ A\text{ last}}} I_\pi + \sum_{\substack{\pi{:}C{\prec}D, \\ B\text{ last}}} I_\pi + \sum_{\pi{:}D{\prec}C} I_\pi \notag \\
\leq & \!\scalebox{0.85}{${\displaystyle \sum_{\substack{\pi:D\text{ last}, \\ A\prec B}}}$} \!\Big[ {\textstyle \frac{1}{8}}\scalebox{0.85}{${\displaystyle \sum_{x,y,z}}$}\, p(\pi|x,y,z) - {\textstyle \frac{1}{16}}\scalebox{0.85}{${\displaystyle \sum_y}$}\, p(\pi,a=\bar{y}|x=1,y,z=1) \Big] \!+ \!\scalebox{0.85}{${\displaystyle \sum_{\substack{\pi:D\text{ last}, \\ B\prec A}}}$} \!\Big[ {\textstyle \frac{1}{8}}\scalebox{0.85}{${\displaystyle \sum_{x,y,z}}$}\, p(\pi|x,y,z) - {\textstyle \frac{1}{16}}\scalebox{0.85}{${\displaystyle \sum_x}$}\, p(\pi,b=\bar{x}|x,y=z=1) \Big] \notag \\
& + \!\scalebox{0.85}{${\displaystyle \sum_{\substack{\pi{:}C{\prec}D, \\ B\text{ last}}}}$} \!\Big[ {\textstyle \frac{1}{8}}\scalebox{0.85}{${\displaystyle \sum_{x,z,t}}$}\, p(\pi|x,z,t) - {\textstyle \frac{1}{16}}\scalebox{0.85}{${\displaystyle \sum_t}$}\, p(\pi,c=\bar{t}|x=z=1,t) \Big] + \!\scalebox{0.85}{${\displaystyle \sum_{\substack{\pi{:}C{\prec}D, \\ A\text{ last}}}}$} \!\Big[ {\textstyle \frac{1}{8}}\scalebox{0.85}{${\displaystyle \sum_{y,z,t}}$}\, 
p(\pi|y,z,t) - {\textstyle \frac{1}{16}}\scalebox{0.85}{${\displaystyle \sum_t}$}\, p(\pi,c=\bar{t}|y=z=1,t) \Big] \notag \\
& + {\textstyle \frac{1}{8}}\scalebox{0.85}{${\displaystyle \sum_{x,y,t}}$}\, p(\pi{:}D{\prec}C|x,y,t) - {\textstyle \frac{1}{16}} p(\pi{:}D{\prec}C|x=y=0,t=1) \notag \\
& \quad =  1 - \frac{1}{16} \Big( J_{C\prec D} + p\big(\pi{:}D{\prec}C\big|x=y=0,t=1\big) \Big), \label{eq:bnd_I4_JCD_pDC}
\end{align}
with
\begin{align}
J_{C\prec D} \coloneqq & \sum_{\substack{\pi:D\text{ last}, \\ A\prec B}} \sum_y p\big(\pi,a=\bar{y}\big|x=1,y,z=1\big) + \sum_{\substack{\pi:D\text{ last}, \\ B\prec A}} \sum_x p\big(\pi,b=\bar{x}\big|x,y=z=1\big) \notag \\
& \hspace{8mm} + \sum_{\substack{\pi{:}C{\prec}D, \\ B\text{ last}}} \sum_t p\big(\pi,c=\bar{t}\big|x=z=1,t\big) + \sum_{\substack{\pi{:}C{\prec}D, \\ A\text{ last}}} \sum_t p\big(\pi,c=\bar{t}\big|y=z=1,t\big) \notag \\[3mm]
= & \sum_y \underbrace{p\big(\pi=(A,B,C,D),a=\bar{y}\big|x=1,y,\cancel{z=1}\big)}_{\ge\,p(\pi=(A,B,C,D)|x=1,y)-p((k_1,k_2)=(A,B),a=y|x=1,\cancel{y})} + \sum_{\substack{\pi=(A,C,B,D), \\ (C,A,B,D)}} \underbrace{{\textstyle \sum_y}\, p\big(\pi,a=\bar{y}\big|x=1,\cancel{y},z=1\big)}_{p(\pi|x=z=1)} \notag \\[1mm]
& + \sum_x \underbrace{p\big(\pi=(B,A,C,D),b=\bar{x}\big|x,y=\cancel{z}=1\big)}_{\ge\,p(\pi=(B,A,C,D)|x,y=1)-p((k_1,k_2)=(B,A),b=x|\cancel{x},y=1)} + \sum_{\substack{\pi=(B,C,A,D), \\ (C,B,A,D)}} \underbrace{{\textstyle \sum_x}\, p\big(\pi,b=\bar{x}\big|\cancel{x},y=z=1\big)}_{p(\pi|y=z=1)} \notag \\[1mm]
& + \sum_t p\big(\pi=(C,D,A,B),c=\bar{t}\big|\cancel{x}=z=1,t\big) + \sum_{\substack{\pi=(C,A,D,B), \\ (A,C,D,B)}} \underbrace{{\textstyle \sum_t}\, p\big(\pi,c=\bar{t}\big|x=z=1,\cancel{t}\big)}_{p(\pi|x=z=1)} \notag \\[1mm]
& + \sum_t p\big(\pi=(C,D,B,A),c=\bar{t}\big|\cancel{y}=z=1,t\big) + \sum_{\substack{\pi=(C,B,D,A), \\ (B,C,D,A)}} \underbrace{{\textstyle \sum_t}\, p\big(\pi,c=\bar{t}\big|y=z=1,\cancel{t}\big)}_{p(\pi|y=z=1)} \notag \\[3mm]
\ge & \sum_y p\big(\pi=(A,B,C,D)\big|x=1,y\big) + \sum_x p\big(\pi=(B,A,C,D)\big|x,y=1\big) \notag \\
& \quad - p\big((k_1,k_2)=(A,B)\big|x=1\big) - p\big((k_1,k_2)=(B,A)\big|y=1\big) \notag \\[1mm]
& \quad + p\big((k_1,k_2)=(A,C)\big|x=\cancel{z}=1\big) + p\big((k_1,k_2)=(C,A)\big|\cancel{x}=z=1\big) \notag \\[1mm]
& \quad + p\big((k_1,k_2)=(B,C)\big|y=\cancel{z}=1\big) + p\big((k_1,k_2)=(C,B)\big|\cancel{y}=z=1\big) \notag \\[1mm]
& \quad + \underbrace{{\textstyle \sum_t}\, p\big((k_1,k_2)=(C,D),c=\bar{t}\big|z=1,\cancel{t}\big)}_{p((k_1,k_2)=(C,D)|z=1)} \notag \\[3mm]
& = \sum_y p\big(\pi=(A,B,C,D)\big|x=1,y\big) + \sum_x p\big(\pi=(B,A,C,D)\big|x,y=1\big) \notag \\
& \quad - p\big((k_1,k_2)=(A,B)\big|x=1\big) - p\big((k_1,k_2)=(B,A)\big|y=1\big) \notag \\[1mm]
& \quad + p\big((k_1,k_2)=(A,C)\big|x=1\big) + p\big((k_1,k_2)=(B,C)\big|y=1\big) + p\big((k_1)=(C)\big|\cancel{z=1}\big), \label{app:eq_intermediate_NIO_bound}
\end{align}
where we repeatedly used the causality constraints of Eq.~\eqref{eq:def_causal_p} to get rid of some dependencies and simplify the expressions.

\bigskip

Note that we have not used the non-influenceable order (NIO) assumption of Eq.~\eqref{eq:def_NIO} yet: the derivations above hold for all causal correlations.
Assuming it now---that is, assuming $p(\pi|x,y,z,t) = p(\pi)$---we then have:
\begin{align}
    & J_{C\prec D} + p\big(\pi{:}D{\prec}C\big|x=y=0,t=1\big) \ge \frac12 J_{C\prec D} + p\big(\pi{:}D{\prec}C\big) \notag \\
    & \quad \ge p\big(\pi=(A,B,C,D)\big) + p\big(\pi=(B,A,C,D)\big) - \frac12 p\big((k_1,k_2)=(A,B)\big) - \frac12 p\big((k_1,k_2)=(B,A)\big) \notag \\
    & \qquad + \frac12 p\big((k_1,k_2)=(A,C)\big) + \frac12 p\big((k_1,k_2)=(B,C)\big) + \frac12 p\big((k_1)=(C)\big) + p\big(\pi{:}D{\prec}C\big) \notag \\[2mm]
    & \qquad = \underbrace{p\big(\pi=(A,B,C,D)\lor(B,A,C,D)\big) + p\big((k_1,k_2)=(A,C)\lor(B,C)\big) + p\big((k_1)=(C)\big) + p\big(\pi{:}D{\prec}C\big)}_{=\, 1} \notag \\
    & \qquad \quad - \frac12 \Big[ \underbrace{p\big((k_1,k_2)=(A,B)\lor(B,A)\lor(A,C)\lor(B,C)\big) + p\big((k_1)=(C)\big)}_{\le 1} \Big] \ge \frac12, \label{app:eq_intermediate_NIO_bound2}
\end{align}
where we used the shorthand notations $p\big(\pi=(A,B,C,D)\lor(B,A,C,D)\big) = p\big(\pi=(A,B,C,D)\big) + p\big(\pi=(B,A,C,D)\big)$, $p\big((k_1,k_2)=(A,C)\lor(B,C)\big) = p\big((k_1,k_2)=(A,C)\big) + p\big((k_1,k_2)=(B,C)\big)$ etc. Recalling Eq.~\eqref{eq:bnd_I4_JCD_pDC}, we then obtain, for correlations with NIO:
\begin{align}
    I_4 \leq 1 - \frac{1}{16} \Big( J_{C\prec D} + p\big(\pi{:}D{\prec}C\big|x=y=0,t=1\big) \Big) \underset{\text{NIO}}{\leq} \frac{31}{32},
\end{align}
as in Eq.~\eqref{eq:bnd_I4_NIO}.

\medskip

This bound can be reached for instance by the correlation
\begin{align}
    & p(a,b,c,d|x,y,z,t) \notag \\[-1mm]
    & \qquad = \underbrace{\left\{
    \begin{array}{ll}
        \delta_{a,0} & \text{if}\ x=0 \\
        \frac12 & \text{if}\ x=1
    \end{array}\right.}_{p(a|x)}
    \underbrace{\left\{
    \begin{array}{ll}
        \delta_{b,0} & \text{if}\ y=0 \\
        \frac12 & \text{if}\ y=1, x=0 \\
        \delta_{b,a} & \text{if}\ y=1, x=1
    \end{array}\right.}_{p(b|x,y,a)} 
    \underbrace{\left\{
    \begin{array}{ll}
        \frac12\,\delta_{c,0}\,\delta_{d,zt} + \frac12\,\delta_{d,0}\,\delta_{c,zt} & \text{if}\ x=y=0 \\[1mm]
        \left\{
        \begin{array}{ll}
            \delta_{c,0}\,\delta_{d,zt} & \text{if}\ a=b=xy \\
            \delta_{d,0}\,\delta_{c,zt} & \text{if}\ \neg(a=b=xy)
        \end{array}\right. & \text{if}\ \neg(x=y=0)
    \end{array}\right.}_{p(c,d|x,y,z,t,a,b)}, \label{eq:saturate_NIO}
\end{align}
which can easily be seen to be causal. In fact, an explicit causal decomposition as in Eq.~\eqref{eq:def_causal_p} can be obtained by taking $p(\pi,a,b,c,d|x,y,z,t)$ to be of the same form as $p(a,b,c,d|x,y,z,t)$ above, after just multiplying the terms $\delta_{c,0}\,\delta_{d,zt}$ by $\delta_{\pi,(A,B,C,D)}$ and the terms $\delta_{d,0}\,\delta_{c,zt}$ by $\delta_{\pi,(A,B,D,C)}$.%
\footnote{
One may notice that the marginal correlation
$p(a,b|x,y) = \left\{
\begin{array}{llcll}
    \delta_{a,0}\,\delta_{b,0} & \text{if}\ x=y=0 & \ ; \ & \frac12\,\delta_{a,0} & \text{if}\ x=0,y=1 \\
    \frac12\,\delta_{b,0} & \text{if}\ x=1,y=0 & \ ; \ & \frac12\,\delta_{a,b} & \text{if}\ x=y=1
\end{array}\right.$
(which does not depend on $z,t$) is non-signalling---and in fact, even Bell-local~\cite{bell64} (as is any non-signalling correlation in the ``lazy'' scenario, where each party has nontrivial outputs for at most one input): $p(a,b|x,y) = \sum_{\lambda=0,1}\frac12\delta_{a,\lambda x}\delta_{b,\lambda y}$---so one could also decompose this correlation onto different orders for $A$ and $B$.}
For such a decomposition, it is then easy to see that $p\big(\pi=(A,B,C,D)\big|x,y,z,t\big) = p\big(\pi=(A,B,D,C)\big|x,y,z,t\big) = \frac12$ does not depend on the inputs $x,y,z,t$, which indeed proves that the correlation is in $\mathcal{P}_{\textup{NIO}}$---and not in $\mathcal{P}_{\textup{convFO}}$, since it violates the bound $I_4 \underset{\text{convFO}}{\leq} \frac{15}{16}$.

\subsection{For correlations with non-influenceable coarse-grained causal orders: $I_4 \leq_{\text{NIO}'} \frac{47}{48}$}
\label{app:proof_NIO'_bound}

Let us now relax the NIO assumption, and just consider the ``non-influenceable coarse-grained causal orders'' (NIO$'$) assumption of Eq.~\eqref{eq:def_NIO'}, that $p\big((\mathcal{K}_{n-1},k_n)\big|\vec x\big) = p\big((\mathcal{K}_{n-1},k_n)\big)$ does not depend on $\vec x$.
Note that it implies in particular, here, that
\begin{align}
    & \hspace{-3mm} p\big(\pi{:}D{\prec}C\big|x=y=0,t=1\big) \notag \\
    & = p\big((\mathcal{K}_2,k_3)=(\{A,B\},D)\big|\cancel{x=y=0,t=1}\big) + p\big((\mathcal{K}_2,k_3)=(\{A,D\},B)\big|\cancel{x=y=0,t=1}\big) \notag \\
    & \quad + p\big((\mathcal{K}_2,k_3)=(\{B,D\},A)\big|\cancel{x=y=0,t=1}\big) + p\big((\mathcal{K}_2,k_3)=(\{A,D\},C)\big|\cancel{x=y=0,t=1}\big) \notag \\
    & \quad + p\big((\mathcal{K}_2,k_3)=(\{B,D\},C)\big|\cancel{x=y=0,t=1}\big) + p\big((\mathcal{K}_1,k_2)=(\{D\},C)\big|\cancel{x=y=0,t=1}\big) \ = \ p\big(\pi{:}D{\prec}C\big)
\end{align}
does not depend on the inputs $x,y,t$.

Coming back to Eq.~\eqref{app:eq_intermediate_NIO_bound}---which, as we emphasised, holds for all causal correlations---we can now write (instead of Eq.~\eqref{app:eq_intermediate_NIO_bound2})
\begin{align}
    & J_{C\prec D} + p\big(\pi{:}D{\prec}C\big|x=y=0,t=1\big) \ge \frac13 J_{C\prec D} + p\big(\pi{:}D{\prec}C\big) \notag \\
    & \quad \ge \frac13 \Big[ p\big(\pi=(A,B,C,D)\big|x=1,y=0\big) + p\big(\pi=(B,A,C,D)\big|x=0,y=1\big) + p\big((\mathcal{K}_2,k_3)=(\{A,B\},C)\big|\cancel{x=y=1}\big) \notag \\[-1mm]
    & \qquad \qquad - p\big((k_1,k_2)=(A,B)\big|\cancel{x=1}\big) - p\big((k_1,k_2)=(B,A)\big|\cancel{y=1}\big) \notag \\
    & \qquad \qquad + p\big((k_1,k_2)=(A,C)\big|\cancel{x=1}\big) + p\big((k_1,k_2)=(B,C)\big|\cancel{y=1}\big) + p\big((k_1)=(C)\big|\cancel{z=1}\big) + \hspace{-10mm} \underbrace{3\,p\big(\pi{:}D{\prec}C\big)}_{\ge\,p(\pi{:}D{\prec}C)+2\,p((\mathcal{K}_2,k_3)=(\{A,B\},D))\qquad} \hspace{-10mm} \Big] \notag \\
    & \quad \ge \frac13 \Bigg[ \underbrace{p\big((\mathcal{K}_2,k_3)=(\{A,B\},C)\big) + p\big((k_1,k_2)=(A,C)\lor(B,C)\big) + p\big((k_1)=(C)\big) + p\big(\pi{:}D{\prec}C\big)}_{=\, 1} \notag \\
    & \qquad \qquad + p\big((\mathcal{K}_2,k_3)=(\{A,B\},D)\big) - \Big( \underbrace{p\big((k_1,k_2)=(A,B)\big) - p\big(\pi=(A,B,C,D)\big|x=1,y=0\big)}_{p(\pi=(A,B,D,C)|x=1,y=0)} \Big) \notag \\
    & \qquad \qquad + p\big((\mathcal{K}_2,k_3)=(\{A,B\},D)\big) - \Big( \underbrace{p\big((k_1,k_2)=(B,A)\big) - p\big(\pi=(B,A,C,D)\big|x=0,y=1\big)}_{p(\pi=(B,A,D,C)|x=0,y=1)} \Big) \Bigg] \notag \\[1mm]
    & \qquad = \frac13 \Big[ 1 + p\big(\pi=(B,A,D,C)\big|x=1,y=0\big) + p\big(\pi=(A,B,D,C)\big|x=0,y=1\big) \Big] \ge \frac13 .
\end{align}
Recalling again Eq.~\eqref{eq:bnd_I4_JCD_pDC}, we then obtain, for correlations with non-influenceable coarse-grained causal orders:
\begin{align}
    I_4 \leq 1 - \frac{1}{16} \Big( J_{C\prec D} + p\big(\pi{:}D{\prec}C\big|x=y=0,t=1\big) \Big) \underset{\text{NIO}'}{\leq} \frac{47}{48},
\end{align}
as in Eq.~\eqref{eq:bnd_I4_NIO'}.

\medskip

This bound can be reached for instance by the correlation 
\begin{align}
    p\big(a,b,c,d|x,y,z,t\big) = & \,\frac{2}{3}
    \left\{ \begin{array}{ll}
        \delta_{a,0}\,\delta_{b,0}\,\delta_{c,0}\,\delta_{d,zt} & \text{if}\ x=0 \\[1mm]
        \frac{1}{2}\,\delta_{b,y} \left\{ \begin{array}{ll}
        \delta_{c,0}\,\delta_{d,zt} & \text{if}\ y=a \\
        \delta_{d,0}\,\delta_{c,zt} & \text{if}\ y=\bar{a}
        \end{array} \right. & \text{if}\ x=1
    \end{array} \right. \,+\, \frac{1}{3}\,\delta_{b,y}\,\delta_{a,xy}
    \left\{ \begin{array}{ll}
        \delta_{d,0}\,\delta_{c,zt} & \text{if}\ x=0 \\[1mm]
        \delta_{c,0}\,\delta_{d,zt} & \text{if}\ x=1
    \end{array} \right. , \label{eq:saturate_NIO'}
\end{align}
 which can easily be seen to be causal. To see that it is in ${\cal P}_{\textup{NIO}'}$, notice that one can decompose it as
\begin{align}
    p\big((k_1,k_2,k_3,k_4),a,b,c,d|x,y,z,t\big) = & \frac{2}{3}\,\delta_{(k_1,k_2),(A,B)}
    \left\{ \begin{array}{ll}
        \delta_{a,0}\,\delta_{b,0}\,\delta_{(k_3,k_4),(C,D)}\,\delta_{c,0}\,\delta_{d,zt} & \text{if}\ x=0 \\[1mm]
        \frac{1}{2}\,\delta_{b,y} \left\{ \begin{array}{ll}
        \delta_{(k_3,k_4),(C,D)}\,\delta_{c,0}\,\delta_{d,zt} & \text{if}\ y=a \\
        \delta_{(k_3,k_4),(D,C)}\,\delta_{d,0}\,\delta_{c,zt} & \text{if}\ y=\bar{a}
        \end{array} \right. & \text{if}\ x=1
    \end{array} \right. \notag \\[1mm]
    & + \frac{1}{3}\,\delta_{(k_1,k_2),(B,A)}\,\delta_{b,y}\,\delta_{a,xy}
    \left\{ \begin{array}{ll}
        \delta_{(k_3,k_4),(D,C)}\,\delta_{d,0}\,\delta_{c,zt} & \text{if}\ x=0 \\[1mm]
        \delta_{(k_3,k_4),(C,D)}\,\delta_{c,0}\,\delta_{d,zt} & \text{if}\ x=1
    \end{array} \right. ,
\end{align}
such that
\begin{align}
     p\big((k_1,k_2,k_3,k_4)|x,y,z,t\big) = & \left\{ \begin{array}{ll}
    \frac{2}{3}\,\delta_{(k_1,k_2,k_3,k_4),(A,B,C,D)} + \frac{1}{3}\,\delta_{(k_1,k_2,k_3,k_4),(B,A,D,C)} & \text{if}\ x=0 \\[1mm]
    \frac{1}{3}\,\delta_{(k_1,k_2,k_3,k_4),(A,B,C,D)} + \frac{1}{3}\,\delta_{(k_1,k_2,k_3,k_4),(A,B,D,C)} + \frac{1}{3}\,\delta_{(k_1,k_2,k_3,k_4),(B,A,C,D)} & \text{if}\ x=1
\end{array} \right. .
\end{align}
It is then easy to verify that $p((k_1)=(A)|x,y,z,t)=p((k_1,k_2)=(A,B)|x,y,z,t)=\frac23$, $p((k_1)=(B)|x,y,z,t)=p((k_1,k_2)=(B,A)|x,y,z,t)=\frac13$, $p((\mathcal{K}_2,k_3)=(\{A,B\},C)|x,y,z,t)=p((\mathcal{K}_3,k_4)=(\{A,B,C\},D)|x,y,z,t)=\frac23$ and $p((\mathcal{K}_2,k_3)=(\{A,B\},D)|x,y,z,t)=p((\mathcal{K}_3,k_4)=(\{A,B,D\},C)|x,y,z,t)=\frac13$ do not depend on $x,y,z,t$ (with all other probabilities $p\big((\mathcal{K}_{n-1},k_n)\big|\vec x\big)$ being null), which indeed proves that the correlation is in $\mathcal{P}_{\textup{NIO}'}$---and not in $\mathcal{P}_{\textup{NIO}}$, since it violates the bound $I_4 \underset{\text{NIO}}{\leq} \frac{31}{32}$.


\subsection{For general causal correlations: $I_4 \leq_{\text{causal}} 1$}
\label{app:proof_causal_bound}

We conclude this appendix with the bound for general causal correlations, which is simply the trivial algebraic bound:
\begin{align}
    I_4 & = p\big(a=b=xy , d=zt\big) + p\big(\neg(a=b=xy) , c=zt\big) \leq p\big(a=b=xy\big) + p\big(\neg(a=b=xy)\big) = 1.
\end{align}

An example of a causal correlation that indeed reaches this algebraic maximum is
\begin{align}
    p(a,b,c,d|x,y,z,t) = \delta_{a,0}\,\delta_{b,0} \left\{ \begin{array}{ll}
    \delta_{c,0}\,\delta_{d,zt} & \text{if}\ xy=0 \\[1mm]
    \delta_{d,0}\,\delta_{c,zt} & \text{if}\ xy=1
\end{array} \right.,
\end{align}
which can be decomposed as
\begin{equation}
p((k_1,k_2,k_3,k_4),a,b,c,d|x,y,z,t) = \delta_{(k_1,k_2),(A,B)}\,\delta_{a,0}\,\delta_{b,0} \left\{ \begin{array}{ll}
    \!\!\delta_{(k_3,k_4),(C,D)}\,\delta_{c,0}\,\delta_{d,zt} & \text{if}\ xy=0 \\[1mm]
    \!\!\delta_{(k_3,k_4),(D,C)}\,\delta_{d,0}\,\delta_{c,zt} & \text{if}\ xy=1
\end{array} \right. ,
\end{equation}
in which the causal order between $C$ and $D$ depends on the product of inputs $xy$ (indeed the causal order has to be ``influenceable'' so as to violate the previous bounds).



\section{Description and characterisation of our different classes of quantum circuits}
\label{app:sec_classes}

In this appendix we provide more details on the description and characterisation of the different classes of quantum circuits with classical and quantum control of causal order considered in the paper. These are described within the wider framework of process matrices~\cite{oreshkov12}. We start by recalling, for completeness, the validity constraints for general process matrices that the characterisations of some of our classes refer to.


\subsection{Validity constraints for general process matrices}
\label{app:subsec_validity_cstr}


The process matrix framework was first introduced to characterise the set of all possible correlations that can be established (in a consistent manner) by a number of parties implementing operations that are locally described by the quantum formalism (as quantum instruments~\cite{davies70}), but without assuming \emph{a priori} that these are applied in any specific, well-defined causal order~\cite{oreshkov12}. Under some reasonable assumptions (in particular: dependency of the probabilities on the realised operations only rather than on the full quantum instruments; linearity of the probabilities to preserve the interpretation of probabilistic mixtures of operations and coarse-graining of outcomes), it was shown that all such correlations could be written in the form of the generalised Born rule of Eq.~\eqref{eq:Born_rule}, for some ``process matrix'' $W \in \mathcal{L}(\mathcal{H}^{A_{\mathcal{N}}^{IO}})$ (where $\mathcal{N}=\{1,\ldots,N\}$ refers to the set of parties, each having input/output spaces $\mathcal{H}^{A_k^I}/\mathcal{H}^{A_k^O}$, and with $\mathcal{H}^{A_{\mathcal{N}}^{IO}} = \bigotimes_{k\in\N}\mathcal{H}^{A_k^{IO}} = \bigotimes_{k\in\N}\mathcal{H}^{A_k^I}\otimes\mathcal{H}^{A_k^O}$).

Requiring that the probabilities thus obtained are nonnegative, even when the parties share other auxiliary systems and their instruments can also act on these, imposes that the process matrix must be positive semidefinite (PSD): $W\ge 0$. Recalling that the elements of a quantum instrument must sum to a trace-preserving (TP) map, and that the TP condition for a map $\M_k: \L(\HS^{A_k^I}) \to \L(\HS^{A_k^O})$ translates in terms of its Choi matrix into $\Tr_{A_k^O} M_k = \id^{A_k^I}$, then the requirement that the probabilities must be normalised, on the other hand, can be phrased as follows:
\begin{align}
    \forall\, M_1\in\L(\HS^{A_1^{IO}}),\ldots,M_N\in\L(\HS^{A_N^{IO}}) \ \text{ such that } \ \Tr_{A_1^O} M_1 = \id^{A_1^I},\ldots,\Tr_{A_N^O} M_N = \id^{A_N^I}, \ \ \Tr [\Big(\bigotimes_k M_k\Big)^{\!T} \, W] = 1. \label{eq:cstr_W}
\end{align}
This was shown to be equivalent to imposing some linear and affine constraints on $W$, which can be written as~\cite{Araujo15,wechs19}%
\footnote{We note that another equivalent formulation of these constraints was also given in terms of ``allowed'' and ``forbidden'' terms in a Hilbert-Schmidt basis decomposition of $W$~\cite{oreshkov12,Oreshkov16}.}
\begin{align}
    \forall \,\emptyset \subsetneq \K \subseteq \N, \, {}_{\prod_{k\in\K}[1-A_k^O]}\Tr_{A_{\N\backslash\K}^{IO}}W = 0 \quad \text{and} \quad \Tr W = d_\N^O, \label{eq:validityW}
\end{align}
where we used the notation ${}_{[1-A_k^O]}W\coloneqq W-(\Tr_{A_k^O} W)\otimes\frac{\id^{A_k^O}}{d_k^O}$ (with $d_k^O$ denoting the dimension of $\HS^{A_k^O}$), such that ${}_{\prod_{k\in\K}[1-A_k^O]}W = {}_{[1-A_{k_1}^O]}({}_{[1-A_{k_2}^O]}(\cdots({}_{[1-A_{k_{|\K|}}^O]}W)))$ for $\K=\{k_1,k_2,\ldots,k_{|\K|}\}$, and where $d_\N^O \coloneqq \prod_{k\in\N}d_k^O$ is the product of the dimensions of all parties' output spaces.

As recalled in the main text, another version of the process matrix framework was introduced in Ref.~\cite{araujo17}, with some ``open'' past and future spaces $\HS^P, \HS^F$. Here the process matrix acts as a ``supermap''~\cite{Chiribella08supermaps} that transforms the parties' local maps to a new quantum map from $\HS^P$ to $\HS^F$, given by the further generalised Born rule of Eq.~\eqref{eq:Born_rule_PF}. Requiring that completely positive (CP) maps thereby get transformed to a CP map (even when involving auxiliary systems: the supermap must be ``completely CP-preserving'') imposes again that $W$ must be PSD. The requirement that TP maps (corresponding e.g. to the sum of the parties' instrument elements) get transformed to a TP map (the supermap must be ``TP-preserving''), on the other hand, can be written here as in Eq.~\eqref{eq:cstr_W}, just replacing the last equality by $\Tr_F [(\bigotimes_k M_k)^T \, W] = \id^P$. It can be shown to be equivalent to the following linear and affine constraints:%
\footnote{These can be verified to be equivalent to the set of constraints obtained (after certain simplifications) from Eq.~\eqref{eq:cstr_W}, when one attributes $\HS^P$ and $\HS^F$ to two additional parties with trivial input and output spaces, respectively.}\}
\begin{align}
    \forall \,\emptyset \subsetneq \K \subseteq \N, \, {}_{\prod_{k\in\K}[1-A_k^O]}\Tr_{A_{\N\backslash\K}^{IO}F}W = 0 \quad \text{and} \quad \Tr_{A_{\N}^{IO}F}W = d_\N^O \, \id^P. \label{eq:validityW_PF}
\end{align}

\medskip

Let us emphasise again that the validity constraints of Eqs.~\eqref{eq:validityW} and~\eqref{eq:validityW_PF} correspond to the requirement that the generalised Born rule of Eq.~\eqref{eq:Born_rule} gives the constant value 1, or that the alternative version of Eq.~\eqref{eq:Born_rule_PF} returns a trace-preserving global map $M_{\vec a|\vec x}^{PF}$, whenever one plugs in TP external operations (obtained e.g.\ as the sum of the elements of the parties' instruments).
When dealing with process matrices, one is often interested in the linear parts of the validity constraints, ignoring the affine part, i.e.\ ignoring the constraint $\Tr W = d_\N^O$ in Eq.~\eqref{eq:validityW}, or only imposing $\Tr_{A_{\N}^{IO}F}W \propto \id^P$ in Eq.~\eqref{eq:validityW_PF}. One then refers to matrices that are valid process matrices \emph{up to normalisation} only%
\footnote{Notice that this includes in particular the null matrix, $W=0$.}%
---as in the characterisations of our classes \textup{\textsf{QC-NICC}} and \textup{\textsf{QC-NIQC}}, see Eqs.~\eqref{eq:cstr_NICC} and~\eqref{eq:cstr_NIQC}.
Requiring validity up to normalisation only, for a given $W$, therefore has the following interpretation: 
when plugging in TP external operations, the generalised Born rules of Eq.~\eqref{eq:Born_rule} or~\eqref{eq:Born_rule_PF} must return a constant value, or a global induced map whose output state has a constant trace, respectively, whatever the choice of the TP external operations. 



\subsection{Quantum circuits with classical control of causal order (QC-CCs)}
\label{app:subsec_QCCC_classes}

Let us now come to a more in-depth presentation of QC-CCs, and of the subclasses of QC-convFOs and QC-NICCs that we considered in this work. Secs.~\ref{app:QC-CC} (general QC-CCs) and~\ref{app:QC-convFO} (QC-convFOs) below are essentially just reviews of previous work, to set up the stage for the presentation and characterisation of our new class of QC-NICCs in Sec.~\ref{app:def_QC-NICC}.

\medskip

QC-CCs were introduced and characterised in Ref.~\cite{wechs21}, which we refer to for more details. One technical ingredient that we will use below is the so-called \emph{link product}~\cite{Chiribella08,Chiribella09}. It is defined, for two matrices $M_1^{XY}\in\L(\HS^{XY})$ and $M_2^{XY}\in\L(\HS^{YZ})$ that share a common space $\HS^Y$, as
\begin{align}
    M_1^{XY} * M_2^{YZ} \coloneqq & \big( \id^{XZ} \otimes \bbra{\id}^{YY} \big) (M_1^{XY} \otimes M_2^{YZ}) \big( \id^{XZ} \otimes \kket{\id}^{YY} \big) \notag \\
    =& \Tr_{Y} \big[ \big( (M_1^{XY})^{T_Y} \otimes \id^Z \big) \big( \id^X \otimes M_2^{YZ} \big) \big] \quad \in \L\big(\HS^{XZ}\big), \label{eq:def_mixed_link_product}
\end{align}
where $\kket{\id}^{YY}\coloneqq \sum_j \ket{i}^Y\otimes\ket{i}^Y$ denotes the unnormalised maximally entangled state (defined for two copies of the space $\HS^Y$ with computational basis $\{\ket{i}^Y\}_i$), and where $\Tr_{Y}$ and ${}^{T_Y}$ denote the partial trace and partial transpose over $\HS^Y$, respectively. The link product corresponds in the Choi picture to the composition of maps: if $M_1^{XY}$ and $M_2^{YZ}$ are the Choi matrices of two linear maps $\M_1: \L(\HS^X)\to\L(\HS^Y)$ and $\M_2: \L(\HS^Y)\to\L(\HS^Z)$, then $M_1^{XY} * M_2^{YZ}$ is the Choi matrix of their composition $\M_2 \circ \M_1: \L(\HS^X)\to\L(\HS^Z)$. (The same interpretation in terms of composition also applies if the output and input spaces of $\M_1$ and $\M_2$ do not match~\cite{Chiribella08,Chiribella09,wechs21}.)

The link product is commutative (up to a re-ordering of the tensor products) and associative (provided each Hilbert space is involved at most twice in an $n$-fold link product---as will always be the case here). It reduces to a standard tensor product $M_1^X * M_2^Z = M_1^X \otimes M_2^Z$ if the space $\HS^Y$ is trivial, and to a scalar product $M_1^Y * M_2^Y = \Tr [(M_1^Y)^T M_2^Y]$ if the spaces $\HS^X$ and $\HS^Z$ are trivial.
Noticing that the Choi matrix of the preparation of a state $\rho$ coincides with the density matrix $\rho$ itself, one can write the output state of a map $\M$ (with Choi matrix $M$) applied to $\rho$ as the composition $\M(\rho) = \rho*M$.
Notice also that the generalised Born rule of Eq.~\eqref{eq:Born_rule_PF} can be written in a simple form as a link product, namely: $M_{\vec a|\vec x}^{PF} = \big(\bigotimes_k M^{A_k}_{a_k|x_k}\big) * W$. \label{page:born_rul_PF_link_prod}


\subsubsection{General QC-CCs}
\label{app:QC-CC}

\paragraph*{Construction of a QC-CC.}

As briefly introduced in the main text, a QC-CC consists in the application of a number of ``internal operations'', each of which determines which ``external operation'' (implemented by one of the $N$ parties $A_k$) is to be applied next---with each of the latter being applied once and only once by the end of the protocol.

One way to understand this is to consider that each internal operation corresponds to a quantum instrument $\{\M_{(k_1,\ldots,k_n)}^{\to k_{n+1}}\}_{k_{n+1}\notin\{k_1,\ldots,k_n\}}$, whose classical output value $k_{n+1}$ indicates the label of the next external operation to be applied, conditioned on the previous operations being those labelled $(k_1,\ldots,k_n)$, in that order. 
The instrument corresponding to the first internal operation consists of CP maps $\M_{\emptyset}^{\to k_1}: \L(\HS^P) \to \L(\HS^{A_{k_1}^I\alpha_1})$ that transform the input state in the ``global past'' space $\HS^P$ into a state in the input space $\HS^{A_{k_1}^I}$ of the first operation to be applied, as well as in some auxiliary ``memory'' space $\HS^{\alpha_1}$.%
\footnote{The auxiliary ``memory'' systems are not touched by the external operations. Notice that these may just be trivial.}
The subsequent internal operations, for $n=1,\ldots,N-1$, consist of CP maps $\M_{(k_1,\ldots,k_n)}^{\to k_{n+1}}: \L(\HS^{A_{k_n}^O\alpha_n}) \to \L(\HS^{A_{k_{n+1}}^I\alpha_{n+1}})$ that transform (conditioned on the previous external operations being $(k_1,\ldots,k_n)$, in that order) the output state of the latest external operation, together with the memory system, into a state in the input space $\HS^{A_{k_{n+1}}^I}$ of the next operation to be applied, as well as in some new memory space $\HS^{\alpha_{n+1}}$. Finally, the last internal operation consists of just a single CPTP map $\M_{(k_1,\ldots,k_N)}^{\to F}: \L(\HS^{A_{k_N}^O\alpha_N}) \to \L(\HS^F)$ (since there is no choice of next operation to be made) that transforms (conditioned on all external operations having been applied in the order $(k_1,\ldots,k_N)$) the output state of the last external operation, together with the memory system, into a state in the ``global future'' space $\HS^F$.

\medskip

\begin{figure*}[t]
\centering
\includegraphics[width=\columnwidth]{QCCC_full.pdf}
\caption{Graphical representation of a QC-CC: a more detailed version than Fig.~\ref{fig:QCCC_graph} (clarifying here the internal structure of the circuit operations $\tilde{\M}_n$), reproduced from Fig.~9 of Ref.~\cite{wechs21}.}
\label{fig:QCCC_graph_full}
\end{figure*}

Another equivalent way to describe such a protocol---as depicted in Fig.~\ref{fig:QCCC_graph} of the main text, or with more details in Fig.~\ref{fig:QCCC_graph_full} here---is to encode the output of these instruments into a physical (effectively classical) system and consider the internal operations to also act on this system, which is used to control the subsequent operations. This can be done by introducing, for each time-slot $t_n$ ($n=1,\ldots,N$) at which an external operation is to be applied, a Hilbert space $\HS^{C_n}$ carrying orthogonal control states of the form
\begin{align}
    [\![(k_1,\ldots,k_n)]\!]^{C_n} \coloneqq \ketbra{(k_1,\ldots,k_n)}{(k_1,\ldots,k_n)}^{C_n}, \label{eq:def_classical_Cn}
\end{align}
which keeps track of all previous external operations, as well as of the current one to be applied.

In order to define a controlled version of the external operations, it is assumed for simplicity that all input Hilbert spaces $\HS^{A_k^I}$ (all output Hilbert spaces $\HS^{A_k^O}$, respectively) of all external operations are isomorphic. One can then introduce, for each time-slot $t_n$, a ``generic'' input Hilbert space $\HS^{\tilde{A}_n^I}$ (a ``generic'' output Hilbert space $\HS^{\tilde{A}_n^O}$, resp.), isomorphic to all $\HS^{A_k^I}$'s (isomorphic to all $\HS^{A_k^O}$'s, resp.). In this way, when an external operation%
\footnote{Here for simplicity we allow for some double-use of notation, using the same $A_k$ for the Choi matrix of an external operation and the party that implements it, as considered in the main text. The operations $A_k$ (in the Choi picture) considered here correspond to the individual CP maps $M_{a_k|x_k}^{A_k}$ considered in the main text to be part of each party's instrument.}
$\A_{k_n}:\L(\HS^{A_{k_n}^I})\to\L(\HS^{A_{k_n}^O})$ (with Choi matrix $A_{k_n}\in\L(\HS^{A_{k_n}^{IO}})$) is applied at time-slot $t_n$, one can identify it formally with an operation of the type $\tilde{\A}_{k_n}:\L(\HS^{\tilde{A}_n^I})\to\L(\HS^{\tilde{A}_n^O})$ (with Choi matrix $\tilde{A}_{k_n}:\L(\HS^{\tilde{A}_n^{IO}})$). This allows one to write all the external operations that may be applied at time-slot $t_n$ as acting in the same generic input and output spaces, and to embed these into some ``larger'' controlled operation $\tilde{\A}_n$, which applies the desired operation $\tilde{\A}_{k_n}$ depending on the state of the control (more specifically, on its last label $k_n$):
\begin{align}
\tilde \A_n \coloneqq & \sum_{(k_1,\ldots,k_n)} \tilde\A_{k_n} \otimes \bigpi_{(k_1,\ldots,k_n)}^{C_n \to C_n'}\ : \ \L(\HS^{\tilde A_n^I C_n}) \to \L(\HS^{\tilde A_n^O C_n'}), \label{eq:tilde_An_QCCC}
\end{align}
where for later convenience we introduced a copy $\HS^{C_n'}$ of the Hilbert space $\HS^{C_n}$, and where $\bigpi_{(k_1,\ldots,k_n)}^{C_n \to C_n'}$ is the (classical) map that projects the control system onto the state $[\![(k_1,\ldots,k_n)]\!]^{C_n}$, while re-labelling the control system $C_n$ to $C_n'$.

Similarly, one can formally write the internal operations $\M_{(k_1,\ldots,k_n)}^{\to k_{n+1}}: \L(\HS^{A_{k_n}^O\alpha_n}) \to \L(\HS^{A_{k_{n+1}}^I\alpha_{n+1}})$ (for each $n=1,\ldots,N-1$) as maps of the type $\tilde{\M}_{(k_1,\ldots,k_n)}^{\to k_{n+1}}: \L(\HS^{\tilde{A}_n^O\alpha_n}) \to \L(\HS^{\tilde{A}_{n+1}^I\alpha_{n+1}})$ acting in the generic Hilbert space introduced above. These can then be embedded into some ``larger'' operation $\tilde{\M}_{n+1}$ that also involves the control system: upon receiving the latter in the state $[\![(k_1,\ldots,k_n)]\!]^{C_n'}$ (as outputted by the operation $\tilde \A_n$), $\tilde{\M}_{n+1}$ applies the operations $\tilde{\M}_{(k_1,\ldots,k_n)}^{\to k_{n+1}}$ and updates the control system into the corresponding state $[\![(k_1,\ldots,k_n,k_{n+1})]\!]^{C_n}$. Formally:
\begin{align}
\tilde \M_{n+1} \coloneqq & \sum_{(k_1,\ldots,k_n,k_{n+1})} \tilde\M_{(k_1,\ldots,k_n)}^{\to k_{n+1}} \otimes \bigpi_{(k_1,\ldots,k_n),k_{n+1}}^{C_n' \to C_{n+1}} \ : \ \L(\HS^{\tilde A_n^O \alpha_nC_n'}) \to \L(\HS^{\tilde A_{n+1}^I \alpha_{n+1}C_{n+1}}), \label{eq:tilde_Mn1_QCCC}
\end{align}
where $\bigpi_{(k_1,\ldots,k_n),k_{n+1}}^{C_n' \to C_{n+1}}: \L(\HS^{C_n'}) \to \L(\HS^{C_{n+1}})$ is the (classical) map that projects the control system onto $[\![(k_1,\ldots,k_n)]\!]^{C_n'}$ and updates it to $[\![(k_1,\ldots,k_n,k_{n+1})]\!]^{C_{n+1}}$.
For the first and last internal operations, one similary defines
\begin{align}
\tilde \M_1 \coloneqq  & \sum_{k_1} \tilde\M_\emptyset^{\to k_1} \otimes \bigpi_{\emptyset,k_1}^{\emptyset \to C_1} \ : \ \L(\HS^P) \to \L(\HS^{\tilde A_1^I \alpha_1C_1}) \label{eq:tilde_M1_QCCC} \\
\text{and} \quad \tilde \M_{N+1} \coloneqq & \sum_{(k_1,\ldots,k_N)} \tilde\M_{(k_1,\ldots,k_N)}^{\to F} \otimes \bigpi_{(k_1,\ldots,k_N),F}^{C_N' \to \emptyset} \ : \ \L(\HS^{\tilde A_N^O \alpha_NC_N'}) \to \L(\HS^F), \label{eq:tilde_MN1_QCCC}
\end{align}
where $\bigpi_{\emptyset,k_1}^{\emptyset \to C_1}$ and $\bigpi_{(k_1,\ldots,k_N),F}^{C_N' \to \emptyset}$ are the maps that create the initial control states $[\![(k_1)]\!]^{C_1}$ and that project onto the final control state $[\![(k_1,\ldots,k_N)]\!]^{C_N'}$, respectively.

In the Choi representation, all these embedding operations are written
\begin{align}
\tilde A_n = & \sum_{(k_1,\ldots,k_n)} \tilde A_{k_n} \otimes [\![(k_1,\ldots,k_n)]\!]^{C_n} \otimes [\![(k_1,\ldots,k_n)]\!]^{C_n'} \ \in \L(\HS^{\tilde A_n^I C_n\tilde A_n^O C_n'}), \label{eq:Choi_An_QCCC} \\[2mm]
\tilde M_1 = & \sum_{k_1} \tilde M_\emptyset^{\to k_1} \otimes [\![(k_1)]\!]^{C_1} \ \in \L(\HS^{P\tilde A_1^I \alpha_1C_1}), \label{eq:def_tilde_M1_QCCC}\\[2mm]
\tilde M_{n+1} = & \sum_{(k_1,\ldots,k_n,k_{n+1})} \tilde M_{(k_1,\ldots,k_n)}^{\to k_{n+1}} \otimes [\![(k_1,\ldots,k_n)]\!]^{C_n'} \otimes [\![(k_1,\ldots,k_n,k_{n+1})]\!]^{C_{n+1}} \ \in \L(\HS^{\tilde A_n^O \alpha_nC_n'\tilde A_{n+1}^I \alpha_{n+1}C_{n+1}}) \notag \\[-3mm]
& \hspace{110mm} (\text{for }n=1,\ldots,N-1), \label{eq:Choi_Mn1_QCCC}\\[2mm]
\tilde M_{N+1} =& \sum_{(k_1,\ldots,k_N)} \tilde M_{(k_1,\ldots,k_N)}^{\to F} \otimes [\![(k_1,\ldots,k_N)]\!]^{C_N'} \ \in \L(\HS^{\tilde A_N^O \alpha_NC_N'F}). \label{eq:def_tilde_MN1_QCCC}
\end{align}
These allow one, in particular, to conveniently evaluate the state of all systems at any point in the circuit. Consider, for that, inputting some state $\rho\in\L(\HS^P)$ in the global past of the circuit. The states $\varrho_{(n)}'$ before and $\varrho_{(n+1)}$ after each operation $\tilde{\M}_{n+1}$ are found (recursively) to be
\begin{align}
\varrho_{(0)}' & = \rho \quad \in \L(\HS^P), \label{eq:link_prod_rho_tilde_0} \\[3mm]
\varrho_{(n)}' & = \rho * \tilde M_1 * \tilde A_1 * \tilde M_2 * \cdots * \tilde M_n * \tilde A_n \notag \\
& = \sum_{(k_1,\ldots,k_n)} \big( \rho \otimes A_{k_1} \otimes \cdots \otimes A_{k_n} \big) * \big(M_\emptyset^{\to k_1} * M_{(k_1)}^{\to k_2} * \cdots * M_{(k_1,\ldots,k_{n-1})}^{\to k_n} * \kketbra{\id}{\id}^{A^O_{k_n}\tilde A_n^O}\big) \otimes [\![(k_1,\ldots,k_n)]\!]^{C_n'} \notag \\[-2mm]
& \hspace{100mm} \in \L(\HS^{\tilde A_n^O\alpha_n C_n'}) \quad \text{ for } n\ge 1 \label{eq:link_prod_rho_tilde_M1_tilde_An}
\end{align}
and
\begin{align}
\varrho_{(n+1)} & = \rho * \tilde M_1 * \tilde A_1 * \tilde M_2 * \cdots * \tilde M_n * \tilde A_n * \tilde M_{n+1} \notag \\
& = \sum_{(k_1,\ldots,k_n,k_{n+1})} \big( \rho \otimes A_{k_1} \otimes \cdots \otimes A_{k_n} \big) * \big( M_\emptyset^{\to k_1} * M_{(k_1)}^{\to k_2} * \cdots * M_{(k_1,\ldots,k_{n-1})}^{\to k_n} * M_{(k_1,\ldots,k_n)}^{\to k_{n+1}} * \kketbra{\id}{\id}^{A^I_{k_{n+1}}\tilde A_{n+1}^I} \big) \notag \\[-2mm]
& \hspace{50mm} \otimes [\![(k_1,\ldots,k_n,k_{n+1})]\!]^{C_{n+1}} \ \in \L(\HS^{\tilde A_{n+1}^I\alpha_{n+1} C_{n+1}}) \quad \text{ for } n\le N-1, \label{eq:link_prod_rho_tilde_M1_tilde_Mn1} \\[3mm]
\varrho_{(N+1)} & = \rho * \tilde M_1 * \tilde A_1 * \tilde M_2 * \cdots * \tilde M_N * \tilde A_N * \tilde M_{N+1} \notag \\
& = \sum_{(k_1,\ldots,k_N)} \big( \rho \otimes A_{k_1} \otimes \cdots \otimes A_{k_N} \big) * \big( M_\emptyset^{\to k_1} * M_{(k_1)}^{\to k_2} * \cdots * M_{(k_1,\ldots,k_{N-1})}^{\to k_N} * M_{(k_1,\ldots,k_N)}^{\to F} \big) \notag \\[-1mm]
& = \big( \rho \otimes A_1 \otimes \cdots \otimes A_N \big) * \Big( \sum_{(k_1,\ldots,k_N)} M_\emptyset^{\to k_1} * M_{(k_1)}^{\to k_2} * \cdots * M_{(k_1,\ldots,k_{N-1})}^{\to k_N} * M_{(k_1,\ldots,k_N)}^{\to F} \Big) \quad \in \L(\HS^F), \label{eq:link_prod_rho_tilde_M1_tilde_MN1}
\end{align}
where $\kketbra{\id}{\id}^{A^O_{k_n}\tilde A_n^O}$ and $\kketbra{\id}{\id}^{A^I_{k_{n+1}}\tilde A_{n+1}^I}$ in Eqs.~\eqref{eq:link_prod_rho_tilde_M1_tilde_An} and~\eqref{eq:link_prod_rho_tilde_M1_tilde_Mn1} simply represent some trivial mappings from the external operations' output and input spaces $\HS^{A^O_{k_n}}$ and $\HS^{A^I_{k_{n+1}}}$ to the corresponding generic output and input spaces $\HS^{\tilde A_n^O}$ and $\HS^{A^I_{k_{n+1}}\tilde A_{n+1}^I}$ (notice how the tildes were removed between the first and second lines in each equation).

\bigskip

\paragraph*{Trace-preserving conditions.}

In order to define a TP-preserving quantum circuit---such that when one plugs in TP external operations, the induced global map remains TP---one requires all internal operations $\tilde{\M}_{n+1}$ to preserve the trace of their input state (they must be TP on their \emph{effective} input space, in which their input state $\varrho_{(n)}'$ may effectively be found). In fact, a stronger condition is imposed here: the control system must evolve in a consistent way, so that for any $n\le N-1$ and any given sequence $(k_1,\ldots,k_n)$, the probabilities of finding the control in the state $[\![(k_1,\ldots,k_n,k_{n+1})]\!]^{C_{n+1}}$ after the operation $\tilde{\M}_{n+1}$ (and of the operations $A_{k_1},\ldots,A_{k_n}$ to be applied, when these are part of quantum instruments) sum up, for all possible $k_{n+1}\notin\{k_1,\ldots,k_n\}$, to the probability of finding the control in the state $[\![(k_1,\ldots,k_n)]\!]^{C_n'}$ before $\tilde{\M}_{n+1}$ (and of the operations $A_{k_1},\ldots,A_{k_n}$ to be applied).
From Eqs.~\eqref{eq:link_prod_rho_tilde_M1_tilde_An} and~\eqref{eq:link_prod_rho_tilde_M1_tilde_Mn1}, these probabilities are
\begin{align}
& \sum_{k_{n+1}} \Tr[(\id^{\tilde A_{n+1}^I \alpha_{n+1}} \otimes [\![ (k_1,\ldots,k_n,k_{n+1}) ]\!]^{C_{n+1}})\varrho_{(n+1)}] \notag \\[-1mm]
& \hspace{15mm} = \sum_{k_{n+1}} \Tr\big[ \big( \rho \otimes A_{k_1} \otimes \cdots \otimes A_{k_n} \big) * \big( M_\emptyset^{\to k_1} * M_{(k_1)}^{\to k_2} * \cdots * M_{(k_1,\ldots,k_{n-1})}^{\to k_n} * M_{(k_1,\ldots,k_n)}^{\to k_{n+1}} \big) \big] \notag \\
& \hspace{15mm} = \Tr\big[\big(\rho \otimes A_{k_1} \otimes \cdots \otimes A_{k_n} \big)^T \sum_{k_{n+1}} \Tr_{A_{k_{n+1}}^I\alpha_{n+1}} ( M_\emptyset^{\to k_1} * M_{(k_1)}^{\to k_2} * \cdots * M_{(k_1,\ldots,k_{n-1})}^{\to k_n} * M_{(k_1,\ldots,k_n)}^{\to k_{n+1}} ) \big]. \label{eq:tr_varrho_n_1_QCCC}
\end{align}
and
\begin{align}
\Tr\big[(\id^{\tilde A_O^n\alpha_n} \otimes [\![ (k_1,\ldots,k_n) ]\!]^{C_n'})\varrho_{(n)}'\big] = \Tr\big[ \big( \rho \otimes A_{k_1} \otimes \cdots \otimes A_{k_n} \big) * \big(M_\emptyset^{\to k_1} * M_{(k_1)}^{\to k_2} * \cdots * M_{(k_1,\ldots,k_{n-1})}^{\to k_n} \big) \big] \notag \\
 = \Tr\big[\big(\rho \otimes A_{k_1} \otimes \cdots \otimes A_{k_n} \big)^T \big( \Tr_{\alpha_n} ( M_\emptyset^{\to k_1} * M_{(k_1)}^{\to k_2} * \cdots * M_{(k_1,\ldots,k_{n-1})}^{\to k_n} \big) \big]. \label{eq:tr_varrho_n_QCCC}
\end{align}
As these two expressions must be equal for all possible $\rho \otimes A_{k_1} \otimes \cdots \otimes A_{k_n}$, which span the whole space $\L(\HS^{PA_{\{k_1,\ldots,k_n\}}^{IO}})$, then the second terms inside both final traces must themselves be equal:
\begin{align}
\sum_{k_{n+1}} \Tr_{A_{k_{n+1}}^I\alpha_{n+1}} ( M_\emptyset^{\to k_1} * M_{(k_1)}^{\to k_2} * \cdots * M_{(k_1,\ldots,k_{n-1})}^{\to k_n} * M_{(k_1,\ldots,k_n)}^{\to k_{n+1}} ) = \Tr_{\alpha_n} ( M_\emptyset^{\to k_1} * M_{(k_1)}^{\to k_2} * \cdots * M_{(k_1,\ldots,k_{n-1})}^{\to k_n} ) \otimes \id^{A_{k_n}^O}. \label{eq:QCCC_TP_n}
\end{align}
For the limiting cases $n=0$ and $n=N$, we correspondingly obtain the constraints:
\begin{align}
\sum_{k_1} \Tr_{A_{k_1}^I\alpha_1} ( M_\emptyset^{\to k_1} ) = \id^P \label{eq:QCCC_TP_0}
\end{align}
and
\begin{align}
\Tr_F ( M_\emptyset^{\to k_1} * M_{(k_1)}^{\to k_2} * \cdots * M_{(k_1,\ldots,k_{N-1})}^{\to k_N} * M_{(k_1,\ldots,k_N)}^{\to F} ) = \Tr_{\alpha_N} ( M_\emptyset^{\to k_1} * M_{(k_1)}^{\to k_2} * \cdots * M_{(k_1,\ldots,k_{N-1})}^{\to k_N} ) \otimes \id^{A_{k_N}^O}. \label{eq:QCCC_TP_N}
\end{align}

\bigskip

\paragraph*{Process matrix description and characterisation.}

The expression for $\varrho_{N+1}$ in Eq.~\eqref{eq:link_prod_rho_tilde_M1_tilde_MN1} allows one to readily obtain the process matrix description of the QC-CC under consideration. Indeed, it follows from the generalised Born rule of Eq.~\eqref{eq:Born_rule_PF} (or its form given on p.~\pageref{page:born_rul_PF_link_prod} after the introduction of the link product) that the final state in the global future should be $\varrho_{N+1} = ( \rho \otimes A_1 \otimes \cdots \otimes A_N ) * W$. 
Since the $\rho \otimes A_1 \otimes \cdots \otimes A_N$'s span the whole space $\L(\HS^{PA_\N^{IO}})$, there is only one matrix $W$ that gives the correct output state through this expression. From Eq.~\eqref{eq:link_prod_rho_tilde_M1_tilde_MN1} we can thus directly identify the process matrix of the QC-CC under consideration to be 
\begin{align}
    W = \sum_{(k_1,\ldots,k_N)} M_\emptyset^{\to k_1} * M_{(k_1)}^{\to k_2} * \cdots * M_{(k_1,\ldots,k_{N-1})}^{\to k_N} * M_{(k_1,\ldots,k_N)}^{\to F} \quad \in \L(\HS^{PA_\N^{IO}F}). \label{eq:W_QCCC}
\end{align}

\medskip

Defining, for all $n=1,\ldots,N$ and all $(k_1,\ldots,k_n)$,
\begin{align}
    W_{(k_1,\ldots,k_n)} & \coloneqq \Tr_{\alpha_n} \big( M_\emptyset^{\to k_1} * M_{(k_1)}^{\to k_2} * \cdots * M_{(k_1,\ldots,k_{n-1})}^{\to k_n} \big) \quad \in \L(\HS^{PA_{\{k_1,\ldots,k_{n-1}\}}^{IO}A_{k_n}^I}), \label{eq:def_Wk1_kn_QCCC} \\
    W_{(k_1,\ldots,k_N,F)} & \coloneqq M_\emptyset^{\to k_1} * M_{(k_1)}^{\to k_2} * \cdots * M_{(k_1,\ldots,k_{N-1})}^{\to k_N} * M_{(k_1,\ldots,k_N)}^{\to F} \quad \in \L(\HS^{PA_\N^{IO}F}), \label{eq:def_Wk1_kN_F_QCCC}
\end{align}
then it follows directly from Eq.~\eqref{eq:W_QCCC} and the TP conditions of Eqs.~\eqref{eq:QCCC_TP_n}--\eqref{eq:QCCC_TP_N} that the process matrix $W \, (\ge 0)$ of a QC-CC has a characterisation as in Eq.~\eqref{eq:charact_W_QCCC_decomp}.

Conversely, from any decomposition of a matrix $W$ in terms of PSD matrices $W_{(k_1,\ldots,k_N,F)}$ and $W_{(k_1,\ldots,k_n)}$ as in Eq.~\eqref{eq:charact_W_QCCC_decomp}, one can explicitly reconstruct (in a non-unique manner) the internal operations $M_{(k_1,\ldots,k_n)}^{\to k_{n+1}}$ and $M_{(k_1,\ldots,k_N)}^{\to F}$ of a QC-QC (satisfying the required TP conditions), whose composition reproduces $W_{(k_1,\ldots,k_n)}$, $W_{(k_1,\ldots,k_N,F)}$ and $W$ as in Eqs.~\eqref{eq:W_QCCC}--\eqref{eq:def_Wk1_kN_F_QCCC} above. This shows that Eq.~\eqref{eq:charact_W_QCCC_decomp} is also a sufficient condition for $W$ to be a QC-CC.
An explicit procedure for such a reconstruction was detailed in Appendix~B of Ref.~\cite{wechs21}.


\subsubsection{Convex mixtures of quantum circuits with fixed causal order (QC-convFOs)}
\label{app:QC-convFO}

\paragraph*{Quantum circuits with fixed causal order (QC-FOs).}

QC-FOs have been described and characterised previously, under the alternative names of channels with memory~\cite{Kretschmann05}, quantum strategies~\cite{Gutoski06}, or quantum combs~\cite{Chiribella08,Chiribella09}. One may describe them in a similar and in fact much simpler way to QC-CCs above, without the need to introduce the control system. For a given fixed order $(k_1,\ldots,k_N)$, the internal operations would simply be of the form $\tilde{\M}_{n+1} = \tilde{\M}_{(k_1,\ldots,k_n)}^{\to k_{n+1}}$. The TP conditions they satisfy are as in Eqs.~\eqref{eq:QCCC_TP_n}--\eqref{eq:QCCC_TP_N}, just without the sums $\sum_{k_{n+1}}, \sum_{k_1}$. One can identify their process matrix representation in the same way as we did above, and one simply gets
\begin{align}
    W = W_{(k_1,\ldots,k_N,F)} = M_\emptyset^{\to k_1} * M_{(k_1)}^{\to k_2} * \cdots * M_{(k_1,\ldots,k_{N-1})}^{\to k_N} * M_{(k_1,\ldots,k_N)}^{\to F} \quad \in \L(\HS^{PA_\N^{IO}F}). \label{eq:W_QCFO}
\end{align}
From the TP conditions, and defining%
\footnote{Notice that in contrast to the general QC-CC case, the matrices $W_{(k_1,\ldots,k_n)}$ defined here are all valid process matrices (indeed, one can readily verify explicitly that the constraints of Eq.~\eqref{eq:validityW_PF} are satisfied). This implies in particular that the matrices $W_{(k_1,\ldots,k_{n})}^{(k_{n+1},\ldots,k_N)}$ that appear in the QC-convFO decomposition of Eq.~\eqref{eq:charact_W_QC_convFO_decomp}, defined below as $W_{(k_1,\ldots,k_{n})}^{(k_{n+1},\ldots,k_N)}\coloneqq q_{\pi=(k_1,\ldots,k_N)}\tilde{W}_{(k_1,\ldots,k_n)}$, are also valid process matrices up to normalisation. \label{ftn:valid_Wk1_kn_FO}}
$W_{(k_1,\ldots,k_n)}$ as in Eq.~\eqref{eq:def_Wk1_kn_QCCC} above, one can readily see that the process matrix $W = W_{(k_1,\ldots,k_N,F)} \, (\ge 0)$ of a quantum circuit with fixed causal order $(k_1,\ldots,k_N)$ is necessarily such that for all $n = 1, \ldots, N$, there exist PSD matrices $W_{(k_1,\ldots,k_n)} \in {\cal L}(\HS^{PA_{\{k_1,\ldots,k_{n-1}\}}^{IO} A_{k_n}^I})$ such that
\begin{align}
    \left\{
    \begin{array}{l}
        \Tr_F W = \Tr_F W_{(k_1,\ldots,k_N,F)} = W_{(k_1,\ldots,k_N)} \otimes \id^{A_{k_N}^O}, \\[3mm]
        \forall \, n=1,\ldots,N-1, \ \ \Tr_{A_{k_{n+1}}^I} W_{(k_1,\ldots,k_{n+1})} = W_{(k_1,\ldots,k_{n})} \otimes \id^{A_{k_n}^O}, \\[3mm]
        \Tr_{A_{k_1}^I} W_{(k_1)} = \id^P.
    \end{array}
    \right. \label{eq:charact_W_QC_FO_decomp}
\end{align}
Conversely, for any PSD matrix $W \in \L(\HS^{PA_\N^{IO}F})$ satisfying the above constraint, one can construct (in a similar way to the case of general QC-CCs) internal circuit operations $\tilde{\M}_{n+1} = \tilde{\M}_{(k_1,\ldots,k_n)}^{\to k_{n+1}}$, whose composition as in Eq.~\eqref{eq:W_QCFO} gives precisely $W$~\cite{Gutoski06,Chiribella09,wechs21}. This shows that Eq.~\eqref{eq:charact_W_QC_FO_decomp} is also a sufficient characterisation of the class of QC-FOs.

\bigskip

\paragraph*{Convex mixtures of QC-FOs (QC-convFOs).}

The process matrix representation of a convex mixture of QC-FOs is then of the form $W = \sum_{\pi=(k_1,\ldots,k_N)} q_\pi\, \tilde{W}_{(k_1,\ldots,k_N,F)}$, with $q_\pi\ge 0$, $\sum_\pi q_\pi = 1$, and each $\tilde{W}_{(k_1,\ldots,k_N,F)}$ satisfying the constraints of Eq.~\eqref{eq:charact_W_QC_FO_decomp}.
By defining the subnormalised process matrices $W_{(k_1,\ldots,k_N,F)}\coloneqq q_{\pi=(k_1,\ldots,k_N)}\tilde{W}_{(k_1,\ldots,k_N,F)}$ and $W_{(k_1,\ldots,k_{n})}^{(k_{n+1},\ldots,k_N)}\coloneqq q_{\pi=(k_1,\ldots,k_N)}\tilde{W}_{(k_1,\ldots,k_n)}$ (with $\tilde{W}_{(k_1,\ldots,k_n)}$ obtained from the QC-FO decomposition of $\tilde{W}_{(k_1,\ldots,k_N,F)}$),
one readily gets the characterisation of Eq.~\eqref{eq:charact_W_QC_convFO_decomp} for the class of QC-convFOs.
The fact that Eq.~\eqref{eq:charact_W_QC_convFO_decomp} is a sufficient condition for $W$ to be a QC-convFO also follows straightforwardly from the sufficiency of Eq.~\eqref{eq:charact_W_QC_FO_decomp} above.

\bigskip

\paragraph*{An alternative description of QC-convFOs.}

We note that one could present an alternative description of QC-convFOs, by encoding each order in the mixture into a classical system that is then used to control all operations and their order---as in a general QC-CC, except that the complete order $(k_1,\ldots,k_N)$ would be decided, and encoded in the control system, from the very beginning (and independently of the global input state of the circuit).

This approach is the one we will follow to define the class of quantum circuits with superposition of fixed causal orders (QC-supFO), after turning the classical control system into a quantum control,  whose initial state will encode the complete order; see Sec.~\ref{app:def_QC-supFO} below.


\subsubsection{Quantum circuits with non-influenceable classical control of causal order (QC-NICCs)}
\label{app:def_QC-NICC}

Let us now come to our new class of QC-NICCs, defined in Sec.~\ref{sec:QC-NICC} of the main text as follows:
\begin{align*}
  \parbox{0.85\linewidth}{%
    \emph{QC-NICCs are the QC-CCs for which at any intermediate time step, the state of the control system is independent of the choice of previously applied external operations and of the potential initial state preparation in the global past,}%
  }
\end{align*}
with here the external operations referring to the parties' whole instruments (or simply a quantum channel they apply) rather than the individual CP maps that comprise them, and the state of the control system being considered after summing over all these individual CP maps.

The states $\varrho_{(n)}$, $\varrho_{(n)}'$ of all systems at any intermediate time step $t_n$ (for $n=1,\ldots,N$, just before or just after the operation $\tilde\A_n$) were given in Eqs.~\eqref{eq:link_prod_rho_tilde_M1_tilde_An} and~\eqref{eq:link_prod_rho_tilde_M1_tilde_Mn1}. Considering the case where all external operations $A_k$ are TP (equivalently, summing over the CP maps that constitute the parties' instruments), the reduced state of the control system is obtained as%
\footnote{In Eq.~\eqref{eq:reduced_state_Cn_QCCC} we used the TP property $\Tr_{A_{k_n}^O}A_{k_n}=\id^{A_{k_n}^I}$ to remove $A_{k_n}$ from the expression of $\Tr_{\tilde A_n^O\alpha_n} \varrho_{(n)}'$. Since we formally get the same reduced state of the control before and after the operation $\tilde\A_n$, we ignore here the distinction between systems $C_n$ and $C_n'$. \label{ftn:same_state_Cn}}
\begin{align}
\Tr_{\tilde A_n^I\alpha_n} \varrho_{(n)} = \Tr_{\tilde A_n^O\alpha_n} \varrho_{(n)}' & = \!\sum_{(k_1,\ldots,k_n)}\!\! \Tr[\big( \rho \!\otimes\! A_{k_1} \!\otimes\! \cdots \!\otimes\! A_{k_{n-1}} \big) * \big( M_\emptyset^{\to k_1} \!*\! M_{(k_1)}^{\to k_2} \!*\! \cdots \!*\! M_{(k_1,\ldots,k_{n-1})}^{\to k_n} \big)] [\![(k_1,\ldots,k_n)]\!]^{C_n^{(\prime)}} \notag \\ 
& = \sum_{(k_1,\ldots,k_n)} \Tr[\big( \rho \otimes A_{k_1} \otimes \cdots \otimes A_{k_{n-1}} \big) * W_{(k_1,\ldots,k_n)} ] \, [\![(k_1,\ldots,k_n)]\!]^{C_n^{(\prime)}}, \label{eq:reduced_state_Cn_QCCC}
\end{align}
with $W_{(k_1,\ldots,k_n)}$ as defined in Eq.~\eqref{eq:def_Wk1_kn_QCCC}, and contributing to the decomposition of the process matrix $W$ of the QC-CC under consideration, as in Eq.~\eqref{eq:charact_W_QCCC_decomp}.

The condition that the state of the control system should be independent of $\rho$ and of the previously applied external operations translates into the constraint that for all $(k_1,\ldots,k_n)$,
\begin{align}
\Tr[\big( \rho \otimes A_{k_1} \otimes \cdots \otimes A_{k_{n-1}} \big) * W_{(k_1,\ldots,k_n)} ] 
& \text{ does not depend on } \rho, A_{k_1}, \ldots, A_{k_{n-1}} \notag \\
& \quad \text{ whenever } A_{k_1}, \ldots, A_{k_{n-1}} \text{ are TP (and $\Tr\rho=1$)}.
\end{align}
Recalling the discussion at the end of Sec.~\ref{app:subsec_validity_cstr}, this is equivalent to
\begin{align}
    \text{all} \ W_{(k_1,\ldots,k_n)} \text{'s are valid process matrices (up to normalisation)},
\end{align}
as in Eq.~\eqref{eq:cstr_NICC}.

Conversely, as we recalled above, from a decomposition of $W$ in terms of $W_{(k_1,\ldots,k_N,F)}$ and $W_{(k_1,\ldots,k_n)}$ as in Eq.~\eqref{eq:charact_W_QCCC_decomp}, one can reconstruct some internal operations $M_{(k_1,\ldots,k_n)}^{\to k_{n+1}}$ (and $M_{(k_1,\ldots,k_N)}^{\to F}$) of a QC-QC such that $\Tr_{\alpha_n} \big( M_\emptyset^{\to k_1} * M_{(k_1)}^{\to k_2} * \cdots * M_{(k_1,\ldots,k_{n-1})}^{\to k_n} \big) = W_{(k_1,\ldots,k_n)}$. 
If each $W_{(k_1,\ldots,k_n)}$ is proportional to a valid process matrix, then the reduced state of the control system at time step $t_n$, as given in Eq.~\eqref{eq:reduced_state_Cn_QCCC} above, does not depend on the operations $A_k$ when these are TP. It follows that $W$ is the process matrix of a QC-NICC.


\subsubsection{Inclusion relations}
\label{app:subsubsec_QCCC_inclusions}

It is quite clear, from the definition of the \textup{\textsf{QC-NICC}} class just above, that $\textup{\textsf{QC-NICC}} \subset \textup{\textsf{QC-CC}}$.
To see that $\textup{\textsf{QC-convFO}} \subset \textup{\textsf{QC-NICC}}$, consider a process matrix $W\in\textup{\textsf{QC-convFO}}$, with a decomposition in terms of PSD matrices (and even valid process matrices, up to normalisation; see Footnote~\ref{ftn:valid_Wk1_kn_FO}) $W_{(k_1,\ldots,k_N,F)}$ and $W_{(k_1,\ldots,k_n)}^{(k_{n+1},\ldots,k_N)}$ as in Eq.~\eqref{eq:charact_W_QC_convFO_decomp}; defining, for each $(k_1,\ldots,k_n)$, $W_{(k_1,\ldots,k_n)}\coloneqq \sum_{(k_{n+1},\ldots,k_N)} W_{(k_1,\ldots,k_n)}^{(k_{n+1},\ldots,k_N)}$, one can easily see that these satisfy the QC-CC decomposition of Eq.~\eqref{eq:charact_W_QCCC_decomp}, and that these are themselves valid process matrices (up to normalisation), which proves that $W \in \textup{\textsf{QC-NICC}}$.
Hence, we obtain the general inclusion relations of Eq.~\eqref{eq:inclusions_QC-CCs}:
\begin{align}
    \text{\textup{\textsf{QC-convFO}}} \ \subset \ \text{\textup{\textsf{QC-NICC}}} \ \subset \ \text{\textup{\textsf{QC-CC}}}.
\end{align}

\medskip

It is straightforward to see that all these classes reduce to the same one (which also matches the whole class of valid process matrices, see Sec.~\ref{app:subsec_validity_cstr}) for $N=1$.

For $N=2$ already, with a nontrivial global past space $\HS^P$, one finds a strict separation between \text{\textup{\textsf{QC-NICC}}} and \text{\textup{\textsf{QC-CC}}}: an example of a process matrix in $\text{\textup{\textsf{QC-CC}}}\backslash\text{\textup{\textsf{QC-NICC}}}$ was given by the ``classical switch'' $W_{\textup{CS}}$, Eq.~\eqref{eq:CS-example} of the main text. If $\HS^P$ is trivial on the other hand, \text{\textup{\textsf{QC-NICC}}} and \text{\textup{\textsf{QC-CC}}} coincide for $N=2$ (see the proof below), and one needs to go to $N\ge 3$ to see a strict separation.

As for \text{\textup{\textsf{QC-convFO}}} vs \text{\textup{\textsf{QC-NICC}}}, these can be seen to coincide for $N\le 3$ (proof below). A strict separation can be found for $N\ge4$: an example of a process matrix in $\text{\textup{\textsf{QC-NICC}}}\backslash\text{\textup{\textsf{QC-convFO}}}$, for $N=4$ with trivial global past and future spaces $\HS^P, \HS^F$, was given by $W_{\textup{NICC}}$ from Eq.~\eqref{eq:QC-NICC-example}.

\begin{itemize}

    \item \underline{Proof that $\text{\textup{\textsf{QC-NICC}}}=\text{\textup{\textsf{QC-CC}}}$ for $N=2$ and a trivial $\HS^P$:} Given the general inclusion $\text{\textup{\textsf{QC-NICC}}}\subset\text{\textup{\textsf{QC-CC}}}$, it remains to prove the inclusion in the reverse direction. \label{proof:NICC_CC_N2_noP}

    Consider for that the process matrix $W$ of a QC-CC in that scenario. It decomposes in terms of PSD matrices $W_{(k_1,k_2,F)}$, $W_{(k_1,k_2)}$ and $W_{(k_1)}$ as in Eq.~\eqref{eq:charact_W_QCCC_decomp}---satisfying in particular $\Tr_{A_{k_2}^I} W_{(k_1,k_2)} = W_{(k_1)}\otimes\id^{A_{k_1}^O}$. Now, according to Eq.~\eqref{eq:validityW_PF}, the validity constraints, up to normalisation, for $W_{(k_1,k_2)} \in \L(\HS^{A_{k_1}^{IO}A_{k_2}^I})$ (with a trivial $\HS^P$) reduce to ${}_{[1-A_{k_1}^O]}\Tr_{A_{k_2}^I} W_{(k_1,k_2)} = 0$, which is indeed implied by $\Tr_{A_{k_2}^I} W_{(k_1,k_2)} = W_{(k_1)}\otimes\id^{A_{k_1}^O}$. Hence, the $W_{(k_1,k_2)}$'s are valid process matrices up to normalisation, which implies that $W$ is a QC-NICC, and therefore that $\text{\textup{\textsf{QC-CC}}}\subset\text{\textup{\textsf{QC-NICC}}}$ in the scenario under consideration. (Recall that it is enough here to check the validity for the $W_{(k_1,k_2)}$'s; in any case, the validity constraints for $W_{(k_1)} \in \L(\HS^{A_{k_1}^I})$, with no $\HS^P$, are trivially satisfied.)

    \item \underline{Proof that $\text{\textup{\textsf{QC-convFO}}}=\text{\textup{\textsf{QC-NICC}}}$ for $N\le 3$:} Given the general inclusion $\text{\textup{\textsf{QC-convFO}}}\subset\text{\textup{\textsf{QC-NICC}}}$, it remains to prove the inclusion in the reverse direction; furthermore, it is enough to consider $N=3$, since any scenario with fewer parties can be considered as a 3-partite scenario where some party(-ies) have trivial input and output spaces. \label{proof:convFO_NICC_N3}

    Consider, therefore, the process matrix $W$ of a tripartite ($N=3$) QC-NICC. It decomposes in terms of PSD matrices $W_{(k_1,k_2,k_3,F)}$, $W_{(k_1,k_2,k_3)}$, $W_{(k_1,k_2)}$ and $W_{(k_1)}$ as in Eq.~\eqref{eq:charact_W_QCCC_decomp}, with all of these being valid process matrices (up to normalisation). Defining $W_{(k_1,k_2,k_3)}^\emptyset\coloneqq W_{(k_1,k_2,k_3)}\ge 0$ and $W_{(k_1,k_2)}^{(k_3)}\coloneqq W_{(k_1,k_2)}\ge 0$ (for $k_3\neq k_1,k_2$), one can see that these (together with $W_{(k_1,k_2,k_3,F)}$) satisfy the first two lines of Eq.~\eqref{eq:charact_W_QC_convFO_decomp}, as well as the third constraint thereof, for $n=2$. Furthermore, the validity of $W_{(k_1,k_2)}\in\L(\HS^{PA_{k_1}^{IO}A_{k_2}^I})$ implies (according to Eq.~\eqref{eq:validityW_PF}) that ${}_{[1-A_{k_1}^O]}\Tr_{A_{k_2}^I} W_{(k_1,k_2)} = 0$, i.e., $\Tr_{A_{k_2}^I} W_{(k_1,k_2)}^{(k_3)} = \frac{1}{d_{k_1}^O}\Tr_{A_{k_1}^OA_{k_2}^I} W_{(k_1,k_2)}^{(k_3)}\otimes\id^{A_{k_1}^O}$, so that by defining $W_{(k_1)}^{(k_2,k_3)}\coloneqq \frac{1}{d_{k_1}^O}\Tr_{A_{k_1}^OA_{k_2}^I} W_{(k_1,k_2)}^{(k_3)}\ge 0$, the third constraint of Eq.~\eqref{eq:charact_W_QC_convFO_decomp} gets also satisfied for $n=1$. The validity of $W_{(k_1,k_2)}$ also implies that ${}_{[1-P]}\Tr_{A_{k_1}^{IO}A_{k_2}^I} W_{(k_1,k_2)} = 0$, i.e., $\Tr_{A_{k_1}^I} W_{(k_1)}^{(k_2,k_3)} = (\frac{1}{d^P}\Tr W_{(k_1)}^{(k_2,k_3)})\id^P$, so that final constraint of Eq.~\eqref{eq:charact_W_QC_convFO_decomp} is also satisfied, with $q_{\pi=(k_1,k_2,k_3)} = \frac{1}{d^P}\Tr W_{(k_1)}^{(k_2,k_3)} \ge 0$, such that $\sum_\pi q_\pi = \sum_{(k_1,k_2,k_3)} \frac{1}{d^P}\Tr W_{(k_1)}^{(k_2,k_3)} 
    = \sum_{k_1} \frac{1}{d^Pd_{k_1}^O} \sum_{k_2}\Tr W_{(k_1,k_2)} = \frac{1}{d^P} \sum_{k_1} \Tr W_{(k_1)} = 1$ as required (where we used $\sum_{k_2}\Tr W_{(k_1,k_2)}=\Tr\,(W_{(k_1)}\otimes\id^{A_{k_1}^O})$ and $\sum_{k_1} \Tr W_{(k_1)} = d^P$, which follow from Eq.~\eqref{eq:charact_W_QCCC_decomp}). 

    We thus obtained a decomposition of $W$ that satisfies all constraints of Eq.~\eqref{eq:charact_W_QC_convFO_decomp}, which shows that $W$ is a QC-convFO, and therefore that $\text{\textup{\textsf{QC-NICC}}}\subset\text{\textup{\textsf{QC-convFO}}}$, for the (at most) tripartite case considered here.

\end{itemize}


\subsubsection{Explicit decompositions of our specific examples of QC-CCs}
\label{app:decomp_ex_QCCCs}

To close this section on QC-CCs, we now provide explicit decompositions of our examples of QC-CCs from Sec.~\ref{subsubsec:examples_QCCCs}, in the appropriate form so as to match the characterisation of the class that they belong to.

\bigskip

Our first example, $W_{\textup{convFO}} = \frac12\ketbra{\psi}{\psi}^{A^I} \otimes \kketbra{\id}{\id}^{A^OB^I}\otimes \id^{B^O} + \frac12\ketbra{\psi}{\psi}^{B^I} \otimes \kketbra{\id}{\id}^{B^OA^I}\otimes \id^{A^O}$ from Eq.~\eqref{eq:QC-convFO-example}, is clearly of the QC-convFO form of Eq.~\eqref{eq:charact_W_QC_convFO_decomp}, with
\begin{align}
\left\{
    \begin{array}{rclcrcl}
W_{(A,B)}^\emptyset &=& {\textstyle\frac12}\ketbra{\psi}{\psi}^{A^I} \otimes \kketbra{\id}{\id}^{A^OB^I}, 
&& W_{(B,A)}^\emptyset &=& {\textstyle\frac12}\ketbra{\psi}{\psi}^{B^I} \otimes \kketbra{\id}{\id}^{B^OA^I}, \\[2mm]
W_{(A)}^{(B)} &=& {\textstyle\frac12}\ketbra{\psi}{\psi}^{A^I}, 
&& W_{(B)}^{(A)} &=& {\textstyle\frac12}\ketbra{\psi}{\psi}^{B^I}, \\[2mm]
\multicolumn{3}{r}{q_{(A,B)}} &=& \multicolumn{3}{l}{q_{(B,A)} \,=\, {\textstyle\frac12}}
    \end{array}
\right. \label{eq:decomp_WconvFO}
\end{align}
(and with $W_{(k_1,k_2,F)} = W_{(k_1,k_2)}^\emptyset \otimes \id^{A_{k_2}^O}$, since $\HS^F$ is trivial).

\bigskip

Our second example, $W_{\textup{NICC}} = \frac12 W_{+\alpha} \otimes \ketbra{\psi}{\psi}^{C^I} \otimes \kketbra{\id}{\id}^{C^O D^I} \otimes \id^{D^{O}} + \frac12 W_{-\alpha}\otimes \ketbra{\psi}{\psi}^{D^I} \otimes \kketbra{\id}{\id}^{D^O C^I} \otimes \id^{C^{O}}$ from Eq.~\eqref{eq:QC-NICC-example}, admits a QC-NICC decomposition of the form of Eq.~\eqref{eq:charact_W_QCCC_decomp}, with for instance%
\footnote{It is clear here that other decompositions are also possible, e.g. involving terms with $B\prec A$ rather than with $A\prec B$ (notice that $A$ and $B$ come in parallel in the implementation of Fig.~\ref{fig:QC-NICC-example}, which is compatible with both orders), or with a mixture of the orders $A\prec B$ and $B\prec A$.}
the valid process matrices (up to normalisation, as required the QC-NICC condition of Eq.~\eqref{eq:cstr_NICC})
\begin{align}
\left\{
    \begin{array}{rclcrcl}
W_{(A,B,C,D)} &=& {\textstyle\frac12} W_{+\alpha} \otimes \ketbra{\psi}{\psi}^{C^I} \otimes \kketbra{\id}{\id}^{C^O D^I}, 
&& W_{(A,B,D,C)} &=& {\textstyle\frac12} W_{-\alpha}\otimes \ketbra{\psi}{\psi}^{D^I} \otimes \kketbra{\id}{\id}^{D^O C^I}, \\[2mm]
W_{(A,B,C)} &=& {\textstyle\frac12} W_{+\alpha} \otimes \ketbra{\psi}{\psi}^{C^I}, 
&& W_{(A,B,D)} &=& {\textstyle\frac12} W_{-\alpha}\otimes \ketbra{\psi}{\psi}^{D^I}, \\[2mm]
\multicolumn{3}{r}{W_{(A,B)}} &=& \multicolumn{3}{l}{{\textstyle\frac14} \id^{A^{IO}B^I},} \\[2mm]
\multicolumn{3}{r}{W_{(A)}} &=& \multicolumn{3}{l}{{\textstyle\frac12} \id^{A^I},}
    \end{array}
\right.
 \label{app:dec_WNICC}
\end{align}
and all other $W_{(k_1,\ldots,k_n)}=0$ (and again with $W_{(k_1,\ldots,k_4,F)} = W_{(k_1,\ldots,k_4)} \otimes \id^{A_{k_4}^O}$, since $\HS^F$ is trivial).
Notice that while the $W_{\pm\alpha}$'s are valid process matrices, the fact that they are causally nonseparable prevents one from obtaining a QC-convFO decomposition of $W_{\textup{NICC}}$ (and indeed no such decomposition exists, as can be checked via SDP).

\bigskip

Our third example, $W_{\textup{CS}} = \ketbra{0}{0}^P \otimes \ketbra{\psi}{\psi}^{A^I} \otimes \kketbra{\id}{\id}^{A^OB^I} \otimes \id^{B^O} + \ketbra{1}{1}^P\otimes \ketbra{\psi}{\psi}^{B^I} \otimes \kketbra{\id}{\id}^{B^OA^I} \otimes \id^{A^O}$ from Eq.~\eqref{eq:CS-example}, can be decomposed in the general QC-CC form of Eq.~\eqref{eq:charact_W_QCCC_decomp} as follows:
\begin{align}
\left\{
    \begin{array}{rclcrcl}
W_{(A,B)} &=& \ketbra{0}{0}^P \otimes \ketbra{\psi}{\psi}^{A^I} \otimes \kketbra{\id}{\id}^{A^OB^I}, && W_{(B,A)} &=& \ketbra{1}{1}^P\otimes \ketbra{\psi}{\psi}^{B^I} \otimes \kketbra{\id}{\id}^{B^OA^I}, \\[2mm]
W_{(A)} &=& \ketbra{0}{0}^P \otimes \ketbra{\psi}{\psi}^{A^I}, && W_{(B)} &=& \ketbra{1}{1}^P\otimes \ketbra{\psi}{\psi}^{B^I}
    \end{array}
\right.
\label{app:dec_WCS}
\end{align}
(and once again with $W_{(k_1,k_2,F)} = W_{(k_1,k_2)} \otimes \id^{A_{k_2}^O}$, since $\HS^F$ is trivial).
Notice that none of the matrices in the above decomposition are valid process matrices; indeed it can be shown via SDP that no decomposition of the form of Eq.~\eqref{eq:charact_W_QCCC_decomp} exists for $W_{\textup{CS}}$ with only valid $W_{(k_1(,k_2))}$'s, which implies that $W_{\textup{CS}}$ is not a QC-NICC.

\subsection{Quantum circuits with quantum control of causal order (QC-QCs)}
\label{app:subsec_QCQC_classes}

We now move to the more in-depth presentation of QC-QCs and of our new subclasses of QC-supFOs and QC-NIQC.

\medskip

QC-QCs were introduced and characterised in Ref.~\cite{wechs21}. The basic idea was to turn the classical control of QC-CCs into a quantum control, so as to allow for coherently controlled superpositions of different causal orders.

To describe such coherent superpositions, it is more convenient to work in the ``pure'' picture of quantum theory: we will deal here with pure quantum states described by ket vectors of the form $\ket{\psi}\in\HS$ (rather than with density matrices $\rho\in\L(\HS)$), that evolve through pure linear operators of the form $V:\HS^X\to\HS^Y$ (rather than through CP maps $\M:\L(\HS^X)\to\L(\HS^Y)$). Correspondingly, we will use the ``pure'' version of the Choi–Jamiołkowski isomorphism and of the link product. Namely, for any given operator $V:\HS^X\to\HS^Y$, we define its Choi vector as the ``double-ket'' vector
\begin{align}
    \kket{V}^{XY} \coloneqq (\id^X\otimes V) \kket{\id}^{XX} = \sum_i \ket{i}^X\otimes V\ket{i}^X \ \in \HS^{XY} \label{eq:pure_Choi_def}
\end{align}
(with $\{\ket{i}^X\}_i$ denoting the computational basis of $\HS^X$, $\kket{\id}^{XX} \coloneqq \sum_i \ket{i}^X\otimes\ket{i}^X$); and for two vectors $\kket{V_1}\in\HS^{XY}$ and $\kket{V_2}\in\HS^{YZ}$ that share a common space $\HS^Y$, we define their pure link product as~\cite{wechs21}
\begin{align}
    \kket{V_1}^{XY} * \kket{V_2}^{YZ} \coloneqq & \big( \id^{XZ} \otimes \bbra{\id}^{YY} \big) \big(\kket{V_1}^{XY} \otimes \kket{V_2}^{YZ}\big) = \big( (\kket{V_1}^{XY})^{T_Y} \otimes \id^Z \big) \kket{V_2}^{YZ} \quad \in \HS^{XZ}. \label{eq:def_pure_link_product}
\end{align}
The pure link product has the same commutativity and associativity properties as in the mixed state, and similarly reduces to a tensor product if $\HS^Y$ is trivial, or to a scalar product if $\HS^X$ and $\HS^Z$ are trivial. 
As in the mixed case, when $\kket{V_1}^{XY}$ and $\kket{V_2}^{YZ}$ are the Choi vectors of two linear operators $V_1:\HS^X\to\HS^Y$ and $V_2:\HS^Y\to\HS^Z$, then their link product is the Choi vector of their composition (or simply their product, here). 

\subsubsection{General QC-QCs}
\label{app:introQCQC}

\paragraph*{Construction of a QC-QC.}

\begin{figure*}[t]
\centering
\includegraphics[width=1\columnwidth]{QCQC_full_v2.pdf}
\caption{Graphical representation of a QC-QC: a more detailed version than Fig.~\ref{fig:QCQC_graph} (clarifying here the internal structure of the circuit operations $\tilde{V}_n$), reproduced from Fig.~10 of Ref.~\cite{wechs21}.}
\label{fig:QCQC_graph_full}
\end{figure*}

The general construction of a QC-QC, depicted in Fig.~\ref{fig:QCQC_graph} of the main text or with more details in Fig.~\ref{fig:QCQC_graph_full} here, is quite similar to that of a QC-CC; we will simply highlight here the essential differences, referring again to Ref.~\cite{wechs21} for more details.

As just mentioned, here we work in the ``pure'' picture, so we now describe both internal and external operations as linear operators $\tilde V_1 : \HS^P \to \HS^{\tilde A_1^I \alpha_1C_1}$, $\tilde V_{n+1} : \HS^{\tilde A_n^O \alpha_nC_n'} \to \HS^{\tilde A_{n+1}^I \alpha_{n+1}C_{n+1}}$ (for $n=1,\ldots,N-1$), $\tilde V_{N+1} : \HS^{\tilde A_N^O \alpha_NC_N'} \to \HS^{F\alpha_F}$ (instead of $\tilde \M_{n+1} : \L(\HS^{\tilde A_n^O \alpha_nC_n'}) \to \L(\HS^{\tilde A_{n+1}^I \alpha_{n+1}C_{n+1}})$ etc.), and $A_k: \HS^{A_k^I}\to\HS^{A_k^O}$ (instead of $\A_k:\L(\HS^{A_k^I})\to\L(\HS^{A_k^O})$).%
\footnote{We again introduce ``generic'' input (respectively output) spaces $\HS^{\tilde A_n^I}$ (resp. $\HS^{\tilde A_n^O}$) for the external operations to be applied at time-slot $t_n$, assuming that all their input (resp. output) spaces are isomorphic. \\
Notice also that we introduce an additional auxiliary system $\alpha_F$ in the global future. This system will ultimately be traced out (see Fig.~\ref{fig:QCQC_graph}) so as to still allow for some mixtures in the general definition of QC-QCs. \label{ftn:abuse_notation} \\
And we again allow for a slight conflict of notation with $A_k$. Here in the pure picture, $A_k: \HS^{A_k^I}\to\HS^{A_k^O}$ (with Choi vector $\kket{A_k}\in \HS^{A_k^{IO}}$) can be understood as a Kraus operator of the operation applied by party $A_k$ (rather than the Choi matrix of their CP map, as we wrote in the context of QC-CCs).}

The structure of the control system is somewhat different here. While in the QC-CC case the (effectively classical) control states were keeping track of the whole order of the previous operations, for QC-QCs the control system at each time-slot $t_n$ only encodes the unordered set $\K_{n-1}$ of the $n-1$ previous operations, as well as the label $k_n (\notin\K_{n-1})$ of the current operation. Thus, the (orthogonal) basis states of the control system take the form
\begin{align}
    \ket{\K_{n-1},k_n}^{C_n^{(\prime)}} \label{eq:def_quantum_Cn}
\end{align}
(instead of $[\![(k_1,\ldots,k_n)]\!]^{C_n^{(\prime)}} \coloneqq \ketbra{(k_1,\ldots,k_n)}{(k_1,\ldots,k_n)}^{C_n^{(\prime)}}$ as in Eq.~\eqref{eq:def_classical_Cn}).
Such states control which external operation $A_{k_n}$ is to be applied at time-slot $t_n$ by embedding these into the larger controlled operation
\begin{align}
\tilde A_n \coloneqq & \sum_{\K_{n-1},k_n} \tilde A_{k_n} \otimes \ket{\K_{n-1},k_n}^{C_n'}\bra{\K_{n-1},k_n}^{C_n}: \ \HS^{\tilde A_n^I C_n} \to \HS^{\tilde A_n^O C_n'} \label{eq:tilde_An_QCQC}
\end{align}
(instead of Eq.~\eqref{eq:tilde_An_QCCC}).
They similarly control the internal operations through%
\footnote{We use the short-hand notations $\K_{n-1}\cup k_n=\K_{n-1}\cup \{k_n\}$, $\N \backslash k_N=\N \backslash\{k_N\}$ (and, further below, ${\cal K}_n \backslash k_n={\cal K}_n \backslash\{k_n\}$).}
\begin{align}
\tilde V_1 & \coloneqq \sum_{k_1} \tilde V_{\emptyset,\emptyset}^{\to k_1} \otimes \ket{\emptyset,k_1}^{C_1} : && \HS^P \to \HS^{\tilde A_1^I \alpha_1C_1}, \label{eq:def_V1_QCQC} \\
\tilde V_{n+1} & \coloneqq \sum_{\substack{\K_{n-1}, \\ k_n,k_{n+1}}} \tilde V_{\K_{n-1},k_n}^{\to k_{n+1}} \otimes \ket{\K_{n-1}\cup k_n,k_{n+1}}^{C_{n+1}}\bra{\K_{n-1},k_n}^{C_n'}: \hspace{-5mm} && \HS^{\tilde A_n^O \alpha_nC_n'} \to \HS^{\tilde A_{n+1}^I \alpha_{n+1}C_{n+1}}, \label{eq:tilde_Vn1_QCQC} \\
\tilde V_{N+1} & \coloneqq \sum_{k_N} \tilde V_{\N\backslash k_N,k_N}^{\to F} \otimes \bra{\N\backslash k_N,k_N}^{C_N'}: && \HS^{\tilde A_N^O \alpha_NC_N'} \to \HS^{F\alpha_F} \label{eq:def_VN1_QCQC}
\end{align}
(instead of Eqs.~\eqref{eq:tilde_Mn1_QCCC}--\eqref{eq:tilde_MN1_QCCC}), where the operators $\tilde V_{\emptyset,\emptyset}^{\to k_1}$, $\tilde V_{\K_{n-1},k_n}^{\to k_{n+1}}$ and $\tilde V_{\N\backslash k_N,k_N}^{\to F}$ act on the target and auxiliary memory systems in an analogous (now coherently) controlled manner to $\tilde \M_{\emptyset}^{\to k_1}$, $\tilde \M_{(k_1,\ldots,k_n)}^{\to k_{n+1}}$ and $\tilde \M_{(k_1,\ldots,k_N)}^{\to F}$ in the QC-CC case.
Notice in particular how the specific position of $k_n$ gets erased in Eq.~\eqref{eq:tilde_Vn1_QCQC}, by merging (in the control state) $\K_{n-1}$ and $k_n$ into the unordered set $\K_{n-1}\cup k_n$; forgetting about the specific order of the past operations will allow different orders to interfere.

The state of all systems at any point in the circuit is simply obtained by composing the above internal and external operations---which is conveniently done in terms of their Choi vectors, using the pure link product. Inputting some initial state $\ket{\psi}\in\HS^P$ in the global past of the circuit, and defining (for any subset $\K_n$ of $\N$) the vectors $\ket{\psi,A_{\K_n}}\coloneqq\ket{\psi}\bigotimes_{k\in\K_n}\kket{A_k}\in\HS^{PA_{\K_n}^{IO}}$, the states $\ket{\varphi'_{(n)}}$ before and $\ket{\varphi_{(n+1)}}$ after each operation $\tilde{V}_{n+1}$ are found to be
\begin{align}
\ket{\varphi_{(0)}'} & = \ket{\psi} \quad \in \HS^P, \label{eq:varphi0} \\[2mm]
\ket{\varphi_{(n)}'} & = \ket{\psi} * \kket{\tilde V_1} * \kket{\tilde A_1} * \kket{\tilde V_2} * \cdots * \kket{\tilde V_n} * \kket{\tilde A_n} \notag \\[1mm]
& = \sum_{(k_1,\ldots,k_n)} \big(\ket{\psi} \otimes \kket{A_{k_1}} \otimes \cdots \otimes \kket{A_{k_n}} \big) * \big( \kket{V_{\emptyset,\emptyset}^{\to k_1}} * \kket{V_{\emptyset,k_1}^{\to k_2}} * \cdots * \kket{V_{\{k_1,\ldots,k_{n-2}\},k_{n-1}}^{\to k_n}} * \kket{\id}^{A^O_{k_n}\tilde A^O_n} \big) \notag \\[-3mm]
& \hspace{125mm} \otimes \ket{\{k_1,\ldots,k_{n-1}\},k_n}^{C_n'} \notag \\[1mm]
& = \sum_{\K_n, \, k_n \in \K_n} \big( \ket{\psi,A_{\K_n}} * \ket{w_{(\K_n\backslash k_n,k_n)}} * \kket{\id}^{A^O_{k_n}\tilde A^O_n} \big) \otimes \ket{\K_n\backslash k_n,k_n}^{C_n'} \quad \in \HS^{\tilde A_n^O\alpha_n C_n'} \quad \text{ for } n\ge 1 \label{eq:link_prod_psi_tilde_V1_tilde_An}
\end{align}
and
\begin{align}
\ket{\varphi_{(n+1)}} & = \ket{\psi} * \kket{\tilde V_1} * \kket{\tilde A_1} * \cdots * \kket{\tilde V_n} * \kket{\tilde A_n} * \kket{\tilde V_{n+1}} \notag \\[1mm]
& = \sum_{(k_1,\ldots,k_n,k_{n+1})} \big(\ket{\psi} \otimes \kket{A_{k_1}} \otimes \cdots \otimes \kket{A_{k_n}} \big) * \big( \kket{V_{\emptyset,\emptyset}^{\to k_1}} * \cdots \notag \\[-3mm]
& \hspace{30mm} \cdots * \kket{V_{\{k_1,\ldots,k_{n-2}\},k_{n-1}}^{\to k_n}} * \kket{V_{\{k_1,\ldots,k_{n-1}\},k_n}^{\to k_{n+1}}} * \kket{\id}^{A^I_{k_{n+1}}\tilde A^I_{n+1}} \big) \otimes \ket{\{k_1,\ldots,k_n\},k_{n+1}}^{C_{n+1}} \notag \\[2mm]
& = \sum_{\K_n, \,k_{n+1} \notin \K_n} \big( \ket{\psi,A_{\K_n}} * \ket{w_{(\K_n,k_{n+1})}} * \kket{\id}^{A^I_{k_{n+1}}\tilde A^I_{n+1}} \big) \otimes \ket{\K_n,k_{n+1}}^{C_{n+1}} \notag \\[-3mm]
& \hspace{90mm} \in \HS^{\tilde A_{n+1}^I\alpha_{n+1} C_{n+1}} \quad \text{ for } n\le N-1, \label{eq:link_prod_psi_tilde_V1_tilde_Vn1} \\[3mm]
\ket{\varphi_{(N+1)}} & = \ket{\psi,A_\N} * \ket{w_{(\N,F)}} \quad \in \HS^{F\alpha_F} \label{eq:link_prod_psi_tilde_V1_tilde_VN1}
\end{align}
(instead of Eqs.~\eqref{eq:link_prod_rho_tilde_0}--\eqref{eq:link_prod_rho_tilde_M1_tilde_MN1}), with 
\begin{align}
\ket{w_{(\K_{n-1},k_n)}} & \coloneqq \sum_{(k_1,\ldots,k_{n-1})\in\K_{n-1}} \kket{V_{\emptyset,\emptyset}^{\to k_1}} * \kket{V_{\emptyset,k_1}^{\to k_2}} * \cdots * \kket{V_{\{k_1,\ldots,k_{n-2}\},k_{n-1}}^{\to k_n}} \quad \in \HS^{PA_{\K_{n-1}}^{IO} A_{k_n}^I\alpha_n}, \label{eq:def_w_Knm1_kn} \\[2mm]
\ket{w_{(\N,F)}} & \coloneqq \sum_{(k_1,\ldots,k_N)} \kket{V_{\emptyset,\emptyset}^{\to k_1}} * \kket{V_{\emptyset,k_1}^{\to k_2}} * \cdots * \kket{V_{\{k_1,\ldots,k_{N-2}\},k_{N-1}}^{\to k_N}} * \kket{V_{\{k_1,\ldots,k_{N-1}\},k_N}^{\to F}} \quad \in \HS^{PA_{\N}^{IO} F\alpha_F}. \label{eq:def_w_KN_F}
\end{align}

\bigskip

\paragraph*{Trace-preserving conditions.}

The TP conditions correspond here to the requirement that all internal operations $\tilde V_{n+1}$ preserve the norm of their input state $\ket{\varphi_{(n)}'}$: they must act as isometries on their effective input space.
The squared norms of $\ket{\varphi_{(n)}'}$ and $\ket{\varphi_{(n+1)}}$ (for $1\leq n\leq N-1$) can be obtained from Eqs.~\eqref{eq:link_prod_psi_tilde_V1_tilde_An}--\eqref{eq:link_prod_psi_tilde_V1_tilde_Vn1} above as
\begin{align}
\braket*{\varphi_{(n)}'}{\varphi_{(n)}'} & = \sum_{\K_n, \, k_n \in \K_n} \Tr\Big[\ketbra{\psi,A_{\K_n}}{\psi,A_{\K_n}} * \ketbra{w_{(\K_n\backslash k_n,k_n)}}{w_{(\K_n\backslash k_n,k_n)}}\Big] \notag \\
& = \sum_{\K_n} \Tr\Big[\big(\ketbra{\psi,A_{\K_n}}{\psi,A_{\K_n}}\big)^T \Big(\sum_{k_n\in\K_n}\Tr_{\alpha_n}\ketbra{w_{(\K_n\backslash k_n,k_n)}}{w_{(\K_n\backslash k_n,k_n)}} \otimes\id^{A_{k_n}^O}\Big)\Big], \\[2mm]
\braket{\varphi_{(n+1)}}{\varphi_{(n+1)}} & = \sum_{\K_n, \, k_{n+1} \notin \K_n} \Tr\Big[\ketbra{\psi,A_{\K_n}}{\psi,A_{\K_n}} * \ketbra{w_{(\K_n,k_{n+1})}}{w_{(\K_n,k_{n+1})}}\Big] \notag \\
& = \sum_{\K_n} \Tr\Big[\big(\ketbra{\psi,A_{\K_n}}{\psi,A_{\K_n}}\big)^T \Big(\sum_{k_{n+1}\notin\K_n}\Tr_{A_{k_{n+1}}^I\alpha_{n+1}}\ketbra{w_{(\K_n,k_{n+1})}}{w_{(\K_n,k_{n+1})}} \Big)\Big].
\end{align}
Equality between these two expressions, for any possible choice of $\ket{\psi}$ and of the $A_k$'s, implies that the last terms in round brackets must themselves be equal, for any $\K_n$:
\begin{align}
\sum_{k_{n+1}\notin\K_n}\Tr_{A_{k_{n+1}}^I\alpha_{n+1}}\ketbra{w_{(\K_n,k_{n+1})}}{w_{(\K_n,k_{n+1})}} = \sum_{k_n\in\K_n}\Tr_{\alpha_n}\ketbra{w_{(\K_n\backslash k_n,k_n)}}{w_{(\K_n\backslash k_n,k_n)}} \otimes\id^{A_{k_n}^O}. \label{eq:QCQC_TP_n}
\end{align}
For the extremal cases $n=0$ and $n=N$, the corresponding constraints are
\begin{align}
& \sum_{k_1\in\N}\Tr_{A_{k_1}^I\alpha_1}\ketbra{w_{(\emptyset,k_1)}}{w_{(\emptyset,k_1)}} = \id^P \label{eq:QCQC_TP_0} \\
\text{and} \qquad & \Tr_{F\alpha_F}\ketbra{w_{(\N,F)}}{w_{(\N,F)}} = \sum_{k_N\in\N}\Tr_{\alpha_N}\ketbra{w_{(\N\backslash k_N,k_N)}}{w_{(\N\backslash k_N,k_N)}} \otimes\id^{A_{k_N}^O}. \label{eq:QCQC_TP_N}
\end{align}

\bigskip

\paragraph*{Process matrix description and characterisation.}

From the expression for $\ket{\varphi_{(N+1)}}$ in Eq.~\eqref{eq:link_prod_psi_tilde_V1_tilde_VN1}, one gets the (in general, mixed) global output state of the whole QC-QC, after tracing out $\alpha_F$:
\begin{align}
    \varrho_{N+1} = \Tr_{\alpha_F} \ketbra{\varphi_{(N+1)}}{\varphi_{(N+1)}} = \ketbra{\psi,A_\N}{\psi,A_\N} * \big(\Tr_{\alpha_F} \ketbra{w_{(\N,F)}}{w_{(\N,F)}}\big) \quad \in \L(\HS^F).
\end{align}
With this, one can readily identify the process matrix that describes the QC-QC under consideration (as we did in the QC-CC case), namely
\begin{align}
    W = \Tr_{\alpha_F} \ketbra{w_{(\N,F)}}{w_{(\N,F)}} \quad \in \L(\HS^{PA_\N^{IO}F}), \label{eq:W_QCQC}
\end{align}
with $\ket{w_{(\N,F)}}$ defined in Eq.~\eqref{eq:def_w_KN_F} above, as a coherent superposition of terms corresponding to different causal orders.

\medskip

Defining, for all $n=1,\ldots,N$, all strict subsets $\K_{n-1}$ of $\N$ and all $k_n\in\N\backslash\K_{n-1}$,
\begin{align}
    W_{({\cal K}_{n-1},k_n)} & \coloneqq \Tr_{\alpha_n}\ketbra{w_{(\K_{n-1},k_n)}}{w_{(\K_{n-1},k_n)}} \quad \in {\cal L}(\HS^{PA_{{\cal K}_{n-1}}^{IO} A_{k_n}^I}), \label{eq:def_W_Kn1_kn}
\end{align}
it then follows directly from Eq.~\eqref{eq:W_QCQC} and the TP conditions of Eqs.~\eqref{eq:QCQC_TP_n}--\eqref{eq:QCQC_TP_N} that the process matrix $W \, (\ge 0)$ of a QC-QC has a characterisation as in Eq.~\eqref{eq:charact_W_QCQC_decomp}.

Conversely, from any decomposition of a process matrix $W$ in terms of PSD matrices $W_{({\cal K}_{n-1},k_n)}$ satisfying Eq.~\eqref{eq:charact_W_QCQC_decomp}, one can explicitly reconstruct (in a non-unique manner) the internal operations $V_{\K_{n-1},k_n}^{\to k_{n+1}}$ and $V_{\N\setminus k_N, k_N}^{\to F}$ of a QC-QC (satisfying the required TP conditions), whose composition reproduces $\ket{w_{(\N,F)}}$ and, subsequently, $W$ as in Eqs.~\eqref{eq:def_w_KN_F} and~\eqref{eq:W_QCQC} above.
This shows that Eq.~\eqref{eq:charact_W_QCQC_decomp} is also a sufficient condition for $W$ to be a QC-QC. An explicit procedure for such a reconstruction was detailed in Appendix B of~\cite{wechs21}.

\subsubsection{Quantum circuits with superposition of fixed causal orders (QC-supFO)}
\label{app:def_QC-supFO}

As succinctly introduced in the main text, we define the class of quantum circuits with superposition of fixed causal orders as a modification of the general QC-QC construction above, in which the control system at any time-slot $t_n$ now encodes (in addition to the past and current operations) the full causal order $(k_{n+1},\ldots,k_N)$ of the upcoming external operations that are still to be applied. The weight of each total order $\pi=(k_1,\ldots,k_N)$ is fixed from the very beginning to some value $q_\pi$ (such that $q_\pi\ge 0$, $\sum_\pi q_\pi=1$). When updating the control system, the internal operations may again erase the order of previous operations, but they should not modify the weight of each remaining ``future'' order $(k_{n+2},\ldots,k_N)$.

The construction, the derivation of the TP conditions, the process matrix description and the characterisation of QC-supFOs align quite closely to the case of general QC-QCs recalled above. We will just point out the differences.

\bigskip

\paragraph*{Construction of a QC-supFO.}

As just said, the control system should now also encode the order of future operations; we thus take its (orthogonal) basis states to be of the form
\begin{align}
    \ket{\K_{n-1},k_n;(k_{n+1},\ldots,k_N)}^{C_n^{(\prime)}}, \label{eq:def_quantum_Cn_supFO}
\end{align}
with $k_n,k_{n+1},\ldots,k_N\not\in\K_{n-1}$, instead of just $\ket{\K_{n-1},k_n}^{C_n^{(\prime)}}$ as in Eq.~\eqref{eq:def_quantum_Cn}.

These states control the external and internal operations through
\begin{align}
\tilde A_n \coloneqq & \sum_{\substack{\K_{n-1},\\ (k_n,k_{n+1},\ldots,k_N)}} \tilde A_{k_n} \otimes \ket{\K_{n-1},k_n;(k_{n+1},\ldots,k_N)}^{C_n'}\bra{\K_{n-1},k_n;(k_{n+1},\ldots,k_N)}^{C_n} \label{eq:tilde_An_QC-supFO}
\end{align}
and
\begin{align}
\tilde V_1 & \coloneqq \sum_{(k_1,k_2,\ldots,k_N)} \tilde V_{\emptyset,\emptyset}^{\to k_1;(k_2,\ldots,k_N)} \otimes \ket{\emptyset,k_1;(k_2,\ldots,k_N)}^{C_1}, \label{eq:def_V1_QC-supFO} \\[1mm]
\tilde V_{n+1} & \coloneqq \!\!\!\sum_{\substack{\K_{n-1}, \\ (k_n,k_{n+1},k_{n+2},\ldots,k_N)}} \!\!\!\!\!\!\!\!\! \tilde V_{\K_{n-1},k_n}^{\to k_{n+1};(k_{n+2},\ldots,k_N)} \otimes \ket{\K_{n-1}\cup k_n,k_{n+1};(k_{n+2},\ldots,k_N)}^{C_{n+1}}\bra{\K_{n-1},k_n;(k_{n+1},k_{n+2},\ldots,k_N)}^{C_n'}, \label{eq:tilde_Vn1_QC-supFO} \\
\tilde V_{N+1} & \coloneqq \ \sum_{k_N} \ \tilde V_{\N\backslash k_N,k_N}^{\to F} \otimes \bra{\N\backslash k_N,k_N;\emptyset}^{C_N'}, \label{eq:def_VN1_QC-supFO}
\end{align}
instead of Eqs.~\eqref{eq:tilde_An_QCQC}--\eqref{eq:def_VN1_QCQC} for the general QC-QC case. Notice that the operators $\tilde V_{\emptyset,\emptyset}^{\to k_1;(k_2,\ldots,k_N)}$ and $\tilde V_{\K_{n-1},k_n}^{\to k_{n+1};(k_{n+2},\ldots,k_N)}$ that act on the target and auxiliary memory systems can depend in general on the order of future operations, as encoded in the system $C_{n(+1)}^{(\prime)}$ that controls them.

Composing the above internal and external operations, we obtain the state of all systems before and after each operation $\tilde{V}_{n+1}$:
\begin{align}
\ket{\varphi_{(0)}'} & = \ket{\psi}, \label{eq:varphi0_supFO} \\[2mm]
\ket{\varphi_{(n)}'} & = \ket{\psi} * \kket{\tilde V_1} * \kket{\tilde A_1} * \kket{\tilde V_2} * \cdots * \kket{\tilde V_n} * \kket{\tilde A_n} \notag \\[1mm]
& = \sum_{(k_1,\ldots,k_N)} \big(\ket{\psi} \otimes \kket{A_{k_1}} \otimes \cdots \otimes \kket{A_{k_n}} \big) \notag \\[-4mm]
& \hspace{30mm} * \big( \kket{V_{\emptyset,\emptyset}^{\to k_1;(k_2,\ldots,k_N)}} * \kket{V_{\emptyset,k_1}^{\to k_2;(k_3,\ldots,k_N)}} * \cdots * \kket{V_{\{k_1,\ldots,k_{n-2}\},k_{n-1}}^{\to k_n;(k_{n+1},\ldots,k_N)}} * \kket{\id}^{A^O_{k_n}\tilde A^O_n} \big) \notag \\
& \hspace{100mm} \otimes \ket{\{k_1,\ldots,k_{n-1}\},k_n;(k_{n+1},\ldots,k_N)}^{C_n'} \notag \\[1mm]
& = \sum_{\substack{\K_n, \, k_n \in \K_n,\\ (k_{n+1},\ldots,k_N)\not\in\K_n}} \big( \ket{\psi,A_{\K_n}} * \ket{w_{(\K_n\backslash k_n,k_n)}^{(k_{n+1},\ldots,k_N)}} * \kket{\id}^{A^O_{k_n}\tilde A^O_n} \big) \otimes \ket{\K_n\backslash k_n,k_n;(k_{n+1},\ldots,k_N)}^{C_n'} \label{eq:link_prod_psi_tilde_V1_tilde_An_supFO}
\end{align}
and
\begin{align}
\ket{\varphi_{(n+1)}} & = \ket{\psi} * \kket{\tilde V_1} * \kket{\tilde A_1} * \cdots * \kket{\tilde V_n} * \kket{\tilde A_n} * \kket{\tilde V_{n+1}} \notag \\[1mm]
& = \sum_{(k_1,\ldots,k_N)} \big(\ket{\psi} \otimes \kket{A_{k_1}} \otimes \cdots \otimes \kket{A_{k_n}} \big) \notag \\[-4mm]
& \hspace{30mm}  * \big( \kket{V_{\emptyset,\emptyset}^{\to k_1;(k_2,\ldots,k_N)}} * \cdots * \kket{V_{\{k_1,\ldots,k_{n-2}\},k_{n-1}}^{\to k_n;(k_{n+1},\ldots,k_N)}} * \kket{V_{\{k_1,\ldots,k_{n-1}\},k_n}^{\to k_{n+1};(k_{n+2},\ldots,k_N)}} * \kket{\id}^{A^I_{k_{n+1}}\tilde A^I_{n+1}} \big) \notag \\
& \hspace{95mm} \otimes \ket{\{k_1,\ldots,k_n\},k_{n+1};(k_{n+2},\ldots,k_N)}^{C_{n+1}} \notag \\[2mm]
& = \sum_{\substack{\K_n,\\ (k_{n+1},k_{n+2},\ldots,k_N)\not\in\K_n}} \big( \ket{\psi,A_{\K_n}} * \ket{w_{(\K_n,k_{n+1})}^{(k_{n+2},\ldots,k_N)}} * \kket{\id}^{A^I_{k_{n+1}}\tilde A^I_{n+1}} \big) \otimes \ket{\K_n,k_{n+1};(k_{n+2},\ldots,k_N)}^{C_{n+1}}, \label{eq:link_prod_psi_tilde_V1_tilde_Vn1_supFO} \\[3mm]
\ket{\varphi_{(N+1)}} & = \ket{\psi,A_\N} * \ket{w_{(\N,F)}}
\label{eq:link_prod_psi_tilde_V1_tilde_VN1_supFO}
\end{align}
with
\begin{align}
\ket{w_{(\K_{n-1},k_n)}^{(k_{n+1},\ldots,k_N)}} & \coloneqq \sum_{(k_1,\ldots,k_{n-1})\in\K_{n-1}} \kket{V_{\emptyset,\emptyset}^{\to k_1;(k_2,\ldots,k_N)}} * \kket{V_{\emptyset,k_1}^{\to k_2;(k_3,\ldots,k_N)}} * \cdots * \kket{V_{\{k_1,\ldots,k_{n-2}\},k_{n-1}}^{\to k_n;(k_{n+1},\ldots,k_N)}}, \label{eq:def_w_Knm1_kn_supFO} \\[2mm]
\ket{w_{(\N,F)}} & \coloneqq \sum_{(k_1,\ldots,k_N)} \kket{V_{\emptyset,\emptyset}^{\to k_1;(k_2,\ldots,k_N)}} * \kket{V_{\emptyset,k_1}^{\to k_2;(k_3,\ldots,k_N)}} * \cdots * \kket{V_{\{k_1,\ldots,k_{N-2}\},k_{N-1}}^{\to k_N;\emptyset}} * \kket{V_{\{k_1,\ldots,k_{N-1}\},k_N}^{\to F}} \label{eq:def_w_KN_F_supFO}
\end{align}
instead of Eqs.~\eqref{eq:varphi0}--\eqref{eq:def_w_KN_F}.

\bigskip

\paragraph*{Trace-preserving conditions.} 

As specified above, the weight of each total order $\pi=(k_1,\ldots,k_N)$ of all parties, which is encoded in the state $\ket{\emptyset,k_1;(k_2,\ldots,k_N)}^{C_1}$ of the control system right after $\tilde V_1$, is fixed to some predefined value $q_\pi$. This weight---which can be interpreted as the probability that the control system is found in the state corresponding to that order (if it were measured in the appropriate basis)---can be obtained from the expression of $\varphi_{(1)}$ in Eq.~\eqref{eq:link_prod_psi_tilde_V1_tilde_Vn1_supFO}:
\begin{align}
    & \Big|\big(\id^{\tilde A_1^I\alpha_1}\otimes\bra{\emptyset,k_1;(k_2,\ldots,k_N)}^{C_1}\big)\ket{\varphi_{(1)}}\Big|^2 = \Big|\ket{\psi} * \ket{w_{(\emptyset,k_1)}^{(k_2,\ldots,k_N)}}\Big|^2 \notag \\
    & \hspace{30mm} = \Tr\Big[\big(\ketbra{\psi}{\psi}\big)^T \Big(\Tr_{A_{k_1}^I\alpha_1}\ketbra{w_{(\emptyset,k_1)}^{(k_2,\ldots,k_N)}}{w_{(\emptyset,k_1)}^{(k_2,\ldots,k_N)}}\Big)\Big] = q_{\pi=(k_1,\ldots,k_N)}.
\end{align}
Imposing that this equality holds for all possible (normalised) input states $\ket{\psi}\in\HS^P$ requires that
\begin{align}
& \Tr_{A_{k_1}^I\alpha_1}\ketbra{w_{(\emptyset,k_1)}^{(k_2,\ldots,k_N)}}{w_{(\emptyset,k_1)}^{(k_2,\ldots,k_N)}} = q_{\pi=(k_1,\ldots,k_N)} \,\id^P, \label{eq:QCQC_TP_0_supFO}
\end{align}
instead of the TP constraint of Eq.~\eqref{eq:QCQC_TP_0} in the general QC-QC case.

Additionally, we impose that the internal operations $\tilde V_{n+1}$ preserve the weight of each future order $(k_{n+1},\ldots,k_N)$.
The total weight attached to that order before $\tilde V_{n+1}$ is obtained as the sum over $k_n$ of the weights corresponding to $(k_n,k_{n+1},\ldots,k_N)$ in the state $\ket{\varphi_{(n)}'}$. Namely, for $\K_n=\N\backslash\{k_{n+1},\ldots,k_N\}$ (using Eq.~\eqref{eq:link_prod_psi_tilde_V1_tilde_An_supFO}):
\begin{align}
    & \sum_{k_n\in\K_n} \Big|\big(\id^{\tilde A_n^O\alpha_n}\otimes\bra{\K_n\backslash k_n,k_n;(k_{n+1},\ldots,k_N)}^{C_n'}\big)\ket{\varphi_{(n)}'}\Big|^2 = \sum_{k_n\in\K_n} \Big|\ket{\psi,A_{\K_n}} * \ket{w_{(\K_n\backslash k_n,k_n)}^{(k_{n+1},\ldots,k_N)}}\Big|^2 \notag \\
    & \hspace{40mm} = \Tr\Big[\big(\ketbra{\psi,A_{\K_n}}{\psi,A_{\K_n}}\big)^T \Big(\sum_{k_n\in\K_n}\Tr_{\alpha_n}\ketbra{w_{(\K_n\backslash k_n,k_n)}^{(k_{n+1},\ldots,k_N)}}{w_{(\K_n\backslash k_n,k_n)}^{(k_{n+1},\ldots,k_N)}} \otimes\id^{A_{k_n}^O}\Big)\Big].
\end{align}
The weight of $(k_{n+1},\ldots,k_N)$ after $\tilde V_{n+1}$ on the other hand is simply (using Eq.~\eqref{eq:link_prod_psi_tilde_V1_tilde_Vn1_supFO})
\begin{align}
    & \Big|\big(\id^{\tilde A_{n+1}^I\alpha_{n+1}}\otimes\bra{\K_n,k_{n+1};(k_{n+2},\ldots,k_N)}^{C_{n+1}}\big)\ket{\varphi_{(n+1)}}\Big|^2 = \Big|\ket{\psi,A_{\K_n}} * \ket{w_{(\K_n,k_{n+1})}^{(k_{n+2},\ldots,k_N)}}\Big|^2 \notag \\
    & \hspace{40mm} = \Tr\Big[\big(\ketbra{\psi,A_{\K_n}}{\psi,A_{\K_n}}\big)^T \Big(\Tr_{A_{k_{n+1}}^I\alpha_{n+1}}\ketbra{w_{(\K_n,k_{n+1})}^{(k_{n+2},\ldots,k_N)}}{w_{(\K_n,k_{n+1})}^{(k_{n+2},\ldots,k_N)}}\Big)\Big].
\end{align}
Imposing that these two expressions are equal, for any $\ket{\psi}$ and any $A_{\K_n}$, implies that one must have (for any $\K_n$, any $k_{n+1},\ldots,k_N\notin\K_n$)
\begin{align}
    \Tr_{A_{k_{n+1}}^I\alpha_{n+1}}\ketbra{w_{(\K_n,k_{n+1})}^{(k_{n+2},\ldots,k_N)}}{w_{(\K_n,k_{n+1})}^{(k_{n+2},\ldots,k_N)}} = \sum_{k_n\in\K_n}\Tr_{\alpha_n}\ketbra{w_{(\K_n\backslash k_n,k_n)}^{(k_{n+1},\ldots,k_N)}}{w_{(\K_n\backslash k_n,k_n)}^{(k_{n+1},\ldots,k_N)}} \otimes\id^{A_{k_n}^O}, \label{eq:QCQC_TP_n_supFO}
\end{align}
instead of Eq.~\eqref{eq:QCQC_TP_n}.
For the final case of $n=N$, the corresponding constraint is
\begin{align}
\Tr_{F\alpha_F}\ketbra{w_{(\N,F)}}{w_{(\N,F)}} = \sum_{k_N\in\N}\Tr_{\alpha_N}\ketbra{w_{(\N\backslash k_N,k_N)}^\emptyset}{w_{(\N\backslash k_N,k_N)}^\emptyset} \otimes\id^{A_{k_N}^O}. \label{eq:QCQC_TP_N_supFO}
\end{align}
instead of Eq.~\eqref{eq:QCQC_TP_N}.

\bigskip

\paragraph*{Process matrix description and characterisation.}

As in the general QC-QC case, from the expression for $\ket{\varphi_{(N+1)}}$ in Eq.~\eqref{eq:link_prod_psi_tilde_V1_tilde_VN1_supFO}, one gets the global output state of the whole QC-supFO, after tracing out $\alpha_F$:
\begin{align}
    \varrho_{N+1} = \Tr_{\alpha_F} \ketbra{\varphi_{(N+1)}}{\varphi_{(N+1)}} = \ketbra{\psi,A_\N}{\psi,A_\N} * \big(\Tr_{\alpha_F} \ketbra{w_{(\N,F)}}{w_{(\N,F)}}\big) \quad \in \L(\HS^F).
\end{align}
One can then identify the process matrix that describes the QC-supFO under consideration as
\begin{align}
    W = \Tr_{\alpha_F} \ketbra{w_{(\N,F)}}{w_{(\N,F)}} \quad \in \L(\HS^{PA_\N^{IO}F}), \label{eq:W_QCQC_supFO}
\end{align}
with $\ket{w_{(\N,F)}}$ defined in Eq.~\eqref{eq:def_w_KN_F_supFO} above.

\medskip

Defining, for all $n=1,\ldots,N$, all $\K_{n-1}\subsetneq\N$ and all $(k_n,k_{n+1},\ldots,k_N)\notin\K_{n-1}$,
\begin{align}
    W_{({\cal K}_{n-1},k_n)}^{(k_{n+1},\ldots,k_N)} & \coloneqq \Tr_{\alpha_n}\ketbra{w_{(\K_{n-1},k_n)}^{(k_{n+1},\ldots,k_N)}}{w_{(\K_{n-1},k_n)}^{(k_{n+1},\ldots,k_N)}} \quad \in {\cal L}(\HS^{PA_{{\cal K}_{n-1}}^{IO} A_{k_n}^I}),
\end{align}
then it follows directly from Eq.~\eqref{eq:W_QCQC_supFO} and the TP conditions of Eqs.~\eqref{eq:QCQC_TP_0_supFO}, \eqref{eq:QCQC_TP_n_supFO} and~\eqref{eq:QCQC_TP_N_supFO} that the process matrix $W \, (\ge 0)$ of a QC-supFO has a characterisation as in Eq.~\eqref{eq:charact_W_QC_SupFO_decomp}.
Notice that this characterisation implies in particular that the $W_{({\cal K}_{n-1},k_n)}^{(k_{n+1},\ldots,k_N)}$'s are valid process matrices, up to normalisation---as it was the case for the $W_{(k_1,\ldots,k_n)}^{(k_{n+1},\ldots,k_N)}$'s in the decomposition of a QC-convFO (cf Footnote~\ref{ftn:valid_Wk1_kn_FO}).

Conversely, the procedure of Ref.~\cite{wechs21} that allows one to reconstruct the internal operations $V_{\K_{n-1},k_n}^{\to k_{n+1}}$ and $V_{\N\setminus k_N, k_N}^{\to F}$ of a QC-QC 
from its characterisation as in Eq.~\eqref{eq:charact_W_QCQC_decomp} can be adapted here, implying that Eq.~\eqref{eq:charact_W_QC_SupFO_decomp} is also a sufficient condition for $W$ to be a QC-supFO.


\bigskip

\paragraph*{Another perspective: \textup{\textsf{QC-supFO}} as a recursive generalisation of the \textup{\textsf{Sup}} class from Ref.~\cite{Liu23}.}
\label{app:discuss_Sup}

Another subclass of QC-QCs was introduced in Ref.~\cite{Liu23}, which could also have been seen as a potential candidate to define quantum circuits with superpositions of fixed orders---it was indeed simply called \textup{\textsf{Sup}} by the authors of~\cite{Liu23}. We will argue however that its definition has an undesirable feature that should rule it out as such a meaningful definition of a relevant class of circuits, and that by generalising the \textup{\textsf{Sup}} class so as to avoid this unwanted feature, we naturally recover our \textup{\textsf{QC-supFO}} class.

\medskip

Formally, the \textup{\textsf{Sup}} class was defined as follows: $W \in \mathcal{L}(\mathcal{H}^{PA_\mathcal{N}^{IO}F})$ is in \textup{\textsf{Sup}} iff $W \ge 0$, and
\begin{align}
    \left\{
    \begin{array}{l}
        \Tr_F W = \sum_\pi q_\pi \, \tilde{W}_\pi, \\[2mm]
        \forall \, \pi, \tilde{W}_\pi \in \text{\textup{\textsf{QC-FO}}}_\pi, \ q_\pi\ge 0, \, \sum_\pi q_\pi = 1.
    \end{array}
    \right. \label{eq:def_Sup}
\end{align}
where $\text{\textup{\textsf{QC-FO}}}_\pi$ is the class of quantum circuits with fixed causal order $\pi$, i.e., for $\pi=(k_1,\ldots,k_N)$, of PSD matrices $W$ that admit a decomposition as in Eq.~\eqref{eq:charact_W_QC_FO_decomp}.
This class was meant to generalise the ``static'' quantum switch, in which the control system is initially prepared in some predefined quantum state corresponding to a superposition of fixed orders and ultimately sent to $\HS^F$ in the global future, so that tracing $\HS^F$ out leaves the rest of the parties in an incoherent mixture of processes with fixed causal order.

\bigskip

The unwanted feature we identify in the definition of \textup{\textsf{Sup}} above is that it crucially depends on the labelling of $\HS^F$. More specifically, recall first that considering the future space $\HS^F$ as ``open'' or attributing it to an additional party, with no output space, leads to formally equivalent frameworks~\cite{araujo17,wechs21}.
Now, if one were to rename $\HS^F$ and consider it as the input space of a new party, treated on equal footing with the other ones, then the definition of the 
\textup{\textsf{Sup}} class above would change.

Concretely, it can be seen for example that the process matrix of the ``static'' quantum switch, $W_{\textup{supFO}}$ from Eq.~\eqref{eq:QC-supFO-example}, is in \textup{\textsf{Sup}}. However, if one were to attribute $\HS^F$---or even just $\HS^{F_\text{c}}$---to another party (call it $C$) and write $W_{\textup{supFO}}=\ketbra{w_\textup{supFO}}{w_\textup{supFO}}$ with $\ket{w_\textup{supFO}} = {\textstyle\frac{1}{\sqrt{2}}} \ket{\psi}^{A^I} \otimes \kket{\id}^{A^OB^I} \otimes 
\kket{\id}^{B^OF_\text{t}} \otimes \ket{0}^{C_I} + {\textstyle\frac{1}{\sqrt{2}}}\ket{\psi}^{B^I} \otimes \kket{\id}^{B^OA^I} \otimes \kket{\id}^{A^OF_\text{t}} \otimes \ket{1}^{C_I}$ instead of Eq.~\eqref{eq:QC-supFO-example}, then one would conclude that $W_{\textup{supFO}}\notin\text{\textup{\textsf{Sup}}}$---even though the situation is physically exactly the same as the one in which one concludes that $W_{\textup{supFO}}\in\text{\textup{\textsf{Sup}}}$.

This observation leads us to argue that any physically meaningful definition of a class of quantum circuits should not depend on the labellings of the different parties, including (crucially) parties in the global past or future.%
\footnote{Unless the class one wishes to define refers explicitly to a certain labelling of the parties. E.g.\ the class $\text{\textup{\textsf{QC-FO}}}_{\pi=(A,B)}$ of quantum circuits with the fixed causal order $(A,B)$ is of course different from the class $\text{\textup{\textsf{QC-FO}}}_{\pi=(B,A)}$ obtained by swapping the two parties' labels.}
In particular, if two parties have no output space, the class should not depend on whose input space if called $\HS^F$; similarly if two parties have no input space, the class should not depend on whose output space if called $\HS^P$.
One can verify that all our classes satisfy this requirement.%
\footnote{Except for $\text{\textup{\textsf{QC-FO}}}_\pi$, see the previous footnote.}
We will now see how one can modify the \textup{\textsf{Sup}} class so as to also satisfy it.

\bigskip

For this, recall that the defining property of \textup{\textsf{Sup}} is that if one traces out $\HS^F$, one should be left with an incoherent mixture of fixed causal orders. If one attributes $\HS^F$ to another party, we would hence like that there is different party in the future, such that if one traces them out, the rest should be in an incoherent mixture of fixed orders.

The key insight we can take from the example of $W_{\textup{supFO}}$ just discussed is that in order to conclude that $W_{\textup{supFO}}\in\text{\textup{\textsf{Sup}}}$, it may not be enough to just trace one future party out; after tracing out one party, one may need to check whether one is left in a situation where another party can be considered to be in the future of the remaining ones, such that tracing it out leaves the other ones in an incoherent mixture of orders---or more generally, whether one is left in an (incoherent) mixture of such situations, with fixed weights. This suggests considering a recursive generalisation of the \textup{\textsf{Sup}} class that would formalise this.

As it turns out, following this idea provides an alternative characterisation of our class \textup{\textsf{QC-supFO}}. More formally: let us add subscripts and write $\textup{\textsf{QC-supFO}}_{P,\N,F}$ to specify the global past Hilbert space $\HS^P$, the set of parties $\N$, and the global future Hilbert space $\HS^F$ considered in the definition of \textup{\textsf{QC-supFO}}. We show below that $\textup{\textsf{QC-supFO}} = \textup{\textsf{QC-supFO}}_{P,\N,F}$ has the following recursive characterisation, which formalises precisely our suggestion above for generalising the \textup{\textsf{Sup}} class: 
\begin{align}
         \textup{\textsf{QC-supFO}}_{P,\N,F} & = 
         \left\{ W\in\L(\HS^{PA_\N^{IO} F})\, \middle|
    \begin{array}{c}
          W\ge 0, \, \Tr_F W = \sum_{k_N\in\N} \, q^{[k_N]}\, \tilde W^{[k_N]}\otimes\id^{A_{k_N}^O}, \\[2mm]
         q^{[k_N]}\ge 0, \ \sum_{k_N} q^{[k_N]} = 1, \\[2mm]
         \tilde W^{[k_N]} \in \textup{\textsf{QC-supFO}}_{P,\N\backslash k_N,A_{k_N}^I}
    \end{array}
    \right\}
    \quad \text{for } |\N|\ge 1, \notag \\[3mm]
        \textup{\textsf{QC-supFO}}_{P,\emptyset,F} & = \Big\{W\in\L(\HS^{PF})\, \Big| \, W\ge 0, \, \Tr_F W = \id^P \Big\}. \label{eq:rec_charact_SupFO}
\end{align}
This characterisation could also be taken as a definition of our class \textup{\textsf{QC-supFO}}, which can therefore be seen, from this perspective, as a natural generalisation of the \textup{\textsf{Sup}} class of Ref.~\cite{Liu23}.
It can indeed be checked that if two parties $F_1$, $F_2$ have no output Hilbert spaces, then $\textup{\textsf{QC-supFO}}_{P,\N\cup F_1,F_2} = \textup{\textsf{QC-supFO}}_{P,\N\cup F_2,F_1}$ 
: the above characterisation does not depend on which of $F_1$, $F_2$ is labelled $F$, thus indeed resolving the issue with the \textup{\textsf{Sup}} class that we pinpointed above.

\bigskip

\noindent\underline{Proof of Eq.~\eqref{eq:rec_charact_SupFO}:}
Let us denote by $\textup{\textsf{QC-supFO}}_{P,\N,F}'$ the RHS of the first equation in~\eqref{eq:rec_charact_SupFO} (adding the prime recursively, to $\textup{\textsf{QC-supFO}}_{P,\N\backslash k_N,A_{k_N}^I}$ and $\textup{\textsf{QC-supFO}}_{P,\emptyset,F}$ as well)---so that our task here is to prove that $\textup{\textsf{QC-supFO}}_{P,\N,F} = \textup{\textsf{QC-supFO}}_{P,\N,F}'$, with $\textup{\textsf{QC-supFO}}_{P,\N,F}$ defined by Eq.~\eqref{eq:charact_W_QC_SupFO_decomp}. 

\begin{itemize}

    \item For $|\N|=N=1$ ($\N=\{A\}$), it is easy to see that the set $\textup{\textsf{QC-supFO}}_{P,\{A\},F}' = \{ W\in\L(\HS^{PA^{IO} F}) | W\ge 0, \Tr_F W = \tilde W^{[A]}\otimes\id^{A^O}, \Tr_{A_I}\tilde W^{[A]} = \id^P \}$ coincides with $\textup{\textsf{QC-supFO}}_{P,\{A\},F}$ as characterised by Eq.~\eqref{eq:charact_W_QC_SupFO_decomp}. (These in fact also coincide with the set of all valid process matrices, as characterised through Eq.~\eqref{eq:validityW_PF}.)

    \item Assume that $\textup{\textsf{QC-supFO}}_{P,\N',F} = \textup{\textsf{QC-supFO}}_{P,\N',F}'$ for all $\N'$ such that $|\N'|=N-1\ge 1$.

    Consider then $W\in\textup{\textsf{QC-supFO}}_{P,\N',F}'$; by definition $\Tr_F W$ can be decomposed as a convex mixture
    \begin{align}
        \Tr_F W = \sum_{k_N\in\N} q^{[k_N]}\, \tilde W^{[k_N]}\otimes\id^{A_{k_N}^O} \label{eq:proof_rec_SupFO_1}
    \end{align}
    with each $\tilde W^{[k_N]} \in \textup{\textsf{QC-supFO}}_{P,\N\backslash k_N,A_{k_N}^I}$, which therefore has a decomposition in terms of PSD matrices $\tilde W_{({\cal K}_{n-1},k_n)}^{(k_{n+1},\ldots,k_{N-1});[k_N]} \in {\cal L}(\HS^{PA_{{\cal K}_{n-1}}^{IO} A_{k_n}^I})$ as in Eq.~\eqref{eq:charact_W_QC_SupFO_decomp}:
\begin{align}
    \left\{
    \begin{array}{l}
        \Tr_{A_{k_N}^I} \tilde W^{[k_N]} = \sum_{k_{N-1} \in \N\backslash k_N} \tilde W_{({\cal N} \backslash \{k_{N-1},k_N\},k_{N-1})}^{\emptyset;[k_N]}\otimes \id^{A_{k_{N-1}}^O}, \\[3mm]
        \forall \, \emptyset \subsetneq {\cal K}_n \subsetneq \N\backslash k_N, \, \forall \, (k_{n+1},\ldots,k_{N-1}) \in \N\backslash k_N\backslash{\cal K}_n, \\[1mm]
        \qquad \Tr_{A_{k_{n+1}}^I} \tilde W_{({\cal K}_n,k_{n+1})}^{(k_{n+2},\ldots,k_{N-1});[k_N]} = \sum_{k_n \in {\cal K}_n} \tilde W_{({\cal K}_n \backslash \{k_n\},k_n)}^{(k_{n+1},\ldots,k_{N-1});[k_N]}\otimes \id^{A_{k_n}^O}, \\[3mm]
        \forall \, \pi'=(k_1,\ldots,k_{N-1}) \in {\cal N}\backslash k_N, \ \Tr_{A_{k_1}^I} \tilde W_{(\emptyset,k_1)}^{(k_2,\ldots,k_{N-1});[k_N]} = q_{\pi'}^{[k_N]} \,\id^P, \ q_{\pi'}^{[k_N]}\ge 0, \, \sum_{\pi'} q_{\pi'}^{[k_N]} = 1.
    \end{array}
    \right. \label{eq:proof_rec_SupFO_2}
\end{align}
Defining $W_{({\cal N} \backslash \{k_N\},k_N)}^{\emptyset}\coloneqq q^{[k_N]}\, \tilde W^{[k_N]}$, $W_{({\cal K}_{n-1},k_n)}^{(k_{n+1},\ldots,k_{N-1},k_N)}\coloneqq q^{[k_N]}\, \tilde W_{({\cal K}_{n-1},k_n)}^{(k_{n+1},\ldots,k_{N-1});[k_N]}$ and $q_{\pi=(k_1,\ldots,k_{N-1},k_N)}\coloneqq q^{[k_N]}\, q_{\pi'=(k_1,\ldots,k_{N-1})}^{[k_N]}$, one can see that Eqs.~\eqref{eq:proof_rec_SupFO_1} and~\eqref{eq:proof_rec_SupFO_2} together provide a decomposition of $W$ as in Eq.~\eqref{eq:charact_W_QC_SupFO_decomp}, which proves that $W\in\textup{\textsf{QC-supFO}}_{P,\N,F}$.

Conversely, consider $W\in\textup{\textsf{QC-supFO}}_{P,\N,F}$, with a decomposition as in Eq.~\eqref{eq:charact_W_QC_SupFO_decomp}.
Defining, for each $k_N$, $q^{[k_N]}\coloneqq \sum_{(k_1,\ldots,k_{N-1})\in\N\backslash k_N} q_{\pi=( k_1,\ldots,k_{N-1},k_N)}$ and $\tilde W^{[k_N]}\coloneqq W_{({\cal N} \backslash \{k_N\},k_N)}^{\emptyset}/q^{[k_N]}$ (when $q^{[k_N]}>0$; otherwise, $\tilde W^{[k_N]}\coloneqq 0$), then one obtains a decomposition of $\Tr_F W$ as in Eq.~\eqref{eq:proof_rec_SupFO_1} above, with $q^{[k_N]}\ge 0$, $ \sum_{k_N} q^{[k_N]} = 1$, and one can further see that each $\tilde W^{[k_N]}$ admits itself a decomposition of the form of Eq.~\eqref{eq:charact_W_QC_SupFO_decomp}, in terms of PSD matrices $\tilde W_{({\cal K}_{n-1},k_n)}^{(k_{n+1},\ldots,k_{N-1});[k_N]} \coloneqq W_{({\cal K}_{n-1},k_n)}^{(k_{n+1},\ldots,k_{N-1},k_N)}/q^{[k_N]}$ and with weights $q_{\pi'=(k_1,\ldots,k_{N-1})}^{[k_N]}\coloneqq q_{\pi=(k_1,\ldots,k_{N-1},k_N)}/q^{[k_N]}\, $ in the final constraint. This implies that each $\tilde W^{[k_N]}\in\textup{\textsf{QC-supFO}}_{P,\N\backslash k_N,F}$, and hence that $W\in\textup{\textsf{QC-supFO}}_{P,\N,F}'$.

We thus have that $\textup{\textsf{QC-supFO}}_{P,\N,F}'=\textup{\textsf{QC-supFO}}_{P,\N,F}$. This, by recursion, concludes the proof of Eq.~\eqref{eq:rec_charact_SupFO}.

\end{itemize}

\subsubsection{Quantum circuits with non-influenceable quantum control of causal order (QC-NIQCs)}
\label{app:def_QC-NIQC}

The last class we introduced is that of QC-NIQCs, defined in Sec.~\ref{sec:QC-NIQC} of the main text as follows:
\begin{align*}
  \parbox{0.85\linewidth}{%
    \emph{QC-NIQCs are the QC-QCs for which at any intermediate time step, the classical weights of each term in the basis $\{\ket{\K_{n-1},k_n}^{C_n}\}_{\K_{n-1},k_n}$ that defines the controllisation---i.e.\ the diagonal elements of the state of the control system in that basis---are independent of the choice of previously applied external operations and of the potential initial state preparation in the global past.}%
  }
\end{align*}
(with, as for QC-NICCs, the external operations referring to the parties' whole instruments rather than the individual CP maps that compose them, and the state of the control system being considered after summing over all these individual CP maps---and over all their Kraus operators when one starts from a description in the ``pure'' picture).

The state $\ket{\varphi_{(n)}}$ of all systems at any intermediate time step $t_n$ (for $n=1,\ldots,N$, just before%
\footnote{Considering the case where the external operations are TP, the reduced state of the control system after the operator $\tilde A_n$ (and after summing over the corresponding Kraus operators) will be the same; as in Eq.~\eqref{eq:reduced_state_Cn_QCCC} (see also Footnote~\ref{ftn:same_state_Cn}).}
applying the operator $\tilde A_n$) is given by Eq.~\eqref{eq:link_prod_psi_tilde_V1_tilde_Vn1}. From this, the weight of each component $\ket{\K_{n-1},k_n}^{C_n}$ of the control system is obtained as
\begin{align}
    \Big\|\,\ket{\psi,A_{\K_{n-1}}} * \ket{w_{(\K_{n-1},k_n)}}\,\Big\|^2 = \Tr\Big[\Big(\ketbra{\psi}{\psi}\bigotimes_{k\in\K_{n-1}}\kketbra{A_k}{A_k}\Big) * W_{({\cal K}_{n-1},k_n)}\Big],
\end{align}
with $W_{({\cal K}_{n-1},k_n)} = \Tr_{\alpha_n}\ketbra{w_{(\K_{n-1},k_n)}}{w_{(\K_{n-1},k_n)}}$ as defined in Eq.~\eqref{eq:def_W_Kn1_kn}.
Summing over the Kraus operators $A_k$ so as to obtain a CPTP map for each party---whose Choi matrix, abusing the notation slightly, we still denote by $A_k$ (see Footnote~\ref{ftn:abuse_notation})---the requirement expressed above translates into the constraint that for all $\K_{n-1},k_n$,
\begin{align}
\Tr\Big[\Big( \ketbra{\psi}{\psi} \bigotimes_{k\in\K_{n-1}} A_k \Big) * W_{(\K_{n-1},k_n)} \Big] 
& \text{ does not depend on $\rho$ nor on the $A_k$'s,} \notag \\[-4mm]
& \quad \text{ whenever all } A_k\text{'s are TP (and $\ket{\psi}$ is normalised)}.
\end{align}
Recalling the discussion at the end of Sec.~\ref{app:subsec_validity_cstr}, this is equivalent to
\begin{align}
    \text{all} \ W_{(\K_{n-1},k_n)} \text{'s are valid process matrices (up to normalisation)},
\end{align}
as in Eq.~\eqref{eq:cstr_NIQC}.

Conversely, as recalled above, from the characterisation of a QC-QC as in Eq.~\eqref{eq:charact_W_QCQC_decomp}, one can reconstruct internal operations that realise it; one can verify that the additional validity constraint above implies indeed that these internal operations are such that the diagonal elements of the state of the control system are independent of the external TP operations---implying that the QC-QC under consideration is then a QC-NIQC.


\subsubsection{Inclusion relations}
\label{app:subsubsec_QCQC_inclusions}

Let us start here by noting that each of the three classes of quantum circuits with quantum control considered above contains the corresponding class with classical control as a subclass: $\text{\textup{\textsf{QC-convFO}}} \subset \text{\textup{\textsf{QC-supFO}}}$, $\text{\textup{\textsf{QC-NICC}}} \subset \text{\textup{\textsf{QC-NIQC}}}$ and $\text{\textup{\textsf{QC-CC}}} \subset \text{\textup{\textsf{QC-QC}}}$.
In the latter case for instance, this can be seen by starting from a QC-CC decomposition in terms of PSD matrices $W_{(k_1,\ldots,k_N,F)}$ and $W_{(k_1,\ldots,k_n)}$ as in Eq.~\eqref{eq:charact_W_QCCC_decomp}, and defining $W_{({\cal K}_{n-1},k_n)}\coloneqq\sum_{(k_1,\ldots,k_{n-1})\in\K_{n-1}}W_{(k_1,\ldots,k_n)}$, which indeed readily provide a QC-QC decomposition as in Eq.~\eqref{eq:charact_W_QCQC_decomp}. For $\text{\textup{\textsf{QC-convFO}}} \subset \text{\textup{\textsf{QC-supFO}}}$, a similar construction works, after just adding the appropriate superscripts $(k_{n+1},\ldots,k_N)$. For $\text{\textup{\textsf{QC-NICC}}} \subset \text{\textup{\textsf{QC-NIQC}}}$, we further note that if $W_{(k_1,\ldots,k_n)}$'s are valid process matrices (up to normalisation), then so are the $W_{({\cal K}_{n-1},k_n)}$'s just defined.

Quite trivially, for $N=1$ all six classes reduce to the same one---which is also the whole class of all valid process matrices. For $N=2$, with a nontrivial global future space $\HS^F$, one already obtains a strict separation between the three QC-QC classes and their QC-CC counterparts: indeed the ``static quantum switch'', $W_{\textup{supFO}}$ from Eq.~\eqref{eq:QC-supFO-example}, provides in that scenario an example in \textup{\textsf{QC-supFO}} (hence also in \textup{\textsf{QC-NIQC}} and \textup{\textsf{QC-QC}}, see below) but not in \textup{\textsf{QC-CC}} (nor in any of its subclasses).
If $\HS^F$ is trivial on the other hand, one can easily see that for $N=2$ each of the three QC-QC classes reduces to its QC-CC counterpart; one then needs to go to $N\ge 3$ to see a strict separation.

\bigskip

Let us now compare the three (sub)classes of QC-QCs.

It is again quite clear, from the definition of the \textup{\textsf{QC-NIQC}} class just above, that $\textup{\textsf{QC-NIQC}} \subset \textup{\textsf{QC-QC}}$. To see that $\textup{\textsf{QC-supFO}} \subset \textup{\textsf{QC-NIQC}}$, consider a process matrix $W\in\textup{\textsf{QC-supFO}}$, with a decomposition in terms of PSD matrices (and even valid process matrices, up to normalisation) $W_{({\cal K}_{n-1},k_n)}^{(k_{n+1},\ldots,k_N)}$ as in Eq.~\eqref{eq:charact_W_QC_SupFO_decomp}; defining, for each $(\K_{n-1},k_n)$, $W_{(\K_{n-1},k_n)}\coloneqq \sum_{(k_{n+1},\ldots,k_N)} W_{(\K_{n-1},k_n)}^{(k_{n+1},\ldots,k_N)}$, one can easily see that these satisfy the QC-QC decomposition of Eq.~\eqref{eq:charact_W_QCQC_decomp}, and that these are themselves valid process matrices (up to normalisation), which proves that $W \in \textup{\textsf{QC-NIQC}}$. 
Hence, we obtain the general inclusion relations of Eq.~\eqref{eq:inclusions_QC-QCs}:
\begin{align}
    \text{\textup{\textsf{QC-supFO}}} \ \subset \ \text{\textup{\textsf{QC-NIQC}}} \ \subset \ \text{\textup{\textsf{QC-QC}}}. 
\end{align}

\medskip

For $N=2$ already, with a nontrivial global past space $\HS^P$, one finds a strict separation between \text{\textup{\textsf{QC-NIQC}}} and \text{\textup{\textsf{QC-QC}}}. An example of a process matrix in $\text{\textup{\textsf{QC-QC}}}\backslash\text{\textup{\textsf{QC-NIQC}}}$ was given by the quantum switch $W_{\textup{QS}}$, Eq.~\eqref{eq:QC-QC-example} of the main text (for $N=2$ indeed, with a nontrivial space $\HS^P$ but also a nontrivial space $\HS^F$ to avoid falling back into the \textup{\textsf{QC-CC}} class; see above). If $\HS^P$ is trivial on the other hand, \text{\textup{\textsf{QC-NIQC}}} and \text{\textup{\textsf{QC-QC}}} coincide for $N=2$ (the proof being quite similar to that for $\text{\textup{\textsf{QC-NICC}}}=\text{\textup{\textsf{QC-CC}}}$ in the same scenario, see p.~\pageref{proof:NICC_CC_N2_noP}), and one needs to go to $N\ge 3$ to see a strict separation.

As for \text{\textup{\textsf{QC-supFO}}} vs \text{\textup{\textsf{QC-NIQC}}}, these can be seen to coincide for $N\le 3$ (again, the proof is quite similar to that for $\text{\textup{\textsf{QC-convFO}}}=\text{\textup{\textsf{QC-NICC}}}$ in the same $N\leq 3$ case, on p.~\pageref{proof:convFO_NICC_N3}). A strict separation can be found for $N\ge4$: an example of a process matrix in $\text{\textup{\textsf{QC-NIQC}}}\backslash\text{\textup{\textsf{QC-supFO}}}$ (which was also not in \textup{\textsf{QC-CC}}), for $N=4$ with trivial global past and future spaces $\HS^P, \HS^F$, was given by $W_{\textup{NIQC}}$ from Eq.~\eqref{eq:QC-NICC-example}.

\subsubsection{Explicit decompositions of our specific examples of QC-QCs}
\label{app:decomp_ex_QCQCs}

We finish this section on QC-QCs by providing explicit decompositions of our examples of QC-QCs from Sec.~\ref{subsubsec:examples_QCQCs}, in the appropriate form so as to match the characterisation of the class that they belong to.

\bigskip

The process matrix $W_{\textup{supFO}}=\ketbra{w_\textup{supFO}}{w_\textup{supFO}}$, with $\ket{w_\textup{supFO}} = \frac{1}{\sqrt{2}} \ket{\psi}^{A^I} \otimes \kket{\id}^{A^OB^I} \otimes  \kket{\id}^{B^OF_\text{t}} \otimes \ket{0}^{F_\text{c}} + \frac{1}{\sqrt{2}}\ket{\psi}^{B^I} \otimes \kket{\id}^{B^OA^I} \otimes \kket{\id}^{A^OF_\text{t}} \otimes \ket{1}^{F_\text{c}}$ of the ``static'', or ``non-dynamical'' quantum switch, Eq.~\eqref{eq:QC-supFO-example}, can be decomposed in the QC-supFO form of Eq.~\eqref{eq:charact_W_QC_SupFO_decomp}, with
\begin{align}
\left\{
    \begin{array}{rclcrcl}
W_{(\{A\},B)}^\emptyset &=& {\textstyle\frac12}\ketbra{\psi}{\psi}^{A^I} \otimes \kketbra{\id}{\id}^{A^OB^I}, 
&& W_{(\{B\},A)}^\emptyset &=& {\textstyle\frac12}\ketbra{\psi}{\psi}^{B^I} \otimes \kketbra{\id}{\id}^{B^OA^I}, \\[2mm]
W_{(\emptyset,A)}^{(B)} &=& {\textstyle\frac12}\ketbra{\psi}{\psi}^{A^I}, 
&& W_{(\emptyset,B)}^{(A)} &=& {\textstyle\frac12}\ketbra{\psi}{\psi}^{B^I}, \\[2mm]
\multicolumn{3}{r}{q_{(A,B)}} &=& \multicolumn{3}{l}{q_{(B,A)} \,=\, {\textstyle\frac12}.}
    \end{array}
\right.
\end{align}
Notice that this is (up to very slightly different notations) the same decomposition as that given for $W_{\textup{convFO}}$ in Eq.~\eqref{eq:decomp_WconvFO}. This is because $\Tr_F W_{\textup{supFO}}=W_{\textup{convFO}}$, and because the QC-supFO constraints for $\Tr_F W_{\textup{supFO}}$ reduce (in the $N=2$ case, with no more $\HS^F$) to the QC-convFO constraints. Besides, it is also well-known---and easy to see---that $W_{\textup{supFO}}$ is not a QC-CC (noting that $W_{\textup{supFO}}=\ketbra{w_\textup{supFO}}{w_\textup{supFO}}$ is rank-1, so that any decomposition of $W_{\textup{supFO}}$ directly into PSD matrices can only contain terms that are proportional to itself).

\bigskip

Our example of a QC-NIQC, $W_{\textup{NIQC}} = \frac12 W_0\otimes \ketbra{\psi}{\psi}^{C^I} \otimes \kketbra{\id}{\id}^{C^OD^I} \otimes \id^{D^O} + \frac12 W_1\otimes \ketbra{\psi}{\psi}^{D^I} \otimes \kketbra{\id}{\id}^{D^OC^I} \otimes \id^{C^O}$ from Eq.~\eqref{eq:QC-NIQC-example},
with $W_0$ and $W_1$ two (valid) process matrices defined in Eq.~\eqref{eq:W0/W1} and satisfying ${\textstyle\frac12} W_0 + {\textstyle\frac12} W_1 = \frac{1}{8}(2 \,\id^{\otimes 4}+ 2 \,Z\id Z\id + XZX\id - YZY\id + X\id XZ - Y\id YZ)^{A^{IO}B^{IO}}$,
admits a QC-NIQC decomposition of the form of Eq.~\eqref{eq:charact_W_QCQC_decomp}, with the valid process matrices (up to normalisation, as required the QC-NIQC condition of Eq.~\eqref{eq:cstr_NIQC})
\begin{align}
\left\{
    \begin{array}{rclrcl}
W_{(\{A,B,C\},D)} &=& {\textstyle\frac12} W_0 \otimes \ketbra{0}{0}^{C^I} \otimes \kketbra{\id}{\id}^{C^O D^I}, & W_{(\{A,B,D\},C)} &=& {\textstyle\frac12} W_1\otimes \ketbra{0}{0}^{D^I} \otimes \kketbra{\id}{\id}^{D^O C^I}, \\[3mm]
W_{(\{A,B\},C)} &=& {\textstyle\frac12} W_0 \otimes \ketbra{0}{0}^{C^I}, & W_{(\{A,B\},D)} &=& {\textstyle\frac12} W_1\otimes \ketbra{0}{0}^{D^I}, \\[3mm]
W_{(\{A\},B)} &=& \frac{1}{8}(\id^{\otimes 3}+ Z\id Z + XZX - YZY)^{A^{IO}B^I}, & W_{(\{B\},A)} &=& \frac{1}{8}(\id^{\otimes 3} + ZZ\id + XXZ - YYZ)^{A^IB^{IO}}, \\[3mm]
W_{(\emptyset,A)} &=& {\textstyle\frac14} \id^{A^I}, & W_{(\emptyset,B)} &=& {\textstyle\frac14} \id^{B^I},
    \end{array}
\right.
 \label{app:dec_WNIQC}
\end{align}
and all other $W_{(\K_{n-1},k_n)}=0$. 

\bigskip

Finally, the process matrix $W_{\textup{QS}}=\ketbra{w_\textup{QS}}{w_\textup{QS}}$, with $\ket{w_\textup{QS}} = \ket{0}^P \otimes \ket{\psi}^{A^I} \otimes \kket{\id}^{A^OB^I} \otimes \kket{\id}^{B^OF_\text{t}} \otimes  \ket{0}^{F_\text{c}} + \ket{1}^P \otimes \ket{\psi}^{B^I} \otimes \kket{\id}^{B^OA^I} \otimes \kket{\id}^{A^OF_\text{t}} \otimes \ket{1}^{F_\text{c}}$ of the ``dynamical'' quantum switch, Eq.~\eqref{eq:QC-QC-example}, can be decomposed in the general QC-QC form of Eq.~\eqref{eq:charact_W_QCQC_decomp} as follows:
\begin{align}
\left\{
    \begin{array}{rclcrcl}
W_{(\{A\},B)} &=& \ketbra{0}{0}^P \otimes \ketbra{\psi}{\psi}^{A^I} \otimes \kketbra{\id}{\id}^{A^OB^I}, && W_{(\{B\},A)} &=& \ketbra{1}{1}^P\otimes \ketbra{\psi}{\psi}^{B^I} \otimes \kketbra{\id}{\id}^{B^OA^I}, \\[2mm]
W_{(\emptyset,A)} &=& \ketbra{0}{0}^P \otimes \ketbra{\psi}{\psi}^{A^I}, && W_{(\emptyset,B)} &=& \ketbra{1}{1}^P\otimes \ketbra{\psi}{\psi}^{B^I}.
    \end{array}
\right.
\label{app:dec_WQS}
\end{align}
Notice that this is again essentially the same decomposition as that given for the process matrix of the classical switch $W_{\textup{CS}}$ in Eq.~\eqref{app:dec_WCS}. This is because $\Tr_F W_{\textup{QS}}=W_{\textup{CS}}$, and because the QC-QC constraints for $\Tr_F W_{\textup{QS}}$ reduce (in the $N=2$ case, with no more $\HS^F$) to the QC-CC constraints. 
As in the case of $W_{\textup{CS}}$, none of the matrices in the above decomposition are valid process matrices; indeed it can be shown via SDP that no decomposition of the form of Eq.~\eqref{eq:charact_W_QCQC_decomp} exists for $W_{\textup{QS}}$ with only valid $W_{(\{k_1\},k_2)}$'s and $W_{(\emptyset,k_1)}$'s, which implies that $W_{\textup{QS}}$ is not a QC-NIQC.
Besides, it is also well-known---and again easy to see---that $W_{\textup{QS}}$ is not a QC-CC (e.g., by contradiction: otherwise, feeding the state $\ket{+}=\frac{\ket{0}+\ket{1}}{\sqrt{2}}$ into $\HS^P$ would otherwise imply that $W_{\textup{supFO}}$ is a QC-CC).

\subsection{A graphical representation of the SDP constraints for our various classes of circuits}
\label{app:subsec:graphical_rep}

Looking at the SDP constraints that characterise each of the classes we considered in this work (see Eqs.~\eqref{eq:charact_W_QCCC_decomp}, \eqref{eq:charact_W_QC_convFO_decomp}, \eqref{eq:charact_W_QCQC_decomp}, and~\eqref{eq:charact_W_QC_SupFO_decomp}), one may notice some similar structure in the different decompositions.
Here we propose a graphical representation of these constraints that exploits their common features and helps visualise the structure of the different classes.

Each of the decompositions under consideration involves PSD matrices in $\L(\HS^{PA_{\K_{n-1}}^{IO}A_{k_n}^I})$ (for some subset $\K_{n-1}\subsetneq\N$ and some $k_n\notin\K_{n-1}$) and in $\L(\HS^{PA_{\N}F})$, as well as the identity matrix $\id^P\in\L(\HS^P)$. The idea of the representation we propose is to organise these PSD matrices in a graph, defined as follows.
\begin{itemize}
    \item The nodes are the various PSD matrices that appear in the decomposition. These are organised in $N+2$ layers: matrices in some $\L(\HS^{PA_{\K_{n-1}}^{IO}A_{k_n}^I})$ appear on the $n^\text{th}$ layer, for each $n=1,\ldots,N$ (from the bottom up), matrices in $\L(\HS^{PA_{\N}F})$ appear on the $(n=N+1)^\text{th}$ (top) layer, while the $\id$'s (i.e.\ the $\id^P$'s; we will drop the superscript~${}^P$) appear on the $(n=0)^\text{th}$ (bottom) layer.
    \item For any SDP constraint of the general form $\big(\sum_{k_{n+1}}\big) \Tr_{A_{k_{n+1}}^I} W_{(\cdots,k_{n+1})} = \big(\sum_{k_n}\big) W_{(\cdots,k_n)}\otimes \id^{A_{k_n}^O}$, with $1\le n\le N-1$, all matrices $W_{(\cdots,k_{n+1})}$ appearing on the LHS of the equality (and on the $(n+1)^\text{th}$ layer in the graph) are connected to all matrices $W_{(\cdots,k_n)}$ appearing on the RHS of the equality (and on the $n^\text{th}$ layer in the graph).
    \item For any SDP constraint of the form $\Tr_F W_{(\cdots)} = \big(\sum_{k_N}\big) W_{(\cdots,k_N)}\otimes \id^{A_{k_N}^O}$, for some $W_{(\cdots)}\in\L(\HS^{PA_{\N}F})$, the matrix $W_{(\cdots)}$ (that appears on the top layer in the graph) is connected to all matrices $W_{(\cdots,k_N)}$ appearing on the RHS of the equality (and on the $N^\text{th}$ layer in the graph).
    \item For any SDP constraint of the form $\big(\sum_{k_1}\big) \Tr_{A_{k_1}^I} W_{(\cdots,k_1)} = q_{(\cdots)}\id^P$ (possibly with $q_{(\cdots)}=1$), all matrices $W_{(\cdots,k_1)}$ appearing on the LHS of the equality (and on the $(n=1)^\text{th}$ layer in the graph) are connected to $q_{(\cdots)}\id$ (that appears on the bottom layer in the graph).
\end{itemize}

\medskip

For concreteness, let us start by illustrating this for the \textup{\textsf{QC-CC}} class, characterised in Eq.~\eqref{eq:charact_W_QCCC_decomp}. From the bottom to the top: the matrix $\id$ ($=\id^P$, on the bottom layer) is connected to all $W_{(k_1)}$'s (on the $(n=1)^\text{th}$ layer); then each $W_{(k_1,\ldots,k_n)}$ (for $n=1,\ldots,N-1$, on the $n^\text{th}$ layer) is connected to all $W_{(k_1,\ldots,k_n,k_{n+1})}$'s (with the same first labels $(k_1,\ldots,k_n)$, on the $(n+1)^\text{th}$ layer); finally, each $W_{(k_1,\ldots,k_N)}$ (on the $N^\text{th}$ layer) is connected to $W_{(k_1,\ldots,k_N,F)}$ (on the top layer). We thus obtain a branch-graph structure, as illustrated in Fig.~\ref{fig:graph_QCCC_N3} for the $N=3$ case.

