\end{sidewaysfigure}

One can see that these classes $\textup{\textsf{QC-NIO}}_{n^*}$ interpolate between \textup{\textsf{QC-NICC}} (obtained%
\footnote{More precisely: with a trivial $\HS^F$ (as we consider when only looking at correlations) we get exactly \textup{\textsf{QC-NICC}} for $n^*=N$. With a nontrivial $\HS^F$, for $n^*=N$ we get in fact a larger class than \textup{\textsf{QC-NICC}}, for which the first two lines of Eq.~\eqref{eq:charact_W_QCCC_decomp} are replaced by $\Tr_F W = \sum_{(k_1,\ldots,k_N)} W_{(k_1,\ldots,k_N)} \otimes \id^{A_{k_N}^O}$. (This larger class includes in particular the class \textup{\textsf{Sup}} from Ref.~\cite{Liu23}, characterised as in Eq.~\eqref{eq:def_Sup}; it thus contains QC-QCs that are not QC-CCs.)}
for $n^*=N$) and \textup{\textsf{QC-supFO}} (obtained for $n^*=1$).%
\footnote{Notice also that for $N=3$, the intermediate value $n^*=2$ recovers the 
\textup{\textsf{QC-QC}} class.}
From these we define the class $\textup{\textsf{QC-NIO}}$ to be their convex hull:
\begin{align}
    \textup{\textsf{QC-NIO}} = \textup{conv}\Big(\bigcup_{n^*=1}^N \textup{\textsf{QC-NIO}}_{n^*}\Big),
\end{align}
which thus includes both \textup{\textsf{QC-NICC}} and \textup{\textsf{QC-supFO}}.
We will now show that process matrices in \textup{\textsf{QC-NIO}} only generate correlations in ${\cal P}_\textup{NIO}$.

\bigskip

By convexity, it suffices to prove that the same claim holds true for process matrices in $\textup{\textsf{QC-NIO}}_{n^*}$, for any fixed value of $n^*$.%
\footnote{Since the claim is already known to be true for $n^*=N$ (the \textup{\textsf{QC-NICC}} class) and for $n^*=1$ (the \textup{\textsf{QC-supFO}} class), we can restrict in the proof to $1<n^*<N$, to avoid bothering with these limit cases.}

Consider therefore a process matrix $W\in\textup{\textsf{QC-NIO}}_{n^*}$ with a decomposition as in Eq.~\eqref{eq:W_NIOn_decomp} with the $W_{(k_1,\ldots,k_{n^*})}^{(k_{n^*+1},\ldots,k_N)}$'s being proportional to valid process matrices, and with now some trivial $\HS^P$ and $\HS^F$.
Similarly to what we did before, let us start by defining here, for all subsets ${\cal K}_n$ of ${\cal N}$ with $n\ge n^*$, all $k_n\in\K_n$ and all $(k_{n+1},\ldots,k_N) \in {\cal N}\backslash{\cal K}_n$,
\begin{align}
    s_{({\cal K}_n\backslash k_n,k_n)}^{(k_{n+1},\ldots,k_N)}(\vec a_{{\cal K}_n}|\vec x_{{\cal K}_n}) & \coloneqq \Tr[(M_{\vec a_{{\cal K}_n}|\vec x_{{\cal K}_n}})^T\big(W_{({\cal K}_n\backslash k_n,k_n)}^{(k_{n+1},\ldots,k_N)}\otimes\id^{A_{k_n}^O}\big)] \ge 0 \notag \\
    \text{and} \quad f_{{\cal K}_n}^{(k_{n+1},\ldots,k_N)}(\vec a_{{\cal K}_n}|\vec x_{{\cal K}_n}) & \coloneqq \!\!\sum_{k_n\in{\cal K}_n}\!\! s_{({\cal K}_n\backslash k_n,k_n)}^{(k_{n+1},\ldots,k_N)}(\vec a_{{\cal K}_n}|\vec x_{{\cal K}_n}) = \Tr\Big[(M_{\vec a_{{\cal K}_n}|\vec x_{{\cal K}_n}})^T\Big(\sum_{k_n\in{\cal K}_n}\!\! W_{({\cal K}_n\backslash k_n,k_n)}^{(k_{n+1},\ldots,k_N)}\otimes\id^{A_{k_n}^O}\Big)\Big] \ge 0.
\end{align}
Following the first steps of Eq.~\eqref{eq:proof_QCQC_causal_correl}, while adding the superscripts ${}^{(k_{n+1},\ldots,k_N)}$ as in Eq.~\eqref{eq:proof_QCsupFO_convFO_correl}, we can write%
\footnote{Still assuming, for simplicity, that all denominators are nonzero. Cf.\ Footnotes~\ref{ftn:nonzero_denom_1} and~\ref{ftn:nonzero_denom_2}.}
\begin{align}
    p(\vec a|\vec x) & = \sum_{(k_{n^*},\ldots,k_N)} 
    s_{(\N\backslash\{k_{n^*},\ldots,k_N\},k_{n^*})}^{(k_{n^*+1},\ldots,k_N)}(\cdot|\cdot)
    \ \frac{s_{(\N\backslash\{k_{n^*+1},\ldots,k_N\},k_{n^*+1})}^{(k_{n^*+2},\ldots,k_N)}(\cdot|\cdot)}{f_{\N\backslash\{k_{n^*+1},\ldots,k_N\}}^{(k_{n^*+1},\ldots,k_N)}(\cdot|\cdot)}
    \ \cdots 
    \ \frac{s_{(\N\backslash k_N,k_N)}^\emptyset(\cdot|\cdot)}{f_{\N\backslash k_N}^{(k_N)}(\cdot|\cdot)}. \label{eq:proof_QC-NIO_1}
\end{align}

Let us then further define, for all $\pi=(k_1,\ldots,k_{n^*},\ldots,k_N)$,
\begin{align}
    \tilde{p}(\pi,\vec a_{k_1,\ldots,k_{n^*}}|\vec x_{k_1,\ldots,k_{n^*}}) & \coloneqq \Tr[(M_{\vec a_{k_1,\ldots,k_{n^*}}|\vec x_{k_1,\ldots,k_{n^*}}})^T\big(W_{(k_1,\ldots,k_{n^*})}^{(k_{n^*+1},\ldots,k_N)}\otimes\id^{A_{k_{n^*}}^O}\big)] \ge 0, \notag \\
    \text{and} \quad \tilde{p}_{\pi,k_n}(a_{k_n}|\vec x_{k_1,\ldots,k_n},\vec a_{k_1,\ldots,k_{n-1}}) & \coloneqq \frac{s_{(\N\backslash\{k_n,\ldots,k_N\},k_n)}^{(k_{n+1},\ldots,k_N)}(\cdot|\cdot)}{f_{\N\backslash\{k_n,\ldots,k_N\}}^{(k_n,\ldots,k_N)}(\cdot|\cdot)} \ge 0 \quad \text{for} \ n=n^*+1,\ldots,N.
\end{align}
From the definition of $W_{({\cal K}_{n^*} \backslash k_{n^*},k_{n^*})}^{(k_{n^*+1},\ldots,k_N)}$ just before Eq.~\eqref{eq:W_NIOn_decomp}, it follows that $s_{({\cal K}_{n^*} \backslash k_{n^*},k_{n^*})}^{(k_{n^*+1},\ldots,k_N)}(\cdot|\cdot) = \sum_{(k_1,\ldots,k_{n^*-1})\in{\cal K}_{n^*} \backslash k_{n^*}} \tilde{p}(\pi,\vec a_{k_1,\ldots,k_{n^*}}|\vec x_{k_1,\ldots,k_{n^*}})$, so that from Eq.~\eqref{eq:proof_QC-NIO_1} we can write
\begin{align}
    p(\vec a|\vec x) & = \sum_{\pi=(k_1,\ldots,k_{n^*},\ldots,k_N)} \tilde{p}(\pi,\vec a_{k_1,\ldots,k_{n^*}}|\vec x_{k_1,\ldots,k_{n^*}}) \prod_{n=n^*+1}^N \tilde{p}_{\pi,k_n}(a_{k_n}|\vec x_{k_1,\ldots,k_n},\vec a_{k_1,\ldots,k_{n-1}}) \ = \ \sum_\pi p(\pi,\vec a|\vec x) \notag \\
    & \hspace{5mm} \text{with} \qquad p\big(\pi=(k_1,\ldots,k_{n^*},\ldots,k_N),\vec a\big|\vec x\big) \coloneqq \tilde{p}(\pi,\vec a_{k_1,\ldots,k_{n^*}}|\vec x_{k_1,\ldots,k_{n^*}}) \prod_{n=n^*+1}^N \tilde{p}_{\pi,k_n}(a_{k_n}|\vec x_{k_1,\ldots,k_n},\vec a_{k_1,\ldots,k_{n-1}}). \label{eq:proof_QC-NIO_2}
\end{align}

Now, it can be shown as in Eq.~\eqref{eq:sum_akn_tilde_p_supFO} that $\sum_{a_{k_n}} \tilde p_{\pi,k_n}(a_{k_n}|\vec x_{k_1,\ldots,k_n}, \vec a_{k_1,\ldots,k_{n-1}}) = 1$. Hence for $n\ge  n^*$ and any $(k_1,\ldots,k_n,k_{n+1})$, $p\big((k_1,\ldots,k_{n+1}),\vec a_{k_1,\ldots,k_n}\big|\vec x\big) = \sum_{(k_{n+2},\ldots,k_N),\vec a_{k_{n+1},\ldots,k_N}} p\big(\pi{=}(k_1,\ldots,k_N),\vec a\big|\vec x\big) = \sum_{(k_{n+2},\ldots,k_N)} \tilde{p}\big(\pi{=}(k_1,\ldots,k_N),\vec a_{k_1,\ldots,k_{n^*}}\big|\vec x_{k_1,\ldots,k_{n^*}}\big) \prod_{j=n^*+1}^n \tilde{p}_{\pi=(k_1,\ldots,k_N),k_j}(a_{k_j}|\vec x_{k_1,\ldots,k_j},\vec a_{k_1,\ldots,k_{j-1}})$ does not depend on $\vec x_{\N\backslash\{k_1,\ldots,k_n\}}$.
For $n< n^*$ on the other hand, and still any $(k_1,\ldots,k_n,k_{n+1})$, it can be shown recursively from the second to last constraint in Eq.~\eqref{eq:W_NIOn_decomp} (in a similar way to Eqs.~\eqref{eq:proof_QCCC_causal_decomp2}--\eqref{eq:proof_QCCC_causal_decomp4}, and using the definition of $W_{(k_1,\ldots,k_{n^*})}$ just before Eq.~\eqref{eq:W_NIOn_decomp} for the case $n=n^*-1$) that $p\big((k_1,\ldots,k_n,k_{n+1}),\vec a_{k_1,\ldots,k_n}\big|\vec x\big) = \sum_{(k_{n+2},\ldots,k_N),\vec a_{k_{n+1},\ldots,k_{n^*}}} \tilde{p}\big(\pi{=}(k_1,\ldots,k_N),\vec a_{k_1,\ldots,k_{n^*}}\big|\vec x_{k_1,\ldots,k_{n^*}}\big) = \Tr\big[\big(M_{\vec a_{k_1,\ldots,k_n}|\vec x_{k_1,\ldots,k_n}}\big)^T\big(\Tr_{A_{k_{n+1}}^I}W_{(k_1,\ldots,k_{n+1})}\big)\big]$, which also does not depend on $\vec x_{\N\backslash\{k_1,\ldots,k_n\}}$.

All in all, we thus find that Eq.~\eqref{eq:proof_QC-NIO_2} provides a causal decomposition of $p(\vec a|\vec x) = \sum_\pi p(\pi,\vec a|\vec x)$ that satisfies Eq.~\eqref{eq:def_causal_p}.
Recalling that each $W_{(k_1,\ldots,k_{n^*})}^{(k_{n^*+1},\ldots,k_N)}$ is assumed to be proportional to a valid process matrix, we can write $W_{(k_1,\ldots,k_{n^*})}^{(k_{n^*+1},\ldots,k_N)} = q_{(k_1,\ldots,k_{n^*},\ldots,k_N)} \tilde{W}_{(k_1,\ldots,k_{n^*})}^{(k_{n^*+1},\ldots,k_N)}$, for some fixed weight $q_{(k_1,\ldots,k_{n^*},\ldots,k_N)}$ and some now properly normalised process matrix $\tilde{W}_{(k_1,\ldots,k_{n^*})}^{(k_{n^*+1},\ldots,k_N)}$. We then have, for all $(k_1,\ldots,k_{n^*},\ldots,k_N)$,
\begin{align}
    & p\big(\pi=(k_1,\ldots,k_{n^*},\ldots,k_N)\big|\vec x\big) \, = \, \sum_{\vec  a} p\big(\pi=(k_1,\ldots,k_{n^*},\ldots,k_N),\vec a\big|\vec x\big) \notag \\
    & \hspace{10mm} = \sum_{\vec a_{k_1,\ldots,k_{n^*}}} \tilde{p}\big(\pi=(k_1,\ldots,k_{n^*},\ldots,k_N),\vec a_{k_1,\ldots,k_{n^*}}\big|\vec x_{k_1,\ldots,k_{n^*}}\big) \notag \\
    & \hspace{10mm} = q_{(k_1,\ldots,k_{n^*},\ldots,k_N)} \underbrace{{\textstyle\sum_{\vec a_{k_1,\ldots,k_{n^*}}}} \Tr\big[(M_{\vec a_{k_1,\ldots,k_{n^*}}|\vec x_{k_1,\ldots,k_{n^*}}})^T\big(\tilde{W}_{(k_1,\ldots,k_{n^*})}^{(k_{n^*+1},\ldots,k_N)}\otimes\id^{A_{k_{n^*}}^O}\big)\big]}_{=1\ (\text{validity and normalisation of }\tilde{W}_{(k_1,\ldots,k_{n^*})}^{(k_{n^*+1},\ldots,k_N)})} = q_{(k_1,\ldots,k_{n^*},\ldots,k_N)},
\end{align}
which does not depend on $\vec x$ and concludes the proof that the correlations are in ${\cal P}_{\textup{NIO}}$.

\bigskip

Beyond the \textup{\textsf{QC-NIO}} class introduced here, one may also construct even larger classes whose correlations are restricted to be in ${\cal P}_\textup{NIO}$. E.g., one can conceive classes of a similar type as $\textup{\textsf{QC-NIO}}_{n^*}$, but allowing for different critical values $n^*$ attached to different orders $(k_1,\ldots,k_N)$ (and then considering convex combinations of such classes). Formalising this properly becomes rather tedious---we only illustrate it with a specific example, depicted in Fig.~\ref{fig:graph_QCNIO_N4_diff_nstar} using the graphical representation of Appendix~\ref{app:subsec:graphical_rep}.

