\begin{prop}\label{prop:zero-coupon-price} 
Let us define, for $t\in[0,T],$ $f_{t}(.)$
by
\begin{equation}
f_{t}(s):=r_{0}(s)+\int_{0}^{t}R_{\kappa_{r}G_{r}}(s,u)r_{0}(u)du+\frac{\eta_{r}}{\kappa_{r}}\int_{0}^{t}R_{\kappa_{r}G_{r}}(s,u)\;dW_{r}^{\mathbb{Q}}(u),\;t\leq s,\label{eq:forward_rate}
\end{equation}
with $R_{\kappa_{r}G_{r}}$ the resolvent associated to $\kappa_{r}G_{r}$
with the convention $\frac{R_{\kappa_{r}G_{r}}}{\kappa_{r}}=G_{r}$
if $\kappa_{r}=0$. The price of the zero-coupon bond at time $t\in[0,T],$
is given by 
\begin{equation}
P(t,T)=A(t,T)\exp\bigg(-\int_{t}^{T}f_{t}(s)\:ds\bigg),\label{eq:zero_coupon_expression}
\end{equation}
with $A(t,T)$ the time-dependent function given by 
\[
A(t,T):=\exp\bigg(-\int_{t}^{T}\bigg(\int_{u}^{T}R_{\kappa_{r}G_{r}}(s,u)r_{0}(u)ds+\frac{\eta_{r}^{2}}{2}B_{G_{r}}^{2}(u,T)\:\bigg)\:du\bigg).
\]
Moreover, the dynamics of ($P(t,T))_{t\in[0,T]}$ are given by 
\[
\frac{dP(t,T)}{P(t,T)}=r_{t}\:dt-\eta_{r}B_{G_{r}}(t,T)dW_{r}^{\mathbb{Q}}(t),
\]
with 
\begin{align}\label{eq:BGr}
B_{G_{r}}(t,T):=\frac{1}{\kappa_{r}}\int_{t}^{T}R_{\kappa_{r}G_{r}}(s,t)\;ds.    
\end{align}
\end{prop}
\begin{proof}
Using the resolvent associated to the kernel $\kappa_{r}G_{r}$ and
using  \cite[Theorem A.3]{key-4}, we have that $(r_{t})_{0\leq t\leq T}$
is the strong solution of the following equation
\[
r_{t}=r_{0}(t)+\int_{0}^{t}R_{\kappa_{r}G_{r}}(t,s)r_{0}(s)ds+\frac{1}{\kappa_{r}}\int_{0}^{t}R_{\kappa_{r}G_{r}}(t,s)\eta_{r}\;dW_{r}^{\mathbb{Q}}(s),\:0\leq t\leq T,
\]
with the convention $\frac{R_{\kappa_{r}G_{r}}}{\kappa_{r}}=G_{r}$
if $\kappa_{r}=0.$ In this case, we have that, for $0\leq t\leq T,$
\[
\int_{t}^{T}r_{s}ds=\int_{t}^{T}r_{0}(s)ds+\int_{t}^{T}\int_{0}^{s}R_{\kappa_{r}G_{r}}(s,u)r_{0}(u)\:duds+\frac{1}{\kappa_{r}}\int_{t}^{T}\int_{0}^{s}R_{\kappa_{r}G_{r}}(s,u)\eta_{r}\;dW_{r}^{\mathbb{Q}}(u)ds.
\]
Using the definition of $f_{t}$ given by \eqref{eq:forward_rate} together with an application of stochastic Fubini's theorem,
we obtain that 
\[
\int_{t}^{T}r_{s}ds=\int_{t}^{T}f_{t}(s)ds+\int_{t}^{T}\int_{u}^{T}R_{\kappa_{r}G_{r}}(s,u)r_{0}(u)dsdu+\eta_{r}\int_{t}^{T}\underbrace{\frac{1}{\kappa_{r}}\int_{u}^{T}R_{\kappa_{r}G_{r}}(s,u)\;ds}_{:=B_{G_{r}}(u,T)}dW_{r}^{\mathbb{Q}}(u).
\]
Thus, for $t\in[0,T],$ conditional on $\mathcal{F}_{t}$, the random variable $\int_{t}^{T}r_{s}ds|$ is
Gaussian with mean 
\[
\E^{\mathbb{Q}}\left[\int_{t}^{T}r_{s}ds\mid \mathcal{F}_{t}\right]=\int_{t}^{T}f_{t}(s)ds+\int_{t}^{T}\int_{u}^{T}R_{\kappa_{r}G_{r}}(s,u)r_{0}(u)dsdu,
\]
and variance
\[
\mathbb{V}^{\mathbb{Q}}\left[\int_{t}^{T}r_{s}ds\mid\mathcal{F}_{t}\right]=\eta_{r}^{2}\int_{t}^{T}B_{G_{r}}^{2}(u,T)\:du.
\]
Therefore, we readily deduce that 
\[
P(t,T)=\exp\bigg(-\int_{t}^{T}f_{t}(s)ds-\int_{t}^{T}\bigg(\int_{u}^{T}R_{\kappa_{r}G_{r}}(s,u)r_{0}(u)ds+\frac{\eta_{r}^{2}}{2}B_{G_{r}}^{2}(u,T)\:\bigg)\:du\bigg),
\]
and we finally obtain that 
\[
\frac{dP(t,T)}{P(t,T)}=r_{t}dt-\eta_{r}\int_{t}^{T}\frac{1}{\kappa_{r}}R_{\kappa_{r}G_{r}}(s,t)ds\:dW_{r}^{\mathbb{Q}}(t).
\]
\end{proof}

\begin{rem}\label{R:stripr0}
Proposition \ref{prop:zero-coupon-price} provides a natural
way to estimate the function $r_{0}(.)$ such that the interest rate
model matches perfectly the initial term-structure of market bond
prices. In fact from \eqref{eq:zero_coupon_expression}, we deduce
that 
\[
\int_{0}^{t}r_{0}(s)\:\bigg(1+\kappa_{r}B_{G_{r}}(s,t)\bigg)\:ds=-\ln P(0,t)-\int_{0}^{t}\frac{\eta_{r}^{2}}{2}B_{G_{r}}^{2}(s,t)\:ds.
\]
Thus, if we assume that, for some given maturities $0=T_{0}<T_{1}<...<T_{n}$,
we have the initial term-structure of market bond prices $P^{Market}(0,T_{i})$,
and that $r_{0}(t)$ is piecewise constant such that
\begin{equation}
r_{0}(t)=-\frac{\ln P^{Market}(0,T_{i})-\ln P^{Market}(0,T_{i-1})+\frac{\eta_{r}^{2}}{2}\int_{T_{i-1}}^{T_{i}}B_{G_{r}}^{2}(u,T_{i})\:du}{(T_{i}-T_{i-1})+\kappa_{r}\int_{T_{i-1}}^{T_{i}}B_{G_{r}}(s,T_{i})\,ds},\:t\in[T_{i-1},T_{i}),\label{eq:link_r0_ZC}
\end{equation}
then $P(0,T_{i})=P^{Market}(0,T_{i}),\:i=1,...,n.$ \QEDA
\end{rem}
Based on the expression for the pricing of zero-coupon bonds, we can
now easily deduce explicit expressions for the pricing of zero-coupon
bond call and put options. 
\begin{prop}
\label{prop:pricing_ZC_options}Let us consider $T-$maturity zero-coupon
bond call option $(P(T,S)-K)_{+}$ and put option $(K-P(T,S))_{+}$
with $S>T$ and $K$ the strike of the option. The arbitrage-free
price at time $t\in[0,T]$ of the call option is given by 
\[
\text{Call}_{ZC}(t,T,S,K)=P(t,S)\phi(-d_{1}(t,T))-KP(t,T)\phi(-d_{2}(t,T)),
\]
and the price of the put option is given by 
\[
\text{Put}_{ZC}(t,T,S,K)=KP(t,T)\phi(d_{2}(t,T))-P(t,S)\phi(d_{1}(t,T)),
\]
where $\phi(.)$ is the cumulative function of a normal distribution
and 
\begin{equation}
d_{1}(t,T)=d_{2}(t,T)-v(t, T, S),\label{eq:d_1}
\end{equation}
\begin{equation}
d_{2}(t,T)=\frac{1}{v(t,T,S)\sqrt{T-t}}\log\bigg(\frac{KP(t,T)}{P(t,S)}\bigg)+\frac{v(t,T,S)\sqrt{T-t}}{2},\label{eq:d_2}
\end{equation}
where 
\begin{equation}
v(t,T,S)^{2}=\frac{\eta_{r}^{2}\int_{t}^{T}\bigg(B_{G_{r}}(s,T)-B_{G_{r}}(s,S)\bigg)^{2}ds.}{T-t}\label{eq:variance_ZC_bond_option_pricing}
\end{equation}
\end{prop}
\begin{proof}
Let us consider the call option. We know that the arbitrage-free price
of a call on zero-coupon bond satisfies 
\[
\text{Call}_{ZC}(t,T,S,K)=P(t,T)\E^{\mathbb{Q}^{T}}\left[(P(T,S)-K)_{+} \mid \mathcal F_t\right].
\]
From Proposition \ref{prop:zero-coupon-price}, we know that under
the risk-neutral measure $\mathbb{Q},$
\[
\frac{dP(t,S)}{P(t,S)}=r_{t}\:dt-\eta_{r}B_{G_{r}}(t,S)dW_{r}(t).
\]
Therefore, for $S>T,$ we obtain that under the $T-$forward measure
$\mathbb{Q}^{T}$\footnote{We introduce the forward measure in Section \ref{sec:forward_measure}.}, the zero-coupon bond dynamics is given by 
\[
\frac{dP(t,S)}{P(t,S)}=\bigg(r_{t}+\eta_{r}^{2}B_{G_{r}}(t,S)B_{G_{r}}(t,T)\bigg)\:dt-\eta_{r}B_{G_{r}}(t,S)dW_{r}^{\mathbb{Q}^{T}}(t).
\]
Moreover, under $\mathbb{Q}^{T},$ we have that 
\[
d\bigg(\frac{P(t,S)}{P(t,T)}\bigg)=\frac{P(t,S)}{P(t,T)}\eta_{r}\bigg(B_{G_{r}}(t,T)-B_{G_{r}}(t,S)\bigg)dW_{r}^{\mathbb{Q}^{T}}(t)
\]
and we deduce that 
\[
\E^{\mathbb{\mathbb{Q}}^{T}}\left[(P(T,S)-K)_{+}\mid \mathcal{F}_{t}\right]=\frac{P(t,S)}{P(t,T)}\phi(-d_{1}(t,T))-K\phi(-d_{2}(t,T)),
\]
where $\phi(.)$ is the cumulative function of a normal distribution
and $d_{1},d_{2}$ are given by \eqref{eq:d_1}-\eqref{eq:d_2}. Finally,
using the call/put parity, we easily deduce the form of the put price. 
\end{proof}
%
Based on zero-coupon bonds call or put options, we can price cap and
floor options since, as explained in \cite{key-9}, cap and floor options
can be decomposed into a sum of zero-coupon bonds options. In fact, 
the cap and floor payoffs are of the form

\[
\text{Cap}=\sum_{i=1}^{\beta}(T_{i}-T_{i-1})\:(L(T_{i-1},T_{i})-K)_{+},
\]
\[
\text{Floor}=\sum_{i=1}^{\beta}(T_{i}-T_{i-1})\:(K-L(T_{i-1},T_{i}))_{+}
\]
where $L$ is the reference rate and $(T_{1},...,T_{\beta})$ are
the payment date. Using \cite{key-9}, we have that the price at time $t< T_0$, of cap and floor options is given by
\[
\text{Cap}(t,\beta,K)=\sum_{i=1}^{\beta}(1+K(T_{i}-T_{i-1}))\:\text{Put}_{ZC}\left(t,T_{i-1},T_i,\frac{1}{1+K(T_{i}-T_{i-1})}\right). 
\]
\[
\text{Floor}(t,\beta,K)=\sum_{i=1}^{\beta}(1+K(T_{i}-T_{i-1}))\:\text{Call}_{ZC}\left(t,T_{i-1},T_i,\frac{1}{1+K(T_{i}-T_{i-1})}\right).
\]
This enable us to calibrate our Gaussian Volterra model for interest rate to the market data of cap and floor options for any Volterra kernel $G_{r}(.)$. 

\subsection{Forward measure and pricing of derivatives on the index}\label{sec:forward_measure}

Let us now focus on the pricing financial derivatives on the index $I$ in our framework.
Standard arguments imply that the arbitrage-free price of financial
derivatives is obtained by taking the discounted value of the payoffs
under a risk-neutral measure $\mathbb{Q}$. In this case, if we consider
a general $T-$maturity derivative of the form 
\[
H_{T}:=h(I_{T})\in L^{2}(\mathbb{Q}),
\]
where $h(.)$ is a continuous positive function, the arbitrage-free
price at time $t\in[0,T],$ is given by 
\begin{equation}
V_{t}=\E^{\mathbb{Q}}\left[e^{-\int_{t}^{T}r_{s}ds}H_{T}\mid \mathcal{F}_{t}\right].\label{eq:price_derivatives}
\end{equation}
In the presence of stochastic interest rates, it is impossible to
obtain a more explicit form of the price if we consider the formulation
under the risk-neutral measure. One technique for dealing with this
problem is to switch from the risk-neutral measure to the $T-$forward
neutral measure. Thus, let us introduce the  $T-$forward neutral
measure denoted by $\mathbb{Q}^{T}$ which is equivalent to the risk-neutral
measure $\mathbb{Q}$. The change of measure from the risk-neutral
measure $\mathbb{Q}$ to the $T-$forward measure $\mathbb{Q}^{T}$
satisfies 
\[
\frac{d\mathbb{Q}^{T}}{d\mathbb{\mathbb{Q}}}\bigg|_{t}:=e^{-\int_{0}^{t}r(s)\:ds}\frac{P(t,T)}{P(0,T)}.
\]

We can now introduce the $T-$forward index denoted by $(I_{t}^{T})_{0\leq t\leq T}$
and defined as, for $0\leq t\leq T,$
\[
I_{t}^{T}:=\E^{\mathbb{Q}^{T}}\left[I_{T}\mid \mathcal{F}_{t}\right]=\frac{I_{t}}{P(t,T)}.
\]
Since under the forward measure the financial index divided by the
zero-coupon bond is a martingale, we obtain that the process $(I_{t}^{T})_{0\leq t\leq T}$
has the following dynamic 
\begin{align}\label{eq:dyn_forward_inflation}
\frac{dI_{t}^{T}}{I_{t}^{T}}=\nu_{t}\:dW_{I}^{\mathbb{Q}^{T}}(t)+\eta_{r}B_{G_{r}}(t,T)\:dW_{r}^{\mathbb{Q}^{T}}(t),    
\end{align}
with
\begin{equation}
\nu_{t}=g_{0}^{T}(t)+\int_{0}^{t}G_{\nu}(t,s)\kappa_{\nu}\:\nu_{s}ds+\int_{0}^{t}G_{\nu}(t,s)\:\eta_{\nu}\:dW_{\nu}^{\mathbb{Q}^{T}}(s),\label{eq:vol_forward_measure}
\end{equation}
 where $(W_{r}^{\mathbb{Q}^{T}},W_{I}^{\mathbb{Q}^{T}},W_{\nu}^{\mathbb{Q}^{T}})$
is a $3-$dimensional correlated Brownian motion under the $T-$forward
measure $\mathbb{Q}^{T}$ and 
\[
g_{0}^{T}(t)=g_{0}(t)-\eta_{\nu}\eta_{r}\rho_{r\nu}\int_{0}^{t}G_{\nu}(t,s)\:B_{G_{r}}(s,T)\:ds.
\]
By combining the forward measure and the $T-$forward financial index,
we obtain that the arbitrage-free price of a derivative (\ref{eq:price_derivatives})
satisfies 
\[
V_{t}=P(t,T)\E^{\mathbb{Q}^{T}}\left[\,h(e^{\log I_{T}^{T}})\,\mid \mathcal{F}_{t}\right].
\]
By switching from the risk-neutral measure to the $T-$forward measure,
we get a simpler framework for pricing financial derivatives. In the
following, we will show that the characteristic function of the log-forward
index $(\log I_{t}^{T})_{0\leq t\leq T}$ admits an explicit form.
This opens the way to a fast pricing of financial derivatives using
Fourier methods. Moreover, using hedging approaches developed in
several papers \cite{key-7,key-11,key-20}, some hedging strategies
can also be deduced by Fourier methods for contingent claims that
admit a Fourier representation. 

\section{The characteristic function of the log-forward index\protect\label{sec:The-characteristic-function} }

The aim of this section is to derive an analytical form of the characteristic
function of the log-forward index $(I_{t}^{T})_{0\leq t\leq T}$ with  dynamics 
\eqref{eq:dyn_forward_inflation} under $\mathbb{Q}^{T}$  and apply it for  Fourier pricing of  derivatives on the index.  \\

We start by recalling some results on operator theory in Hilbert spaces as well as introducing some notations. Let $\mathbf{A}$ be a linear compact operator acting on $L^{2}([0,T],\mathbb{C})$. Then, $\mathbf{A}$ is a bounded operator i.e. there exists $C>0$ such that, for all $f\in L^{2}([0,T],\mathbb{C})$, $||\mathbf{A}f||\leq C ||f||$ and for $B:=\{f\in L^{2}([0,T],\mathbb{C}): ||f||\leq 1\}$, the closure of $\mathbf{A}(B)$ is compact in $L^{2}([0,T],\mathbb{C})$. $\mathbf{A}$ is an integral operator if $\mathbf{A}$ a linear operator induced by a kernel $G\in L^{2}([0,T]^2,\mathbb{R})$ such that, for $f\in L^{2}([0,T],\mathbb{C})$ and $s\in[0,T],$
\[
(\mathbf{A}f)(s)=\int_{0}^{T}G(s,w)f(w)dw.
\]
Moreover, if $\mathbf{A}$ is a integral operator, then $\mathbf{A}$ is a Hilbert-Schmidt operator on  $L^{2}([0,T],\mathbb{C})$ into itself and is in particular compact. The trace of an operator, denoted by $\text{Tr}(.)$, is defined for operators of trace class where a compact operator $\mathbf{A}$ is said to be of trace class if
\[
\text{Tr}(\mathbf{A})=\sum_{n\geq 1} \langle \mathbf{A} v_n, v_n \rangle <\infty,
\]
for a given orthonormal basis $(v_n)_{n\geq 1}$. For more details about the trace of an operator, we refer to \cite[Section
A]{key-4} and the references therein. \\

Let us now introduce some notations and properties:
\begin{itemize}
\item $\langle \cdot,\cdot\rangle_{L^{2}}$ denotes the following product on $L^{2}([0,T],\mathbb{C})$
\[
\langle f,g\rangle_{L^{2}}=\int_{0}^{T}f(s)g(s)ds,\quad f,g\in L^{2}([0,T],\mathbb{C}).
\]
Note that $\langle\cdot,\cdot\rangle_{L^{2}}$ is the inner product in $L^{2}([0,T],\mathbb{R})$ but not in $L^{2}([0,T],\mathbb{C})$. 
\item For any kernels $G_{1},G_{2}\in L^{2}([0,T]^{2},\mathbb{\mathbb{R}}),$
the $\star-$product is defined by
\[
(G_{1}\star G_{2})(s,w)=\int_{0}^{T}G_{1}(s,z)G_{2}(z,w)dz, \quad (s,w)\in[0,T]^{2}.
\]
\item For a kernel $G,$ $G^{*}$ denotes the adjoint kernel such that,
for $(s,w)\in[0,T]^{2},$
\[
G^{*}(s,w)=G(w,s),
\]
and $\mathbf{G}^{*}$ is the operator induced by $G^{*}.$
\item $\text{id}$ denotes the identity operator such that $(\text{id}f)=f$,  $f\in L^{2}([0,T],\mathbb{C})$. 
\end{itemize}

\subsection{Semi-explicit expression}

We now derive a semi-explicit form for the characteristic function of
the log-forward index in our framework. \\

To this end, we consider an
approach similar to \cite{key-4} which deduces the explicit form
of the log-price characteristic function in equity markets with a 
Volterra Stein-Stein volatility model. Here, we show that this result
can be extended to a framework where interest rates are also stochastic.
As in \cite{key-4}, we consider the expression of
the adjusted conditional mean of $\nu_{t}$ and then we define a linear
operator $\mathbf{\Psi}_{t}^u$ in $L^{2}([0,T],\mathbb{C})$ that will
be useful for the expression of the characteristic function.
The adjusted conditional mean of $\nu_{t}$ denoted by $g_{t}$ is
given by 
\[
g_{t}(s)=1_{t\leq s}\E^{\mathbb{Q}^{T}}\left[\nu_{s}-\int_{t}^{T}G_{\nu}(s,w)\kappa_{\nu}\nu_{w}dw\mid \mathcal{F}_{t}\right],\quad s,t\leq T,
\]
and we can easily show that $g_{t}$ reduces to 
\[
g_{t}(s)=1_{t\leq s}\bigg(g_{0}^{T}(s)+\int_{0}^{t}G_{\nu}(s,w)\kappa_{\nu}\nu_{w}dw+\int_{0}^{t}G_{\nu}(s,w)\eta_{\nu}\:dW_{\nu}^{\mathbb{Q}^{T}}(w)\bigg),\quad s,t\leq T.
\]

\begin{defn}
For $u\in\mathbb{C}$ such that $0\leq\mathcal{\mathfrak{R}}(u)\leq1,$
the operator $\mathbf{\Psi}_{t}^{u}$ acting on $L^{2}([0,T],\mathbb{C})$
is defined by 
\begin{equation}
\mathbf{\Psi}_{t}^{u}:=(\text{id}-b^{u}\mathbf{G}_{\nu}^{*})^{-1}a^{u}(\text{id}-2a^{u}\tilde{\mathbf{\Sigma}}_{t}^{u})^{-1}(\text{id}-b^{u}\mathbf{G}_{\nu})^{-1},\quad t\leq T,\label{eq:def_psi_t}
\end{equation}
where:


\begin{itemize}
\item $\mathbf{G}_{\nu}$ is the integral operator induced by $G_{\nu}(.)$
and $\mathbf{G}_{\nu}^{*}$ the adjoint operator,
\item $a^{u}:=\frac{1}{2}(u^{2}-u)$ and $b^{u}:=\kappa_{\nu}+\eta_{\nu}u\rho_{I\nu},$
\item $\tilde{\mathbf{\Sigma}}_{t}^{u}$ is the adjusted covariance integral
operator such that 
\[
\tilde{\mathbf{\Sigma}}_{t}^{u}=(\text{id}-b^{u}\mathbf{G}_{\nu})^{-1}\mathbf{\Sigma}_{t}(\text{id}-b^{u}\mathbf{G}_{\nu}^{*})^{-1},
\]
with $\mathbf{\Sigma_{t}}$ the integral operator associated with
the covariance kernel given by 
\[
\Sigma_{t}(s,w)=\eta_{\nu}^{2}\int_{t}^{T}G_{\nu}(s,z)G_{\nu}(w,z)dz,\;t\leq s,u\leq T.
\] 
\end{itemize}
Note that using similar arguments than in the proof of \cite[Lemma 5.6.]{abi2021markowitz}, we can prove that $\mathbf{\Psi}_{t}^{u}$ is well defined and is a bounded linear operator acting on $L^{2}([0,T],\mathbb{C})$. 
\end{defn}

Based now on $g_{t}$ and $\mathbf{\Psi}_{t}^{u}$, we deduce a semi-explicit
expression of the characteristic function. The methodology used in
\cite{key-4} to deduce the analytical expression of the characteristic
function can be extended to a framework with stochastic interest rates.
Nevertheless, to extend these results, we need to consider the process
$h_{t}^{u}(.)$ defined, for $u\in\mathbb{C}$ such that $0\leq\mathcal{\mathfrak{R}}(u)\leq1,$
as
\[
h_{t}^{u}(s):=g_{t}(s)+1_{t\leq s}\bigg(\rho_{Ir}\eta_{r}B_{G_{r}}(s,T)-\int_{t}^{s}G_{\nu}(s,w)\:(b^{u}\rho_{Ir}-u\eta_{\nu}\rho_{\nu r})\eta_{r}B_{G_{r}}(w,T)\:dw\bigg),\;s,t\leq T,
\]
in order to take account of the correlations between the processes, recall the definition of $B_{G_r}$ in \eqref{eq:BGr}. 
In particular when $\rho_{Ir}=\rho_{\nu r}=0$, $h_{t}^{u}(.)$ reduces
to $g_{t}(.)$ and we recover the framework of \cite{key-4}. 

\begin{thm}
\label{thm:chf_general} Let $g_{0}(.)$ be given by \eqref{eq:g_0_t}
and $G_{\nu}(.)$ a Volterra kernel as in Definition \ref{def:L2_kernel-1}. Fix
$u\in\mathbb{C}$ such that $0\leq\mathcal{\mathfrak{R}}(u)\leq1,$
then, for all $t\leq T$,
\begin{equation}
\E^{\mathbb{Q}^{T}}\bigg[\exp\bigg(u\log\frac{I_{T}^{T}}{I_{t}^{T}}\bigg)\bigg|\mathcal{F}_{t}\bigg]=\exp\left(\phi_{t}^{u}+\chi_{t}^{u}+\langle h_{t}^{u},\mathbf{\Psi}_{t}^{u}h_{t}^{u}\rangle_{L^{2}}\right),\label{eq:chf_explicit}
\end{equation}
with:
\end{thm}
\begin{itemize}
\item $\mathbf{\Psi}_{t}^{u}$ given by \eqref{eq:def_psi_t},
\item $\phi_{t}^{u}=-\int_{t}^{T}\text{Tr}(\mathbf{\Psi}_{s}^{u}\dot{\mathbf{\Sigma}_{s}})ds,$
where $\dot{\mathbf{\Sigma}_{t}}$ is the strong derivative of $t\to\Sigma_{t}$
induced by the kernel 
\[
\dot{\mathbf{\Sigma_{t}}}(s,u)=-\eta_{\nu}^{2}G_{\nu}(s,t)G_{\nu}(u,t),\;a.e.
\]
\item $\chi_{t}^{u}=\frac{1}{2}(u^{2}-u)\int_{t}^{T}(1-\rho_{Ir}^{2})\eta_{r}^{2}B_{G_{r}}(s,T)^{2}ds.$
\end{itemize}
\begin{proof}
The proof is given in Section \ref{sec:Proofs}. 
\end{proof}
%

\subsection{Numerical implementation and Fourier pricing  \protect\label{subsec:numerical_implementation_general_kernels}}

For a practical perspective, we propose a natural way of approximating
the expression of the characteristic function when we consider general
Volterra kernels that lead, for example, to non-Markovian models such
as the fractional or shifted fractional kernels. This approximation is
based a natural discretization of the inner product $\langle.,.\rangle_{L^{2}}$.
In this section, for sake of simplicity, we fix $t=0$. \\
\\
As proposed by \cite{key-4}, we can approximate the explicit
expression of the characteristic function \eqref{eq:chf_explicit}
by an approximate closed form solution using a simple disctretization
of the operator $\mathbf{\Psi}_{0}^{u}$ \emph{\`a la} Fredholm. To
this end, for fixed $N\in\mathbb{N},$ we consider a partition  of $[0,T]$
with $t_{i}=i\frac{T}{N}$ for $i=0,\ldots,N.$ Then,
for $u\in\mathbb{C}$ such that $0\leq\mathcal{\mathfrak{R}}(u)\leq1,$
we can approximate the operator $\mathbf{\Psi}_{0}^{u}$ by a $N\times N$
matrix denoted $\mathbf{\Psi}_{0}^{u;\,N}$ and defined by
\begin{equation}
\mathbf{\Psi}_{0}^{u;\,N}:=(I_{N}-b^{u}(\mathbf{G}_{\nu}^{N})^{T})^{-1}a^{u}(I_{N}-2a^{u}\tilde{\mathbf{\Sigma}}_{0}^{u;\,N})^{-1}(I_{N}-b^{u}\mathbf{G}_{\nu}^{N})^{-1},\label{eq:approx_operator}
\end{equation}
where $I_{N}$ is the $N\times N$ identity matrix, $\mathbf{G}_{\nu}^{N}$
is the lower triangular matrix such that 
\begin{equation}
G_{\nu,\:ij}^{N}:=1_{j\leq i-1}\int_{t_{j-1}}^{t_{j}}G_{\nu}(t_{i-1},s)ds,\;1\leq i,j\leq N, \label{eq:G_matrix}
\end{equation}
and 
\[
\tilde{\mathbf{\Sigma}}_{0}^{u;\,N}:=\frac{T}{N}(I_{N}-b^{u}\mathbf{G}_{\nu}^{N})^{-1}\mathbf{\Sigma}_{0}^{N}(I_{N}-b^{u}(\mathbf{G}_{\nu}^{N})^{T})^{-1},
\]
with $\mathbf{\Sigma}_{0}^{N}$ the $N\times N$ discretized covariance
matrix given by 
\begin{equation}
\mathbf{\Sigma}_{0}^{i,j;\:N}:=\eta_{\nu}^{2}\int_{0}^{T}G_{\nu}(t_{i-1},s)G_{\nu}(t_{j-1},s)ds,\;1\leq i,j\leq N. \label{eq:Sigma_matrix}
\end{equation}

When we consider kernels of the form 
\[
G_\nu(t,s)=\frac{(t-s+\varepsilon)^{H-1/2}}{\Gamma(H+1/2)},~\varepsilon\geq 0, 
\] with $H\in(0,1)$ for $\epsilon=0$ and $H\in \mathbb{R}$ for $\varepsilon>0$, we observe that the $N\times N$ matrix \eqref{eq:G_matrix}-\eqref{eq:Sigma_matrix} can be computed in closed form
\[
G_{\nu,\:ij}^{N}=1_{j\leq i-1} \frac{(t_{i-1}-t_{j-1}+\varepsilon)^{\alpha}-(t_{i-1}-t_{j}+\varepsilon)^{\alpha}}{\Gamma(\alpha+1)},~1\leq i, j\leq N, 
\]
\[
\mathbf{\Sigma}_{0}^{i,j;\:N}=\frac{\eta_\nu^2~t_{i-1}~(t_{i-1}+\varepsilon)^{\alpha-1} (t_{j-1}+\varepsilon)^{\alpha-1}  }{\Gamma(\alpha)^2} F_1(1,1-\alpha,1-\alpha,2,\frac{t_{i-1}}{t_{j-1}+\varepsilon},\frac{t_{i-1}}{t_{i-1}+\varepsilon}),~\mathbf{\Sigma}_{0}^{i,j;\:N}=\mathbf{\Sigma}_{0}^{j,i;\:N}, ~1\leq i\leq j\leq N, 
\]
where $\alpha:=H+1/2$ and $F_1(a,b,c,d,x,y)$ is the Appell hypergeometric function of the first kind given by 
\[
F_1(\alpha,\beta,\gamma,\delta,x,y)=\sum_{m,n=0}^{\infty} \frac{(\alpha)_{m+n}(\beta)_m(\gamma)_n}{(\delta)_{m+n} m!n!} x^m y^n\,
\]
with $(.)_n$ the Pochhammer symbol such that 
\[
(x)_n=\prod_{k=1}^n (x-k+1). 
\]\\

Based on the approximate operator, we now deduce a closed form approximate solution to the characteristic function. Relying on 
\cite{abijaber_guellil}, we have that $\phi_{t}^{u}$, that appears in \eqref{eq:chf_explicit},
can be rewritten in term of the Fredholm determinant such that $$\phi_{t}^{u}=i\pi n_t(u)-\frac{1}{2}\log(\det(\text{id}-2a^u\tilde{\mathbf{\Sigma}}_{t}^{u})),$$ where $n_t(u)$ is
the net number of times $\det(\text{id}-2a^u\tilde{\mathbf{\Sigma}}_{t}^{u})$ crosses the negative real axis between $0$ and $u$. 
The reason we have rewritten $\phi_t^u$ is that this enables us to use the Fredholm determinant to calculate $\phi_t^u$, instead of having to discretize the trace-dependent expression which would require the computation of $\mathbf{\Psi}_{t}^{u}$ for several values of $t$. 
In this case, if for $N\in\mathbb{N}$ and for $u\in\mathbb{C}$ such
that $0\leq\mathcal{\mathfrak{R}}(u)\leq1,$ we consider the $N-$dimensional
vector $h_{0}^{u;\,N}=(h_{0}^{u}(t_{0}),...,h_{0}^{u}(t_{N}))$ with
$t_{i}=i\frac{T}{N}$, a natural approximation of the characteristic
function is given by
\begin{equation}
E^{\mathbb{Q}^{T}}\bigg[\exp\bigg(u\log\frac{I_{T}^{T}}{I_{0}^{T}}\bigg)\bigg]=\exp(\phi_{0}^{u}+\chi_{0}^{u}+\langle h_{0}^{u},\mathbf{\Psi}_{0}^{u}h_{0}^{u}\rangle_{L^{2}})\approx e^{\pi i n_0(u)}\frac{\exp\left(\chi_{0}^{u}+\frac{T}{N}(h_{0}^{u;\,N})^{T}\mathbf{\Psi}_{0}^{u;\,N}h_{0}^{u;N}\right)}{\det(\mathbf{\Phi}_{0}^{u;\,N})^{1/2}},\label{eq:approx_fractional_kernel_op_disc}
\end{equation}
with:
\begin{itemize}
\item $\mathbf{\Psi}_{0}^{u;\,N}$ the approximate operator defined by \eqref{eq:approx_operator},
\item $\mathbf{\Phi}_{0}^{u;\,N}:=(I_{N}-2a^{u}\tilde{\mathbf{\Sigma}}_{0}^{u;\,N}),$ 
\item $\chi_{0}^{u}=\frac{1}{2}(u^{2}-u) (1-\rho_{Ir}^{2})\eta_{r}^{2}\int_{0}^{T}B_{G_{r}}(s,T)^2ds.$
\end{itemize}

\begin{rem}
To compute $\chi_{0}^{u}$, we need to compute the integral of the form $\int_{0}^{T}B_{G_{r}}(s,T)^2ds$, where $B_{G_{r}}(s,T)$ is defined by \eqref{eq:BGr} and admits an explicit expression for some well-known kernels as revealed by Table \ref{tab:Resolvents_example}. However, except for the indicator or exponential kernels, the integral $\int_{0}^{T}B_{G_{r}}(s,T)^2ds$ does not have an explicit expression and needs to be computed numerically. \QEDA
\end{rem}

Let us now discuss the pricing of equity derivatives. From Section
\ref{sec:forward_measure}, we know that the arbitrage-free
price, at time $t\in[0,T]$, of a financial derivative $H_{T}=h(I_{T})\in L^{2}$
is given by
\[
V_{t}=P(t,T)\:E^{\mathbb{\mathbb{Q}}^{T}}\bigg(h(e^{\log I_{T}^{T}})\:|\mathcal{F}_{t}\bigg),
\]
where $P(t,T)$ is the price of a zero-coupon bond of maturity $T$.
Exploiting the Fourier link between the density function and the characteristic
function, we can easily deduce how to efficiently compute the price
of vanilla options such as call and put options using a Fourier method.
For $u\in\mathbb{R}$, let us consider $\varphi_{t}^{u}$ defined
by 
\[
\varphi_{t}^{u}=\E^{\mathbb{Q}^{T}}\bigg[\exp\bigg(iu\log\frac{I_{T}^{T}}{I_{t}^{T}}\bigg)\bigg|\mathcal{F}_{t}\bigg],
\]
then, from \cite{key-18}, the price at time $t\in[0,T],$ of a call
option $(I_{T}-K)_{+}$ is given by 
\begin{equation}
V_{t}=P(t,T)\:\bigg[I_{t}^{T}-\frac{K}{\pi}\int_{0}^{+\infty}\mathfrak{Re}\bigg(e^{(iu+1/2)k_{t}}\varphi_{t}^{u-i/2}\bigg)\:\frac{du}{u^{2}+1/4}\bigg],\label{eq:lewis_price_call}
\end{equation}
where $k_{t}:=\log\frac{I_{t}^{T}}{K}$. Using a numerical integration
of \eqref{eq:lewis_price_call}, we can efficiently price call options
as well as calibrate the model to equity market data. In this paper,
we use the Gauss-Laguerre quadrature numerical integration which has
been demonstrated to be efficient in the context of option pricing
(see \cite{key-7}). In practice, for a general kernel function $G_{\nu}(.)$,
such as the fractional or path-dependent kernels, we have to approximate
the expression of the characteristic function of $\log\frac{I_{T}^{T}}{I_{t}^{T}}$
that appears in the integral \eqref{eq:lewis_price_call}. To this
end, we  use the discretization approach detailed above.
Note that such approximation procedure is not always necessary. In
fact, as we will see later in Section \ref{subsec:Riccati-equations-for-Markov-vol},
if we consider the Stein-Stein volatility model i.e. $G_{\nu}(t,s)=1_{s<t}$,
the analytic expression of the characteristic function is more explicit
as shown by Corollary \ref{corr:chf_stein-stein}.\\


The closed form approximate solution of the characteristic function \eqref{eq:approx_fractional_kernel_op_disc} has been proposed in different
papers \cite{key-4,key-5}. However, it is important to note that
theoretically, a general convergence result when $N$ tends to infinity
has not yet been demonstrated. We nevertheless
verify empirically the convergence of this approximation method as
$N\to\infty$. For this purpose, we restrict ourselves to a one-factor
Hull and White model for the interest rate i.e. $G_{r}(t,s)=1_{s<t}$
and we consider the fractional kernel for the volatility $G_{\nu}(t,s)=1_{s<t}\frac{(t-s)^{H_{\nu}-1/2}}{\Gamma(H_{\nu}+1/2)}$.
Without loss of generality, we fix arbitrarily the model parameters
to 
\begin{align*}
 & \kappa_{r}=-0.03,\:\eta_{r}=0.01,\:I_{0}^{T}=100,\:\nu_{0}=0.1,\:\kappa_{\nu}=0,\:\theta_{\nu}=0.1,\:\sigma_{\nu}=0.125,\\
 & \rho_{I\nu}=-0.7,\:\rho_{Ir}=-0.25,\:\rho_{\nu r}=-0.25.
\end{align*}
Figure \ref{fig:Implied-volatility-dynamics_op_discr} presents the
implied volatility dynamics generated by the operator discretization
$H_{\nu}=0.5$ as well as $H_{\nu}=0.3$. As expected, we observe
a relative fast convergence as the number of discretization factors
$N$ increases. 

