\section{\protect\label{sec:Link-with-conventional_models}Link with conventional
quadratic linear models}

\subsection{Link with operator Riccati equations}

In this section, we provide the link between the analytic expression
of the characteristic function \eqref{eq:chf_explicit} and expression
that depends on Riccati equations. 
\begin{prop}
\label{prop:-chf_riccati_1}Let $g_{0}(.)$ be given by \eqref{eq:g_0_t},
$G_{\nu}(.)$ a Volterra kernel as in Definition \ref{def:L2_kernel-1}. 
Fix $u\in\mathbb{C}$ such that $0\leq\mathcal{\mathfrak{R}}(u)\leq1.$
Then, for all $t\leq T$,
\begin{equation}
E^{\mathbb{Q}^{T}}\bigg[\exp\bigg(u\log\frac{I_{T}^{T}}{I_{t}^{T}}\bigg)\bigg|\mathcal{F}_{t}\bigg]=\exp\left(\phi_{t}^{u}+\chi_{t}^{u}+a^{u}\int_{t}^{T}h_{t}^{u}(s)^{2}ds+\int_{t}^{T}\int_{t}^{T}h_{t}^{u}(s)h_{t}^{u}(w)\:\bar{\psi}_{t}^{u}(s,w)dsdw\right),\label{eq:chf_explicit-1}
\end{equation}
 with $\chi_{t}^{u}$ as in Theorem \ref{thm:chf_general}, $\phi_{t}^{u}$
such that
\begin{align}
\dot{\phi}_{t}^{u} & =-a^{u}\eta_{\nu}^{2}\int_{t}^{T}G_{\nu}(s,t)^{2}ds-\eta_{\nu}^{2}\int_{t}^{T}\int_{t}^{T}G_{\nu}(s,t)G_{\nu}(w,t)\:\bar{\psi}_{t}^{u}(s,w)\,ds\,dw,\:t<T,\nonumber \\
\phi_{T}^{u} & =0,\label{eq:phi_t_ODE}
\end{align}
and $\bar{\psi}_{t}^{u}(s,w)$ that satisfies  a Riccati equation
of the form 
\begin{align*}
\dot{\bar{\psi}}_{t}^{u}(s,w)= & 2(a^{u})^{2}\eta_{\nu}^{2}\,G_{\nu}(s,t)G_{\nu}(w,t)+2a^{u}\eta_{\nu}^{2}\bigg(G_{\nu}(s,t)\,(\mathbf{G}_{\nu}^{*}\bar{\psi}_{t}^{u}(.,w))(t)+G_{\nu}(w,t)\,(\mathbf{G}_{\nu}^{*}\bar{\psi}_{t}^{u}(s,.))(t)\bigg)\\
 & +2\eta_{\nu}^{2}\,(\mathbf{G}_{\nu}^{*}\bar{\psi}_{t}^{u}(s,.))(t)\:(\mathbf{G}_{\nu}^{*}\bar{\psi}_{t}^{u}(.,w))(t),\:t<T,\:(s,w)\in(t,T]^{2}\:a.e.,\\
\bar{\psi}_{t}(t,s)= & \bar{\psi}_{t}(s,t)=b^{u}\bigg(a^{u}G_{\nu}(s,t)+(\mathbf{G}_{\nu}^{*}\bar{\psi}_{t}^{u}(s,.))(t)\bigg),\:t\leq s\leq T.
\end{align*}
\end{prop}
\begin{proof}
From Lemma \ref{lem:integral_operator}, we have that $\mathbf{\Psi}_{t}^{u}=a^{u}\text{id}+\bar{\mathbf{\Psi}}_{t}^{u}$,
where $\bar{\mathbf{\Psi}}_{t}^{u}$ is an integral operator induced
by a symmetric kernel $\bar{\psi}_{t}^{u}(s,w)$ such that 
\begin{align*}
\bar{\psi}_{t}^{u}(t,s)=\bar{\psi}_{t}^{u}(s,t) & =b^{u}\int_{t}^{T}G_{\nu}(w,t)(a^{u}\delta_{w=s}+\bar{\psi}_{t}^{u}(s,w))dw,\:t\leq s\leq T\\
 & =b^{u}\bigg(a^{u}G_{\nu}(s,t)+(\mathbf{G}_{\nu}^{*}\bar{\psi}_{t}^{u}(s,.))(t)\bigg),\:t\leq s\leq T.
\end{align*}
In this case, we have that 
\[
\langle h_{t}^{u},\mathbf{\Psi}_{t}^{u}h_{t}^{u}\rangle_{L^{2}}=a^{u}\int_{t}^{T}h_{t}^{u}(s)^{2}\:ds+\int_{t}^{T}\int_{t}^{T}h_{t}^{u}(s)h_{t}^{u}(w)\:\bar{\psi}_{t}^{u}(s,w)\:dsdw.
\]
Moreover, we also know from Lemma B.1. in \cite{key-4} that 
\begin{align*}
\dot{\mathbf{\Psi}}_{t}^{u} & =2\mathbf{\Psi}_{t}^{u}\dot{\mathbf{\Sigma}}_{t}\mathbf{\Psi}_{t}^{u},\:t<T,\\
\mathbf{\Psi}_{T}^{u} & =a^{u}(\text{id}-b^{u}\mathbf{G}_{\nu}^{*})^{-1}(\text{id}-b^{u}\mathbf{G}_{\nu})^{-1},
\end{align*}
and by the definition, we also have that 
\begin{align*}
\dot{\bar{\mathbf{\Psi}}}_{t}^{u} & =2\mathbf{\Psi}_{t}^{u}\dot{\mathbf{\Sigma}}_{t}\mathbf{\Psi}_{t}^{u},\:t<T,\\
 & =2(a^{u}\text{id}+\bar{\mathbf{\Psi}}_{t}^{u})\dot{\mathbf{\Sigma}}_{t}(a^{u}\text{id}+\bar{\mathbf{\Psi}}_{t}^{u}),\:t<T,\\
\bar{\mathbf{\Psi}}_{T}^{u} & =a^{u}(\text{id}-b^{u}\mathbf{G}_{\nu}^{*})^{-1}(\text{id}-b^{u}\mathbf{G}_{\nu})^{-1}-a^{u}\text{id},
\end{align*}
As $\dot{\bar{\mathbf{\Psi}}}_{t}^{u}$ is composed of integral operators,
it is also an integral operator induced by the following kernel 
\[
2((a^{u}\delta+\bar{\mathbf{\Psi}}_{t}^{u})\star\dot{\mathbf{\Sigma}}_{t}\star(a^{u}\delta+\bar{\mathbf{\Psi}}_{t}^{u}))(s,w),
\]
with $\delta$ the kernel induced by the identity operator such that
$(\text{id}f)(s)=\int_{t}^{T}\delta_{s=w}(ds,dw)f(w)=f(s).$ Thus, using
the dominated convergence theorem, we obtain that $t\to\bar{\psi}_{t}^{u}(s,w)$
solves a Riccati equation given, for $t<s$ and $w\leq T,$ by
\[
\dot{\bar{\psi}}_{t}^{u}(s,w)=2((a^{u}\,\delta+\bar{\mathbf{\Psi}}_{t}^{u})\star\dot{\mathbf{\Sigma}}_{t}\star(a^{u}\,\delta+\bar{\mathbf{\Psi}}_{t}^{u}))(s,w).
\]
More explicitly, since $G(z,t)=0$ for $z\leq t,$ we also have, for
$(s,w)\in(t,T]^{2}\:a.e.$, 
\begin{align*}
\dot{\bar{\psi}}_{t}^{u}(s,w)= & 2(a^{u})^{2}\eta_{\nu}^{2}\,G_{\nu}(s,t)G_{\nu}(w,t)+2a^{u}\eta_{\nu}^{2}\,G_{\nu}(s,t)\int_{t}^{T}G_{\nu}(z,t)\,\bar{\psi}_{t}^{u}(z,w)\,dz\\
 & +2a^{u}\eta_{\nu}^{2}\,G_{\nu}(w,t)\int_{t}^{T}G_{\nu}(z,t)\,\bar{\psi}_{t}^{u}(s,z)\,dz\\
 & +2\eta_{\nu}^{2}\,\int_{t}^{T}G_{\nu}(z,t)\,\bar{\psi}_{t}^{u}(s,z)\,dz\int_{t}^{T}G_{\nu}(z^{'},t)\,\bar{\psi}_{t}^{u}(z^{'},w)\,dz^{'},\:t<T.
\end{align*}
Thus, using the integral operator $\mathbf{G}_{\nu}^{*},$ we obtain
that, for $(s,w)\in(t,T]^{2}\:a.e.$, 
\begin{align*}
\dot{\bar{\psi}}_{t}^{u}(s,w)= & 2(a^{u})^{2}\eta_{\nu}^{2}\,G_{\nu}(s,t)G_{\nu}(w,t)+2a^{u}\eta_{\nu}^{2}\bigg(G_{\nu}(s,t)\,(\mathbf{G}_{\nu}^{*}\bar{\psi}_{t}^{u}(.,w))(t)+G_{\nu}(w,t)\,(\mathbf{G}_{\nu}^{*}\bar{\psi}_{t}^{u}(s,.))(t)\bigg)\\
 & +2\eta_{\nu}^{2}\,(\mathbf{G}_{\nu}^{*}\bar{\psi}_{t}^{u}(s,.))(t)\:(\mathbf{G}_{\nu}^{*}\bar{\psi}_{t}^{u}(.,w))(t),\:t<T.
\end{align*}
In addition, from Theorem \ref{thm:chf_general}, we know that $t\to\phi_{t}^{u}$
satisfies the following ODE 
\begin{align*}
\dot{\phi}_{t}^{u} & =\text{Tr}(\mathbf{\Psi}_{t}^{u}\dot{\mathbf{\Sigma}_{t}}),\:t<T\\
 & =\text{Tr}((a^{u}\text{id}+\bar{\mathbf{\Psi}}_{t}^{u})\dot{\mathbf{\Sigma}_{t}}),\:t<T\\
 & =a^{u}\text{Tr}(\dot{\mathbf{\Sigma}_{t}})+\text{Tr}(\bar{\mathbf{\Psi}}_{t}^{u}\dot{\mathbf{\Sigma}_{t}}),\:t<T\\
 & =-a^{u}\eta_{\nu}^{2}\int_{t}^{T}G_{\nu}(s,t)^{2}ds-\eta_{\nu}^{2}\int_{t}^{T}\int_{t}^{T}G_{\nu}(s,t)G_{\nu}(w,t)\:\bar{\psi}_{t}^{u}(s,w)\,ds\,dw,\:t<T,
\end{align*}
with $\phi_{T}^{u}=0.$ 
\end{proof}
We go now a step further and deduce more explicit Riccati equations by
considering completely monotone Volterra kernels. 
\begin{defn}
A kernel $G:[0,T]^{2}\to\mathbb{R}$ is a completely monotone Volterra
kernel if it satisfies Definition \ref{def:L2_kernel-1} and admits
a Laplace representation of the form 
\begin{equation}
G(t,s)=1_{s<t}\int_{\mathbb{R}^{+}}e^{-(t-s)x}\lambda(dx),\label{eq:completely_monotone_kernel}
\end{equation}
where $\lambda(.)$ is a positive measure. 
\end{defn}
\begin{prop}
\label{prop:riccati_ODE_last}Assume that the kernel function $G_{\nu}(t,s)$
is completely monotone and can be represented as \eqref{eq:completely_monotone_kernel}.
Moreover, assume that $g_{0}(.)$ is given by \eqref{eq:g_0_t} and that the kernel satisfies Definition \ref{def:L2_kernel-1}. Fix
$u\in\mathbb{C}$ such that $0\leq\mathcal{\mathfrak{R}}(u)\leq1.$
Then, for all $t\leq T$,
\begin{equation}
E^{\mathbb{Q}^{T}}\bigg[\exp\bigg(u\log\frac{I_{T}^{T}}{I_{t}^{T}}\bigg)\bigg|\mathcal{F}_{t}\bigg]=\exp\bigg(\Theta_{t}^{u}+2\int_{\mathbb{R}_{+}}\Lambda_{t}^{u}(x)Y_{t}(x)\:\lambda(dx)+\int_{\mathbb{R}_{+}^{2}}\Gamma_{t}^{u}(x,y)Y_{t}(x)Y_{t}(y)\:\lambda(dx)\:\lambda(dy)\bigg),\label{eq:chf_explicit-1-1-1}
\end{equation}
where $t\to(\Theta_{t}^{u},\Lambda_{t}^{u},\Gamma_{t}^{u})$ solve
Riccati equations of the form 
\begin{align}
\dot{\Theta}_{t}^{u}= & \dot{\chi}_{t}^{u}-a^{u}\bigg(g_{0}^{T}(t)+\rho_{Ir}\eta_{r}B_{G_{r}}(t,T)\bigg)^{2}-\eta_{\nu}^{2}\bigg(2\bigg(\int_{\mathbb{R}_{+}}\Lambda_{t}^{u}(x)\:\lambda(dx))\bigg)^{2}+\int_{\mathbb{R}_{+}}\int_{\mathbb{R}_{+}}\Gamma_{t}^{u}(x,y)\:\lambda(dx)\:\lambda(dy)\bigg)\nonumber \\
 & -2\int_{\mathbb{R}_{+}}\bigg(b^{u}g_{0}^{T}(t)+u\eta_{\nu}\rho_{\nu r}\eta_{r}B_{G_{r}}(t,T)\bigg)\:\Lambda_{t}^{u}(x^{'})\:\lambda(dx'),\:t<T,\label{eq:theta_t}
\end{align}
\begin{align}
\dot{\Lambda}_{t}^{u}(x)= & -a^{u}\bigg(g_{0}^{T}(t)+\rho_{Ir}\eta_{r}B_{G_{r}}(t,T)\bigg)+x\Lambda_{t}^{u}(x)-2\eta_{\nu}^{2}\bigg(\int_{\mathbb{R}_{+}}\Gamma_{t}^{u}(x,x')\:\lambda(dx')\bigg)\bigg(\int_{\mathbb{R}_{+}}\Lambda_{t}^{u}(y)\:\lambda(dy)\bigg)\nonumber \\
 & -\int_{\mathbb{R}_{+}}\bigg(b^{u}g_{0}^{T}(t)+u\eta_{\nu}\rho_{\nu r}\eta_{r}B_{G_{r}}(t,T)\,\bigg)\Gamma_{t}^{u}(x,x^{'})\:\lambda(dx')\nonumber \\
 & -b^{u}\int_{\mathbb{R}_{+}}\Lambda_{t}^{u}(x^{'})\:\lambda(dx'),\:t<T,\:x\in\mathbb{R}_{+},\label{eq:lambda_t}
\end{align}
 and 
\begin{align}
\dot{\Gamma}_{t}^{u}(x,y)= & (x+y)\Gamma_{t}^{u}(x,y)-a^{u}-2\,\eta_{\nu}^{2}\bigg(\int_{\mathbb{R}_{+}}\Gamma_{t}^{u}(x,x')\:\lambda(dx')\bigg)\bigg(\int_{\mathbb{R}_{+}}\Gamma_{t}^{u}(y,y')\:\lambda(dy')\bigg)\nonumber \\
 & -b^{u}\bigg(\int_{\mathbb{R}_{+}}\Gamma_{t}^{u}(x,x^{'})\:\lambda(dx')+\int_{\mathbb{R}_{+}}\Gamma_{t}^{u}(y^{'},y)\:\lambda(dy')\bigg),\:t<T,\:(x,y)\in\mathbb{R}_{+}^{2},\label{eq:gamma_t}
\end{align}
with $\Theta_{T}^{u}=\Lambda_{T}^{u}=\Gamma_{T}^{u}=0.$
\end{prop}
\begin{proof}
The proof is given in Section \ref{sec:Proofs}.
\end{proof}
\begin{rem}
A general result about the existence and the uniqueness of solutions
to Riccati equations \eqref{eq:theta_t}-\eqref{eq:lambda_t}-\eqref{eq:gamma_t}
is provided in \cite{key-3}. \QEDA
\end{rem}

\subsection{\protect\label{subsec:Riccati-equations-for-Markov-vol}Riccati equations
for Markovian volatility models }

In this section, we consider some particular completely monotone kernels
associated to Markovian volatility models. For those models, we derive
a simplified version of the characteristic function based on Riccati
equations. In particular, for the indicator $G_{\nu}(t,s)=1_{s<t}$
and exponential $G_{\nu}(t,s)=1_{s<t}\alpha\exp(-\beta(t-s))$ kernels,
we obtain closed form expressions similar to the characteristic functions
deduced in \cite{key-25}. 
\begin{prop}
\label{prop:chf_multi_factors_ODE}Suppose that $G_{\nu}(t,s)=1_{s<t}\sum_{i=1}^{N}w_{i}e^{-x_{i}(t-s)}$
and $g_{0}(t)=\nu_{0}+\theta_{\nu}\sum_{i=1}^{N}\int_{0}^{t}w_{i}\exp(-x_{i}(t-s))ds$
with $\nu_{0}>0$ and $\theta_{\nu}\in\mathbb{R}$, then, for $u\in\mathbb{C}$
such that $0\leq\mathcal{\mathfrak{R}}(u)\leq1,$
\begin{equation}
E^{\mathbb{Q}^{T}}\bigg[\exp\bigg(u\log\frac{I_{T}^{T}}{I_{t}^{T}}\bigg)\bigg|\mathcal{F}_{t}\bigg]=\exp\left(A_{t}^{u;\,N}+2\sum_{i=1}^{N}B_{t}^{u;\,i}\:\nu_{t}^{i}+\sum_{i=1}^{N}\sum_{j=1}^{N}C_{t}^{u;\,ij}\:\nu_{t}^{i}\nu_{t}^{j}\right),\label{eq:chf_markov_vol_n_factors}
\end{equation}
 with $\left((\nu_{t}^{i})_{i=1,...,N}\right)_{0\leq t\leq T}$ solution
of the following SDEs 
\begin{align*}
d\nu_{t}^{i} & =(-x_{i}\nu_{t}^{i}+\theta(t)+\kappa_{\nu}\:\nu_{t})\:dt+\eta_{\nu}\:dW_{\nu}^{\mathbb{Q}^{T}}(t),\:t>0,\:i=1,...,N,\\
\nu_{0}^{i} & =0,
\end{align*}
on $(\Omega,\mathcal{F},(\mathcal{F}_{t})_{t\leq T},\mathbb{Q}^{T})$
with $\theta(t):=\theta_{\nu}-\eta_{\nu}\sum_{i=1}^{n}\eta_{i}\rho_{i\nu}B_{i}(t,T)$,
such that, almost surely, 
\[
\nu_{t}=\nu_{0}+\sum_{i=1}^{N}w_{i}\nu_{t}^{i},\:t\leq T,
\]
and $A_{t}^{u;\,N}$, $(B_{t}^{u;\,i})_{i=1,...,N}$ and $(C_{t}^{u;\,ij})_{i,j=1,...,N}$
time-dependent functions satisfying Riccati equations of the form
\begin{align}
\dot{A}_{t}^{u;\,N} & =-a^{u}\bigg(\nu_{0}^{2}+\eta_{r}^{2}B_{G_{r}}(t,T)^{2}-2\nu_{0}\rho_{Ir}\eta_{r}B_{G_{r}}(t,T)\bigg)\nonumber \\
 & -2\sum_{i=1}^{N}B_{t}^{u;\,i}\bigg(\theta(t)+u\eta_{\nu}\rho_{\nu r}\eta_{r}B_{G_{r}}(t,T)+b^{u}\nu_{0}\bigg)-\eta_{\nu}^{2}\sum_{i,j=1}^{N}(2B_{t}^{u;\,i}B_{t}^{u;\,j}+C_{t}^{u;\,ij}),\:t<T.\label{eq:A_n_ODE}
\end{align}

\begin{align}
\dot{B}_{t}^{u;\,i}= & x_{i}B_{t}^{u;\,i}-a^{u}w_{i}\bigg(\nu_{0}+\rho_{Ir}\eta_{r}B_{G_{r}}(t,T)\bigg)-2\eta_{\nu}^{2}\sum_{j,k=1}^{N}C_{t}^{u;\,ij}B_{t}^{u;\,k}\nonumber \\
 & -w_{i}b^{u}\sum_{j=1}^{N}B_{t}^{u;\,j}-\sum_{j=1}^{N}C_{t}^{u;\,ij}\bigg(\theta(t)+u\eta_{\nu}\rho_{\nu r}\eta_{r}B_{G_{r}}(t,T)+b^{u}\nu_{0}\bigg),\:t<T,\:i=1,...,N,\label{eq:B_n_ODE}
\end{align}

\begin{equation}
\dot{C}_{t}^{u;\,ij}=(x_{i}+x_{j})C_{t}^{u;\,ij}-w_{i}w_{j}a^{u}-2\eta_{\nu}^{2}\sum_{k=1}^{N}\sum_{l=1}^{N}C_{t}^{u;\,ik}C_{t}^{u;\,jl}-b^{u}\sum_{k=1}^{N}\bigg(w_{j}C_{t}^{u;\,ik}+w_{i}C_{t}^{u;\,kj}\bigg)\label{eq:C_n_ODE}
\end{equation}
with $A_{T}^{u;\,N}=B_{T}^{u;\,i}=C_{T}^{u;\,ij}=0,$ for $i,j=1,...,N.$
\end{prop}
\begin{proof}
The proof is given in Section \ref{sec:Proofs}. 
\end{proof}
\begin{cor}
\label{corr:chf_stein-stein}Suppose that $G_{\nu}(t,s)=1_{s<t}\:\alpha\exp(-\beta(t-s))$
and $g_{0}(t)=\nu_{0}+\theta_{\nu}\int_{0}^{t}\alpha\exp(-\beta(t-s))ds,$
with $\nu_{0}>0$, $\alpha,\beta\in\mathbb{R}_{+}$ and $\theta_{\nu}\in\mathbb{R}$.
Then, for $u\in\mathbb{C}$ such that $0\leq\mathcal{\mathfrak{R}}(u)\leq1,$
\begin{equation}
E^{\mathbb{Q}^{T}}\bigg[\exp\bigg(u\log\frac{I_{T}^{T}}{I_{t}^{T}}\bigg)\bigg|\mathcal{F}_{t}\bigg]=\exp(A_{t}^{u}+2B_{t}^{u}\:\nu_{t}+C_{t}^{u}\:\nu_{t}^{2}),\label{eq:chf_markov_vol}
\end{equation}
 with $A_{t}^{u}$, $B_{t}^{u}$ and $C_{t}^{u}$ time-dependent functions
given by 
\begin{align}
A_{t}^{u} & =-\frac{1}{2}u(1-u)V_{r}(t,T)+\int_{t}^{T}\bigg[\bigg(\alpha\theta_{\nu}+(u-1)\rho_{\nu r}\alpha\eta_{\nu}\eta_{r}B_{G_{r}}(t,T)\bigg)B_{s}^{u}\nonumber \\
 & \;\;\;\;\;\;\;\;\;\;\;\;\;\;\;\;\;\;+\frac{1}{2}\eta_{\nu}^{2}\bigg((B_{s}^{u})^{2}+C_{s}^{u}\bigg)\bigg]\:ds,\label{eq:A_stein}
\end{align}
\begin{align}
B_{t}^{u} & =-\frac{1}{2}\frac{u(1-u)}{\gamma_{1}+\gamma_{2}e^{-2\gamma(T-t)}}\bigg[\gamma_{0}(1+e^{-2\gamma(T-t)})\nonumber \\
 & \;\;\;\;\;+(\gamma_{3}-\gamma_{4}e^{-2\gamma(T-t)}-(\gamma_{5}e^{-\kappa_{r}(T-t)}-\gamma_{6}e^{-(2\gamma+\kappa_{r})(T-t)})-\gamma_{7}e^{-\gamma(T-t)}\bigg],\label{eq:B_stein}
\end{align}

\begin{equation}
C_{t}^{u}=-\frac{1}{2}u(1-u)\frac{1-e^{-2\gamma(T-t)}}{\gamma_{1}+\gamma_{2}e^{-2\gamma(T-t)}},\label{eq:C_stein}
\end{equation}
where $V_{r}(t,T)$ is the integrated variance of the interest rate
process \eqref{eq:IR_HW_multi_factor} and 
\begin{align*}
\gamma & =\sqrt{(-(\alpha\kappa_{\nu}-\beta)-\rho_{I\nu}\alpha\eta_{\nu}u)^{2}-\alpha^{2}\eta_{\nu}^{2}(u^{2}-u)},\:\:\:\:\:\:\gamma_{0}=\frac{\alpha\theta_{\nu}}{\gamma},\\
\gamma_{1} & =\gamma-(\alpha\kappa_{\nu}-\beta+\rho_{I\nu}\alpha\eta_{\nu}u),\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\gamma_{2}=\gamma((\alpha\kappa_{\nu}-\beta+\rho_{I\nu}\alpha\eta_{\nu}u),\\
\gamma_{3} & =\frac{\rho_{Ii}\eta_{r}\gamma_{1}+\rho_{\nu i}\eta_{r}\alpha\eta_{\nu}(u-1)}{\kappa_{r}\gamma},\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\gamma_{4}=\frac{\rho_{Ir}\eta_{r}\gamma_{2}-\rho_{\nu r}\eta_{r}\alpha\eta_{\nu}(u-1)}{\kappa_{r}\gamma},\\
\gamma_{5} & =\frac{\rho_{Ir}\eta_{r}\gamma_{1}+\rho_{\nu r}\eta_{r}\alpha\eta_{\nu}(u-1)}{\kappa_{r}(\gamma-\kappa_{r})},\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\:\gamma_{6}=\frac{\rho_{Ir}\eta_{r}\gamma_{2}-\rho_{\nu r}\eta_{r}\alpha\eta_{\nu}(u-1)}{\kappa_{r}(\gamma+\kappa_{r})},\\
\gamma_{7} & =(\gamma_{3}-\gamma_{4})-(\gamma_{5}-\gamma_{6}).
\end{align*}
\end{cor}
\begin{proof}
Based on Proposition \ref{prop:chf_multi_factors_ODE} with $N=1$,
$w_{1}=1$ and $x_{1}=\alpha$, we deduce the Riccati equations satisfied
by $A_{t}^{u},$$B_{t}^{u},$ $C_{t}^{u}$. Thus, using a laborious
development as in \cite{key-25,key-26}, we can obtain the explicit
forms given by \eqref{eq:A_stein}-\eqref{eq:B_stein}-\eqref{eq:C_stein}.
\end{proof}

\subsection{\protect\label{subsec:Multi-factor-approximation}Multi-factor approximation
for completely monotone Volterra kernels}

In this section, we propose another alternative to approximate
the characteristic function when considering completely monotone Volterra
kernels in the sense of Definition \ref{def:L2_kernel-1}. The approximate
method is based on a Laplace representation of completely monotone
kernels and expression of the characteristic function in terms of
Riccati equations. Unlike the approach proposed in Section \ref{subsec:numerical_implementation_general_kernels},
a convergence result is deduced for this multi-factor approximate
approach. Using a Laplace transform representation, we have that completely
monotone kernels can be rewritten such that 
\begin{equation}
G_{\nu}(t,s)=1_{s<t}\int_{\mathbb{R}^{+}}e^{-(t-s)x}\lambda(dx),\label{eq:completely_monotone_kernel-1}
\end{equation}
with $\lambda(.)$ a positive measure. Hence a natural approximation
of the kernel is given by 
\begin{equation}
\hat{G}_{\nu}(t,s):=1_{s<t}\sum_{i=1}^{N}\hat{w}_{i}e^{-(t-s)\hat{x}_{i}},\label{eq:approx_kernel}
\end{equation}
where $(\hat{w}_{i})_{i=1,...,N}$ are the weights and $(\hat{x}_{i})_{i=1,...,N}$
the mean reversion terms that should be appropriately defined. Under
suitable choice, $\hat{G}_{\nu}$ converges in $L^{2}([0,T]^{2},\mathbb{R})$
to the completely monotone kernels. Therefore, based on Proposition
\ref{prop:chf_multi_factors_ODE}, we can propose another approximate
solution of the characteristic function associated to completely monotone
Volterra kernels. 
\begin{lem}
\label{lem:conve_kernel}Suppose that for all $N\geq1$, $(\hat{w}_{i})_{i=1,...,N}$
and $(\hat{x}_{i})_{i=1,...,N}$ are such that 
\[
\hat{w}_{i}:=\int_{k_{i-1}}^{k_{i}}\lambda(dk),\:\hat{x}_{i}:=\frac{1}{\hat{w}_{i}}\int_{k_{i-1}}^{k_{i}}k\;\lambda(dk),
\]
such that $k_{0}=0<k_{1}<...<k_{n}$ and 
\[
k_{n}\to\infty,\:\sum_{i=1}^{N}\int_{k_{i-1}}^{k_{i}}(k_{i}-k)^{2}\;\lambda(dk)\to0.
\]
\emph{as $N$ goes to infinity.} For $N\geq1$ fixed, there exists
a function $f_{N}^{(2)}((k_{i})_{i=0,...,N})$ such that the following
inequality holds
\begin{equation}
||\hat{G}_{\nu}-G_{\nu}||_{L^{2}([0,T]^{2},\mathbb{R})}\leq f_{N}^{(2)}((k_{i})_{i=1,...,N}),\label{eq:upper_bound_L2}
\end{equation}
and $\hat{G}_{\nu}$ converges in $L^{2}([0,T]^{2},\mathbb{R})$ to
$G_{\nu}$ when $N$ goes to infinity i.e. 
\[
||\hat{G}_{\nu}-G_{\nu}||_{L^{2}([0,T]^{2},\mathbb{R})}\to0,
\]
as $N$ goes to infinity. 
\end{lem}
\begin{proof}
We refer to the proof of \cite[Proposition 3.3.]{key-1}. 
\end{proof}
\begin{rem}
As stated in \cite{key-1}, there are different possible choices
of the auxiliary terms $(k_{i})_{i=0,...,N}$. In this paper, for fixed
$N\geq1,$ we take auxiliary terms $(k_{i})_{i=0,...,N}$ that minimize
the upper bound \eqref{eq:upper_bound_L2}. Thus, we choose $(k_{i})_{i=1,...,N}$
solutions of
\[
\inf_{(k_{i})_{i=1,..,N}\in\mathcal{E}_{N}}f_{N}^{(2)}((k_{i})_{i=1,...,N}),
\]
with $\mathcal{E}_{N}:=\{(k_{i})_{i=1,..,N}:\;k_{0}=0<k_{1}<...<k_{n}\}.$ 
\end{rem}
\begin{prop}
\label{prop:second_approx_fractional_kernel}Let $(I_{t}^{T})_{0\leq t\leq T}$
be the solution of \eqref{eq:dyn_forward_inflation} with the completely
monotone kernel \eqref{eq:completely_monotone_kernel-1} and $(\tilde{I}_{t}^{T})_{0\leq t\leq T}$
solution of \eqref{eq:dyn_forward_inflation} with the approximate
kernel \eqref{eq:approx_kernel}. Suppose that the assumptions of
Lemma \ref{lem:conve_kernel} are satisfied and that, for $u\in\mathbb{C}$
such that $0\leq\mathcal{\mathfrak{R}}(u)\leq1,$ the sequence $(\exp(u\log\tilde{I}_{T}^{T}))_{N\in\mathbb{N}}$
is uniformly integrable, then
\[
\lim_{N\to\infty}\exp(A_{0}^{u;\,N})=E^{\mathbb{Q}^{T}}\bigg[\exp\bigg(u\log\frac{I_{T}^{T}}{I_{0}^{T}}\bigg)\bigg|\mathcal{F}_{0}\bigg],
\]
where $A_{0}^{u;\,N}$ is the solution of Riccati equation \eqref{eq:A_n_ODE}
with $w_{i}=\hat{w}_{i}$ and $x_{i}=\hat{x}_{i}$, for $i=1,...,N.$ 
\end{prop}
\begin{proof}
Using arguments similar to those of \cite{key-20}, we can show that,
for $t\in[0,T],$
\[
\tilde{I}_{t}^{T}\xrightarrow{\mathcal{L}}I_{t}^{T},
\]
as $N$ goes to infinity, where $\xrightarrow{\mathcal{L}}$ stands
for weak convergence. Therefore, using the uniform integrability of
$\exp(u\log\tilde{I}_{T}^{T})$ and the fact that $I_{0}^{T}=\tilde{I}_{0}^{T},$
we obtain that 
\[
\lim_{N\to\infty}E^{\mathbb{Q}^{T}}\bigg[\exp\bigg(u\log\frac{\tilde{I}_{T}^{T}}{\tilde{I}_{0}^{T}}\bigg)\bigg|\mathcal{F}_{0}\bigg]=E^{\mathbb{Q}^{T}}\bigg[\exp\bigg(u\log\frac{I_{T}^{T}}{I_{0}^{T}}\bigg)\bigg|\mathcal{F}_{0}\bigg],
\]
and thus, we conclude the proof using Corollary \ref{prop:chf_multi_factors_ODE}
and the fact that $\nu_{0}^{i}=0$ for $i=1,...,N.$
\end{proof}
Based on Proposition \ref{prop:second_approx_fractional_kernel},
we can deduce a second approximate solution of the characteristic
function for which a theoretical convergence result is established.
However, it is a semi-closed solution in the sense that it requires
solving Riccati equations. \\
\\
Finally, we decide to compare this ``multi-factor'' approximate
method with the ``operator discretization'' method proposed
in Section \ref{subsec:numerical_implementation_general_kernels}.
For this purpose, we consider the same kernels and model parameters
as in Section \ref{subsec:numerical_implementation_general_kernels}.
Figure \ref{fig:Implied-volatility-dynamics_H_03_multi_factors} presents
the implied volatility generated for different $N$ by the multi-factor
method where the system of Riccati $(N^{2}+N+1)$ equations \eqref{eq:A_n_ODE}-\eqref{eq:B_n_ODE}-\eqref{eq:C_n_ODE}
is solved numerically using an implicit method. We observe a convergence
as the number of factors increases. However,
the speed of convergence differs between the methods. As revealed by Figure
\ref{fig:Implied-volatility-ATM_H_01_}, the operator discretization
approach converges much faster than the multi-factor approach, either
with respect to $N$ or in terms of computation time. Nevertheless, it
should be noted that the speed of convergence of the ``multi-factor''
method depends strongly on the choice of multi-factor parameters $(\hat{w}_{i},\hat{x}_{i})_{i=1,...,N}$
, as well as the numerical method used to solve the system of Riccati $(N^{2}+N+1)$ equations and other choices than those used in this paper could
give a faster speed of convergence. The aim of this comparison is
above all to illustrate that the ``operator discretization'' method
converges quickly and is fairly simple to implement compared with
the ``multi-factor'' method. 

