\section{Proofs\protect\label{sec:Proofs}}

\subsection{Proof of Theorem \ref{thm:chf_general}}

We first consider two useful lemmas before proving Theorem \ref{thm:chf_general}. 
\begin{lem}
\label{lem:integral_operator}For $u\in\mathbb{C}$ such that $0\leq\mathcal{\mathfrak{R}}(u)\leq1,$
there exists an integral operator $\bar{\mathbf{\Psi}}_{t}^{u}$ induced
by a symmetric kernel $\bar{\psi}_{t}^{u}(s,w)$ such that 
\begin{equation}
\mathbf{\Psi}_{t}^{u}=a^{u}\text{id}+\bar{\mathbf{\Psi}}_{t}^{u},\label{eq:operator_wrt_integral_op}
\end{equation}
and for any $f\in L^{2}([0,T],\mathbb{C}),$
\begin{equation}
(\mathbf{\Psi}_{t}^{u}f1_{t})(t)=(a^{u}\text{id}+b^{u}\mathbf{G}_{\nu}^{*}\mathbf{\Psi}_{t}^{u})(f1_{t})(t),\label{eq:operator_f_t}
\end{equation}
with $1_{t}:s\to1_{t\leq s}.$ Moreover, the kernel $\bar{\psi}_{t}(s,w)$
satisfies 
\begin{equation}
\bar{\psi}_{t}^{u}(t,s)=\bar{\psi}_{t}^{u}(s,t)=b^{u}\int_{t}^{T}G_{\nu}(w,t)(a\delta_{w=s}+\bar{\psi}_{t}^{u}(s,w))dw,\:t\leq s\leq T,\:a.e.\label{eq:cond_psi_t}
\end{equation}
\end{lem}
\begin{proof}
From \cite[Lemma B.1.]{key-4}, we know that in our setting there
exists an integral operator $\bar{\mathbf{\Psi}}_{t}^{u}$ induced
by a symmetric kernel $\bar{\psi}_{t}(s,u)$ such that \eqref{eq:operator_wrt_integral_op}
and \eqref{eq:operator_f_t} are satisfied. Moreover, from \eqref{eq:operator_f_t},
since $\mathbf{G}_{\nu}^{*}$ is an integral operator and $\bar{\psi}_{t}^{u}(s,w)$
is symmetric, we deduce that, for any $f\in L^{2}([0,T],\mathbb{C})$,
\begin{align*}
(\bar{\mathbf{\Psi}}_{t}^{u}f1_{t})(t) & =(b^{u}\mathbf{G}_{\nu}^{*}\mathbf{\Psi}_{t}^{u})(f1_{t})(t)\\
 & =b^{u}\int_{t}^{T}G_{\nu}^{*}(t,s)\:(\mathbf{\Psi}_{t}^{u}f1_{t})(s)\:ds\\
 & =b^{u}\int_{t}^{T}G_{\nu}(s,t)\:\int_{t}^{T}(a^{u}\delta_{w=s}+\bar{\psi}_{t}^{u}(s,w))\:f(w)dw\:ds\\
 & =b^{u}\int_{t}^{T}f(s)\int_{t}^{T}G_{\nu}(w,t)(a^{u}\delta_{w=s}+\bar{\psi}_{t}^{u}(s,w))dw\:ds
\end{align*}
Moreover, since $\bar{\mathbf{\Psi}}_{t}$ is a symmetric integral
operator, we also have that 
\begin{align*}
(\bar{\mathbf{\Psi}}_{t}^{u}f1_{t})(t) & =\int_{t}^{T}\bar{\psi}_{t}^{u}(t,s)\:f(s)\:ds.\\
 & =\int_{t}^{T}\bar{\psi}_{t}^{u}(s,t)\:f(s)\:ds
\end{align*}
We conclude that, for any $f\in L^{2}([0,T],\mathbb{C})$, 
\begin{align*}
0 & =\int_{t}^{T}f(s)\bigg[\bar{\psi}_{t}^{u}(s,t)-b^{u}\int_{t}^{T}G_{\nu}(w,t)(a^{u}\delta_{w=s}+\bar{\psi}_{t}^{u}(s,w))dw\bigg]\:ds\\
 & =\int_{t}^{T}f(s)\bigg[\bar{\psi}_{t}^{u}(t,s)-b^{u}\int_{t}^{T}G_{\nu}(w,t)(a^{u}\delta_{w=s}+\bar{\psi}_{t}^{u}(s,w))dw\bigg]\:ds,
\end{align*}
and thus, for $t\leq s\leq T,$
\[
\bar{\psi}_{t}^{u}(t,s)=\bar{\psi}_{t}^{u}(s,t)=b^{u}\int_{t}^{T}G_{\nu}(w,t)(a^{u}\delta_{w=s}+\bar{\psi}_{t}^{u}(s,w))dw,
\]
almost everywhere. 
\end{proof}
\begin{lem}
\label{lem:h_Psi_t_dynamic}For $u\in\mathbb{C}$ such that $0\leq\mathcal{\mathfrak{R}}(u)\leq1$
and $t\in[0,T],$ let us define $h_{t}^{u}(.)$ such that 
\[
h_{t}^{u}(s):=g_{t}(s)+1_{t\leq s}\bigg(\rho_{Ir}\eta_{r}B_{G_{r}}(s,T)-\int_{t}^{s}G_{\nu}(s,w)\:(b^{u}\rho_{Ir}-u\eta_{\nu}\rho_{\nu r})\eta_{r}B_{G_{r}}(w,T)\:dw\bigg),\;s,t\leq T.
\]
Then the dynamics of $t\to\langle h_{t}^{u},\mathbf{\Psi}_{t}^{u}h_{t}^{u}\rangle_{L^{2}}$
is given by 
\begin{align}
d\langle h_{t}^{u},\mathbf{\Psi}_{t}^{u}h_{t}^{u}\rangle_{L^{2}}= & \bigg(-a^{u}\bigg(\nu_{t}+\rho_{Ir}\eta_{r}B_{G_{r}}(t,T)\bigg)^{2}\nonumber \\
 & -2u\eta_{\nu}(\rho_{I\nu}\nu_{t}+\rho_{\nu r}\eta_{r}B_{G_{r}}(t,T)(\mathbf{G}_{\nu}^{*}\mathbf{\Psi}_{t}^{u}h_{t})(t)\nonumber \\
 & -Tr(\mathbf{\Psi}_{t}^{u}\dot{\mathbf{\Sigma}}_{t})+\langle h_{t}^{u},\dot{\mathbf{\Psi}}_{t}^{u}h_{t}^{u}\rangle_{L^{2}}\bigg)\:dt\nonumber \\
 & +2\eta_{\nu}(\mathbf{G}_{\nu}^{*}\mathbf{\Psi}_{t}^{u}h_{t}^{u})(t)\:dW_{\nu}^{\mathbb{Q}^{T}}(t).\label{eq:dyn_quad_function}
\end{align}
\end{lem}
\begin{proof}
First, we set 
\begin{align*}
\bar{h}_{t}^{u}(s):= & g_{0}^{T}(s)+\int_{0}^{t}G_{\nu}(s,w)\kappa_{\nu}\:\nu_{w}dw+\int_{0}^{t}G_{\nu}(s,w)\:\eta_{\nu}\:dW_{I}^{\mathbb{Q}^{T}}(w)\\
+ & \bigg(\rho_{Ir}\eta_{r}B_{G_{r}}(s,T)-\int_{t}^{s}G_{\nu}(s,w)\:(b^{u}\rho_{Ir}-u\eta_{\nu}\rho_{\nu r})\eta_{r}B_{G_{r}}(w,T)\:dw\bigg)
\end{align*}
and using Lemma \ref{lem:integral_operator}, we have that 
\[
\langle h_{t}^{u},\mathbf{\Psi}_{t}^{u}h_{t}^{u}\rangle_{L^{2}}=\int_{t}^{T}(a^{u}\bar{h}_{t}^{u}(s)^{2}+\bar{h}_{t}^{u}(s)(\bar{\mathbf{\Psi}}_{t}^{u}h_{t}^{u})(s))\:ds.
\]
Using the Leibniz rule, we deduce that 
\begin{align*}
d\langle h_{t}^{u},\mathbf{\Psi}_{t}^{u}h_{t}^{u}\rangle_{L^{2}}= & -(a^{u}\bar{h}_{t}^{u}(t)^{2}+\bar{h}_{t}^{u}(t)(\bar{\mathbf{\Psi}}_{t}^{u}h_{t}^{u})(t))dt\\
 & +\int_{t}^{T}d(a^{u}\bar{h}_{t}^{u}(s)^{2}+\bar{h}_{t}^{u}(s)(\bar{\mathbf{\Psi}}_{t}^{u}h_{t}^{u})(s))\:ds.\\
= & -(a^{u}\bar{h}_{t}^{u}(t)^{2}+\bar{h}_{t}^{u}(t)(\bar{\mathbf{\Psi}}_{t}^{u}h_{t}^{u})(t))dt\\
 & +\int_{t}^{T}\bigg(a^{u}\,d(\bar{h}_{t}^{u}(s)^{2})+d\bar{h}_{t}^{u}(s)(\bar{\mathbf{\Psi}}_{t}^{u}h_{t}^{u})(s)+\bar{h}_{t}^{u}(s)d(\bar{\mathbf{\Psi}}_{t}^{u}h_{t}^{u})(s)\\
 & +d[\bar{h}_{t}^{u}(s),(\bar{\mathbf{\Psi}}_{t}^{u}h_{t}^{u})(s)]_{t}\bigg)\:ds.
\end{align*}
For fixed $s\in[t,T],$ let us now deduce the dynamics of $t\to d\bar{h}_{t}^{u}(s),$
$t\to d(\bar{h}_{t}^{u}(s)^{2})$ and $t\to d(\bar{h}_{t}^{u}(s)(\bar{\mathbf{\Psi}}_{t}^{u}h_{t}^{u})(s)).$
Since we have that 
\[
d\bar{h}_{t}^{u}(s)=G_{\nu}(s,t)\bigg(\kappa_{\nu}\nu_{t}+(b^{u}\rho_{Ir}-u\eta_{\nu}\rho_{\nu r})\eta_{r}B_{G_{r}}(t,T)\bigg)dt+G_{\nu}(s,t)\eta_{\nu}\:dW_{\nu}^{\mathbb{Q}^{T}}(t),
\]
an application of Ito's lemma yields to 
\begin{align*}
d(\bar{h}_{t}^{u}(s)^{2})= & \bigg(\eta_{\nu}^{2}G_{\nu}(s,t)^{2}+2\bar{h}_{t}^{u}(s)G_{\nu}(s,t)\bigg(\kappa_{\nu}\nu_{t}+(b^{u}\rho_{Ir}-u\eta_{\nu}\rho_{\nu r})\eta_{r}B_{G_{r}}(t,T)\bigg)\bigg)dt\\
 & +2\bar{h}_{t}^{u}(s)G_{\nu}(s,t)\eta_{\nu}\:dW_{\nu}^{\mathbb{Q}^{T}}(t).
\end{align*}
Moreover, an application of the Leibniz rule combined with the fact
that $\bar{h}_{t}^{u}(t)=\nu_{t}+\rho_{Ir}\eta_{r}B_{G_{r}}(t,T)$
yields to 
\begin{align*}
d(\bar{\mathbf{\Psi}}_{t}^{u}h_{t}^{u})(s)= & \bigg(-\bar{\psi}_{t}^{u}(s,t)(\nu_{t}+\rho_{Ir}\eta_{r}B_{G_{r}}(t,T))+(\dot{\mathbf{\Psi}_{t}}^{u}h_{t}^u)(s)\\
 & +\bigg(\kappa_{\nu}\nu_{t}+(b^{u}\rho_{Ir}-u\eta_{\nu}\rho_{\nu r})\eta_{r}B_{G_{r}}(t,T)\bigg)(\bar{\mathbf{\Psi}}_{t}^{u}G_{\nu}(.,t))(s)\bigg)\:\bigg)dt\\
 & +(\bar{\mathbf{\Psi}}_{t}^{u}G_{\nu}(.,t)\eta_{\nu})(s)\:dW_{\nu}^{\mathbb{Q}^{T}}(t),
\end{align*}
The quadratic variation $t\to[\bar{h}_{t}^{u}(s),(\bar{\mathbf{\Psi}}_{t}^{u}h_{t})(s)]_{t}$
is given by 
\begin{align*}
d[\bar{h}_{t}^{u}(s),(\bar{\mathbf{\Psi}}_{t}^{u}h_{t}^{u})(s)]_{t} & =\eta_{\nu}^{2}\int_{0}^{T}\bar{\psi}_{t}^{u}(s,w)G_{\nu}(w,t)G_{\nu}(s,t)dwdt\\
 & =-\int_{0}^{T}\bar{\psi}_{t}^{u}(s,w)\dot{\Sigma}_{t}(w,s)dwdt\\
 & =-(\bar{\mathbf{\Psi}}_{t}^{u}\dot{\Sigma}_{t}(.,s))(s)dt.
\end{align*}
Take it all together, we have that 
\begin{align*}
 & a^{u}\,d(\bar{h}_{t}^{u}(s)^{2})+d\bar{h}_{t}^{u}(s)(\bar{\mathbf{\Psi}}_{t}^{u}h_{t}^{u})(s)+\bar{h}_{t}^{u}(s)d(\bar{\mathbf{\Psi}}_{t}^{u}h_{t}^{u})(s)+d[\bar{h}_{t}^{u}(s),(\bar{\mathbf{\Psi}}_{t}^{u}h_{t}^{u})(s)]_{t}\\
=\bigg( & a^{u}\bigg(\eta_{\nu}^{2}G_{\nu}(s,t)^{2}+2\bar{h}_{t}^{u}(s)G_{\nu}(s,t)\bigg(\kappa_{\nu}\nu_{t}+(b^{u}\rho_{Ir}-u\eta_{\nu}\rho_{\nu r})\eta_{r}B_{G_{r}}(t,T)\bigg)\bigg)\\
+ & G_{\nu}(s,t)\bigg(\kappa_{\nu}\nu_{t}+(b^{u}\rho_{Ir}-u\eta_{\nu}\rho_{\nu r})\eta_{r}B_{G_{r}}(t,T)\bigg)(\bar{\mathbf{\Psi}}_{t}^{u}h_{t}^{u})(s)\\
+ & \bar{h}_{t}^{u}(s)\bigg(-\bar{\psi}_{t}^{u}(s,u)(\nu_{t}+\rho_{Ir}\eta_{r}B_{G_{r}}(t,T)+(\dot{\mathbf{\Psi}_{t}}^{u}h_{t}^{u})(s)\\
+ & \bigg(\kappa_{\nu}\nu_{t}+(b^{u}\rho_{Ir}-u\eta_{\nu}\rho_{\nu r})\eta_{r}B_{G_{r}}(t,T)\bigg)(\bar{\mathbf{\Psi}}_{t}^{u}G_{\nu}(.,t))(s)\bigg)-(\bar{\mathbf{\Psi}}_{t}^{u}\dot{\Sigma}_{t}(.,s))(s)\bigg)\:dt\\
+ & \bigg(2a^{u}\bar{h}_{t}^{u}(s)G_{\nu}(s,t)\eta_{\nu}+(\bar{\mathbf{\Psi}}_{t}^{u}h_{t}^{u})(s)G_{\nu}(s,t)\eta_{\nu}+\bar{h}_{t}^{u}(s)(\bar{\mathbf{\Psi}}_{t}^{u}G_{\nu}(.,t)\eta_{\nu})(s)\bigg)\:dW_{\nu}^{\mathbb{Q}^{T}}(t).
\end{align*}
Therefore, we obtain that 
\begin{align*}
d\langle h_{t}^{u},\mathbf{\Psi}_{t}^{u}h_{t}^{u}\rangle_{L^{2}}= & \bigg(-(a^{u}(\nu_{t}+\rho_{Ir}\eta_{r}B_{G_{r}}(t,T))^{2}\\
 & -2(\nu_{t}+\rho_{Ir}\eta_{r}B_{G_{r}}(t,T))(\bar{\mathbf{\Psi}}_{t}^{u}h_{t}^{u})(t)\\
 & +2(\kappa_{\nu}\nu_{t}+(b^{u}\rho_{Ir}-u\eta_{\nu}\rho_{\nu r})\eta_{r}B_{G_{r}}(t,T))(\mathbf{G}_{\nu}^{*}\mathbf{\Psi}_{t}^{u}h_{t})(t)\\
 & +\langle h_{t}^{u},\dot{\mathbf{\Psi}}_{t}^{u}h_{t}^{u}\rangle_{L^{2}}-\text{Tr}(\mathbf{\Psi}_{t}^{u}\dot{\mathbf{\Sigma}}_{t})\bigg)\:dt\\
 & +2\eta_{\nu}(\mathbf{G}_{\nu}^{*}\mathbf{\Psi}_{t}^{u}h_{t}^{u})(t)\:dW_{\nu}^{\mathbb{Q}^{T}}(t).
\end{align*}
Finally, using the fact that $b^{u}=\kappa_{\nu}+u\eta_{\nu}\rho_{I\nu}$
and $(\bar{\mathbf{\Psi}}_{t}^{u}h_{t}^{u})(t)=b^{u}(\mathbf{G}_{\nu}^{*}\mathbf{\Psi}_{t}^{u}h_{t}^{u})(t)$
(see Lemma \ref{lem:integral_operator}), we obtain that 
\begin{align*}
d\langle h_{t}^{u},\mathbf{\Psi}_{t}^{u}h_{t}^{u}\rangle_{L^{2}}= & \bigg(-a^{u}(\nu_{t}+\rho_{Ir}\eta_{r}B_{G_{r}}(t,T))^{2}\\
 & -2u\eta_{\nu}(\rho_{I\nu}\nu_{t}+\rho_{\nu r}\eta_{r}B_{G_{r}}(t,T))(\mathbf{G}_{\nu}^{*}\mathbf{\Psi}_{t}^{u}h_{t})(t)\\
 & -\text{Tr}(\mathbf{\Psi}_{t}^{u}\dot{\mathbf{\Sigma}}_{t})+\langle h_{t}^{u},\dot{\mathbf{\Psi}}_{t}^{u}h_{t}^{u}\rangle_{L^{2}}\bigg)\:dt\\
 & +2\eta_{\nu}(\mathbf{G}_{\nu}^{*}\mathbf{\Psi}_{t}^{u}h_{t}^{u})(t)\:dW_{\nu}^{\mathbb{Q}^{T}}(t).
\end{align*}
\end{proof}
Based now of Lemma \ref{lem:integral_operator} and \ref{lem:h_Psi_t_dynamic},
we are now ready to prove Theorem \ref{thm:chf_general}. 
\begin{proof}
As explained in \cite{key-4}, it is sufficient to make the proof
for $u\in\mathbb{R}$ such $0\leq u\leq1.$ Fix $u\in[0,1]$ and consider
the processes $(U_{t})_{0\leq t\leq T}$ and $(M_{t})_{0\leq t\leq T}$
defined, for $t\in[0,T],$ by 
\begin{equation}
U_{t}=u\log I_{t}^{T}+\phi_{t}^{u}+\chi_{t}^{u}+\langle h_{t}^{u},\mathbf{\Psi}_{t}^{u}h_{t}^{u}\rangle_{L^{2}},\label{eq:dyn_u}
\end{equation}
and 
\[
M_{t}=\exp(U_{t}).
\]
 If we prove that $(M_{t})_{0\leq t\leq T}$ is a martingale under
$\mathbb{Q}^{T}$, then the proof is complete since, in this case,
we have that 
\[
E^{\mathbb{Q}^{T}}(M_{T}|\mathcal{F}_{t})=M_{t},
\]
and thus 
\[
E^{\mathbb{Q}_{}^{T}}\bigg[\exp\bigg(u\log\frac{I_{T}^{T}}{I_{t}^{T}}\bigg)\bigg|\mathcal{F}_{t}\bigg]=\exp(\phi_{t}^{u}+\chi_{t}^{u}+\langle h_{t}^{u},\mathbf{\Psi}_{t}^{u}h_{t}^{u}\rangle_{L^{2}}).
\]
Let us prove that $(M_{t})_{0\leq t\leq T}$ is a (true) martingale
under $\mathbb{Q}^{T}$. First, we can prove that $(M_{t})_{0\leq t\leq T}$
is a local martingale by showing that the drift of the dynamic of
$(M_{t})_{0\leq t\leq T}$ is null. Using the dynamic of $(I_{t}^{T})_{0\leq t\leq T}$
given by \eqref{eq:dyn_forward_inflation}, the dynamic of $(\langle h_{t}^{u},\mathbf{\Psi}_{t}^{u}h_{t}^{u}\rangle_{L^{2}})_{0\leq t\leq T}$
given by \eqref{eq:dyn_quad_function} and the fact that $a^{u}=\frac{1}{2}(u^{2}-u)$,
we observe that 
\begin{align*}
dU_{t}= & u\:d(\log I_{t}^{T})+(\dot{\phi}_{t}^{u}+\dot{\chi}_{t}^{u})dt+d\langle h_{t}^{u},\mathbf{\Psi}_{t}^{u}h_{t}^{u}\rangle_{L^{2}}\\
= & \bigg(-\frac{u^{2}}{2}\bigg(\nu_{t}^{2}+\eta_{r}^{2}B_{G_{r}}(t,T)^{2}+2\nu_{t}\eta_{r}B_{G_{r}}(t,T)\rho_{Ir}\bigg)\\
 & +\langle h_{t}^{u},\dot{\mathbf{\Psi}}_{t}^{u}h_{t}^{u}\rangle_{L^{2}}-2u\eta_{\nu}(\rho_{I\nu}\nu_{t}+\rho_{\nu r}\eta_{r}B_{G_{r}}(t,T))(\mathbf{G}_{\nu}^{*}\mathbf{\Psi}_{t}^{u}h_{t}^{u})(t)\:\bigg)\:dt\\
 & +u\nu_{t}\:dW_{I}^{\mathbb{Q}^{T}}(t)+u\eta_{r}B_{G_{r}}(t,T)dW_{r}^{\mathbb{Q}^{T}}(t)+2\eta_{\nu}(\mathbf{G}_{\nu}^{*}\mathbf{\Psi}_{t}^{u}h_{t}^{u})(t))\:dW_{\nu}^{\mathbb{Q}^{T}}(t).
\end{align*}
Moreover, the quadratic variation of $(U_{t})_{0\leq t\leq T}$ satisfies
\begin{align*}
d\langle U\rangle_{t}= & \bigg((u^{2}\nu_{t}^{2}+4\eta_{\nu}^{2}(\mathbf{G}_{\nu}^{*}\mathbf{\Psi}_{t}^{u}h_{t}^{u})(t))^{2}+u^{2}\eta_{r}^{2}B_{G_{r}}(t,T)^{2}\\
 & +2u^{2}\nu_{t}\rho_{Ir}\eta_{r}B_{G_{r}}(t,T)\\
 & +4u\eta_{\nu}(\mathbf{G}_{\nu}^{*}\mathbf{\Psi}_{t}^{u}h_{t}^u)(t))\bigg(\rho_{I\nu}\nu_{t}+\rho_{r\nu}\eta_{r}B_{G_{r}}(t,T)\bigg)\:\bigg)dt.
\end{align*}
As the dynamic of $(M_{t})_{0\leq t\leq T}$ can be written such that
\[
dM_{t}=M_{t}\,\bigg(\frac{1}{2}d\langle U\rangle_{t}+dU_{t}\bigg),
\]
we easily obtain that 
\begin{align*}
dM_{t}= & M_{t}\,\bigg(2\eta_{\nu}^{2}((\mathbf{G}_{\nu}^{*}\mathbf{\Psi}_{t}^{u}h_{t}^{u})(t))^{2}+\langle h_{t}^{u},\dot{\mathbf{\Psi}}_{t}^{u}h_{t}^{u}\rangle_{L^{2}}\bigg)\:dt\\
 & +M_{t}\,\bigg(u\nu_{t}\:dW_{I}^{\mathbb{Q}^{T}}(t)+u\eta_{r}B_{G_{r}}(t,T)dW_{r}^{\mathbb{Q}_{}^{T}}(t)+2\eta_{\nu}(\mathbf{G}_{\nu}^{*}\mathbf{\Psi}_{t}^{u}h_{t}^{u})(t))\:dW_{\nu}^{\mathbb{Q}_{}^{T}}(t)\bigg),
\end{align*}
but as 
\[
2\eta_{\nu}^{2}((\mathbf{G}_{\nu}^{*}\mathbf{\Psi}_{t}^{u}h_{t}^{u})(t))^{2}=-2\langle h_{t}^{u},\mathbf{\Psi}_{t}^{u}\dot{\mathbf{\Sigma}}_{t}\mathbf{\Psi}_{t}^{u}h_{t}^{u}\rangle_{L^{2}},
\]
we have that 
\begin{align*}
dM_{t}= & M_{t}\,\bigg(\langle h_{t}^{u},(\dot{\mathbf{\Psi}}_{t}^{u}-2\mathbf{\Psi}_{t}^{u}\dot{\mathbf{\Sigma}}_{t}\mathbf{\Psi}_{t}^{u})h_{t}^{u}\rangle_{L^{2}}\bigg)\:dt\\
 & +M_{t}\,\bigg(u\nu_{t}\:dW_{I}^{\mathbb{Q}^{T}}(t)+u\eta_{r}B_{G_{r}}(t,T)dW_{r}^{\mathbb{Q}^{T}}(t)+2\eta_{\nu}(\mathbf{G}_{\nu}^{*}\mathbf{\Psi}_{t}^{u}h_{t}^{u})(t))\:dW_{I}^{\mathbb{Q}^{T}}(t)\bigg)\\
= & M_{t}\,\bigg(u\nu_{t}\:dW_{I}^{\mathbb{Q}^{T}}(t)+u\eta_{r}B_{G_{r}}(t,T)dW_{r}^{\mathbb{Q}^{T}}(t)+2\eta_{\nu}(\mathbf{G}_{\nu}^{*}\mathbf{\Psi}_{t}^{u}h_{t}^{u})(t))\:dW_{I}^{\mathbb{Q}^{T}}(t)\bigg),
\end{align*}
and since, from \cite[Lemma B.1.]{key-4},
\[
\dot{\mathbf{\Psi}}_{t}^{u}-2\mathbf{\Psi}_{t}^{u}\dot{\mathbf{\Sigma}}_{t}\mathbf{\Psi}_{t}^{u}=0,
\]
we have that $(M_{t})_{0\leq t\leq T}$ is a local martingale. It
remains to show that this is a true martingale. Since $\langle h_{t}^{u},\dot{\mathbf{\Psi}}_{t}^{u}h_{t}^{u}\rangle_{L^{2}}\leq0$
and $\phi_{t}^{u}=-\int_{t}^{T}Tr(\mathbf{\Psi}_{s}^{u}\dot{\mathbf{\Sigma}}_{s})\:ds\leq0$,
from \eqref{eq:dyn_u}, it follows that 

\[
U_{t}\leq u\log I_{t}^{T}+\chi_{t}^{u}.
\]
Furthermore, we observe that
\begin{align*}
U_{t}\leq & u\log I_{0}^{T}-\frac{u}{2}^{2}\int_{0}^{t}\bigg(\,\bigg(\nu_{s}+\rho_{Ir}\eta_{r}B_{G_{r}}(s,T)\bigg)^{2}+(1-\rho_{Ir}^{2})\eta_{r}^{2}B_{G_{r}}(s,T)^{2}\bigg)\:ds\\
 & +\frac{1}{2}(u^{2}-u)\bigg(\int_{0}^{T}(1-\rho_{Ir}^{2})\eta_{r}^{2}B_{G_{r}}(s,T)^{2}\:ds\bigg)\\
 & +\int_{0}^{t}u\nu_{s}\:dW_{I}^{\mathbb{Q}^{T}}(s)+\int_{0}^{t}u\eta_{r}B_{G_{r}}(s,T)dW_{r}^{\mathbb{Q}^{T}}(s),
\end{align*}
and, as $u\in[0,1],$ we deduce that 
\begin{align*}
U_{t}\leq & u\log I_{0}^{T}-\frac{u}{2}^{2}\int_{0}^{t}\bigg(\,\bigg(\nu_{s}+\rho_{Ir}\eta_{r}B_{G_{r}}(s,T)\bigg)^{2}+(1-\rho_{Ir}^{2})\eta_{r}^{2}B_{G_{r}}(s,T)^{2}\bigg)\:ds\\
 & +\int_{0}^{t}u\nu_{s}\:dW_{I}^{\mathbb{Q}^{T}}(s)+\int_{0}^{t}u\eta_{r}B_{r}(s,T)dW_{r}^{\mathbb{Q}^{T}}(s).
\end{align*}
Then, we define the process $(N_{t})_{0\leq t\leq T}$ such that 
\begin{align*}
N_{t}:= & \bigg(I_{0}^{T}\bigg)^{u}\exp\bigg(-\frac{u}{2}^{2}\int_{0}^{t}\bigg(\,\bigg(\nu_{s}+\rho_{Ir}\eta_{r}B_{G_{r}}(s,T)\bigg)^{2}+(1-\rho_{Ir}^{2})\eta_{r}^{2}B_{G_{r}}(s,T)^{2}\bigg)\:ds\\
 & +\int_{0}^{t}u\nu_{s}\:dW_{I}^{\mathbb{Q}^{T}}(s)+\int_{0}^{t}u\eta_{r}B_{G_{r}}(s,T)dW_{r}^{\mathbb{Q}^{T}}(s)\bigg),
\end{align*}
This process $(N_{t})_{0\leq t\leq T}$ is a true martingale (see
arguments in \cite[in Lemma 7.3]{key-3}). Therefore, we finally have
that 
\[
|M_{t}|\leq\exp(U_{t})\leq N_{t}
\]
and as $(M_{t})_{0\leq t\leq T}$ is a local martingale upper bounded
by a true martingale, this a true martingale and it completes the
proof. 
\end{proof}

\subsection{Proof of Proposition \ref{prop:riccati_ODE_last}}

We first consider a lemma before proving Proposition \ref{prop:riccati_ODE_last}. 
\begin{lem}
\label{lem:laplace_representation}Assume that the kernel function
$G_{\nu}(t,s)$ is completely monotone and can be represented as \eqref{eq:completely_monotone_kernel}.
Then, 
\[
\nu_{t}=g_{0}^{T}(t)+\int_{\mathbb{R}_{+}}Y_{t}(x)\:\lambda(dx),\:t\leq T,
\]
\[
g_{t}(s)=1_{t\leq s}\bigg(g_{0}^{T}(s)+\int_{\mathbb{R}_{+}}e^{-x(s-t)}Y_{t}(x)\:\lambda(dx)\bigg),
\]
with 
\begin{equation}
Y_{t}(x)=\int_{0}^{t}e^{-(t-w)x}\kappa_{\nu}\:\nu_{w}\:dw+\int_{0}^{t}e^{-(t-w)x}\eta_{\nu}\:dW_{\nu}^{\mathbb{Q}^{T}}(w),\:t\leq T,\:x\in\mathbb{R}_{+}.\label{eq:Y_t_x}
\end{equation}
Moreover, for $u\in\mathbb{C}$ such that $0\leq\mathcal{\mathfrak{R}}(u)\leq1,$
\[
h_{t}^{u}(s)=g_{t}(s)+1_{t\leq s}\bigg(\rho_{Ir}\eta_{r}B_{G_{t}}(s,T)-\int_{\mathbb{R}_{+}}b_{t}^{u}(s,x)\:\lambda(dx)\bigg),
\]
with
\begin{equation}
b_{t}^{u}(s,x)=\int_{t}^{s}e^{-(s-w)x}\bigg((b^{u}\rho_{Ir}-u\eta_{\nu}\rho_{\nu r})\eta_{r}B_{G_{r}}(w,T)\bigg)\:dw,\:t\leq s\leq T,\:x\in\mathbb{R}_{+}.\label{eq:b_t_u}
\end{equation}
\end{lem}

\begin{proof}
For $t\leq T$, applying Fubini's theorem, we can rewrite $\nu_{t}$
such that 
\begin{align*}
\nu_{t} & =g_{0}^{T}(s)+\int_{0}^{t}G_{\nu}(t,w)\kappa_{\nu}\:\nu_{u}dw+\int_{0}^{t}G_{\nu}(t,w)\eta_{\nu}\:dW_{\nu}^{\mathbb{Q}^{T}}(w)\\
 & =g_{0}^{T}(s)+\int_{0}^{t}\int_{\mathbb{R}_{+}}e^{-(t-w)x}\lambda(dx)\kappa_{\nu}\:\nu_{w}dw+\int_{0}^{t}\int_{\mathbb{R}_{+}}e^{-(t-w)x}\lambda(dx)\eta_{\nu}\:dW_{\nu}^{\mathbb{Q}^{T}}(w)\\
 & =g_{0}^{T}(s)+\int_{\mathbb{R}_{+}}\bigg(\int_{0}^{t}e^{-(t-w)x}\kappa_{\nu}\:\nu_{w}dw+\int_{0}^{t}e^{-(t-w)x}\eta_{\nu}\:dW_{\nu}^{\mathbb{Q}^{T}}(w)\bigg)\:\lambda(dx)\\
 & =g_{0}^{T}(s)+\int_{\mathbb{R}_{+}}Y_{t}(x)\:\lambda(dx),
\end{align*}
with $Y_{t}(x)$ given by \eqref{eq:Y_t_x}. Using the same arguments,
we obtain that, 
\[
g_{t}(s)=1_{t\leq s}\bigg(g_{0}^{T}(s)+\int_{\mathbb{R}_{+}}e^{-x(s-t)}Y_{t}(x)\:\lambda(dx)\bigg).
\]
 Finally, we have that, 
\begin{align*}
h_{t}^{u}(s)= & g_{t}(s)+1_{t\leq s}\bigg(\rho_{Ir}\eta_{r}B_{G_{r}}(s,T)-\int_{t}^{s}G_{\nu}(s,w)\bigg((b^{u}\rho_{Ir}-u\eta_{\nu}\rho_{\nu r})\eta_{r}B_{G_{r}}(w,T)\bigg)dw\bigg)\\
= & g_{t}(s)+1_{t\leq s}\bigg(\rho_{Ir}\eta_{r}B_{G_{r}}(s,T)-\int_{\mathbb{R}_{+}}\bigg(\int_{t}^{s}e^{-(s-w)x}\bigg((b^{u}\rho_{Ir}-u\eta_{\nu}\rho_{\nu r})\eta_{r}B_{G_{r}}(w,T)\bigg)\:dw\bigg)\:\lambda(dx)\bigg)\\
= & g_{t}(s)+1_{t\leq s}\bigg(\rho_{Ir}\eta_{r}B_{G_{r}}(s,T)-\int_{\mathbb{R}_{+}}b_{t}^{u}(s,x)\:\lambda(dx)\bigg),
\end{align*}
with $b_{t}^{u}(s,x)$ given by \eqref{eq:b_t_u}.
\end{proof}
