\begin{proof}
We divide the proof into two steps. The first step is to show that
\[
E^{\mathbb{Q}^{T}}\bigg[\exp\bigg(u\log\frac{I_{T}^{T}}{I_{t}^{T}}\bigg)\bigg|\mathcal{F}_{t}\bigg]=\exp\bigg(\Theta_{t}^{u}+2\int_{\mathbb{R}_{+}}\Lambda_{t}^{u}(x)Y_{t}(x)\:\lambda(dx)+\int_{\mathbb{R}_{+}^{2}}\Gamma_{t}^{u}(x,y)Y_{t}(x)Y_{t}(y)\:\lambda(dx)\:\lambda(dy)\bigg),
\]
with $t\to(\Theta_{t}^{u},\Lambda_{t}^{u},\Gamma_{t}^{u})$ such that
\begin{equation}
\Theta_{t}^{u}:=\phi_{t}^{u}+\chi_{t}^{u}+\int_{t}^{T}a^{u}\bar{h}_{t}^{u}(s)^{2}ds+\int_{t}^{T}\int_{t}^{T}\bar{h}_{t}^{u}(s)\bar{h}_{t}(w)\bar{\psi}_{t}^{u}(s,w)dsdw,\label{eq:capital_theta}
\end{equation}
\begin{equation}
\Lambda_{t}(x):=\int_{t}^{T}a^{u}\bar{h}_{t}^{u}(s)e^{-x(s-t)}\,ds+\int_{t}^{T}\int_{t}^{T}\bar{h}_{t}^{u}(w)e^{-x(s-t)}\bar{\psi}_{t}^{u}(s,w)\,dsdw,\:x\in\mathbb{R}_{+},\label{eq:capital_lambda}
\end{equation}
and 
\begin{equation}
\Gamma_{t}(x,y):=\int_{t}^{T}\int_{t}^{T}e^{-x(s-t)}e^{-y(w-t)}\:(a^{u}\delta_{s=w}+\bar{\psi}_{t}^{u}(s,w))\:ds\,dw,\:(x,y)\in\mathbb{R}_{+}^{2},\label{eq:capital_gamma}
\end{equation}
with $\bar{h}_{t}^{u}(s)$ a time-dependent function given by 
\begin{equation}
\bar{h}_{t}^{u}(s):=1_{t\leq s}\bigg(g_{0}^{T}(s)+\rho_{Ir}\eta_{r}B_{G_{r}}(s,T)-\int_{\mathbb{R}_{+}}b_{t}^{u}(s,x)\:\lambda(dx)\bigg).\label{eq:h_t_u_bar}
\end{equation}
Then, the second step is to deduce the equations satisfied by $(\Theta_{t}^{u},\Lambda_{t}^{u},\Gamma_{t}^{u})$. 
\subsubsection*{Step 1}

Using Proposition \ref{prop:-chf_riccati_1}, we have that 
\[
E^{\mathbb{Q}^{T}}\bigg[\exp\bigg(u\log\frac{I_{T}^{T}}{I_{t}^{T}}\bigg)\bigg|\mathcal{F}_{t}\bigg]=\exp(\phi_{t}^{u}+\chi_{t}^{u}+a^{u}\int_{t}^{T}h_{t}^{u}(s)^{2}ds+\int_{t}^{T}\int_{t}^{T}h_{t}^{u}(s)h_{t}^{u}(w)\:\bar{\psi}_{t}^{u}(s,w)dsdw).
\]
Moreover, from Lemma \ref{lem:laplace_representation}, we have that
\[
h_{t}^{u}(s)=\bar{h}_{t}^{u}(s)+1_{t\leq s}\int_{\mathbb{R}_{+}}e^{-x(s-t)}Y_{t}(x)\:\lambda(dx),
\]
with $\bar{h}_{t}^{u}(s)$ given by \eqref{eq:h_t_u_bar}. \\
Therefore, using once again Fubini's theorem, we have that 
\begin{align*}
\int_{t}^{T}h_{t}^{u}(s)^{2}ds= & \int_{t}^{T}\bigg(\bar{h}_{t}^{u}(s)+\int_{\mathbb{R}_{+}}e^{-x(s-t)}Y_{t}(x)\:\lambda(dx)\bigg)\:\bigg(\bar{h}_{t}^{u}(s)+\int_{\mathbb{R}_{+}}e^{-y(s-t)}Y_{t}(y)\:\lambda(dy)\bigg)ds\\
= & \int_{t}^{T}\bigg(\bar{h}_{t}^{u}(s)^{2}+2\bar{h}_{t}^{u}(s)\int_{\mathbb{R}_{+}}e^{-x(s-t)}Y_{t}(x)\:\lambda(dx)+\int_{\mathbb{R}_{+}^{2}}e^{-x(s-t)}e^{-y(s-t)}Y_{t}(x)\:Y_{t}(y)\:\lambda(dx)\:\lambda(dy)\bigg)ds\\
= & \int_{t}^{T}\bar{h}_{t}^{u}(s)^{2}ds+\int_{\mathbb{R}_{+}}\bigg(\int_{t}^{T}2\bar{h}_{t}^{u}(s)e^{-x(s-t)}\,ds\bigg)\:Y_{t}(x)\:\lambda(dx)\\
 & +\int_{\mathbb{R}_{+}^{2}}\bigg(\int_{t}^{T}e^{-x(s-t)}e^{-y(s-t)}ds\bigg)Y_{t}(x)\:Y_{t}(y)\:\lambda(dx)\:\lambda(dy),
\end{align*}
and 
\begin{align*}
\int_{t}^{T}\int_{t}^{T}h_{t}^{u}(s)h_{t}^{u}(w)\:\bar{\psi}_{t}^{u}(s,w)dsdw= & \int_{t}^{T}\int_{t}^{T}\bar{h}_{t}^{u}(s)\bar{h}_{t}^{u}(w)\bar{\psi}_{t}^{u}(s,w)dsdw\\
 & +\int_{\mathbb{R}_{+}}\bigg(\int_{t}^{T}\int_{t}^{T}2\bar{h}_{t}^{u}(w)e^{-x(s-t)}\bar{\psi}_{t}^{u}(s,w)\,dsdw\bigg)\:Y_{t}(x)\:\lambda(dx)\\
 & +\int_{\mathbb{R}_{+}^{2}}\bigg(\int_{t}^{T}\int_{t}^{T}e^{-x(s-t)}e^{-y(u-t)}\bar{\psi}_{t}^{u}(s,w)ds\,dw\bigg)Y_{t}(x)\:Y_{t}(y)\:\lambda(dx)\:\lambda(dy).
\end{align*}
 Thus, we have that 
\begin{align*}
a^{u}\int_{t}^{T}h_{t}^{u}(s)^{2}ds+\int_{t}^{T}\int_{t}^{T}h_{t}^{u}(s)h_{t}^{u}(w)\:\bar{\psi}_{t}^{u}(s,w)dsdw= & \int_{t}^{T}a^{u}\bar{h}_{t}^{u}(s)^{2}ds+\int_{t}^{T}\int_{t}^{T}\bar{h}_{t}^{u}(s)\bar{h}_{t}^{u}(w)\bar{\psi}_{t}^{u}(s,w)dsdw\\
 & +2\int_{\mathbb{R}_{+}}\bigg(\int_{t}^{T}a^{u}\bar{h}_{t}^{u}(s)e^{-x(s-t)}\,ds\\
 & \;\;\;\;\;\;\;+\int_{t}^{T}\int_{t}^{T}\bar{h}_{t}^{u}(w)e^{-x(s-t)}\bar{\psi}_{t}^{u}(s,w)\,dsdw\bigg)\:Y_{t}(x)\:\lambda(dx)\\
 & +\int_{\mathbb{R}_{+}^{2}}\bigg(\int_{t}^{T}\int_{t}^{T}e^{-x(s-t)}e^{-y(w-t)}\:(a^{u}\delta_{s=w}\\
 & \;\;\;\;\;\;\;\;\;\;\;\;\;\;+\bar{\psi}_{t}^{u}(s,w))\:ds\,dw\bigg)Y_{t}(x)\:Y_{t}(y)\:\lambda(dx)\:\lambda(dy).
\end{align*}
By defining $t\to(\Theta_{t}^{u},\Lambda_{t}^{u},\Gamma_{t}^{u})$
by \eqref{eq:capital_theta}-\eqref{eq:capital_lambda}-\eqref{eq:capital_gamma},
we obtain that 
\[
E^{\mathbb{Q}^{T}}\bigg[\exp\bigg(u\log\frac{I_{T}^{T}}{I_{t}^{T}}\bigg)\bigg|\mathcal{F}_{t}\bigg]=\exp\bigg(\Theta_{t}^{u}+2\int_{\mathbb{R}_{+}}\Lambda_{t}^{u}(x)Y_{t}(x)\:\lambda(dx)+\int_{\mathbb{R}_{+}^{2}}\Gamma_{t}^{u}(x,y)Y_{t}(x)Y_{t}(y)\:\lambda(dx)\:\lambda(dy)\bigg).
\]


\subsubsection*{Step 2}

Let us now deduce the equations satisfied by $(\Theta_{t}^{u},\Lambda_{t}^{u},\Gamma_{t}^{u})$.
First, we have that 
\[
\Gamma_{t}^{u}(x,y)=\int_{t}^{T}\int_{t}^{T}e^{-x(s-t)}e^{-y(w-t)}\bigg(a^{u}\delta_{s=w}+\bar{\psi}_{t}^{u}(s,w)\bigg)ds\,dw.
\]
 A direct differentiation of $t\to\Gamma_{t}^{u}$ with respect to
$t$ leads to 
\begin{align*}
\dot{\Gamma}_{t}^{u}(x,y)= & (x+y)\Gamma_{t}^{u}(x,y)-a^{u}-\int_{t}^{T}\bigg(e^{-x(s-t)}+e^{-y(s-t)}\bigg)\:\bar{\psi}_{t}^{u}(s,t)ds\\
 & +\int_{t}^{T}\int_{t}^{T}e^{-x(s-t)}e^{-y(w-t)}\dot{\bar{\psi}}_{t}^{u}(s,w)ds\,dw.
\end{align*}
Using the form of $\dot{\bar{\psi}}_{t}^{u}(s,w),$ we obtain that
\[
\int_{t}^{T}\int_{t}^{T}e^{-x(s-t)}e^{-y(w-t)}\dot{\bar{\psi}}_{t}^{u}(s,w)ds\,dw=-2\,\eta_{\nu}^{2}\bigg(\int_{\mathbb{R}_{+}}\Gamma_{t}^{u}(x,x')\:\lambda(dx')\bigg)\bigg(\int_{\mathbb{R}_{+}}\Gamma_{t}^{u}(y,y')\:\lambda(dy')\bigg).
\]
Moreover, using \eqref{eq:cond_psi_t} in Lemma \ref{lem:integral_operator}
and once again the Fubini's theorem, we have that
\begin{align*}
\int_{t}^{T}e^{-x(s-t)}\:(\bar{\psi}_{t}^{u}(s,t))ds & =b^{u}\int_{t}^{T}e^{-x(s-t)}\int_{t}^{T}G_{\nu}(w,t)(a^{u}\delta_{w=s}+\bar{\psi}_{t}^{u}(s,w))dwds\\
 & =b^{u}\bigg(\int_{t}^{T}e^{-x(s-t)}\int_{t}^{T}\bigg(\int_{\mathbb{R}_{+}}e^{-x^{'}(w-t)}\:\lambda(dx')\bigg)\:(a^{u}\delta_{w=s}+\bar{\psi}_{t}^{u}(s,w)\:dwds\\
 & =b^{u}\int_{\mathbb{R}_{+}}\bigg(\int_{t}^{T}\int_{t}^{T}e^{-x^{'}(w-t)}e^{-x(s-t)}\bigg(a^{u}\delta_{w=s}+\bar{\psi}_{t}^{u}(s,w)\bigg)\:dwds\bigg)\:\lambda(dx')\\
 & =b^{u}\int_{\mathbb{R}_{+}}\Gamma_{t}(x,x^{'})\:\lambda(dx').
\end{align*}
Using the same arguments, we also obtain that 
\[
\int_{t}^{T}e^{-y(s-t)}\:(a^{u}\delta_{s=w}+\bar{\psi}_{t}^{u}(s,t))ds=b^{u}\int_{\mathbb{R}_{+}}\Gamma_{t}^{u}(y^{'},y)\:\lambda(dy').
\]
Thus, we deduce that 
\begin{align*}
\dot{\Gamma}_{t}^{u}(x,y)= & (x+y)\Gamma_{t}^{u}(x,y)-a^{u}-2\,\eta_{\nu}^{2}\bigg(\int_{\mathbb{R}_{+}}\Gamma_{t}^{u}(x,x')\:\lambda(dx')\bigg)\bigg(\int_{\mathbb{R}_{+}}\Gamma_{t}^{u}(y,y')\:\lambda(dy')\bigg)\\
 & -b^{u}\bigg(\int_{\mathbb{R}_{+}}\Gamma_{t}^{u}(x,x^{'})\:\lambda(dx')+\int_{\mathbb{R}_{+}}\Gamma_{t}^{u}(y^{'},y)\:\lambda(dy')\bigg).
\end{align*}
Let us consider now the ODE satisfied by $t\to\Lambda_{t}^{u}$. We
have that 
\begin{align*}
\Lambda_{t}^{u}(x) & =\int_{t}^{T}a^{u}\bar{h}_{t}^{u}(s)e^{-x(s-t)}\,ds+\int_{t}^{T}\int_{t}^{T}\bar{h}_{t}^{u}(w)e^{-x(s-t)}\bar{\psi}_{t}^{u}(s,w)\,dsdw\\
 & =\int_{t}^{T}\int_{t}^{T}\bar{h}_{t}^{u}(w)e^{-x(s-t)}\bigg(a^{u}\delta_{s=w}+\bar{\psi}_{t}^{u}(s,w)\bigg)\,dsdw.
\end{align*}
Using the same argument than for $\Gamma_{t}^{u},$ we have that 
\begin{align*}
\dot{\Lambda}_{t}^{u}(x)= & -a^{u}\bar{h}_{t}^{u}(t)+x\Lambda_{t}^{u}(x)+\int_{t}^{T}\int_{t}^{T}\bar{h}_{t}^{u}(w)e^{-x(s-t)}\dot{\bar{\psi}}_{t}^{u}(s,w)\,dsdw\\
 & +\int_{t}^{T}\int_{t}^{T}\dot{\bar{h}}_{t}^{u}(w)e^{-x(s-t)}\bigg(a^{u}\delta_{s=w}+\bar{\psi}_{t}^{u}(s,w)\bigg)\,dsdw\\
 & -\int_{t}^{T}(\bar{h}_{t}^{u}(t)e^{-x(s-t)}+\bar{h}_{t}^{u}(s))\:\bar{\psi}_{t}^{u}(s,t)\,ds.
\end{align*}
Using the form of $\dot{\bar{\psi}}_{t}^{u}(s,w),$ we obtain that
\[
\int_{t}^{T}\int_{t}^{T}\bar{h}_{t}^{u}(w)e^{-x(s-t)}\dot{\bar{\psi}}_{t}^{u}(s,w)\,dsdw=-2\eta_{\nu}^{2}\bigg(\int_{\mathbb{R}_{+}}\Gamma_{t}^{u}(x,x')\:\lambda(dx')\bigg)\bigg(\int_{\mathbb{R}_{+}}\Lambda_{t}^{u}(y)\:\lambda(dy)\bigg),
\]
and, using similar arguments than previously, we also have that 
\begin{align*}
\int_{t}^{T}(\bar{h}_{t}^{u}(t)e^{-x(s-t)}+\bar{h}_{t}^{u}(s))\:\bar{\psi}_{t}^{u}(s,t)\,ds & =b^{u}\int_{t}^{T}\int_{t}^{T}(\bar{h}_{t}^{u}(t)e^{-x(s-t)}+\bar{h}_{t}^{u}(s))\:G(w,t)(a^{u}\delta_{w=s}+\bar{\psi}_{t}^{u}(s,w))\:dw\,ds\\
 & =b^{u}\int_{\mathbb{R}_{+}}\bigg(\int_{t}^{T}\int_{t}^{T}e^{-x^{'}(w-t)}(\bar{h}_{t}^{u}(t)e^{-x(s-t)}+\bar{h}_{t}^{u}(s))\:(a^{u}\delta_{w=s}\\
 & \;\;\;\;\;\;\;\;\;\;\;\;\;\;\;\;\;\;\;\;\;\;\;\;\;\;\;\;+\bar{\psi}_{t}^{u}(s,w))\:dwds\bigg)\:\lambda(dx')\\
 & =b^{u}\int_{\mathbb{R}_{+}}\bigg(\bar{h}_{t}^{u}(t)\Gamma_{t}^{u}(x,x^{'})+\Lambda_{t}^{u}(x^{'})\bigg)\:\lambda(dx').
\end{align*}
Moreover, as 
\[
\dot{\bar{h}}_{t}^{u}(s)=(b^{u}\rho_{Ir}-u\eta_{\nu}\rho_{\nu r})\eta_{r}B_{G_{r}}(t,T)\int_{\mathbb{R}_{+}}e^{-(s-t)x^{'}}\,\:\lambda(dx^{'}),
\]
we have that 
\begin{align*}
 & \int_{t}^{T}\int_{t}^{T}\dot{\bar{h}}_{t}^{u}(w)e^{-x(s-t)}\bigg(a^{u}\delta_{s=w}+\bar{\psi}_{t}^{u}(s,w)\bigg)\,dsdw\\
 & =(b^{u}\rho_{Ir}-u\eta_{\nu}\rho_{\nu r})\eta_{r}B_{G_{r}}(t,T)\int_{\mathbb{R}_{+}}\Gamma_{t}^{u}(x,x^{'})\,\:\lambda(dx^{'}).
\end{align*}
Therefore, as $\bar{h}_{t}^{u}(t)=g_{0}^{T}(t)+\rho_{Ir}\eta_{r}B_{G_{r}}(t,T)$,
we obtain that 
\begin{align*}
\dot{\Lambda}_{t}^{u}(x)= & -a^{u}\bar{h}_{t}^{u}(t)+x\Lambda_{t}^{u}(x)-2\eta_{\nu}^{2}\bigg(\int_{\mathbb{R}_{+}}\Gamma_{t}^{u}(x,x')\:\lambda(dx')\bigg)\bigg(\int_{\mathbb{R}_{+}}\Lambda_{t}^{u}(y)\:\lambda(dy)\bigg)\\
 & -\int_{\mathbb{R}_{+}}\bigg(b^{u}\bar{h}_{t}^{u}(t)-(b^{u}\rho_{Ir}-u\eta_{\nu}\rho_{\nu r})\eta_{r}B_{G_{r}}(t,T)\bigg)\Gamma_{t}^{u}(x,x^{'})\:\lambda(dx')\\
 & -b^{u}\int_{\mathbb{R}_{+}}\Lambda_{t}^{u}(x^{'})\:\lambda(dx')\\
= & -a^{u}\bigg(g_{0}^{T}(t)+\rho_{Ir}\eta_{r}B_{G_{r}}(t,T)\bigg)+x\Lambda_{t}^{u}(x)-2\eta_{\nu}^{2}\bigg(\int_{\mathbb{R}_{+}}\Gamma_{t}^{u}(x,x')\:\lambda(dx')\bigg)\bigg(\int_{\mathbb{R}_{+}}\Lambda_{t}^{u}(y)\:\lambda(dy)\bigg)\\
 & -\int_{\mathbb{R}_{+}}\bigg(b^{u}g_{0}^{T}(t)+u\eta_{\nu}\rho_{\nu r}\eta_{r}B_{G_{r}}(t,T)\bigg)\Gamma_{t}^{u}(x,x^{'})\:\lambda(dx')\\
 & -b^{u}\int_{\mathbb{R}_{+}}\Lambda_{t}^{u}(x^{'})\:\lambda(dx').
\end{align*}
Finally, let us consider the equation satisfied by $t\to\Theta_{t}^{u}$.
We know that 
\begin{align*}
\Theta_{t}^{u} & =\phi_{t}^{u}+\chi_{t}^{u}+\int_{t}^{T}a^{u}\bar{h}_{t}^{u}(s)^{2}ds+\int_{t}^{T}\int_{t}^{T}\bar{h}_{t}^{u}(s)\bar{h}_{t}^{u}(w)\bar{\psi}_{t}^{u}(s,w)dsdw\\
 & =\phi_{t}^{u}+\chi_{t}^{u}+\int_{t}^{T}\int_{t}^{T}\bar{h}_{t}^{u}(s)\bar{h}_{t}^{u}(w)(a^{u}\delta_{s=w}+\bar{\psi}_{t}^{u}(s,w))dsdw.
\end{align*}
Therefore, we have that 
\begin{align*}
\dot{\Theta}_{t}^{u}= & \dot{\phi}_{t}^{u}+\dot{\chi}_{t}^{u}-a^{u}\bar{h}_{t}^{u}(t)^{2}+\int_{t}^{T}\int_{t}^{T}\bar{h}_{t}^{u}(s)\bar{h}_{t}^u(w)\dot{\bar{\psi}}_{t}^{u}(s,w)\,dsdw\\
 & -2\bar{h}_{t}^{u}(t)\int_{t}^{T}\bar{h}_{t}^{u}(s)\:\bar{\psi}_{t}^{u}(s,t)\,ds\\
 & +2\int_{t}^{T}\int_{t}^{T}\dot{\bar{h}}_{t}^{u}(s)\bar{h}_{t}^{u}(w)(a\delta_{s=w}+\bar{\psi}_{t}^{u}(s,w))\,dsdw.
\end{align*}
 Using once again the form of $\dot{\bar{\psi}}_{t}^{u}(s,w),$ we
deduce that 
\[
\int_{t}^{T}\int_{t}^{T}\bar{h}_{t}^{u}(s)\bar{h}_{t}^u(w)\dot{\bar{\psi}}_{t}^{u}(s,w)\,dsdw=-2\eta_{\nu}^{2}\bigg(\int_{\mathbb{R}_{+}}\Lambda_{t}^{u}(x)\:\lambda(dx))\bigg)\bigg(\int_{\mathbb{R}_{+}}\Lambda_{t}^{u}(y)\:\lambda(dy)\bigg).
\]
 Also, we have that 
\[
-2\bar{h}_{t}^{u}(t)\int_{t}^{T}\bar{h}_{t}^{u}(s)\:\bar{\psi}_{t}^{u}(s,t)\,ds=-2b^{u}\bar{h}_{t}^{u}(t)\int_{\mathbb{R}_{+}}\Lambda_{t}^{u}(x^{'})\:\lambda(dx'),
\]
and
\begin{align*}
\dot{\phi}_{t}^{u} & =-\eta_{\nu}^{2}\int_{t}^{T}\int_{t}^{T}G_\nu(s,t)G_\nu(w,t)\bigg(a^{u}\delta_{s=w}+\bar{\psi}_{t}^{u}(s,w)\bigg)ds\,dw\\
 & =-\eta_{\nu}^{2}\int_{\mathbb{R}_{+}}\int_{\mathbb{R}_{+}}\Gamma_{t}^{u}(x,y)\:\lambda(dx)\:\lambda(dy),
\end{align*}
Moreover, as 
\begin{align*}
2\int_{t}^{T}\int_{t}^{T}\dot{\bar{h}}_{t}^{u}(s)\bar{h}_{t}^{u}(w)(a^{u}\delta_{s=w}+\bar{\psi}_{t}^{u}(s,w))\,dsdw= & 2(b^{u}\rho_{Ir}-u\eta_{\nu}\rho_{\nu r})\eta_{r}B_{G_{r}}(t,T)\\
 & \int_{\mathbb{R}_{+}}\bigg(\int_{t}^{T}e^{-(s-t)x^{'}}\bar{h}_{t}(u)(a\delta_{s=u}+\bar{\psi}_{t}(s,u))\,dsdu\bigg)\:\lambda(dx^{'})\\
= & 2(b^{u}\rho_{Ir}-u\eta_{\nu}\rho_{\nu r})\eta_{r}B_{G_{r}}(t,T)\int_{\mathbb{R}_{+}}\Lambda_{t}(x^{'})\:\lambda(dx^{'}),
\end{align*}
and $\bar{h}_{t}^{u}(t)=g_{0}^{T}(t)+\rho_{Ir}\eta_{r}B_{G_{r}}(t,T)$,
we finally obtain that 
\begin{align*}
\dot{\Theta}_{t}^{u}= & \dot{\chi}_{t}^{u}-a^{u}\bigg(g_{0}^{T}(t)+\rho_{Ir}\eta_{r}B_{G_{r}}(t,T)\bigg)^{2}-\eta_{\nu}^{2}\bigg(2\bigg(\int_{\mathbb{R}_{+}}\Lambda_{t}^{u}(x)\:\lambda(dx))\bigg)^{2}+\int_{\mathbb{R}_{+}}\int_{\mathbb{R}_{+}}\Gamma_{t}^{u}(x,y)\:\lambda(dx)\:\lambda(dy)\bigg)\\
 & -2\int_{\mathbb{R}_{+}}\bigg(b^{u}g_{0}^{T}(t)+u\eta_{\nu}\rho_{\nu r}\eta_{r}B_{G_{r}}(t,T)\bigg)\:\Lambda_{t}^{u}(x^{'})\:\lambda(dx'),
\end{align*}
and that concludes the proof. 
\end{proof}

\subsection{Proof of Proposition \ref{prop:chf_multi_factors_ODE}}
\begin{proof}
Assuming that $G_{\nu}(t,s)=1_{s<t}\sum_{i=1}^{N}w_{i}e^{-x_{i}(t-s)}$
and $g_{0}^{T}(t)=\nu_{0}+\sum_{i=1}^{N}\int_{0}^{t}\theta(s)w_{i}\exp(-x_{i}(t-s))ds$,
with $\theta(t):=\theta_{\nu}-\eta_{\nu}\eta_{r}\rho_{r\nu}B_{G_{r}}(t,T),$
the volatility process $(\nu_{t})_{0\leq t\leq T}$ reduces to 
\[
\nu_{t}=\nu_{0}+\int_{0}^{t}\sum_{i=1}^{N}w_{i}\exp(-x_{i}(t-s))(\theta(s)+\kappa_{\nu}\:\nu_{s})ds+\eta_{\nu}\int_{0}^{t}\sum_{i=1}^{N}w_{i}\exp(-x_{i}(t-s))\:dW_{\nu}^{\mathbb{Q}_{}^{T}}(t).
\]
Let us introduce some auxiliary processes $\left((\nu_{t}^{i})_{i=1,...,N}\right)_{0\leq t\leq T}$
solution of the following SDEs 
\begin{align*}
d\nu_{t}^{i} & =(-x_{i}\nu_{t}^{i}+\theta(t)+\kappa_{\nu}\:\nu_{t})\:dt+\eta_{\nu}\:dW_{\nu}^{\mathbb{Q}^{T}}(t),\:t>0,\:i=1,...,N,\\
\nu_{0}^{i} & =0.
\end{align*}
Then, we can deduce that, almost surely, 
\[
\nu_{t}=\nu_{0}+\sum_{i=1}^{N}w_{i}\nu_{t}^{i},\:t\leq T.
\]
Also, we observe that 
\[
g_{t}(s)=1_{t\leq s}\bigg(\nu_{0}+\sum_{i=1}^{N}w_{i}e^{-x_{i}(s-t)}\nu_{t}^{i}\bigg),\;s,t\leq T,
\]
and 
\[
G_{\nu}(t,s)=1_{s<t}\sum_{i=1}^{N}w_{i}e^{-x_{i}(t-s)}=1_{s<t}\int_{0}^{+\infty}e^{-(t-s)x}\lambda(dx),
\]
with
\[
\lambda(dx)=\sum_{i=1}^{N}w_{i}\delta_{x=x_{i}}dx.
\]
We also have that, for $i=1,...,N,$
\[
Y_{t}(x_{i})=\nu_{t}^{i}-\theta_{x_{i}}(t).
\]
with $\theta_{x}(t):=\int_{0}^{t}e^{-x(t-s)}\theta(s)\:ds.$ Therefore,
using Proposition \ref{prop:riccati_ODE_last}, we have that 
\begin{align*}
E^{\mathbb{Q}^{T}}\bigg[\exp\bigg(u\log\frac{I_{T}^{T}}{I_{t}^{T}}\bigg)\bigg|\mathcal{F}_{t}\bigg]= & \exp\bigg(\Theta_{t}^{u}+2\int_{\mathbb{R}_{+}}\Lambda_{t}^{u}(x)Y_{t}(x)\:\lambda(dx)+\int_{\mathbb{R}_{+}^{2}}\Gamma_{t}^{u}(x,y)Y_{t}(x)Y_{t}(y)\:\lambda(dx)\:\lambda(dy)\bigg)\\
= & \exp\bigg(\Theta_{t}^{u}+2\sum_{i=1}^{N}w_{i}\int_{\mathbb{R}_{+}}\Lambda_{t}^{u}(x)Y_{t}(x)\:\delta_{x=x_{i}}dx\\
 & +\sum_{i,j=1}^{N}w_{i}w_{j}\int_{\mathbb{R}_{+}^{2}}\Gamma_{t}^{u}(x,y)Y_{t}(x)Y_{t}(y)\:\delta_{x=x_{i}}\delta_{y=x_{j}}dx\:dy\bigg)\\
= & \exp\bigg(\Theta_{t}^{u}+2\sum_{i=1}^{N}w_{i}\Lambda_{t}^{u}(x_{i})Y_{t}(x_{i})+\sum_{i,j=1}^{N}w_{i}w_{j}\Gamma_{t}^{u}(x_{i},x_{j})Y_{t}(x_{i})Y_{t}(x_{j})\bigg)\\
= & \exp\bigg(\Theta_{t}^{u}-2\sum_{i=1}^{N}w_{i}\Lambda_{t}^{u}(x_{i})\theta_{x_{i}}(t)+\sum_{i=1}^{N}\sum_{j=1}^{N}w_{i}w_{j}\Gamma_{t}^{u}(x_{i},x_{j})\theta_{x_{i}}(t)\theta_{x_{j}}(t)\\
 & +2\sum_{i=1}^{N}\nu_{t}^{i}w_{i}\bigg(\Lambda_{t}^{u}(x_{i})-\sum_{j=1}^{N}w_{j}\Gamma_{t}^{u}(x_{i},x_{j})\theta_{x_{j}}(t)\bigg)+\sum_{i,j=1}^{N}w_{i}w_{j}\Gamma_{t}^{u}(x_{i},x_{j})\nu_{t}^{i}\nu_{t}^{j}\bigg)\\
:= & \exp(A_{t}^{u;\,N}+2\sum_{i=1}^{N}B_{t}^{u;\,i}\:\nu_{t}^{i}+\sum_{i=1}^{N}\sum_{j=1}^{N}C_{t}^{u;\,ij}\:\nu_{t}^{i}\nu_{t}^{j})
\end{align*}
with 
\begin{align*}
A_{t}^{u;\,N} & :=\Theta_{t}^{u}-2\sum_{i=1}^{N}w_{i}\Lambda_{t}^{u}(x_{i})\theta_{x_{i}}(t)+\sum_{i=1}^{N}\sum_{j=1}^{N}w_{i}w_{j}\Gamma_{t}^{u}(x_{i},x_{j})\theta_{x_{i}}(t)\theta_{x_{j}}(t),\\
B_{t}^{u;\,i} & :=w_{i}\bigg(\Lambda_{t}^{u}(x_{i})-\sum_{j=1}^{N}w_{j}\Gamma_{t}^{u}(x_{i},x_{j})\theta_{x_{j}}(t)\bigg),\:i=1,...,N,\\
C_{t}^{u;\,ij} & :=w_{i}w_{j}\Gamma_{t}^{u}(x_{i},x_{j}),\:i,j=1,...,N.
\end{align*}
Using Proposition \ref{prop:riccati_ODE_last}, we have that 
\begin{align*}
\dot{C}_{t}^{u;\,ij}= & w_{i}w_{j}\dot{\Gamma}_{t}^{u}(x_{i},x_{j})\\
= & w_{i}w_{j}\bigg((x_{i}+x_{j})\Gamma_{t}^{u}(x_{i},x_{j})-a^{u}-2\eta_{\nu}^{2}\sum_{k=1}^{N}\sum_{l=1}^{N}w_{k}w_{l}\Gamma_{t}^{u}(x_{i},x_{k})\Gamma_{t}^{u}(x_{j},x_{l})\bigg)\\
 & -b^{u}\bigg(\sum_{k=1}^{N}w_{k}\Gamma_{t}^{u}(x_{i},x_{k})+\sum_{k=1}^{N}w_{k}\Gamma_{t}^{u}(x_{k},x_{j})\bigg)\\
= & (x_{i}+x_{j})C_{t}^{u;\,ij}-w_{i}w_{j}a^{u}-2\eta_{\nu}^{2}\sum_{k=1}^{N}\sum_{l=1}^{N}C_{t}^{u;\,ik}C_{t}^{u;\,jl}-b^{u}\sum_{k=1}^{N}\bigg(w_{j}C_{t}^{u;\,ik}+w_{i}C_{t}^{u;\,kj}\bigg).
\end{align*}
Moreover, after fastidious calculus, we end up with
\begin{align*}
\dot{B}_{t}^{u;\,i}= & x_{i}B_{t}^{u;\,i}-a^{u}w_{i}\bigg(\nu_{0}+\rho_{Ir}\eta_{r}B_{G_{r}}(t,T)\bigg)-2\eta_{\nu}^{2}\sum_{j,k=1}^{N}C_{t}^{u;\,ij}B_{t}^{u;\,k}\\
 & -b^{u}\bigg(\sum_{j=1}^{N}\bigg(w_{i}B_{t}^{u;\,j}+\nu_{0}C_{t}^{u;\,ij}\bigg)-\sum_{j=1}^{N}C_{t}^{u;\,ij}\bigg(\theta(t)+u\eta_{\nu}\rho_{\nu r}\eta_{r}B_{G_{r}}(t,T)\bigg),\:t<T,\:i=1,...,N,
\end{align*}
and 
\begin{align*}
\dot{A}_{t}^{u;\,N} & =-a^{u}\bigg(\nu_{0}^{2}+\eta_{r}^{2}B_{G_{r}}(t,T)^{2}-2\nu_{0}\rho_{Ir}\eta_{r}B_{G_{r}}(t,T)\bigg)\\
 & -2\sum_{i=1}^{N}B_{t}^{u;\,i}\bigg(\theta(t)+u\eta_{\nu}\rho_{\nu r}\eta_{r}B_{G_{r}}(t,T)+b^{u}\nu_{0}\bigg)-\eta_{\nu}^{2}\sum_{i,j=1}^{N}(2B_{t}^{u;\,i}B_{t}^{u;\,j}+C_{t}^{u;\,ij}).
\end{align*}
\end{proof}

