\begin{equation}
\begin{aligned}
\textsf{P}_{\rm con}( s_t | \{s_{t-1}\}) = \sum^3_{j=1}\mathcal{P}_{j}(s_t | \mathcal{X}_j);
\label{conversation_loss_1}
\end{aligned}
\end{equation}
