\section{Preliminaries}
This section introduces fundamental definitions, preliminary lemmas, and key theorems that will underpin the theoretical development in the following sections.

The definitions presented here are primarily based on the framework established by Bohner et al. \cite{Peterson}.

A time scale \(\mathbb{T}\) is any closed subset of the real numbers \(\mathbb{R}\). The forward and backward jump operators, \(\sigma\) and \(\rho\), map \(\mathbb{T}\) into itself and are defined by
\[
\sigma(t) = \inf\{ s \in \mathbb{T} : s > t \}, \quad \rho(t) = \sup\{ s \in \mathbb{T} : s < t \},
\]
with the conventions \(\inf \emptyset := \sup \mathbb{T}\) and \(\sup \emptyset := \inf \mathbb{T}\). A point \( t \in \mathbb{T} \) is classified as left-dense if \( t > \inf \mathbb{T} \) and \(\rho(t) = t\); left-scattered if \(\rho(t) < t\); right-dense if \( t < \sup \mathbb{T} \) and \(\sigma(t) = t\); and right-scattered if \(\sigma(t) > t\). If \(\mathbb{T}\) has a maximum point \( M \) that is left-scattered, then define \(\mathbb{T}^{\kappa} := \mathbb{T} \setminus \{M\}\); otherwise, \(\mathbb{T}^{\kappa} := \mathbb{T}\). The forward graininess function \(\mu : \mathbb{T} \to [0, \infty)\) is given by
\[
\mu(t) = \sigma(t) - t,
\]
representing the distance to the next point in the time scale.

For a function $f : \mathbb{T} \to \mathbb{R}$ and a point $t \in \mathbb{T}^{\kappa}$, the delta derivative of $f$ at $t$, denoted by $\Delta f(t)$, is defined as the number (if it exists) such that for any $\varepsilon > 0$, there is a neighborhood $U$ of $t$ satisfying
$$|[f(\sigma(t)) - f(s)] - \Delta f(t)[\sigma(t) - s]| \leq \varepsilon |\sigma(t) - s|$$
for all $s \in U$.
\begin{theorem}\label{nabladerrule}\cite{Peterson}
Let \( f: \mathbb{T} \to \mathbb{R} \) be a function, and let \( t \in \mathbb{T}^\kappa \) be a point. The following statements hold:
\begin{enumerate}[label=(\roman*)]
\item If \( f \) is $\Delta$-differentiable at \( t \), then \( f \) is continuous at \( t \).
\item If \( f \) is continuous at \( t \) and \( t \) is right-scattered, then \( f \) is $\Delta$-differentiable at \( t \) with
\begin{equation*}
\Delta f(t) = \frac{f(\sigma(t)) - f(t)}{\mu(t)}.
\end{equation*}
\item If \( t \) is right-dense, then \( f \) is $\Delta$-differentiable at \( t \) if and only if the limit
$$\lim_{s \to t} \frac{f(s) - f(t)}{s - t}$$
exists. In this case, we have
$$\Delta f(t) = \lim_{s \to t} \frac{f(s) - f(t)}{s - t}.$$
\item If \( f \) is $\Delta$-differentiable at \( t \), then
\begin{equation}
f(\sigma(t)) = f(t) + \mu(t) \Delta f(t).
\end{equation}
\end{enumerate}
\end{theorem}


\begin{definition}\cite{Zadeh}
A fuzzy set \( u \) on a universe \( U \) is characterized by a membership function \( u : U \to [0,1] \), where \( u(x) \) indicates the membership grade of element \( x \) in \( u \).
\end{definition}

\begin{definition}\cite{Negoita}
Given a fuzzy set \( u: U \to [0,1] \), its \(\alpha\)-level set for \( \alpha \in (0,1] \) is defined as
\[
[u]_\alpha = \{ x \in U : u(x) \geq \alpha \},
\]
while the support, or \( 0 \)-level set, is given by
\[
[u]_0 = \overline{\{ x \in U : u(x) > 0 \}},
\]
where the bar denotes the closure.
\end{definition}

\begin{definition}\cite{Bedebook}
A fuzzy number \( u: \mathbb{R} \to [0,1] \) satisfies the following:
\begin{enumerate}
    \item \textbf{Normality:} There exists \( x_0 \in \mathbb{R} \) with \( u(x_0) = 1 \).
    \item \textbf{Fuzzy Convexity:} For any \( t \in [0,1] \) and \( x,y \in \mathbb{R} \),
    \[
    u(tx + (1-t)y) \geq \min\{u(x), u(y)\}.
    \]
    \item \textbf{Upper semicontinuity:} For each \( x_0 \in \mathbb{R} \) and any \( \varepsilon > 0 \), there exists \( \delta > 0 \) such that
\[
u(x)-u(x_0)< \varepsilon \quad \text{whenever} \quad |x - x_0| < \delta.
\]
    \item \textbf{Compact Support:} The support of \( u \) is compact.
\end{enumerate}
\end{definition}

The set of all fuzzy numbers is denoted by \( \mathbb{R}_{\mathcal{F}} \).

\begin{theorem}\cite{Bedebook}\label{Bede1}
Let \( u^-, u^+ : [0,1] \to \mathbb{R} \) be bounded functions where \( u^- \) is non-decreasing, left-continuous on \((0,1]\), and right-continuous at 0; similarly, \( u^+ \) is non-increasing, left-continuous on \((0,1]\), and right-continuous at 0. Assume \( u^-_1 \leq u^+_1 \). Then there is a unique fuzzy number \( u \in \mathbb{R}_{\mathcal{F}} \) with \(\alpha\)-level sets \( [u]_\alpha = [u^-_\alpha, u^+_\alpha] \).
\end{theorem}

\begin{definition}\cite{Stef}
The generalized Hukuhara difference (\(gH\)-difference) between fuzzy numbers \( u \) and \( v \) is the fuzzy number \( \omega \), if it exists, such that
\[
u \ominus_{gH} v = \omega \quad \text{iff} \quad u = v + \omega \quad \text{or} \quad v = u + (-1)\omega.
\]
\end{definition}

\begin{remark}\cite{Stef,Bede}
For the existence of \( \omega = u \ominus_{gH} v \), one of the following must hold:

\textbf{Case (i):}  
\begin{itemize}
    \item \( \omega^-_\alpha = u^-_\alpha - v^-_\alpha \) and \( \omega^+_\alpha = u^+_\alpha - v^+_\alpha \) for all \(\alpha \in [0,1]\),
    \item \( \omega^-_\alpha \) is non-decreasing and \( \omega^+_\alpha \) is non-increasing with \( \omega^-_\alpha \leq \omega^+_\alpha \) for all \(\alpha \in [0,1]\).
\end{itemize}

\textbf{Case (ii):}  
\begin{itemize}
    \item \( \omega^-_\alpha = u^+_\alpha - v^+_\alpha \) and \( \omega^+_\alpha = u^-_\alpha - v^-_\alpha \) for all \(\alpha \in [0,1]\),
    \item \( \omega^-_\alpha \) is non-decreasing and \( \omega^+_\alpha \) is non-increasing with \( \omega^-_\alpha \leq \omega^+_\alpha \) for all \(\alpha \in [0,1]\).
\end{itemize}
\end{remark}

\begin{theorem}\cite{Stef, Bede}\label{prop2}
If \( \omega = u \ominus_{gH} v \) exists for \( u,v \in \mathbb{R}_{\mathcal{F} } \), then the \(\alpha\)-level sets of \(\omega\) satisfy
\[
[\omega]_\alpha = [\omega^-_\alpha, \omega^+_\alpha],
\]
where
\[
\omega^-_\alpha = \min\{ u^-_\alpha - v^-_\alpha, u^+_\alpha - v^+_\alpha \}, \quad \omega^+_\alpha = \max\{ u^-_\alpha - v^-_\alpha, u^+_\alpha - v^+_\alpha \}.
\]
\end{theorem}

\begin{lemma}\cite{Cano}
Given fuzzy numbers \( u,v \) with an existing \( u \ominus_{gH} v \), then for any scalar \( a \in \mathbb{R} \), the difference \( a u \ominus_{gH} a v \) also exists and satisfies
\[
a (u \ominus_{gH} v) = a u \ominus_{gH} a v.
\]
\end{lemma}

The Hausdorff metric between fuzzy numbers, essential in applications such as clustering, pattern recognition, and decision-making, is defined as follows. This metric generalizes the classical Hausdorff distance to handle the uncertainty intrinsic to fuzzy numbers, thereby providing a reliable measure of similarity between fuzzy quantities.












\begin{definition}\cite{Diamond2} \label{def12}
	The Hausdorff metric $D:\mathbb{R}_{\mathcal{F} }\times \mathbb{R}_{\mathcal{F} }
    \rightarrow 
	[0,\infty)$ is defined by
    \begin{equation*}
    \begin{split}
	D(u,v)&=\sup_{\alpha\in \lbrack 0,1]}D_H([u]_{\alpha},[v]_{\alpha})\\
    &=\sup_{\alpha\in \lbrack 0,1]}\max \left\{ \left\vert
	u_{\alpha}^{-}-v_{\alpha}^{-}\right\vert ,\left\vert u_{\alpha}^{+}-v_{\alpha}^{+}\right\vert
	\right\}, 
    \end{split}
    \end{equation*}
	where $[u]_{\alpha}=[u_{\alpha}^{-},u_{\alpha}^{+}]$, $[v]_{\alpha}=[v_{\alpha}^{-},v_{\alpha}^{+}]$.
\end{definition}


