\begin{definition}\label{rightcomp}
Let $f_1, f_2:(t_0,t_0+\delta)\cap{\mathbb{T}} \to \mathbb{R}$ be two real valued functions, where $\delta > 0$ and $t_0 \in \mathbb{T}$ is a right-dense point. We say that $f_1$ and $f_2$ are \textit{right complementary} at $t_0$ if they satisfy the following two conditions:
\begin{itemize}
    \item[(i)] $
    \mathcal{C}_{R(t_0)}(f_1) = \mathcal{C}_{R(t_0)}(f_2) = \{\underline{a},\overline{a}\},\,\text{where}\,\, \underline{a},\overline{a}\in \mathbb{R},\,\underline{a} <\overline{a}.
    $
    \item[(ii)] The following limits hold:
    \[
    \lim_{\substack{h \to 0^+\\ h\in\tilde{\mathbb{T}}}}\min\{f_1(t_0 + h), f_2(t_0 + h)\} =\underline{a},
    \]
    \[
     \lim_{\substack{h \to 0^+\\ h\in\tilde{\mathbb{T}}}} \max\{f_1(t_0 + h), f_2(t_0 + h)\} =\overline{a}.\]
    \end{itemize}

Similarly, the functions \( f_1 \) and \( f_2 \) are said to be \emph{left complementary} at \(t_0 \) if they fulfill the analogous criteria at \( t_0 \).
\end{definition}
\begin{definition}\label{defder}\cite{Mert1}
Let \( f: \mathbb{T} \to \mathbb{R}_{\cal{F}} \) be a fuzzy function, and let \( t_0 \in \mathbb{T}^{\kappa} \). The generalized Hukuhara \(\Delta\)-derivative of \( f \) at \( t_0 \), denoted by \( \Delta_{gH} f(t_0) \), is defined as the element of \( \mathbb{R}_{\cal{F}} \) (if it exists) with the property that for any \( \varepsilon > 0 \), there exists a neighborhood \( U_{\mathbb{T}}=(t_0- \delta, t_0 + \delta) \cap \mathbb{T}\) 
of \( t_0\)  for some \( \delta > 0 \) such that the following inequalities hold:
\begin{equation*}
D\left(f(t_0+h) \ominus_{gH} f(\sigma(t_0)), \Delta_{gH} f(t_0)(h - \mu(t_0))\right) \leq \varepsilon |h - \mu(t_0)|,
\end{equation*}
\begin{equation*}
D\left(f(\sigma(t_0)) \ominus_{gH} f(t_0-h), \Delta_{gH} f(t_0)(h + \mu(t_0))\right) \leq \varepsilon |h + \mu(t_0)|
\end{equation*}
for all \( t_0 - h, t_0 + h \in U_{\mathbb{T}} \) with \( 0 \leq h < \delta \).


It is said that \( f \) is \(\Delta_{gH}\)-differentiable at \( t_0 \) if the \(\Delta_{gH}\)-derivative of \( f \) exists at \( t_0 \). Furthermore, \( f \) is called  \(\Delta_{gH}\)-differentiable on \( \mathbb{T}^{\kappa} \) if the \(\Delta_{gH}\)-derivative of $f$ exists at every point \( t_0 \in \mathbb{T}^{\kappa} \). In this context, the function \( \Delta_{gH} f: \mathbb{T}^{\kappa} \to \mathbb{R}_{\cal{F}} \) is referred to as the \(\Delta_{gH}\)-derivative of \( f \) over the time scale \( \mathbb{T}^{\kappa} \).
\end{definition}
The generalized Hukuhara 
$\Delta$-derivative can alternatively be defined through a limit-based formulation, as described below.
\begin{definition}\label{defderlim}\cite{Mert1}
A fuzzy function \( f: \mathbb{T} \to \mathbb{R}_{\cal{F}} \) is said to be \(\Delta_{gH}\)-differentiable at \( t_0 \in \mathbb{T}^{\kappa} \) if there exists an element \( \Delta_{gH} f(t_0) \in \mathbb{R}_{\cal{F}} \) such that
\[
\Delta_{gH} f(t_0) = \lim_{\substack{h \to 0\\ h\in\tilde{\mathbb{T}}}}\frac{1}{h - \mu(t_0)} \left[ f(t_0+h)\ominus_{gH} f(\sigma(t
_0))\right].
\]
\end{definition}

As introduced in \cite{Mert1}, a fuzzy number-valued function \( f: \mathbb{T} \to \mathbb{R}_{\mathcal{F}} \) can be represented, for each \( \alpha \in [0,1] \), by an interval-valued function \( f_{\alpha}(t) = [f(t)]_{\alpha} \in \mathcal{K}_C \), where \( \mathcal{K}_C \) denotes the set of all bounded closed intervals in \( \mathbb{R} \). Each such interval  can be expressed as
\[
f_{\alpha}(t) = [f_{\alpha}^{-}(t), f_{\alpha}^{+}(t)],
\]
with \( f_{\alpha}^{-} \) and \( f_{\alpha}^{+} \) denoting the real valued lower and upper endpoint functions, respectively, defined on the time scale \( \mathbb{T} \). In that work, the authors have investigated the connection between the \(\Delta_{gH}\)-differentiability of the fuzzy function \( f \) and the \(\Delta_{gH}\)-differentiability of its associated family of interval-valued functions \(  f_{\alpha} \), and have established the following theorem.

\begin{theorem}\label{Thmlevel}\cite{Mert1}
If \( f: \mathbb{T} \to \mathbb{R}_{\cal{F}} \) is \(\Delta_{gH}\)-differentiable at \( t_0\in \mathbb{T}^{\kappa} \), then the family of interval-valued functions \( f_{\alpha}: \mathbb{T} \to \mathcal{K}_C \) is \(\Delta_{gH}\)-differentiable at \( t_0 \) uniformly in \( \alpha \in [0,1] \). Furthermore, the \(\Delta_{gH}\)-derivative of \( f_{\alpha} \) at \( t_0 \) is given by
\[
\Delta_{gH} f_{\alpha}(t_0) = [\Delta_{gH} f(t
_0)]_{\alpha}
\]
for all \( \alpha \in [0,1] \).
\end{theorem}

It can be readily shown that the converse of the above theorem also holds.


\begin{theorem}\label{reverse}
Let \( f: \mathbb{T} \to \mathbb{R}_{\mathcal{F}} \) be a fuzzy number-valued function, and let \( t_0 \in \mathbb{T}^{\kappa} \) be a point. Suppose that, for every \( \alpha \in [0,1] \),  the associated interval-valued functions \( f_{\alpha}(t) = [f(t)]_{\alpha} \) are \(\Delta_{gH}\)-differentiable at \( t_0 \), uniformly in \( \alpha \). Furthermore, assume that the generalized Hukuhara difference \( f(t_0 + h) \ominus_{gH} f(\sigma(t_0)) \) exists for all \( h \in \tilde{\mathbb{T}} \) such that \( |h| < \delta \), for some sufficiently small \( \delta > 0 \). Then the function  $f$ is \(\Delta_{gH}\)-differentiable at \( t_0 \).
\end{theorem}

\begin{remark}\label{Rmk}
The conclusions of Theorems~\ref{Thmlevel} and~\ref{reverse} remain valid for both the right-hand and left-hand \(\Delta_{gH}\)-derivatives.
\end{remark}

The following results extend Theorem~\ref{nabladerrule}, which concerns the \(\Delta\)-derivative of real-valued functions on time scales, to the more general setting of the \(\Delta_{gH}\)-derivative for fuzzy number-valued functions defined on a time scale.


\begin{theorem}\label{derivative}(\cite{Mert1})
Let \( f: \mathbb{T} \to \mathbb{R}_{\cal{F}} \) be a fuzzy number-valued function, and let \( t_0 \in \mathbb{T}^{\kappa} \) be a point. Then the following results hold:
\begin{enumerate}[label=(\roman*)]
\item If the \(\Delta_{gH}\)-derivative of \( f \) exists at \( t_0 \), then it is unique.
\item If $f$ is \(\Delta_{gH}\)-differentiable at $t_0,$ then $f$ is continuous at $t_0.$
\item If \( f \) is continuous at \( t_0 \) and \( t_0 \) is right-scattered, then \( f \) is \(\Delta_{gH}\)-differentiable at \( t_0 \), and the derivative is given by
\[
\Delta_{gH} f(t_0) = \frac{f(\sigma(t_0)) \ominus_{gH} f(t_0)}{\mu(t_0)}.
\]
\item If \( t_0 \) is right-dense, then \( f \) is \(\Delta_{gH}\)-differentiable at \( t_0 \) if and only if the following two limits exist:
\[
\lim_{\substack{h \to 0^+\\ h\in\tilde{\mathbb{T}}}} \frac{f(t_0+h) \ominus_{gH} f(t_0)}{h} \quad \text{and} \quad \lim_{\substack{h \to 0^+\\ h\in\tilde{\mathbb{T}}}}\frac{f(t_0) \ominus_{gH} f(t_0-h)}{h},
\]
and the equality
\[
\lim_{\substack{h \to 0^+\\ h\in\tilde{\mathbb{T}}}} \frac{f(t_0+h) \ominus_{gH} f(t_0)}{h} = \lim_{\substack{h \to 0^+\\ h\in\tilde{\mathbb{T}}}} \frac{f(t_0) \ominus_{gH} f(t_0-h)}{h} = \Delta_{gH} f(t_0)
\]
holds.
\end{enumerate}
\end{theorem}
\begin{theorem}\cite{Mert1}\label{rhothm}
Let \( f : \mathbb{T} \to \mathbb{R}_{\cal{F}} \) be a fuzzy number-valued function, and let \( t_0 \in \mathbb{T}^{\kappa} \) be a point. If \( f \) is \( \Delta_{gH} \)-differentiable at \( t_0 \), then the following identities hold:
\[
f(\sigma(t_0)) = f(t_0) \oplus \mu(t_0) \Delta_{gH} f(t_0),
\]
or
\[
f(t_0) = f(\sigma(t_0)) \oplus (-1) \mu(t_0) \Delta_{gH} f(t_0).
\]
\end{theorem}
\section{Main Results}
In this section, we provide a detailed analysis of the generalized Hukuhara 
\(\Delta\)-differentiability for fuzzy number-valued functions defined on time scales, expressed in terms of their associated lower and upper endpoint representations.


Our analysis is restricted to the left \(\Delta\)-derivative at points that are simultaneously right-scattered and left-dense, and the right \(\Delta\)-derivative at points that are both left-scattered and right-dense, within the time scale \(\mathbb{T}^{\kappa}\).

For the sake of notational simplicity, we introduce the following definitions, which will be used throughout the paper as needed. For each \(\alpha \in [0,1]\),  we define
\[
\lim_{\substack{h \to 0^+\\ h \in \tilde{\mathbb{T}}}} \min\left\{ \varphi_{f_{\alpha}^{-}}(h), \varphi_{f_{\alpha}^{+}}(h) \right\}:=a_{\alpha}:=\lim_{\substack{h \to 0^-\\ h \in \tilde{\mathbb{T}}}} \min\left\{ \varphi_{f_{\alpha}^{-}}(h), \varphi_{f_{\alpha}^{+}}(h) \right\},\]
\[
\lim_{\substack{h \to 0^+\\ h \in \tilde{\mathbb{T}}}} \max\left\{ \varphi_{f_{\alpha}^{-}}(h), \varphi_{f_{\alpha}^{+}}(h) \right\}:=b_{\alpha}:=\lim_{\substack{h \to 0^-\\ h \in \tilde{\mathbb{T}}}} \max\left\{ \varphi_{f_{\alpha}^{-}}(h), \varphi_{f_{\alpha}^{+}}(h) \right\} .
\]

These expressions, denoted by \(a_{\alpha}\) and \(b_{\alpha}\), will appear frequently in the analysis that follows. We encourage the reader to keep this notation in mind, as it contributes to the clarity and consistency of the exposition.


%We will refer to these expressions as \(a_{\alpha}\) and \(b_{\alpha}\), respectively, in several parts of the paper. The reader is encouraged to keep this shorthand in mind, as it will be used repeatedly for clarity and conciseness.
\begin{theorem}\label{right1}
Let \( f:\mathbb{T} \to \mathbb{R}_{\mathcal{F}} \) be a fuzzy number-valued function, and let \( t_0 \in \mathbb{T}^{\kappa} \) be a right-dense point. Suppose that \( f \) is right \(\Delta_{gH}\)-differentiable at \( t_0 \). Then, one of the following two cases must hold:

\begin{enumerate}[label=(\roman*)]
\item The right delta derivatives \( \Delta_{+} f_{\alpha}^{-}(t_0) \) and \( \Delta_{+} f_{\alpha}^{+}(t_0) \)  exist uniformly with respect to  \( \alpha \in [0,1] \). Hence, the right \(\Delta_{gH}\)-derivative of \( f \) at \( t_0 \) takes the form
\[
[\Delta_{gH_+} f(t_0)]_{\alpha} = \left[ \Delta_{+} f_{\alpha}^{-}(t_0), \Delta_{+} f_{\alpha}^{+}(t_0) \right] \]\quad \text{or} \quad
\[[\Delta_{gH_+} f(t_0)]_{\alpha} = \left[ \Delta_{+} f_{\alpha}^{+}(t_0), \Delta_{+} f_{\alpha}^{-}(t_0) \right]
\]
for all $\alpha.$%\( \alpha \in [0,1] \).

\item There exists a threshold \( \alpha_0 \in (0,1] \) such that, for all \( \alpha \in [\alpha_0,1] \), the right delta derivatives \( \Delta_{+} f_{\alpha}^{-}(t_0) \) and \( \Delta_{+} f_{\alpha}^{+}(t_0) \) exist and are equal, that is,
\[
\Delta_{+} f_{\alpha}^{-}(t_0) = \Delta_{+} f_{\alpha}^{+}(t_0) = a_{\alpha} = b_{\alpha},
\]
and this existence is uniform with respect to \( \alpha \). 

\noindent On the other hand, for \( \alpha \in [0,\alpha_0) \), the functions \( f_{\alpha}^{-} \) and \( f_{\alpha}^{+} \) are not right delta differentiable at \( t_0 \), but their associated slope functions \( \varphi_{f_{\alpha}^{-}} \) and \( \varphi_{f_{\alpha}^{+}} \) are right complementary at zero. That is, there exist constants \( a_{\alpha} < b_{\alpha} \) such that
\[
C_{R(0)}(\varphi_{f_{\alpha}^{-}}) = C_{R(0)}(\varphi_{f_{\alpha}^{+}}) = \{a_{\alpha}, b_{\alpha}\},
\]
and the limits 
\[
\lim_{\substack{h \to 0^+ \\ h \in \tilde{\mathbb{T}}}} \min\left\{ \varphi_{f_{\alpha}^{-}}(h), \varphi_{f_{\alpha}^{+}}(h) \right\} = a_{\alpha}, \quad
\lim_{\substack{h \to 0^+ \\ h \in \tilde{\mathbb{T}}}} \max\left\{ \varphi_{f_{\alpha}^{-}}(h), \varphi_{f_{\alpha}^{+}}(h) \right\} = b_{\alpha}\]
exist uniformly with respect to  $\alpha$. 

Consequently, the right \(\Delta_{gH}\)-derivative of \( f \) at \( t_0 \) is given by
\[
[\Delta_{gH_+} f(t_0)]_{\alpha} = [a_{\alpha}, b_{\alpha}]
\]
for all \( \alpha \in [0,1] \).
\end{enumerate}
\end{theorem}
\begin{proof}
Suppose that the function \( f \) is right \(\Delta_{gH}\)-differentiable at a right-dense point $t_0\in\mathbb{T}^{\kappa}.$ We consider two possible cases.


\textbf{Case 1:} The value of \( \Delta_{gH_{+}} f(t_0) \) is a crisp (real)  number.

For any \( h > 0 \) such that \( h \in \tilde{\mathbb{T}}\),  the following inequalities hold naturally: 
\begin{equation}\label{E1S}
\min\left\{ \varphi_{f_{\alpha }^{-}}(h), \varphi_{f_{\alpha }^{+}}(h) \right\}\leq \varphi_{f_{\alpha }^{-}}(h)\leq \max\left\{\varphi_{f_{\alpha }^{-}}(h), \varphi_{f_{\alpha }^{+}}(h) \right\},
\end{equation}
\begin{equation}\label{E2S}
\min\left\{ \varphi_{f_{\alpha }^{-}}(h), \varphi_{f_{\alpha }^{+}}(h) \right\}\leq \varphi_{f_{\alpha }^{+}}(h)\leq \max\left\{\varphi_{f_{\alpha }^{-}}(h), \varphi_{f_{\alpha }^{+}}(h) \right\}.
\end{equation}
Since  the function \(f \) is   assumed to be right \(\Delta_{gH}\)-differentiable at  the point \( t_0 \), it follows from  Definition \ref{defderlim} and Theorem \ref{prop2} %Definition \ref{defderlim}
that, for each $\alpha\in[0,1],$ 
the level set of the right $\Delta_{gH}$ derivative is given by
\begin{align*}
[\Delta_{gH_+} f(t_0)]_{\alpha}
&= \lim_{\substack{h \to 0^+\\ h\in\tilde{\mathbb{T}}}} \frac{1}{h} \left( [f(t_0 + h)]_{\alpha} \ominus_{gH} [f(t_0)]_{\alpha} \right) \notag \\
&= \lim_{\substack{h \to 0^+\\ h\in\tilde{\mathbb{T}}}} \frac{1}{h} \left[
\min\left\{ f_{\alpha}^{-}(t_0 + h) - f_{\alpha}^{-}(t_0),\,
           f_{\alpha}^{+}(t_0 + h) - f_{\alpha}^{+}(t_0) \right\}, \right. \notag \\
&\qquad\qquad\qquad\left.
\max\left\{ f_{\alpha}^{-}(t_0 + h) - f_{\alpha}^{-}(t_0),\,
           f_{\alpha}^{+}(t_0 + h) - f_{\alpha}^{+}(t_0) \right\} \right] \notag \\
&= \lim_{\substack{h \to 0^+\\ h\in\tilde{\mathbb{T}}}} \left[
\min\left\{ \frac{f_{\alpha}^{-}(t_0 + h) - f_{\alpha}^{-}(t_0)}{h},\,
           \frac{f_{\alpha}^{+}(t_0 + h) - f_{\alpha}^{+}(t_0)}{h} \right\}, \right. \notag \\
&\qquad\qquad\qquad\left.
\max\left\{ \frac{f_{\alpha}^{-}(t_0 + h) - f_{\alpha}^{-}(t_0)}{h},\,
           \frac{f_{\alpha}^{+}(t_0 + h) - f_{\alpha}^{+}(t_0)}{h} \right\} \right] \notag \\
    &= \left[
\lim_{\substack{h \to 0^+\\ h\in\tilde{\mathbb{T}}}}\min\left\{ \varphi_{f_{\alpha }^{-}}(h), \varphi_{f_{\alpha }^{+}}(h) \right\},\,
\lim_{\substack{h \to 0^+\\ h\in\tilde{\mathbb{T}}}} \max\left\{ \varphi_{f_{\alpha }^{-}}(h), \varphi_{f_{\alpha }^{+}}(h) \right\}
\right].
%&=[a_{\alpha}, b_{\alpha}].\label{EEE}
\end{align*}
The fact that \( \Delta_{gH_{+}} f(t_0) \) is a crisp number implies that the left and right endpoints of the \(\alpha\)-level set interval are identical. Hence, for each \( \alpha \in [0,1] \), we have
%\[[a_{\alpha}, b_{\alpha}]=
%\Delta_{gH_{+}} f(t_0).\]
\[\lim_{\substack{h \to 0^+ \\ h \in \tilde{\mathbb{T}}}} \min\left\{ \varphi_{f_\alpha^{-}}(h), \varphi_{f_\alpha^{+}}(h) \right\}
=
\lim_{\substack{h \to 0^+ \\ h \in \tilde{\mathbb{T}}}} \max\left\{ \varphi_{f_\alpha^{-}}(h), \varphi_{f_\alpha^{+}}(h) \right\}
=
\Delta_{gH_{+}} f(t_0).
\]
%Now, since \( \Delta_{gH_{+}} f(t_0) \) is a crisp number,the lower and upper bounds of the interval described above must be equal. That is, for all $\alpha\in[0,1],$
%\begin{equation}\label{EEEEE}
% \lim_{\substack{h \to 0^+\\ h\in\tilde{\mathbb{T}}}}\min\left\{ \varphi_{f_{\alpha }^{-}}(h), \varphi_{f_{\alpha }^{+}}(h) \right\} =  \lim_{\substack{h \to 0^+\\ h\in\tilde{\mathbb{T}}}}\max\left\{ \varphi_{f_{\alpha }^{-}}(h), \varphi_{f_{\alpha }^{+}}(h) \right\}=\Delta_{gH_{+}} f(t_0). 
%\end{equation}
By applying the Squeeze Theorem along with inequalities \eqref{E1S} and \eqref{E2S}, we conclude that the right-hand limits of both slope functions exist and are equal. Specifically,
\[
\Delta_{+} f_{\alpha }^{-}(t_0)=\lim_{\substack{h \to 0^+\\ h\in\tilde{\mathbb{T}}}} \varphi_{f_{\alpha }^{-}}(h) = \Delta_{gH_{+}} f(t_0),
\]
\[
\Delta_{+} f_{\alpha }^{+}(t_0)=\lim_{\substack{h \to 0^+\\ h\in\tilde{\mathbb{T}}}} \varphi_{f_{\alpha }^{+}}(h) =\Delta_{gH_{+}} f(t_0),
\]
for all $\alpha\in[0,1].$ 

\noindent Combining this result  with the definition of the Hausdorff metric, it follows that both \( f_{\alpha}^{-} \) and \( f_{\alpha}^{+} \) are right delta differentiable at \( t_0 \) for every \( \alpha \in [0,1] \), and this differentiability is uniform in \( \alpha \). Consequently, the level set  of the right  \(\Delta_{gH}\)-derivative is given by
 \[
    [\Delta_{gH_+} f(t_0)]_{\alpha} = \Delta_{gH_{+}} f(t_0)
    %\left[ \min\left\{\Delta_{+} f_{\alpha }^{-}(t_0), \Delta_{+} f_{\alpha }^{+}(t_0) \right\}, \max\left\{ \Delta_{+} f_{\alpha }^{-}(t_0), \Delta_{+} f_{\alpha }^{+}(t_0) \right\} \right]
\]
for all \( \alpha \in [0,1] \).

\textbf{Case 2:}  The value of \( \Delta_{gH_{+}} f(t_0) \) is not a crisp  number.

To analyze this situation, we consider three subcases based on the behavior of the auxiliary functions \( \varphi_{f_{\alpha}^{-}}(h) \) and \( \varphi_{f_{\alpha}^{+}}(h) \).

\textbf{Subcase 1:}  There exists a constant  \( \delta > 0 \) such that for every \( h \in \tilde{\mathbb{T}} \) with \( 0 \leq h < \delta \), the following inequality holds:
\begin{equation*}\label{EQ9}
\operatorname{len}\left( [f(t_0 + h)]_{\alpha} \right) \geq \operatorname{len}\left( [f(t_0)]_{\alpha} \right), \quad \text{for all } \alpha \in [0, 1].
\end{equation*}

\textbf{Subcase 2:} 
There exists  a constant  \( \delta> 0 \) such that for every \( h \in \tilde{\mathbb{T}} \) with \( 0 \leq h < \delta\), the following inequality  holds:
    \begin{equation*}\label{EQ10}
\operatorname{len}\left( [f(t_0 + h)]_{\alpha} \right) \leq \operatorname{len}\left( [f(t_0)]_{\alpha} \right), \quad \text{for all } \alpha \in [0, 1].
\end{equation*}

 \textbf{Subcase 3:}  For every \( n \in \mathbb{N} \), there exist \( h_n, h_n^{\prime} \in \tilde{\mathbb{T}} \) such that \( 0 < h_n, h_n^{\prime} <1/n \), and the following inequalities hold:
\begin{align*}
\operatorname{len}\left( [f(t_0 + h_n)]_{\alpha} \right) &> \operatorname{len}\left( [f(t_0)]_{\alpha} \right), \\
\operatorname{len}\left( [f(t_0 + h_n^{\prime})]_{\alpha} \right) &< \operatorname{len}\left( [f(t_0)]_{\alpha} \right),
\end{align*}
for all \( \alpha \in [0, 1] \).



\textbf{Subcase 1:}  
In this case, the inequality implies that for  sufficiently small   \( h>0 \) within  $\tilde{\mathbb{T}}$, the generalized Hukuhara difference \( f(t_0 + h) \ominus_{gH} f(t_0)\) simplifies to  the classical  Hukuhara difference  \(f(t_0 + h) \ominus_H f(t_0) \). 

Accordingly, we have
\[
\min\left\{ \varphi_{f_{\alpha}^{-}}(h), \varphi_{f_{\alpha}^{+}}(h) \right\} = \varphi_{f_{\alpha}^{-}}(h), \quad 
\max\left\{ \varphi_{f_{\alpha}^{-}}(h), \varphi_{f_{\alpha}^{+}}(h)\right \} = \varphi_{f_{\alpha}^{+}}(h)
\]
for all \( \alpha \in [0,1]. \) %and   sufficiently small 
%$h>0$ in $\tilde{\mathbb{T}}.$


Since  the function \( f \) is right \(\Delta_{gH}\)-differentiable at \( t_0 \), it follows that
\[
a_{\alpha} = \lim_{\substack{h \to 0^+\\ h\in\tilde{\mathbb{T}}}}\varphi_{f_{\alpha}^{-}}(h) = \Delta_{+} f_{\alpha}^{-}(t_0),
\]
\[
b_{\alpha} = \lim_{\substack{h \to 0^+\\ h\in\tilde{\mathbb{T}}}} \varphi_{f_{\alpha}^{+}}(h) = \Delta_{+} f_{\alpha}^{+}(t_0),
\]
for every \( \alpha \in [0,1] \). Therefore, both \( f_{\alpha}^{-} \) and \( f_{\alpha}^{+} \) are right delta differentiable at \( t_0 \), uniformly in  \( \alpha \), and we obtain
\[
    [\Delta_{gH_+} f(t_0)]_{\alpha} = \left[ \Delta_{+} f_{\alpha }^{-}(t_0),  \Delta_{+} f_{\alpha }^{+}(t_0) \right]\] 
for all \( \alpha \in [0,1] \).   
%\[
%[\Delta_{gH_+} f(t_0)]_{\alpha} %= 
%\left[ \min\left\{ \Delta_{+} f_{\alpha}^{-}(t_0), \Delta_{+} f_{\alpha}^{+}(t_0) \right\}, 
%\max\left\{ \Delta_{+} f_{\alpha}^{-}(t_0), \Delta_{+} f_{\alpha}^{+}(t_0) \right\} \right].
%\]

\textbf{Subcase 2:}  
%The proof follows analogously to Subcase (I), with reversed inequalities and the same conclusion regarding differentiability.
%For Subcase (II), the proof is similar to Subcase (I).
The argument proceeds similarly to Subcase 1, with the roles of \( f_{\alpha}^{-} \) and \( f_{\alpha}^{+} \) interchanged due to the reversed inequality. As a result, we have
\[
[\Delta_{gH_+} f(t_0)]_{\alpha} = \left[ \Delta_{+} f_{\alpha}^{+}(t_0), \Delta_{+} f_{\alpha}^{-}(t_0) \right]
\]
for all \( \alpha \in [0,1] \). 

\textbf{Subcase 3:}  
In this case, as \( h \to 0^+ \) with \( h \in \tilde{\mathbb{T}} \), the length of the \(\alpha\)-level sets of \( f(t_0 + h) \) oscillates, taking values both greater and smaller than that of \( [f(t_0)]_{\alpha} \), for all \( \alpha \in [0,1] \). Nevertheless, under the assumption that \( f \) is right \(\Delta_{gH}\)-differentiable at \( t_0 \), it follows that for every \( \alpha \in [0,1] \), the limits
\[
\lim_{n \to \infty} \varphi_{f_{\alpha}^{-}}(h_n) =a_{\alpha}, \quad 
\lim_{n \to \infty} \varphi_{f_{\alpha}^{+}}(h_n) =b_{\alpha},
\]
\[
\lim_{n \to \infty} \varphi_{f_{\alpha}^{+}}(h_n') = a_{\alpha}, \quad 
\lim_{n \to \infty} \varphi_{f_{\alpha}^{-}}(h_n') = b_{\alpha}
\]
hold. These equalities show that the points $a_\alpha$ and $b_\alpha$
belong to both cluster sets \( C_{R(0)}(\varphi_{f_{\alpha}^{-}}) \) and \( C_{R(0)}(\varphi_{f_{\alpha}^{+}}) \).

Since  $a_{\alpha}\leq b_{\alpha}$, suppose that for some $\alpha_0\in(0,1],$ $a_{\alpha_0}=b_{\alpha_0}.$ Then, it follows that for every $\alpha\in[\alpha_0,1],$ the equality $a_{\alpha}=b_{\alpha}$ holds. Consequently, the right delta derivatives  \( \Delta_{+} f_{\alpha}^{-}(t_0) \) and \( \Delta_{+} f_{\alpha}^{+}(t_0) \) exist and coincide. Specifically,  we have
\[
\Delta_{+} f_{\alpha}^{-}(t_0) = \Delta_{+} f_{\alpha}^{+}(t_0) = a_{\alpha} = b_{\alpha},
\]
and the existence of these derivatives is uniform with respect to \( \alpha \).

We now aim to show that for every \( \alpha \in [0,{\alpha_0})\), the cluster sets contain no points other than \( a_\alpha \) and \( b_\alpha \). In other words,
\[
C_{R(0)}(\varphi_{f_{\alpha}^{-}}) = \{ a_\alpha, b_\alpha \}\quad{\text{and}}\quad C_{R(0)}(\varphi_{f_{\alpha}^{+}}) = \{ a_\alpha, b_\alpha \}.
\]

Assume, for the sake of contradiction, that there exists some  $\alpha^*\in[0,{\alpha_0})$, and a third cluster point \( c\in C_{R(0)}(\varphi_{f_{\alpha^*}^{-}})  \)  such that \[ a_{\alpha^*} < c < b_{\alpha^*}. \] Then, there exists a sequence \( \{ h_n^{''} \}_{n=1}^\infty \subseteq \tilde{\mathbb{T}} \),   with each  term $h_n{''}  > 0$  and $h_n{''}  \to 0^+$ as $n \to \infty$, such that
\[
\lim_{n \to \infty} \varphi_{f_{\alpha^*}^{-}}(h_n'') = c.
\]
Hence, there exists \( N_1 \in \mathbb{N} \) such that for all \( n > N_1 \),
\begin{equation}\label{L1}
\frac{a_{\alpha^*} + c}{2} < \varphi_{f_{\alpha^*}^{-}}(h_n'') < \frac{c +b _{\alpha^*}}{2}.
\end{equation}
Since
\[
\lim_{n \to \infty} \min\left\{ \varphi_{f_{\alpha^*}^{-}}(h_n''), \varphi_{f_{\alpha^*}^{+}}(h_n'') \right\} = a_{\alpha^*},
\]
there is \( N_2 \in \mathbb{N} \) such that for all \( n > N_2 \),
\begin{equation}\label{L2}
\min\left\{ \varphi_{f_{\alpha^*}^{-}}(h_n''), \varphi_{f_{\alpha^*}^{+}}(h_n'') \right\} < \frac{a_{\alpha^*} + c}{2}.
\end{equation}
Similarly, as
\[
\lim_{n \to \infty} \max\left\{ \varphi_{f_{\alpha^*}^{-}}(h_n''), \varphi_{f_{\alpha^*}^{+}}(h_n'') \right\} = b_{\alpha^*},
\]
there is \( N_3 \in \mathbb{N} \) such that for all \( n > N_3 \),
\begin{equation}\label{L3}
\max\left\{ \varphi_{f_{\alpha^*}^{-}}(h_n''), \varphi_{f_{\alpha^*}^{+}}(h_n'') \right\} > \frac{c + b_{\alpha^*}}{2}.
\end{equation}
Combining inequalities \eqref{L1} and \eqref{L2},  we find that  for all \( n > \max\{N_1, N_2\} \),
\begin{equation}\label{L4}
\varphi_{f_{\alpha^*}^{+}}(h_n'') < \frac{a_{\alpha^*} + c}{2},
\end{equation}
whereas from  \eqref{L1} and \eqref{L3},   it follows that for all \( n > \max\{N_1, N_3\} \),
\begin{equation}\label{L5}
\varphi_{f_{\alpha^*}^{+}}(h_n'') > \frac{c + b_{\alpha^*}}{2}.
\end{equation}
For all \( n > \max\{N_1, N_2, N_3\} \), the inequalities \eqref{L4} and \eqref{L5} contradict each other, which means the point \( c  \) cannot exist. A similar argument applies to the cluster set $C_{R(0)}(\varphi_{f_{\alpha}^{+}}),$   which also contains no points other than \( a_\alpha \) and \( b_\alpha \). Therefore, we conclude that for every \( \alpha \in [0,\alpha_{0}),\)  the sets of right-sided cluster points of both functions are precisely
\[
C_{R(0)}(\varphi_{f_{\alpha}^{-}}) = \{ a_\alpha, b_\alpha \}, \quad 
C_{R(0)}(\varphi_{f_{\alpha}^{+}}) = \{ a_\alpha, b_\alpha \}.
\]
%for every \( \alpha \in [0,\alpha_{0}).\)

Since \( f \) is right \(\Delta_{gH}\)-differentiable at \( t_0 \), the \(\alpha\)-level set of its right \(\Delta_{gH}\)-derivative  is expressed as
\begin{align*}
[\Delta_{gH_+} f(t_0)]_{\alpha} 
&= \left[
\lim_{\substack{h \to 0^+ \\ h \in \tilde{\mathbb{T}}}} \min \left\{ \varphi_{f_{\alpha}^{-}}(h), \varphi_{f_{\alpha}^{+}}(h) \right\},
\lim_{\substack{h \to 0^+ \\ h \in \tilde{\mathbb{T}}}} \max \left\{ \varphi_{f_{\alpha}^{-}}(h), \varphi_{f_{\alpha}^{+}}(h) \right\}
\right] \\
&= [a_\alpha, b_\alpha],
\end{align*}
which is valid for all  \( \alpha \in [0,1] \), and  in particular for  \( \alpha \in [0,\alpha_0). \) This confirms that the functions \( \varphi_{f_{\alpha}^{-}}(h) \) and \( \varphi_{f_{\alpha}^{+}}(h) \) are right complementary at \( h = 0 \),  and  that the limits of the interval endpoints vary uniformly in
 $\alpha,$ as ensured by the structure of the Hausdorff metric.
\end{proof}
\begin{theorem}\label{right22}
Let $f:\mathbb{T} \to \mathbb{R}_{\cal{F}}$ be a fuzzy number-valued function, and let $t_0 \in \mathbb{T}^{\kappa}$ be a right-dense point. Then, $f$ is right $\Delta_{gH}$-differentiable at  $t_0$ if one of the following three cases holds:
\begin{enumerate}[label=(\roman*)]
\item The right delta derivatives \(\Delta_{+} f_{\alpha}^{-}(t_0)\) and \(\Delta_{+} f_{\alpha}^{+}(t_0)\) exist uniformly with respect to \(\alpha \in [0,1]\). Furthermore, as functions of \(\alpha\), \(\Delta_{+} f_{\alpha}^{-}(t_0)\) is monotonically increasing, while \(\Delta_{+} f_{\alpha}^{+}(t_0)\) is monotonically decreasing, and they satisfy the inequality
\[
\Delta_{+} f_{1}^{-}(t_0) \leq \Delta_{+} f_{1}^{+}(t_0).
\]
Under these conditions, the right \(\Delta_{gH}\)-derivative of \(f\) at \(t_0\) is expressed as
\[
\left[\Delta_{gH_+} f(t_0)\right]_{\alpha} = \left[\Delta_{+} f_{\alpha}^{-}(t_0), \, \Delta_{+} f_{\alpha}^{+}(t_0)\right]
\]
for every \(\alpha \in [0,1]\).



\item The right delta derivatives $\Delta_{+} f_{\alpha }^{-}(t_0)$ and $\Delta_{+} f_{\alpha }^{+}(t_0)$ exist  uniformly with respect to  $\alpha \in [0,1].$  Furthermore, as functions of  $\alpha$, $\Delta_+ f_{\alpha}^{+}(t_0)$ is monotonically increasing, while $\Delta_+ f_{\alpha}^{-}(t_0)$ is monotonically decreasing, and they satisfy the inequality $$\Delta_+ f_{1}^{+}(t_0) \leq \Delta_+ f_{1}^{-}(t_0).$$ Under these conditions, the right \(\Delta_{gH}\)-derivative of \( f \) at \( t_0 \) is expressed as
\begin{equation*}
    \left[\Delta_{gH_+} f(t_0)\right]_{\alpha} = \left[\Delta _+f_{\alpha}^{+}(t_0), \Delta_+ f_{\alpha}^{-}(t_0)\right]
\end{equation*}
for every $\alpha \in [0,1]$.



\item There exists a threshold \( \alpha_0 \in (0,1] \) such that,  for all \( \alpha \in [\alpha_0,1] \), the right delta derivatives \( \Delta_{+} f_{\alpha}^{-}(t_0) \) and \( \Delta_{+} f_{\alpha}^{+}(t_0) \) exist and are equal, that is,
\[
\Delta_{+} f_{\alpha}^{-}(t_0) = \Delta_{+} f_{\alpha}^{+}(t_0) = a_{\alpha} = b_{\alpha},
\]
and this existence is uniform with respect to \( \alpha \). 

\noindent  On the other hand, for \( \alpha \in [0,\alpha_0) \), the functions \( f_{\alpha}^{-} \) and \( f_{\alpha}^{+} \) are not right delta differentiable at \( t_0 \), but their associated slope functions \( \varphi_{f_{\alpha}^{-}} \) and \( \varphi_{f_{\alpha}^{+}} \) are right complementary at zero. Specifically, there exist constants \( a_{\alpha} < b_{\alpha} \) such that
\[
C_{R(0)}(\varphi_{f_{\alpha}^{-}}) = C_{R(0)}(\varphi_{f_{\alpha}^{+}}) = \{a_{\alpha}, b_{\alpha}\},
\]
and the limits 
\[
\lim_{\substack{h \to 0^+ \\ h \in \tilde{\mathbb{T}}}} \min\left\{ \varphi_{f_{\alpha}^{-}}(h), \varphi_{f_{\alpha}^{+}}(h) \right\} = a_{\alpha}, \quad
\lim_{\substack{h \to 0^+ \\ h \in \tilde{\mathbb{T}}}} \max\left\{ \varphi_{f_{\alpha}^{-}}(h), \varphi_{f_{\alpha}^{+}}(h) \right\} = b_{\alpha}\]
exist uniformly with respect to $\alpha$.

\noindent Furthermore, the endpoints \( a_{\alpha} \) and \( b_{\alpha} \) vary monotonically with \( \alpha \): the function \( a_{\alpha} \) increases, while \( b_{\alpha} \) decreases. These endpoints also satisfy the consistency condition \( a_1 \leq b_1 \). 

Consequently, the right \(\Delta_{gH}\)-derivative of \( f \) at \( t_0 \) is given by
\[
[\Delta_{gH_+} f(t_0)]_{\alpha} = [a_{\alpha}, b_{\alpha}]
\]
for all \( \alpha \in [0,1] \).
%\item  For each \( \alpha \in [0,1] \), the functions \( f_{\alpha}^{-} \) and \( f_{\alpha}^{+} \) fail to be right delta differentiable at the point \( t_0 \). Nonetheless, their associated slope functions, \( \varphi_{f_{\alpha}^{-}} \) and \( \varphi_{f_{\alpha}^{+}} \), exhibit a form of right sided complementary behavior at \( 0 \). In particular, there exist real numbers \( a_{\alpha} < b_{\alpha} \) such that the set of right-hand cluster points of both slope functions at zero is given by:
%\[
%C_{R(0)}(\varphi_{f_{\alpha}^{-}}) = C_{R(0)}(\varphi_{f_{\alpha}^{+}}) = \{a_{\alpha}, b_{\alpha}\}.
%\]
%Moreover, the following uniform limits with respect to \( \alpha \) are satisfied:
%\[
%\lim_{h \to 0^+} \min\left\{\varphi_{f_{\alpha}^{-}}(h), \varphi_{f_{\alpha}^{+}}(h)\right\} = a_{\alpha}, \quad
%\lim_{h \to 0^+} \max\left\{\varphi_{f_{\alpha}^{-}}(h), \varphi_{f_{\alpha}^{+}}(h)\right\} = b_{\alpha}.
%\]

%The bounds \( a_{\alpha} \) and \( b_{\alpha} \) depend monotonically on the level \( \alpha \): \( a_{\alpha} \) increases monotonically with \( \alpha \), while \( b_{\alpha} \) decreases monotonically. These bounds also satisfy the consistency condition \( a_1 \leq b_1 \).

%Consequently, the generalized Hukuhara right delta derivative of \( f \) at \( t_0 \), in terms of its level set representation, is given by:
%\[
%\left[\Delta_{gH_+}f(t_0)\right]_{\alpha} = [a_{\alpha}, b_{\alpha}],
%\]
%for all \( \alpha \in [0,1] \).
\end{enumerate}
\end{theorem}
\begin{proof}
Assume that Case (i) holds. Since the right delta derivatives \( \Delta_+ f_\alpha^-(t_0) \) and \( \Delta_+ f_\alpha^+(t_0) \) exist  uniformly in  \( \alpha \in [0,1] \), it follows from the definition of the right delta derivative that  for all sufficiently small  \( h > 0 \) with \( h \in \tilde{\mathbb{T}} \),  the following asymptotic expansions hold uniformly with respect to \( \alpha \):
\[
f_\alpha^-(t_0 + h) - f_\alpha^-(t_0) = h \Delta_+ f_\alpha^-(t_0) + o(h),
\]
\[
f_\alpha^+(t_0 + h) - f_\alpha^+(t_0) = h \Delta_+ f_\alpha^+(t_0) + o(h).
\]
Subtracting these two expressions yields
\[
f_\alpha^-(t_0 + h) - f_\alpha^-(t_0) - \left( f_\alpha^+(t_0 + h) - f_\alpha^+(t_0) \right)
= hA(\alpha) + o(h),
\]
where we define 
\[
A(\alpha) := \Delta_+ f_\alpha^-(t_0) - \Delta_+ f_\alpha^+(t_0).
\]

Given that \( \Delta_+ f_{\alpha}^{-}(t_0) \) is monotonically increasing and \( \Delta_+ f_{\alpha}^{+}(t_0) \) is monotonically decreasing with respect to \( \alpha \in [0,1] \), and that
\[
\Delta_+ f_{1}^{-}(t_0) \leq \Delta_+ f_{1}^{+}(t_0),
\]
it follows that
\[
\Delta_+ f_{\alpha}^{-}(t_0) \leq \Delta_+ f_{\alpha}^{+}(t_0) \quad \text{for all } \alpha \in [0,1],
\]
so $A(\alpha)\leq 0$ for all $\alpha \in [0,1].$

We now distinguish two subcases.

{\bf{Case 1:}} \( A(\alpha)< 0 \) for some $\alpha\in[0,1].$

Since \( h > 0 \) and \( A(\alpha) < 0 \), it follows that \( hA(\alpha) < 0 \). 
Also, because \(\frac{ o(h)}{h} \to 0 \) as \( h \to 0^+ \) within $\tilde{\mathbb{T}}$, there exists \( \delta > 0 \) such that for all $h\in\tilde{\mathbb{T}}$ with \( 0 < h < \delta \),  we have
\[
|o(h)| < \frac{|A(\alpha)|}{2} h.
\]
Thus,
\[
hA(\alpha) + o(h) < hA(\alpha) + \frac{|A(\alpha)|}{2} h =  \frac{A(\alpha)}{2}h < 0.
\]
This leads to the inequality
\[
f_\alpha^-(t_0 + h) - f_\alpha^-(t_0) < f_\alpha^+(t_0 + h) - f_\alpha^+(t_0)
\]
holding for all sufficiently small \( h > 0 \) within $\tilde{\mathbb{T}}$.%, and for all $\alpha\in[0,1].$



{\bf{Case 2:}} \( A(\alpha) = 0 \) for some $\alpha\in[0,1].$

 In this situation,  the expression  simplifies to
\[
f_\alpha^-(t_0 + h) - f_\alpha^-(t_0) - \left( f_\alpha^+(t_0 + h) - f_\alpha^+(t_0) \right)
= o(h).
\]
According to the definition of little-$o$ notation, for any  \( \varepsilon > 0 \), there exists \( \delta > 0 \) such that 
for all  $h\in\tilde{\mathbb{T}}$  with \( 0 < h < \delta \), we have 
$$ |o(h)| < \varepsilon h.$$
Set $\delta_0:=\min\{1,\delta\}.$
Then for all $h\in\tilde{\mathbb{T}}$ satisfying
$0<h<\delta_0$,  it follows that
$$ |o(h)| < \varepsilon .$$
Therefore,  for such $h$, we get
\[
f_\alpha^-(t_0 + h) - f_\alpha^-(t_0)<f_\alpha^+(t_0 + h)-f_\alpha^+(t_0)+\varepsilon.
\]
Taking the limit as  \( \varepsilon \to 0^+ \), we obtain the inequality
\[
f_\alpha^-(t_0 + h) - f_\alpha^-(t_0) \leq f_\alpha^+(t_0 + h) - f_\alpha^+(t_0),
\]
valid for    %\( \alpha \in [0,1] \) and 
all $0<h<\delta_0$ within $\tilde{\mathbb{T}}$.

\noindent In summary, regardless of whether \( A(\alpha) < 0 \) or \( A (\alpha)= 0 \),    the inequality
\[
f_\alpha^-(t_0 + h) - f_\alpha^-(t_0) \leq f_\alpha^+(t_0 + h) - f_\alpha^+(t_0)
\]
holds for all \( \alpha \in [0,1] \),  provided  \( h > 0 \) is  sufficiently small in $\tilde{\mathbb{T}}$. This ensures that the Hukuhara difference of the $\alpha$-level sets,
\[
[f(t_0 + h)]_\alpha \ominus_H [f(t_0)]_\alpha
\]
defines a valid interval for each  \( \alpha\in[0,1] \).

Now, let \( \varepsilon > 0 \) be arbitrary.  Since the right delta derivatives exist uniformly with respect to $\alpha$, there exists \( \delta > 0 \) such that for all \( h \in\tilde{\mathbb{T}}\) with \( 0 < h < \delta \), and all \( \alpha \in [0,1] \), we have
\[
\left| \frac{f_\alpha^{-}(t_0 + h) - f_\alpha^{-}(t_0)}{h} - \Delta_+ f_\alpha^{-}(t_0) \right| < \varepsilon.
\]
Previously, we considered the slope  function  $\varphi_{f_\alpha^-}(h)$
as a function of \( h \). To analyze  how this slope  varies with respect to  the parameter \( \alpha \), we now fix \(0<h<\delta \) in $\tilde{\mathbb T}$ and define
\[
\Phi_h(\alpha) := \frac{f_\alpha^-(t_0 + h) - f_\alpha^-(t_0)}{h}.
\]
Let  \(\alpha_1, \alpha_2 \in [0,1]\) with \(\alpha_1 < \alpha_2\). From the earlier inequality, we deduce
\[
\Phi_h(\alpha_1) < \Delta_+ f_{\alpha_1}^{-}(t_0) + \varepsilon, \quad
\Phi_h(\alpha_2) > \Delta_+ f_{\alpha_2}^{-}(t_0) - \varepsilon.
\]
Subtracting the two gives
\[
\Phi_h(\alpha_2) - \Phi_h(\alpha_1) > \Delta_+ f_{\alpha_2}^{-}(t_0) - \Delta_+ f_{\alpha_1}^{-}(t_0) - 2\varepsilon.
\]
Since \( \Delta_+ f_\alpha^{-}(t_0)\) is monotonically increasing in $\alpha$, we know
\[
\Delta_+ f_{\alpha_2}^{-}(t_0) - \Delta_+ f_{\alpha_1}^{-}(t_0) \geq 0,
\]
and hence
\[
\Phi_h(\alpha_2)>\Phi_h(\alpha_1)-2\varepsilon.
\]
As this inequality holds for any \(\varepsilon > 0\), taking the limit as \(\varepsilon \to 0^+\) yields
\[
\Phi_h(\alpha_2)\geq \Phi_h(\alpha_1).
\]
This implies that
$$f_{\alpha_{2}}^{-}(t_0 + h) - f_{\alpha_{2}}^{-}(t_0)\geq f_{\alpha_{1}}^{-}(t_0 + h) - f_{\alpha_{1}}^{-}(t_0)$$
for all sufficiently  small $h>0$ in $\tilde{\mathbb{T}}$. That is, the map
 $$\alpha \mapsto f_\alpha^{-}(t_0 + h) - f_\alpha^{-}(t_0)$$ is monotonically increasing. Similarly, using the fact that  \( \Delta_+ f_\alpha^{+}(t_0)\) is monotonically decreasing  and applying the same reasoning, we  conclude that
$$f_\alpha^{+}(t_0 + h) - f_\alpha^{+}(t_0)$$ is monotonically decreasing in $\alpha$.

Therefore, the generalized Hukuhara difference
 $$ f(t_0 + h) \ominus_{gH} f(t_0) $$ 
 exists for all sufficiently small \( h > 0 \) in $\tilde{\mathbb{T}}$.

Since the right delta derivatives $\Delta_+ f_{\alpha}^{-}(t_0)$ and $\Delta_+ f_{\alpha}^{+}(t_0)$ exist for every $\alpha \in [0,1]$, the associated auxiliary functions $\varphi_{f_{\alpha}^{-}}$ and $\varphi_{f_{\alpha}^{+}}$ satisfy the limits
\begin{equation*}\label{limlim}
\lim_{\substack{h \to 0^+ \\ h \in \tilde{\mathbb{T}}}} \varphi_{f_{\alpha }^{-}}(h)= \Delta_{+} f_{\alpha }^{-}(t_0), \quad \text{and} \quad \lim_{\substack{h \to 0^+ \\ h \in \tilde{\mathbb{T}}}} \varphi_{f_{\alpha }^{+}}(h) = \Delta_{+} f_{\alpha }^{+}(t_0).
\end{equation*}
%As a result, the limit of the pointwise minimum of the two auxiliary functions equals the minimum of their respective limits, that is,
%\begin{align*}
%\lim_{\substack{h \to 0^+ \\ h \in \tilde{\mathbb{T}}}}\min\{ \varphi_{f_{\alpha }^{-}}(h), \varphi_{f_{\alpha }^{+}}(h) \}
%= \min\{\lim_{\substack{h \to 0^+ \\ h \in \tilde{\mathbb{T}}}} \varphi_{f_{\alpha }^{-}}(h), \lim_{\substack{h \to 0^+ \\ h \in \tilde{\mathbb{T}}}}\varphi_{f_{\alpha }^{+}}(h)\}&=\min\{\Delta_{+} f_{\alpha }^{-}(t_0),\Delta_{+} f_{\alpha }^{+}(t_0)\}\\
%&=\Delta_{+} f_{\alpha }^{-}(t_0).
%\end{align*}
%and similarly,
%Similarly, the limit of the pointwise maximum is given by
%\begin{align*}
%\lim_{\substack{h \to 0^+ \\ h \in \tilde{\mathbb{T}}}}\max\{ \varphi_{f_{\alpha }^{-}}(h), \varphi_{f_{\alpha }^{+}}(h) \}
%= \max\{\lim_{\substack{h \to 0^+ \\ h \in \tilde{\mathbb{T}}}} \varphi_{f_{\alpha }^{-}}(h), \lim_{\substack{h \to 0^+ \\ h \in \tilde{\mathbb{T}}}}\varphi_{f_{\alpha }^{+}}(h)\}&=\max\{\Delta_{+} f_{\alpha }^{-}(t_0),\Delta_{+} f_{\alpha }^{+}(t_0)\}\\&=\Delta_{+} f_{\alpha }^{+}(t_0).
%\end{align*}
Because $f^{-}_\alpha$ and $f^{+}_\alpha$ are right delta differentiable at $t_0,$ uniformly in $\alpha $, these limits  also hold uniformly over $\alpha\in[0,1].$

Let $\{h_n\}_{n=1}^{\infty} \subseteq \tilde{\mathbb{T}}$ be a sequence with each  $h_n > 0$  and $h_n \to 0^+$ as $n \to \infty$.  Then  these limits can be expressed as
\[
\Delta_+ f^{-}_\alpha(t_0) = \lim_{n \to \infty} \varphi_{f_{\alpha }^{-}}(h_n)
, \quad \text{and} \quad 
\Delta_+ f^{+}_\alpha(t_0) = \lim_{n \to \infty} \varphi_{f_{\alpha }^{+}}(h_n).
\]
This shows that both  $\Delta_+ f^{-}_\alpha(t_0)$ and $\Delta_+ f^{+}_\alpha(t_0)$ are  uniform limits of sequences of left-continuous functions with respect to 
 $\alpha \in (0,1]$,  hence they  themselves are left-continuous on $(0,1].$
 %Consequently, they are themselves are left continuous for $\alpha \in (0,1]$.
 A similar argument gives right continuity at  $\alpha = 0$.
 %A similar argument establishes right continuity at $\alpha = 0$.

\noindent  Thus, by Theorem~\ref{Bede1}, the interval-valued function
 %By applying  Theorem~\ref{Bede1}, we conclude that the interval-valued function
\[
\left[ \Delta_+ f_{\alpha}^{-}(t_0), \Delta_+ f_{\alpha}^{+}(t_0) \right]
\]
defines a valid fuzzy number. 

It further follows that the limit 
\begin{align*}
\Delta_{gH_+} f_{\alpha}(t_0) 
&= \lim_{\substack{h \to 0^+ \\ h \in \tilde{\mathbb{T}}}} \frac{1}{h} \left( [f(t_0 + h)]_{\alpha} \ominus_{gH} [f(t_0)]_{\alpha} \right) \\
&= \lim_{\substack{h \to 0^+ \\ h \in \tilde{\mathbb{T}}}} \frac{1}{h} [ f_{\alpha}^{-}(t_0 + h) - f_{\alpha}^{-}(t_0),\,
           f_{\alpha}^{+}(t_0 + h) - f_{\alpha}^{+}(t_0)]\\
&=\lim_{\substack{h \to 0^+ \\ h \in \tilde{\mathbb{T}}}}\left[ \frac{f_{\alpha}^{-}(t_0 + h) - f_{\alpha}^{-}(t_0)}{h},\,
           \frac{f_{\alpha}^{+}(t_0 + h) - f_{\alpha}^{+}(t_0)}{h}\right]\\
%&= \lim_{\substack{h \to 0^+ \\ h \in \tilde{\mathbb{T}}}} \frac{1}{h} \left[
%\min\left\{ f_{\alpha}^{-}(t_0 + h) - f_{\alpha}^{-}(t_0),\,
%           f_{\alpha}^{+}(t_0 + h) - f_{\alpha}^{+}(t_0) \right\}, \right. \\
%&\qquad\qquad\qquad\left.
%\max\left\{ f_{\alpha}^{-}(t_0 + h) - f_{\alpha}^{-}(t_0),\,
  %         f_{\alpha}^{+}(t_0 + h) - f_{\alpha}^{+}(t_0) \right\} \right] \\
%&= \lim_{\substack{h \to 0^+ \\ h \in \tilde{\mathbb{T}}}} \left[
%\min\left\{ \frac{f_{\alpha}^{-}(t_0 + h) - f_{\alpha}^{-}(t_0)}{h},\,
%           \frac{f_{\alpha}^{+}(t_0 + h) - f_{\alpha}^{+}(t_0)}{h} \right\}, \right. \\
%&\qquad\qquad\qquad\left.
%\max\left\{ \frac{f_{\alpha}^{-}(t_0 + h) - f_{\alpha}^{-}(t_0)}{h},\,
%           \frac{f_{\alpha}^{+}(t_0 + h) - f_{\alpha}^{+}(t_0)}{h} \right\} \right] \\
    &=\left[
\lim_{\substack{h \to 0^+ \\ h \in \tilde{\mathbb{T}}}} \varphi_{f_{\alpha }^{-}}(h),\,
\lim_{\substack{h \to 0^+ \\ h \in \tilde{\mathbb{T}}}}   \varphi_{f_{\alpha }^{+}}(h) 
\right] \\
&= \left[\Delta_{+} f_{\alpha }^{-}(t_0), \Delta_{+} f_{\alpha }^{+}(t_0)\right]
\end{align*}
exists for all \(\alpha \in [0,1]\), and it exists uniformly in \(\alpha\).
 Hence, by Remark  \ref{Rmk}, the function $f$ is right 
$\Delta_{gH}$-differentiable at $t_0,$  and
\begin{equation*}
    \left[\Delta_{{gH}_{+}} f(t_0)\right]_{\alpha} = \left[\Delta_+ f_{\alpha}^{-}(t_0), \Delta_+ f_{\alpha}^{+}(t_0)\right]
\end{equation*}
for all $\alpha \in [0,1]$. The reasoning for Case (ii) proceeds in a similar manner.

Now consider Case (iii). For \( \alpha \in [\alpha_0, 1] \),  by the reasoning used in  Case (i), the generalized Hukuhara difference
    \[
    f(t_0 + h) \ominus_{gH} f(t_0)
    \]
    exists for all sufficiently small \( h > 0 \) in $\tilde{\mathbb{T}}$. On the other hand, for \( \alpha \in [0, \alpha_0) \), although the endpoint functions \( f_\alpha^- \) and \( f_\alpha^+ \) are not right delta differentiable at $t_0$, the uniform existence with respect to $\alpha$ of the limits of the minimum and maximum of the slope functions ensures that the generalized Hukuhara difference at level $\alpha,$
    \[[f(t_0 + h)]_\alpha \ominus_{gH} [f(t_0)]_\alpha\]
    forms a valid interval for sufficiently small \( h > 0 \) in $\tilde{\mathbb{T}}$. Depending on the slope behavior, this interval is either
\[
    [f_\alpha^-(t_0 + h) - f_\alpha^-(t_0),\, f_\alpha^+(t_0 + h) - f_\alpha^+(t_0)]
    \]
    or
     \[
     [f_\alpha^+(t_0 + h) - f_\alpha^+(t_0),\, f_\alpha^-(t_0 + h) - f_\alpha^-(t_0)].
    \]
%, with the limiting behavior of slope functions determining the derivative interval.
Therefore, the generalized Hukuhara difference
 $$ f(t_0 + h) \ominus_{gH} f(t_0) $$ 
 exists for all sufficiently small \( h > 0 \) in $\tilde{\mathbb{T}}$.

Assuming that the following limits exist uniformly for all $\alpha\in[0,1],$
\[\lim_{\substack{h \to 0^+ \\ h \in \tilde{\mathbb{T}}}} \min\left\{ \varphi_{f_{\alpha}^{-}}(h), \varphi_{f_{\alpha}^{+}}(h) \right\} = a_{\alpha},\quad
\lim_{\substack{h \to 0^+ \\ h \in \tilde{\mathbb{T}}}} \max\left\{ \varphi_{f_{\alpha}^{-}}(h), \varphi_{f_{\alpha}^{+}}(h) \right\} = b_{\alpha},
\]
we conclude that the function \( f_{\alpha} \) is right \(\Delta_{gH}\)-differentiable at \( t_0 \), and this differentiability holds uniformly with respect to \( \alpha \). Furthermore, because these limits exist uniformly in \( \alpha \),  an argument analogous to  Case (i) shows that the endpoint functions  \( a_{\alpha} \) and \( b_{\alpha} \) are left-continuous on  \( (0,1] \) and right-continuous at \( \alpha = 0 \). Hence, by Theorem~\ref{Bede1}, the family of intervals \( [a_{\alpha}, b_{\alpha}] \)  constitutes a valid fuzzy number.

Additionally, the following uniform limit exists and defines the right \(\Delta_{gH}\)-derivative of $f_{\alpha}$ at $t_0$:
\begin{align*}
\Delta_{gH_+} f_{\alpha}(t_0) 
&= \lim_{\substack{h \to 0^+ \\ h \in \tilde{\mathbb{T}}}} \frac{1}{h} \left( [f(t_0 + h)]_{\alpha} \ominus_{gH} [f(t_0)]_{\alpha} \right) \\
&= \lim_{\substack{h \to 0^+ \\ h \in \tilde{\mathbb{T}}}} \frac{1}{h} \left[
\min\left\{ f_{\alpha}^{-}(t_0 + h) - f_{\alpha}^{-}(t_0),\,
           f_{\alpha}^{+}(t_0 + h) - f_{\alpha}^{+}(t_0) \right\}, \right. \\
&\qquad\qquad\qquad\left.
\max\left\{ f_{\alpha}^{-}(t_0 + h) - f_{\alpha}^{-}(t_0),\,
           f_{\alpha}^{+}(t_0 + h) - f_{\alpha}^{+}(t_0) \right\} \right] \\
&= \lim_{\substack{h \to 0^+ \\ h \in \tilde{\mathbb{T}}}} \left[
\min\left\{ \frac{f_{\alpha}^{-}(t_0 + h) - f_{\alpha}^{-}(t_0)}{h},\,
           \frac{f_{\alpha}^{+}(t_0 + h) - f_{\alpha}^{+}(t_0)}{h} \right\}, \right. \\
&\qquad\qquad\qquad\left.
\max\left\{ \frac{f_{\alpha}^{-}(t_0 + h) - f_{\alpha}^{-}(t_0)}{h},\,
           \frac{f_{\alpha}^{+}(t_0 + h) - f_{\alpha}^{+}(t_0)}{h} \right\} \right] \\
&= \left[
\lim_{\substack{h \to 0^+ \\ h \in \tilde{\mathbb{T}}}} \min\left\{ \varphi_{f_{\alpha }^{-}}(h), \varphi_{f_{\alpha }^{+}}(h) \right\},\,
\lim_{\substack{h \to 0^+ \\ h \in \tilde{\mathbb{T}}}} \max\left\{ \varphi_{f_{\alpha }^{-}}(h), \varphi_{f_{\alpha }^{+}}(h) \right\}
\right] \\
&= [a_{\alpha}, b_{\alpha}].
\end{align*}
Thus, by Remark  \ref{Rmk}, the function $f$ is right  $\Delta_{gH}$-differentiable at $t_0,$   with its derivative given level-wise by
\[
\left[\Delta_{gH_+} f(t_0)\right]_\alpha = 
\begin{cases}
[a_\alpha, b_\alpha], & \alpha \in [0, \alpha_0), \\
[a_\alpha, a_\alpha], &\alpha \in [\alpha_0, 1],
\end{cases}
\]
where in the latter case the derivative reduces to a singleton interval.
\end{proof}

Similarly to  Theorems \ref{right1} and \ref{right22}, we can also establish the following results for a left-dense point \( t_0 \in \mathbb{T}^{\kappa} \).


\begin{theorem}\label{left1}
Let \( f:\mathbb{T} \to \mathbb{R}_{\mathcal{F}} \) be a fuzzy number-valued function, and let \( t_0 \in \mathbb{T}^{\kappa} \) be a left-dense point. Suppose that \( f \) is left \(\Delta_{gH}\)-differentiable at \( t_0 \). Then, one of the following two cases must hold:

\begin{enumerate}[label=(\roman*)]
\item The left delta derivatives \( \Delta_{-} f_{\alpha}^{-}(t_0) \) and \( \Delta_{-} f_{\alpha}^{+}(t_0) \)  exist uniformly with respect to  \( \alpha \in [0,1] \).  Hence, the left \(\Delta_{gH}\)-derivative of \( f \) at \( t_0 \) takes the form
  \[
    [\Delta_{gH_-} f(t_0)]_{\alpha} = \left[\Delta_{-} f_{\alpha }^{-}(t_0), \Delta_{-} f_{\alpha }^{+}(t_0) \right]
    \]
    or
    \[
    [\Delta_{gH_-} f(t_0)]_{\alpha} = \left[\Delta_{-} f_{\alpha }^{+}(t_0), \Delta_{-} f_{\alpha }^{-}(t_0) \right]
    \]
for all \( \alpha\).

\item There exists a threshold \( \alpha_0 \in (0,1] \) such that, for all \( \alpha \in [\alpha_0,1] \), the left delta derivatives \( \Delta_{-} f_{\alpha}^{-}(t_0) \) and \( \Delta_{-} f_{\alpha}^{+}(t_0) \) exist and are equal, that is,
\[
\Delta_{-} f_{\alpha}^{-}(t_0) = \Delta_{-} f_{\alpha}^{+}(t_0) = a_{\alpha} = b_{\alpha},
\]
and this existence is uniform with respect to  \( \alpha \).

\noindent On the other hand, for \( \alpha \in [0,\alpha_0) \), the functions \( f_{\alpha}^{-} \) and \( f_{\alpha}^{+} \) are not left delta differentiable at \( t_0 \), but their associated slope functions \( \varphi_{f_{\alpha}^{-}} \) and \( \varphi_{f_{\alpha}^{+}} \) are left complementary at zero. That is, there exist constants \( a_{\alpha} < b_{\alpha} \) such that
\[
    C_{L(0)}(\varphi_{f_{\alpha }^{-}}) = C_{L(0)}(\varphi_{f_{\alpha }^{+}}) = \{a_{\alpha}, b_{\alpha}\}\]  and the limits 
    \[\lim_{\substack{h \to 0^- \\ h \in \tilde{\mathbb{T}}}} \min\left\{\varphi_{f_{\alpha }^{-}}(h), \varphi_{f_{\alpha }^{+}}(h)\right\} =a_{\alpha},\quad 
    \lim_{\substack{h \to 0^- \\ h \in \tilde{\mathbb{T}}}} \max\left\{\varphi_{f_{\alpha }^{-}}(h), \varphi_{f_{\alpha }^{+}}(h)\right\} =b_{\alpha}
    \] 
exist uniformly with respect to $\alpha$. 

\noindent Consequently, the left \(\Delta_{gH}\)-derivative of \( f \) at \( t_0 \) is given by
    $$[\Delta_{gH_-} f(t_0)]_{\alpha }=[a_{\alpha}, b_{\alpha}]$$
for all $\alpha \in [0,1]$.
\end{enumerate}
\end{theorem}



\begin{theorem}\label{right2}
Let $f:\mathbb{T} \to \mathbb{R}_{\cal{F}}$ be a fuzzy number-valued function, and let $t_0 \in \mathbb{T}^{\kappa}$ be a left-dense point. Then, $f$ is left $\Delta_{gH}$-differentiable at  $t_0$ if one of the following three cases holds:
\begin{enumerate}[label=(\roman*)]
 \item The left delta derivatives $\Delta_{-} f_{\alpha }^{-}(t_0)$ and $\Delta_{-} f_{\alpha }^{+}(t_0)$ exist uniformly with respect to  $\alpha \in [0,1].$  Furthermore, as functions of $\alpha$, $\Delta_-f_{\alpha}^{-}(t_0)$ is monotonically increasing, while $\Delta_- f_{\alpha}^{+}(t_0)$ is monotonically decreasing, and they satisfy the inequality $$\Delta_- f_{1}^{-}(t_0) \leq \Delta_- f_{1}^{+}(t_0).$$Under these conditions, the left \(\Delta_{gH}\)-derivative of \( f \) at \( t_0 \) is expressed as
\begin{equation*}
    \left[\Delta_{gH_-} f(t_0)\right]_{\alpha} = \left[\Delta _-f_{\alpha}^{-}(t_0), \Delta_- f_{\alpha}^{+}(t_0)\right]
\end{equation*}
for all $\alpha \in [0,1].$

\item  The left delta derivatives $\Delta_{-} f_{\alpha }^{-}(t_0)$ and $\Delta_{-} f_{\alpha }^{+}(t_0)$ exist   uniformly with respect to  $\alpha \in [0,1].$  Furthermore, as functions of $\alpha$, $\Delta_- f_{\alpha}^{+}(t_0)$ is monotonically increasing, while $\Delta_- f_{\alpha}^{-}(t_0)$ is monotonically decreasing, and they satisfy the inequality $$\Delta_- f_{1}^{+}(t_0) \leq \Delta_- f_{1}^{-}(t_0).$$ 

\noindent Under these conditions, the left \(\Delta_{gH}\)-derivative of \( f \) at \( t_0 \) is expressed as
\begin{equation*}
    \left[\Delta_{gH_-} f(t_0)\right]_{\alpha} = \left[\Delta _-f_{\alpha}^{+}(t_0), \Delta_- f_{\alpha}^{-}(t_0)\right]
\end{equation*}
for all $\alpha \in [0,1]$.

\item There exists a threshold \( \alpha_0 \in (0,1] \) such that, for all \( \alpha \in [\alpha_0,1] \), the left delta derivatives \( \Delta_{-} f_{\alpha}^{-}(t_0) \) and \( \Delta_{-} f_{\alpha}^{+}(t_0) \) exist and are equal, that is,
\[
\Delta_{-} f_{\alpha}^{-}(t_0) = \Delta_{-} f_{\alpha}^{+}(t_0) = a_{\alpha} = b_{\alpha},
\]
and this existence is uniform with respect to \( \alpha \). 

\noindent On the other hand, for \( \alpha \in [0,\alpha_0) \), the functions \( f_{\alpha}^{-} \) and \( f_{\alpha}^{+} \) are not left delta differentiable at \( t_0 \), but their associated slope functions \( \varphi_{f_{\alpha}^{-}} \) and \( \varphi_{f_{\alpha}^{+}} \) are left complementary at zero. Specifically, there exist constants \( a_{\alpha} < b_{\alpha} \) such that
\[
    C_{L(0)}(\varphi_{f_{\alpha }^{-}}) = C_{L(0)}(\varphi_{f_{\alpha }^{+}}) = \{a_{\alpha}, b_{\alpha}\},\]  and the limits 
    \[\lim_{\substack{h \to 0^- \\ h \in \tilde{\mathbb{T}}}} \min\left\{\varphi_{f_{\alpha }^{-}}(h), \varphi_{f_{\alpha }^{+}}(h)\right\} =a_{\alpha},\quad 
    \lim_{\substack{h \to 0^- \\ h \in \tilde{\mathbb{T}}}} \max\left\{\varphi_{f_{\alpha }^{-}}(h), \varphi_{f_{\alpha }^{+}}(h)\right\} =b_{\alpha}
    \] 
exist uniformly with respect to $\alpha$. 


\noindent Furthermore, the endpoints \( a_{\alpha} \) and \( b_{\alpha} \) vary monotonically with  \( \alpha \): the function \( a_{\alpha} \) increases, while \( b_{\alpha} \) decreases. These  endpoints also satisfy the consistency condition \( a_1 \leq b_1 \). 

\noindent Consequently, the left \(\Delta_{gH}\)-derivative of \( f \) at \( t_0 \) is given by
\[
\left[\Delta_{gH_-}f(t_0)\right]_{\alpha} = [a_{\alpha},b_{\alpha}]
\]
for all $\alpha \in [0,1]$.
\end{enumerate}
\end{theorem}

By combining the theorems stated above, we obtain the following results, which characterizes the gH-differentiability of a fuzzy number-valued function at a dense point \( t_0 \in \mathbb{T}^{\kappa} \).

\begin{theorem}\label{der1}
Let $f:\mathbb{T} \to \mathbb{R}_{\cal{F}}$ be a fuzzy number-valued function, and let $t_0 \in \mathbb{T}^{\kappa}$ be a  dense  point.   If $f$ is  $\Delta_{gH}$-differentiable at  $t_0$, then one of the following cases holds:
\begin{enumerate}[label=(\roman*)]

\item The functions \( f_{\alpha}^{-} \) and \( f_{\alpha}^{+} \) are uniformly \( \Delta \)-differentiable at \( t_0 \) with respect to \( \alpha \in [0,1] \). Then, for each \( \alpha \in [0,1] \), the \( \alpha \)-level set of the \( \Delta_{gH} \)-derivative of \( f \) at \( t_0 \) is an interval given by either
\[
[\Delta_{gH} f(t_0)]_{\alpha} = \left[\Delta f_{\alpha}^{-}(t_0), \Delta f_{\alpha}^{+}(t_0)\right]
\]
or
\[
[\Delta_{gH} f(t_0)]_{\alpha} = \left[\Delta f_{\alpha}^{+}(t_0), \Delta f_{\alpha}^{-}(t_0)\right].
\]




 \item The functions $f_{\alpha }^{-}$ and $f_{\alpha }^{+}$ are uniformly $\Delta$-differentiable at $t_0$   with respect to $\alpha \in [0,1]$. Then, for all \( \alpha \in [0,1] \), the \( \alpha \)-level set of the \( \Delta_{gH} \)-derivative of \( f \) at \( t_0 \) is an interval given by either
 \begin{equation*}
        [\Delta_{gH} f(t_0)]_{\alpha} = \left[\Delta f_{\alpha }^{-}(t_0), \Delta f_{\alpha }^{+}(t_0)\right]
    \end{equation*}
    or
    \begin{equation*}
        [\Delta_{gH} f(t_0)]_{\alpha} = \left[\Delta f_{\alpha }^{+}(t_0), \Delta f_{\alpha }^{-}(t_0).\right]
    \end{equation*}

\item   The one sided derivatives  $\Delta_{-} f_{\alpha }^{-}(t_0),$ $\Delta_{+} f_{\alpha }^{-}(t_0),$ $ \Delta_{-} f_{\alpha }^{+}(t_0),$ and $\Delta_{+} f_{\alpha }^{+}(t_0)$ exist uniformly with respect to $\alpha\in[0,1]$. Furthermore, the function  
$\Delta_{-} f_{\alpha }^{-}(t_0)=\Delta_{+} f_{\alpha }^{+}(t_0)$ is monotonically increasing with respect to $\alpha,$ while $\Delta_{+} f_{\alpha }^{-}(t_0)=\Delta_{-} f_{\alpha }^{+}(t_0)$ is monotonically decreasing.  In addition, the inequality $\Delta_{-} f_{1}^{-}(t_0)\leq \Delta_{-} f_{1}^{+}(t_0)$ holds.  In this setting, we have
$$\left[\Delta_{gH}f(t_0)\right]_{\alpha}=[\Delta_{-} f_{\alpha }^{-}(t_0),\Delta_{-} f_{\alpha }^{+}(t_0)]=[\Delta_{+} f_{\alpha }^{+}(t_0),\Delta_{+} f_{\alpha }^{-}(t_0)]$$
for all $\alpha\in[0,1].$

\item The one sided derivatives  $\Delta_{-} f_{\alpha}^{-}(t_0),$ $\Delta_{+} f_{\alpha}^{-}(t_0)$, $\Delta_{-} f_{\alpha}^{+}(t_0)$, and $\Delta_{+} f_{\alpha}^{+}(t_0)$ exist  uniformly with respect to $\alpha \in [0,1]$.   Furthermore, the function  $\Delta_{+} f_{\alpha}^{-}(t_0) = \Delta_{-} f_{\alpha}^{+}(t_0)$ is monotonically increasing with respect to $\alpha,$ while $\Delta_{-} f_{\alpha}^{-}(t_0) = \Delta_{+} f_{\alpha}^{+}(t_0)$ is monotonically decreasing. In addition, the inequality $\Delta_{+} f_{1}^{-}(t_0) \leq \Delta_{+} f_{1}^{+}(t_0)$. In this setting, we have
$$
\left[\Delta_{gH} f(t_0)\right]_{\alpha} = [\Delta_{+} f_{\alpha}^{-}(t_0), \Delta_{+} f_{\alpha}^{+}(t_0)] = [\Delta_{-} f_{\alpha}^{+}(t_0), \Delta_{-} f_{\alpha}^{-}(t_0)]
$$
for all $\alpha \in [0,1]$.

\item There exists a threshold \( \alpha_0 \in (0,1] \) such that, for all \( \alpha \in [\alpha_0,1] \), the functions  $f_{\alpha }^{-}$ and $f_{\alpha }^{+}$ are uniformly $\Delta$-differentiable at $t_0$   with respect to $\alpha,$ and 
$$
\left[\Delta_{gH} f(t_0)\right]_{\alpha} =\Delta f_{\alpha }^{-}(t_0)=\Delta f_{\alpha }^{+}(t_0)
.$$
\noindent On the other hand, for \( \alpha \in [0,\alpha_0) \), neither \( f_{\alpha}^{-} \) nor \( f_{\alpha}^{+} \) is left or right $\Delta$-differentiable at $t_0$. However, their associated slope functions, \( \varphi_{f_{\alpha}^{-}} \) and \( \varphi_{f_{\alpha}^{+}} \), are  left and right complementary at zero, that is, there exist constants \( a_{\alpha} < b_{\alpha} \) such that
\[
C_{R(0)}(\varphi_{f_{\alpha}^{-}}) = C_{R(0)}(\varphi_{f_{\alpha}^{+}}) = C_{L(0)}(\varphi_{f_{\alpha }^{-}}) = C_{L(0)}(\varphi_{f_{\alpha }^{+}}) = \{a_{\alpha}, b_{\alpha}\},
\]
and the limits 
\[
\lim_{\substack{h \to 0^+\\ h \in \tilde{\mathbb{T}}}} \min\left\{ \varphi_{f_{\alpha}^{-}}(h), \varphi_{f_{\alpha}^{+}}(h) \right\}=\lim_{\substack{h \to 0^-\\ h \in \tilde{\mathbb{T}}}} \min\left\{ \varphi_{f_{\alpha}^{-}}(h), \varphi_{f_{\alpha}^{+}}(h) \right\}=a_{\alpha},\]
\[
\lim_{\substack{h \to 0^+\\ h \in \tilde{\mathbb{T}}}} \max\left\{ \varphi_{f_{\alpha}^{-}}(h), \varphi_{f_{\alpha}^{+}}(h) \right\}=\lim_{\substack{h \to 0^-\\ h \in \tilde{\mathbb{T}}}} \max\left\{ \varphi_{f_{\alpha}^{-}}(h), \varphi_{f_{\alpha}^{+}}(h) \right\}=b_{\alpha} .\]
exist uniformly with respect to  $\alpha$. 

As a result, the  \(\Delta_{gH}\)-derivative of \( f \) at \( t_0 \) is given by
\[
[\Delta_{gH_+} f(t_0)]_{\alpha} = [a_{\alpha}, b_{\alpha}]
\]
for all \( \alpha \in [0,1] \).
\end{enumerate}
\end{theorem}
\begin{theorem}\label{denseder}
Let $f:\mathbb{T} \to \mathbb{R}_{\cal{F}}$ be a fuzzy number-valued function, and let $t_0 \in \mathbb{T}^{\kappa}$ be a  dense point. Then, $f$ is  $\Delta_{gH}$-differentiable at  $t_0$ if one of the following cases holds:
\begin{enumerate}[label=(\roman*)]
\item The functions $f_{\alpha }^{-}$ and $f_{\alpha }^{+}$
are uniformly $\Delta$-differentiable at $t_0$  with respect to $\alpha\in[0,1].$  Furthermore, as functions of  $\alpha$, $\Delta f_{\alpha}^{-}(t_0)$ is monotonically increasing, while $\Delta f_{\alpha}^{+}(t_0)$ is monotonically decreasing. In addition, the
inequality $\Delta f_{1}^{-}(t_0) \leq \Delta f_{1}^{+}(t_0)$ holds. Then, for each \( \alpha \in [0,1] \), the \( \alpha \)-level set of the \( \Delta_{gH} \)-derivative of \( f \) at \( t_0 \) is  given by
\begin{equation*}
    \left[\Delta_{gH} f(t_0)\right]_{\alpha} = \left[\Delta f_{\alpha}^{-}(t_0), \Delta f_{\alpha}^{+}(t_0)\right].
\end{equation*}


\item The functions $f_{\alpha }^{-}$ and $f_{\alpha }^{+}$
are uniformly  $\Delta$-differentiable at $t_0$ with respect to $\alpha\in[0,1].$   Furthermore, as functions of  $\alpha$, $\Delta f_{\alpha}^{+}(t_0)$ is monotonically increasing, while $\Delta f_{\alpha}^{-}(t_0)$ is monotonically decreasing. In addition, the
inequality $\Delta f_{1}^{+}(t_0) \leq \Delta f_{1}^{-}(t_0)$ holds. Then, for each \( \alpha \in [0,1] \), the \( \alpha \)-level set of the \( \Delta_{gH} \)-derivative of \( f \) at \( t_0 \) is  given by
\begin{equation*}
    \left[\Delta_{gH} f(t_0)\right]_{\alpha} = \left[\Delta f_{\alpha}^{+}(t_0), \Delta f_{\alpha}^{-}(t_0)\right].
\end{equation*}


\item  The one sided derivatives  $\Delta_{-} f_{\alpha}^{-}(t_0),$ $\Delta_{+} f_{\alpha}^{-}(t_0)$, $\Delta_{-} f_{\alpha}^{+}(t_0)$, and $\Delta_{+} f_{\alpha}^{+}(t_0)$  exist uniformly with respect to $\alpha\in[0,1]$. Furthermore, the function 
$\Delta_{-} f_{\alpha }^{-}(t_0)=\Delta_{+} f_{\alpha }^{+}(t_0)$ is monotonically increasing with respect to $\alpha,$ while $\Delta_{+} f_{\alpha }^{-}(t_0)=\Delta_{-} f_{\alpha }^{+}(t_0)$ is monotonically decreasing. In addition, the
inequality $\Delta_{-} f_{1}^{-}(t_0)\leq \Delta_{-} f_{1}^{+}(t_0)$ holds. In this setting, we have
$$\left[\Delta_{gH}f(t_0)\right]_{\alpha}=[\Delta_{-} f_{\alpha }^{-}(t_0),\Delta_{-} f_{\alpha }^{+}(t_0)]=[\Delta_{+} f_{\alpha }^{+}(t_0),\Delta_{+} f_{\alpha }^{-}(t_0)]$$
for all $\alpha\in[0,1].$

\item The one sided derivatives  $\Delta_{-} f_{\alpha}^{-}(t_0)$, $\Delta_{+} f_{\alpha}^{-}(t_0)$, $\Delta_{-} f_{\alpha}^{+}(t_0)$, and $\Delta_{+} f_{\alpha}^{+}(t_0)$ exist  uniformly with respect to $\alpha \in [0,1]$.  Furthermore, the function  $\Delta_{+} f_{\alpha}^{-}(t_0) = \Delta_{-} f_{\alpha}^{+}(t_0)$ is monotonically increasing with respect to $\alpha,$ while $\Delta_{-} f_{\alpha}^{-}(t_0) = \Delta_{+} f_{\alpha}^{+}(t_0)$ is monotonically decreasing. In addition, the inequality  $\Delta_{+} f_{1}^{-}(t_0) \leq \Delta_{+} f_{1}^{+}(t_0)$ holds. In this setting, we have
$$
\left[\Delta_{gH} f(t_0)\right]_{\alpha} = [\Delta_{+} f_{\alpha}^{-}(t_0), \Delta_{+} f_{\alpha}^{+}(t_0)] = [\Delta_{-} f_{\alpha}^{+}(t_0), \Delta_{-} f_{\alpha}^{-}(t_0)]
$$
for all $\alpha \in [0,1]$.


\item  There exists a threshold \( \alpha_0 \in (0,1] \) such that, for all \( \alpha \in [\alpha_0,1] \), the functions  $f_{\alpha }^{-}$ and $f_{\alpha }^{+}$ are uniformly $\Delta$-differentiable at $t_0$   with respect to $\alpha,$ and 
$$
\left[\Delta_{gH} f(t_0)\right]_{\alpha} =\Delta f_{\alpha }^{-}(t_0)=\Delta f_{\alpha }^{+}(t_0)
.$$
\noindent On the other hand, for \( \alpha \in [0,\alpha_0) \), neither \( f_{\alpha}^{-} \) nor \( f_{\alpha}^{+} \) is left or right $\Delta$-differentiable at $t_0$. However, their associated slope functions, \( \varphi_{f_{\alpha}^{-}} \) and \( \varphi_{f_{\alpha}^{+}} \), are  left and right complementary at zero, that is, there exist constants \( a_{\alpha} < b_{\alpha} \) such that
\[
C_{R(0)}(\varphi_{f_{\alpha}^{-}}) = C_{R(0)}(\varphi_{f_{\alpha}^{+}}) = C_{L(0)}(\varphi_{f_{\alpha }^{-}}) = C_{L(0)}(\varphi_{f_{\alpha }^{+}}) = \{a_{\alpha}, b_{\alpha}\},
\]
and the limits 
\[
\lim_{\substack{h \to 0^+\\ h \in \tilde{\mathbb{T}}}} \min\left\{ \varphi_{f_{\alpha}^{-}}(h), \varphi_{f_{\alpha}^{+}}(h) \right\}=\lim_{\substack{h \to 0^-\\ h \in \tilde{\mathbb{T}}}} \min\left\{ \varphi_{f_{\alpha}^{-}}(h), \varphi_{f_{\alpha}^{+}}(h) \right\}=a_{\alpha},\]
\[
\lim_{\substack{h \to 0^+\\ h \in \tilde{\mathbb{T}}}} \max\left\{ \varphi_{f_{\alpha}^{-}}(h), \varphi_{f_{\alpha}^{+}}(h) \right\}=\lim_{\substack{h \to 0^-\\ h \in \tilde{\mathbb{T}}}} \max\left\{ \varphi_{f_{\alpha}^{-}}(h), \varphi_{f_{\alpha}^{+}}(h) \right\}=b_{\alpha} .\]
exist uniformly with respect to  $\alpha$. 

\noindent Furthermore, the endpoints \( a_{\alpha} \) and \( b_{\alpha} \) vary monotonically with  \( \alpha \): the function \( a_{\alpha} \) increases, while \( b_{\alpha} \) decreases. These  endpoints also satisfy the consistency condition \( a_1 \leq b_1 \). 

\noindent As a result, the  \(\Delta_{gH}\)-derivative of \( f \) at \( t_0 \) is given by
\[
\left[\Delta_{gH_-}f(t_0)\right]_{\alpha} = [a_{\alpha},b_{\alpha}]
\]
for all $\alpha \in [0,1]$.
\end{enumerate}
\end{theorem}
At any isolated point 
 $t_0\in\mathbb{T}^{\kappa},$  the following theorem is valid.

\begin{theorem}\cite{Mert1}
Let $f:\mathbb{T} \to \mathbb{R}_{\cal{F}}$ be a fuzzy number-valued function, and let $t_0 \in \mathbb{T}^{\kappa}$ be an isolated point. Then, $f$ is  $\Delta_{gH}$-differentiable at  $t_0$, and for each \( \alpha \in [0,1] \), the \( \alpha \)-level set of the \( \Delta_{gH} \)-derivative of \( f \) at \( t_0 \) is an interval given by either
\[
[\Delta_{gH} f(t_0)]_{\alpha} = \left[\Delta f_{\alpha}^{-}(t_0), \Delta f_{\alpha}^{+}(t_0)\right]
\]
or
\[
[\Delta_{gH} f(t_0)]_{\alpha} = \left[\Delta f_{\alpha}^{+}(t_0), \Delta f_{\alpha}^{-}(t_0)\right].
\]
\end{theorem}

