%\bibliography{a_note.bib}
%\bibliographystyle{agsm}
%\appendix

\begin{abstract}

We propose Fast Equivariant Imaging (FEI), a novel unsupervised learning framework to efficiently train deep imaging networks without ground-truth data. From the perspective of reformulating the Equivariant Imaging based optimization problem via the method of Lagrange multipliers and utilizing plug-and-play denoisers, this novel unsupervised scheme shows superior efficiency and performance compared to vanilla Equivariant Imaging paradigm. In particular, our PnP-FEI scheme achieves an order-of-magnitude (10x) acceleration over standard EI on training U-Net with CT100 dataset for X-ray CT reconstruction, with improved generalization performance.


\end{abstract}

\section{Introduction}
In this work, we consider unsupervised learning of deep neural networks for solving inverse problems of the form:
\begin{equation}
    y = Ax^\dagger + \epsilon,
\end{equation}
with reference signal / image $x^\dagger \in \mathbb{R}^n$ to be estimated, noisy measurements $y \in  \mathbb{R}^m$, measurement noise $\epsilon \in \mathbb{R}^m$. $A \in \mathbb{R}^{m \times n}$ is the forward operator potentially with $m \ll n$, and can be a downsampling operator for super-resolution task, masks for inpainting, Gaussian linear measurements for compressive sensing, Radon transform for CT/PET, to name a few. In this setting, one can construct an MAP estimator for $x^\dagger$ by solving the following optimization problem with classical proximal splitting algorithms \citep{combettes2011proximal}:
\begin{equation}
    x^\star = \mathop{\arg \min}\limits_{x} \{f_\mr{mc}(Ax, y) + R(x)\},
\end{equation}
 where $f_\mr{mc}(x)$ is the measurement consistency (MC) term such as $\ell_1$ loss, $\ell_2$ loss and SURE-loss \citep{chen2022robust}, $R(x)$ is the prior or regularizer.

In unsupervised learning, given that we only have access to noisy measurements $\mathcal{Y}$, one can reconstruct the signal/image by learning a reconstruction function $G_{\theta}: \mathbb{R}^m \to \mathbb{R}^n$ such that $G_{\theta}(y) \approx x^\dagger$. By enforcing that the inverse mapping $G_{\theta}$ is consistent in the measurement domain, the following measurement consistence estimator (MC) can be obtained,
\begin{equation}
    \min_{\theta}\mathbb{E}_{y \in \mathcal{Y}} f_\mr{mc} ( AG_{\theta}(y) , y ).
    \tag{MC}
\end{equation}


However, the MC constraint is not enough to learn the inverse mapping, as it cannot capture information about the signal/image outside the range of the operator $A^\top$, we refer the interested reader to~\cite{chen2021equivariant} for details. 

In order to learn beyond the range space of $A^\top$, \cite{chen2021equivariant} takes advantage of some mild prior information mainly about the symmetries of plausible signal/image, $i.e.$, signal/image is invariant to certain groups of transformations, such as shifts, rotations, reflections, etc. According to invariance, the composition $G_{\theta} \circ A$ should be equivariant to the transformation $T_g$, $i.e.$
\begin{equation}
    G_{\theta} (AT_g x) = T_g G_{\theta}(Ax)
\end{equation}
where $T_g \in \mathbb{R}^{n \times n}$ are unitary matrices. This equivariant regularization leads to the following unsupervised learning paradigm:
\begin{equation}\label{eq: EI}
    \min_{\theta} \mathbb{E}_{y \in \mathcal{Y}, g \sim \mathcal{G}} \{f_\mr{mc} (y , AG_{\theta}(y) ) + \alpha \Vert T_g G_{\theta}(y) - G_{\theta}(AT_g G_{\theta}(y)) \Vert_2^2 \}.
\end{equation}
%\billy{since in this paper we do not use sketching, it should be better if we merge $G_\theta$ and $A^\dagger$ in one, to be more general. Meanwhile, I think we can put a more general description rather than the least-squares data-fit $\frac{1}{2} \Vert y - AG_{\theta}(y) \Vert_2^2$, something like $f_\mr{MC}(y, AG_{\theta}(y))$ -- to be more general to cover other possible options for data consistency term such as $\ell_1$ loss, or SURE loss, etc. }

This deep-learning-based unsupervised method has recently achieved state-of-the-art performance for a host of inverse problems~\citep{chen2021equivariant,chen2022robust, terris2024equivariant}. Their success has been attributed to their ability to explore group symmetry from a range of physics, at the cost of cumbersome and time-consuming training. However, one of the main challenges of this type of unsupervised schemes is the computational cost of training due to the slow convergence and large computational complexity across training iterations, particularly for large-scale inverse problems and advanced architectures such as unrolling \citep{monga2021algorithm,zhou2024deep}. In our recent work of Sketched EI \citep{xu2024sketched} we partially addressed the computational complexity issue for those inverse problems on which dimensionality reduction strategies can be applied. In this work we aimed to address the problem of slow convergence of standard optimizers such as Adam \citep{kingma2014adam} on minimizing this EI objective.

In this work, we explore from an optimization perspective to accelerate this promising unsupervised method via proximal alternating minimization \citep{afonso2010fast}, namely Fast Equivariant Imaging (FEI), for faster convergence. Our modification is achieved using an Lagrangian formulation of the problem, and is solved using an alternating-direction minimization method. From numerical experiments, we show that this fast EI method and its PnP variant (PnP-FEI) can improve both the convergence rate and performance.


\subsection{Relation to Prior Works}
Our method (FEI) is a significantly improved variant of Equivariant Imaging (EI)~\citep{chen2021equivariant,chen2022robust}, which is based on the alternating proximal gradient~\citep{driggs2021stochastic, afonso2010fast} optimization. The further PnP-FEI is a combination of the FEI and plug-and-play prior. It combines a pre-trained denoiser with an explicit EI prior and solves the problem by ADMM. 

We differ from~\cite{chen2021equivariant} in two important ways: First, the way they minimize the objective function is by optimizing the data consistency term and equivariance term uniformly in a single backpropagation, which hence enjoys moderate convergence and time-consuming training. In contrast, we consider a more aggressive minimization for the data consistency term via proximal alternating minimization. A second crucial difference is that within our FEI scheme, we can easily incorporate plug-and-play framework as implicit priors to further speed the convergence. In sharp contrast, the vanilla EI, by only exploiting group symmetry of the physics, can be seen as a special case of our proposed PnP-FEI. Although we focus only on accelerating EI in this work, the same algorithmic structure can be easily extended to more recent variants of EI such as Robust Equivariant Imaging (REI) \citep{chen2022robust}, Multi-Operator Imaging (MOI) \citep{tachella2022unsupervised}, and our recently proposed Sketched Equivariant Imaging (SkEI) \citep{xu2024sketched} which utilizes the dimensionality reduction techniques for acceleration.


\section{Proposed Methods}
\subsection{Fast Equivariant Imaging}
We propose solving the problem~\eqref{eq: EI} from an optimization point of view, which leads us to reformulate~\eqref{eq: EI} as follows
\begin{equation}\label{eq: fei}
    \min_{\theta, \mathbf{u}} \mathbb{E}_{y \in \mathcal{Y}, g \sim \mathcal{G}} \{f_\mr{mc}(y , A\mathbf{u}) + \alpha \Vert T_g G_{\theta}(y) - G_{\theta}(AT_g G_{\theta}(y)) \Vert_2^2 \}, \quad \text{s.t.} \quad \mathbf{u} = G_{\theta}(y).
\end{equation}

%\billy{Since this time we wish to also cover the case where we have a small dataset $Y$ (e.g., of 10 images) for training, to be more general we should include this when we present:\[ \min_{\theta, \mathbf{u}} \mb{E}_{y \sim Y, g \sim \mathcal{G}}\{ f_\mr{MC}(y, AG_\theta(y)) + \alpha \Vert T_g G_{\theta}(y) - G_{\theta}(AT_g G_{\theta}(y)) \Vert_2^2 \}, \quad \text{s.t.} \quad \mathbf{u} = G_{\theta}(y)\]}

 Typical choices for the measurement consistency term $f_\mr{mc}(x)$ includes $\ell_1$ loss, $\ell_2$ loss or SURE-loss \citep{chen2022robust}, etc. We simply substitute $G_{\theta}(y)$ with $\mathbf{u}$ in the MC term and further incorporate the EI regularizer. From another perspective, the neural network $G_{\theta}(y)$ in~\eqref{eq: EI} is replaced by an auxiliary variable $\mathbf{u}$. 

To solve this new problem with the choice of Euclidean norm of $f$, we first rewrite the Lagrangian with penalty parameter $\lambda$,
\begin{equation}
    \mathcal{L}_{\lambda, \alpha} (\mathbf{u}, \theta) = {\mathbb{E}_{y \in \mathcal{Y}, g \sim \mathcal{G}}} \{ f_\mr{mc}(y , A\mathbf{u}) + \frac{\lambda}{2} \Vert \mathbf{u} - G_{\theta}(y) \Vert_2^2 + \alpha \Vert T_g G_{\theta}(y) - G_{\theta}(AT_g G_{\theta}(y)) \Vert_2^2\}.
\end{equation}
The corresponding alternating minimization steps for this Lagrangian are
\begin{align}
    \mathbf{u}_{t+1} &\approx \arg \min_{\mathbf{u}} \mathcal{L}_{\lambda, \alpha}(\mathbf{u}, \theta_t)\label{eq: sub1}; \ \ \rightarrow \mathrm{\it\color{purple} Latent\ reconstruction\ step} \\
    \theta_{t+1} &\approx \arg \min_{\theta} \mathcal{L}_{\lambda, \alpha}(\mathbf{u}_{t+1}, \theta); \ \ \rightarrow \mathrm{\it\color{purple} Pseudo\ supervision\ step} \label{eq: sub2}
\end{align}
This Lagrangian with respect to $\mathbf{u}$ is convex, which means that the minimization over $\mathbf{u}$ can simply be obtained by first-order gradient descent, so the subproblem~\eqref{eq: sub1} is equivalent to the following:
\begin{equation}\label{eq: sub11}
    \min_{\mathbf{u}} { \mathbb{E}_{y \in \mathcal{Y}}} \{ f_\mr{mc}(y , A\mathbf{u}) + \frac{\lambda}{2} \Vert \mathbf{u} - G_{\theta}(y) \Vert_2^2 \},
\end{equation}
we propose solving~\eqref{eq: sub11} via Nesterov Accelerated Gradient (NAG)~\citep{nesterov1983method, nesterov2007gradient}, with the details present in Algorithm~\ref{alg:nag}. Of course, one could also use other optimizers such as stochastic gradient methods \citep{ehrhardt2024guide} (if the objective can be minibatched) or quasi-Newton methods \citep{tan2024provably} for this step.


However, the Lagrangian with respect to $\theta$ is nonconvex, which means the minimization over $\theta$ is often intractable. Here we bypass it by calling backpropagating over $\theta$ and taking one gradient descent step. The complete algorithm for Lagrangian-based fast equivariant imaging can be found in Algorithm~\ref{alg:LEI}.

\begin{algorithm}[tp!]
    \caption{Fast Equivariant Imaging (FEI)}
    \label{alg:LEI}
    \begin{algorithmic}[1]
        \Inputs{
        \begin{multicols}{2}
        \begin{itemize}
        \setlength{\itemsep}{-3pt}
        \setlength{\parsep}{-3pt}
        \setlength{\topsep}{-3pt}
            {\item $\mathcal{Y}$ - Observations (training dataset)} 
            \item $\lambda$ - Lagrangian multiplier
            \item $\alpha$ - EI regularization parameter
            %\item $z$ - network input
            \item $N$ - number of epochs
            \item $\mathbf{u}_0$ - initial NAG point
            \item $v_0$ - initial NAG velocity point
            \item $\beta$ - NAG momentum factor
            \item $\eta$ - NAG step size
            \item $J$ - number of NAG iterations
            \item $\mathcal{G}$ - Group of transformations
        \end{itemize}
        \end{multicols}
           }
        \Initialize{Neural network $G_{\theta}$, $\mathbf{u}_0 = A^\dagger y$, $v_0 = \mathbf{0}$}, $k=0$;
        \State{\textbf{For} $i=0, \cdots, N-1$ do:}
            {\State{\qquad \textbf{For} $y \in \mathcal{Y}$ do:}}
            \State{\qquad \qquad Sample $T_g$ where $g \sim \mathcal{G}$;}
            \State{\qquad \qquad Compute $x_0 = G_{\theta_k}(y)$, $\mathbf{u}_k = x_0$;}
            \State{\qquad \qquad Set $f(\mathbf{u}) = f_\mr{mc}(y, A\mathbf{u}) + \frac{\lambda}{2} \Vert \mathbf{u} - G_{\theta_k}(y) \Vert_2^2$;}
            \State{\qquad \qquad Update $\mathbf{u}_{k+1} = \mathcal{A}(f, J, \mathbf{u}_k, v_k, \beta, \eta)$  via NAG algorithm presented in Algorithm~\ref{alg:nag};}
            \State{\qquad \qquad Let $x_1 = \mathbf{u}_{k+1}$;}
            \State{\qquad \qquad Transform $x_2 = T_g(x_1)$;}
            \State{\qquad \qquad Compute $x_3 = G_{\theta_k}(A x_2)$;}
            \State{\qquad \qquad Update $\theta_{k+1}$ via progressively minimizing loss $\mathcal{L} = \mathbb{E}_{g \sim \mathcal{G}} \{ \Vert x_0 - x_1 \Vert^2_2 + \alpha \Vert x_2 - x_3 \Vert^2_2 \}$ using \par \qquad a gradient-based optimizer (such as Adam) in each iteration;}
            \State{\qquad \qquad$k \leftarrow k+1$}
            \State{\qquad \textbf{End For}}
            \State{\textbf{End For}}
        {\Output{$G_{\theta^\star}$}} 

    \end{algorithmic}
\end{algorithm}


\begin{algorithm}[htp!]
    \caption{Nesterov Accelerated Gradient (NAG) -- $\mathcal{A}(f, J, \mathbf{u}_0, v_0, \beta, \eta)$}
    \label{alg:nag}
    \begin{algorithmic}[1]
        \Inputs{Objective function $f$, number of iterations $J$, initial point $\mathbf{u}_0$, initial velocity point $v_0$, momentum factor $\beta$, step size $\eta$}
        \Output{Estimated point $\mathbf{u}_J$};
        \State{\textbf{For} $j=0, \cdots, J-1$ do:}
            \State{\quad Compute one-step ahead point $\mathbf{u}_{\text{ahead}} = \mathbf{u}_j - \beta v_j$;}
            \State{\quad Compute one-step ahead gradient $\nabla f(\mathbf{u}_{\text{ahead}})$;}
            \State{\quad Compute next velocity $v_{j+1} = \beta v_j + \eta \nabla f(\mathbf{u}_{\text{ahead}})$;}
            \State{\quad Update $\mathbf{u}_{j+1} = \mathbf{u}_j - v_{j+1}$;}
            \State{\textbf{End For}}

    \end{algorithmic}
\end{algorithm}

\subsection{Fast Plug-and-Play Equivariant Imaging}



The plug-and-play~\citep{venkatakrishnan2013plug} prior is a flexible framework that incorporates state-of-the-art denoising algorithms as priors in more challenging inverse problems. Our goal here is to bring this method to Fast Equivariant Imaging, in the hope of boosting its convergence rate and its performance as well.

Starting with~\eqref{eq: fei}, we turn the constraint into a penalty using the Augmented Lagrangian (AL)~\citep{afonso2010fast},
\begin{equation}\label{eq: alfei}
    \min_{\theta, \mathbf{u}} \mathbb{E}_{y \in \mathcal{Y}, g \sim \mathcal{G}} \{ f_\mr{mc}( y , A\mathbf{u}) + \alpha \Vert T_g G_{\theta}(y) - G_{\theta}( AT_g G_{\theta}(y)) \Vert_2^2 + \frac{\lambda}{2} \Vert \mathbf{u} - G_{\theta} (y) \Vert_2^2 + \lambda \mathbf{L}^T(\mathbf{u} - G_{\theta}(y))  \},
\end{equation}
where $\mathbf{L}$ stands for the Lagrange multiplier vector for the set of equality constraints, and $\lambda$ is a free parameter to be chosen. Merging the last two terms, we get the scaled form of~\eqref{eq: alfei},
\begin{equation}
    \min_{\theta, \mathbf{u, L}} { \mathbb{E}_{y \in \mathcal{Y}, g \sim \mathcal{G}}} \{ f_\mr{mc}(y, A\mathbf{u}) + \alpha \Vert T_g G_{\theta}(y) - G_{\theta}(AT_g G_{\theta}(y)) \Vert_2^2 + \frac{\lambda}{2} \Vert \mathbf{u} - G_{\theta} (y) - \mathbf{L} \Vert_2^2 \}.
\end{equation}
The remedy for this problem comes in the form of the Alternating Directions Method of Multipliers~\citep{boyd2011distributed}(ADMM), which amounts to a sequential update of the three unknowns in this expression: $\theta$, $\mathbf{u}$, and $\mathbf{L}$. Fixing $\theta_k, \mathbf{L}_k$, $\mathbf{u}$ should be updated by solving
\begin{equation}\label{eq: alfei-sub1}
    \mathbf{u}_{k+1} = \mathop{\arg\min}_{\mathbf{u}} f_\mr{mc}( y , A\mathbf{u}) + \frac{\lambda}{2} \Vert \mathbf{u} - G_{\theta_k}(y) - \mathbf{L}_k \Vert_2^2,
\end{equation}
This is a strictly convex quadratic function to be minimized, which can be solved exactly (naturally, up to numerical precision) as follows (for the case where $\ell_2$ loss is used for MC term):
\begin{equation}
    \mathbf{u}_{k+1} = (A^T A+\lambda I)^{-1} \cdot (A^T y + \lambda G_{\theta_k}(y) + \lambda \mathbf{L}_k).
\end{equation}
However, solving this linear system exactly often requires enormous computational efforts, which hinders the convergence of the algorithm, and we suggest solving it in one of two ways: The first option is to use the fixed-point strategy as presented in Algorithm~\ref{alg:nag}, applying the Nesterov Accelerated Gradient update several times provides the necessary update for $\mathbf{u}$. An alternative approach to update $\mathbf{u}$ is Plug-and-Play, for the Lagrangian quadratic data-fidelity term~\eqref{eq: alfei-sub1}, the classical PnP algorithm reads %notice that~\eqref{eq: alfei-sub1} is formally similar to the \textit{maximum a posterior} (MAP) estimate of $\mathbf{u}$, from observation $y = A\mathbf{u}+\mathbf{n}$ (where $\mathbf{n}$ is white Gaussian noise of variance $\frac{1}{\lambda}$) under a Gaussian prior of mean $G_{\theta_k}(y) + \mathbf{L}_k$ and covariance $I$, representing a denoising of the signal/image $G_{\theta_k}(y) + \mathbf{L}_k$,
\begin{equation}\label{eq: fei-sub1-pnp}
    \mathbf{u}_{k+1} = \mathcal{D}( \mathbf{u}_k - \eta[  \nabla f_\mr{mc}( y , A\mathbf{u}_k) + \lambda (\mathbf{u}_k - G_{\theta_k}(y) - \mathbf{L}_k)]),
\end{equation}
where $\mathbf{u}_{k+1}$ is obtained by one step gradient descent and then denoising, and $\mathcal{D}(\cdot)$ represents classical denoisings such as BM3D~\citep{dabov2007image}, DnCNN~\citep{zhang2017beyond}, etc. This motivates us to solve~\eqref{eq: alfei-sub1} in a proximal way and replace the proximal operator with other denoising algorithms, in a similar fashion to Plug-and-Play.

Fixing $\mathbf{u}_{k+1}, \mathbf{L}_k$, the update of $\theta$ is done by solving
\begin{equation}
    \theta_{k+1} = \mathop{\arg\min}\limits_{\theta} \ {\mathbb{E}_{y \in \mathcal{Y}, g \sim \mathcal{G}}} \ \alpha \Vert T_g G_{\theta}(y) - G_{\theta} (A T_g G_{\theta}(y)) \Vert_2^2 + \frac{\lambda}{2} \Vert \mathbf{u}_{k+1} - G_{\theta}(y) - \mathbf{L}_k \Vert_2^2,
\end{equation}
which can be updated by calling backpropagating and taking one gradient descent step over $\theta$.

As for the Lagrange multiplier vector $\mathbf{L}$, its update is much easier, given by
\begin{equation}
    \mathbf{L}_{k+1} = \mathbf{L}_k -\mathbf{u}_{k+1} + G_{\theta_{k+1}}(y)
\end{equation}
as emerging from the AL method~\citep{afonso2010fast}. Algorithm~\ref{alg:PnP-LEI} summarizes the steps to be taken to apply this overall algorithm to handle minimization of the objective of equivariant imaging. Moreover, taking into account of more recent equivariant PnP \citep{terris2024equivariant,tang2024practical}, we can also modify the PnP step with equivariant denoisers. We present this option in Algorithm \ref{alg:EQPnP-LEI}.


\begin{algorithm}[tp!]
\caption{Fast Equivariant Imaging with Plug-and-Play (PnP-FEI)}
    \label{alg:PnP-LEI}
    \begin{algorithmic}[1]
        \Inputs{
        \begin{multicols}{2}
        \begin{itemize}
        \setlength{\itemsep}{-3pt}
        \setlength{\parsep}{-3pt}
        \setlength{\topsep}{-3pt}
            {\item $\mathcal{Y}$ - Observations (training dataset)}
            \item $\mathbf{L}$ - Augmented Lagrangian multiplier
            \item $\lambda$ - Augmented Lagrangian free parameter
            \item $\mathcal{D}(\cdot)$ - Denoiser
            \item $\alpha$ - EI regularization parameter
            %\item $z$ - network input
            \item $N$ - number of epochs
            \item $\mathcal{G}$ - Group of transformations
            {\item $\mathbf{u}$ - Initial gradient descent point of~\eqref{eq: fei-sub1-pnp}} 
            {\item $\gamma$ - Gradient descent step size in PnP step}
        \end{itemize}
        \end{multicols}
           }
        \Initialize{Neural network $G_{\theta}$, $\mathbf{L}_0 = \mathbf{0}$, $\mathbf{u}_0 = \mathbf{0}$, $k=0$;}
        \State{\textbf{For} $i=0, \cdots, N-1$ do:}
            {\color{blue}\State{\qquad \textbf{For} $y \in \mathcal{Y}$ do:}}
            \State{\qquad \qquad Sample $T_g$ where $g \sim \mathcal{G}$;}
            \State{\qquad \qquad Compute $x_0 = G_{\theta_k}(y)$, by default let $\mathbf{u}_k = x_0$;}
            {\color{blue}\State{\qquad \qquad Update $\mathbf{u}_{k+1} = \mathcal{D}
            [\mathbf{u}_k - \gamma[  \nabla f_\mr{mc}( y , A\mathbf{u}_k) + \lambda (\mathbf{u}_k - G_{\theta_k}(y) - \mathbf{L}_k^{(y)})]]$}}
            {\State{\qquad \qquad Let $x_1 = \mathbf{u}_{k+1}$;}}
            \State{\qquad \qquad Transform $x_2 = T_g(x_1)$;}
            \State{\qquad \qquad Compute $x_3 = G_{\theta_k}( A x_2)$;}
            \State{\qquad \qquad Update $\theta_{k+1}$ via progressively minimizing $\mathcal{L} = \mathbb{E}_{ g \sim \mathcal{G}} \{ \Vert x_0 + \mathbf{L}_k^{(y)} - x_1 \Vert^2_2 + \alpha \Vert x_2 - x_3 \Vert^2_2 \}$ \par \qquad using an adaptive gradient-based optimizer (such as Adam) in each iteration;}
            \State{\qquad \qquad Update $\mathbf{L}_{k+1}^{(y)} = \mathbf{L}_k^{(y)} - x_1 + G_{\theta_{k+1}}(y)$;}
            \State{\qquad \qquad$k \leftarrow k+1$}
            \State{\qquad \textbf{End For}}
            \State{\textbf{End For}}
        {\Output{$G_{\theta^\star}$}}

    \end{algorithmic}
\end{algorithm}


\begin{algorithm}[tp!]
    \caption{FEI with Equivariant Plug-and-Play (EQPnP-FEI)}

    \label{alg:EQPnP-LEI}
    \begin{algorithmic}[1]
        \Inputs{
        \begin{multicols}{2}
        \begin{itemize}
        \setlength{\itemsep}{-3pt}
        \setlength{\parsep}{-3pt}
        \setlength{\topsep}{-3pt}
            {\item $\mathcal{Y}$ - Observations (training dataset)}
            \item $\mathbf{L}$ - Augmented Lagrangian multiplier
            \item $\lambda$ - Augmented Lagrangian free parameter
            \item $\mathcal{D}(\cdot)$ - Denoiser
            \item $\alpha$ - EI regularization parameter
            %\item $z$ - network input
            \item $N$ - number of epochs
            \item $\mathcal{G}$ - Group of transformations
            {\item $\mathbf{u}$ - Initial gradient descent point of~\eqref{eq: fei-sub1-pnp}} 
            {\item $\gamma$ - Gradient descent step size in PnP step}
        \end{itemize}
        \end{multicols}
           }
        \Initialize{Neural network $G_{\theta}$, $\mathbf{L}_0 = \mathbf{0}$, $\mathbf{u}_0 = \mathbf{0}$, $k=0$;}
        \State{\textbf{For} $i=0, \cdots, N-1$ do:}
            {\color{blue}\State{\qquad \textbf{For} $y \in \mathcal{Y}$ do:}}
            \State{\qquad \qquad Sample $T_g$, $T_{g'}$ where $g \sim \mathcal{G}$, $g' \sim \mathcal{G}$;}
            \State{\qquad \qquad Compute $x_0 = G_{\theta_k}(y)$, by default let $\mathbf{u}_k = x_0$;}
            {\color{blue}\State{\qquad \qquad Update $\mathbf{u}_{k+1} = T_{g'}^{-1}\mathcal{D}
            [T_{g'}[\mathbf{u}_k - \gamma[  \nabla f_\mr{mc}( y , A\mathbf{u}_k) + \lambda (\mathbf{u}_k - G_{\theta_k}(y) - \mathbf{L}_k^{(y)})]]]$}}
            {\State{\qquad \qquad Let $x_1 = \mathbf{u}_{k+1}$;}}
            \State{\qquad \qquad Transform $x_2 = T_g(x_1)$;}
            \State{\qquad \qquad Compute $x_3 = G_{\theta_k}( A x_2)$;}
            \State{\qquad \qquad Update $\theta_{k+1}$ via progressively minimizing $\mathcal{L} = \mathbb{E}_{ g \sim \mathcal{G}} \{ \Vert x_0 + \mathbf{L}_k^{(y)} - x_1 \Vert^2_2 + \alpha \Vert x_2 - x_3 \Vert^2_2 \}$ \par \qquad using an adaptive gradient-based optimizer (such as Adam) in each iteration;}
            \State{\qquad \qquad Update $\mathbf{L}_{k+1}^{(y)} = \mathbf{L}_k^{(y)} - x_1 + G_{\theta_{k+1}}(y)$;}
            \State{\qquad \qquad$k \leftarrow k+1$}
            \State{\qquad \textbf{End For}}
            \State{\textbf{End For}}
        {\Output{$G_{\theta^\star}$}}

    \end{algorithmic}
\end{algorithm}





