\section{Appendix - Commutativity of the transfer matrices}
To show that (\ref{ctm}) holds, first observe that the left-hand side is a fourth-order polynomial in the $T^j_k(u),\,T^p_q(v)$. 
Using the cyclic rule of trace, Jacobi identity (\ref{ji}), Leibniz property (\ref{lp}), and (\ref{yba}) allows for the order to be reduced step-by-step. How the calculation evolves depends on the order in which the manipulations are taken. Here we sketch out the relevant steps. First
%
\begin{align*}
[t(u),\,t(v)]&={\rm tr}_{12}([T_1(u) T_1(u),\,T_2(v)T_2(v)]) \\
&={\rm tr}_{12}(T_1(u)T_2(v)[T_1(u),\,T_2(v)] + T_1(u)[T_1(u),\,T_2(v)]T_2(v) \\
&\qquad + T_2(v)[ T_1(u),\,T_2(v)]T_1(u) + [T_1(u),\,T_2(v)]T_2(v)T_1(u)) \\ 
&={\rm tr}_{12}(T_1(u)T_2(v)([T_2(v),\,r_{12}(u,v)] - [T_1(u),\,r_{21}(v,u)] ) ) \\
&\qquad + {\rm tr}_{12}(T_1(u)([T_2(v),\,r_{12}(u,v)] - [T_1(u),\,r_{21}(v,u)] )T_2(v) ) \\ 
&\qquad + {\rm tr}_{12}(T_2(v)([T_2(v),\,r_{12}(u,v)] - [T_1(u),\,r_{21}(v,u)] )T_1(u) ) \\ 
&\qquad + {\rm tr}_{12}(([T_2(v),\,r_{12}(u,v)] - [T_1(u),\,r_{21}(v,u)] )T_2(v)T_1(u) ) 
\end{align*}
which reduces to the compact form
%
\begin{align*}
[t(u),\,t(v)]
&={\rm tr}_{12}([T_2(v),\,[r_{21}(v,u)T_1(u),\,T_1(u)]]). 
\end{align*}
Using the relations (\ref{yba}) to reduce further to a quadratic expression leads to 
\begin{align*}
[t(u),\,t(v)]={\rm tr}_{12}([[T_1(u),\,r_{21}(v,u)],\,[T_2(v),\,r_{12}(u,v)]]).
\end{align*} 
To advance the calculations to the next stage, we find it useful to incorporate the use of partial transpositions on the second component of the tensor product, denoted $t_2$, leading to  
\begin{align*}
[t(u),\,t(v)]
&= {\rm tr}_{12}( [T_1(u),\, T^{t_2}_2(v)] (r^{t_2}_{21}(v,u) r^{t_2}_{12}(u,v) +r^{t_2}_{12}(u,v)
r^{t_2}_{21})(v,u))  \\
&\qquad -  {\rm tr}_{12}([T_1(u),\, T_2(v)](r_{21}(v,u)r_{12}(u,v) +r_{12}(u,v)r_{21}(v,u)) ). 
\end{align*}
From (\ref{yba}) it follows that 
\begin{align*}
[T_{1}(u),\,T^{t_2}_{2}(v)]
=[r_{12}^{t_2}(u,v),\, T^{t_2}_2(v)] - [T_1(u),\,r^{t_2}_{21}(v,u)]
%\label{yba}
\end{align*}
which is employed to make the final simplification to
%
\begin{align*}
[t(u),\,t(v)]=
&= {\rm tr}_{12}(T_2(v) r^{t_1}_{12}(u,v) r^{t_1}_{12}(u,v) r^{t_1}_{21}(v,u)-  T_2(v) r_{12}(u,v)r_{12}(u,v)r_{21}(v,u))   \\
&\qquad +   {\rm tr}_{12}(T_2(v)r_{21}(v,u) r_{12}(u,v)r_{12}(u,v)  -T_2(v) r^{t_1}_{21}(v,u)r^{t_1}_{12}(u,v)r^{t_1}_{12}(u,v))  \\
&\qquad +{\rm tr}_{12}(T_1(u) r_{21}(v,u)r_{21}(v,u)r_{12}(u,v)
- T_1(u) r^{t_2}_{21}(v,u)r^{t_2}_{21}(v,u)r^{t_2}_{12}(u,v)) 
    \\
&\qquad 
+{\rm tr}_{12}(T_1(u)r^{t_2}_{12}(u,v)r^{t_2}_{21}(v,u)r^{t_2}_{21}(v,u)- T_1(u)r_{12}(u,v)r_{21}(v,u)r_{12}(u,v) ) .
\end{align*}
The above vanishes provided 
\begin{align}
[r_{12}(u,v),\,r_{21}(v,u)]&=0, \label{c1}\\
[r^{t_2}_{12}(u,v),\,r^{t_2}_{21}(v,u)]&=0. \label{c2} 
\end{align}
Eq. (\ref{c1}) may be verified from (\ref{rm}) in a direct fashion. Checking the validity of (\ref{c2}) is more involved and relies on
a choice of $A$ satisfying ${\rm tr}(A)=0$, which is the case for (\ref{a}). 

