\section{Preliminaries}\label{sec:preliminaries}
%----------------------subsection-------------------------%
In Section~\ref{subsec: prem QAA}, we recall the definition of quantum Kac-Moody algebras, which include both non-twisted and twisted quantum affine algebras. In Section~\ref{subsec: prem non twisted} and Section~\ref{subsec: prem twisted type}, we review the representation theory of non-twisted quantum affine algebras and twisted quantum affine algebras, respectively. In Section~\ref{subsec: folding}, we recall known results that establish the relations between twisted and non-twisted types via the folding process. Finally, in Section~\ref{subsec: prem Langlands}, we recall the definition of Langlands dual algebras and the conjectures of Frenkel and Hernandez on Langlands dual representations.


\subsection{Quantum Kac-Moody algebras}\label{subsec: prem QAA}

For $N \in \NN^*$, an $N \times N$ matrix $C$ is called a generalized Cartan matrix if $C_{ij} \in \mathbb{Z}$ ($\forall i,j$), $C_{ii}=2$ ($\forall i$), $C_{ij} \leq 0$ ($\forall i \neq j$) and $C_{ij}=0$ if and only if $C_{ji}=0$. We suppose that $C$ is symmetrizable, that is, there exists a diagonal matrix $D = \mathrm{diag}(d_1,\dots,d_N)$ such that the matrix $DC$ is symmetric. A generalized Cartan matrix $C$ is said to be of affine type if its determinant is $0$ and all of its principal minors are positive. In the affine type, the positive integers $d_i$ are unique up to a scalar. We fix them so that $\mathrm{min}(d_i) = 1$. See \cite[Section~4.5]{kac1990infinite} for the classification of affine Cartan matrices. 

Let $q \in \mathbb{C}^*$ be such that $q$ is not a root of unity. Denote by $q_i = q^{d_i}$.

\begin{definition}
    Let $C$ be a generalized Cartan matrix of affine type. The quantum Kac-Moody algebra $\mathcal{U}_q(\mathfrak{g}(C))$ is the associative $\mathbb{C}$-algebra with generators $k_{i}^{\pm 1} , e_i^{\pm} \; (1 \leq i \leq N)$, and relations
	\begin{equation*}
		\begin{split}
			&k_i k_i^{-1} = k_i^{-1}k_i = 1, \; k_ik_j = k_jk_i,\\
			&k_ie_j^{\pm} = q_i^{\pm C_{i,j}}e_j^{\pm}k_i,\\
			&[e_i^{+},e_j^{-}] = \delta_{i,j} \frac{k_i-k_i^{-1}}{q_i - q_i^{-1}}, \forall i,j,\\
			&\sum_{r=0}^{1-C_{i,j}} (-1)^r(e_i^{\pm})^{(1-C_{i,j}-r)} e_j^{\pm} (e_i^{\pm})^{(r)} = 0 \; \text{for} \; i \neq j,
		\end{split}
	\end{equation*}
	where $(e_i^{\pm})^{(r)} = \frac{(e_i^{\pm})^r}{[r]_{q_i}!}$, $[r]_{q_i}! = [r]_{q_i} [r-1]_{q_i} \cdots [1]_{q_i}$, and $ [m]_{q_i}$ is the $q$-number $[m]_{q_i} = \frac{q_i^m-q_i^{-m}}{q_i-q_i^{-1}}$. We use the convention that $[0]_q = 0$, $[0]_q! = 1$.
\end{definition}

In this paper, we are interested in the affine type $A_{2n-1}^{(1)}$, $B_{n}^{(1)}$ and $A_{2n-1}^{(2)}$, $n \geq 2$. As in \cite[Section~4.5]{kac1990infinite}, we use the set of indices as follows:

In type $A_{2n-1}^{(1)}$, $N = 2n$. The set of indices is $\hat{I} = I \sqcup \{0\}$, consisting of the index set $I = \{1,2,\dots,2n-1\}$ of the Lie algebra $\mathfrak{sl}_{2n}$ and an extra index $0$. The generalized Cartan matrix of type $A_{2n-1}^{(1)}$ is 
\[
\left(
\scalebox{0.8}{$\begin{array}{cccccccc}
2 & -1 &        &        &        &        &        &     -1   \\
-1 & 2 & -1     &        &        &        &        &        \\
   & -1 & 2 & -1     &        &        &        &        \\
   &    & -1 & \ddots & \ddots &        &        &        \\
   &    &    & \ddots & \ddots & -1     &        &        \\
   &    &    &        & -1 & 2 & -1     &        \\
   &    &    &        &    & -1 & 2 & -1 \\
 -1  &    &    &        &    &    & -1 & 2
\end{array}$}
\right),
\]
where the order of labels of the matrix is $0,1,2,\dots,2n-1$.

In type $B_n^{(1)}$, $N = n+1$. The set of indices is $\hat{I} = I \sqcup \{0\}$, consisting of the index set $I = \{1,2,\dots,n\}$ of the Lie algebra $\mathfrak{so}_{2n+1}$ and an extra index $0$. Here $n$ is the index for the short root of $\mathfrak{so}_{2n+1}$. The generalized Cartan matrix of type $B_{n}^{(1)}$ is 
\[
\left(
\scalebox{0.8}{$\begin{array}{cccccccc}
2 & 0 &  -1      &        &        &        &        &        \\
0 & 2 & -1     &        &        &        &       &        \\
-1   & -1 & 2 & -1     &        &        &        &        \\
   &    & -1 & \ddots & \ddots &        &        &        \\
   &    &    & \ddots & \ddots & -1     &        &        \\
   &    &    &        & -1 & 2 & -1     &        \\
   &    &    &        &    & -1 & 2 & -1 \\
   &    &    &        &    &    & -2 & 2
\end{array}$}
\right),
\]
where the order of labels of the matrix is $0,1,2,\dots,n$.

In type $A_{2n-1}^{(2)}$, $N = n+1$. The set of indices is $\hat{I}^{\sigma} = I \sqcup \{0\}$, consisting of the index set $I = \{\bar{1},\dots,\bar{n}\}$ and an extra index $0$. Here we remark that the set $I$ arises from the orbits of the involution on the Dynkin diagram of type $A_{2n-1}$. We use the notation with a bar to emphasize that we are in the twisted case. The generalized Cartan matrix of type $A_{2n-1}^{(2)}$ is 
\[
\left(
\scalebox{0.8}{$\begin{array}{cccccccc}
2 & 0 &  -1      &        &        &        &        &        \\
0 & 2 & -1     &        &        &        &       &        \\
-1   & -1 & 2 & -1     &        &        &        &        \\
   &    & -1 & \ddots & \ddots &        &        &        \\
   &    &    & \ddots & \ddots & -1     &        &        \\
   &    &    &        & -1 & 2 & -1     &        \\
   &    &    &        &    & -1 & 2 & -2 \\
   &    &    &        &    &    & -1 & 2
\end{array}$}
\right),
\]
where the order of labels of the matrix is $0,\bar{1},\bar{2},\dots,\bar{n}$.

Quantum Kac–Moody algebras can be defined as affinizations of finite-type quantum groups via Drinfeld’s realization \cite{drinfeld1987new, chari1998twisted, damiani2015from}. We do not list the generators and relations here, as they will not be used in an essential way. We note, however, that there exists a large commutative subalgebra $\Uqhaffine$, generated by elements $\phi_{i,\pm k}^{\pm}$ ($i \in I, k \geq 0$) in Drinfeld's realization.

Denote by
    \[\phi_{i}^{\pm}(u) = \sum_{k=0}^{\infty} \phi_{i,\pm k}^{\pm} u^{\pm k}, \quad i \in I.\]

In accordance with common terminology, we will also call a quantum Kac-Moody algebra of non-twisted affine type as a non-twisted quantum affine algebra, and a quantum Kac-Moody algebra of twisted affine type as a twisted quantum affine algebra.

%----------------------subsection-------------------------%

\subsection{Non-twisted type}\label{subsec: prem non twisted}
Let $\mathfrak{h}$ be the Cartan subalgebra of the finite-dimensional Lie algebra $\g$, 
and $\mathfrak{h}^*$ be its dual vector space.
Let $\omega_i \in \mathfrak{h}^*$ ($i \in I$) be the fundamental weights of $\g$, and $\alpha_i \in \mathfrak{h}^*$ ($i \in I$) be the simple roots of $\g$. $\mathfrak{h}^*$ is equipped with an inner product $\langle, \rangle$ such that $\langle \alpha_i,\omega_j \rangle = d_i \delta_{ij}$.

Let $\Uqghat$ be a quantum Kac-Moody algebra of non-twisted affine type. In this paper, it will be of type $A_{2n-1}^{(1)}$ or $B_n^{(1)}$. For a finite-dimensional representation $V$ of $\Uqghat$, an element $\lambda \in \mathfrak{h}^*$ is called a weight of $V$ if the space
\[V_{\lambda} := \{v \in V~|~k_i v = q^{\langle \alpha_i,\lambda \rangle}v, \forall i \in I \}\]
is non zero. 

Denote by $P = \bigoplus_{i \in I} \ZZ \omega_i$ the weight lattice of $\g$.

The \textit{usual character} of a finite-dimensional representation $V$ of $\Uqghat$ is defined as
\[\chi(V) = \sum_{\lambda \in P} \dim(V_{\lambda})[{\lambda}].\]
This is an element in the abelian group $\ZZ[P]$ generated by formal symbols $[\lambda]$, $\lambda \in P$. We remark that the usual character is defined as a $\g$-character for the finite-dimensional simple Lie algebra $\g$, it should not be confused with the $\hatg$-character of the affine Kac-Moody algebra as considered in \cite{kac1990infinite,lusztig1993introduction}. However, since we consider only finite-dimensional representations, the $\g$-character contains the same information as the $\hatg$-character in this context.

Then we recall the $q$-characters of finite-dimensional representations of $\Uqghat$.

For any $\Uqghat$-module $V$, a set of complex numbers $\bpsi = (\psi_{i,\pm m}^{\pm})_{i \in I, m \in \NN}$ is called an $l$-weight of $V$ if the space 
$\{v \in V~|~\phi_{i,\pm m}^{\pm}.v = \psi_{i,\pm m}^{\pm}v \}$ is non zero. It was proved in \cite{frenkel1999q} that any $l$-weight of a finite-dimensional representation $V$ of $\Uqghat$ is of the form
\[\sum_{m \geq 0} \psi^{\pm}_{i, \pm m} u^{\pm m} = q^{\deg(P_i) - \deg(R_i)}\frac{P_i(uq_i^{-1})R_i(uq_i)}{P_i(uq_i)R_i(uq_i^{-1})} \]
expanded in $\CC \llbracket u \rrbracket$ (resp. in $\CC \llbracket u^{-1} \rrbracket$), for some polynomials $P_i$ and $R_i$ satisfying $P_i(0) = R_i(0) = 1$.

The $q$-characters of finite-dimensional representations of $\Uqghat$ were defined by Frenkel and Reshetikhin (and their Yangian analogues were defined by Knight) \cite{frenkel1999q,knight1995spectra}. Let $V$ be a finite-dimensional representation of $\Uqghat$,

\[\chi_q(V) = \sum_{\bpsi} \dim(V_{\bpsi}) m_{\bpsi} \in \ringYa,\]
where $m_{\bpsi} = \prod_{i\in I,a\in \CC^*} Y_{i,a}^{p_{i,a}-r_{i,a}}$, $P_i(u) = \prod_{a \in \CC^*} (1-au)^{p_{i,a}}$, $R_i(u) = \prod_{a \in \CC^*} (1-au)^{r_{i,a}}$,
and
	\[V_{\bpsi} := \{v \in V~|~\exists p \geq 0, \forall i \in I,m \geq 0, (\phi_{i,\pm m}^{\pm} - \psi_{i,\pm m}^{\pm})^p.v = 0 \}.\]

The irreducible finite-dimensional representations of $\Uqghat$ are classified by $l$-highest weight representations \cite{chari1991quantum,chari1995quantum}. An $l$-highest weight representation of $\Uqghat$ is a $\Uqghat$-module $V$ generated by a vector $v_0 \in V$ such that 
	\[x_{i,k}^+.v_0 = 0, \; \phi_{i,\pm m}^{\pm}.v_0 = \psi_{i,\pm m}^{\pm}v_0, \quad \forall i \in I, k \in \ZZ, m \in \NN, \]
for some complex numbers $\psi_{i,\pm m}^{\pm} \in \CC$ ($i \in I, m \in \NN$). We call such $\bpsi = (\psi_{i,\pm m}^{\pm})_{i \in I, m \in \NN}$ and its corresponding monomial $m_{\bpsi} \in \ringYa$ a highest $l$-weight of $V$.

A monomial $m = \prod_{i \in I,a \in \CC^*} Y_{i,a}^{u_{i,a}} \in \ringYa$ is called dominant if $u_{i,a} \geq 0$, $\forall i \in I, a \in \CC^*$.

\begin{theorem}[\cite{chari1991quantum,chari1995quantum}]
    For each dominant monomial $m = \prod_{i \in I,a \in \CC^*} Y_{i,a}^{u_{i,a}} \in \ringYa$, there is a unique irreducible finite-dimensional $l$-highest weight representations of $\Uqghat$ with highest $l$-weight $m$. We denote this irreducible representation by $L(m)$.

    Moreover, any irreducible finite-dimensional representation of $\Uqghat$ is of this form.
\end{theorem}

The usual character $\chi(V)$ can be easily recovered from the $q$-character $\chi_q(V)$ as follows. The map $\prod_{i,a} Y_{i,a}^{u_{i,a}} \mapsto [\sum_{i,a} u_{i,a} \omega_i]$ generates a homomorphism $\ZZ[Y_{i,a}^{\pm 1}]_{i \in I,a \in \CC^*} \to \ZZ[P]$. The image of $\chi_q(V)$ under this homomorphism is exactly the usual character $\chi(V)$ \cite[Theorem~3]{frenkel1999q}.

\subsection{Twisted type}\label{subsec: prem twisted type}
The character theory for quantum Kac-Moody algebras of twisted affine type is parallel to that of non-twisted type \cite{chari1998twisted,hernandez2010kirillov,wang2023qq}. Let $\Uqghatsigma$ be a quantum Kac-Moody algebra of twisted affine type. 

In this paper, $\Uqghatsigma$ will be of type $A_{2n-1}^{(2)}$. Recall that in this case, the index set $I = \{\bar{1},\dots,\bar{n}\}$. Let $\leftindex^L {\mathfrak{h}}^* = \bigoplus_{i \in I} \CC \check{\omega}_i$ and  $\leftindex^L {P} = \bigoplus_{i \in I} \ZZ \check{\omega}_i$. For now, the symbols $\check{\omega}_i$, $\leftindex^L {\mathfrak{h}}^*$ and $\leftindex^L {P}$ are simply notations used to distinguish the twisted types from the non-twisted types; the reason for this choice of notation will become clear in Section~\ref{subsec: prem Langlands}.

For a finite-dimensional representation $V$ of $\Uqghatsigma$, an element $\lambda \in \leftindex^L{\mathfrak{h}}^*$ is called a weight of $V$ if the space 
\[V_{\lambda} := \{v \in V~|~k_i v = q^{\langle \check{\alpha}_i,\lambda \rangle}v, \forall i \in I \}\]
is non zero. Here $\langle, \rangle$ is the inner product on $\leftindex^L {\mathfrak{h}}^*$ such that $\langle \check{\alpha}_i,\check{\omega}_j \rangle = \check{d}_i \delta_{ij}$, where $\check{d}_i$ are entries of the diagonal matrix $D$ which symmetrize the generalized Cartan matrix $C$ of type $A_{2n-1}^{(2)}$.

The usual character of a finite-dimensional representation $V$ of $\Uqghatsigma$ is defined as
\[\chi^{\sigma}(V) = \sum_{\lambda \in \leftindex^L{P}} \dim(V_{\lambda})[{\lambda}],\]
which is an element in the abelian group $\ZZ[\leftindex^L{P}]$ generated by formal symbols $[\lambda]$, $\lambda \in \leftindex^L {P}$.

In Drinfeld realization of twisted quantum affine algebras, there are elements 
$$\phi_{i,\pm m}^{\pm},\quad i \in I, m \in \NN^*,$$ 
where $\phi_{\bar{n},\pm m}^{\pm} = 0$ if $m$ is odd.

Similarly, for any $\Uqghatsigma$-module $V$, a set of complex numbers $\bpsi = (\psi_{i,\pm m}^{\pm})_{i \in I, m \in \NN}$, is called an $l$-weight of $V$ if the space 
$\{v \in V~|~\phi_{i,\pm m}^{\pm}.v = \psi_{i,\pm m}^{\pm}v \}$ is non zero, and any $l$-weight of a finite-dimensional representation $V$ of $\Uqghat$ is of the form
\[\sum_{m \geq 0} \psi^{\pm}_{i, \pm m} u^{\pm m} = q^{\deg(P_i) - \deg(R_i)}\frac{P_i(uq_i^{-1})R_i(uq_i)}{P_i(uq_i)R_i(uq_i^{-1})} \]
expanded in $\CC \llbracket u \rrbracket$ (resp. in $\CC \llbracket u^{-1} \rrbracket$), for some polynomials $P_i$ and $R_i$ which satisfy that $P_i(0) = R_i(0) = 1$ and that $P_{\bar{n}}$ and $R_{\bar{n}}$ have only even degree terms.

As in \cite{wang2023qq}, we consider the commutative ring
\[\mathcal{Z} := \ZZ[Z_{i,a}^{\pm 1}]_{i \in I,a \in \CC^*}/(Z_{\bar{n},a}^{\pm 1} = Z_{\bar{n},-a}^{\pm 1})_{a \in \CC^*}.\]

The $q$-character of a finite-dimensional representation $V$ of $\Uqghatsigma$ is

\[\chi_q^{\sigma}(V) = \sum_{\bpsi} \dim(V_{\bpsi}) m_{\bpsi} \in \mathcal{Z},\]
where $m_{\bpsi} = \prod_{i\in I,a\in \CC^*} Z_{i,a}^{p_{i,a}-r_{i,a}}$, $P_i(u) = \prod_{a \in \CC^*} (1-au)^{p_{i,a}}$, $R_i(u) = \prod_{a \in \CC^*} (1-au)^{r_{i,a}}$ when $i \neq \bar{n}$, and $P_{\bar{n}}(u) = \prod_{a \in \CC^*} (1-a^2u^2)^{p_{\bar{n},a}}$, $R_{\bar{n}}(u) = \prod_{a \in \CC^*} (1-a^2u^2)^{r_{\bar{n},a}}$,
and the $l$-weight space
	\[V_{\bpsi} := \{v \in V~|~\exists p \geq 0, \forall i \in I,m \geq 0, (\phi_{i,\pm m}^{\pm} - \psi_{i,\pm m}^{\pm})^p.v = 0 \}.\]

Similar to non-twisted type, irreducible finite-dimensional representations of $\Uqghatsigma$ are classified by $l$-highest weight representations $L(m)$ with monomial $m = \prod_{i \in I,a \in \CC^*} Z_{i,a}^{u_{i,a}} \in \mathcal{Z}$ such that $u_{i,a} \geq 0$, $\forall i \in I, a \in \CC^*$, which are defined in the same way as in non-twisted type.

As in the non-twisted case, the usual character of a finite-dimensional representation $V$ of $\Uqghatsigma$ can be recovered from its $q$-character as follows.

The map $\prod_{i,a} Z_{i,a}^{u_{i,a}} \mapsto [\sum_{i,a} u_{i,a}\check{\omega}_i]$ generates a homomorphism $\mathcal{Z} \to \ZZ[\leftindex^L{P}]$. The image of the $q$-character $\chi_q^{\sigma}(V)$ under this homomorphism coincides with the usual character $\chi^{\sigma}(V)$.

\subsection{Folding characters}\label{subsec: folding}
Let $\g$ be a finite-dimensional simply-laced simple Lie algebra. In this section we assume that $\g$ is of type $A_{2n-1}$. Let $\Uqghat$ be its associated non-twisted quantum affine algebra of type $A_{2n-1}^{(1)}$ and $\Uqghatsigma$ be the twisted quantum affine algebra of type $A_{2n-1}^{(2)}$. Even though no relation is known between the algebra structures of $\Uqghat$ and $\Uqghatsigma$, the character theories of their representations are closely related \cite{hernandez2010kirillov,wang2023qq}.

It was proved \cite[Theorem~4.15]{hernandez2010kirillov} that the ring homomorphism
\begin{equation}\label{eqn: folding pi}
    \begin{split}
    \pi: \ZZ[Y^{\pm 1}_{i,a}]_{1 \le i \le 2n-1,a\in \CC^*} \to \mathcal{Z},\\
    \begin{cases}
    Y_{i,a}^{\pm 1} \mapsto Z_{\bar{i},a}^{\pm 1},&~\text{if}~i \le n,\\
    Y_{i,a}^{\pm 1} \mapsto Z_{\overline{2n-i},-a}^{\pm 1},&~\text{if}~i > n,
    \end{cases}
\end{split}
\end{equation}
induces a ring homomorphism between the Grothendieck ring of finite-dimensional representations
\[\bar{\pi}: \mathrm{Rep}(\Uqghat) \to \mathrm{Rep}(\Uqghatsigma).\]
Here $\mathrm{Rep}(\Uqghat)$ (resp. $\mathrm{Rep}(\Uqghatsigma)$) is the Grothendieck ring of the category of finite-dimensional representations of $\Uqghat$ (resp. of $\Uqghatsigma$).

If we restrict to the subcategory of representations whose $l$-weights are monomials in $\ZZ[Y_{i,q^n}^{\pm 1}]_{i\in I,n \in\ZZ}$, then it is conjectured that $\bar{\pi}$ maps the classes  of irreducible representations to classes of irreducible representations.

\begin{conjecture}[{\cite[Section~4.4]{hernandez2010kirillov},\cite[Conjecture~2.20]{wang2023qq}}]\label{conj: folding}
    Let $m$ be a dominant monomial in $\ZZ[Y_{i,q^n}^{\pm}]_{i\in I,n \in\ZZ}$, let $\pi(m)$ be the corresponding dominant monomial in $\mathcal{Z}$ under the map $\pi$. Then 
    \[\bar{\pi} ([L(m)]) = [L(\pi(m))].\]
\end{conjecture}
This conjecture has been proven for Kirillov-Reshetikhin modules and, more generally, also holds for snake modules of type $A_{2n-1}$ by essentially the same proof. We will recall the notion of snake modules in Section~\ref{subsection:snakeposition} and in Definition~\ref{def: snake modules}. For now, the reader may also refer to \cite[Section~4.3]{mukhin2012path}.

\begin{proposition}[{\cite[Theorem~4.15]{hernandez2010kirillov}}]
    When $L(m)$ is a snake module of type $A_{2n-1}$, we have 
    \[\bar{\pi} ([L(m)]) = [L(\pi(m))].\]
\end{proposition}

\begin{proof}
    The proof is the same as that for Kirillov-Reshetikhin modules \cite[Theorem~4.15]{hernandez2010kirillov}. Note that for snake modules $L(m)$, $m$ is the unique dominant monomial appearing in its $q$-character $\chi_q(L(m))$ \cite[Theorem~6.1]{mukhin2012path}.
\end{proof}

The homomorphism $\bar{\pi}$ is constructed such that $\pi(\chi_q(L(m))) = \chi_q^{\sigma}(L(\pi(m)))$. As a consequence, we have
\begin{proposition}\label{prop: fold character}
When $L(m)$ is a snake module of type $A_{2n-1}$, the usual characters of $L(m)$ and $L(\pi(m))$ satisfy
\[\varpi(\chi(L(m))) = \chi^{\sigma}(L(\pi(m))),\]
where 
\begin{equation}\label{eqn: folding character}
    \varpi : \ZZ[\bigoplus_{1 \le i \le 2n-1} \ZZ \omega_i] \to \ZZ[\bigoplus_{i \in \{\bar{1},\dots,\bar{n}\}} \ZZ \check{\omega}_i] =  \ZZ[\leftindex^L{P}],
\end{equation}


which maps $[\sum_{i=1}^{2n-1} k_i\omega_{i}]$ to $[\sum_{i=1}^{n-1} (k_i+k_{2n-i})\check{\omega}_{\bar{i}} +k_n\check{\omega}_{\bar{n}}]$.
\end{proposition}

