%    A snake module of $\Uqghatsigma$ of type $A_{2n-1}^{(2)}$ is an irreducible finite-dimensional $l$-highest weight module $L(m')$, such that $m' \in \mathcal{Z}$ is of the form $m' = \pi(m)$, where $m$ is the highest $l$-weight of a snake module $L(m)$ of type $A_{2n-1}^{(1)}$.
%\end{definition}

\subsection{Langlands duality}\label{subsec: prem Langlands}
We begin with an explanation of the notations $\leftindex^L {\mathfrak{h}}^*$, $\leftindex^L {P}$, $\check{\omega}_i$ and $\check{\alpha}_i$ used in Section~\ref{subsec: prem twisted type}.

Let $\Uqghat$ be the quantum affine algebra of type $B_n^{(1)}$. Recall that the index set $I = \{1,\dots,n\}$. Recall that $\mathfrak{h}^* = \bigoplus_{i \in I} \CC \omega_i$, and $P = \bigoplus_{i \in I} \ZZ \omega_i$ is the weight lattice of the simple Lie algebra of type $B_n$. Let $R = \bigoplus_{i \in I}\ZZ \alpha_i \subset P$ be the root lattice of type $B_n$.

Consider the dual space $\leftindex^L {\mathfrak{h}}^* = \Hom(\mathfrak{h}^*,\CC)$ and the dual lattice to the root lattice $R$, denoted by $\leftindex^L{P} = \bigoplus_{i \in I} \ZZ \check{\omega}_{\bar{i}} \subset \leftindex^L {\mathfrak{h}}^*$ with dual basis $\check{\omega}_{\bar{i}} (\alpha_j) = \delta_{ij}$. Let $\leftindex^L {R} = \bigoplus_{i \in I} \ZZ \check{\alpha}_{\bar{i}} \subset \leftindex^L {P}$ be the dual lattice of the weight lattice $P$ with dual basis $\check{\alpha}_{\bar{i}} (\omega_j) = \delta_{ij}$.

Then the inner product $\langle,\rangle$ on $\mathfrak{h}^*$ induces an inner product $\langle,\rangle$ on $\leftindex^L {\mathfrak{h}}^*$. One calculates that $\langle \check{\alpha}_{\bar{i}},\check{\omega}_{\bar{j}} \rangle = \check{d}_{\bar{i}} \delta_{ij}$, where $\check{d}_{\bar{i}}$ are exactly the entries of the diagonal matrix $D$ which symmetrize generalized Cartan matrix of type $A_{2n-1}^{(2)}$.

This phenomenon arises from the fact that the generalized Cartan matrices of type $B_{n}^{(1)}$ and of type $A_{2n-1}^{(2)}$ are transposes of each other. Two quantum Kac-Moody algebras are said to be \textit{Langlands dual} if their associated generalized Cartan matrices are transposes of one another. In particular, the non-twisted quantum affine algebra $\Uqghat$ of type $B_n^{(1)}$ and the twisted quantum affine algebra of type $A_{2n-1}^{(2)}$ are Langlands dual. For this reason, we denote the latter by $\Uqghatdual$.

Let $P'$ be the sublattice of $P$ defined by 
$$P' = \bigoplus_{i \in I} \check{d}_{\bar{i}} \omega_i,$$ where $\check{d}_{\bar{i}} = 1$ for $i \neq n$ and $\check{d}_{\bar{n}} = 2$. 

Following \cite{frenkel2011langlandsfinite,frenkel2011langlandsreps}, there is a bijective linear map
\begin{equation}\label{eqn: Langlands character dual map}
    \Pi : P' \to \leftindex^L{P}, \quad \check{d}_{\bar{i}} \omega_i \mapsto \check{\omega}_{\bar{i}}, \forall i.
\end{equation}


\begin{remark}\label{remark: P prime}
    Notice that the root lattice $R$ is a sublattice of $P'$. Therefore, for any irreducible representation $V$ of $\Uqghat$, if there exists a non zero weight space $V_{\lambda} \neq \{0\}$ with $\lambda \in P'$, then all weights of $V$ lie in $P'$. For this reason, we will focus on finite-dimensional irreducible representations whose highest weight lies in $P'$.
\end{remark}


Representations of quantum Kac-Moody algebras of Langlands dual types have been found to exhibit intriguing relations \cite{frenkel2011langlandsfinite,frenkel2011langlandsreps}. More precisely, it is conjectured that each irreducible representation of $\Uqghat$ admits a Langlands dual representation, in the following sense.

\begin{definition}
    Given an irreducible finite-dimensional representation $V$ of $\Uqghat$ of highest weight $\lambda \in P'$, an irreducible representation of $\Uqghatdual$ is called a Langlands dual representation of $V$, denoted by ${}^L{V}$, if it has highest weight $\Pi(\lambda)$ and 
    \[\chi^{\sigma}({}^L{V}) \preceq \Pi (\chi(V)),\]
    where the inequality means $\Pi (\chi(V)) - \chi^{\sigma}({}^L{V}) \in \NN [\leftindex^L {P}]$, i.e. the multiplicity of each weight on the left-hand side is less than or equal to that on the right-hand side.
\end{definition}

\begin{conjecture}[{\cite[Conjecture~2.2]{frenkel2011langlandsfinite}}]
    For any irreducible finite-dimensional representation $V$ of $\Uqghat$ whose highest weight lies in $P'$, there exists an irreducible representation ${}^L{V}$ of $\Uqghatdual$, which is a Langlands dual representation of $V$.
\end{conjecture}

The conjecture is stated for all pairs of Langlands dual algebras, beyond just the duality between $B_n^{(1)}$ and $A_{2n-1}^{(2)}$. It has been verified in the case where $V$ is a Kirillov-Reshetikhin module \cite[Theorem~2.3]{frenkel2011langlandsfinite}. Moreover, an algorithm was developed to compute the $q$-character of ${}^L {V}$, known as the interpolating $(q,t)$-characters.

Furthermore, it is conjectured that the expression $\Pi (\chi(V))$ is the character of an actual representation of $\Uqghatdual$.

\begin{conjecture}[{\cite[Conjecture~2.4]{frenkel2011langlandsfinite}}]
    For any irreducible finite-dimensional representation $V$ of $\Uqghat$ whose highest weight lies in $P'$, there is a representation of $\Uqghatdual$, denoted by $W$, such that
    \[\chi^{\sigma}(W) = \Pi(\chi(V)).\]
\end{conjecture}


In this paper, we prove that these two conjectures hold when $V$ is a snake module of type $B_n^{(1)}$. Moreover, in this case, we provide an explicit formula expressing the representation $W$ above as a direct sum of irreducible representations. That is, under the bijective map $\Pi$, the character of $V$ decomposes into a sum of characters of irreducible representations of $\Uqghatdual$. For this reason, we refer to this decomposition as the Langlands branching rule.



\section{Path description}\label{sec:path description}
In this section, we recall the path descriptions introduced by Mukhin and Young \cite{mukhin2012path}. Path descriptions are combinatorial methods of describing the $q$-characters of snake modules of quantum affine algebras in type $A_{2n-1}^{(1)}$ or $B_n^{(1)}$. Throughout this paper, the number $n \geq 2$ will be fixed. 

\subsection{Paths}\label{subsec: paths}
In this subsection, we review fundamental concepts of the paths defined in \cite{mukhin2012path}. We will adopt slightly different notation for convenience. For the original definitions and additional details, readers can refer to \cite[Section~5]{mukhin2012path}. 


Let $I = \{1,2,\dots,2n-1\}$ (resp. $I = \{1,2,\dots,n\}$) be the set of indices of Dynkin diagram of type $A_{2n-1}$ (resp. type $B_n$). In type $B_n$, the label $n \in I$ corresponds to the short simple root.

Define 
\[\mathcal{X}^A = \{(i,k) \in I \times \ZZ~|~k \equiv n+i+1 \pmod 2\},\] and 
\[\mathcal{X}^B = \{(i,k) \in I \times \ZZ~|~k \equiv 2n+2i+2 \pmod 4\}.\]

\begin{definition}\label{def: paths}
    The sets of paths are defined as follows.
    \begin{itemize}
        \item Type $A_{2n-1}$: for $(i,k) \in \mathcal{X}^A$,
        \begin{align*}
           \mathscr{P}_{i,k}^{A}:=\{\big( (0,y_0), &(1,y_1), \dots, (2n, y_{2n}) \big)~| \\ &y_0= i+k, y_{2n}=2n-i+k, 
            \text{and $\lvert y_{r+1}-y_r \rvert=1$ for $0\leq r \leq 2n-1$}\}.
        \end{align*}

        \item Type $B_n$: fix an $\epsilon \in \RR$, $0 < \epsilon < 1/2$. For $(i,k) \in \mathcal{X}^B$,
        \begin{align*}
        &&\mathscr{P}_{i,k}^{B}:=\{\big( (0,y_0), &(2,y_1), \dots, (2n-4, y_{n-2}), (2n-2,y_{n-1}), (2n-1,y_n), \\
           && &(2n-1,z_n), (2n,z_{n-1}),\dots,(4n-4,z_1),(4n-2,z_0) \big)~|~y_n > z_n, \text{and} \\
           && & y_0= 2i+k,  \lvert y_{n}-y_{n-1} \rvert=1+\epsilon,  \text{and $\lvert y_{r+1}-y_r \rvert=2$ for $0\leq r\leq n-2$,}\\
           &&z_0= 4n-&2i+k-2,  \lvert z_{n}-z_{n-1} \rvert=1+\epsilon,  \text{and $\lvert z_{r+1}-z_r \rvert=2$ for $0\leq r\leq n-2$}\}.
        \end{align*}
    \end{itemize}
\end{definition}

Paths of type $B_n$ will be illustrated in Figure~\ref{illustrate of P_ik}.

For simplicity, we use the notation $\mathscr{P}_{i,k}$ to represent either $\mathscr{P}_{i,k}^A$ or $\mathscr{P}_{i,k}^B$ when the type is irrelevant or can be inferred from context. A similar omission of upper indices will apply to other symbols as well, and we will not repeat this explanation.

