        \[\big( (2n-1,z_n), (2n,z_{n-1}),(2n+2,z_{n-2}), \dots,(4n-4,z_1),(4n-2,z_0) \big)\] the right branch.
    \end{enumerate}
\end{definition}

\begin{remark}\label{remark: path new definition}
    Our definitions correspond to the original definitions in the following way:

    \begin{itemize}
        \item In $\mathscr{P}_{i,k}^{A}$, we changed the condition $k \equiv i+1 \pmod 2$ in \cite[Section~5.1]{mukhin2012path} to $k \equiv n+i+1 \pmod 2$.

        \item A path in $\mathscr{P}_{n,k}^{B}$ is a pair of paths in $(\mathscr{P}_{n,k-1},\mathscr{P}_{n,k+1})$ of type $B_n$ in \cite[Section~5.1]{mukhin2012path}, because we will always use two paths of type $B_n$ in pair.
    \end{itemize}
\end{remark}


We recall the definitions of upper corners and lower corners, following \cite[Section~5.2]{mukhin2012path}.

\begin{definition}
     Denote by $X^B = \big( \{0,1,\dots,n-1\} \times 2\ZZ \big) \sqcup \big(\{n\} \times (2\ZZ+1)\big)$.
    Define an injective map
        \begin{equation}\label{eqn: tau}
        \begin{split}
        \tau: X^B &\rightarrow \ZZ \times \ZZ  \\
        (j,\ell)&\mapsto 
        \begin{cases}
        (2j,\ell), &\text{if}~j<n~\text{and}~\ell \equiv 2n+2j+2 \pmod 4,\\
        (4n-2-2j,\ell), &\text{if}~j<n~\text{and}~\ell \equiv 2n+2j\pmod 4,\\
        (2n-1,\ell), &\text{if}~j=n.
        \end{cases}
        \end{split}
        \end{equation}
\end{definition}

\begin{itemize}
    \item 
In type $A_{2n-1}$: let $p=\big( (j_r,y_r)\big)_{0\leq r\leq 2n}\in\mathscr{P}_{i,k}^{A}$. Define
\[
C_{p}^{-}:=\{(j_r,y_r)~|~1 \leq r \leq 2n-1, y_{r-1}=y_{r}-1=y_{r+1}\},
\]
called the set of \textit{lower corners}, and
\[
C_{p}^{+}:=\{(j_r,y_r)~|~1 \leq r \leq 2n-1, y_{r-1}=y_{r}+1=y_{r+1}\},
\]
called the set of \textit{upper corners}.


\item
In type $B_n$, let $p=\big( (j_r,y_r)\big)_{0\leq r\leq 2n+1}\in\mathscr{P}_{i,k}^{B}$. Define
\begin{align*}
C_{p}^{-}:=\tau^{-1}\{(j_r,y_r)\in p~|~j_r\notin \{0,2n-1,4n-2\}, y_{r-1}<y_{r}, y_{r+1}<y_r \} \\ \sqcup \{(n,\ell)~|~(2n-1, \ell+\epsilon)\in p~\text{and}~(2n-1, \ell-\epsilon)\notin p \}, 
\end{align*}
called the set of \textit{lower corners}, and
\begin{align*}
C_{p}^{+}:=\tau^{-1}\{(j_r,y_r)\in p~|~j_r\notin \{0,2n-1,4n-2\}, y_{r-1}>y_{r}, y_{r+1}>y_r \} \\
\sqcup \{(n,\ell)~|~(2n-1, \ell-\epsilon)\in p~\text{and}~(2n-1, \ell+\epsilon)\notin p \},
\end{align*}
called the set of \textit{upper corners}.
\end{itemize}



\subsection{Snake positions}\label{subsection:snakeposition}

In this subsection, we recall the definition of snakes and make a slight modification for the purposes of this paper.

We introduce the notion of shortened snake positions. Let $\mathcal{X}$ be the set $\mathcal{X}^A$ or $\mathcal{X}^B$ defined in Section~\ref{subsec: paths}.
\begin{definition}\label{def: shortened snakes}
    For $(i,k)\in \mathcal{X}$, another point $(i',k') \in \mathcal{X}$ is said in \textit{shortened snake position} with respect to $(i,k)$ if 
    \begin{itemize}
        \item 
            Type $A_{2n-1}$:\[ k'-k\geq \lvert i'-i\rvert +2.\]
        \item 
            Type $B_n$:
            \[k'-k\geq 2\lvert i'-i\rvert +4.\]
    \end{itemize}
\end{definition}

Shortened snakes are defined as follows.
\begin{definition}\label{def: definition of snakes}
    A \textit{shortened snake} is a finite sequence $(i_t, k_t)_{1 \leq t \leq T}$, $T\in \mathbb{N}^*$, of points in $\mathcal{X}$ such that for $2 \leq t \leq T$, $(i_t,k_t)$ is in shortened snake position with respect to $(i_{t-1},k_{t-1})$. 
\end{definition}

The shortened snakes are related to the notion of snakes in \cite[Section~4.2]{mukhin2012path} and \cite[Section~3.2]{duan2019cluster} in the following way.

In type $A_{2n-1}$, a shortened snake is exactly the same as a snake. Therefore, we will interchangeably use the name snake in type $A_{2n-1}$.

In type $B_n$, given a shortened snake $(i_t, k_t)_{1 \leq t \leq T}$, we replace the terms $(i_t,k_t)$ in the sequence by two terms $(i_t,k_t-1)(i_t,k_t+1)$ whenever $i_t =n$, and retain all other terms. The resulting sequence is then a snake in the sense of  \cite{mukhin2012path,duan2019cluster}. This gives an injective but non-surjective map
\[\{\text{shortened snakes}\} \to \{\text{snakes}\}.\]

We use the notion of shortened snakes so that the weights of the snake module will be contained in the sublattice $P'$ of $P$, as we have seen in Remark~\ref{remark: P prime}.


\subsection{Non-overlapping paths and snake modules}
For two paths $p$ and $p'$ of the same type, $p$ is said being strictly above $p'$ (or, $p'$ strictly below $p$) if
\[
\forall (x,y) \in p, (x,z) \in p' \Rightarrow y < z.
\]
In this case, we denote by $p \succ p'$.

A $T$-tuple of paths $(p_1, \dots , p_T )$ is said to be \textit{non-overlapping} if $p_1 \succ p_2 \succ \cdots \succ p_T$.

For any shortened snake $\big((i_1,k_1)(i_2,k_2)\cdots(i_T,k_T)\big)$, $T\in\mathbb{N}^*$, define
\[
\overline{\mathscr{P}}_{(i_t,k_t)_{1\leq t \leq T}}:=\{(p_1,\dots,p_T)~|~p_t \in\mathscr{P}_{i_t,k_t},1\leq t \leq T,(p_1,\dots,p_T)~\text{is non-overlapping}\}.
\]
This is the set of $T$-tuples of \textit{non-overlapping paths} (NOP), where the $t$-th path is in the set $\mathscr{P}_{i_{t},k_{t}}$ determined by the snake.

The paths are combinatorial tools for describing the $q$-characters of a large class of representations of quantum affine algebras, called snake modules \cite{mukhin2012path}. 

\begin{definition}\label{def: snake modules}
    Let $\Uqghat$ be a quantum affine algebra of type $A_{2n-1}^{(1)}$ or $B_n^{(1)}$. Let $(i_t,k_t)_{1\leq t\leq T}$ be a shortened snake of the corresponding type. Let $L(m)$ be the irreducible $l$-highest weight representation of $\Uqghat$, with the highest $l$-weight
    \begin{equation}\label{eqn: m snake highest weight}
        \begin{split}
            & m = \prod_{1 \leq t \leq T} Y_{i_t,q^{k_t}},~\text{ in type $A_{2n-1}$}, \\
            & m = \prod_{t:i_t \neq n} Y_{i_t,q^{k_t}} \prod_{t: i_t = n} Y_{n,q^{k_t-1}}Y_{n,q^{k_t+1}},~\text{ in type $B_n$}. 
        \end{split}
    \end{equation}
    These are known as \textit{snake modules} of $\Uqghat$.
\end{definition}

We extend this definition to twisted quantum affine algebra of type $A_{2n-1}^{(2)}$.
\begin{definition}
    A snake module of twisted quantum affine algebra $\Uqghatsigma$ of type $A_{2n-1}^{(2)}$ is an irreducible finite-dimensional $l$-highest weight representation $L(m)$, $m \in \mathcal{Z}$, such that 
    \[m = \prod_{1 \le t \le T} Z_{\bar{i_t},q^{k_t}},\]
    where $(i_t,k_t)_{1 \le t \le T}$ is a snake of type $A_{2n-1}$ such that $1 \le i_t \le n$ for all $t$.
\end{definition}

Proposition~\ref{prop: fold character} states that
\begin{proposition}\label{prop: folding snake formula}
    Let $(i_t,k_t)_{1 \le t \le T}$ be a snake of type $A_{2n-1}$ such that $1 \le i_t \le n$ for all $t$. Then
    \[\chi^{\sigma}(L(\prod_{1 \le t \le T} Z_{\bar{i_t},q^{k_t}})) = \varpi (\chi(L(\prod_{1 \le t \le T} Y_{i_t,q^{k_t}}))).\]
\end{proposition}

The path description provides a method to compute both the usual characters and $q$-characters of snake modules of types $A_{2n-1}^{(1)}$ and $B_n^{(1)}$.

\begin{theorem}\cite[Theorem~6.1]{mukhin2012path}\label{path description}
Let $(i_t,k_t)_{1\leq t\leq T}$ be a shortened snake and $m$ as in \eqref{eqn: m snake highest weight}, then we have
\[
\chi_q\big( L(m) \big) = \mathop{\sum}\limits_{(p_1,\dots,p_T)\in\overline{\mathscr{P}}_{(i_t,k_t)_{1\leq t\leq T}}}\prod_{t=1}^{T}\mathfrak{m}(p_t),
\]
where 
\begin{equation}\label{eqn: monomial m of p}
\mathfrak{m}(p) = \prod_{(j,\ell) \in C_p^+} Y_{j,q^\ell} \prod_{(j,\ell) \in C_p^-} Y_{j,q^\ell}^{-1} \quad \text{for any path $p$.}
\end{equation}
\end{theorem}

Similarly, for a $T$-tuple of NOP $\overline{p} = (p_1,\dots,p_T)$, we denote by 
\begin{equation}\label{eqn: monomial m of non-overlapping paths}
    \mathfrak{m}(\overline{p}) = \prod_{t=1}^T \mathfrak{m}(p_t).
\end{equation}

By \cite[Theorem~3]{frenkel1999q}, the usual character $\chi$ can be obtained from the $q$-character directly.

\begin{corollary}\label{character-path}
 Let $(i_t,k_t)_{1\leq t\leq T}$ be a shortened snake and $m$ as in \eqref{eqn: m snake highest weight}, then the usual character
\[
\chi \big( L(m)\big) = \mathop{\sum}\limits_{(p_1,\dots,p_T)\in\overline{\mathscr{P}}_{(i_t,k_t)_{1\leq t\leq T}}}\bigg[\sum_{t=1}^{T}\mathfrak{m}'(p_t) \bigg],
\]
where 
\begin{equation}\label{eqn: m prime of p}
\mathfrak{m}'(p) = \sum_{(j,\ell) \in C_p^+} \omega_{j} - \sum_{(j,\ell) \in C_p^-} \omega_{j} \quad \text{for any path $p$.}
\end{equation}
\end{corollary}
We also write 
\[\mathfrak{m}'(\overline{p}) = \sum_{t=1}^T \mathfrak{m}'(p_t)\]
for a $T$-tuple of NOP $\overline{p} = (p_1,\dots,p_T)$.


\section{Langlands dual from \texorpdfstring{$B_n^{(1)}$}{} to \texorpdfstring{$A_{2n-1}^{(2)}$}{}}\label{sec:Langlands B to A}
In this section, we work within type $A_{2n-1}$ and type $B_{n}$, $n\geq 2$. The goal of this section is to construct an injective map which associates a tuple of non-overlapping paths of type $A_{2n-1}$ with a tuple of non-overlapping paths of type $B_n$. As a consequence, we deduce that snake modules of type $B_n^{(1)}$ admit Langlands dual representations.

\subsection{The map between sets of points}
In this subsection, we begin with constructing the map on the level of points.

Define the set of points 
\[X^A = \{(j,\ell)\in \{0,\dots,2n\} \times \ZZ~|~\ell \equiv n + j + 1 \pmod 2 \}.\]

We construct a map $f$ from the set of points $X^A$ to the set of points $X^B$. Recall that 
\[X^B = \big( \{0,1,\dots,n-1\} \times 2\ZZ \big) \sqcup \big(\{n\} \times (2\ZZ+1)\big).\]

\begin{definition}\label{def: map f between sets of points}
Define an injective map
\begin{align*}
f: X^A &\rightarrow X^B\\
(j,\ell) &\mapsto \begin{cases}(j,2\ell), &\text{if}~j< n,\\
(n, 2\ell-1), &\text{if}~j= n,\\
(2n-j,2\ell-2), &\text{if}~j> n.
\end{cases}
\end{align*}
\end{definition}
This is injective because if $(j,\ell),(2n-j,\ell') \in X^A$, then $\ell \equiv \ell' \pmod 2$, thus $2\ell \not\equiv 2\ell'-2 \pmod 4$.


\subsection{The map between paths}
The goal of this subsection and the next subsection is to construct a map which associates a tuple of NOP of type $A_{2n-1}$ with a tuple of NOP of type $B_n$. We begin our construction for one single path.


\begin{definition}\label{def: map F between paths}
    Let $p \in \mathscr{P}^{A}_{i,k}$, $i \leq n$. We define a path $F(p)$ in $\mathscr{P}^{B}_{i,2k}$ in the following way.

    Write \[p = \big( (0,x_0),(1,x_1),\dots,(2n,x_{2n})  \big).\]

    Then we define 
    \begin{align*}
        F(p) = \big( (0,y_0), &(2,y_1), \dots, (2n-4, y_{n-2}), (2n-2,y_{n-1}), (2n-1,y_n), \\
         &(2n-1,z_n), (2n,z_{n-1}),\dots,(4n-4,z_1),(4n-2,z_0) \big),
    \end{align*}

    with coordinates 
    \[y_j = 
    \begin{cases}
        2x_j, &\text{if}~j < n,\\
        2x_n-1 + \epsilon, &\text{if}~j=n~\text{and}~x_n>x_{n-1}, \\
        2x_n+1-\epsilon, &\text{if}~j=n~\text{and}~x_n<x_{n-1},
    \end{cases}
    \]
    and
    \[z_j = 
    \begin{cases}
        2x_{2n-j}-2, &\text{if}~j < n,\\
        2x_n-3 + \epsilon, &\text{if}~j=n~\text{and}~x_n>x_{n+1}, \\
        2x_n-1-\epsilon, &\text{if}~j=n~\text{and}~x_n<x_{n+1}.
    \end{cases}
    \]
\end{definition}

    One can easily verify that $F(p)$ is indeed a path in $\mathscr{P}^{B}_{i,2k}$. An example of $p$ and $F(p)$ can be illustrated in Figure~\ref{illustrate of F}.

\begin{lemma}\label{lemma: F injective}
    The map $F: \mathscr{P}_{i,k}^A \to \mathscr{P}_{i,2k}^B$ is injective.
\end{lemma}
\begin{proof}
    This follows immediately from the definition of $F$.
\end{proof}


