\begin{proposition}\label{prop: path map}
Let $p$ be a path in $\mathscr{P}_{i,k}^A$, $i \leq n$. Let $f : X^A \to X^B$ be the map in Definition~\ref{def: map f between sets of points}, and $F(p)$ be the path in $\mathscr{P}_{i,2k}^B$ defined above. Then
\begin{align*}
C^{-}_{F(p)}=&\{f(j,\ell)~|~(j,\ell)\in C^{-}_{p}, j\neq n\}\sqcup \{(n,2\ell-1), (n,2\ell-3)~|~(n,\ell)\in C^{-}_{p}\}\sqcup\\
&\{(n,2\ell-3)~|~(n-1,\ell+1),(n,\ell),(n+1,\ell-1)\in p\},\\
C^{+}_{F(p)}=&\{f(j,\ell)~|~(j,\ell)\in C^{+}_{p}, j \neq n\}\sqcup \{(n,2\ell-1), (n,2\ell+1)~|~(n,\ell)\in C^{+}_{p}\}\sqcup \\
&\{(n,2\ell+1)~|~(n-1,\ell+1),(n,\ell),(n+1,\ell-1)\in p\}.
\end{align*}

\end{proposition}
\begin{proof}
    The part with first coordinate $j \neq n$ follows immediately from definition of the map $F$. We now calculate the upper and lower corners of $F(p)$ with first coordinate $n$.

    Let $(n-1,x_{n-1}), (n,\ell), (n+1,x_{n+1}) \in p$ be consecutive points of the path $p$.
    \begin{itemize}
        \item If $x_{n-1} = \ell +1$ and $x_{n+1} = \ell -1$, then we have four consecutive points in $F(p)$:
        \[(2n-2,2\ell+2), (2n-1,2\ell+1-\epsilon),(2n-1,2\ell-3+\epsilon),(2n,2\ell-4).\]
        Thus we are in the case $(n,2\ell +1) \in C_{F(p)}^+$ and $(n,2\ell -3) \in C_{F(p)}^-$.

        \item If $x_{n-1} = \ell -1$ and $x_{n+1} = \ell +1$, then we have four consecutive points in $F(p)$:
        \[(2n-2,2\ell-2), (2n-1,2\ell-1+\epsilon),(2n-1,2\ell-1-\epsilon),(2n,2\ell).\]
        Thus we are in the case that $C_{F(p)}^+$ and $C_{F(p)}^-$ have no point with first coordinate $n$.

        \item If $x_{n-1} = x_{n+1} = \ell +1$, then we have four consecutive points in $F(p)$:
        \[(2n-2,2\ell+2), (2n-1,2\ell+1-\epsilon),(2n-1,2\ell-1-\epsilon),(2n,2\ell).\]
        Thus we are in the case $(n,2\ell +1),(n,2\ell -1) \in C_{F(p)}^+$.

        \item If $x_{n-1} = x_{n+1} = \ell -1$, then we have four consecutive points in $F(p)$:
        \[(2n-2,2\ell-2), (2n-1,2\ell-1+\epsilon),(2n-1,2\ell-3+\epsilon),(2n,2\ell-4).\]
        Thus we are in the case $(n,2\ell -1),(n,2\ell -3) \in C_{F(p)}^-$.
    \end{itemize}
\end{proof}


Recall that $\varpi$ is the folding map in \eqref{eqn: folding character} and $\Pi$ is the Langlands dual map on the weight lattice in \eqref{eqn: Langlands character dual map}.

\begin{theorem}\label{thm: map between paths preserves the character}
    Let $\mathfrak{m}'$ be the associated weight of a path, as defined in \eqref{eqn: m prime of p}. Then for any path $p \in \mathscr{P}^A_{i,k}$, $i \le n$, we have  
    \[\varpi \circ \mathfrak{m}'(p)=\Pi \circ \mathfrak{m}'(F(p)).\]
\end{theorem}
\begin{proof}
    The associated weight of a path is given by the positions of upper corners and lower corners. Suppose that the path $p$ has an upper (resp. lower) corner at first coordinate $j$, $j \neq n$, which provides $\omega_j$ (resp. $-\omega_j$) in the weight. By Proposition~\ref{prop: path map}, $F(p)$ has a corresponding upper (resp. lower) corner at first coordinate $\min(j,2n-j)$.

    At the first coordinate $n$, if $(n,\ell)$ is an upper (resp. lower) corner of $p$, then by  Proposition~\ref{prop: path map}, $F(p)$ has double upper (resp. lower) corners at first coordinate $n$, which contribute $2\omega_n$ (resp. $-2\omega_n$) to the weight. If $(n,\ell)$ is neither an upper corner nor a lower corner of $p$, then $F(p)$ has exactly one upper corner and one lower corner at first coordinate $n$, which contribute $0$ to the weight.

    Note that $\varpi(\omega_j) = \varpi(\omega_{2n-j}) = \check{\omega}_{\bar{j}}$, and $\Pi(\omega_j) = \check{\omega}_{\bar{j}}$, $\forall j \neq n$, $\Pi(2\omega_n) = \check{\omega}_{\bar{n}}$, the identity follows immediately.
\end{proof}


\subsection{The map between non-overlapping paths}\label{subsec: map between non-overlapping paths}
Having constructed the map $F$ for a single path, now we construct the map for a tuple of NOP.

For each given shortened snake of type $A_{2n-1}$, we associate a shortened snake of type $B_n$ in the following way.

Let $\big( (i_1,k_1)\cdots(i_T,k_T) \big)$, $T \in \NN^*$, be a shortened snake of type $A_{2n-1}$ such that $1 \leq i_t \leq n$, $\forall 1\leq t\leq T$ (see Section~\ref{subsection:snakeposition}). By Definition~\ref{def: shortened snakes} 
\[\big( (i_1,2k_1)(i_2,2k_2)\cdots(i_T,2k_T) \big)\]
is a shortened snake of type $B_n$.



\begin{proposition}\label{prop: maps between non-overlapping paths}
Let $(p_1,p_2,\dots,p_T)\in\overline{\mathscr{P}}^A_{(i_t,k_t)_{1\leq t\leq T}}$ be a $T$-tuple of NOP. Then the $T$-tuple 
\[
\big(F(p_1),F(p_2),\dots,F(p_T) \big)
\]
is a $T$-tuple of NOP in $\overline{\mathscr{P}}^B_{(i_t,2k_t)_{1 \leq t \leq T}}$. Here $F(p_t) \in \mathscr{P}_{i_t,2k_t}^B$ is the image of $p_t$ under the map $F: \mathscr{P}_{i_t,k_t}^A \to \mathscr{P}_{i_t,2k_t}^B$ in Definition~\ref{def: map F between paths}.
\end{proposition}
\begin{proof}
    One only has to check that $F(p_{t-1}) \succ F(p_{t})$, $\forall 2 \leq t \leq T$. 

    Suppose that for $j < n$, $(2j,y_j^{(t-1)}) \in F(p_{t-1})$ and $(2j,y_j^{(t)}) \in F(p_t)$, then $(j,y_j^{(t-1)}/2) \in p_{t-1}$ and $(j,y_j^{(t)}/2) \in p_t$. Since $p_{t-1} \succ p_t$, we have $y_j^{(t-1)} < y_j^{(t)}$.

    Similarly, suppose that for $j < n$, $(4n-2-2j,z_j^{(t-1)}) \in F(p_{t-1})$ and $(4n-2-2j,z_j^{(t)}) \in F(p_t)$, then $(2n-j,z_j^{(t-1)}/2+1) \in p_{t-1}$ and $(j,z_j^{(t)}/2+1) \in p_t$. Since $p_{t-1} \succ p_t$, we have $z_j^{(t-1)} < z_j^{(t)}$.

    At first coordinate $2n-1$, let $(n,x_n^{(t-1)}) \in p_{t-1}$ and $(n,x_n^{(t)}) \in p_{t}$. Then $p_{t-1} \succ p_t$ implies that $x_n^{(t-1)} < x_n^{(t)}$. Thus $x_n^{(t-1)} \le x_n^{(t)}-2$ since $x_n^{(t-1)} \equiv x_n^{(t)} \pmod 2$. Therefore, suppose that $(2n-1,y_n^{(t-1)}),(2n-1,z_n^{(t-1)}) \in F(p_{t-1})$ and $(2n-1,y_n^{(t)}), (2n-1,z_n^{(t)}) \in F(p_t)$, then
    \[z_n^{(t-1)} < y_n^{(t-1)} \le 2x_n^{(t-1)} + 1 -\epsilon \le 2x_n^{(t)} - 4 + 1 -\epsilon < 2x_n^{(t)} - 3 + \epsilon \le z_n^{(t)} < y_n^{(t)}.\]

    Thus we have verified that $F(p_{t-1}) \succ F(p_{t})$, $\forall 2 \leq t \leq T$. 
\end{proof}

As a consequence of Theorem~\ref{thm: map between paths preserves the character} and Proposition~\ref{prop: maps between non-overlapping paths}, we have
\begin{corollary}\label{cor: F preserves characters}
    Let $\overline{p} = (p_1,\dots,p_T) \in \overline{\mathscr{P}}^A_{(i_t,k_t)_{1\leq t\leq T}}$ and $F(\overline{p}) = (F(p_1),\dots,F(p_T)) \in \overline{\mathscr{P}}^B_{(i_t,2k_t)_{1 \leq t \leq T}}$. Then
    \[\varpi \circ \mathfrak{m}'(\overline{p})=\Pi \circ \mathfrak{m}'(F(\overline{p})).\]
\end{corollary}

\subsection{Langlands dual representations}\label{subsec: Langlands dual from B to A}

Now we can prove that the conjecture of Frenkel and Hernandez \cite[Conjecture~2.2]{frenkel2011langlandsfinite} holds for snake modules from type $B_n^{(1)}$ to type $A_{2n-1}^{(2)}$. Let $\Uqghat$ be the quantum affine algebra of type $B_n^{(1)}$. Let $\Uqghatdual$ be the twisted quantum affine algebra of type $A_{2n-1}^{(2)}$.

\begin{theorem}\label{thm: langlands dual rep A to B}
     Let $V$ be any shortened snake module of $\Uqghat$, whose highest weight is $\lambda \in P$. There is a shortened snake module ${}^L{V}$ of $\Uqghatdual$ whose highest weight is $\Pi(\lambda) \in \leftindex^L{P}$, such that
    \[ \chi^{\sigma}({}^L{V}) \preceq \Pi(\chi(V)).\]
\end{theorem}

\begin{proof}
    Let $(i_t,k_t)_{1 \leq t \leq T}$ be a shortened snake of type $B_{n}$, and 
        \begin{equation}\label{eqn: snake weight type B}
            m = \prod_{t:i_t \neq n}Y_{i_t,q^{k_t}} \prod_{t: i_t=n}Y_{n,q^{k_t-1}}Y_{n,q^{k_t+1}}
        \end{equation}
    the corresponding dominant monomial.

    Then $(i_t,\frac{k_t}{2})_{1 \leq t \leq T}$ is a shortened snake of type $A_{2n-1}$ such that $1 \leq i_t \leq n$, $\forall 1\leq t\leq T$. Let 
        \begin{equation}\label{eqn: snake weight Lm}
            {}^L{m} = \prod_{1 \leq t \leq T} Z_{\bar{i_t},q^{k_t/2}}
        \end{equation}
    be the corresponding dominant monomial. 

    We prove that if $V = L(m)$, then we can choose ${}^L{V} = L({}^L{m})$.

    By Proposition~\ref{prop: folding snake formula} and Corollary~\ref{character-path},
    \[\chi^{\sigma}({}^L{V}) = \varpi(\chi(L(\prod_{1 \leq t \leq T} Y_{i_t,q^{k_t/2}}))) =  \mathop{\sum}\limits_{\overline{p} \in\overline{\mathscr{P}}^A_{(i_t,\frac{k_t}{2})_{1\leq t\leq T}}}  \bigg[ \varpi \circ \mathfrak{m}'(\overline{p}) \bigg],\]
    and by Corollary~\ref{cor: F preserves characters}, it equals to
    \[\mathop{\sum}\limits_{\overline{p} \in\overline{\mathscr{P}}^A_{(i_t,\frac{k_t}{2})_{1\leq t\leq T}}}  \bigg[ \Pi \circ \mathfrak{m}'(F(\overline{p})) \bigg].\]

    On the other hand, by Corollary~\ref{character-path},
    \[\Pi(\chi(V)) = \mathop{\sum}\limits_{\overline{p} \in\overline{\mathscr{P}}^B_{(i_t,k_t)_{1\leq t\leq T}}}\bigg[\Pi \circ \mathfrak{m}'(\overline{p}) \bigg].\]

    By Lemma~\ref{lemma: F injective},
    \[F: \overline{\mathscr{P}}^A_{(i_t,\frac{k_t}{2})_{1\leq t\leq T}}\to \overline{\mathscr{P}}^B_{(i_t,k_t)_{1\leq t\leq T}} \]
    is injective on every single path, thus injective on $T$-tuples of NOP. Therefore,
    \[ \chi^{\sigma}({}^L{V}) \preceq \Pi(\chi(V)).\]
\end{proof}

It is interesting to know the image of the map $F$. For this purpose, we introduce the following notion.

\begin{definition}\label{def: level}
    Recall that a path $p$ of type $B_n$ has two points $(2n-1,y_n)$, $(2n-1,z_n)$ with first coordinate $2n-1$, and $y_n > z_n$. Define the \textit{gap} of the path $p$ to be
    \[\mathrm{gap}(p) := \frac{1}{2} (\lfloor \frac{y_n+1}{2} \rfloor -  \lfloor \frac{z_n+3}{2} \rfloor).\]

    The gap of a $T$-tuple of NOP is the sum of the gap of each component:
    \[\mathrm{gap}\big((p_1,\dots,p_T)\big) = \sum_{t=1}^T \mathrm{gap}(p_t).\]
\end{definition}

