\begin{remark}
    The gap is a non-negative integer. This is because one can prove that 
    $$\frac{1}{2} (\lfloor \frac{y_n+1}{2} \rfloor -  \lfloor \frac{z_n+3}{2} \rfloor) = \lfloor \frac{y_n-z_n}{4} \rfloor,$$
    using the properties $y_n > z_n$ and
    \[y_n \in (4\ZZ +3-\epsilon) \sqcup (4\ZZ+1+\epsilon),\]
    \[z_n \in (4\ZZ +3+\epsilon) \sqcup (4\ZZ+1-\epsilon).\]
    We omit the calculation.
\end{remark}

\begin{lemma}
    A $T$-tuple of NOP in the image of $F$ has gap $0$.
\end{lemma}
\begin{proof}
    This follows from Definition~\ref{def: map F between paths}. Note that for a type $A_{2n-1}$ path $p$, if $(n,x_n) \in p$ and $(2n-1,y_n),(2n-1,z_n) \in F(p)$, then
    \[0 \le \frac{1}{2} (\lfloor \frac{y_n+1}{2} \rfloor -  \lfloor \frac{z_n+3}{2} \rfloor) \le \frac{1}{2}(\lfloor \frac{2x_n+1-\epsilon+1}{2} \rfloor -  \lfloor \frac{2x_n-3+\epsilon+3}{2} \rfloor) = 0.\]

\end{proof}

\begin{proposition}\label{prop: level 0 bijection}
    Let $(p_1,\dots,p_T) \in \overline{\mathscr{P}}^B_{(i_t,k_t)_{1\leq t \leq T}}$ be a $T$-tuple of NOP. Then $(p_1,\dots,p_T)$ is in the image $F(\overline{\mathscr{P}}^A_{(i_t,\frac{k_t}{2})_{1\leq t \leq T}})$ if and only if it has gap $0$. 
\end{proposition}
\begin{proof}
    It remains to prove that for a single path $p \in \mathscr{P}^B_{i,k}$, if $p$ has gap $0$, then $p$ is in the image $F(\mathscr{P}^A_{i,\frac{k}{2}})$.

    In fact, we are able to write down its preimage explicitly. Let
        \begin{align*}
           && p = \big( (0,y_0), &(2,y_1), \dots, (2n-4, y_{n-2}), (2n-2,y_{n-1}), (2n-1,y_n), \\
           && &(2n-1,z_n), (2n,z_{n-1}),\dots,(4n-4,z_1),(4n-2,z_0) \big).
        \end{align*}
    Then its preimage is the path 
        \begin{align*}
           && F^{-1}(p) = \big( (0,\frac{y_0}{2}), &(1,\frac{y_1}{2}), \dots, (n-1, \frac{y_{n-1}}{2}), (n,\lfloor \frac{y_{n}+1}{2} \rfloor ), \\
           && &(n+1,\frac{z_{n-1}+2}{2}),\dots,(2n-1,\frac{z_1+2}{2}),(2n,\frac{z_0+2}{2}) \big).
        \end{align*}
    It is straightforward to check that $F^{-1}(p)$ is a path in $\mathscr{P}^A_{i,\frac{k}{2}}$. One only has to use that $y_i,z_i$ are even integers when $i \neq n$, and $y_n \in 2\ZZ +1 \pm \epsilon$.

    Moreover, for a $T$-tuple of NOP $(p_1,\dots,p_T) \in \overline{\mathscr{P}}^B_{(i_t,k_t)_{1\leq t \leq T}}$, the corresponding paths $F^{-1}(p_1),\dots,F^{-1}(p_T)$ are also non-overlapping. In fact, for points whose first coordinate is not $2n-1$, the inequality is evident. For points with first coordinate $2n-1$, if $p_{t-1}$ is strictly above $p_{t}$ and $(2n-1,y_n^{(t-1)}),(2n-1,z_n^{(t-1)}) \in p_{t-1}$ (resp. $(2n-1,y_n^{(t)}),(2n-1,z_n^{(t)}) \in p_{t}$) are points of $p_{t-1}$ (resp. $p_{t}$), then $z_n^{(t-1)} < y_n^{(t-1)} < z_n^{(t)} < y_n^{(t)}$. Since $y_n^{(t-1)},z_n^{(t)},y_n^{(t)} \in 2\ZZ + 1 \pm \epsilon$, we have $y_n^{(t)} - y_n^{(t-1)} \geq 2$, thus $\lfloor \frac{y_{n}^{(t-1)}+1}{2} \rfloor < \lfloor \frac{y_{n}^{(t)}+1}{2} \rfloor$.
\end{proof}

Since the path description gives not only the usual character but also the $q$-character, we have constructed the embedding at the level of $q$-characters. In \cite{frenkel2011langlandsfinite}, Frenkel and Hernandez provided an algorithm to compute which term in $\chi_q(V)$ corresponds to a term in $\chi_q^{\sigma}({}^L{V})$ when $V$ is a Kirillov-Reshetikhin module. Their method is known as the interpolating $(q,t)$-characters. In this paper, we propose an alternative method for this question, and more generally for snake modules.

The gap of a monomial in $\chi_q(V)$ is defined as the gap of its corresponding path. Then we have the following method to write down the $q$-character of $L({}^L{m})$.

\begin{corollary}
    Let $L(m)$ be a shortened snake module of $\Uqghat$ with $m$ in \eqref{eqn: snake weight type B}. Let $C_0$ be the set of $T$-tuples of NOP in $\overline{\mathscr{P}}^B_{(i_t,k_t)_{1\leq t \leq T}}$ having gap $0$. Then
    \[\chi_q^{\sigma}(L({}^L{m})) = \sum_{\overline{p} \in C_0} \pi \circ \mathfrak{m}(F^{-1}(\overline{p})),\]
    where $\mathfrak{m}$ is defined in \eqref{eqn: monomial m of non-overlapping paths}, and $\pi$ is the folding map on $q$-characters defined in \eqref{eqn: folding pi}.
\end{corollary}








\section{An identity of characters of type \texorpdfstring{$A_{n-1}^{(1)}$}{} snake modules}\label{sec:equality}
We prove an identity between characters of snake modules of type $A_{n-1}^{(1)}$. This identity will play a key role in the next section, where we establish the Langlands branching rule. In Section~\ref{subsec: path interpretation of identity}, we provide an interpretation of this identity in the language of paths.

\subsection{Main theorem}\label{subsec: main theorem}
In this section, we present a snake module in terms of multi-segments for simplicity.

A multi-segment is a finite family of segments $[l_j,r_j]$, such that $l_j, r_j \in \ZZ$, $l_j \le r_j$, for all $j$ in a finite index set.

A \textit{type $A_{n-1}$ snake} is a multi-segment such that the segments are ordered as $[l_t,r_t]$, $1 \leq t \leq T$, $T \in \NN^*$, which satisfies
\[l_1 < l_2 < \cdots < l_T, r_1 < r_2< \cdots < r_T,~\text{and}~0 \le r_t - l_t \le n, \forall t.\]
The number $T$ is called the length of the snake.

Recall that in type $A_{n-1}$, there is a correspondence between multi-segments and dominant monomials in $\ZZ[Y^{\pm1}_{i,q^{i+2m}}]_{i \in I, m \in \ZZ}$ \cite{chari1996quantum}, which associates an individual segment $[l,r]$ with $Y_{r-l,q^{r+l}}$, and associates the multi-segment with the product $\prod_{t=1}^T Y_{r_t-l_t,q^{r_t+l_t}}$. Here the variable $Y_{r-l,q^{r+l}}$ should be understood as $1$ if $r-l = 0$ or $n$.

Under this correspondence, it is easy to see that $[\mathbf{l},\mathbf{r}] = ([l_t,r_t])_{1 \le t \le T}$ is a type $A_{n-1}$ snake if and only if the sequence of points $(r_t-l_t,r_t+l_t) \in \{0,\dots,n\} \times \ZZ$, $1 \leq t \leq T$ form a shortened snake in the sense of Definition~\ref{def: definition of snakes}.

The corresponding snake module is denoted by $L([\mathbf{l},\mathbf{r}])$.


\begin{definition}
    Given two sequences $\mathbf{l} = (l_1,\dots,l_T)$ and $\mathbf{l}' = (l'_1,\dots,l'_T)$, 
    \begin{itemize}
        \item 
        we say that 
        $$\mathbf{l} \leq \mathbf{l}', \text{ if } l_t \leq l_t', \forall t.$$

        \item In case that $\mathbf{l} \le \mathbf{l}'$, we denote by
        \[|\mathbf{l}'-\mathbf{l}| = \sum_{t=1}^T (l_t' - l_t) \in \NN.\]

        \item We say that 
        $$\mathbf{l}[-1] < \mathbf{l}', \text{ if } l_{t-1} < l'_t, \forall t,$$
        where $l_0 = -\infty$.

        Similarly, we say that 
        $$\mathbf{l}' < \mathbf{l}[1], \text{ if } l'_{t} < l_{t+1}, \forall t,$$
        where $l_{T+1} = \infty$.
    \end{itemize}
\end{definition}

This section is devoted to proving the following theorem.

\begin{theorem}\label{thm: type A equality}
Let $[\mathbf{l},\mathbf{r}]$ be a type $A_{n-1}$ snake of length $T$. For each fixed integer $M \in \NN$, we have
    \begin{equation}\label{eqn: type A equation}
    \sum_{\substack{\mathbf{l} \le \mathbf{l}' <  \mathbf{l}[1]\\ |\mathbf{l}'-\mathbf{l}| = M\\ [\mathbf{l}',\mathbf{r}]~\text{is a snake}}} \chi(L(\mathbf{l}',\mathbf{r})) = \sum_{\substack{\mathbf{r}[-1] < \mathbf{r}' \le \mathbf{r} \\|\mathbf{r}-\mathbf{r}'| = M\\ [\mathbf{l},\mathbf{r}']~\text{is a snake}}} \chi(L(\mathbf{l},\mathbf{r}')),
    \end{equation}
    where the sum on the left-hand side is taken over $\mathbf{l}'$ such that $[\mathbf{l'},\mathbf{r}]$ is a type $A_{n-1}$ snake and $\mathbf{l} \le \mathbf{l}' <  \mathbf{l}[1]$, $|\mathbf{l}'-\mathbf{l}| = M$. Similarly, the sum on the right-hand side is taken over $\mathbf{r}'$ such that $[\mathbf{l},\mathbf{r}']$ is a type $A_{n-1}$ snake and $\mathbf{r}[-1] < \mathbf{r}' \le  \mathbf{r}$, $|\mathbf{r} - \mathbf{r}'| =M$. 
\end{theorem}

\subsection{Determinant formula}
In this subsection, we recall the determinant formula for snake modules, which allows us to express the character of a snake module as an algebraic combination of characters of fundamental representations. We refer the reader to \cite{brito2024alternating} for the notation and results needed here. This formula can also be derived via Schur–Weyl duality from the corresponding result for algebraic groups \cite{tadic1995on, chenevier2008characters, lapid2014on, lapid2018geometric, bittmann2023on}.

We use the notation $W(l,r)$ to denote the character of $W(\bm{\omega}_{l,r})$ in \cite{brito2024alternating}. That is,
\begin{definition}
     For $l,r \in \ZZ$,
\begin{align*}
    W(l,r) = 
    \begin{cases}
    \chi(L([l,r])),&~\text{if}~0 \le r-l \le n, \\
    0,&~\text{otherwise}.
    \end{cases}
\end{align*}
\end{definition}

Notice that $[l,r]$ is a type $A_{n-1}$ snake if and only if $[l+m,r+m]$ is as well, and the usual $\g$-character of a fundamental is independent of the spectral parameter. Therefore, we have

\begin{lemma}\label{lemma: shift invariant}
    $W(l,r) = W(l+m,r+m)$, $\forall l,r,m \in \ZZ$.
\end{lemma}

The following lemma is a direct corollary of the determinant formula \cite[Theorem~3]{brito2024alternating}, where the formula there is stated as an equation in the Grothendieck ring of certain category of finite-dimensional representations of $\Uqghat$. Here we only need the resulting formula for their usual $\g$-characters.

\begin{lemma}[{\cite[Theorem~3]{brito2024alternating}}]\label{lemma: determinant formula}



Let $[\mathbf{l},\mathbf{r}]$ be a type $A_{n-1}$ snake of length $T$. Let $A$ be the $T \times T$ matrix whose $(i,j)$-entry is $W(l_i,r_j)$, then
    \begin{equation}
\chi(L([\mathbf{l},\mathbf{r}])) = \det (A) = \sum_{\sigma \in \Sigma_T} (-1)^{\sgn (\sigma)} \prod_{t=1}^T W(l_t,r_{\sigma(t)}),
    \end{equation}
    where $\Sigma_T$ is the permutation group of $T$ elements.
\end{lemma}

\begin{remark}
    The matrix $A$ is slightly different from the matrix $A(\mathbf{s})$ in \cite{brito2024alternating}, but it is easy to see that their determinants are equal.
\end{remark}

\begin{definition}
    For integers $l_1,\dots,l_T,r_1,\dots,r_T \in \ZZ$, we use the notation 
    \begin{equation}\label{eqn: definition of W}
    W(\mathbf{l},\mathbf{r}) = \sum_{\sigma \in \Sigma_T} (-1)^{\sgn (\sigma)} \prod_{t=1}^T W(l_t,r_{\sigma(t)}).\end{equation}
\end{definition}

Lemma~\ref{lemma: determinant formula} states that if $[\mathbf{l},\mathbf{r}]$ is a type $A_{n-1}$ snake, then 
\begin{equation}\label{eqn: chi = W}
    \chi(L([\mathbf{l},\mathbf{r}])) = W(\mathbf{l},\mathbf{r}).
\end{equation}



\begin{corollary}\label{cor: W = 0 when two are equal}
    If $l_i = l_j$ for some $1 \leq i \neq j \leq T$, then $W(\mathbf{l},\mathbf{r}) = 0$. Similarly, if $r_i = r_j$ for some $1 \leq i \neq j \leq T$, then $W(\mathbf{l},\mathbf{r}) = 0$. 
\end{corollary}
\begin{proof}
    The determinant is $0$ when two rows or two columns are identical.
\end{proof}

\subsection{Proof of Theorem~\ref{thm: type A equality}}\label{sebsec: proof of identity}
\subsubsection*{Step 1}\label{step 1}

By \eqref{eqn: chi = W}, the equality~\eqref{eqn: type A equation} is equivalent to  
\begin{equation}\label{eqn: W equation}
    \sum_{\substack{\mathbf{l} \le \mathbf{l}' <  \mathbf{l}[1]\\ |\mathbf{l}'-\mathbf{l}| = M\\ [\mathbf{l}',\mathbf{r}]~\text{is a snake}}} W(\mathbf{l}',\mathbf{r}) = \sum_{\substack{\mathbf{r}[-1] < \mathbf{r}' \le \mathbf{r} \\|\mathbf{r}-\mathbf{r}'| = M\\ [\mathbf{l},\mathbf{r}']~\text{is a snake}}} W(\mathbf{l},\mathbf{r}'),
\end{equation}

Notice that if $[\mathbf{l},\mathbf{r}]$ is a type $A_{n-1}$ snake, then a sequence $\mathbf{l}' = (l_1',\dots,l_T')$ which verifies $\mathbf{l} \le \mathbf{l}' < \mathbf{l}[1]$ is strictly increasing, because $l_t' < l_{t+1} \le l_{t+1}'$, $\forall 1 \le t \le T-1$. Moreover, $r_t - l_t' \le r_t - l_t \le n$, $\forall 1 \le t \le T$.

Therefore, if a multi-segment $[\mathbf{l}',\mathbf{r}]$ is not a type $A_{n-1}$ snake, then there exists a $t$, $1 \le t \le T$, such that $l_t' > r_t$. We claim that $W(\mathbf{l}',\mathbf{r}) = 0$ in this case.

In fact, the entries of the matrix $A$ verify that $A_{ij} = W(l_i',r_j) = 0$ for all $i \ge t$ and $j \le t$, because $l_i' \ge l_t' > r_t \ge r_j$. Any matrix satisfying this condition has determinant $0$.

Similarly, if a multi-segment $[\mathbf{l},\mathbf{r}']$ is not a type $A_{n-1}$ snake, then $W(\mathbf{l},\mathbf{r}') = 0$.

In conclusion, we can drop the condition on snakes in the summation in \eqref{eqn: W equation}, and the equation becomes equivalent to 
\[\sum_{\substack{\mathbf{l} \le \mathbf{l}' <  \mathbf{l}[1]\\ |\mathbf{l}'-\mathbf{l}| = M}} W(\mathbf{l}',\mathbf{r}) = \sum_{\substack{\mathbf{r}[-1] < \mathbf{r}' \le \mathbf{r}\\ |\mathbf{r} - \mathbf{r}'|= M}} W(\mathbf{l},\mathbf{r}'),\]
where $[\mathbf{l},\mathbf{r}]$ is a fixed type $A_{n-1}$ snake, and the sum is taken for sequences $\mathbf{l}'$ (resp. $\mathbf{r'}$).

\subsubsection*{Step 2}\label{step 2}
We prove that for any fixed sequences $\mathbf{l}$ and $\mathbf{r}$, which are not necessarily increasing, we always have 
\[\sum_{\substack{\mathbf{l} \leq  \mathbf{l}'\\ |\mathbf{l}'-\mathbf{l}| = M}} W(\mathbf{l}',\mathbf{r}) = \sum_{\substack{\mathbf{r}' \leq \mathbf{r}\\ |\mathbf{r} - \mathbf{r}'| = M}} W(\mathbf{l},\mathbf{r}'),\]
where $M \in \NN$, and the sums are taken over $\mathbf{l}'$ and $\mathbf{r}'$, respectively.

We calculate that
\[
\begin{split}
    \sum_{\substack{\mathbf{l} \leq  \mathbf{l}'\\ |\mathbf{l}' - \mathbf{l}| = M}} W(\mathbf{l}',\mathbf{r}) &= \sum_{\substack{\mathbf{l} \leq  \mathbf{l}'\\ |\mathbf{l}' - \mathbf{l}| = M}} \sum_{\sigma \in \Sigma_T} (-1)^{\sgn(\sigma)} \prod_{i=1}^T W(l_i',r_{\sigma(i)}) \\
    &= \sum_{\substack{a_1,\dots,a_T \in \NN\\ a_1 + \cdots + a_T = M}} \sum_{\sigma \in \Sigma_T} (-1)^{\sgn(\sigma)} \prod_{i=1}^T W(l_i + a_i,r_{\sigma(i)}).
    \end{split}\]
By Lemma~\ref{lemma: shift invariant}, this is equal to
    \[\begin{split}
    &\sum_{\substack{a_1,\dots,a_T \in \NN\\ a_1 + \cdots + a_T = M}} \sum_{\sigma \in \Sigma_T} (-1)^{\sgn(\sigma)} \prod_{i=1}^T W(l_i,r_{\sigma(i)}-a_i)\\
     &= \sum_{\sigma \in \Sigma_T} (-1)^{\sgn(\sigma)} \sum_{\substack{a_1,\dots,a_T \in \NN\\ a_1 + \cdots + a_T = M}} \prod_{i=1}^T W(l_i,r_{\sigma(i)}-a_i)\\
     &= \sum_{\sigma \in \Sigma_T} (-1)^{\sgn(\sigma)} \sum_{\substack{a_{\sigma(1)},\dots,a_{\sigma(T)} \in \NN\\ a_{\sigma(1)} + \cdots a_{\sigma(T)} = M}} \prod_{i=1}^T W(l_i,r_{\sigma(i)}-a_{\sigma(i)})\\
     &= \sum_{\sigma \in \Sigma_T} (-1)^{\sgn(\sigma)} \sum_{\substack{a_1,\dots,a_T \in \NN\\ a_1 + \cdots + a_T = M}} \prod_{i=1}^T W(l_i,r_{\sigma(i)}-a_{\sigma(i)})\\
    &=\sum_{\substack{a_1,\dots,a_T \in \NN\\ a_1 + \cdots + a_T = M}} \sum_{\sigma \in \Sigma_T} (-1)^{\sgn(\sigma)} \prod_{i=1}^T W(l_i,r_{\sigma(i)}-a_{\sigma(i)})\\   
      &= \sum_{\substack{\mathbf{r}'\leq \mathbf{r}\\ |\mathbf{r} - \mathbf{r}'| = M}} \sum_{\sigma \in \Sigma_T} (-1)^{\sgn(\sigma)} \prod_{i=1}^T W(l_i,r_{\sigma(i)}') =\sum_{\substack{\mathbf{r}'\leq \mathbf{r}\\ |\mathbf{r} - \mathbf{r}'| = M}} W(\mathbf{l},\mathbf{r}').
\end{split}
\]
This completes \nameref{step 2}.

\subsubsection*{Step 3}\label{step 3}
We show that when $[\mathbf{l},\mathbf{r}]$ is a type $A_{n-1}$ snake, then
\[\sum_{\substack{\mathbf{l} \le \mathbf{l}' <  \mathbf{l}[1]\\ |\mathbf{l}' - \mathbf{l}| = M}} W(\mathbf{l}',\mathbf{r}) = \sum_{\substack{\mathbf{l} \le  \mathbf{l}'\\ |\mathbf{l}' - \mathbf{l}| = M}} W(\mathbf{l}',\mathbf{r}),\]
and
\[\sum_{\substack{\mathbf{r}[-1] <  \mathbf{r}' \le \mathbf{r}\\ |\mathbf{r} - \mathbf{r}'| = M}} W(\mathbf{l},\mathbf{r}') = \sum_{\substack{\mathbf{r}' \leq  \mathbf{r}\\ |\mathbf{r} - \mathbf{r}'| = M}} W(\mathbf{l},\mathbf{r}').\]

We prove the first equality, as the second is similar. We need the following lemma.
\begin{lemma}\label{lemma: sum of W = 0 when two are equal}
    Let $\mathbf{p}$, $\mathbf{q}$ be two sequences of integers of length $T$. If $p_i=p_j$ for some $1 \le i \neq j \le T$, then
    \[\sum_{\substack{\mathbf{p} \le  \mathbf{p}'\\|\mathbf{p}'-\mathbf{p}|=M}} W(\mathbf{p}',\mathbf{q}) = 0.\]
\end{lemma}
\begin{proof}
    By the equality proved in \nameref{step 2},
    \[\sum_{\substack{\mathbf{p} \le  \mathbf{p}'\\|\mathbf{p}'-\mathbf{p}|=M}} W(\mathbf{p}',\mathbf{q}) = \sum_{\substack{\mathbf{q}' \le  \mathbf{q}\\ |\mathbf{q}-\mathbf{q}'|=M}} W(\mathbf{p},\mathbf{q}') .\]
    By Corollary~\ref{cor: W = 0 when two are equal}, each term on the right-hand side is $0$.
\end{proof}

Now we are ready to complete \nameref{step 3}. We use the following notation. Let $J = (j_1,\dots,j_T)$ be a sequence such that $j_t \in \{t,t+1\} \cap \{1,2,\dots,T\}$. Denote by $\mathrm{h}(J) = \sum_{t=1}^T (j_t -t)$.

Recall that now we have $l_1 < l_2 < \cdots < l_T$. Basic set theory tells us that for any function $f(\mathbf{l}')$ depending on the sequence $\mathbf{l}'$, we have
\[\sum_{\substack{\mathbf{l} \le \mathbf{l}' < \mathbf{l}[1]\\|\mathbf{l}'-\mathbf{l}|=M}} f(\mathbf{l}') = \sum_J (-1)^{\mathrm{h}(J)} \sum_{\substack{(l_{j_1},l_{j_2},\dots,l_{j_T}) \le \mathbf{l}'\\ |\mathbf{l}'-\mathbf{l}|=M}} f(\mathbf{l}').\]

When $f(\mathbf{l}') = W(\mathbf{l}',\mathbf{r})$, the term for $J = (1,2,\dots,T)$ on the right-hand side equals to $$\sum_{\substack{\mathbf{l} \le \mathbf{l}'\\|\mathbf{l}'-\mathbf{l}|=M}} W(\mathbf{l}',\mathbf{r}),$$ and all other terms corresponding to $J \neq (1,2,\dots,T)$ are zero by Lemma~\ref{lemma: sum of W = 0 when two are equal}, because at least two indices $j_s,j_t$ are equal, $1 \le s \neq t \le T$.

Combining \nameref{step 2} and \nameref{step 3}, we have
\[\sum_{\substack{\mathbf{l} \le \mathbf{l}' <  \mathbf{l}[1]\\ |\mathbf{l}' - \mathbf{l}| = M}}  W(\mathbf{l}',\mathbf{r}) = \sum_{\substack{\mathbf{l} \le  \mathbf{l}'\\ |\mathbf{l}' - \mathbf{l}| = M}}  W(\mathbf{l}',\mathbf{r}) = \sum_{\substack{\mathbf{r}' \le  \mathbf{r}\\ |\mathbf{r} - \mathbf{r}'| = M}} W(\mathbf{l},\mathbf{r}') = \sum_{\substack{\mathbf{r}[-1] <  \mathbf{r}' \le \mathbf{r}\\ |\mathbf{r} - \mathbf{r}'| = M}}W(\mathbf{l},\mathbf{r}').\]

By the conclusion in \nameref{step 1}, we have completed the proof of Theorem~\ref{thm: type A equality}.

\subsection{Paths interpretation}\label{subsec: path interpretation of identity}
In this paper, we will need Theorem~\ref{thm: type A equality} in the language of paths. In this subsection, we derive a corollary of Theorem~\ref{thm: type A equality} formulated in terms of path descriptions.

We recalled the definition of type $A_{2n-1}$ paths in Definition~\ref{def: paths}. In this subsection and the following section, we will need type $A_{n-1}$ paths for all $n \ge 2$. The definition is nearly identical to that in Definition~\ref{def: paths}, but for completeness, we repeat it here with a slight extension that allows $i = 0$ or $i = n$.

\begin{definition}
    For $0 \le i \le n$ and $k \in \ZZ$, a path of type $A_{n-1}$ is a finite sequence $\big( (0,y_0),\dots,(n,y_n) \big)$ in the set 
        \begin{align*}
           \mathscr{P}_{i,k}^{A_{n-1}}:=\{\big( (0,y_0), (1,y_1),& \dots, (n, y_{n}) \big)~| \\ &y_0= i+k, y_{n}=n-i+k, 
            \text{and $\lvert y_{r+1}-y_r \rvert=1$ for $0\leq r \leq n-1$}\}.
        \end{align*}
\end{definition}
    The path description of snake modules of type $A_{2n-1}^{(1)}$ (see Theorem~\ref{path description}) also applies to snake modules of type $A_{n-1}^{(1)}$ \cite[Theorem~6.1]{mukhin2012path}. We note that when $i=0$ or $i=n$, the sets $\mathscr{P}^{A_{n-1}}_{0,k}$ and $\mathscr{P}^{A_{n-1}}_{n,k}$ each consist of only one path, whose associated character is $1$. This gives the path description of the trivial representation.


\begin{lemma}\label{lemma: segment and monomial}
    Given a segment $[l,r]$ of type $A_{n-1}$, let $Y_{r-l,q^{r+l}}$ be its corresponding monomial. A path $p \in \mathscr{P}_{r-l,r+l}$ of type $A_{n-1}$ is a path of the form
    \[p = \big((0,y_0),(1,y_1),\dots,(n,y_n) \big)\]
    such that $y_0 = 2r$ and $y_n = n+2l$.
\end{lemma}
\begin{proof}
    This follows immediately from Definition~\ref{def: paths} and the correspondence between segments and monomials as described in Section~\ref{subsec: main theorem}.
\end{proof}

Fix a sequence of points with first coordinate $0$, 
    $$(0,x_0^{(1)}),(0,x_0^{(2)}),\dots,(0,x_0^{(T)})$$
    such that $x_0^{(1)} < x_0^{(2)} < \cdots < x_0^{(T)}$, and a sequence of points with first coordinate $n$,
    $$(n,x_n^{(1)}),(n,x_n^{(2)}),\dots,(n,x_n^{(T)})$$
    such that $x_n^{(1)} < x_n^{(2)} < \cdots < x_n^{(T)}$. Assume that $-n \le x_n^{(t)} - x_0^{(t)} \le n$ for all $1 \le t \le T$.

\begin{definition}\label{def: sets A and B}
    Given $M \in \NN$, we define the following sets of NOP of type $A_{n-1}$:


    \[\begin{split}
        &A_{x_0^{(1)},\dots,x_0^{(T)}; x_n^{(1)},\dots,x_n^{(T)};M} := \\
        &\{\overline{p} = (p_1,\dots,p_T)~\text{non-overlapping of type}~A_{n-1}~|~(0,y_0^{(t)}) \in p_t~\text{and}~(n,y_n^{(t)}) \in p_t\\
        &\hspace{4cm} \text{such that}~y_0^{(t)} \in 
        \left] x_0^{(t-1)},x_0^{(t)}\right], y_n^{(t)} = x_n^{(t)}~\text{and}~\sum_{t=1}^T(x_0^{(t)} - y_0^{(t)}) = 2M \},
    \end{split}\]
    where $x_0^{(-1)} = -\infty$, and 
    \[\begin{split}
        &B_{x_0^{(1)},\dots,x_0^{(T)}; x_n^{(1)},\dots,x_n^{(T)};M} := \\
        &\{ \overline{p} = (p_1,\dots,p_T)~\text{non-overlapping of type}~A_{n-1}~|~(0,y_0^{(t)}) \in p_t~\text{and}~(n,y_n^{(t)}) \in p_t\\
        &\hspace{4cm} \text{such that}~y_0^{(t)} = x_0^{(t)}, y_n^{(t)} \in \left[ x_n^{(t)},x_n^{(t+1)}\right[~\text{and}~\sum_{t=1}^T(y_n^{(t)}-x_n^{(t)}) = 2M \},
    \end{split}\]
    where $x_n^{(T+1)} = \infty$.
\end{definition}    


