\begin{corollary}\label{cor: cerrespondence of type A paths}
    The equality in Theorem~\ref{thm: type A equality} induces a (non-unique) bijection between the sets $$A_{x_0^{(1)},\dots,x_0^{(T)}; x_n^{(1)},\dots,x_n^{(T)};M}~\text{and}~B_{x_0^{(1)},\dots,x_0^{(T)}; x_n^{(1)},\dots,x_n^{(T)};M}.$$ Moreover, if we write $\overline{p}_A$ and $\overline{p}_B$ as the corresponding paths under this bijection, then $$\mathfrak{m}'(\overline{p}_A) = \mathfrak{m}'(\overline{p}_B),$$ where $\mathfrak{m}'$ is the associated $\g$-weight defined in Corollary~\ref{character-path}.
\end{corollary}
\begin{proof}
    By Lemma~\ref{lemma: segment and monomial}, the set of NOP $\overline{p} \in A_{x_0^{(1)},\dots,x_0^{(T)}; x_n^{(1)},\dots,x_n^{(T)};M}$ with left endpoints $(0,y_0^{(1)}),\dots,(0,y_0^{(T)})$ form the path description of the snake module $L([\mathbf{l},\mathbf{r}])$, such that $l_t = \frac{x_n^{(t)} - n}{2}$ and $r_t = \frac{y_0^{(t)}}{2}$, $1 \le t \le T$. Therefore, by Corollary~\ref{character-path}, there is a bijection between the set $A_{x_0^{(1)},\dots,x_0^{(T)}; x_n^{(1)},\dots,x_n^{(T)};M}$ and the set of terms in the character on the left-hand side of \eqref{eqn: type A equation}, which maps a $T$-tuple of NOP $\overline{p}$ to its associated character $\mathfrak{m}'(\overline{p})$.

    Similarly, the set $B_{x_0^{(1)},\dots,x_0^{(T)}; x_n^{(1)},\dots,x_n^{(T)};M}$ is in bijection with terms on the right-hand side of \eqref{eqn: type A equation} in the same way.

    Therefore, Theorem~\ref{thm: type A equality} induces a (non-unique) bijection between paths in the two sets, preserving their associated character.
\end{proof}

In addition to the above corollary, this bijection also preserves what we call the \textit{half-character at $n$} as follows.

\begin{definition}
    For a path $p = \big((0,y_0),(1,y_1),\dots,(n,y_n) \big)$ of type $A_{n-1}$, we say that its half-character at $n$ is $\omega_n'$ if $y_{n} = y_{n-1}-1$, and we say that its half-character at $n$ is $-\omega_n'$ if $y_{n} = y_{n-1}+1$.

    The half-character at $n$ of a $T$-tuple of NOP is defined as the sum of the half-characters at $n$ of each individual path.

    In other words, we have a simple expression that the half-character at $n$ of $\overline{p}$ equals to
    \[\big(\sum_{t=1}^T (y_{n-1}^{(t)} - y_n^{(t)})\big) \omega_n',\]
    where $(n-1,y_{n-1}^{(t)}),(n,y_n^{(t)}) \in p_t$, $1 \le t \le T$.
\end{definition}

\begin{proposition}\label{prop: bijection preseves half-character}
    The bijection in Corollary~\ref{cor: cerrespondence of type A paths} preserves the half-character at $n$.
\end{proposition}
\begin{proof}
    We begin with a single path $p$ with endpoints $(0,y_0)$ and $(n,y_n)$. Let $\mathfrak{m}'(p) = k_1\omega_1 + \cdots k_{n-1}\omega_{n-1}$ be its associated weight. Let $k_n'\omega_n'$ be its half-character at $n$, $k_n' \in \{\pm 1\}$. We claim that 
    \[y_0 - y_n = 2k_1 + 4k_2 + \cdots + 2(n-1)k_{n-1}+nk_n'.\]

    In fact, we note that at each $1 \le j \le n-1$, $(j,y_j)$ is  
    \begin{itemize}
        \item an upper corner of $p$ if and only if $y_{j-1} - 2y_{j} + y_{j+1}= 2$,
        \item a lower corner of $p$ if and only if $y_{j-1} - 2y_{j} + y_{j+1}= -2$,
        \item neither an upper corner nor a lower corner if and only if $y_{j-1} - 2y_{j} + y_{j+1}= 0$.
    \end{itemize}
    Therefore, $2k_j = y_{j-1} - 2y_j + y_{j+1}$. Then we can calculate that 
    \[y_0 - y_n = \sum_{j=1}^{n-1}j(y_{j-1}-2y_j+y_{j+1}) + ny_{n-1} -ny_n = \sum_{j=1}^{n-1} 2jk_j + nk_n'.\]

    Since the weight $\mathfrak{m}'$ of a $T$-tuple of NOP is the sum of the weight of each single path, for a $T$-tuple of NOP $\overline{p} = (p_1,\dots,p_T)$, whose associated weight is $\mathfrak{m}'(\overline{p}) = k_1\omega_1 + \cdots k_{n-1}\omega_{n-1}$, and whose half-character at $n$ is $k_n'\omega_n'$, $k_n' \in \ZZ$, we have 
    \[\sum_{t=1}^T (y_0^{(t)} - y_n^{(t)}) = 2k_1 + 4k_2 + \cdots + 2(n-1)k_{n-1}+nk_n',\]
    where $(0,y_0^{(t)}), (n,y_n^{(t)}) \in p_t$.

    Note that the one-to-one correspondence in Corollary~\ref{cor: cerrespondence of type A paths} preserves the weight $\mathfrak{m}'$, and it also preserves the sum $\sum_{t=1}^T (y_0^{(t)} - y_n^{(t)})$, which equals to $\sum_{t=1}^T (x_0^{(t)} - x_n^{(t)}) - 2M$. By the above identity, the one-to-one correspondence preserves $k_n'$ as well.
\end{proof}

\section{Langlands branching rule}\label{sec:Langlands branching rule}
We have proved in Theorem~\ref{thm: langlands dual rep A to B} that for a shortened snake module $V$ of $\Uqghat$ of type $B_n^{(1)}$, there is a shortened snake module ${}^L{V}$ of $\Uqghatdual$, whose highest weights are in correspondence, such that $\chi^{\sigma}({}^L{V}) \preceq \Pi (\chi(V))$. We have also established a criteria, using the notion of gaps, to determine which term of $\Pi(\chi(V))$ appears in the character of ${}^L{V}$. In this section, we establish an equality
\[ \Pi(\chi(V)) = \chi^{\sigma}({}^L{V})  + \sum_W \chi^{\sigma}(W),\]
which decomposes $\Pi(\chi(V))$ into a sum of characters of irreducible representations of $\Uqghatdual$.

\subsection{Paths of non-zero gap}
Given a shortened snake $(i_t,k_t)_{1 \le t \le T}$ of type $B_n$. Let $V = L(\prod_{t:i_t \neq n}Y_{i_t,q^{k_t}} \prod_{t: i_t=n}Y_{n,q^{k_t-1}}Y_{n,q^{k_t+1}})$ be the corresponding shortened snake module of the quantum affine algebra of type $B_n^{(1)}$.

Let $(p_1,\dots,p_T) \in \overline{\mathscr{P}}^B_{(i_t,k_t)_{1\leq t \leq T}}$ be a $T$-tuple of NOP for this module. Recall that we have defined a map $F^{-1}$ in Proposition~\ref{prop: level 0 bijection} which associates each path $p \in \mathscr{P}_{i,k}^B$ of gap $0$ to a path $F^{-1}(p)$ in $\mathscr{P}^A_{i,\frac{k}{2}}$, where the notion gap is defined in Definition~\ref{def: level}.

In this subsection, we generalize the map $F^{-1}$ to paths of arbitrary gap.

For a single path $p \in \mathscr{P}_{i,k}^B$, suppose that
    \begin{align*}
        && p = \big( (0,y_0), &(2,y_1), \dots, (2n-4, y_{n-2}), (2n-2,y_{n-1}), (2n-1,y_n), \\
        && &(2n-1,z_n), (2n,z_{n-1}),\dots,(4n-4,z_1),(4n-2,z_0) \big),
    \end{align*}
then we define a pair of type $A_{n-1}$ paths by
    \begin{align*}
        L(p) = \big( (0,\frac{y_0}{2}),(1,\frac{y_1}{2}), \dots, (n-1, \frac{y_{n-1}}{2}), (n,\lfloor \frac{y_{n}+1}{2} \rfloor) \big) \in \mathscr{P}^{A_{n-1}}_{i,k},
    \end{align*}
    where $i = \frac{y_0-2 \lfloor \frac{y_{n}+1}{2} \rfloor+ 2n}{4}$, $k = \frac{y_0+ 2 \lfloor \frac{y_{n}+1}{2} \rfloor-2n}{4}$,
    and 
    \begin{align*}
        R(p) = \big((n,\lfloor \frac{z_n + 3}{2} \rfloor), (n+1,\frac{z_{n-1}+2}{2}),\dots,(2n-1,\frac{z_1+2}{2}), (2n,\frac{z_0+2}{2}) \big),
    \end{align*}
     where we label the first coordinate from $n$ to $2n$, instead of from $0$ to $n$, for later simplicity.

$L(p)$ and $R(p)$ are respectively determined by the left and the right branch of $p$.

For a $T$-tuple of NOP $\overline{p} = (p_1,\dots,p_T) \in \overline{\mathscr{P}}^B_{(i_t,k_t)_{1\leq t \leq T}}$, we associate it with a pair of NOP of type $A_{n-1}$: $(L(p_1),\dots,L(p_T))$ and $(R(p_1),\dots,R(p_T))$.


\begin{lemma}
    We have
    \[\lfloor \frac{z_n^{(t)}+3}{2} \rfloor \le \lfloor \frac{y_n^{(t)}+1}{2} \rfloor, \quad \forall 1 \le t \le T,\]
    and 
    \[ \lfloor \frac{y_n^{(t)}+1}{2} \rfloor < \lfloor \frac{z_n^{(t+1)}+3}{2} \rfloor, \quad \forall 1 \le t \le T-1. \]
\end{lemma}
\begin{proof}
    We have seen the first equality in the definition of gaps. For the second inequality, one notice that $p_t \succ p_{t+1}$ implies $y_n^{(t)} < z_n^{(t+1)}$, thus $\lfloor \frac{y_n^{(t)}+1}{2} \rfloor < \lfloor \frac{z_n^{(t+1)}+3}{2} \rfloor$.
\end{proof}

The following proposition is an analogue of Lemma~\ref{lemma: F injective} and Proposition~\ref{prop: level 0 bijection}.
\begin{proposition}
    The map which associates $\overline{p}$ with $(L(\overline{p}),R(\overline{p}))$ defines a bijection between the set $\overline{\mathscr{P}}^B_{(i_t,k_t)_{1\leq t \leq T}}$ and the set
    \[\begin{split}
        \{(\overline{q}',\overline{q})~&\text{a pair of $T$-tuples of NOP of type}~A_{n-1}~|~(0,i_t+\frac{k_t}{2}) \in q_t',\\
        &(2n,2n-i_t+\frac{k_t}{2}) \in q_t,~{x_n}^{(1)} \le {x_n'}^{(1)} < {x_n}^{(2)} \le {x_n'}^{(2)} < \cdots < {x_n}^{(T)} \le {x_n'}^{(T)}\},
    \end{split}
    \]
    where $\overline{q}' = (q_1',\dots,q_T')$, $\overline{q} = (q_1,\dots,q_T)$, and $(n,{x_n'}^{(t)}) \in q_t'$, $(n,{x_n}^{(t)}) \in q_t$, $\forall t$.
\end{proposition}
\begin{proof}
    The injectivity follows immediately from the definition of $L(p)$ and $R(p)$.

    We prove the surjectivity by writing down the preimage explicitly. Given a pair of paths $(q',q)$ of type $A_{n-1}$ such that $(0,i+\frac{k}{2}) \in q'$, $(2n,2n-i+\frac{k}{2}) \in q$ and $x_n \le x_n'$, where $(n,x_n') \in q'$, $(n,x_n) \in q$, we write their points as $(j,x_j') \in q'$ and $(j,x_j) \in q$, $0 \le j \le n$.

    Its preimage is the type $B_n$ path in $\mathscr{P}^B_{i,k}$ of the form 
    \begin{align*}
        p = \big( (0,y_0), &(2,y_1), \dots, (2n-4, y_{n-2}), (2n-2,y_{n-1}), (2n-1,y_n), \\
         &(2n-1,z_n), (2n,z_{n-1}),\dots,(4n-4,z_1),(4n-2,z_0) \big),
    \end{align*}
    with coordinates 
    \[y_j = 
    \begin{cases}
        2x_j', &\text{if}~j < n,\\
        2x_n'-1 + \epsilon, &\text{if}~j=n~\text{and}~x_n'>x_{n-1}', \\
        2x_n'+1-\epsilon, &\text{if}~j=n~\text{and}~x_n'<x_{n-1}',
    \end{cases}
    \]
    and
    \[z_j = 
    \begin{cases}
        2x_{2n-j}-2, &\text{if}~j < n,\\
        2x_n-3 + \epsilon, &\text{if}~j=n~\text{and}~x_n>x_{n+1}, \\
        2x_n-1-\epsilon, &\text{if}~j=n~\text{and}~x_n<x_{n+1}.
    \end{cases}
    \]
    One verifies directly that $L(p) = q'$ and $R(p) = q$.

    For a pair of $T$-tuples of NOP $(\overline{q}',\overline{q})$ satisfying the condition in the proposition, the preimage is the $T$-tuple of NOP formed by taking the preimage of each component. Note that, by definition of type $A_{n-1}$ paths, we have ${x_n'}^{(t)} \equiv {x_n}^{(t+1)} \pmod 2$. Therefore, the condition ${x_n'}^{(t)} < {x_n}^{(t+1)}$ implies ${x_n'}^{(t)} \le {x_n}^{(t+1)} -2$, which ensures that the preimage is non-overlapping.
\end{proof}

\begin{remark}
    We notice that the formula for the preimage of $(L(p),R(p))$ is almost identical to the formula of the map $F$ defined in Definition~\ref{def: map F between paths}, except that $F^{-1}$ requires the path to have gap $0$. Therefore, this construction can be regarded as a generalization of the map $F$ to the case of arbitrary gaps.
\end{remark}

Recall that the gap of $\overline{p} = (p_1,\dots,p_T) \in \overline{\mathscr{P}}^B_{(i_t,k_t)_{1\leq t \leq T}}$ is defined as \[\mathrm{gap}(\overline{p}) := \sum_{t=1}^T (\lfloor \frac{y_n^{(t)}+1}{2} \rfloor -  \lfloor \frac{z_n^{(t)}+3}{2} \rfloor),\]
where $(2n-1,y_n^{(t)}), (2n-1,z_n^{(t)}) \in p_t$. This suggests that $\overline{p}$ has gap $0$ if and only if the right endpoints of $L(p_t)$ coincide with the left endpoints of $R(p_t)$ for all $1 \le t \le T$.

We have proved in Section~\ref{subsec: Langlands dual from B to A} that $T$-tuples of NOP $(p_1,\dots,p_T) \in \overline{\mathscr{P}}^B_{(i_t,k_t)_{1\leq t \leq T}}$ having gap $0$ are in one-to-one correspondence with $T$-tuples of NOP in $\overline{\mathscr{P}}^A_{(i_t,\frac{k_t}{2})_{1\leq t \leq T}}$. In this section, we construct a correspondence between all NOP $(p_1,\dots,p_T) \in \overline{\mathscr{P}}^B_{(i_t,k_t)_{1\leq t \leq T}}$ and type $A_{2n-1}$ NOP.


\subsection{Bijection between type \texorpdfstring{$B_n$}{} paths and type \texorpdfstring{$A_{2n-1}$}{} paths}
Fix a shortened snake $(i_t,k_t)_{1 \le t \le T}$ of type $B_n$. Fix a $T$-tuple of NOP $\overline{q} = (q_1,\dots,q_T)$ of type $A_{n-1}$ such that $(2n,2n-i_t+\frac{k_t}{2}) \in q_t$. Here we label their first coordinates of $\overline{q}$ from $n$ to $2n$, instead of from $0$ to $n$, as above. We denote the left endpoints of $q_t$ by $(n,x^{(t)})$, $1 \le t \le T$.

\begin{definition}
    For a given $T$-tuple of NOP $\overline{q}$ of type $A_{n-1}$, we denote by
    \[L_{\overline{q}} = \{(p_1,\dots,p_T) \in \overline{\mathscr{P}}^B_{(i_t,k_t)_{1\leq t \leq T}}~|~(R(p_1),\dots,R(p_T)) = \overline{q} \}.\]
\end{definition}

In other words, this is the set of $(p_1,\dots,p_T) \in \overline{\mathscr{P}}^B_{(i_t,k_t)_{1\leq t \leq T}}$ such that their associated $(R(p_1),\dots,R(p_T))$ are the same and equal to the given $\overline{q}$.



By the path description of type $B_n$ snake modules, $(p_1,p_2,\dots,p_T) \in L_{\overline{q}}$ if and only if $(R(p_1),\dots,R(p_T))=\overline{q}$ and $(L(p_1),\dots,L(p_T))$ is a $T$-tuple of NOP of type $A_{n-1}$ such that 
\begin{itemize}
    \item the left endpoints are fixed by the snake as $(0,\frac{y_0^{(t)}}{2}) = (0,\frac{2i_t+k_t}{2}) \in L(p_t)$,
    \item and the right endpoints are $(n,a_n^{(t)}): = (n, \lfloor \frac{y_{n}^{(t)}+1}{2} \rfloor)$ such that 
    \[x^{(t)} \le a_n^{(t)} < x^{(t+1)}, \]
    where $x^{(t)} = \lfloor \frac{z_n^{(t)} + 3}{2} \rfloor$.
\end{itemize}

In other words, $(L(p_1),\dots,L(p_T))$ is a $T$-tuple of NOP of type $A_{n-1}$ in the set $$B_{\frac{2i_1+k_1}{2},\dots,\frac{2i_T+k_T}{2};x^{(1)},\dots,x^{(T)};M}$$
defined in Definition~\ref{def: sets A and B}, for some integer $M \in \NN$. Here, by definition, $M$ equals to the gap of $\overline{p} = (p_1,\dots,p_T)$.

By Corollary~\ref{cor: cerrespondence of type A paths}, these $T$-tuples of NOP are in one-to-one correspondence with $T$-tuples of NOP in the set 
$A_{\frac{2i_1+k_1}{2},\dots,\frac{2i_T+k_T}{2};x^{(1)},\dots,x^{(T)};M}$, in such a way that the associated character $\mathfrak{m}'(L(p_1),\dots,L(p_T))$ and also the associated half-character at $n$ are preserved.

Notice that for any $T$-tuple of NOP $(p_1,\dots,p_T)$ in $A_{\frac{2i_1+k_1}{2},\dots,\frac{2i_T+k_T}{2};x^{(1)},\dots,x^{(T)};M}$, the right endpoint of $p_t$ coincides with the left endpoint of $q_t$, which are both $x^{(t)} = \lfloor \frac{z_n^{(t)}+3}{2} \rfloor$. Therefore, these paths together with $\overline{q}$ connected to the right from a $T$-tuple of NOP of type $A_{2n-1}$.

In this way, we have associated a $T$-tuple of NOP of type $B_{n}$ with a $T$-tuple of NOP of type $A_{2n-1}$. An example is illustrated in Figure~\ref{fig: s and p in correspondence}.

In conclusion, we have
\begin{proposition}\label{prop: decomposition theorem}
    Given a fixed $T$-tuple of NOP $\overline{q} = (q_1,\cdots,q_T)$ of type $A_{n-1}$ and a fixed integer $M \in \NN$, let $(n,x^{(t)}) \in q_t$ be the left endpoint of $q_t$. There is a bijection between the set
    $$\{\overline{p} \in L_{\overline{q}}~|~\mathrm{gap}(\overline{p}) = M\}$$
    and the set 
    \begin{align*}
        \mathcal{S}_{\overline{q},M} : = \{\overline{s} = (s_1,\dots,s_T)~\text{$T$-tuple of NOP of type}~A_{2n-1}~| \\
        \overline{s}|_{[0,n]} \in A_{\frac{2i_1+k_1}{2},\dots,\frac{2i_T+k_T}{2};x^{(1)},\dots,x^{(T)};M}~\text{and}~\overline{s}|_{[n,2n]} = \overline{q} \},
    \end{align*}
    where $\overline{s}|_{[0,n]}$ is the $T$-tuple of NOP of type $A_{n-1}$ formed by the subsequences of each $s_t$ consisting of points whose first coordinate ranges from $0$ to $n$. The tuple $\overline{s}|_{[n,2n]}$ is defined similarly. 

    Moreover, this correspondence preserves character in the sense that
    \[\Pi \circ \mathfrak{m}'(\overline{p}) = \varpi \circ \mathfrak{m}'(\overline{s})\]
    for all $\overline{p}$ and $\overline{s}$ in correspondence, where $\varpi$ is the folding map on weights defined in Proposition~\ref{prop: fold character}.
\end{proposition}
\begin{proof}
    The bijection has been explained above. We verify the equation of associated weights. 

    Recall that for a tuple of NOP $\overline{p}$ of type $B_n$, its associated character \begin{equation}\label{eqn: mp}
    \mathfrak{m}'(\overline{p}) = \mathfrak{m}'(L(\overline{p})) + \mathfrak{m}'(R(\overline{p})) + k_n'(L(\overline{p})) + k_n'(R(\overline{p})),
    \end{equation}
    where $\mathfrak{m}'(L(\overline{p}))$ and $\mathfrak{m}'(R(\overline{p}))$ are the associated defined by upper corners and lower corners, which is a linear combination of $\omega_j$ ($1 \le j \le n-1$), and $k_n'(L(\overline{p}))$ (resp. $k_n'(R(\overline{p}))$) is the half-character at $n$ of $L(\overline{p})$ (resp. $R(\overline{p})$), which is a multiple of $\omega_n$.

    By Proposition~\ref{prop: bijection preseves half-character}, the bijection which maps $L(\overline{p})$ to $\overline{s}|_{[0,n]}$ preserves the associated character and the half-character at $n$. Therefore, $\mathfrak{m}'(L(\overline{p})) = \mathfrak{m}'(\overline{s}|_{[0,n]})$ and
    \[k_n'(L(\overline{p})) = k_n'(\overline{s}|_{[0,n]}) = \sum_{t=1}^T (b_{n-1}^{(t)} - b_n^{(t)}),\]
    where $(n-1,b_{n-1}^{(t)}), (n,b_n^{(t)}) \in s_t$, $1 \le t \le T$.

    The right branch $R(\overline{p})$ coincides with $\overline{s}|_{[n,2n]}$, thus 
    \[k_n'(R(\overline{p})) = k_n'(\overline{s}|_{[n,2n]}) = \sum_{t=1}^T (b_{n+1}^{(t)} - b_n^{(t)}),\]
    where $(n+1,b_{n+1}^{(t)})\in s_t$, $1 \le t \le T$.

    Recall that the multiplicity of $\omega_n$ in $\mathfrak{m}'(\overline{s})$ equals to
    \[\frac{1}{2} \sum_{t=1}^T (b_{n-1}^{(t)} - 2b_n^{(t)} + b_{n+1}^{(t)}),\]
    as we have seen in the proof of Proposition~\ref{prop: bijection preseves half-character}. Thus we have 
    \begin{equation}\label{eqn: ms}
        \mathfrak{m}'(\overline{s}) = \mathfrak{m}'(\overline{s}|_{[0,n]}) + \mathfrak{m}'(\overline{s}|_{[n,2n]}) + \frac{1}{2} (k_n'(L(\overline{p})) + k_n'(R(\overline{p})) ).
    \end{equation}

    The identity follows from \eqref{eqn: mp}, \eqref{eqn: ms} and the definition of $\varpi$ and $\Pi$.
\end{proof}

