Combining all possible $\overline{q} = (R(p_1),\dots,R(p_T))$ and all $M \in \NN$, the following theorem is derived immediately from the the above proposition.

\begin{theorem}
    Given a shortened snake $(i_t,k_t)_{1 \le t \le T}$ of type $B_n$, there is a bijection between the set $\overline{\mathscr{P}}^B_{(i_t,k_t)_{1 \le t \le T}}$ and the set 
     \begin{align*}
        \mathcal{S} := \{\overline{s} = (s_1,\dots,s_T)~\text{NOP of type}~A_{2n-1}~|~(2n,2n-i_t+\frac{k_t}{2}) \in s_t \\
        \text{and}~(0,y_0^{(t)})\in s_t~\text{with}~y_0^{(t)}\in \left]i_{t-1}+\frac{k_{t-1}}{2}, i_t + \frac{k_t}{2} \right] , \forall 2 \le t \le T \},
    \end{align*}
    where we view $i_0 + \frac{k_0}{2}$ as $-\infty$.

    Moreover, this bijection preserves the character in the sense that
    \[\Pi \circ \mathfrak{m}'(\overline{p}) = \varpi \circ \mathfrak{m}'(\overline{s})\]
    for all $\overline{p} \in \overline{\mathscr{P}}^B_{(i_t,k_t)_{1 \le t \le T}}$ and $\overline{s} \in \mathcal{S}$ in correspondence.
\end{theorem}
\begin{proof}
    Notice that
    \[\overline{\mathscr{P}}^B_{(i_t,k_t)_{1 \le t \le T}} = \bigsqcup_{\substack{\overline{q}~\text{such that}\\(2n,2n-i_t+\frac{k_t}{2}) \in q_t}} \bigsqcup_{M \in \NN} \{\overline{p} \in L_{\overline{q}}~|~\mathrm{gap}(\overline{p}) = M\},\]
    and 
    \begin{align*}
        \mathcal{S} = \bigsqcup_{\substack{\overline{q}~\text{such that}\\(2n,2n-i_t+\frac{k_t}{2}) \in q_t}} \bigsqcup_{M \in \NN} \mathcal{S}_{\overline{q},M}.
    \end{align*}
    The theorem follows from Proposition~\ref{prop: decomposition theorem} immediately.
\end{proof}

Finally, by applying Corollary~\ref{character-path}, we conclude our main theorem.

\begin{theorem}\label{thm: langlands branching rule}
    Let $(i_t,k_t)_{1 \le t \le T}$ be a shortened snake of type $B_n$. Let 
    $$m = \prod_{t:i_t \neq n}Y_{i_t,q^{k_t}} \prod_{t: i_t=n}Y_{n,q^{k_t-1}}Y_{n,q^{k_t+1}}$$ be the dominant monomial defined by the snake. Then
    \begin{equation}\label{eqn: decomposition equality}
    \Pi(\chi(L(m))) = \sum_{[\mathbf{l},\mathbf{r}]} \varpi (\chi(L([\mathbf{l}, \mathbf{r}]))),
    \end{equation}
    where the sum on the right-hand side is taken over all snake modules of type $A_{2n-1}$ such that $l_t = \frac{-2i_t+k_t}{4}$ and $\frac{2i_{t-1}+k_{t-1}}{4} < r_t \le \frac{2i_t+k_t}{4}$, $\forall 1 \le t \le T$. Here $\frac{-2i_0+k_0}{4}$ is understood as $-\infty$.

    Equivalently, applying Proposition~\ref{prop: fold character}, we can write \eqref{eqn: decomposition equality} as
    \begin{equation}
        \Pi(\chi(L(m))) = \sum_{s_t} \chi^{\sigma}(L(\prod_{t=1}^T Z_{i_t - s_t,q^{\frac{k_t}{2}- s_t}})),
    \end{equation}
    where the sum on the right-hand side is taken over $T$-tuples of integers $(s_1,\dots,s_T)$ such that $0 \le s_t < \min( \frac{2i_t+k_t-2i_{t-1}-k_{t-1}}{4}, i_t+1)$, where a term $Y_{0,q^c}$ ($c \in \ZZ$) should be understood as $1$.

    In particular, the leading term, which corresponds to the $T$-tuple of integers $(s_1,\dots,s_T) = (0,\dots,0)$ is the Langlands dual representation that we obtained in Theorem~\ref{thm: langlands dual rep A to B}.
\end{theorem}

We close this section with an example of the branching rule.

\begin{example}
    For a fixed $i \in I$, let $(i_t,k_t) = (i,4t)$, $1 \le t \le T$, be a shortened snake of type $B_n$. The associated snake module is 
    \[W^{(i)}_{T,q^4} = L(Y_{i,q^4}Y_{i,q^8}Y_{i,q^{12}}\cdots Y_{i,q^{4T}})~\text{if}~i \neq n,\]
    \[W^{(n)}_{2T,q^3} = L(Y_{n,q^3}Y_{n,q^5}Y_{n,q^7}\cdots Y_{i,q^{4T+1}})~\text{if}~i = n,\]
    which are known as Kirillov-Reshetikhin modules.

    Then the Langlands branching rule states that
    \[\Pi(\chi(W^{(i)}_{T,q^4})) = \sum_{k=0}^{i} \chi^{\sigma}(L(Z_{i-k,q^{2-k}}Z_{i,q^4}\cdots Z_{i,q^{2T}})),\]
    where $Z_{0,q^{2-i}}$ in the last term is understood as $1$.

    Similarly,
    \[\Pi(\chi(W^{(i)}_{2T,q^3})) = \sum_{k=0}^{n} \chi^{\sigma}(L(Z_{n-k,q^{2-k}}Z_{n,q^4}\cdots Z_{n,q^{2T}})),\]
    where $Z_{0,q^{2-n}}$ in the last term is understood as $1$.
\end{example}



\section{Langlands dual from \texorpdfstring{$A_{2n-1}^{(2)}$}{} to \texorpdfstring{$B_n^{(1)}$}{}}\label{sec:A to B}
Having established the Langlands branching rule from type $B_n^{(1)}$ to type $A_{2n-1}^{(2)}$, we now turn to the question of Langlands duality in the opposite direction, namely from $A_{2n-1}^{(2)}$ to $B_n^{(1)}$.

In \cite[Theorem~6.8]{frenkel2011langlandsfinite}, it is also proved that Kirillov-Reshetikhin modules of twisted type admit Langlands dual representations, using the interpolating $(q,t)$-characters. In this section, we provide an alternative proof of their theorem for the case of type $A_{2n-1}^{(2)}$ to type $B_n^{(1)}$, using the path description. 

%\subsection{Kirillov-Reshetikhin modules}

As above, we denote by $\Uqghat$ the non-twisted quantum affine algebra of type $B_n^{(1)}$ and $\Uqghatdual$ the twisted quantum affine algebra of type $A_{2n-1}^{(2)}$.

\begin{definition}
    Recall that $P$ is the weight lattice of type $B_n$, $\leftindex^L{P}$ is the dual to the root lattice of type $B_n$. 

    Let $\leftindex^L {P}'$ be the sublattice of $\leftindex^L {P}$ defined by $\leftindex^L {P}' = \bigoplus_{i \in I} d_i \check{\omega}_{\bar{i}}$, where $d_i = 2$ for $i \neq n$, and $d_n = 1$.

    There is a bijective linear map
    \[\leftindex^L{P}' \to P, \quad d_i \check{\omega}_{\bar{i}} \mapsto \omega_i, \forall i \]
    and we extend it to a surjective map
    \[\leftindex^L {\Pi} :\leftindex^L{P} \to P\]
    such that $\leftindex^L {\Pi}(\lambda) = 0$ if $\lambda \notin \leftindex^L {P}'$.
\end{definition}

We remark that, unlike the weight lattice of type $B_n$, where the root lattice $R \subset P'$ is a sublattice of $P'$, in the dual case, $\leftindex^L{R}$ is not a sublattice of $\leftindex^L{P}'$. Therefore, the definition must be extended to the entire lattice $\leftindex^L{P}$ so that the expression $\leftindex^L{\Pi}(\chi^{\sigma}(V))$ make sense.

\begin{lemma}\label{lemma: tensor irreducible}
    For $i \in I$ and $T \in \NN^*$, the tensor product of Kirillov-Reshetikhin modules of $\Uqghatdual$
    \[L(Z_{i,a}Z_{i,aq^2}\cdots Z_{i,aq^{2T-2}})\otimes L(Z_{i,-a}Z_{i,-aq^2}\cdots Z_{i,-aq^{2T-2}})\]
    is irreducible.
\end{lemma}
\begin{proof}
    It is well-known that for $1 \le i \le n$ the representation
    \[L(Y_{i,a}Y_{i,aq^2}\cdots Y_{i,aq^{2T-2}})\otimes L(Y_{2n-i,a}Y_{2n-i,aq^2}\cdots Y_{2n-i,aq^{2T-2}})\]
    of the quantum affine algebra of type $A_{2n-1}^{(1)}$ is irreducible. Moreover, it is special in the sense that its $q$-character has a unique dominant monomial. This is due to the fact that Kirillov-Reshetikhin modules are right-minuscule, see, for example, \cite{hernandez2006kirillov}. As a consequence, the tensor product is isomorphic to the irreducible $l$-highest weight module 
    \[V := L(Y_{i,a}Y_{i,aq^2}\cdots Y_{i,aq^{2T-2}}Y_{2n-i,a}Y_{2n-i,aq^2}\cdots Y_{2n-i,aq^{2T-2}}).\]

    For the same reason as in \cite[Theorem~4.15]{hernandez2010kirillov},
    \[\pi(\chi_q(V))= \chi_q^{\sigma}(L(Z_{i,a}Z_{i,aq^2}\cdots Z_{i,aq^{2T-2}}Z_{i,-a}Z_{i,-aq^2}\cdots Z_{i,-aq^{2T-2}})).\]

    The module on the right-hand side is a subquotient of the tensor product 
    \[L(Z_{i,a}Z_{i,aq^2}\cdots Z_{i,aq^{2T-2}})\otimes L(Z_{i,-a}Z_{i,-aq^2}\cdots Z_{i,-aq^{2T-2}}),\]
    and they have the same $q$-character. Therefore, the tensor product is isomorphic to 
    \[L(Z_{i,a}\cdots Z_{i,aq^{2T-2}} Z_{i,-a}\cdots Z_{i,-aq^{2T-2}}),\]
    thus irreducible.
\end{proof}

These modules are called generalized Kirillov-Reshetikhin modules in \cite[Section~6.3]{frenkel2011langlandsfinite}. 

\begin{definition}
    A \textit{generalized Kirillov-Reshetikhin module} of $\Uqghatdual$ is 
    \[W_{T,a}^{(i)} = L(Z_{i,a}\cdots Z_{i,aq^{2T-2}} Z_{i,-a}\cdots Z_{i,-aq^{2T-2}}), \quad \text{$T \in \NN^*$, $a \in \CC^*$}.\]
\end{definition}


By the above lemma, the path description of type $A$ implies that a monomial in the $q$-character $\chi_q(W^{(i)}_{T,a})$ corresponds to a pair of $T$-tuples of NOP.

\begin{proposition}
    Let $\overline{\mathscr{P}}^A_{1}$ be the set of $T$-tuples of NOP associated to the snake 
    $$(i,k)(i,k+2)\cdots(i,k+2T-2).$$ 
    Let $\overline{\mathscr{P}}^A_{2}$ be the set of $T$-tuples of NOP associated to the snake 
    $$(2n-i,k)(2n-i,k+2)\cdots(2n-i,k+2T-2).$$ 
    Then
    \[\chi_q(W^{(i)}_{T,q^k}) = \sum_{(\overline{p}_1,\overline{p}_2) \in \overline{\mathscr{P}}^A_{1} \times \overline{\mathscr{P}}^A_{2}} \mathfrak{m}(\overline{p}_1) \mathfrak{m}(\overline{p}_2).
    \]
\end{proposition}

Our goal is to construct an injective map from $\overline{\mathscr{P}}^B_{(i_t,k_t)}$ associated to the snake 
\[(i_t,k_t)_{1 \leq t \leq T} = \big( (i,2k)(i,2k+4)\cdots(i,2k+4T-4) \big)\] to $\overline{\mathscr{P}}^A_{1} \times \overline{\mathscr{P}}^A_{2}$.

As above, we begin with the construction for a single path, then we pass to a $T$-tuple of NOP.

\begin{definition}
    Let $p \in \mathscr{P}^B_{i,2k}$, $(i,2k) \in \mathcal{X}^B$. We define a pair of paths in $\mathscr{P}^A_{i,k} \times \mathscr{P}^A_{2n-i,k}$ in the following way.

    Write 
        \begin{align*}
           && p = \big( (0,y_0), &(2,y_1), \dots, (2n-4, y_{n-2}), (2n-2,y_{n-1}), (2n-1,y_n), \\
           && &(2n-1,z_n), (2n,z_{n-1}),\dots,(4n-4,z_1),(4n-2,z_0) \big).
        \end{align*}

    Let $j_0 = \max\{j| 1 \le j \le n, y_{j-1} \le z_{j-1}+2\}$. Such a $j_0$ exists, because $y_0 = 2i+2k$, $z_0 = 4n-2i+2k-2$, thus $y_0 \le z_0 +2$.

    Define $G(p)_L$ to be the path in $\mathscr{P}^A_{i,k}$:
    \[G(p)_L = \big( (0,x_0),(1,x_1),\dots,(2n,x_{2n}) \big)\]
    such that 
    \[x_j = 
    \begin{cases}
        y_j/2, &\text{if}~0 \le j \le n-1,\\
        \lfloor (y_n +1)/2 \rfloor, &\text{if}~j=n, \\
        y_{2n-j}/2, &\text{if}~n+1 \le j \le 2n-j_0,\\
        (z_{2n-j}+2)/2, &\text{if}~2n-j_0+1 \le j \le 2n.
    \end{cases}
    \]

    Similarly, define $G(p)_R$ to be the path in $\mathscr{P}^A_{2n-i,k}$:
    \[G(p)_R = \big( (0,x_0'),(1,x_1'),\dots,(2n,x_{2n}') \big)\]
    such that 
    \[x_j' = 
    \begin{cases}
        (z_j+2)/2, &\text{if}~0 \le j \le n-1,\\
        \lfloor (z_n +3)/2 \rfloor, &\text{if}~j=n, \\
        (z_{2n-j}+2)/2, &\text{if}~n+1 \le j \le 2n-j_0,\\
        y_{2n-j}/2, &\text{if}~2n-j_0+1 \le j \le 2n.
    \end{cases}
    \]

    Denote by $G(p)$ the pair of paths $(G(p)_L,G(p)_R)$. 
\end{definition}

\begin{lemma}
    We show that this defines a map 
    \[G: \mathscr{P}^B_{i,2k} \to \mathscr{P}^A_{i,k} \times \mathscr{P}^A_{2n-i,k}.\]
\end{lemma}
\begin{proof}
    Let $j_0 = \max\{j| 1 \le j \le n, y_{j-1} \le z_{j-1}+2\}$. We claim that $y_{j_0-1} = z_{j_0-1} +2$.

    If $j_0 \neq n$, then $\lvert y_{j_0} - y_{j_0-1} \rvert = 2$ and $\lvert z_{j_0} -z_{j_0-1} \rvert =2$. Thus $y_{j_0} > z_{j_0}+2$ implies that $0 \leq y_{j_0-1} - z_{j_0-1}-2 < 4$. Notice that $\forall j \neq n$, $\lvert y_j - z_j \rvert \equiv 2 \pmod 4$, thus the difference $y_{j_0-1} - z_{j_0-1}-2$ must be $0$.

    If $j_0 = n$, then $\lvert y_{n-1} - y_n \rvert = 1+\epsilon$ and $\lvert z_{n-1} - z_n \rvert = 1+\epsilon$. Thus $y_n > z_n$ implies that $0 \leq y_{n-1} - z_{n-1}-2 < 2\epsilon$. The difference is an integer, thus must be $0$.

    Therefore, the point $(2n-j_0+1,(z_{j_0-1}+2)/2)$ in $G(p)_L$ and $G(p)_R$ can also be written as $(2n-j_0+1,y_{j_0-1}/2)$.

    Then it is easy to check that $G(p)_L$ and $G(p)_R$ are type $A_{2n-1}$ paths in $\mathscr{P}^A_{i,k}$ and $\mathscr{P}^A_{2n-i,k}$, respectively.
\end{proof}

The following proposition is a direct consequence of the definition.
\begin{proposition}
    The map $G: \mathscr{P}^B_{i,2k} \to \mathscr{P}^A_{i,k} \times \mathscr{P}^A_{2n-i,k}$ is injective.
\end{proposition}
\begin{proof}
    For two paths $p$ and $p'$ in $\mathscr{P}^B_{i,2k}$, the equality $G(p)_L = G(p')_L$ implies that $p$ and $p'$ have the same left branch, and $G(p)_R = G(p')_R$ implies that they have the same right branch. Therefore, the map $G$ is injective.
\end{proof}


The following theorem is the analogue of Theorem~\ref{thm: map between paths preserves the character}.

\begin{theorem}
    The map $G$ preserves the weight of paths in the sense that for any path $p \in \mathscr{P}^B_{i,2k}$, 
    \[\mathfrak{m}'(p) = \leftindex^L{\Pi} \circ \varpi(\mathfrak{m}'(G(p)_L) + \mathfrak{m}'(G(p)_R)).\]
\end{theorem}
\begin{proof}
    We consider the set of points with multiplicity
    \[ G(p)_L \sqcup G(p)_R.\]
    This set consists of the disjoint union of two paths of type $A_{2n-1}$, and we call it a double path in the following. 

    We remark that there may be several different ways to decompose a double path as a union of two paths of type $A_{2n-1}$. However, given a double path of type $A_{2n-1}$, if we decompose it as $p_1 \sqcup p_2$, then we have 
    that the multiplicity of $\omega_j$ ($\forall j$) in $\mathfrak{m}'(p_1) + \mathfrak{m}'(p_2)$ equals to
    \[\frac{1}{2}(a_{j-1} - 2a_j + a_{j+1} + b_{j-1} - 2b_j + b_{j+1}),\]
    as we have seen in the proof of Proposition~\ref{prop: bijection preseves half-character}, where $(j-1,a_{j-1}),(j,a_j), (j+1,a_{j+1}),(j-1,b_{j-1}),(j,b_j),(j+1,b_{j+1}) \in p_1 \sqcup p_2$ with multiplicity.

    We note that this expression is independent of the decomposition $p_1 \sqcup p_2$. Therefore, if $p_1' \sqcup p_2' = p_1 \sqcup p_2$ as set of points with multiplicity, then $\mathfrak{m}'(p_1) + \mathfrak{m}'(p_2) = \mathfrak{m}'(p_1') + \mathfrak{m}'(p_2')$.

    In our case, we can also decompose 
    \[G(p)_L \sqcup G(p)_R = p_y \sqcup p_z,\]
    where 
    \[p_y = \big( (0,\frac{y_0}{2}),(1,\frac{y_1}{2}),\dots,(n-1,\frac{y_{n-1}}{2}),(n,\lfloor \frac{y_n+1}{2} \rfloor),(n+1,\frac{y_{n-1}}{2}),\dots,(2n-1,\frac{y_{1}}{2}),(2n,\frac{y_{0}}{2}) \big), \]
    \[p_z = \big( (0,\frac{z_0+2}{2}),\dots,(n-1,\frac{z_{n-1}+2}{2}),(n,\lfloor \frac{z_n+3}{2} \rfloor),(n+1,\frac{z_{n-1}+2}{2}),\dots,(2n,\frac{z_{0}+2}{2}) \big). \]

    Therefore,
    \[\leftindex^L{\Pi} \circ \varpi(\mathfrak{m}'(G(p)_L) + \mathfrak{m}'(G(p)_R)) = \leftindex^L{\Pi} \circ \varpi(\mathfrak{m}'(p_y) + \mathfrak{m}'(p_z)).\]

    Since the Langlands dual map $\leftindex^L{\Pi}$ acts by 
    \begin{align*}
        &\omega_{\bar{i}} \mapsto \omega_{i}/2, \quad i \neq n,\\
        &\omega_{\bar{n}} \mapsto \omega_{n},
    \end{align*}
    we have 
    \[\leftindex^L{\Pi} \circ \varpi(\mathfrak{m}'(p_y) + \mathfrak{m}'(p_z))  = \mathfrak{m}'(p).\]
\end{proof}


For a $T$-tuple of NOP $\overline{p} = (p_1,\dots,p_{T}) \in \overline{\mathscr{P}}^B_{(i_t,k_t)}$ associated to the snake 
\[(i_t,k_t)_{1 \leq t \leq T} = \big( (i,2k)(i,2k+4)\cdots(i,2k+4T-4) \big),\]
we define $G(\overline{p})$ to be the pair of $T$-tuples of paths \[\big(G(p_1)_L,G(p_2)_L,\dots,G(p_{T})_L \big)\] and \[\big( G(p_1)_R,G(p_2)_R,\dots,G(p_{T})_R \big).\]

\begin{theorem}
    $G$ maps a $T$-tuple of NOP to a pair of $T$-tuples of NOP    
    \[G: \overline{\mathscr{P}}^B_{(i_t,k_t)} \to \overline{\mathscr{P}}^A_{1} \times \overline{\mathscr{P}}^A_{2}.\]
\end{theorem}
\begin{proof}
    We need to show that if $p_1 \succ p_2$, then $G(p_1)_L \succ G(p_2)_L$ and $G(p_2)_R \succ G(p_2)_R$. For points whose first coordinate is not $n$, the inequality is obvious. For points with first coordinate $n$, the same argument in the proof of Proposition~\ref{prop: level 0 bijection} also applies here word by word.
\end{proof}

\begin{corollary}
    Let $W_{T,q^k}^{(i)}$ be a generalized Kirillov-Reshetikhin module of $\Uqghatdual$. Then the usual character of the Kirillov-Reshetikhin module $L(Y_{i,q^k}\cdots Y_{i,q^{k+2T-2}})$ of $\Uqghat$ is dominated by that of $W_{T,q^k}^{(i)}$:
    \[\chi(L(Y_{i,q^k}\cdots Y_{i,q^{k+2T-2}})) \preceq \leftindex^L{\Pi} (\chi^{\sigma}(W_{T,q^k}^{(i)})). \]
\end{corollary}
\begin{proof}
    The proof is identical to that of Theorem~\ref{thm: langlands dual rep A to B}.
\end{proof}

\begin{comment}
\subsection{Snake modules}
The argument in the previous section works for snake modules as well, except that the analogue of Lemma~\ref{lemma: tensor irreducible} is not proved.

\begin{conjecture}\label{conj: dual direction}
    Let $(i_t,k_t)_{1 \leq t \leq T}$ be a snake of type $A_{2n-1}$ such that $i_t \leq n$, $\forall t$. Then the tensor product of snake modules of type $A^{(2)}_{2n-1}$ 
    \[L(\prod_{1 \le t \le T} Z_{i_t,q^{k_t}}) \otimes L(\prod_{1 \le t \le T} Z_{i_t,-q^{k_t}})\]
    is irreducible.
\end{conjecture}

If this conjecture holds, the rest argument will be the same to prove that

\begin{corollary}[of Conjecture~\ref{conj: dual direction}]
     Let $(i_t,k_t)_{1 \leq t \leq T}$ be a snake of type $A_{2n-1}$ such that $i_t \leq n$, $\forall t$. Let $L(m)$ be the irreducible $l$-highest weight module of type $A_{2n-1}^{(2)}$ with 
     \[m = \prod_{1 \le t \le T} Z_{i_t,q^{k_t}} Z_{i_t,-q^{k_t}}.\]
     Then the shortened snake module of type $B_n^{(1)}$  
    \[{}^L{V} = L(\prod_{t: i_t \neq n} Y_{i_t,q^{2k_t}}Y_{i_t,q^{2k_t}} \prod_{t: i_t = n} Y_{n,q^{2k_t-1}}Y_{n,q^{2k_t+1}})\]
    is a Langlands dual representation of $L(m)$, i.e.
    \[\chi({}^L{V}) \preceq \leftindex^L{\Pi}(\chi^{\sigma}(L(m))).\]
\end{corollary}
\end{comment}

\begin{remark}
    Following the same proof, it can be shown that for any shortened snake $(i_t,k_t)_{1 \le t \le T}$ of type $B_{n}$, 
    \[\chi(L(m)) \preceq \leftindex^L{\Pi} (\chi^{\sigma}(L({}^L{m}) \otimes L({}^L{m}'))), \]
    where $m$ is the monomial associated to the shortened snake $(i_t,k_t)_{1 \le t \le T}$ as defined in \eqref{eqn: snake weight type B}, ${}^L{m}$ is the monomial in \eqref{eqn: snake weight Lm}, and ${}^L{m}'$ is the monomial obtained from ${}^L{m}$ by replacing the spectral parameters $q^k$ with $-q^k$, $\forall k \in \ZZ$.

    However, in contrast to Kirillov-Reshetikhin modules, the tensor product of snake modules $L({}^L{m}) \otimes L({}^L{m}')$ is not irreducible in general.
\end{remark}

Finally, we remark that the usual character of a module of type $A_{2n-1}^{(2)}$ cannot be decomposed into a sum of characters of modules of type $B_n^{(1)}$.

Following \cite{frenkel2011langlandsfinite}, the conjecture is that for an irreducible finite-dimensional representation $V$ of $\Uqghatdual$ of type $A_{2n-1}^{(2)}$, the image $\leftindex^L{\Pi}(\chi^{\sigma}(V))$ can be decomposed into a sum of characters of finite-dimensional representations of $\Uqghat$. However, when $n \ge 3$, the root lattice $\leftindex^L{R}$ is not a sublattice of $\leftindex^L {P}'$, and thus $\leftindex^L{\Pi}$ is not injective on the weights of $V$. As a result, the expression $\leftindex^L{\Pi}(\chi^{\sigma}(V))$ contains fewer terms than $\chi^{\sigma}(V)$. 



