\begin{document}
\title{
On periodic families in the stable stems of height two
}

\author{Christian Carrick}
\email{c.d.carrick@uu.nl}
\author{Jack Morgan Davies}
\email{davies@math.uni-bonn.de}
% \author{Christian Carrick}\footnote{\href{mailto:c.d.carrick@uu.nl}{\texttt{c.d.carrick@uu.nl}}}\, and Jack Morgan Davies\footnote{\href{mailto:davies@math.uni-bonn.de}{\texttt{davies@math.uni-bonn.de}}}}

\date{June 26, 2025}

\maketitle

\begin{abstract}
    We discover 110 infinite periodic families in the $2$-primary stable homotopy groups of spheres. These families appear in seventeen different congruence classes of degrees modulo $192$, four of them consist of simple $4$-torsion elements, and another two of simple $8$-torsion. They all vanish in the homotopy groups of the spectrum $\TMF$ of topological modular forms, but we show that they are detected in the fixed-points of $\TMF$ with respect to an Atkin--Lehner involution.
\end{abstract}    
    %These families are hit by differentials in the ANSS of $\TMF$, but not in that of the sphere spectrum. 
