\section{Generalities on periodic families}\label{ssec:periodicfamilies}
First, let us define periodic families and discuss the relationship between periodic families generated by the same element. This follows \cite[\textsection3]{exoticwithcokerJ}.

\begin{mydef}\label{def:periodicfamilies}
    Fix a prime $p$ and a nonnegative integer $h\geq 0$.
\begin{itemize}
    \item An element $x \in \pi_s \Sph$ is \emph{$v_h$-periodic} if there exists a type $h$ finite spectrum $M$, a map $\partial:M\to\Sph^d$ for some integer $d$, and a lift $\tilde{x}$ along the map
    \[\pi_{s+d}M\to\pi_s\Sph\]
    with the property that $\tilde{x}$ has nonzero image in $v_h^{-1}\pi_s M$.
    In this case, the complex $M$ admits $v_h^k$-self map $v$ on $F$ such that $v^t(\widetilde{x}) \neq 0$ for all $t\geq 1$. We say that $x$ is \emph{$v_h^k$-periodic}, emphasising the $k$.
    \item If $x$ is $v_h^k$-periodic, then fixing $M\to \Sph^d$, the choice of $v_h^k$-self map $v$, and a choice of lift $\widetilde{x}$, we write $v^t(x) \in \pi_{s+t|v|}\Sph$ for the projection $\partial(v^t(\widetilde{x}))$. We call the sequence $(v^t({x}))_{t\geq 0}$ the \emph{$v_h^k$-periodic family generated by $x$}.
    \item More generally, given a sequence of elements $\gX=(x_0, x_1, x_2, \ldots) \subseteq \pi_\ast X$, we say that $\gX$ is a \emph{$v_h^k$-periodic family} if it is a $v_h^k$-periodic family generated by $x_0$ in the sense above. If each $x_i\neq 0$, then we say this family is \emph{nonzero}.
\end{itemize}
\end{mydef}

Hidden in the notation $(v^t(x))_{t\geq 0}$ are the choices of type $2$ complex, map $\partial$, self map $v$, and lift $\tilde{x}$. For example, we have a choice of lifting a class such as $\kappa\kappabar$ using lifts of either $\kappa$ or of $\kappabar$, as found in \cite[Lm.7.17]{hurewicztmf}, and there is no immediate reason for the associated families to agree. The periodicity theorem and consequent asymptotic uniqueness of $v_h$-self maps, see \cite[Th.9]{hopkinssmith} or \cite[Th.1.5.4]{orangebook}, shows that two $v_h^k$-periodic families with the same generator have infinite intersection.

\begin{theorem}\label{thm:infiniteagreement}
    Let $\gX=(x_1,x_2,\ldots) \subseteq \pi_\ast\Sph$ be a $v_h^s$-periodic family and $\gY=(y_1,y_2,\ldots)\subseteq \pi_\ast\Sph$ be a $v_h^t$-periodic family. If $x_1=y_1$, then there are integers $i,j$ such that for all integers $n\geq 1$ we have $x_{in} = y_{jn}$ in $\pi_\ast\Sph$.
\end{theorem}

\begin{proof}
    By definition, we have maps $\partial:M\to S^d$ and $\partial:M'\to S^{d'}$ for type $h$ complexes $M$ and $M'$, a $v_h^s$-self map $v$ of $M$ and a $v_h^t$-self map $w$ of $M'$, and classes $\tilde{x_1}\in\pi_*M$ and $\tilde{y_1}\in\pi_*M'$ with the property that $\partial(\tilde{x_1})=x_1$ and $\partial'(\tilde{y_1})=y_1$. Also by definition, $x_i=\partial(v^i\tilde{x_1})$ and $y_i=\partial'(w^i\tilde{y_1})$. Suppressing shifts, we may form the commutative diagram
    \[
    \begin{tikzcd}
        M\oplus M'\arrow[d,"\pi_1"]\arrow[r,"\pi_2"]&M\arrow[d,"\partial"]\\
        M'\arrow[r,"\partial'"]&\Sph
    \end{tikzcd}
    \]
    The type $h$ complex $M\oplus M'$ admits the $v_h$-self maps $v\oplus\id$ and $\id\oplus w$, and the uniqueness of self maps, see \cite[Lm.6.1.3]{orangebook}, guarantees that there exists positive integers $i$ and $j$ such that $(v\oplus\id)^i=(\id\oplus w)^j$ as endomorphisms of $M\oplus M'$. Therefore, for all $n\ge0$
    \begin{align*}
        x_{in}&=\partial(v^{in}x_1)\\
        &=\partial(\pi_2((v\oplus\id)^{in}(x_1,y_1))\\
        &=\partial'(\pi_1((v\oplus\id)^{in}(x_1,y_1))\\
        &=\partial'(\pi_1((\id\oplus w)^{jn}(x_1,y_1))\\
        &=\partial'(w^{jn}y_1)\\
        &=y_{jn}\qedhere
    \end{align*}
\end{proof}

\begin{cor}\label{cortoinfiniteagreement}
    For any two $v_2^{32}$-periodic families $\gX$ and $\gY$ of \Cref{tab:classes} whose generators are equal the intersection $\gX \cap \gY$ contains a $v_2^{32s}$-periodic family for some $s\geq 1$.
\end{cor}

