\subsubsection{Synthetic height 2 image-of-$J$ spectra}
In \cite[\textsection3]{adamsontmf}, we considered the fixed points of $\TMF$ with respect to the Adams operations constructed by either \cite[Df.2.1]{heckeontmf} or \cite[Df.6.16]{luriestheorem}. The main character in this article is the following variant.

%Recall that $\TMF[\tfrac{1}{k}]$ has $\E_\infty$-automorphisms $\psi^k$ called \emph{Adams operations}; see \cite[Df.2.1]{heckeontmf} or \cite[Df.6.16]{luriestheorem}. Following \cite[\textsection3]{adamsontmf}, we define \emph{height $2$ image-of-$J$ spectra}; to avoid burdensome notation, we only consider a specific case here.

%\begin{mydef}
%Implicitly localise at the prime $p=2$. Let $\J$ be the $\E_\infty$-ring given by the limit of the diagram of $\E_\infty$-rings
%    \[\J^\bullet = \begin{tikzcd}
%        {\TMF}\ar[r, shift left = 1, "{\psi^3}"]\ar[r, shift right = 1, "{\id}", swap]    &   {\TMF.}
%    \end{tikzcd}\]
%\end{mydef}

%The connective analogue of $\J$ was studied at the prime $3$ in \cite{heighttwojat3}. At the prime $2$, we will need to use another variant.
By \cite[Df.2.5]{heckeontmf}, there is a \emph{stable Atkin--Lehner involution} (also called a \emph{stable Fricke involution} there), so a map of $\E_\infty$-rings $w_N = w\colon \TMF_0(N) \to \TMF_0(N)$ inducing the classical Atkin--Lehner involution $w_N$ on the descent spectral sequence for $\TMF_0(N)$.

\begin{mydef}\label{def:jspectra}
    Let $\J_0(N)$ be the $\E_\infty$-ring given by the limit of the diagram of $\E_\infty$-rings
    \[\J_0^\bullet(N) = \begin{tikzcd}
        {\TMF}\ar[r, shift left = 1, "{q}"]\ar[r, shift right = 1, "{p}", swap]    &   {\TMF_0(N),}
    \end{tikzcd}\]
    where $p\colon \TMF \to \TMF_0(N)$ is the canonical $\TMF$-algebra map, and $q = wp$. Equivalently, the $\E_0$-ring $\J_0(N)$ is the fibre of $q-p\colon \TMF \to \TMF_0(N)$. 
\end{mydef}

The $\E_\infty$-rings $\J_0(N)$ have previously been used in detection arguments, such as in \cite[Pr.12.1]{exoticwithcokerJ} to show that $\kappabar^6\neq0$. This fact will be reproven in \Cref{hurewiczforjzerothree}.

\begin{mydef}\label{def:syntheticjspectra}
Let $\J_0(N)_\BP$ be the synthetic $\E_\infty$-ring given by the limit of the diagram of synthetic $\E_\infty$-rings
    \[\J_0^\bullet(N)_\BP = \begin{tikzcd}
        {\TMF_\BP}\ar[r, shift left = 1, "{\nu q}"]\ar[r, shift right = 1, "{\nu p}", swap]    &   {\TMF_0(N)_\BP}
    \end{tikzcd},\]
    or equivalently as the synthetic $\E_0$-ring $\fib(\nu q-\nu p\colon \TMF_\BP \to \TMF_0(N)_\BP)$. 
\end{mydef}

\begin{prop}
    The synthetic $\E_\infty$-ring $\J_0(N)_\BP$ is a $\tau$-complete lift of $\J_0(N)$.
\end{prop}

\begin{proof}
    By \Cref{pr:liftsfortmf} and the fact that $\tau$-completeness is closed under limits shows $\J_0(N)_\BP$ is $\tau$-complete. It is clear that $\J_0(N)_\BP$ is a lift of $\J_0(N)$ as the synthetic analogue functor is a section of the $\tau$-inversion functor, and $\tau$-inversion is exact.
\end{proof}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsubsection{Simple computations in bigraded homotopy groups}\label{ssec:pqcomputations}
One can compute the bigraded homotopy groups of $\J_0(3)_\BP$ in any particular degree from the long exact sequence induced by its defining fibre sequence, however, these homotopy groups are very busy. As we are more interested in $\J_0(3)_\BP$ as a detection spectrum, we will only compute enough of its homotopy groups to apply \Cref{cor:synthetichurewiczimpractice}.

By identifying $\pi_{\ast,\ast}\TMF_\BP/\tau$ with the $E_2$-page of the DSS for $\TMF$, see \Cref{dssvsanss}, write $\Delta\in \pi_{24,0} \TMF_\BP/\tau$ for the usual discriminant modular form.

\begin{prop}\label{pr:injectivityofpandq}
    For $0\leq i\leq 2$ and $k\geq 1$, the element $\eta^i \Delta^k \in \pi_{i+24k,i} \TMF_\BP/\tau^4$ has nonzero image under the map $q-p\colon \colon \TMF_\BP/\tau^4 \to \TMF_0(N)_\BP/\tau^4$.
\end{prop}

To apply \Cref{cor:synthetichurewiczimpractice} in this situation, will be need to delete various $d_5$-differentials, hence why we demand on working modulo $\tau^4$ in this proposition.

\begin{proof}

    First, we refer to \cite[Pr.8.1]{levelonethree}, which states that as a map between $E_2$-pages we have
    \[(q-p)(\Delta^{2^r(2s+1)}) = a_1^{3\cdot 2^{r+1}} a_3^{2^{r+1}(4s+1)} + O(a_1^{3\cdot 2^{r+1}+1})\]
    modulo $2$. These elements are all nonzero on the $E_2$-page of $\sigma(\TMF_0(3)_\BP)$. As the reduction maps $\TMF_\BP/\tau^4 \to \TMF_\BP/\tau$ and $\TMF_0(3)_\BP/\tau^4\to \TMF_0(3)_\BP/\tau$ are both isomorphisms in degrees $\pi_{24k,0}$, this proves our statement for $i=0$. For $i\neq0$, we use the fact that $\eta^i$ comes from $\nu\Sph$ and $q-p$ is $\nu\Sph$-linear, which leads to $(q-p)(\eta^i \Delta^k) = \eta^i (q-p)(\Delta^k)$. This expression is nonzero by inspection of $\pi_{\ast,\ast}\TMF_0(3)_\BP/\tau^4$.
\end{proof}

We will often use the following simple facts about $\J_0(N)_\BP$.

\begin{lemma}\label{lm:checkboard}
    The $\BP$-synthetic spectrum $\J_0(N)_\BP$ is \emph{even}, so in particular, $\sigma(\J_0(N)_\BP)$ is concentrated in even total degrees and can only support odd differentials.
\end{lemma}

In other words, $\sigma(\J_0(N)_\BP)$ obeys a ``checkerboard'' pattern.

\begin{proof}
    This is true for $\TMF_\BP$ and $\TMF_0(N)_\BP$ and this condition is closed under fibres.
\end{proof}

\begin{lemma}\label{lm:nothingbelowzero}
    For $f\leq -1$, the groups $\pi_{\ast,f}\J_0(N)_\BP/\tau$ all vanish.
\end{lemma}

\begin{proof}
    This follows from this fact for $\TMF_\BP$ and $\TMF_0(N)_\BP$, which is clear as their signatures are classical ANSSs. 
\end{proof}

\begin{lemma}\label{lm:filtrationzero}
    For all $n\neq0$, the groups $\pi_{n,0}\J_0(N)_\BP/\tau$ vanish. In other words, the zero line of $\sigma(\J_0(N)_\BP)$ is zero away from the zero stem.
\end{lemma}

\begin{proof}
    From the long exact sequence on mod $\tau$-bigraded homotopy groups defining $\J_0(N)_\BP$, the zero line of $\sigma(\J_0(N)_\BP)$ comes from classes in the zero line of $\sigma(\TMF_\BP)$ which lie in the kernel of $q-p$. One of the key features of the Atkin--Lehner involution on $\TMF_0(N)$ is that $w^2\simeq \psi^N$; see \cite[Th.C]{heckeontmf}. In particular, it suffices to compute the kernel of the map
    \[(w+1)(q-p) \simeq \psi^Np - q + q - p \simeq \psi^Np-p \simeq p\psi^N - p \simeq p(\psi^N-1)\]
    on the zero line of $E_2$-pages; the second-to-last homotopy is the naturality of Adams operations from \cite[(2.2)]{heckeontmf}. The map $p$ is injective on $0$-lines between $\sigma(\TMF_\BP)$ and $\sigma(\TMF_0(N)_\BP)$, as a modular form of level $\Ga_0(1)$ is a modular form of level $\Ga_0(N)$. It suffices to show then that $\psi^N-1$ has trivial kernel on the zero line of $\sigma(\TMF_\BP)$ away from the zero stem. For each $x\in \pi_{s,0}\TMF_\BP/\tau$, we have $\psi^N(x)=N^{\tfrac{s}{2}}x$ by \cite[Cor.2.12]{heckeontmf}, and that all of these abelian groups $\pi_{s,0}\TMF_\BP/\tau$ are torsion-free. In particular, such an $x$ is in the kernel of $\psi^N-1$ if and only if it lies in the zero stem $s=0$. This finishes the proof.
\end{proof}

