\section{Construction of integral representations}\label{section:construction_integral_representation}
In this section we will construct certain integral local systems on $\Sigma_{g,n}$ whose mapping class group orbit is Zariski-dense in the appropriate relative character variety---essentially, integral $\mathcal{P}$-good points in the terminology of \autoref{defn:p-good}. We will do so by gluing local systems on subsurfaces. We first
 introduce a class of integral matrices $\mathcal{M}_K$ such that local systems with peripheral monodromy in $\mathcal{M}_K$ are especially well-suited for such gluing.

\begin{definition} Let $K$ be a number field with ring of integers $\mc{O}_K$. 
	We define $\mc M_{K} \subset \SL_2(\mc O_K)$ to be the set of matrices
	\begin{equation*}
		\mc M_{K} = \left\{ \begin{pmatrix}
			a & u^{-1}(ad-1) \\
			u & d \\
		\end{pmatrix}   \, \Big | \, u \in \mc O_K^{\times}, \, a,d \in \mc O_K  \right\}.
	\end{equation*}
\end{definition}
\begin{remark}
	$\mc M_K$ is closed under inversion.
\end{remark}

\subsection{Surfaces of genus $0$}

\begin{lemma}\label{lemma:existence-integral-matrices-pant}
	Let $k_1, k_2 \in \mc O_K$ and let $A \in \mc M_K$. Then there exists a quadratic extension $L$ of $K$ and matrices $M_1, M_2 \in \SL_2(\mc O_L)$ such that $\tr M_i = k_i$ and $M_2=AM_1$. 
\end{lemma}
\begin{proof}
	Set 
	\begin{equation*}
		A=\begin{pmatrix}
			a & b \\
			c & d \\
		\end{pmatrix},
		M_1=\begin{pmatrix}
			x & y \\
			z & w \\
		\end{pmatrix}
	\end{equation*}
	so that our problem is equivalent to solving the following system
	\begin{equation*}
		\begin{cases}
			ax+bz+cy+dw=k_2\\
			x+w=k_1\\
			xw-yz=1\\
		\end{cases}
	\end{equation*}
	for $x,y,z,w \in \overline{\mb Z}$. This is equivalent to solving
	\begin{equation*}
		\begin{cases}
			(a-d)x+bz+cy=k_2-dk_1\\
			x^2-k_1x+yz+1=0\\
		\end{cases}
	\end{equation*}
	with $x,y,z \in \overline{\mb Z}$. Since $A \in \mc M_K$, we have $c \in \mc O_K^{\times}$, so the first equation gives
	\begin{equation*}
		y=c^{-1}(k_2-dk_1)-c^{-1}bz-c^{-1}(a-d)x.
	\end{equation*} 
	Substituting this expression for $y$ into the second equation, we get a monic quadratic equation in $x$ with coefficients in $\mc O_K[z]$. In particular, for any $z \in \mc O_K$, there exists a quadratic extension $L$ of $K$ and $x \in \mc O_L$ solving the equation. This concludes the proof.
\end{proof}

\begin{corollary}\label{corollary:existence-integral-representation-pant}
	Let $k_1, k_2 \in \mc O_K$ and let $A \in \mc M_K$ such that
	\begin{equation}\label{equation:numerical-condition-irreducibility}
		(\tr A)^2 + k_1^2+k_2^2-k_1k_2\tr A-2 \neq 2.
	\end{equation}
	Then there exists a quadratic extension $L$ of $K$ and a representation $\rho \colon \pi_1(\Sigma_{0,3}) \to \SL_2(\mc O_L)$ with monodromy $A$ along one puncture and trace $k_1$ and $k_2$ along the two other punctures, such that $\rho\otimes L$ is absolutely irreducible.
\end{corollary}
\begin{proof}
	The existence of a representation with the desired local monodromy and traces follows immediately from \autoref{lemma:existence-integral-matrices-pant}; irreducibility follows from \cite[Lemma $3.3$]{whang:ant}.
\end{proof}

\begin{lemma}\label{lemma:induction-step}
	Assume $\mc O_K^{\times}$ is infinite.
	Fix $k\in \mc O_K$ and $A \in \mc M_K$. Then there exists infinitely many pairs of matrices $(B,M) \in \mc M_K \times \SL_2(\mc O_K)$ such that $ABM=I$, $\tr M = k$, $\tr B \notin E$ and the traces of $A,B$ and $M$ satisfy \eqref{equation:numerical-condition-irreducibility}. Moreover, there are infinitely many values of $\tr B$ as $B$ varies among the above solutions.
\end{lemma}
\begin{proof}
	Since $M=(AB)^{-1}$, we need to find $B \in \mc M_K$ such that $\tr AB=k$. Assume that $A= \begin{pmatrix} a & u^{-1}(ad-1) \\ u & d  \end{pmatrix}$. Pick any $v \in \mc O_K^{\times}$ and let $B = \begin{pmatrix} x & v^{-1}(xw-1) \\ v & w  \end{pmatrix}$ with
	 \begin{equation*}
	 	\begin{cases}
	 		x=s^{-1}k-u^{-1}vd+s^{-1}(u^{-1}v+uv^{-1})\\
	 		w=u^{-1}v(s-a)\\
	 	\end{cases}
	 \end{equation*}
	for a suitable $s \in \mc O_K^{\times}$ that we will choose so that the required conditions on $\tr B$ will be satisfied. One can verify that the above choice of $B$ gives $\tr AB=k$. Using the above expressions for $x$ and $w$ one sees immediately that both $\tr B=x+w$ and $(\tr A)^2 + (\tr B)^2+k^2-k\tr A\tr B-4$ are non-constant rational functions in $K(s)$. In particular, for all but finitely many $s \in \mc O_K^{\times}$, the condition of \eqref{equation:numerical-condition-irreducibility} is satisfied and we have $\tr B \notin E$, proving the claim.
\end{proof}

\begin{proposition}\label{proposition:existence-representation-punctured-sphere}
	Let $K$ be a number field, $k=(k_1,\dots,k_{n}) \in (\mc O_K)^n$, $M \in \mc M_K$, $n \ge 3 $. Assume $\mc O_K^{\times}$ is infinite. There exists a pants decomposition $\mathcal{P}$ of $\Sigma=\Sigma_{0,n+1}$, a quadratic extension $L$ of $K$ and a $\mc P$-good integral representation $\rho \colon \pi_1(\Sigma) \to \SL_2(\mc O_L)$ such that
	\begin{itemize}
		\item the trace of the monodromy at the $i$-th puncture is $k_i$ for $i=1, \dots, n$,
		\item the monodromy at the $(n+1)$-st puncture is $M$.
	\end{itemize}
\end{proposition}
\begin{proof}
	Pick a simple loop $\gamma$ in $\Sigma$ that separates the $n+1$-st and the $n$-th puncture from the rest. This gives a decomposition $\Sigma_{0,n+1}=\Sigma_1 \cup \Sigma_{2}$ where $\Sigma_1$ is a pair of pants. Using \autoref{lemma:induction-step} we obtain an irreducible  $\SL_2(\mc O_K)$-representation on $\Sigma_1$ with monodromy of trace $k_n$ along the $n$-th puncture, monodromy $M$ along the $n+1$-th puncture and monodromy $M' \in \mc M_K$ along $\gamma$, with $\tr M' \notin E$. Moreover, when $n=3$, we choose $M'$ so that $\tr M'$, $k_1$ and $k_{2}$ satisfy the condition of \eqref{equation:numerical-condition-irreducibility}.


	We will argue by induction on $n$.

	If $n=3$, $\Sigma_2$ is a pair of pants, and using \autoref{corollary:existence-integral-representation-pant} we find a quadratic extension $L$ of $K$ and an irreducible $\mc O_L$-representation on $\Sigma_2$ with monodromy $M'$ along the puncture corresponding to $\gamma$. We may then glue along $\gamma$ the two representations we constructed on $\Sigma_1$ and $\Sigma_2$, thereby obtaining an $\mc O_L$ representation on $\Sigma_{0,4}$ satisfying the sought conditions.

	If $n \ge 4$, by the inductive hypothesis there exists a quadratic extension $L$ of $K$ and an $\mc O_L$-representation on $\Sigma_2$ satisfying the conditions of \autoref{proposition:existence-representation-punctured-sphere} with monodromy $M'$ along the puncture corresponding to $\gamma$. We may then glue along $\gamma$ the representations on $\Sigma_1$ and $\Sigma_2$, thereby obtaining a representation on $\Sigma_{0,n+1}$ satisfying the sought conditions.
\end{proof}

\subsection{Surfaces of positive genus}

\begin{lemma}\label{lemma:existence-representation-two-holed-torus}
	Assume $\mc O_K^{\times}$ is infinite. Let $M \in \mc M_K$. Then there exists a pants decomposition $\mc P$ of $\Sigma_{1,2}$ and a $\mc P$-good representation $\rho \colon \pi_1(\Sigma_{1,2}) \to \SL_2(\mc O_K)$ such that the monodromies along the first and second puncture are $M$ and $M^{-1}$, respectively.
\end{lemma}
\begin{proof}
