To construct integral representations on a once-punctured torus, we introduce a subset of $\mc M_K$.
\begin{definition}
Let $\mc N_{K} \subset \SL_2(\mc O_K)$ be the set of matrices
\begin{equation*}
	\mc N_{K} = \left\{ \left[ \begin{pmatrix}
		a & u^{-1}(a-1) \\
		u & 1 \\
	\end{pmatrix} , \begin{pmatrix}
	v & 0 \\
	0 & v^{-1} \\
	\end{pmatrix} \right]   \, \Big | \, u,v,v-v^{-1} \in \mc O_K^{\times}, \, v \notin \mu_{\infty}, \, a \in \mc O_K  \right\}
\end{equation*}
\end{definition}
\begin{remark}
	$\mc N_K$ is closed under inversion.
\end{remark}
\begin{remark}\label{remark:special-unit}
	As long as $\mc O_K$ contains a unit $v \in \mc O_K^{\times}\setminus \mu_{\infty}$ such that $v-v^{-1}$ is also a unit, then $\mc N_K$ is infinite. For instance, it is sufficient that $ \sqrt{5} \in K$, so that $\frac{1+\sqrt{5}}{2} \in \mc O_K^{\times}$.
\end{remark}
\begin{remark}\label{remark:unit-scaling-nk}
	For $\lambda \in \mc O_K^{\times}$ we have
	\begin{equation*}
		\left[ \begin{pmatrix}
			a\lambda & u^{-1}(a-1)\lambda^{-1} \\
			u\lambda & \lambda^{-1} \\
		\end{pmatrix} , \begin{pmatrix}
			v & 0 \\
			0 & v^{-1} \\
		\end{pmatrix} \right]= \left[ \begin{pmatrix}
		a & u^{-1}(a-1) \\
		u & 1 \\
		\end{pmatrix} , \begin{pmatrix}
		v & 0 \\
		0 & v^{-1} \\
		\end{pmatrix} \right]
	\end{equation*}
	In particular, if $\mc O_K^{\times}$ is infinite, for any $M \in \mc N_K$ the set $\left\{ \tr A \, \Big | \, \left[A, \begin{pmatrix} 
		i & 0 \\
		0 & -i \\
	\end{pmatrix}\right]=M \right\}$ is infinite.
\end{remark}

\begin{remark}\label{remark:trace-of-commutator-matrix}
The matrices of $\mc N_K$ are of the form
\begin{equation*}
	M=\begin{pmatrix}
		a(1-v^{-2})+ v^{-2} & u^{-1}a(a-1)(1-v^2)\\[5pt]
		u(1-v^{-2}) & a(1-v^2)+v^2
	\end{pmatrix}
\end{equation*}
so that $\mc N_K \subset \mc M_K$.
We also have
\begin{equation}\label{equation:trace-formula}
	\tr M= -a(v-v^{-1})^2+v^2+v^{-2}
\end{equation} 
so that, since $-(v-v^{-1})^2$ is a unit, for any $k \in \mc O_K$ there exists a matrix $M \in \mc N_K$ with $\tr M=k$.
\end{remark}

The following result is a consequence of the definition of $\mc N_K$:
\begin{lemma}\label{lemma:existence-integral-representation-torus}
	For any $C \in \mc N_K$ there exists a pants decomposition $\mc P$ of $\Sigma_{1,1}$ and a $\mc P$-good representation $\rho \colon \pi_1(\Sigma_{1,1}) \to \SL_2(\mc O_K)$ with monodromy $C$ along the puncture.
\end{lemma}
\begin{proof}
	The fundamental group of $\Sigma_{1,1}$ is generated by paths $\alpha, \beta, \gamma$ with the condition $[\alpha, \beta]\gamma=1$, where $\gamma$ is the path going around the puncture. By \autoref{remark:unit-scaling-nk}, there exists $A,B \in\SL_2(\mc O_K)$ such that $[A,B]=C$, $\tr A \notin E$ and $(\tr A)^2 \neq 2+\tr C$. Let $\mc P = \{ \beta \}$ and consider the representation $\rho \colon \pi_1(\Sigma_{1,1}) \to \SL_2(\mc O_K)$ defined by $\rho(\alpha)=B$, $\rho(\beta)=A$ and $\rho(\gamma)=C$. We claim that $\rho$ is $\mc P$-good. If $\tr C = 2$, we are done by \autoref{definition:perfect-fiber} (since we are in the $(g,n,k)=(1,1,2)$ case) and the fact that $\tr A \notin E$. If $\tr C \neq 2$, we should check that \eqref{equation:numerical-condition-irreducibility} is satisfied by $\tr A, \tr A, \tr C$. Indeed \eqref{equation:numerical-condition-irreducibility} can be rewritten as
	\begin{equation*}
		((\tr A)^2 - (2+\tr C))(2-\tr C) \neq 0,
	\end{equation*}
	which is true by the hypotheses on $\tr A$ and $\tr C$.
\end{proof}

We may now construct integral $\mc P$-good representations on surfaces with one puncture:
\begin{proposition}\label{proposition:existence-representation-positive-genus}
	Let $K$ be a number field, $g \ge 1$ and $M \in \mc N_K$ such that $\tr M \notin E$. Assume that $\mc O_K^{\times}$ is infinite. There exists a pants decomposition $\mathcal{P}$ of $\Sigma=\Sigma_{g,1}$ and a $\mc P$-good representation $\rho \colon \pi_1(\Sigma) \to \SL_2(\mc O_K)$ with monodromy $M$ at the puncture.
\end{proposition}
\begin{proof}
	We proceed by induction on $g$. When $g=1$, this is \autoref{lemma:existence-integral-representation-torus}. If $g>1$, consider a separating path $\gamma$ cutting $\Sigma$ into two surfaces $\Sigma_1$ and $\Sigma_2$, where $\Sigma_1$ is a surface of type $(1,2)$ containing the puncture of $\Sigma$ (and with the other puncture along $\gamma$), and $\Sigma_2$ is of type $(g-1,1)$ with a puncture along $\gamma$. By \autoref{lemma:existence-representation-two-holed-torus} there exists an integral representation of $\pi_1(\Sigma_1)$ with monodromy $M$ along the puncture of $\Sigma$ and monodromy $M^{-1}$ along $\gamma$, and satisfying the conditions of \autoref{proposition:existence-representation-positive-genus}. Since $M^{-1} \in \mc N_K$, by the induction hypothesis there exists an integral representation on $\Sigma_2$ satisfying the conditions of \autoref{proposition:existence-representation-positive-genus}, and with monodromy $M^{-1}$ along $\gamma$. We may then glue the two representation and obtain the sought integral representation on $\Sigma$.
\end{proof}

\autoref{proposition:existence-representation-positive-genus} does not cover the case where the trace of the monodromy at the puncture belongs to $E$. In order to treat this case, we need the following:
\begin{lemma}\label{lemma:induction-step-family-N}
	Let $k\in \mc O_K \cap E$ and let $A \in \mc M_K$ with $\tr A \notin E$. Assume that there exists $v \in \mc O_K^{\times} \setminus \mu_{\infty}$ for which $v-v^{-1} \in \mc O_K^{\times}$. Then there exists a quadratic extension $L$ of $K$ and matrices $M \in \SL_2(\mc O_L)$ and $B \in \mc N_L$ such that $ABM=I$, $\tr M = k$, $\tr B \notin E$ and the traces of $A,B$ and $M$ satisfy the condition of \eqref{equation:numerical-condition-irreducibility}.
\end{lemma}
\begin{proof}
	We argue as in \autoref{lemma:induction-step}. Let $A= \begin{pmatrix} x & y \\ z & w  \end{pmatrix} \in \mc M_K$, so that $z \in \mc O_K^{\times}$. We will choose $L$ and $B \in \mc N_L$ of the form
	\begin{equation*}
		B=\begin{pmatrix}
			a(1-v^{-2})+ v^{-2} & u^{-1}a(a-1)(1-v^2)\\[5pt]
			u(1-v^{-2}) & a(1-v^2)+v^2
		\end{pmatrix}.
	\end{equation*}
	Our aim is to pick $a \in \mc O_L$ and $u \in \mc O_L^{\times}$ so that $\tr AB=k$, where $L$ is a suitable quadratic extension of $K$. The equation $\tr AB=k$ is
	\begin{equation}\label{equation:trace-of-product}
		x(a(1-v^{-2})+ v^{-2})+yu(1-v^{-2})+zu^{-1}a(a-1)(1-v^2)+w(a(1-v^2)+v^2)=k
	\end{equation}
	After dividing by $z(1-v^2)u^{-1}$ (which is a unit), this becomes a monic quadratic equation in $a$ with $\mc O_K$-integral coefficients. Therefore, for any $u \in \mc O_K^{\times}$, there exists a quadratic extension $L$ of $K$ and $a \in \mc O_L$ that solves \eqref{equation:trace-of-product}. Moreover, we claim that the coefficients of this quadratic equation are non-constant polynomials in $u$. Indeed if this was not the case, one would have that
	\begin{equation*}
		\begin{cases}
			x+w=xv^{-2}+wv^2\\
			x+w=k\\
		\end{cases}
	\end{equation*}
	which would imply that $\tr A = k \in E$, contradicting the hypotheses. In particular, as $u$ varies in $\mc O_K^{\times}$, the $a$'s solving \eqref{equation:trace-of-product} vary in an infinite set.

	In order to complete the proof, we just need to show that by choosing a suitable $u \in \mc O_K^{\times}$ we can ensure that $\tr B \notin E$ and that the traces of $A,B$ and $M$ satisfy \eqref{equation:numerical-condition-irreducibility}.

	We claim that only for finitely many such $u$'s we have $\tr B \in E$. Indeed, if $a$ solves \eqref{equation:trace-of-product}, then $[\mb Q(a) : \mb Q] \le 2[K : \mb Q] $ and, if $\tr B \in E$, then from \eqref{equation:trace-formula} one deduces that the Weil height $h(a)$ is bounded, so Northcott's theorem implies that there are only finitely many choices of $u$ with $\tr B\in E$.

	Similarly, substituting the traces of $A, B$ and $M$ in \eqref{equation:numerical-condition-irreducibility}, one finds a quadratic equation in $a$ with constant coefficients, so for all but (at most) two values of $a$, the condition of \eqref{equation:numerical-condition-irreducibility} is satisfied.

	The statement follows by picking any $u \in \mc O_K^{\times}$ such that the corresponding $a$ does not belong to the finite set where the two conditions are not satisfied.
\end{proof}
\begin{proposition}\label{proposition:doubly-punctured-torus}
	Fix $k \in \mc O_K \cap E$ and $M \in \mc M_K$ with $\tr M \notin E$. Assume that there exists $v \in \mc O_K^{\times} \setminus \mu_{\infty}$ for which $v-v^{-1} \in \mc O_K^{\times}$. Then there exists a quadratic extension $L$ of $K$, a pants decomposition $\mc P$ of $\Sigma_{1,2}$ and a $\mc P$-good representation $\rho \colon \pi_1(\Sigma_{1,2}) \to \SL_2(\mc O_L)$ such that the monodromy along one puncture is $M$ and the monodromy along the other puncture has trace $k$.
\end{proposition}
\begin{proof}
	Take a separating path $\gamma$ around the two punctures of $\Sigma_{1,2}$, so that $\gamma$ cuts $\Sigma_{1,2}$ into surfaces $\Sigma_1$ and $\Sigma_2$ of type $(0,3)$ and $(1,1)$, respectively, so that the puncture of $\Sigma_2$ corresponds to $\gamma$.

	By \autoref{lemma:induction-step-family-N}, there exists a quadratic extension $L$ of $K$ and an irreducible  $\SL_2(\mc O_L)$-local system $\rho_1$ on $\Sigma_1$, such that the monodromy of $\rho_1$ along the puncture corresponding to $\gamma$ is a matrix $N \in \mc N_L$ with $\tr N \notin E$, and at another puncture the monodromy is $M$, and at the last puncture it has trace $k$.

	By \autoref{lemma:existence-integral-representation-torus}, there exists a pants decomposition $\mc P'$ of $\Sigma_2$ and a $\mc P'$-good  $\SL_2(\mc O_L)$-local system $\rho_2$ on $\Sigma_2$ with monodromy $N$ along the puncture.

	Let $\mc P \coloneqq \{\gamma \} \cup \mc P'$ be a pants decomposition of $\Sigma_{1,2}$. Then,
	gluing $\rho_1$ and $\rho_2$, we obtain a $\mc P$-good  $\SL_2(\mc O_L)$-representation on $\Sigma_{1,2}$ satisfying the sought conditions. 
\end{proof}



\section{Proof of potential density}\label{sec:potential-density-sl2}
In this section we prove potential density of integral points on relative $\SL_2$-character varieties of surface groups.

We first construct integral $\mathcal{P}$-good representations in general:
\begin{proposition}\label{proposition:existence-good-representation}
	Let $\Sigma$ be a surface of type $(g,n)$ with $3g-3+n>0$, $K$ be number field and $k=(k_1,\dots,k_n) \in (\mc O_K)^n$. Assume that there exists $v \in \mc O_K^{\times} \setminus \mu_{\infty}$ for which $v-v^{-1} \in \mc O_K^{\times}$.
	Then there exists a quadratic extension $L$ of $K$, a pants decomposition $\mathcal{P}$ and a $\mc P$-good representation $\rho \colon \pi_1(\Sigma) \to \SL_2(\mc O_L)$ such that $[\rho] \in X_{g, n, k}(\mc O_L)$.
\end{proposition}
\begin{proof}
	Recall that the hypothesis on $K$ implies that $\mc N_K$ and $\mc O_K^{\times}$ are infinite. We will distinguish various cases depending on the values of $n$ and $g$.

	If $n=0$, then $g \ge 2$. Take a separating path $\gamma$ cutting $\Sigma$ into two surfaces $\Sigma_1$ and $\Sigma_2$, where $\Sigma_1$ is a surface of type $(1,1)$ with a puncture along $\gamma$ and $\Sigma_2$ is of type $(g-1,1)$ with a puncture along $\gamma$. Pick $M \in \mc N_K$ with $\tr M \notin E$ (this always exists by \autoref{remark:trace-of-commutator-matrix}); by \autoref{proposition:existence-representation-positive-genus} there exist good integral representations on $\Sigma_1$ and $\Sigma_2$ with monodromy $M$ along $\gamma$, so that the claim follows by gluing.

	If $n=1$ and $g=1$, by \autoref{remark:trace-of-commutator-matrix} there exists $M \in \mc N_K$ such that $\tr M=k$, and the claim follows from \autoref{lemma:existence-integral-representation-torus}. If $n=1$, $g>1$ and $k \notin E$, then the same reasoning works by using \autoref{proposition:existence-representation-positive-genus}. Instead, if $k \in E$, we pick $M \in \mc N$ with $\tr M \notin E$ and we consider a separating path $\gamma$ cutting $\Sigma$ into two surfaces $\Sigma_1$ and $\Sigma_2$, where $\Sigma_1$ is a surface of type $(1,2)$ containing the puncture of $\Sigma$ (and with the other puncture along $\gamma$), and $\Sigma_2$ is of type $(g-1,1)$ with a puncture along $\gamma$. Applying \autoref{proposition:doubly-punctured-torus} to $\Sigma_1$ and \autoref{proposition:existence-representation-positive-genus} to $\Sigma_2$, and possibly taking a quadratic extension of $K$, we find good integral representations with monodromy $M$ along $\gamma$, and the claim follows by gluing.

	If $n=2$, then $g>0$, so that we can take a separating path $\gamma$ cutting $\Sigma$ into two surfaces $\Sigma_1$ and $\Sigma_2$, where $\Sigma_1$ is a pair of pants containing the two punctures of $\Sigma$ (and with the other puncture along $\gamma$), and $\Sigma_2$ is of type $(g,1)$ with a puncture along $\gamma$. Pick any $M \in \mc N_K$ such that $\tr M$, $k_1$ and $k_2$ satisfy \eqref{equation:numerical-condition-irreducibility} and $\tr M \notin E$. The claim then follows applying \autoref{corollary:existence-integral-representation-pant} and \autoref{proposition:existence-representation-positive-genus} and gluing the constructed representations with monodromy $M$ along $\gamma$.

	If $n \ge 3$ and $g=0$, then $n \ge 4$. Pick $M \in \mc M_K$ such that $\tr M = k_n$: applying \autoref{proposition:existence-representation-punctured-sphere} we find a good integral representation satisfying the sought-after trace conditions at the punctures, possibly defined over a quadratic extension of $K$.

	If $n \ge 3$ and $g>0$, take a separating path $\gamma$ cutting $\Sigma$ into two surfaces $\Sigma_1$ and $\Sigma_2$, where $\Sigma_1$ is of type $(0,n+1)$ and contains all the $n$ punctures of $\Sigma$ (and with the other puncture along $\gamma$), and $\Sigma_2$ is of type $(g,1)$ with a puncture along $\gamma$. Pick any $M \in \mc N_K$ with $\tr M \notin E$. The claim follows by applying \autoref{proposition:existence-representation-punctured-sphere} and \autoref{proposition:existence-representation-positive-genus} and gluing the constructed representations with monodromy $M$ along $\gamma$.
\end{proof}
Combining \autoref{proposition:existence-good-representation} and \autoref{proposition:zariski-dense-orbit} we obtain:
\begin{theorem}\label{theorem:point-with-dense-orbit}
	Let $\Sigma$ be a surface of type $(g,n)$ with $3g-3+n>0$, $K$ be number field, and $k=(k_1,\dots,k_n) \in (\mc O_K)^n$. There exists $p \in X_{g,n,k}(\overline{\mb Z})$ such that $\Gamma_{g,n} \cdot p$ is Zariski dense in $X_{g,n,k, \overline{\mathbb{Q}}}$.
\end{theorem}
Before establishing \autoref{thm:main-theorem} for relative $\SL_2$-character varieties of surfaces, we separately treat the following special case:
\begin{lemma}\label{lemma:finite-orbit-torus}
	The surface $X \colon x^2+y^2+z^2-xyz-4=0$ contains a Zariski dense set of $\mb Z$-points.
\end{lemma}
\begin{proof}
	The automorphism $\tau_x(x,y,z)=(x,z,xz-y)$ of $X$ fixes $x$ and acts on $\begin{pmatrix}y\\z \end{pmatrix}$ as the matrix $\begin{pmatrix}0 & 1 \\-1 & x \\\end{pmatrix}$. Whenever $x \notin E$, we have that $\begin{pmatrix}0 & 1 \\-1 & x \\\end{pmatrix}^n-\begin{pmatrix}1 & 0 \\0 & 1\\\end{pmatrix}$ is invertible, which implies that $(x,0,0)$ is the only point of $\mathbb{A}^3$ with finite $\tau_x$-orbit and first coordinate equal to $x$. It follows that, for all $n \in \mb Z$, the point $(n,n,2)$ has a Zariski dense $\tau_x$-orbit in the curve $x=n$, proving the claim.
\end{proof}
We can finally prove the following:
\begin{theorem}\label{theorem:main-theorem-sl2} Let $\Sigma_{g,n}$ be an orientable surface of genus $g$ with $n$ punctures. Let $k\in \overline{\mathbb{Z}}^n$ be an $n$-tuple of algebraic integers.
	There exists a number field $K$ such that $X_{g,n,k}(\mc O_K)$ is Zariski dense.
\end{theorem}
\begin{proof}
	When $3g-3+n > 0$ the result follows from \autoref{theorem:point-with-dense-orbit}. If $3g-3+n \le  0$ and $g=0$, then the relative character variety is a point (see e.g.~\autoref{rem:P-good}), so the claim is trivial. If $3g-3+n \le  0$ and $g=1$, then $n=0$: by \autoref{proposition:degenerate-character-varieties} $X_{SL_2}(\Sigma_{1,0})$ is just the (full) character variety of a torus, that is $x^2+y^2+z^2-xyz-4=0$, so we conclude by \autoref{lemma:finite-orbit-torus}.
\end{proof}
\begin{remark}\label{rem:degree-4}
Unwinding the proof, one can check that if $K=\mathbb{Q}(k_1, \cdots, k_n)$ is the number field generated by the coordinates of $k\in \overline{\mathbb{Z}}^n$, then there exists a degree $4$ (in fact biquadratic) extension $L$ of $K$ such that $\mathscr{O}_L$-points are Zariski-dense in $X_{g,n,k, \overline{\mathbb{Q}}}$.
\end{remark}
\begin{remark}\label{rem:extension-necessary}
	Some extension is necessary; indeed, consider the variety $$x^2+y^2+z^2-xyz=3,$$ which is a relative character variety of $\Sigma_{1,1}$, by \autoref{subsec:1104}. Working mod $3$, we see that any $\mathbb{Z}$-point of this variety must have $x=y=z=0\bmod 3$. But then $x^2+y^2+z^2-xyz$ is divisible by $9$, and hence cannot equal $3$. Thus this relative character variety has no $\mathbb{Z}$-points.
\end{remark}


\section{ $\PGL_2$-character varieties}\label{sec:pgl2}
Let $\Sigma=\Sigma_{g,n}$ be an orientable surface of genus $g$ with $n$ punctures. The  $\PGL_2$-representation variety $\Hom(\pi_1(\Sigma),\PGL_2)$ is the affine scheme representing the functor $$A \mapsto \Hom(\pi_1(\Sigma),\PGL_2(A)).$$ The  $\PGL_2$-character variety $X_{\PGL_2}(\Sigma)$ is the (categorical) quotient $\Hom(\pi_1(\Sigma),\PGL_2)/\PGL_2$ under the action of  $\PGL_2$ by conjugation.

The regular function $\frac{\tr^2}{\det}$ descends from $\on{GL}_2$ to $\PGL_2$. Hence for each $a \in \pi_1(\Sigma)$ there is a regular function $f_a \coloneqq \frac{\tr_a^2}{\det_a} \colon \Hom(\pi_1(\Sigma), \PGL_2) \to \mb A^1 $ given by $\rho \mapsto \frac{\tr(\rho(a))^2}{\det(\rho(a))}$, which descend to a regular function $f_a \colon X_{\PGL_2}(\Sigma) \to \mb A^1$.
There is a natural morphism $f_{\partial \Sigma} \colon X_{\PGL_2}(\Sigma) \to \mb A^n$ sending $p \in X_{\PGL_2}(\Sigma)$ to the $n$-tuple of $f_a(p)$'s as $a$ varies along the $n$ boundary components of $\Sigma$. For $k \in \mb A^n$, we denote by $X_{\PGL_2, k}(\Sigma) \coloneqq f_{\partial \Sigma}^{-1}(k)$ the \emph{relative  $\PGL_2$-character variety} of $\Sigma$.

The goal of this section is to prove the following:
\begin{theorem}\label{theorem:pgl2-density}
	Let $\Sigma$ be a surface of type $(g,n)$ and $k \in \mb A^n(\Zbar)$. Then there exists a number field $K$ such that $X_{\PGL_2, k}(\Sigma)(\mc O_K)$ is Zariski dense.
\end{theorem}
We will do so by reducing the statement to the potential density of integral points on certain $\SL_2$-character varieties.

\subsection{Reduction to potential density on  $\SL_2$-character varieties}

Given $k=(k_1, \dots, k_n) \in \mb A^n(\Qbar)$, we let $\sqrt{k}_{+}=(\sqrt{k_1}, \dots, \sqrt{k_{n-1}}, \sqrt{k_n})$ and $\sqrt{k}_{-}=(\sqrt{k_1}, \dots, \sqrt{k_{n-1}}, -\sqrt{k_n})$ for a fixed choice of square roots. There are natural morphisms  $X_{\SL_2,\sqrt{k}_{+}}(\Sigma) \to X_{\PGL_2, k}(\Sigma)$ and $X_{\SL_2,\sqrt{k}_{-}}(\Sigma) \to X_{\PGL_2, k}(\Sigma)$. We have the following:
\begin{proposition}\label{proposition:pgl2-lift}
	Let $\Sigma$ be a surface of type $(g,n)$ with $n>0$ and let $k\in \mb A^n(\Qbar)$. Then each point of $X_{\PGL_2, k}(\Sigma)(\Qbar)$ lifts to either $X_{\SL_2,\sqrt{k}_{+}}(\Sigma)(\overline{\mb{Q}})$ or $X_{\SL_2,\sqrt{k}_{-}}(\Sigma)(\overline{\mb{Q}})$.
\end{proposition}
\begin{proof}
	Consider a standard presentation
	\begin{equation*}
		\pi_1(\Sigma)=\langle \alpha_1, \beta_1, \dots, \alpha_g, \beta_g, \gamma_1, \dots, \gamma_n \, \vert \, [\alpha_1,\beta_1] \cdots [\alpha_g,\beta_g] \gamma_1 \cdots \gamma_n=1 \rangle
	\end{equation*}
	of the fundamental group of $\Sigma$.
	Let $p \in  X_{\PGL_2, k}(\Sigma)(\Qbar)$ and let $\rho \in \Hom(\pi_1(\Sigma), \PGL_2(\Qbar))$ be a lift of $p$ to the representation variety. Choose $\widetilde{\rho}(\alpha_i), \widetilde{\rho}(\beta_i), \widetilde{\rho}(\gamma_i) \in \SL_2(\Qbar)$ lifting $\rho(\alpha_i), \rho(\beta_i), \rho(\gamma_i)$  such that $\tr \widetilde{\rho}(\gamma_i)=\sqrt{k_i}$ for $i=1, \dots, n$. In particular, we have that
	\begin{equation*}
		[\widetilde{\rho}(\alpha_1),\widetilde{\rho}(\beta_1)] \cdots [\widetilde{\rho}(\alpha_g),\widetilde{\rho}(\beta_g)] \widetilde{\rho}(\gamma_1) \cdots \widetilde{\rho}(\gamma_n)= \pm I,
	\end{equation*}
	where $I$ denotes the identity matrix. If the right hand side is $+I$, then $[\widetilde{\rho}]$ provides a lift of $p$ to $X_{\SL_2,\sqrt{k}_{+}}(\Sigma)(\overline{\mb{Q}})$. Otherwise, consider the  $\SL_2$-representation $\widetilde{\rho}_{-}$ which agrees with $\widetilde{\rho}$ on all generators of $\pi_1(\Sigma)$ except $\gamma_n$, where instead $\widetilde{\rho}_{-}(\gamma_n)\coloneqq -\widetilde{\rho}(\gamma_n)$. Then $[\widetilde{\rho}_{-}]$ provides a lift of $p$ to $X_{\SL_2,\sqrt{k}_{-}}(\Sigma)(\overline{\mb{Q}})$.
\end{proof}
\begin{corollary}\label{corollary:pgl2-lift}
	The map $X_{\SL_2,\sqrt{k}_{+}}(\Sigma) \sqcup X_{\SL_2,\sqrt{k}_{-}}(\Sigma) \to X_{\PGL_2, k}(\Sigma)$ is dominant.
\end{corollary}
In order to obtain a statement analogous to the above in the non-punctured case, we need to introduce the moduli space of $\SL_2$-local systems on a once-punctured surface with monodromy $-I$ at the puncture. Let $\Sigma$ be a surface of type $(g,1)$ and consider a standard presentation of its fundamental group
\begin{equation*}
	\pi_1(\Sigma)=\langle \alpha_1, \beta_1, \dots, \alpha_g, \beta_g, \gamma \, \vert \, [\alpha_1,\beta_1] \cdots [\alpha_g,\beta_g] \gamma =1 \rangle
\end{equation*}
where $\gamma$ is a loop around the puncture. Let $\Hom(\pi_1(\Sigma), \SL_2)_{-I}$ be the scheme representing the functor
\begin{equation*}
	A \mapsto \{\rho \in \Hom(\pi_1(\Sigma), \SL_2(A)) \, \vert \, \rho(\gamma)=-I \}.
\end{equation*} 
and let $X_{g,-I} \coloneqq \Hom(\pi_1(\Sigma), \SL_2)_{-I} /\SL_2$ be the categorical quotient under the action of  $\SL_2$ by  conjugation.
We have the following analogue of \autoref{proposition:pgl2-lift}:
\begin{proposition}\label{proposition:pgl2-lift-closed-surface}
	Let $\Sigma$ be a surface of type $(g,0)$ with $g\ge 1$. Then each point of $X_{\PGL_2}(\Sigma)(\Qbar)$ lifts to either $X_{\SL_2}(\Sigma)(\overline{\mb{Q}})$ or $X_{g,-I}(\overline{\mb{Q}})$.
\end{proposition}
\begin{proof}
	Analogous to \autoref{proposition:pgl2-lift}.
\end{proof}
\begin{corollary}\label{corollary:pgl2-lift-closed-surface}
	The map $X_{\SL_2}(\Sigma) \sqcup X_{g,-I} \to X_{\PGL_2}(\Sigma)$ is dominant.
\end{corollary}
The goal of the incoming sections is to prove the following:
\begin{theorem}\label{theorem:pgl2-density-minus-id}
	There exists a number field $K$ for which $X_{g,-I}(\mc O_K)$ is Zariski dense.
\end{theorem}
As a corollary of \autoref{theorem:pgl2-density-minus-id} and \autoref{theorem:main-theorem-sl2}, we can now obtain \autoref{theorem:pgl2-density}.
\begin{proof}[Proof of \autoref{theorem:pgl2-density}, assuming \autoref{theorem:pgl2-density-minus-id}]
	The statement follows from \autoref{corollary:pgl2-lift} and \autoref{theorem:main-theorem-sl2} if $n>0$, and from \autoref{corollary:pgl2-lift-closed-surface} and \autoref{theorem:pgl2-density-minus-id} if $n=0$.
\end{proof}



\subsection{Dynamics on $X_{g, -I} $}
Let $\Sigma$ be a surface of type $(g,1)$ with $g \ge 2$ and let $\mc P$ be a pants decomposition of $\Sigma$. The pair of pants containing the puncture of $\Sigma$ will have two more punctures corresponding to paths of $\mc P$, which we denote by $\gamma$ and $\delta$. Let us fix an enumeration $\mc P = \{a_1, \dots, a_{3g-3}, a_{3g-3+1} \}$, where $a_{3g-3}=\gamma$ and $ a_{3g-3+1}=\delta$. We consider the modified trace map
\begin{equation*}
	\tr_{\mc P, -I} \colon X_{g, -I} \to \mb A^{3g-3}
\end{equation*}
that sends a point of $X_{g, -I}$ to the traces along all paths of $\mc P$ \emph{except} $\delta$.

For $t \in \mb A^{3g-3}$, we denote $X^\mathcal{P}_{t,-I} \coloneqq \tr_{\mc P,-I}^{-1}(t)$.
Let
\begin{equation*}
	(-) \vert_{\Sigma \setminus \mc P} \colon X_{g,-I} \to X(\Sigma_1)\times \cdots \times X(\Sigma_{2g-2})
\end{equation*}
be the morphism induced by the immersion $\Sigma \setminus \mc P \to \Sigma$, where the product on the right hand side is taken over all the pair of pants associated to $\mc P$, with the exception of the pair of pants containing the puncture of $\Sigma$. Clearly $(-) \vert_{\Sigma \setminus \mc P}$ is constant along each fiber $X^\mathcal{P}_{t,-I}$.

\begin{definition}
	We say that $X^\mathcal{P}_{t,-I}$ is \emph{perfect} if
	\begin{itemize}
		\item for all $a_i \in \mc P$, we have $\tr_{a_i}(X^\mathcal{P}_{t,-I}) \neq \pm 2$ and
		\item $g=1$ or, for each $[\rho]$ in $X^\mathcal{P}_{t,-I}(\mb C)$, its restriction to each component of ${\Sigma \setminus \mc P}$ is irreducible, with the exception of the component containing the puncture of $\Sigma$.
	\end{itemize}
\end{definition}

Let $X^\mathcal{P}_{t,-I}$ be a perfect fiber. Notice that the action of $\Gamma_{\mc P}$ preserves $X^\mathcal{P}_{t,-I}$. Fix $(\lambda_1, \dots, \lambda_{3g-3}) \in (\Qbar^{\times})^{3g-3}$ such that $\lambda_i+\lambda_i^{-1}=t_i$. We denote by $T_{z_i} \colon \mb{G}_m^{3g-3} \to \mb{G}_m^{3g-3}$ the multiplication of the $i$-th coordinate by $\lambda_i$.
\begin{proposition}
	If $X^\mathcal{P}_{t,-I}$ be a perfect fiber, then there is a morphism
	\begin{equation*}
		F \colon \mb{G}_m^{3g-3} \to X^\mathcal{P}_{t,-I}
	\end{equation*}
	defined over $\Qbar$ satisfying the following:
	\begin{enumerate}
		\item at the level of $\Qbar$-points, $F$ is surjective with finite fibers,
		\item the action of $T_{z_i}$ on $\mb{G}_m^{3g-3}$ lifts the action of the Dehn twist $\tau_{a_i}$ on $X^\mathcal{P}_{t,-I}$.
	\end{enumerate}
\end{proposition}
\begin{proof}
	We refer the reader to the proof of \cite[Proposition $4.3$]{whang:ant}, as the argument is the same, with the only difference that in our case one obtains a morphism from $\mb{G}_m^{3g-3}$ to $X^\mathcal{P}_{t,-I}$, rather than from $\mb{G}_m^{3g-3+1}$ as in \cite[Proposition $4.3$]{whang:ant}. This is due to the fact that the restriction of a representation $\rho \in \Hom(\pi_1(\Sigma), \SL_2)_{-I}(\Qbar)$ to the pair of pants containing the puncture of $\Sigma$ is uniquely determined by $\rho(\gamma)$, since $\rho(\delta)=-\rho(\gamma)^{-1}$ as the monodromy at the puncture is $-I$.
\end{proof}


\begin{definition}
	Let $\mc P$ be a pants decomposition of $\Sigma$, $p \in X_{g,-I}$ and $t \coloneqq \tr_{\mc P,-I}(p)$. We say that $p$ is $\mc P$-good if $X^{\mc P}_{t,-I}$ is perfect and, for any $a \in \mc P \setminus \{ \gamma \cup \delta \}$, we have $\tr_a(X^\mathcal{P}_{t,-I}) \notin E$.
\end{definition}
Let $\Gamma_{-I}$ be the subgroup of the mapping class group of $\Sigma$ which is the identity on $\gamma$ and $\delta$. In particular $\Gamma_{-I}$ preserves the fibers of $\tr_{\gamma}$. We have the following:
\begin{proposition}\label{proposition:zariski-dense-orbit-minus-identity}
	Let $\mc P$ be a pants decomposition and let $p \in X_{g,-I}(\Qbar)$ be a $\mc P$-good point. Then $\Gamma_{-I} \cdot p$ is Zariski dense in $\tr_{\gamma}^{-1}(\tr_{\gamma}(p))$.
\end{proposition}
\begin{proof}
	The proof is the same as \autoref{proposition:zariski-dense-orbit}, except that we only use Dehn twists along paths that do not intersect $\gamma$ and $\delta$.
\end{proof}
In light of the previous proposition, in order to prove \autoref{theorem:pgl2-density-minus-id} it is sufficient to find a number field $K$ and a pants decomposition $\mc P$ of $\Sigma$ for which there exists infinitely many $\mc P$-good points $p \in X_{g,-I}(\mc O_K)$ with \emph{distinct} traces along $\gamma$. We will construct these points in the next section.

\subsection{Construction of an integral representation}
We introduce a class of matrices that will play the same role as the class $\mc N_K$ used in \autoref{section:construction_integral_representation}.
\begin{definition}
	Let $K$ be a finite extension of $\mb Q(i)$. We define $\mc L_{K} \subset \SL_2(\mc O_K)$ as the set of matrices
	\begin{align*}
		\mc L_{K} &= \left\{ \begin{pmatrix}
			ad+bc & 2ab \\
			2cd & ad+bc \\
		\end{pmatrix}  \, \Big | \, a, b, c, d \in \mc O_K, ad-bc=1, cd \neq 0  \right\}  \\
		&= \left\{ \left[ \begin{pmatrix}
			a & b \\
			c & d \\
		\end{pmatrix} , \begin{pmatrix}
			i & 0 \\
			0 & -i \\
		\end{pmatrix} \right]   \, \Big | \, a, b, c, d \in \mc O_K, ad-bc=1, cd \neq 0 \right\}
	\end{align*}
\end{definition}

\begin{remark}\label{remark:unit-scaling}
	For $\lambda \in \mc O_K^{\times}$ we have
	\begin{equation*}
		 \left[ \begin{pmatrix}
			a \lambda & b \lambda^{-1} \\
			c \lambda & d \lambda^{-1} \\
		\end{pmatrix} , \begin{pmatrix}
			i & 0 \\
			0 & -i \\
		\end{pmatrix} \right]= \left[ \begin{pmatrix}
		a & b \\
		c & d \\
		\end{pmatrix} , \begin{pmatrix}
		i & 0 \\
		0 & -i \\
		\end{pmatrix} \right].
	\end{equation*}
	In particular, if $\mc O_K^{\times}$ is infinite, for any $M \in \mc L_K$ the set $\left\{ \tr A \, \Big | \, \left[A, \begin{pmatrix} 
	i & 0 \\
	0 & -i \\
	\end{pmatrix}\right]=M \right\}$ is infinite.
\end{remark}

\begin{remark}\label{rem:minus-inverse}
	If $M \in \mc L_K$ then $M^{-1} \in \mc L_K$ and $-M \in \mc L_K$. Indeed
	\begin{equation*}
		\left[ \begin{pmatrix}
			a & b \\
			c & d \\
		\end{pmatrix} , \begin{pmatrix}
			i & 0 \\
			0 & -i \\
		\end{pmatrix} \right]^{-1} = \left[ \begin{pmatrix}
		-a & b \\
		c & -d \\
		\end{pmatrix} , \begin{pmatrix}
		i & 0 \\
		0 & -i \\
		\end{pmatrix} \right] 
	\end{equation*} 
	and
	\begin{equation*}
		-\left[ \begin{pmatrix}
			a & b \\
			c & d \\
		\end{pmatrix} , \begin{pmatrix}
			i & 0 \\
			0 & -i \\
		\end{pmatrix} \right] = \left[ \begin{pmatrix}
			-b & a \\
			-d & c \\
		\end{pmatrix} , \begin{pmatrix}
			i & 0 \\
			0 & -i \\
		\end{pmatrix} \right] 
	\end{equation*} 
\end{remark}
The class of matrices $\mc L_K$ satisfies similar properties as $\mc N_K$.
Specifically, we have the following:
\begin{lemma}\label{lemma:existence-representation-two-holed-torus-minus-id}
	Assume $\mc O_K^{\times}$ is infinite. Let $M \in \mc L_K$. Then there exists a pants decomposition $\mc P$ of $\Sigma_{1,2}$ and a $\mc P$-good representation $\rho \colon \pi_1(\Sigma_{1,2}) \to \SL_2(\mc O_K)$ such that the monodromies along the first and second puncture are $M$ and $M^{-1}$, respectively.
\end{lemma}
\begin{proof}
	The proof is the same as \autoref{lemma:existence-representation-two-holed-torus}, and crucially uses that the bottom left entry of $M$ is non-zero.
\end{proof}


\begin{lemma}\label{lemma:existence-integral-representation-torus-minus-id}
	Assume $\mc O_K^{\times}$ is infinite. For any $M \in \mc L_K$ there exists a pants decomposition $\mc P$ of $\Sigma_{1,1}$ and a $\mc P$-good representation $\rho \colon \pi_1(\Sigma_{1,1}) \to \SL_2(\mc O_K)$ with monodromy $M$ along the puncture.
\end{lemma}
\begin{proof}
	This is an immediate consequence of \autoref{remark:unit-scaling}.
\end{proof}

\begin{proposition}\label{proposition:existence-representation-positive-genus-minus-id}
	Let $K$ be a number field, $g \ge 1$ and $M \in \mc L_K$ such that $\tr M \notin E$. Assume that $\mc O_K^{\times}$ is infinite. There exists a pants decomposition $\mathcal{P}$ of $\Sigma=\Sigma_{g,1}$ and a $\mc P$-good representation $\rho \colon \pi_1(\Sigma) \to \SL_2(\mc O_K)$ with monodromy $M$ at the puncture.
\end{proposition}
\begin{proof}
	The proof is analogous to \autoref{proposition:existence-representation-positive-genus} and crucially uses that $\mc L_K$ is closed under inversion.
\end{proof}


