 % \section{When the Rothberger number is well defined?}

In the studies of $\bnumber_{R}(\I)$, we can restrict to $\I$-gaps satisfying an additional property that  $\cA$ is a partition of $\omega$ \cite[Lemma~2.2]{MR3247032}.
Consequently, a  necessary condition for the number $\bnumber_{R}(\I)$ to be well defined (i.e.~to be $\leq \continuum$) is the existence of an infinite  partition of $\omega$ consisting of $\I$-positive sets. 
On the other hand, such a partition exists if and only if $\I$ is not a direct sum (see page~\pageref{def:direct-sum} for the definition) of finitely many maximal ideals
\cite[Proposition 4.3]{FKL}.
In particular, such a partition exists for every ideal $\I$ with the \emph{hereditary Baire property} (i.e., $\I\restriction X = \{A\cap X: A\in \I\}$ has the Baire property for every $X\in\I^+$) \cite[Proposition 2.5]{FKL}. Note that Borel and analytic ideals have the hereditary Baire property.
The following lemma gives a sufficient condition for $\bnumber_R(\I)$ to be well defined.

\begin{lemma}
\label{lem:when-bR-exists-charaterization}
	 $\bnumber_{R}(\I)\leq \continuum$ if and only if 
	there exists a partition $\{A_n:n<\omega\}$ of $\omega$ such that 
	$A_n\in \I^+$ for each $n$ and 
	$$\forall C\subseteq\omega \left[
	\forall n\, (C\cap A_n\in \I)
	\implies 
	\exists B\in \I^+(B\cap C=\emptyset \land \forall n\, (B\cap A_n\in \I))\right].
	$$
\end{lemma}

\begin{proof}
	($\implies$)
	Let  $(\cA,\cB)$ be a Rothberger $\I$-gap with $|\cB|\leq \continuum$. Without loss of generality, we can assume that $\cA=\{A_n:n<\omega\}$ is a partition of $\omega$ into $\I$-positive sets \cite[Lemma~2.2]{MR3247032}.
	Take any $C\subseteq\omega$ such that $C\cap A_n\in \I$ for each $n$. Since $(\cA,\cB)$ is an $\I$-gap, there is $B\in \cB$ such that $B'=B\setminus C\notin\I$. Then $B'\in\I^+$, $B'\cap C=\emptyset$  and $B'\cap A_n\subseteq B\cap A_n\in \I$ for all $n$.

	($\impliedby$)
	Let  $\{A_n:n<\omega\}$ be a partition of $\omega$ into $\I$-positive sets with the required property.
Let  $\cB=\{B\subseteq \omega: B\in \I^+ \text{ and } B\cap A_n\in \I\text{ for all }n\}$.
The pair $(\cA,\cB)$ is $\I$-orthogonal.
Once we show that $(\cA,\cB)$ cannot be $\I$-separated, 
$\bnumber_{R}(\I)\leq |\cB|\leq \continuum$ and the proof will be finished.
	Take $C\subseteq\omega$ such that $C\cap A_n\in \I$ for each $n$. Then there is $B\in\I^+$ such that $B\cap C=\emptyset$ and $B\cap A_n\in \I$ for each $n$.
	Since $B\in \cB$ and $B\setminus C=B\notin\I$, $C$ does not $\I$-separate $(\cA,\cB)$.
\end{proof}


An ideal $\I$ on $X$ is a \emph{$P^+$-ideal} (\emph{$P^+(\I)$-ideal}, resp.)  if for any decreasing sequence $\langle A_n : n\in\omega\rangle$ of $\I$-positive sets there is $A \in \I^+$ such that
$A\setminus A_{n}$ is finite 
($A\setminus A_{n}\in \I$, resp.)
for every $n$.
Every $F_\sigma$-ideal is a $P^+$-ideal \cite[Lemma 3.2.4]{alcantara-phd-thesis}.
Obviously, every $P^+$-ideal is $P^+(\I)$. 
On the other hand, 
the ideal 
% $$\Fin^2 = \FIN\otimes \FIN = \{A\subseteq \omega\times \omega: |\{n:|\{k:(n,k)\in A\}|=\omega\}|<\omega\}$$ 
$$\Fin^2 = \FIN\otimes \FIN = \{A\subseteq \omega\times \omega: A_{(n)} \text{ is finite for all but finitely many $n$}\}$$ 
is $P^+(\FIN\otimes\FIN)$-ideal but it is not a $P^+$-ideal \cite[Proposition~2.6(2)]{MR4448270}.
On can also show   that the ideal 
$$\conv = \{A\subseteq \Q\cap [0,1]: \text{$A$ has finitely many accumulation points in $[0,1]$}\}$$ 
is $P^+(\conv)$-ideal but it is not a $P^+$-ideal.
Each $P^+(\I)$-ideal has $BW$ property (for definition see \cite{MR2961261}), so 
the following ideals (which do not have $BW$ property \cite{MR2320288}) are not $P^+(\I)$-ideals:
\begin{equation*}
    \begin{split}
\I_d &= \left\{A\subseteq\omega: \limsup_{n\to\infty} \frac{|A\cap n|}{n}=0\right\},
\\
\nwd & = \{A\subseteq\Q\cap [0,1]: \text{$A$ is nowhere dense in $[0,1]$}\}.
    \end{split}
\end{equation*}

The following proposition gives a sufficient condition for $\bnumber_R(\I)$ to be well defined.

\begin{proposition}
Each of the following conditions guarantees  (separately)  that $\bnumber_{R}(\I)\leq \continuum$. 
	\begin{enumerate}
		\item 
$\I$ is a $P^+(\I)$-ideal and there exists an infinite partition of $\omega$ consisting of $\I$-positive sets.

		\item 	
There is $X\in\I^+$ such that $\I\restriction X$ is a $P^+(\I\restriction X)$-ideal and 
there exists an infinite partition of $X$ consisting of $\I$-positive sets.

\item $\I$ is a Borel ideals and 
and there is $X\in\I^+$ such that $\I\restriction X$ is a $P^+(\I\restriction X)$-ideal.
	\end{enumerate}
\end{proposition}

\begin{proof}
	(1) 
    Let $\{A_n:n<\omega\}$ be a partition of $\omega$ such that $A_n\in \I^+$ for each $n$. We will use Lemma~\ref{lem:when-bR-exists-charaterization}. Take any $C\subseteq \omega$ with $C\cap A_n\in \I$ for all $n$.
    Define 
$$D_n=\bigcup \{ A_k\setminus C : k\geq n\}$$
for each $n$.
Since
$D_n\supseteq D_{n+1}$ and $D_n\notin \I$ for all $n$
and $\I$ is a $P^+(\I)$-ideal, there exists $B\in\I^+$ such that $B\setminus D_n\in \I$ for each $n$. In particular, $B'=B\cap D_0\notin\I$. Then $B'\cap A_n \subseteq B\setminus D_{n+1}\in\I$ for each $n$ and $B'\cap C\subseteq D_0\cap C=\emptyset$, so  
$\bnumber_{R}(\I)\leq \continuum$
by Lemma~\ref{lem:when-bR-exists-charaterization}.

	(2) Apply item (1) to the ideal $\I\restriction X$ and use the fact that $\bnumber_{R}(\I)\leq \bnumber_{R}(\I\restriction X)$ \cite[Remark~2.4(2)]{MR3247032}. 

    (3) Follows from item (2) and the fact that Borel ideals have the hereditary Baire property (hence there is an infinite partition of $\omega$ consisting of $\I$-positive sets \cite[Proposition 2.5]{FKL}).
\end{proof}



\begin{question}
Is $\bnumber_{R}(\I)\leq \continuum$ for each Borel ideal $\I$?
\end{question}

