\section{\texorpdfstring{$\bnumber(\I)$}{b-I} is less than or equal to  \texorpdfstring{$\bnumber_{R}(\I)$}{b-R-I}}

For an ideal $\I$, we use the following notation:
\begin{itemize}
    \item $\widehat{\cP}_\I$ is the family of all sequences $\langle A_n : n\in\omega\rangle$ such that 
	$A_n\in \I$ for  all $n\in\omega$
	and
	$A_n\cap A_k=\emptyset$ for $n\neq k$;
    \item $\cP_\I$ is the family of all sequences 
	$\langle A_n : n\in\omega\rangle \in \widehat{\cP}_\I$ with 
	$\bigcup\{A_n: n\in \omega\} = \omega$.
\end{itemize}

Using the above notation, we can characterize
the number $\bnumber(\I)$ in the following more technical though useful manner.

\begin{theorem}[{\cite[Theorem~3.10]{MR4472525}}]
\label{thm:b-characterization}
For any ideal $\I$ on $\omega$, 
\begin{equation*}
\begin{split}
\bnumber(\I)  = 
\min \left\{|\cE|:\cE\subseteq\widehat{\cP}_\I 
\text{ and } \right.
& 
\text{for every  $\langle A_n\rangle\in\cP_\I$ there exists $\langle E_n\rangle\in\cE$ with } 
\\ &
\left. 
\text{$\bigcup_{n\in\omega}\left(A_n\cap \bigcup_{i\leq n}E_i\right)\notin\I$}  
\right\}.
\end{split}
\end{equation*}

    % \begin{equation*}
	% 	\begin{split}
	% 		\bb(\I)  & = 
	% 		\min \left\{|\cE|:\cE\subseteq\widehat{\cP}_\I \land \forall \langle A_n\rangle\in\cP_\I \, \exists \langle E_n\rangle\in\cE \ \bigcup_{n\in\omega}\left(A_n\cap \bigcup_{i\leq n}E_i\right)\notin\I  \right\}.\\
	% 	\end{split}
	% \end{equation*}
\end{theorem}

With the aid of the above characterization, we can prove the following theorem.

\begin{theorem}
\label{thm:b-vs-b-inequality}
$\bnumber(\I)\leq\bnumber_{R}(\I)$ for every ideal $\I$.
\end{theorem}

\begin{proof}
It is enough to show that $\lambda<\bnumber(\I)$  implies $\lambda<\bnumber_{R}(\I)$.
Let $\lambda<\bnumber(\I)$ and take families $\cA,\cB\subseteq \cP(\omega)$ such that $|\cA|=\omega$, $|\cB|=\lambda$, $\cA=\{A_n:n\in\omega\}$ is a partition of $\omega$ and $A\cap B\in \I$ for any $A\in \cA$, $B\in \cB$.
We have to show that there is $C\subseteq \omega$ such that $A\cap C\in \I$ and $B\setminus C\in \I$ for any $A\in \cA$ and  $B\in \cB$.

For each $A\in \cA$ and $B\in \cB$, we define $E_A^B=A\cap B$. Then $E_A^B\in \I$ for each $A,B$. Moreover, since $\cA$ is a partition of $\omega$, $E_{A_1}^B\cap E_{A_2}^B=\emptyset$ for any distinct $A_1,A_2\in \cA$.

Let $\cE=\{\{E_A^B:A\in \cA\}:B\in \cB\}$.
Since $|\cE|\leq |\cB| = \lambda<\bnumber(\I)$, 
there is a partition $\{C_n:n\in \omega\}$ of $\omega$ such that $C_n\in \I$ for each $n$, and 
$$\bigcup_{n\in \omega}\left(C_n\cap \bigcup_{i\leq n} E^B_{A_i}\right)\in \I$$ for each $B\in \cB$.
We claim that the set 
$$C = \bigcup_{n\in \omega}\left(A_n\cap \bigcup_{i<n} C_i\right)$$
separates the pair $(\cA,\cB)$.
First, we observe that 
$$
A_k\cap C 
= 
A_k\cap \bigcup_{n\in \omega}\left(A_n\cap \bigcup_{i<n} C_i\right)
=
A_k\cap \bigcup_{i<k}C_i
\in \I
$$
for every $k\in\omega$.
Second, we observe that 
\begin{equation*}
\begin{split}
B \setminus C 
& 
= 
B \setminus \bigcup_{n\in \omega}\left(A_n\cap \bigcup_{i<n} C_i\right)
=
\bigcup_{n\in \omega}\left(A_n\cap B\right) \setminus \bigcup_{n\in \omega}\left(A_n\cap \bigcup_{i<n} C_i\right)
\\ & 
=
\bigcup_{n\in \omega}\left(A_n\cap B \setminus  \bigcup_{i<n} C_i\right)
=
\bigcup_{n\in \omega}\left(E^B_{A_n} \setminus  \bigcup_{i<n} C_i\right)
\\ &
\subseteq
\bigcup_{n\in \omega}\left(C_n\cap \bigcup_{i\leq n }E^B_{A_i}\right)
\in\I
\end{split}
\end{equation*}
for every $B\in \cB$. 
\end{proof}

\begin{remark}
In Theorem \ref{thm:bR-characterization} we provide a characterization of $\bnumber_R(\I)$ which is similar to the above characterization of $\bnumber(\I)$, and then Theorem~\ref{thm:b-vs-b-inequality} 
will  easily follow from Theorem~\ref{thm:bR-characterization}, However, we decided to prove Theorem \ref{thm:b-vs-b-inequality} without the use of Theorem \ref{thm:bR-characterization}, since the above proof is much simpler.
\end{remark}

As a collorary of Theorem \ref{thm:bR-characterization},  we can  calculate $\bb(\I)$ for some well-known ideals (for the definitions of ideals mentioned in this theorem see e.g.~\cite{MR3247032}).

\begin{corollary}
	$\bnumber(\I)=\omega_1$ for 
the following ideals 
$\I$: (1)~$\ED$, (2)~$\ED_{\fin}$, 
(3)~fragmented not gradually fragmented ideals $\I = \I_{\{(a_i,\phi_i):j\in\omega\}}$ such that all $\phi_i$ are uniform submeasures
and 
(4)~somewhere tall fragmented ideals 
$\I = \I_{\{(a_i,\phi_i):j\in\omega\}}$ such that all $\phi_i$ are measures.
\end{corollary}

\begin{proof}
Since $\bnumber(\I)\geq \omega_1$ for each $\I$ \cite[Theorem~4.2]{MR4472525}, we only need to show that $\bnumber(\I)\leq \omega_1$ in the case of these ideals. Items (2), (3) and (4) follow from Theorem~\ref{thm:b-vs-b-inequality} and the fact that  $\bnumber_{R}(\I)=\omega_1$ in these cases \cite[Theorem~3.1, 3.4 and 3.6]{MR3247032}. Item (1) follows from 
item (2), the equality  $\ED_{\fin} = \ED\restriction\{(n,k)\in \omega^2: k\leq n\}$
and the inequality $\bnumber(\I)\leq \bnumber(\I\restriction X)$, which holds for every $X\notin \I$ \cite[Theorem~5.1]{MR4472525}.
\end{proof}

\begin{proposition}
\label{prop:b-for-products}
Let  $\I$ and $\J$ be ideals on $\omega$.
\begin{enumerate}
    \item 
$\bnumber_{R}(\I\otimes \J)\leq\bnumber_R(\I)$. 
\item 
If $\bnumber_{R}(\I)  = \bnumber(\I)$, then 
$\bnumber_{R}(\I\otimes \J) = \bnumber(\I\otimes \J)=\bnumber(\I)$.
\end{enumerate}
\end{proposition}

\begin{proof}
(1)
If $\bnumber_{R}(\I)=\continuum^+$, there is nothing to show, so assume that $\bnumber_{R}(\I)\leq \continuum$ and take an $\I$-$(\omega,\bnumber_{R}(\I))$-gap $(\cA,\cB)$.
		Define $\cC = \{A\times\omega: A\in \cA\}$ and $\cD = \{B\times\omega: B\in \cB\}$.
	Once we show that $(\cC,\cD)$ is an $\I\otimes\J$-$(\omega,\bnumber_{R}(\I))$-gap, the proof will be finished.
	Obviously, $|\cC|=\omega$ and $|\cD|=\bnumber_{R}(\I)$. Moreover, since $A\cap B\in \I$, $(A\times \omega)\cap (B\times \omega) = (A\cap B)\times\omega \in \I\otimes\J$. Thus, $(\cC,\cD)$ is $\I\otimes\J$-orthogonal. Suppose that there is a set $C\subseteq \omega\times\omega$ which $\I\otimes\J$-separates the pair $(\cC,\cD)$. Denote $D = \{n\in \omega: C_{(n)}\notin \J\}$, where $C_{(n)} = \{k\in \omega: (n,k)\in C\}$. If we show that the pair $(\cA,\cB)$ is $\I$-separated by the set
    $D$, we will obtain a contradiction.
Take a set $A\in \cA$.
Since $(A\times \omega)\cap C\in \I\otimes\J$, 
$A\cap D \subseteq  \{n\in\omega: ((A\times \omega)\cap C)_{(n)}\notin\J\}\in \I$. Now take a set $B\in \cB$.
Since $(B\times \omega)\setminus  C\in \I\otimes\J$, 
$B\setminus D \subseteq  \{n\in\omega: ((B\times \omega)\setminus  C)_{(n)}\notin\J\}\in \I$. Thus $D$ separates the pair $(\cA,\cB)$.


(2)
It is known that 
$\bnumber(\I) = \bnumber(\I\otimes \J)$ \cite[Theorem 5.13]{MR4472525}, so using item (1) and Theorem~\ref{thm:b-vs-b-inequality}, we obtain 
	$$\bnumber_{R}(\I\otimes \J) \leq  \bnumber_{R}(\I) =\bnumber(\I) = \bnumber(\I\otimes \J) \leq \bnumber_{R}(\I\otimes\J).$$
\end{proof}

For any positive  $n\in \omega$, we define by recursion the ideals $\FIN^n$ by  
$$\FIN^1=\Fin \quad  \text{ and }\quad \FIN^{n+1} = \FIN\otimes \FIN^n.$$ 


\begin{corollary}
	$\bnumber_{R}(\fin^{n+1}) = \bnumber$ for each $n\in \omega$.
	In particular, $\bnumber_{R}(\fin\otimes\fin) = \bnumber$.
\end{corollary}

\begin{proof}
		Since $\bnumber_{R}(\fin)=\bb(\fin)=\bnumber$ and $\fin^{n+1} = \fin\otimes \fin^{n}$, Proposition~\ref{prop:b-for-products}
finishes the proof.
\end{proof}




