\section{Characterization of the Rothberger number}


The  characterization of the number $\bnumber(\I)$ from Theorem~\ref{thm:b-characterization} can be rephrased  in the following manner:
\begin{equation*}
\begin{split}
\bnumber(\I) = 
\min 
\left\{ 
\kappa: 
 \right.
&
\exists_{\{E_n^\alpha: n<\omega \alpha<\kappa\}\subseteq \I} \,
\left[ 
\left( 
\forall_{\alpha<\kappa}\,\forall_{n\in\omega}\, E^\alpha_n\cap \bigcup_{m\neq n} E^\alpha_m=\emptyset
\right) 
\land 
\right. 
\\&
\left.  
\left. 
\left(
\forall_{\{A_n:n<\omega\}\in\cP_\I} \, \exists_{\alpha<\kappa}\, \bigcup_{n\in\omega}
\left(
A_n\cap \bigcup_{i\leq n}E^\alpha_i
\right) 
\notin\I
\right)
\right]
\right\}.
\end{split}
\end{equation*}
In Theorem~\ref{thm:bR-characterization}, we show that the Rothberger number $\bnumber_{R}(\I)$ can be characterized in a similar manner as  the above  characterization of $\bb(\I)$.
It is worth to stress that the \emph{only} difference between the above characterization of
	$\bnumber(\I)$ and the below characterization of $\bnumber_{R}(\I)$ 
	lies in the fact that 
	in the former we only require 
	$$E^\alpha_n\cap \bigcup_{m\neq n} E^\alpha_m=\emptyset$$ 
	for each $\alpha$ separately,
	whereas in the latter we will require disjointness for all $\beta$ simultaneously, i.e.
	$$E^\alpha_n\cap \bigcup_{\beta<\kappa} \left(\bigcup_{m\neq n} E^\beta_m\right)=\emptyset.$$ 

\begin{theorem}
	\label{thm:bR-characterization}
	For any ideal $\I$, 
\begin{equation*}
	\begin{split}
		\bnumber_R(\I) = 
		\min \left\{\kappa:
        \right.
        &
        \left.
\exists_{\{E_n^\alpha: n<\omega,\alpha<\kappa\}\subseteq \I}\,
\left[\left( \forall_{\alpha<\kappa}\, \forall_{n\in\omega}\,E^\alpha_n\cap \bigcup_{\beta<\kappa} \left(\bigcup_{m\neq n} E^\beta_m\right)=\emptyset\right) \land 
		\right.\right.
		\\&
		\left. \left.\left(\forall_{\{A_n:n<\omega\}\in\cP_\I}\, \exists_{\alpha<\kappa}\, \bigcup_{n\in\omega}\left(A_n\cap \bigcup_{i\leq n}E^\alpha_i\right)\notin\I\right)\right]\right\}.
	\end{split}
\end{equation*}
\end{theorem}

\begin{proof}
	$(\geq)$ 
	Let $(\cA,\cB)$ be an $\I$-gap of type $(\omega,\bnumber_{R}(\I))$.
	Without loss of generality, we can assume that $\cA$ is a partition of $\omega$.
	Let $\cA = \{A_n:n\in\omega\}$ and $\cB = \{B_\alpha:\alpha<\bnumber_{R}(\I)\}$.
	We define 
	$$E_n^\alpha = A_n\cap B_\alpha\in\I$$
	for each $n<\omega$ and $\alpha<\bnumber_{R}(\I)$.
	Then $E_n^\alpha\cap E_m^\beta=\emptyset$ for each $n\neq m$ and arbitrary $\alpha,\beta<\bnumber_{R}(\I)$.	
	Take any $\{D_n:n<\omega\}\in\cP_\I$. To finish the proof, we have to show that  
    $$\bigcup_{n\in\omega}\left(D_n\cap \bigcup_{i\leq n}E^\alpha_i\right)\notin\I$$ 
    for some $\alpha<\bnumber_{R}(\I)$.
	Let us define 
	$$C =\bigcup_{n\in\omega} \left(A_n\cap \bigcup_{i< n} D_i\right).$$ 
	Since $C\cap A_n \subseteq \bigcup_{i< n} D_i \in \I$ for each $n$ and $(\cA,\cB)$ is an $\I$-gap, there exists $\alpha<\bnumber_{R}(\I)$ with 
	$B_\alpha\setminus C\notin \I$.
	We claim that 
    $$B_\alpha\setminus C\subseteq \bigcup_{n\in\omega}\left(D_n\cap \bigcup_{i\leq n}E^\alpha_i\right).$$
	Indeed, take $x\in B_\alpha\setminus C$ and let $n\in\omega$ be such that $x\in A_n$. Since $x\notin C$, $x\notin \bigcup_{i< n} D_i$. Then there is $k\geq n$ such that $x\in D_k$.
	Consequently, 
	$$x\in D_k\cap A_n \cap  B_\alpha= D_k\cap E^\alpha_n \subseteq D_k\cap \bigcup_{i\leq k} E^\alpha_i  \subseteq \bigcup_{n\in\omega}\left(D_n\cap \bigcup_{i\leq n}E^\alpha_i\right).$$


	$(\leq)$
	Let $\{E_n^\alpha : n<\omega, \alpha<\kappa\} \subseteq \I$
	be such that 	
	$E_n^\alpha \cap E_m^\beta=\emptyset$ for each $\alpha,\beta<\kappa$ and $n\neq m$
	and for any $\{D_n:n<\omega\} \in \cP_\I$ there is $\alpha<\kappa$ with 
    $$\bigcup_{n\in\omega}\left(D_n\cap \bigcup_{i\leq n}E^\alpha_i\right)\notin\I.$$ 
	Let $\cA=\{A_n:n\in\omega\}$ and $\cB=\{B_\alpha:\alpha<\kappa\}$, where  
	$$A_n =\bigcup_{\alpha<\kappa} E^\alpha_n
	\text{\ \ and\ \ } B_\alpha = \bigcup_{n<\omega} E^\alpha_n$$ 
	for each $n\in\omega$ and $\alpha<\kappa$.
If we show that $(\cA, \cB)$ is an $\I$-$(\omega,\lambda)$-gap  and  $\lambda\leq \kappa$, the proof will be finished.	
	Since $A_n\cap B_\alpha = E^\alpha_n\in \I$, the families $\cA$ and $\cB$ are $\I$-orthogonal.
	Obviously $|\cB|\leq \kappa$. We claim that 
	$|\cA|=\omega$. Indeed, otherwise $A_n=\emptyset$ for all but finitely many $n$, so there is $k$ such that $E^\alpha_n=\emptyset$ for each $\alpha$ and $n\geq k$. Consequently, for any $\{D_n :n<\omega\} \in\cP_\I$ and any $\alpha<\kappa$ we have 
    $$\bigcup_{n\in\omega}\left(D_n\cap \bigcup_{i\leq n} E^\alpha_i\right)\subseteq \bigcup_{n<\omega}E^\alpha_n \in\I,$$ a contradiction.	
	Finally, we show that no $C$ can $\I$-separate $(\cA,\cB)$.	
	Take any $C\subseteq\omega$ such that $A_n\cap C\in \I$ for any $n$.
	We need to find $\alpha<\kappa$ such that $B_\alpha\setminus C\notin\I$.
	We define $D'_n = C\cap A_{n+1}$ for each $n\in \omega$. Let $\omega\setminus \bigcup_{n\in \omega}D'_n = \{a_n:n\in\omega\}$. Now we define $D_n = D'_n\cup\{a_n\}$ for each $n$. Then $\{D_n:n\in \omega\}\in \cP_\I$, so there is $\alpha<\kappa$ 
	with 
    $$\bigcup_{n\in\omega}\left(D_n\cap \bigcup_{i\leq n}E^\alpha_i\right)\notin\I.$$ 
Once we show  that 
$$\bigcup_{n\in\omega}\left(D_n\cap \bigcup_{i\leq n}E^\alpha_i\right) \subseteq (B_\alpha\setminus C) \cup (A_0\cap C),$$    
then 	$B_\alpha\setminus C\notin\I$,
    because
 $A_0\cap C\in \I$.
Since
$$
	\bigcup_{n\in\omega}\left(D_n\cap \bigcup_{i\leq n}E^\alpha_i\right) 
	\subseteq 
	\bigcup_{n\in\omega}\bigcup_{i\leq n}E^\alpha_i
	= B_\alpha,$$
	we have
\begin{equation*}
	\begin{split}
    \bigcup_{n\in\omega}\left(D_n\cap \bigcup_{i\leq n}E^\alpha_i\right) 
 & = 
	% \left(
    \bigcup_{n\in\omega}\left(D_n\cap \bigcup_{i\leq n}E^\alpha_i\right)
    % \right)
    \setminus C 
	\\&
     \cup 
	% \left(
    \bigcup_{n\in\omega}\left(D_n\cap \bigcup_{i\leq n}E^\alpha_i\right)
    % \right) 
    \cap  C
	 \\&
    \subseteq 
	(B_\alpha\setminus C)
	\cup
	% \left(
    \left(\bigcup_{n\in\omega}\left(D_n\cap \bigcup_{i\leq n}E^\alpha_i\right)\cap  C\right) 
    % \right)
    .
\end{split}
\end{equation*}
Now we show that 
$$C\cap \bigcup_{n\in\omega}\left(D_n\cap \bigcup_{i\leq n}E^\alpha_i\right)  \subseteq A_0\cap C.$$
	Indeed, 
	using the facts 
	that
    $A_{n+1}\cap \bigcup_{i\leq n}E^\alpha_i=\emptyset$ for each $n$,
    $B_\alpha\cap (\omega\setminus\bigcup_{n\in\omega}A_n)=\emptyset$
    and
$$\{a_n:n\in\omega\} = \left(\omega\setminus \bigcup_{n\in\omega}A_n\right)\cup A_0\cup  \left(\bigcup_{n\geq 1}A_n\setminus C\right),$$
	we obtain 
\begin{equation*}
\begin{split}
\bigcup_{n\in\omega}\left(D_n\cap \bigcup_{i\leq n}E^\alpha_i\right) \cap  C
	& =
\bigcup_{n\in\omega}\left((D'_n\cup \{a_n\})\cap \bigcup_{i\leq n}E^\alpha_i\right) \cap  C
\\&	=
\bigcup_{n\in\omega}\left(((A_{n+1}\cap C) \cup\{a_n\})\cap \bigcup_{i\leq n}E^\alpha_i \right) \cap  C
	\\& =
\bigcup_{n\in\omega}\left(\{a_n\} \cap \bigcup_{i\leq n}E^\alpha_i\right) \cap  C
	\\&
    \subseteq 
	\{a_n:n\in \omega\}\cap B_\alpha \cap C
	\\& =
	\left(\left(\omega\setminus \bigcup_{n\in\omega}A_n\right)\cup A_0\cup  \left(\bigcup_{n\geq 1}A_n\setminus C\right)\right)\cap B_\alpha \cap C 
    \\& = 
    A_0\cap B_\alpha\cap C. 
    	\end{split}
\end{equation*}
\end{proof}



