\section{Consistently \texorpdfstring{$\bnumber(\I)$}{b-I} is less than  \texorpdfstring{$\bnumber_{R}(\I)$}{b-R-I}}


We have either $\bnumber_{R}(\I)\leq \bnumber$ or $\bnumber_{R}(\I)=\continuum^+$ for ideals $\I$ for which the value $\bnumber_{R}(\I)$  had been estimated so far in the literature.
Moreover, it is consistent that $\bnumber_{R}(\I)<\bnumber$ for some ideal $\I$  \cite[Theorem~6.1]{MR3247032}.  
In Theorem~\ref{thm:bR-graeter-thatn-b} we show that consistently the value of $\bnumber_{R}(\I)$ can be strictly greater than $\bnumber$ and strictly less than $\continuum^+$. However, this example is cooked up with the aid of maximal ideals, so the following questions remains open.


\begin{question}
Is it consistent that there exists a \emph{Borel} ideal $\I$ such that $\bnumber(\I)<\bnumber_{R}(\I)\leq\cc$?
\end{question}


\begin{lemma}
	\label{lem:b-bR-for-I-times-empty}
	$\bnumber_{R}(\I\otimes\{\emptyset\}) = \bnumber(\I\otimes\{\emptyset\}) = \bnumber(\I)$
    for any ideal $\I$.
\end{lemma}

\begin{proof}
	The second equality is proved in \cite[Theorem~5.13]{MR4472525} and the inequality $\bnumber_{R}(\I\otimes\{\emptyset\}) \geq \bnumber(\I\otimes\{\emptyset\})$ follows from Theorem~\ref{thm:b-vs-b-inequality}.
Below, we show $\bnumber_{R}(\I\otimes\{\emptyset\}) \leq \bnumber(\I)$.

Since, $\bnumber(\I) = \bnumber(\geq_{\I}\cap (\cD_\I\times\cD_\I))$, there exists $\cF\subseteq \cD_\I$ such that $|
\cF|=\bnumber(\I)$ and for each $g\in \cD_\I$ there is $f\in \cF$ such that $f\not\geq_{\I}g$.

Define $A_n=\omega\times\{n\}$ for each $n\in \omega$ and $B_f=\{(n,k)\in \omega^2: f(n)\leq k\}$ for each $f\in \cF$.
Let $\cA = \{A_n:n\in \omega\}$ and $\cB = \{B_f:f\in \cF\}$. Once we show that $(\cA,\cB)$ is an $(\I\otimes\{\emptyset\})$-$(\omega,\bnumber(\I))$-gap, the proof will be finished.

Obviously, $|\cA|=\omega$ and $|\cB|=\bnumber(\I)$. Since $f\in D_\I$, $f^{-1}[\{n\}]\in \I$ for each $n\in \omega$.
Then 
$$A_n\cap B_f \subseteq \bigcup_{k\leq n} f^{-1}[\{k\}]\times \omega \in \I\otimes\{\emptyset\}.$$
Thus,  the pair $(\cA,\cB)$ is $\I\otimes\{\emptyset\}$-orthogonal.

Finally, we have to show that no $C$ can  $\I\otimes\{\emptyset\}$-separate the pair $(\cA,\cB)$.
Let $C\subseteq \omega\times\omega$ be such that $A_n\cap C\in \I\otimes\{\emptyset\}$ for each $n$.
Then all horizontal sections of the set $C$ belongs to $\I$ i.e.~$C^{(n)} = \{k\in \omega: (k,n)\in C\}\in \I$ for each $n$. We define $g:\omega\to\omega$ by 
$$g(i) =
\begin{cases}
i & \text{if }    i\in\omega\setminus\bigcup_{n\in\omega}C^{(n)},\\
n & \text{if } i\in C^{(n)}\setminus \bigcup_{k<n}C^{(k)}.
\end{cases}$$
Since $C^{(n)}\in\I$ for all $n$, $g\in \cD_\I$ and there is $f\in \cF$ such that $f\not\geq_\I g$.
Then $D = \{i\in \omega: f(i)< g(i)\}\notin\I$. Observe that $B_f\setminus C \supseteq \{(i,f(i)): i\in D\}$ as $\{(i,f(i)): i\in D\}\subseteq\{(i,f(i)): i\in \omega\}\subseteq B_f$ and given any $i\in D$ we have two cases:
\begin{itemize}
    \item  $i\in\omega\setminus\bigcup_{n\in\omega}C^{(n)}$, which gives us $C\cap (\{i\}\times\omega)=\emptyset$, so $(i,f(i))\notin C$, or
    \item $i\in C^{(n)}\setminus \bigcup_{k<n}C^{(k)}$ for some $n\in\omega$, which gives us $C\cap (\{i\}\times\omega)\subseteq\{(i,j): j\geq g(i)\}$, so $(i,f(i))\notin C$ by the fact that $i\in D$.
\end{itemize} 
Since $D\notin\I$, we conclude that $B_f\setminus C \supseteq \{(i,f(i)): i\in D\}\notin \I\otimes\{\emptyset\}$, so $C$ does not $\I\otimes\{\emptyset\}$-separate $(\cA,\cB)$.
\end{proof}


\begin{theorem}
	\label{thm:bR-graeter-thatn-b}\
    \begin{enumerate}
        \item If $\dnumber=\continuum$, then there exists an ideal $\I$ with 
$\bnumber(\I) = \bnumber_{R}(\I)=\cf(\dnumber)$. In particular, it is consistent that there exists an ideal $\I$ such that $\bb<\bnumber(\I)=\bnumber_{R}(\I)\leq \dd=\continuum$.
        \item It is consistent that there exists  an ideal $\I$ with $\dd<\bb(\I)=\bb_R(\I)\leq\cc$.
    \end{enumerate}
\end{theorem}

\begin{proof}
	(1)  Canjar \cite{Canjar} proved that, under $\dnumber=\continuum$, there exists a maximal P-ideal $\J$ such that $\bnumber(\J)=\cf(\dnumber)$. Then taking $\I=\J\otimes\{\emptyset\}$ and using Lemma~\ref{lem:b-bR-for-I-times-empty}, we obtain
	$\bb(\I)=\bnumber_{R}(\I)=\cf(\dnumber)$.

    (2) It is  consistent \cite[Theorem 4.2]{more-AK}  (more precisely, in the model obtained by adding $\aleph_2$ random reals to a model of GCH) that there exists an ideal $\J$ with $\dd<\bb(\J)\leq\cc$. Then $\dd<\bnumber_{R}(\J\otimes\{\emptyset\}) = \bnumber(\J\otimes\{\emptyset\}) = \bnumber(\J)\leq\cc$ by Lemma \ref{lem:b-bR-for-I-times-empty}.
\end{proof}

For ideals $\I_i$ on $X_i$ with $i\in \{0,1\}$, we define the following  ideal (called the \emph{direct sum} of $\I_0$ and $\I_1$):\label{def:direct-sum}
$$\I_0\oplus \I_1 = \{A\subseteq (X_0\times\{0\})\cup  (X_1\times\{1\}): \{x\in X_i : (x,i)\in A\} \in\I_i \text{ for $i\in \{0,1\}$}\}.$$

\begin{lemma}
\label{lem:bR-for-direct-sum}
	$\bnumber_{R}(\I\oplus\J) = \min\{\bnumber_{R}(\I),\bnumber_{R}(\J)\}$ for any ideals $\I$ and $\J$.
\end{lemma}

\begin{proof}
	$(\leq)$ 
	If $(\cA,\cB)$ is an $\I$-$(\omega,\bnumber_R(\I))$-gap, then it is not difficult to check that $(\{A\times\{0\}:A\in \cA\}, \{B\times\{0\}: B\in \cB\})$ is an $\I\oplus \J$-$(\omega,\bnumber_R(\I))$-gap. Similarly for $\J$-gaps. 

$(\geq)$
Let $(\cA,\cB)$ be an $\I\oplus\J$-$(\omega,\bnumber_R(\I\oplus\J))$-gap.
For each $A\in \cA$ and $B\in \cB$  let $A^0,A^1, B^0,B^1\subseteq \omega $ be such that $A = (A^0\times\{0\}) \cup (A^1\times\{1\})$
and
$B = (B^0\times\{0\}) \cup (B^1\times\{1\})$. Let 
$\cA^i = \{A^i:A\in \cA\}$ 
and
$\cB^i = \{B^i:B\in \cB\})$ 
for $i=0,1$. If we show that 
$(\cA^0,\cB^0)$ is an $\I$-$(\omega,|\cB^0|)$-gap 
or
$(\cA^1, \cB^1)$ is an $\J$-$(\omega,|\cB^1|)$-gap, 
the proof will be finished (as $|\cB^0|,|\cB^1|\leq \bnumber_R(\I\oplus\J)$).

Since $(A^0\cap B^0)\times \{0\} \cup (A^{1}\cap B^{1})\times\{1\} = A\cap B \in \I\oplus\J$ for each $A\in \cA$ and $B\in \cB$,
the pair $(\cA^0,\cB^0)$ is $\I$-orthogonal
and
the pair $(\cA^1,\cB^1)$ is $\J$-orthogonal.

Suppose that there exists 
$C^0\subseteq\omega$ 
which $\I$-separates 
$(\cA^0,\cB^0)$ 
and there exists 
$C^1\subseteq\omega$ 
which $\J$-separates 
$(\cA^1, \cB^1)$.
Then it is not difficult to see that $C = (C^0\times\{0\})\cup (C^1\times\{1\})$ is a set which $\I\oplus\J$-separates $(\cA,\cB)$ and yields a contradiction. Thus, either $(\cA^0,\cB^0)$ is an $\I$-gap or $(\cA^1,\cB^)1$ is a $\J$-gap. 

Notice that if $(\cA^0,\cB^0)$ is an $\I$-gap then $\cA^0$ is infinite. Indeed, if $\cA^0$ was finite, then the set $(\omega\setminus \bigcup \cA^0)\times\{0\}$ would separate $(\cA^0,\cB^0)$, a contradiction. Similarly we can show that $\cA^1$ is infinite, provided that $(\cA^1,\cB^1)$ is a $\J$-gap.
\end{proof}


\begin{lemma}
\label{lem:b-less-than-bR}
If  $\J$ and $\K$ are  two maximal ideals such that $\bnumber(\J)\leq\bnumber(\K)$, then 
$$\bb_R(\J\oplus (\K\otimes \{\emptyset\}))=\bb(\K)
\quad
\text{and} \quad 
\bb(\J\oplus (\K\otimes \{\emptyset\}))=\bb(\J).$$ 
\end{lemma}

\begin{proof}
Denote $\I=\J\oplus (\K\otimes \{\emptyset\})$. By \cite[Theorems 5.1 and 5.13]{MR4472525} we have 
\[
\bnumber(\I) 
= 
\min\{\bnumber(\J),\bnumber(\K\otimes \{\emptyset\})\} 
= 
\min\{\bnumber(\J),\bnumber(\K)\} 
= 
\bnumber(\J),\]
and by Lemmas~\ref{lem:b-bR-for-I-times-empty} and \ref{lem:bR-for-direct-sum} we have
\[\bnumber_{R}(\I) 
= 
\min\{\bnumber_{R}(\J),\bnumber_{R}(\K\otimes \{\emptyset\})\} 
= 
\min\{\continuum^+,\bnumber(\K)\} 
= 
\bnumber(\K).\]
\end{proof}

If $\I$ is a maximal ideal, then $\bnumber(\I)\leq \continuum < \continuum^+=\bnumber_{R}(\I)$. In Theorem~\ref{thm:b-less-than-bR} we show that $\bnumber(\I)<\bnumber_{R}(\I)\leq \continuum$ is also consistent.


\begin{theorem}
\label{thm:b-less-than-bR}
In the model obtained by adding $\lambda$ Cohen reals to a model of GCH, for every two regular cardinals $\kappa, \kappa'$ such that $\aleph_1\leq \kappa\leq\kappa'< \lambda=\cc$, there is an ideal $\I$ with $\bb(\I)=\kappa$ and $\bb_R(\I)=\kappa'$. In particular, the following statements are consistent:
\begin{enumerate}
    \item there exists an ideal $\I$ such that $\bb=\bnumber(\I)<\bnumber_{R}(\I)\leq \continuum$;
    \item there exists an ideal $\I$ such that $\bb<\bnumber(\I)<\bnumber_{R}(\I)\leq \continuum$.
\end{enumerate}
\end{theorem}

\begin{proof}
    By \cite{Canjar2} and \cite{CanjarPhD}, in the model obtained by adding $\lambda$ Cohen reals to a model of GCH, for every regular cardinals $\aleph_1\leq \kappa\leq\kappa'< \lambda$ there are two maximal ideals $\J$ and $\K$ such that $\bnumber(\J)=\kappa$ and $\bnumber(\K)=\kappa'$. Then Lemma \ref{lem:b-less-than-bR} finishes the proof.
\end{proof}



