\subsection{Rothberger number for ideals which are between \texorpdfstring{$\conv$}{conv} and \texorpdfstring{$\ctbl$}{ctbl}}
\label{subsec:b-R-for-CONV-CTBL}

\begin{lemma}	
	\label{lem:b-R-for-conv-and-ctbl}
	$\bnumber_{R}(\ctbl,\ctbl,\conv) \leq  \omega_1$,
where 
$$\ctbl = \{A\subseteq\Q\cap [0,1]: |\overline{A}|\leq \omega\}$$
and  the closure $\overline{A}$ is taken in the space $[0,1]$.
\end{lemma}

\begin{proof}
Let $\{U_n:n\in\omega\}$ be a countable base for the topology on $[0,1]$.
Inductively, we pick infinite sets 
$$A_n\subseteq \Q\cap \left(U_n \setminus \bigcup_{i<n}\overline{A_i}\right)$$ 
such that $\overline{A_n}$ is a perfect nowhere dense set, $\overline{A_n}\subseteq U_n$ and 
$$\overline{A_n}\cap \bigcup_{i<n}\overline{A_i}=\emptyset.$$

	For all $n\in \omega$ and $\alpha<\omega_1$, 
	we pick convergent sequences $x^{n,\alpha} : \omega\to A_n$ having  pairwise distinct limits $y^{n,\alpha}$.
	Then, we define 
    $$B_\alpha = \bigcup_{n\in \omega} \{x^{n,\alpha}(i): i\in\omega\}$$ for each $\alpha<\omega_1$.

	Let $\cA=\{A_n:n\in \omega\}$ and $\cB=\{B_\alpha:\alpha<\omega_1\}$. Once we show that $(\cA,\cB)$ is an $(\ctbl,\ctbl,\conv)$-$(\omega,\omega_1)$-gap, the proof will be finished.

	Obviously, $|\cA|=\omega$ and $|\cB|=\omega_1$.
	Since $A_n\cap B_\alpha = \{x^{n,\alpha}(i):i\in\omega\} \in \conv$ for any $n$ and $\alpha$, the families $\cA$ and $\cB$ are $\conv$-orthogonal.


	Let $C\subseteq \Q\cap [0,1]$ be such that $A_n\cap C\in \ctbl$ for each $n$.
	We need to find $\alpha$ with $B_\alpha\setminus  C\notin \ctbl$. For each $n$, since $A_n\cap C\in \ctbl$, there is $\alpha_n<\omega_1$ such that 
	$y^{n,\alpha}\notin \overline{A_n\cap C}$ for each $\alpha>\alpha_n$.
Take any countable ordinal $\alpha > \sup\{\alpha_n:n<\omega\}$.
Then $y^{n,\alpha}\notin \overline{A_n\cap C}$ for each $n$, so $x^{n,\alpha}(i)\notin C$ for all but finitely many $i\in \omega$.
Consequently, $x^{n,\alpha}(i)\in B_\alpha\setminus C$ for all but finitely many $i\in \omega$, hence $y^{n,\alpha}\in \overline{B_\alpha \setminus C}$. Since $y^{n,\alpha}\in U_n$, $\overline{B_\alpha \setminus C} = [0,1]$. Thus, $B_\alpha \setminus C\notin\ctbl$.
\end{proof}

For a countable ordinal $\alpha$, 
we have the following \emph{$\alpha$-th Cantor-Bendixson ideal} \cite{alcantara-phd-thesis}
$$\CB_{\alpha} = \{A\subseteq \Q\cap [0,1]: (\overline{A})^{(\alpha)}=\emptyset\},$$
where
 the closure $\overline{A}$ 
and the $\alpha$-th Cantor-Bendixson derivative $(\overline{A})^{(\alpha)}$  
are taken in the space $[0,1]$ (see e.g.~\cite{MR1321597}).
It is not difficult to see  that 
$\CB_{0} = \{\emptyset\}$, $\CB_{1}=\fin$, $\CB_{2}= \conv$
and 
$$\ctbl = \bigcup_{\alpha<\omega_1}\CB_{\alpha}.$$


\begin{theorem}
	\label{thm:b-for-conv-and-ctbl}
If $\conv\subseteq\I\subseteq\ctbl$, then $\bnumber(\I)=\bnumber_{R}(\I)=\omega_1$.
In particular, 
	\begin{enumerate}
		\item 
	$\bnumber(\conv) = \bnumber_{R}(\conv) = \omega_1$,
\item 	
	$\bnumber(\ctbl) = \bnumber_{R}(\ctbl) = \omega_1$,
	\item 
	$\bnumber(\CB_{\alpha}) = \bnumber_{R}(\CB_{\alpha}) = \omega_1$ for each $\alpha\geq 2$. 
\end{enumerate}
\end{theorem}

\begin{proof}
	Using Theorem~\ref{thm:b-vs-b-inequality}
	and the fact that $\bnumber(\I)\geq \omega_1$ for each $\I$ \cite[Theorem~4.2]{MR4472525}, 
	we obtain 
	$\omega_1\leq \bnumber(\I) \leq \bnumber_{R}(\I)$. Now using Lemmas~\ref{lem:monotonicity-of-b-R} and \ref{lem:b-R-for-conv-and-ctbl}, 
we obtain 
$\bnumber_{R}(\I) = \bnumber_{R}(\I,\I,\I) \leq \bnumber_{R}(\ctbl,\ctbl,\conv)\leq \omega_1$.
\end{proof}


