\subsection{Rothberger number for P-ideals}
\label{subsec:b-R-for-P-BP}

It is known \cite[Theorem~2.3(7)]{MR3247032} that $\bnumber_{R}(\I)=\bnumber$ for all analytic P-ideals. Below we extend this result to all P-ideals with the Baire property.

\begin{lemma}
\label{bR-I-F-F-for-BP-ideal}
$\bnumber_{R}(\I,\fin,\fin)=\bnumber$
for every ideal  $\I$ with the Baire property.
\end{lemma}

\begin{proof}
	By Lemma~\ref{lem:monotonicity-of-b-R}, we have $\bnumber =\bnumber_{R}(\fin,\fin,\fin)\leq \bnumber_{R}(\I,\fin,\fin)$. We will show that $\bnumber_{R}(\I,\fin,\fin)\leq\bnumber$ for ideals $\I$ with the Baire property.

	Since $\I$ has the Baire property,
	there exists a sequence $m_1<m_2<\dots$ such that 
	if there are infinitely many $k$ with $[m_k,m_{k+1})\subseteq A$, then $A\notin \I$
\cite[Th\'{e}or\`{e}me 21]{MR579439} (see also \cite[Theorem 4.1.2]{MR1350295}).

	Take any partition $\{D_n:n\in \omega\}$ of $\omega$ into infinite sets and any unbounded family $\{f_\alpha:\alpha<\bnumber\}$ in $(\omega,\leq^*)$.

	Define 
	$$A_n = \bigcup_{k\in D_n}[m_k,m_{k+1}) \ \ \ \text{and} \  \ \  
	B_\alpha = \bigcup_{n\in \omega} \bigcup_{k\in D_n\cap f_\alpha(n)} [m_k,m_{k+1})$$
	for each $n\in \omega$ and $\alpha<\bnumber$.

	Let $\cA=\{A_n:n\in \omega\}$ and $\cB=\{B_\alpha:\alpha<\bnumber\}$.
	Once we show that $(\cA,\cB)$ is an $(\I,\fin,\fin)$-$(\omega,\kappa)$-gap  with some $\kappa\leq \bnumber$, the proof will be finished.

	Using the fact that $D_n$ are pairwise disjoint, we see that $|\cA|=\omega$.
	Obviously, $|\cB|\leq \bnumber$. Moreover, for any $n$ and $\alpha$, 
    $$A_n\cap B_\alpha = \bigcup_{k\in D_n\cap f_\alpha(n)} [m_k,m_{k+1}) \in \fin.$$ 
    Thus $\cA$ and $\cB$ are $\fin$-orthogonal. 

	Finally, take any $C\subseteq\omega$ such that $A_n\cap C\in \fin$ for each $n$. We need to find $\alpha$ such that $B_\alpha\setminus C\notin\I$. Let $f:\omega\to\omega$ be defined by
	$$f(n)= \min\{k\in D_n: (A_n\cap C) \cap [m_k,m_{k+1})=\emptyset\}.$$
	Let $\alpha<\bnumber$ be such that the set $E = \{n\in \omega: f(n)<f_\alpha(n)\}$ is infinite. Then $[m_{f(n)}, m_{f(n)+1}) \subseteq B_\alpha \setminus (A_n\cap C)$ for each $n\in E$.
	Since $[m_{f(n)}, m_{f(n)+1}) \subseteq A_n$, 
	$[m_{f(n)}, m_{f(n)+1}) \subseteq B_\alpha \setminus C$ for each $n\in E$.
	Consequently, $B_\alpha \setminus C \notin \I$.
\end{proof}

\begin{lemma}
\label{lem:inequality_for_P-ideals}
    $\bb_R(\I)\leq\bb(\I,\fin,\fin)$ 
    for each P-ideal $\I$.
\end{lemma}

\begin{proof}
    By Lemma \ref{lem:monotonicity-of-b-R}, $\bb_R(\I)\leq\bb_R(\I,\I,\fin)$. To finish the proof, we will show that $\bb_R(\I,\I,\fin)\leq\bb_R(\I,\fin,\fin)$ for every P-ideal $\I$. 

    Let $(\cA,\cB)$ be an $(\I,\fin,\fin)$-$(\omega,\bnumber_{R}(\I,\fin,\fin))$-gap. Then $\cA$ and $\cB$ are $\fin$-orthogonal. Take any $C\subseteq\omega$ such that $A\cap C\in \I$ for all $A\in \cA$. Since $\I$ is a P-ideal and $\cA$ is countable, there exists $D\in \I$ such that $(A\cap C)\setminus D\in \fin$ for each $A\in \cA$. Let $C' = C\setminus D$. Since $A\cap C' \in\fin$ for each $A\in \cA$, there exists $B\in \cB$ with $B\setminus C'\notin\I$. Then $B\setminus C=(B\setminus C')\setminus D\notin\I$ (as $D\in\I$), so $C$ does not $(\I,\I)$-separate $(\cA,\cB)$.
\end{proof}

\begin{theorem}
\label{thm:all-ideal-b-equals-b-for-BP-ideals}
$\bb_R(\I)=\bb(\I)=\bb$
for each P-ideal $\I$ with the Baire property.
\end{theorem}

\begin{proof}
The inequality $\bb_R(\I)\leq\bb$ follows from Lemmas~\ref{bR-I-F-F-for-BP-ideal} and \ref{lem:inequality_for_P-ideals}. The inequalities $\bb_R(\I)\geq\bb(\I)\geq\bb$ follow from Theorem \ref{thm:b-vs-b-inequality} and the fact that $\bb(\I)\geq\bb$ for P-ideals \cite[Theorem 4.5]{MR4472525}.
\end{proof}


