\begin{lemma}
Let $\Lambda$ and $\Gamma$ be separably equivalent defined by $_{\Lambda}M_\Gamma$ and $_\Gamma N_\Lambda$. 
For any $L\in$ Mod $\Gamma$, one has

(1) If $L\in$ $^{\bot}(\T_{M}(\Prod C^{+}))$, then $L\in$ $^{\bot}(\Prod \T_{M}(C^{+}))$.

(2) If $L\in$ $\mathrm{cores} (\widetilde{\T_{M}(\Prod C^{+})})$, then $L\in$ $\mathrm{cores}( \widetilde{\Prod \T_{M}(C^{+})})$.
\end{lemma}

\begin{proof}
Since $M_\Gamma$ is finitely generated projective, then 
$\T_{M}$ commutes with direct products and
$\T_{M}(\Prod C^{+})\subseteq$ $\Prod \T_{M}(C^{+})$.
By a similar argument of Lemma 3.8, one gets the assertion.
\end{proof}

\begin{proposition}
Let $_{\Lambda}C$ be a Wakamatsu tilting module with $\Gamma = \End(_{\Lambda}C)$,
and suppose that $\Lambda$ and $\Gamma$ are separably equivalent defined by 
$_{\Lambda}M_\Gamma$ and $_\Gamma N_\Lambda$ with  an adjoint pair $(-\otimes_{\Lambda}M, -\otimes_{\Gamma}N)$.

$(1)$ If $H\in$ $\mathscr{A}_{C}(\Gamma)$, then $\T_{M}(H) \in$ $\mathscr{A}_{C\otimes_{\Gamma}N}(\Lambda)$.

$(2)$ If $G\in$ $\mathcal{GI}_{C}(\Gamma)$, then $\T_{M}(G) \in$ $\mathcal{GI}_{C\otimes_{\Gamma}N}(\Lambda)$.
\end{proposition}

\begin{proof} 
(1) Let $H\in$ $\mathscr{A}_{C}(\Gamma)$.
From Remark 2.6(2) we know that $\mathscr{A}_{C}(\Gamma) = $ $r\mathcal{G}(\Prod C^{+})$.
Thus $\T_{M}(H)\in$ $r\mathcal{G}(\T_{M}(\Prod C^{+}))$ by Theorem 3.3(1).
From Lemma 3.11, one has $r\mathcal{G}(\T_{M}($ $\Prod C^{+}))$
$\subseteq$ $r\mathcal{G}(\Prod \T_{M}(C^{+}))$.

Because $(-\otimes_{\Lambda}M, -\otimes_{\Gamma}N)$ is an adjoint pair,
$\T_{M}(C^{+})\cong(\Hom_{\Gamma^{op}}(M, C))^{+}$ $\cong$ $(C\otimes_{\Gamma}N)^{+}$.
Note that $C_{\Gamma}$ is Wakamatsu tilting from \cite[Corollary 3.2]{Wa}, 
it follows from Proposition 3.9 that $C\otimes_{\Gamma}N$ is a Wakamatsu tilting right $\Lambda$-module.
Therefore, $\T_{M}(H)\in$ $r\mathcal{G}(\Prod (C\otimes_{\Gamma}N)^{+})$ $=\mathscr{A}_{C\otimes_{\Gamma}N}(\Lambda)$.

(2) Note that $\mathcal{GI}_{C}(\Gamma) = $ $l\mathcal{G}(\Prod C^{+})$.
The proof is similar to (1) by using the dual result of Lemma 3.11.
\end{proof} 


