\title{Chiral superconductivity in a semiconducting wire induced by helical magnetic order}
\author{Florinda Vi\~nas Bostr\"om}
\email{florinda.bostrom@nbi.ku.dk}
\affiliation{Center for Quantum Devices, Niels Bohr Institute, University of Copenhagen, DK-2100 Copenhagen, Denmark}
