\section*{End Matter}

\subsection{Superconducting gap in the band basis}\label{app:gap_rotation}
The corresponding eigenstates of the energies $\epsilon_{ks}$ are found by a rotation of the original basis,
\begin{align}\label{eq:transform}
  \begin{pmatrix} d_{kd} \\ d_{ku} \end{pmatrix} =
  \begin{pmatrix} \phantom{-} \cos\frac{\theta_k}{2} & \sin\frac{\theta_k}{2} \\ -\sin\frac{\theta_k}{2} & \cos\frac{\theta_k}{2} \end{pmatrix} \begin{pmatrix} c_{k-\frac{q}{2},\uparrow} \\ c_{k+\frac{q}{2},\downarrow} \end{pmatrix},
\end{align}
with the inverse transformation given by
\begin{align}\label{eq:inv_transform}
 \begin{pmatrix} c_{k\uparrow} \\ c_{k\downarrow} \end{pmatrix} =
 \begin{pmatrix} \cos\frac{\theta_{k+q/2}}{2} d_{k+\frac{q}{2},d} -\sin\frac{\theta_{k+q/2}}{2} d_{k+\frac{q}{2},u} \\ \sin\frac{\theta_{k-q/2}}{2} d_{k-\frac{q}{2},d} + \cos\frac{\theta_{k-q/2}}{2} d_{k-\frac{q}{2},u} \end{pmatrix}.
\end{align}
Here, the rotation angle $\theta_k$ is implicitly defined via the relations
\begin{subequations}
 \begin{align}
  \sin\theta_k &= \frac{2gS}{\sqrt{(\epsilon_{k+q/2}-\epsilon_{k-q/2})^2+4g^2S^2}} \\
  \cos\theta_k &= \frac{\epsilon_{k+q/2}-\epsilon_{k-q/2}}{\sqrt{(\epsilon_{k+q/2}-\epsilon_{k-q/2})^2+4g^2S^2}}.
\end{align}
\end{subequations}
Using the transformations above, we can write the electronic Hamiltonian as
\begin{align}
 H_e &= \sum_{ks} \epsilon_{ks} \hat{d}_{ks}^\dagger \hat{d}_{ks} - \Delta_0 \sum_{k} (\hat{c}_{k\uparrow}^\dagger \hat{c}_{-k,\downarrow}^\dagger + \hat{c}_{k\uparrow} \hat{c}_{-k,\downarrow}) \nonumber
\end{align}
To transform the last term, we use the rotation in Eq.~\ref{eq:inv_transform}, and make use of the fact that sum is over all $k$, such that we can relabel the summation index as $k' = k + q/2$. We then find
\begin{align}
 &\sum_{k} c_{k\uparrow} c_{-k,\downarrow} = \sum_{k} \bigg( \cos\frac{\theta_{k}}{2} \sin\frac{\theta_{-k}}{2} d_{kd} d_{-kd} \\
 &\hspace*{0.2cm}+ \cos\frac{\theta_{k}}{2} \cos\frac{\theta_{-k}}{2} d_{kd} d_{-ku} - \sin\frac{\theta_{k}}{2} \sin\frac{\theta_{-k}}{2} d_{ku} d_{-kd} \nonumber \\
 &\hspace*{0.2cm}- \sin\frac{\theta_{k}}{2} \cos\frac{\theta_{-k}}{2} d_{ku} d_{-ku} \bigg), \nonumber
\end{align}
and similarly for the complex conjugate.



%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%



\subsection{Bulk topology}\label{app:bulk_topology}
A bulk topological index can be defined from the Pfaffian of the Hamiltonian $H$, evaluated at the time-reversal invariant momenta $q = 0$ and $q = \pi/a$. It is given by $Z = \sign (\pf [H(0)] \pf [H(\pi/a)])$. To calculate the index, we note that the Pfaffian of a general $4\times 4$ skew-symmetric matrix (satisfying $A^T = -A$) can be written as $\pf(A) = af - be + dc$, provided that 
\begin{align}
 A = \begin{pmatrix} 0 &  a & b & c \\ -a &  0 &  d & e \\
                    -b & -d & 0 & f \\ -c & -e & -f & 0
     \end{pmatrix}.
\end{align}

To evaluate the topological index, we want to transform the BdG Hamiltonian into a skew-symmetric form. This is achieved by the unitary transformation
\begin{align}
 \tilde{\mathcal{H}}_e &= \frac{1}{2} \begin{pmatrix} 1 & 1 \\ i & -i \end{pmatrix}
 \begin{pmatrix} h - \mu & \Delta \\ \Delta &  \mu - h \end{pmatrix}
 \begin{pmatrix} 1 & -i \\ 1 & i \end{pmatrix} \\
 &= \begin{pmatrix} 0 & i\Delta - ih + i\mu \\ i\Delta + ih - i\mu &  0 \end{pmatrix}. \nonumber
\end{align}
This is skew-symmetric since $\Delta^T = -\Delta$, which follows from the anticommutation relations of fermionic operators and the fact that the $s$-wave ($p$-wave) gaps are even (odd) function of momentum. Writing the transformed Hamiltonian in detail, it has the form
\begin{align}
 \tilde{\mathcal{H}}_e &= \begin{pmatrix}
                   0 & 0 & i\mu - i\epsilon_{kd} & i\Delta_s \\
                   0 & 0 & -i\Delta_s & i\mu - i\epsilon_{ku} \\
                   i\epsilon_{kd} - i\mu & -i\Delta_s & 0 & 0 \\
                   i\Delta_s & i\epsilon_{ku} - i\mu & 0 & 0
                  \end{pmatrix}.
\end{align}
Here, since we are only interested in the Hamiltonian at $k = 0$ and $k = \pi/a$, we have neglected the triplet gaps that vanish at these points. The Pfaffian is now given by $\pf[H(k)] = (\epsilon_{kd} - \mu)(\epsilon_{ku} - \mu) - \Delta_s^2$, and the topological index by
\begin{align}
 Z &= \sign( [(\epsilon_d(0) - \mu)(\epsilon_u(0) - \mu) - \Delta_s^2] \\
 &\hspace*{0.7cm} \times [(\epsilon_d(\pi/a) - \mu)(\epsilon_u(\pi/a) - \mu) - \Delta_s^2] ) \nonumber
\end{align}
This is illustrated as a function of chemical potential $\mu = \epsilon_F$ in Fig.~\ref{fig:topology}c.

Noting that for small doping, where the Fermi level is close to the bottom of the bands, only the first term of the topological index is relevant, we can solve for the chemical potential corresponding to the topological transition. This gives
\begin{align}
 \mu = \frac{\epsilon_d(0) + \epsilon_u(0)}{2} \pm \frac{1}{2} \sqrt{(\epsilon_d(0) - \epsilon_u(0))^2 + 4\Delta^2}.
\end{align}
In the high-doping limit, where the Fermi level is closer to the top of the bands, we can similarly solve for the zeroes of the second term, to get
\begin{align}
 \mu = \frac{\epsilon_d(\frac{\pi}{a}) + \epsilon_u(\frac{\pi}{a})}{2} \pm \frac{1}{2} \sqrt{(\epsilon_d(\frac{\pi}{a}) - \epsilon_u(\frac{\pi}{a}))^2 + 4\Delta^2}.
\end{align}
These results agree very well with the boundaries of the region of chemical potentials where zero modes are found numerically, as shown in Fig.~\ref{fig:topology}.



