\medskip
\section{\large Preliminaries}\label{sec-2}

	In the section, we recall the all the necessary definitions and notions related to operads and graded operads, that we use throughout this article.  

	\begin{definition}
		\label{S-module}
		An {\bf $\Sm$-module}  over $\K$ is a family 
		$\p = (\p(0),\p(1),\ldots,\p(n),\ldots)$	
		of right $\K[\Sm_n]$-modules $\p(n)$. The \textbf{tensor product} of two $\Sm$-modules $\p$ and $\q$ is given by 
		\begin{equation*}
			\p \otimes \q(n) := \bigoplus_{i+j=n} \p(i) \otimes \q(j) \otimes \K[Sh(i,j)]
		\end{equation*}
		where $Sh(i,j)$ denotes the set of all $(i,j)$-shuffles of $\Sm_n$. The category of $\Sm$-modules, denoted by $\Sm$-mod, forms a monoidal category given by the following \textbf{composition product} 
		\begin{equation*}
			\p \circ \q (n) := \bigoplus_{k \ge 0} \p(k) \otimes_{\Sm_k} \q^{\otimes k}
		\end{equation*}
		The notation $\q^{\otimes k}$ denotes the tensor product of $k$ copies of the $\Sm$-module $\q$. The unit for the composition is given by $\I=(0,\K,0,\cdots)$. 
		See \cite[Section 5.1, pg 123]{Loday-Vallette} for further details regarding $\Sm$-modules and their products.   

	\end{definition}

	\begin{definition}[\bf Monoidal Definition]\label{monoidal_def}
		An {\bf operad} $\mathcal{P}$ is a monoid in the monoidal category of $\Sm$-modules. More precisely, it is an $\Sm$-module $\p= \{\p(n)\}_{n \ge 0}$ endowed with a morphisms of $\Sm$-module 
		\begin{equation*}
			\gamma: \p \circ \p \to \p 
		 	\quad \text{and} \quad 
		 	\eta: \I \to \p
		\end{equation*} 
		called composition map and unit map respectively, which makes $\p$ into a monoid. 
		For a more detailed description of the monoidal definition we refer the readers to \cite[Section 5.2.1, pg 131]{Loday-Vallette}. 
	\end{definition}

	There are several other equivalent definitions of an operad, including the classical, combinatorial, and partial definitions. We describe the partial definition below, while the classical and combinatorial definitions can be found in \cite[pg 142 and pg 161]{Loday-Vallette}, respectively.

	\begin{definition}[\bf Partial Definition]\label{partial_def}
		An {\bf operad} $\p$ is a sequence $\{\p(n)\}_{n \in \mathbb{N}}$ of vector spaces, together with partial composition maps
		\begin{equation*}
			\circ_i : \p(m) \times \p(n) \rightarrow \p(m-1+n)
		\end{equation*}
		for $1 \leq i \leq m$ and $n \geq 0$, along with a unit element $\mathbbm{1} \in \p(1)$ satisfying the following conditions
		\begin{itemize}
			\item (Associativity) for all $\mu \in \p(m)$, $\nu \in \p(n)$, and $\eta \in \p(r)$

			\begin{equation}
				(\mu \circ_i \nu) \circ_j \eta = 
				\begin{cases}
					\begin{array}{ll}
					(\mu \circ_j \eta) \circ_{i+j-1} \nu \quad &1 \le j \le i-1, \\ 
					\mu \circ_i (\nu \circ_{j-i+1} \eta) \quad &i \le j \le m+i-1, \\
					(\mu \circ_{j-m+1} \eta) \circ_i \nu \quad &m+i \le j \le m-1+n.
					\end{array}
 				\end{cases}
			\end{equation}
			\smallskip
			\item (Equivariance) Each $\p(n)$ has a right action of $\Sm_n$, $\cdot:\p(n) \times \Sm_n \to \p(n)$, denoted by $(\mu,\sigma) \mapsto \mu \cdot \sigma$, such that for all $\mu \in \p(n)$, $\nu \in \p(m)$ and $\sigma \in \Sm_n$, $\tau \in \Sm_m$
			\begin{equation}
				(\mu\cdot \sigma) \circ_i (\nu \cdot \tau)= (\mu \circ_i\nu)\cdot (\sigma \circ_i \tau)
			\end{equation}
			where $\sigma \circ_i \tau$ is the block permutation, with the $i^{th}$ entry of $\sigma$ being replaced by the entire block $\tau$.  
			\smallskip
			\item (Unitality) There exists a unique element $\mathbbm{1} \in \p(1)$ such that $\mu \in \p(n)$ $(\text{with}~n \ge 1)$, and $1 \le i \le n$,
			\begin{equation}
				\mu \circ_i \mathbbm{1} ~=~ \mu ~=~ \mathbbm{1} \circ_1 \mu.
			\end{equation}
		\end{itemize}
		A pictorial description of the above mentioned conditions can be found in \cite[Section 5.3.4, pg 146]{Loday-Vallette}.
	\end{definition}

	Let us consider a fundamental example to illustrate the basic idea of operads: the endomorphism operad, associated with a given vector space serves as a key example to understand the operadic composition. 

	\begin{example}[\bf Endomorphism operad]\label{ExEnd}
		For any vector space $\fa$, the endomorphism operad $\mathrm{End}_\fa$ is given by
		\begin{equation}
			\mathrm{End}_\fa(n) := \mathrm{Hom}(\fa^{\otimes n},\fa) \quad \text{for all}~ n \ge 0,
		\end{equation}
		where $\fa^{\otimes n}$ denotes the $n$-fold tensor product of $\fa$, and by convention $\fa^{\otimes 0} = \K$. The partial composition maps given by $\circ_i: \mathrm{Hom}(\fa^{\otimes n}, \fa) \times \mathrm{Hom}(\fa^{\otimes m},\fa) \to \mathrm{Hom}(\fa^{\otimes m-1+n},\fa)$ are defined as follows: 	
		\begin{equation}\label{def_partial_comp_end_operad}
			f \circ_i g (a_1,\ldots, a_{m-1+n}) := f(a_1, \ldots,a_{i-1}, g(a_i,\ldots,a_{i+m-1}), a_{i+m},\ldots, a_{m-1+n})
		\end{equation}
		for all $a_1,\ldots,a_{m-1+n} \in \fa$. The right action $\cdot: \mathrm{Hom}(\fa^{\otimes n}, \fa) \times \Sm_n \to \mathrm{Hom}(\fa^{\otimes n}, \fa)$ is given by 
		\begin{equation}\label{def_end_opd_sym_action}
			(f \cdot \sigma) (a_1,\ldots,a_{n}) := f(a_{\sigma(1)},\ldots,a_{\sigma(n)})  
		\end{equation}
		and the unit element $\mathbbm{1}$ is the identity map $\mathrm{id}_\fa \in \mathrm{End}_\fa(1)$. 
	\end{example}

	\begin{example}\label{com}
		Consider a constant sequence of the field $\K$ as follows:   
		\begin{equation*}
			Com(n) := \mathbb{K} \quad \text{for all } n \ge 0.
		\end{equation*}
		together with partial compositions, $\mathbb{S}_n$ right action, and unit element described below. 

		\medskip\noindent 
		{\it Partial composition:} For any $a \in Com(m) = \mathbb{K}$ and $b \in Com(n)= \mathbb{K}$ define 
		\begin{equation*} \label{Com_circle_product}
			a \circ_{i} b := ab \quad \text{for all}~ 1 \le i \le m.
		\end{equation*}
		(the usual multiplication of $\mathbb{K}$). 
		The associativity of the partial composition maps follows from the associativity and commutativity of the multiplication in $\mathbb{K}$.

		\medskip \noindent
		{\it $\mathbb{S}_n$ action on $Com(n)$:}
		The right action of $\mathbb{S}_n$ on $Com(n)$ is assumed to be trivial for each $n \ge 1$, i.e., for any $\sigma \in \mathbb{S}_n$ and $f \in Com(n)$; $f \cdot \sigma = f$.

		\medskip \noindent
		{\it Unit element:}
		For any $n \ge 1$ let $1_{\mathbb{K}}^{(n)} \in Com(n) = \mathbb{K}$ denote the multiplicative identity of $Com(n) = \mathbb{K}$. 
		With this notation $1_{\mathbb{K}}^{(1)}$ is the unit element in $\mathcal{C}om$.	
		Thus, making $\mathcal{C}om$ an operad.
	\end{example}

	Next, we give an example of an operad $\p$ in which all the spaces $\p(n)$ are equal to a fixed vector space $V$.

	\begin{example}\label{exm_V}
		Let $V$ be a vector space with a basis being given by the set $\{b_1,\ldots,b_p\} = B$. Now, we consider the following sequence of vector spaces: 
		\begin{equation}
			\p(n) := \mathrm{Hom}(B,\K) \cong V \quad \text{for any } n \ge 0,
		\end{equation} 
		where $\mathrm{Hom}(B,\K)$ denotes the vector space consisting of all set maps from $B$ to $\K$. We define the partial composition, $\mathbb{S}_n$ right action on $\p(n)$, and the unit element as follows:

		\medskip\noindent 
		{\it Partial composition:} For any $f \in \p(m) = \mathrm{Hom}(B,\K)$ and $g \in \p(n)= \mathrm{Hom}(B,\K)$ we define 
		\begin{equation*} \label{Com_circle_product}
			f \circ_{i} g := f \cdot g \quad \text{for all}~ 1 \le i \le m,
		\end{equation*}
		where $f \cdot g$ is defined pointwise using the multiplication defined on $\mathbb{K}$. 
		We note that the associativity of the partial composition maps follows from the associativity and commutativity of the multiplication in $\mathbb{K}$.

		\medskip \noindent
		{\it $\mathbb{S}_n$ action on $\p(n)$:}
		The right action of $\mathbb{S}_n$ on $\p(n)$ is assumed to be trivial for each $n \ge 1$, i.e., for any $\sigma \in \mathbb{S}_n$ and $f \in \p(n)$; $f \cdot \sigma = f$.

		\medskip \noindent
		{\it Unit element:}
		Considering the constant map $\mathbbm{1}: B \to \K$, defined as $\mathbbm{1}(b) := 1_\K$ for all $b \in B$, we note that $\mathbbm{1} \in \p(1)$ acts as the the unit element in $\p$.	
		Thus, turning $\p$ into an operad.
	\end{example}

	\begin{example}\label{ass}
		Consider a sequence of vector spaces over $\K$ as follows: 
		\begin{equation} \label{def_Ass}
			Ass(n) := 
			\begin{cases}
				0 \quad \qquad n = 0, \\
				\mathbb{K} ~\quad \quad n=1, \\
				\mathbb{K}[\mathbb{S}_n] \quad n \ge 2.
			\end{cases}
		\end{equation}
		along with  partial compositions, $\mathbb{S}_n$ right action, and unit element described below.

		\medskip\noindent
		{\it Partial composition:} 
		Let $\sigma \in \mathbb{K}[\mathbb{S}_n]$ and $\tau \in \mathbb{K}[\mathbb{S}_m]$ be two basis elements. Define 
		\begin{equation*}
			\sigma \circ_i \tau := \text{The block 	permutation, where the} ~i^{th}~ \text{entry of} ~\sigma~ \text{is replaced by the entire block} ~\tau,	
		\end{equation*} 
		then extend it linearly to whole of $\mathbb{K}[\mathbb{S}_n]$ and $\mathbb{K}[\mathbb{S}_m]$.

		\medskip\noindent 
		{\it $\mathbb{S}_n$ action on $Ass(n)$:} 
		The right action of $\mathbb{S}_n$ on $Ass(n) = \mathbb{K}[\mathbb{S}_n]$ is the regular action that is defined as follows. For any basis element $\sigma \in \mathbb{K}[\mathbb{S}_n]$ and $\tau \in \mathbb{S}_n$, defining $\sigma \tau := \sigma \cdot \tau$ (group multiplication of $\mathbb{S}_n$), and then extending it linearly to whole $\mathbb{K}[\mathbb{S}_n]$ gives us the $\mathbb{S}_n$ right action on $\mathbb{K}[\mathbb{S}_n]$. 

		\medskip\noindent
		{\it Unit element:} 
		$1 \in \mathbb{K} = Ass(1)$ is the unit element of $Ass$. Thus, making $\mathcal{A}ss$ an operad.  
	\end{example}

	For more examples of operads, we refer the reader to \cite{Apurba-Da}, where a comprehensive list of examples along with detailed descriptions can be found.

	\begin{definition}
		Let $\mathcal{P} = \{\mathcal{P}(n) : n \ge 0\}$ and $\mathcal{Q} = \{\mathcal{Q}(n) : n \ge 0\}$ be two operads. A {\bf morphism of operads} $\gamma: \mathcal{P} \to \mathcal{Q}$ consists of a sequence of linear maps $\gamma_n : \mathcal{P}(n) \to \mathcal{Q}(n)$ for all $n \ge 0$ such that 
		\begin{equation} \label{morphism_unital_cond}
			\gamma_1 (\mathbbm{1}_{\mathcal{P}}) = \mathbbm{1}_{\mathcal{Q}}
		\end{equation}
		and for all $n,m \ge 1$ and $\sigma \in \mathbb{S}_n$ the following diagrams commute.
		\begin{equation} \label{morphism_diagram}
			\begin{tikzcd}
				{\mathcal{P}(n) \times \mathcal{P}(m)} & {\mathcal{P}(m-1+n)} &&& {\mathcal{P}(n)} & {\mathcal{P}(n)} \\
				{\mathcal{Q}(n) \otimes \mathcal{Q}(m)} & {\mathcal{Q}(m-1+n)} &&& {\mathcal{Q}(n)} & {\mathcal{Q}(n)}
				\arrow["{\circ_i}", from=1-1, to=1-2]
				\arrow["{\circ_i}", from=2-1, to=2-2]
				\arrow["{\gamma_n \otimes \gamma_m}"', from=1-1, to=2-1]
				\arrow["{\gamma_{m-1+n}}", from=1-2, to=2-2]
				\arrow["\sigma", from=1-5, to=1-6]
				\arrow["\sigma", from=2-5, to=2-6]
				\arrow["{\gamma_n}"', from=1-5, to=2-5]
				\arrow["{\gamma_n}", from=1-6, to=2-6]
			\end{tikzcd}
		\end{equation}
	\end{definition}

	\begin{definition}
		A {\bf $\p$-algebra} is a vector space $\fa$ along with a morphism of operads $\gamma: \mathcal{P} \to \mathrm{End}_\fa$. Let $\fa$ and $\mathfrak{b}$ be two $\p$-algebras with the $\p$-algebra structures given by $\gamma: \p \to \mathrm{End}_\fa$ and $\widetilde{\gamma}:\p \to \mathrm{End}_\mathfrak{b}$, respectively. A {\bf $\p$-algebra morphism} from $\fa$ to $\mathfrak{b}$ is a linear map $f: \fa \to \mathfrak{b}$  such that for any $n \in \mathbb{N}$ and $\mu \in \p(n)$ 
		\begin{equation}
			f\big(\gamma_n(\mu)(a_{1},\ldots,a_{n})\big) = \widetilde{\gamma}_n(\mu)(f(a_{1}),\ldots,f(a_{n})).   
		\end{equation}
		Equivalently, the following diagram commutes for any $k \in \mathbb{N}$ and $\mu \in \p(k)$
		\begin{equation*}
			\begin{tikzcd}
				{\mathfrak{a}^{\otimes k}} & {\mathfrak{a}} \\
				{\mathfrak{b}^{\otimes k}} & {\mathfrak{b}}
				\arrow["{\gamma_k}", from=1-1, to=1-2]
				\arrow["{f^{\otimes k}}"', from=1-1, to=2-1]
				\arrow["f", from=1-2, to=2-2]
				\arrow["{\widetilde{\gamma}_k}", from=2-1, to=2-2]
			\end{tikzcd}
		\end{equation*}
		An equivalent definition of $\p$-algebras, using the language of category theory, can be found in \cite[Section 5.3.4, pg 146]{Loday-Vallette}.
	\end{definition}

	\begin{remark}
		Any algebra over the operad $\mathcal{C}om$ (see Example \ref{com}) is a commutative and associative algebra. 
		In contrast, an algebra over the operad described in Example \ref{exm_V} is a vector space endowed with $p$ distinct binary operations, each of which is commutative and associative, but with no imposed compatibility conditions between them. 
		Finally, an algebra over the operad $\mathcal{A}ss$ (see Example \ref{ass}) is an associative algebra.
	\end{remark}

	\begin{definition}
		Let $M$ be an $\Sm$-module. The \textbf{free operad} over the $\Sm$-module $M$ is an operad $\T(M)$ equipped with an $\Sm$-module morphism $\eta(M): M \to \T(M)$ which satisfies the following universal property:
		Any $\Sm$-module morphism $f: M \to \p$, where $\p$ is an operad, extends uniquely into an operad morphism $\widetilde{f}: \T(M) \to \p$ such that the following diagram commutes
		\begin{equation*}
			\begin{tikzcd}
				M & {\T(M)} \\
				& \p
				\arrow["{\eta(M)}", from=1-1, to=1-2]
				\arrow["f"', from=1-1, to=2-2]
				\arrow["{\widetilde{f}}", from=1-2, to=2-2]
			\end{tikzcd}
		\end{equation*}
		In other words, the functor $\T: \Sm$-mod $\to \Op$ is left adjoint to the forgetful functor $\Op \to \Sm$-mod, where $\Op$ denotes the category of operads over $\K$. An explicit construction of the free operad $\T(M)$ is described as follows: 
		\begin{equation}
			\T(M)(n) := \bigoplus_{t \in RT(n)} M(t),
		\end{equation}
		where $RT(n)$ denotes the set of all rooted trees with $n$ leaves such that each vertex has atleast one input. And $M(t)$ denotes the tree wise tensor product, for a detailed description of $M(t)$ see \cite[Section 5.6.1, pg 160]{Loday-Vallette}. 
	\end{definition}

	We illustrate this construction by considering a specific example, primarily highlighting the structure of a binary quadratic operad. 	

	\begin{example}\label{EXAMPLE}
		Let $E$ be a right $\Sm_2$-module. Consider the binary quadratic $\Sm$-module $\overline{E} := (0,0,E,0,0, \ldots)$.
		We denote the free operad over $\overline{E}$ by $\mathbb{T}(E)$ instead of $\mathbb{T}(\overline{E})$. We now describe a way to construct $T(E)(n)$, for each $n \in \mathbb{N}$. The non-trivial summands of $\T(E)(n)$ can be identified with a collection of subsets $S \subseteq \{1,2,\ldots,n\}$ which satisfies the following properties:  
		\begin{itemize}
			\item Each $S$ in the collection has cardinality greater than $1$, 

			\item The collection includes $\{1,2,\ldots,n\}$, and 

			\item For subsets $S, S'$ belonging to the collection, either $S \subseteq S'$ or $S' \subseteq S$ or $S \cap S' = \emptyset$. 
		\end{itemize}

		One may think of each $S$ in the collection as the set of leaves lying above a given vertex in the tree (and in this situation each vertex of the tree is uniquely determined by the set of leaves above it). So for the set $\{1,2,3\}$ there are four possibilities:
 		\begin{equation*}
 			\lbrace \lbrace 1, 2\rbrace, \lbrace 1, 2, 3\rbrace\rbrace, \quad \lbrace \lbrace 1, 3\rbrace, \lbrace 1, 2, 3\rbrace\rbrace, \quad \lbrace \lbrace 2, 3 \rbrace, \lbrace 1, 2, 3\rbrace\rbrace, \quad \lbrace\lbrace 1, 2, 3\rbrace\rbrace.
 		\end{equation*}
 		The last possibility indexes a trivial summand (because $\overline{E}(3)=0$), so that just leaves the first three, where the treewise tensor products are each isomorphic to $E \otimes E$.
		The first four terms of $\mathbb{T}(E)$ are described below:
		\begin{equation*}
			\T(E)(0) \cong 0, \quad \T(E) (1) \cong \K, \quad \T(E)(2) \cong E, \quad \T(E) (3) \cong 3 (E \otimes E), \quad \T(E) (4) \cong 15 (E \otimes E \otimes E)
		\end{equation*}
		where $k(E \otimes \cdots \otimes E)$ means direct sum of $k$ copies of $E \otimes \cdots \otimes E$. 
	\end{example}

	Having established the foundational concepts and examples related to operads, we now consider the graded context. While many of the definitions and constructions carry over, we present them briefly, focusing on the key changes needed for graded operads.

	\begin{definition}[\textnormal{\cite[Section 6.2.1, pg 197]{Loday-Vallette}}]
		A {\bf graded $\Sm$-module} $\g$ over $\K$ is a family 
		$\g = (\g(0),\g(1),\ldots,\g(n),\ldots)$
		of graded vector spaces over $\K$ equipped with a graded right $\K[\Sm_n]$-module structure. Analogous to the category $\Sm$-mod, one can show that the category g$\Sm$-mod of graded $\Sm$-modules over $\K$ also forms a monoidal category.
	\end{definition}

	\begin{definition}
		A {\bf graded operad $\g$} is a monoid in the monoidal category g$\Sm$-mod of graded $\Sm$-modules. For further details we refer the readers to \cite[Section 6.3.1, pg 199]{Loday-Vallette}.  
	\end{definition}

	Building on the partial definition of operads in Definition \ref{partial_def}, we can similarly define a partial definition for graded operads. We now provide an example of a graded operad.

	\begin{example}[\bf Graded endomorphism operad]
		Let $\mathfrak{A}=\oplus_{p \ge 0} \mathfrak{A}_p$ be a graded vector space. The graded endomorphism operad $\mathrm{End}_{\mathfrak{A}}$ is defined as follows:
		\begin{equation}
			\mathrm{End}_{\mathfrak{A}}(n) := \mathrm{Hom}_{\mathrm{g}}(\mathfrak{A}^{\otimes n},\mathfrak{A}) \quad \text{for all}~ n \ge 0.
		\end{equation}
		where $\mathfrak{A}^{\otimes n}$ denotes the $n$-fold tensor product of $\mathfrak{A}$ over $\K$, by convention $\mathfrak{A}^{\otimes 0} = \K$, and $\mathrm{Hom}_{\mathrm{g}}(\mathfrak{A}^{\otimes n},\mathfrak{A})$ denotes the graded vector space of all graded linear maps $f:\mathfrak{A}^{\otimes n} \to \mathfrak{A}$ of any degree, that is, for any $a_1 \in \mathfrak{A}_{p_1}, \ldots, a_n \in \mathfrak{A}_{p_n}$, we have $f(a_1,\ldots,a_n) \in \mathfrak{A}_{p_1 + \cdots + p_n+|f|}$. The partial composition maps $\circ_i: \mathrm{Hom}_\mathrm{g}(\mathfrak{A}^{\otimes n}, \mathfrak{A}) \times \mathrm{Hom}_\mathrm{g}(\mathfrak{A}^{\otimes m},\mathfrak{A}) \to \mathrm{Hom}_\mathrm{g}(\mathfrak{A}^{\otimes m-1+n},\mathfrak{A})$ and the right action $\cdot: \mathrm{Hom}_\mathrm{g}(\mathfrak{A}^{\otimes n}, \mathfrak{A}) \times \Sm_n \to \mathrm{Hom}_\mathrm{g}(\mathfrak{A}^{\otimes n}, \mathfrak{A})$ are defined in the same way as defined in Equation \eqref{def_partial_comp_end_operad} and \eqref{def_end_opd_sym_action}, which preserves the degree. 	
		The unit element $\mathbbm{1}$ is the identity map $\mathrm{id}_{\mathfrak{A}} \in \mathrm{End}_\mathfrak{A}(1)$. 
	\end{example}

	\begin{definition}
		Let $\mathcal{G} = \{\mathcal{G}(n) : n \ge 0\}$ and $\mathcal{H} = \{\mathcal{H}(n) : n \ge 0\}$ be two graded operads. A {\bf morphism of graded operads} $\gamma: \mathcal{G} \to \mathcal{H}$ consists of a sequence of degree zero linear maps $\gamma_n : \mathcal{G}(n) \to \mathcal{H}(n)$ for all $n \ge 0$ such that 
		\begin{equation} \label{graded_morphism_unital_cond}
			\gamma_1 (\mathbbm{1}_{\mathcal{G}}) = \mathbbm{1}_{\mathcal{H}}
		\end{equation}
		and for all $n,m \ge 1$ and $\sigma \in \mathbb{S}_n$, Diagram \ref{morphism_diagram} should commute. 
	\end{definition}

	\begin{definition}\label{algebra_graded_def}
		A {\bf $\g$-algebra} is a graded vector space $\mathfrak{c}$ equipped with a morphism of graded operads $\gamma: \mathcal{G} \to \mathrm{End}_\mathfrak{c}$.
	\end{definition}

	With these notations and definitions, we proceed to the construction of a universal algebra associated with a given finite-dimensional algebra over an arbitrary operad. 

