\bigskip
\section{\large The construction of a Universal algebra for algebras over (Graded) Operads}\label{sec-3}

	In this section, we present a universal construction for $\p$-algebras, where $\p$ is an arbitrary (graded) operad. For any given $\p$-algebra $\mathfrak{a}$, we establish the existence of a functor \(\mathfrak{a} \otimes - : \mathrm{ComAlg} \to \p\)\text{-}\(\mathrm{Alg}\) from the category of commutative algebras to the category of $\p$-algebras (cf. Proposition \ref{funct_com_to_p-alg}). Additionally, in Theorems \ref{thm_left_adjoint} and \ref{thm_graded_left_adjoint}, we prove that this functor admits a left adjoint \(\mathcal{C}(\fa, -): \mathcal{P}\)\text{-}\(\mathrm{Alg} \to \mathrm{ComAlg}\), provided certain conditions are satisfied.
	Our construction not only unifies the results of \cite[Theorem 2.1]{Ag-Mil}, \cite[Theorem 2.2]{Ag-Mil2}, \cite[Theorem 3.1]{Lie-Y}, and \cite[Theorem 1.1]{Mil} (obtained for 
	%which deal with 
	Leibniz/Lie, Poisson, Lie-Yamaguti, and associative algebras, respectively),  
	%Furthermore, Theorem \ref{thm_graded_left_adjoint} 
	but also naturally extends them to their graded counterparts.

\medskip	
\subsection{Algebras over an Operad}


	\begin{prop}\label{funct_com_to_p-alg}
		Let $\p$ be an operad. For any $\p$-algebra $\fa$ we obtain a functor $\fa  \otimes - : \mathrm{ComAlg} \to  \p$-Alg. 
	\end{prop}

	\begin{proof}
		Let $\gamma:\p \to \mathrm{End}_\fa$ be the $\p$-algebra structure on $\fa$. Now, for any $C \in \mathrm{ComAlg}$, we show that $\fa\otimes C$ is a $\p$-algebra. We define a map $\overline{\gamma}:\p\rightarrow \mathrm{End}_{\fa\otimes C}$ by 
		\begin{equation}\label{morph}
			\overline{\gamma}_k(\mu)(a_1\otimes c_1,\ldots,a_k\otimes c_k):=\gamma_k(\mu)(a_1,\ldots,a_k)\otimes c_1\cdots c_k,
		\end{equation}
		for all $\mu\in \p(k);~a_1,a_2,\ldots,a_k\in \fa;$ and $c_1,\ldots,c_k\in C$. To show that $\overline{\gamma}$ defines a $\p$ algebra structure on $\fa \otimes C$, we first establish the commutativity of the following diagram
		\begin{equation}\label{prop_diag1_P-Alg_tensor_ComAlg}
			\begin{tikzcd}
				{\p(k) \otimes \p(l)} & {\p(k-1+l)} \\
				{\mathrm{End}_{\mathfrak{a} \otimes C}(k) \otimes \mathrm{End}_{\mathfrak{a} \otimes C}(l)} & {\mathrm{End}_{\mathfrak{a} \otimes C}(k-1+l),}
				\arrow["{\circ_i}", from=1-1, to=1-2]
				\arrow["{\overline{\gamma}_k \otimes \overline{\gamma}_l}"', from=1-1, to=2-1]
				\arrow["{\overline{\gamma}_{k-1+l}}", from=1-2, to=2-2]
				\arrow["{\circ_i}", from=2-1, to=2-2]
			\end{tikzcd}
		\end{equation}
		for any $k,l \in \mathbb{N}$. Let $\mu \in \p(k)$ and $\nu \in \p(l)$. Then, we obtain the following expression.  
		\begin{align*}
			\overline{\gamma}&_{k-1+l}(\mu \circ_i \nu) (a_1 \otimes c_1, \ldots, a_{k-1+l} \otimes c_{k-1+l}) \\
			&\stackrel{(\ref{morph})}{=} 
			\gamma_{k-1+l} (\mu \circ_i \nu) (a_1,\ldots,a_{k-1+l}) \otimes c_1 \cdots c_{k-1+l} \\
			&\stackrel{(\ref{morphism_diagram})}{=}
			\gamma_k(\mu) \circ_i \gamma_l(\nu) (a_1,\ldots,a_{k-1+l}) \otimes c_1 \cdots c_{k-1+l} \\
			&\stackrel{(\ref{def_partial_comp_end_operad})}{=}\gamma_k(\mu)(a_1,\ldots,a_{i-1}, \gamma_l(\nu) (a_i,\ldots,a_{i+l-1}),a_{i+l},\ldots,a_{k-1+l}) \otimes c_1 \cdots c_{k-1+l} \\
			&\stackrel{(\ref{morph})}{=}
			\overline{\gamma}_k(\mu) (a_1 \otimes c_1, \ldots, a_{i-1} \otimes c_{i-1}, \gamma_l(\nu)(a_i,\ldots,a_{i+l-1}) \otimes c_{i} \cdots c_{i+l-1}, a_{i+l}\otimes c_{i+l}, \ldots, a_{k-1+l} \otimes c_{k-1+l}) \\
			&\stackrel{(\ref{morph})}{=}
			\overline{\gamma}_k(\mu)(a_1 \otimes c_1, \ldots, a_{i-1} \otimes c_{i-1}, \overline{\gamma}_l(\nu)(a_i \otimes c_i,\ldots,a_{i+l-1}\otimes c_{i+l-1}), a_{i+l}\otimes c_{i+l}, \ldots, a_{k-1+l} \otimes c_{k-1+l})\\
			&\stackrel{(\ref{def_partial_comp_end_operad})}{=}
			\overline{\gamma}_k(\mu) \circ_i \overline{\gamma}_l(\nu) (a_1 \otimes c_1, \ldots, a_{k-1+l} \otimes c_{k-1+l}), 
		\end{align*}
		for any $a_1,\ldots,a_{k-1+l} \in \fa$ and $c_1,\ldots,c_{k-1+l} \in C$. Therefore, Diagram \eqref{prop_diag1_P-Alg_tensor_ComAlg} commutes for any $k,l \in \mathbb{N}$. Furthermore, it is obvious that $\overline{\gamma}_1(1)=\mathrm{id}_{\fa\otimes C}$. Next, to obtain  $\overline{\gamma}_k(\mu\cdot\sigma)=\overline{\gamma}_k\cdot\sigma$ for any $\sigma\in S_k$, we do the following computation. Let $\mu \in \p(k)$ and $\sigma \in \Sm_k$,  
		\begin{eqnarray*}
			\overline{\gamma}_k(\mu) \cdot \sigma (a_1 \otimes c_1, \ldots, a_k \otimes c_k) 
			&\stackrel{(\ref{def_end_opd_sym_action})}{=}& \overline{\gamma}_k(\mu) (a_{\sigma(1)} \otimes c_{\sigma(1)}, \ldots, a_{\sigma(k)} \otimes c_{\sigma(k)}) \\
			&\stackrel{(\ref{morph})}{=}& \gamma_k(\mu)(a_{\sigma(1)},\ldots,a_{\sigma(k)}) \otimes c_{\sigma(1)} \cdots c_{\sigma(k)} \\
			(\text{Since} ~C \in \mathrm{ComAlg})
			&=& \gamma_k(\mu)(a_{\sigma(1)},\ldots,a_{\sigma(k)}) \otimes c_1 \cdots c_k \\
			&\stackrel{(\ref{morphism_diagram})}{=}&
			\gamma_k(\mu \cdot \sigma) (a_1,\ldots,a_k) \otimes c_1 \cdots c_k \\  		 
			&\stackrel{(\ref{morph})}{=}& 
			\overline{\gamma}_k(\mu \cdot \sigma)(a_1 \otimes c_1, \ldots, a_k \otimes c_k), 
		\end{eqnarray*}
		for any $a_1,\ldots,a_k \in \fa$ and $c_1,\ldots,c_k \in C$. Hence, $\fa\otimes C$ is a $\p$-algebra. 

		\medskip
		Next, we show that a morphism $f: C \to D$ in $\mathrm{ComAlg}$ induces a morphism $\mathfrak{a} \otimes f:\fa \otimes C \to \fa \otimes D$ in $\p$-Alg. We define it as follows
		\begin{equation}
			\fa\otimes{f}(a \otimes c):=a \otimes f(c),
		\end{equation}
		for any $a \in \fa$ and $c \in C$. Now, using Equation \eqref{morph}, we show that $\fa \otimes f: \fa \otimes C \to \fa \otimes D$ is a $\p$-algebra morphism. In other words, we prove the commutativity of the following diagram
		\begin{equation}
			\begin{tikzcd}
				{(\mathfrak{a} \otimes C)^{\otimes k}} & 	{\mathfrak{a} \otimes C} \\
				{(\mathfrak{a} \otimes D)^{\otimes k}} & 	{\mathfrak{a} \otimes D,}
				\arrow["{\overline{\gamma}_k(\mu)}", 	from=1-1, to=1-2]
				\arrow["{(\mathrm{id} \otimes f)^{\otimes k}}"', from=1-1, to=2-1]
				\arrow["{\mathrm{id} \otimes f}", 	from=1-2, to=2-2]
				\arrow["{\overline{\gamma}_k'(\mu)}", 	from=2-1, to=2-2]
			\end{tikzcd}
		\end{equation}
		for any $\mu \in \p(k)$. Let $a_1,\ldots,a_k \in \fa$ and $c_1,\ldots,c_k \in C$, then 
		\begin{eqnarray*}
			(\mathrm{id} \otimes f) \big(\overline{\gamma}_k(\mu) (a_{1} \otimes c_1, \ldots, a_k \otimes c_k)\big) 
			&\stackrel{(\ref{morph})}{=}& 
			(\mathrm{id} \otimes f) \big(\gamma_k(\mu)(a_1,\ldots,a_k) \otimes c_1 \cdots c_k\big) \\
			&=&
			\gamma_k(\mu)(a_1,\ldots,a_k) \otimes f(c_1 \cdots c_k) \\
			&=&
			\gamma_k(\mu)(a_1,\ldots,a_k) \otimes f(c_1)\cdots f(c_k) \\
			&\stackrel{(\ref{morph})}{=}& 
			\overline{\gamma}_k'(\mu) (a_1 \otimes f(c_1), \ldots, a_k \otimes f(c_k)) \\ 
			&=& 
			\overline{\gamma}_k'(\mu) \big((\mathrm{id} \otimes f)^{\otimes k}(a_1\otimes c_1, \ldots, a_k\otimes c_k)\big). 
		\end{eqnarray*}
		%Note that, here the operad morphisms $\overline{\gamma}: \p \to \mathrm{End}_{\fa \otimes C}$ and $\overline{\gamma}^\prime: \p \to \mathrm{End}_{\mathfrak{a} \otimes D}$ are induced by the operad morphism $\gamma:\p\rightarrow \mathrm{End}_{\fa}$ as described in Equation (\ref{morph}). 
		Thus, any morphism $f: C \to D$ in $\mathrm{ComAlg}$ induces a morphism $\mathfrak{a} \otimes f:\fa \otimes C \to \fa \otimes D$ in $\p$-Alg. 
		Hence, giving a functor $\fa \otimes - : \mathrm{ComAlg} \to \p$-Alg.
	\end{proof}

	\begin{theorem}\label{thm_left_adjoint}
		Let $\p$ be an operad and $\fa$ be a $\p$-algebra. Then, the functor $\fa\otimes -: \mathrm{ComAlg} \to \p$-Alg admits a left adjoint if and only if $\fa$ is finite-dimensional.
	\end{theorem}

	\begin{proof}
		($\impliedby$)
		We assume $\fa$ to be a finite-dimensional $\p$-algebra with a vector space basis $\{a_1,\ldots,a_n\}$. Let the $\p$-algebra structure on $\fa$ is given by $\gamma:\p\rightarrow \mathrm{End}_\fa$. Then for any $\mu \in \p(k)$ we obtain 
		\begin{equation}\label{struc_const_rel1}
			\gamma_k(\mu)(a_{i_1},\ldots,a_{i_k})
			~=~\sum_{s=1}^n \alpha^s_{\gamma_k(\mu),i_1,\ldots,i_k} a_s,
		\end{equation}
  		where $i_1,\ldots,i_k = 1,\ldots,n$. Therefore, the set of scalars $\{\alpha^s_{\gamma_k(\mu),i_1,\ldots,i_k}~|~s,i_1,\ldots,i_k=1,\ldots,n,~\mu\in \p(k)\}$ yields the structure constants of $\fa$.
		Now, for an arbitrary $\p$-algebra $\mathfrak{b}$, we construct a commutative algebra $\mathcal{C}(\fa,\mathfrak{b}) \in \mathrm{ComAlg}$.
		Let $\{b_i|~i\in I\}$ be a vector space basis of $\mathfrak{b}$. Assuming the $\p$-algebra structure on $\mathfrak{b}$ to be given $\widetilde{\gamma}:\p\rightarrow \mathrm{End}_{\mathfrak{b}}$, for any $\mu \in \p(k)$ we obtain 
		\begin{equation}\label{struc_const_rel2}
			\widetilde{\gamma}_k(\mu)(b_{i_1},\ldots,b_{i_k}) \quad =
			\sum_{u\in I_{\widetilde{\gamma}_k(\mu),i_1,\ldots,i_k}} \beta^u_{\widetilde{\gamma}_k(\mu),i_1,\ldots,i_k} b_u,
		\end{equation}
		where $i_1,\ldots,i_k \in I$ and $I_{\widetilde{\gamma}_k(\mu),i_1,i_2,\ldots,i_k}$ is a finite subset of $I$. Thus, the structure constants of $\mathfrak{b}$ is given by the set
		$\{\beta^u_{\widetilde{\gamma}_k(\mu),i_1,\ldots,i_k}|~i_1,\ldots,i_k\in I,~u\in I_{\widetilde{\gamma}_k(\mu),i_1,i_2,\ldots,i_k},~\mbox{and}~\mu\in \p(k)\}$.
		Let $\mathbb{K}\big[X_{si}|~s=1,2,\ldots,n, ~i\in I\big]$ be the polynomial algebra with indeterminates $X_{si}$. We define 
		\begin{equation}\label{C(a,b)}
			\mathcal{C}(\fa,\mathfrak{b}) := \mathbb{K}\big[X_{si}|~s=1,2,\ldots,n, ~i\in I\big] \big/ J,
		\end{equation}
		where $J$ is the ideal generated by the polynomials of the form
		\begin{equation}
			P^{(\fa,\mathfrak{b})}_{(\mu,a,i_1,\ldots,i_k)} ~:=
			\sum_{u\in I_{\widetilde{\gamma}_k(\mu),i_1,\ldots,i_k}} \beta^u_{\widetilde{\gamma}_k(\mu),i_1,\ldots,i_k} X_{au}
			\hspace{0.2cm} -
			\sum_{s_1,s_2,\ldots, s_k=1}^n \alpha^a_{\gamma_k(\mu),s_1,\ldots,s_k}X_{s_1 i_1}\cdots X_{s_k i_k},
		\end{equation}
		for any $\mu\in \p(k)$, $a=1,2,\ldots, n$, and $i_1,\ldots, i_k\in I$. Let $x_{si}$ denote the class $\widehat{X_{si}}$ of $X_{si}$ in the algebra $\mathcal{C}(\fa,\mathfrak{b})$. This gives us the following equality in  $\mathcal{C}(\fa,\mathfrak{b})$: 
		\begin{equation}\label{thm_rel_struc_const_a_b}
			\sum_{u\in I_{\widetilde{\gamma}_k(\mu),i_1,\ldots,i_k}} \beta^u_{\widetilde{\gamma}_k(\mu),i_1,\ldots,i_k} x_{au}
			\hspace{0.2cm} =~ 
			\sum_{s_1,s_2,\ldots, s_k=1}^n \alpha^a_{\gamma_k(\mu),s_1,\ldots,s_k}x_{s_1 i_1}\cdots x_{s_k i_k}, 
		\end{equation} 
		for any $\mu \in \p(k)$, $a =1,\ldots,n$, and  $i_1,\ldots,i_k \in I$.

		\bigskip
		Next, we define a map 
		$\eta_{\mathfrak{b}}:\mathfrak{b}\rightarrow \fa\otimes \mathcal{C}(\fa,\mathfrak{b})$ by 
		\begin{equation} \label{thm_def_eta_b}
			\eta_\mathfrak{b}(b_i):=\sum_{s=1}^n a_s \otimes x_{si}\quad \mbox{for any } i\in I,
		\end{equation}
		and show that $\eta_\mathfrak{b}$ is a $\p$-algebra morphism. That is, the following diagram commutes for any $\mu \in \p(k)$

		\begin{equation}
			\begin{tikzcd}
				{\mathfrak{b}^{\otimes k}} & {\mathfrak{b}} \\
				{(\fa \otimes \mathcal{C}(\fa,\mathfrak{b}))^{\otimes k}} & {\fa \otimes \mathcal{C}(\fa,\mathfrak{b}),}
				\arrow["{\widetilde{\gamma}_{k}(\mu)}", from=1-1, to=1-2]
				\arrow["{\eta_{\mathfrak{b}}^{\otimes k}}"', from=1-1, to=2-1]
				\arrow["{\eta_{\mathfrak{b}}}", from=1-2, to=2-2]
				\arrow["{\overline{\gamma}_{k}(\mu)}", from=2-1, to=2-2]
			\end{tikzcd}
		\end{equation}
		where the operad morphism $\overline{\gamma}: \p \to \mathrm{End}_{\fa \otimes \mathcal{C}(\fa,\mathfrak{b})}$ is induced from the operad morphism $\gamma: \p \to \mathrm{End}_\mathfrak{a}$ as defined in Equation (\ref{morph}). The commutativity of the above diagram follows from the computation given below. Let $\mu \in \p(k)$, and ${i_1},\ldots,{i_k} \in I$, then
		\begin{eqnarray*}
			\overline{\gamma}_k(\mu) \big(\eta_\mathfrak{b}^{\otimes k}(b_{i_1}, \ldots, b_{i_k})\big)
			&\stackrel{(\ref{thm_def_eta_b})}{=}&
			\overline{\gamma}_k(\mu) \Big(\sum_{s_1=1}^n a_{s_1} \otimes x_{s_1i_1}, \ldots, \sum_{s_k=1}^n a_{s_k} \otimes x_{s_ki_k}\Big) \\
			&=& 
			\sum_{s_1,\ldots,s_k=1}^n \gamma_k(\mu) (a_{s_1},\ldots,a_{s_k}) \otimes x_{s_1i_i} \cdots x_{s_ki_k} \\
			&\stackrel{(\ref{struc_const_rel1})}{=}&
			\sum_{i=1}^n ~a_i \hspace{0.2cm} \otimes \sum_{s_1,\ldots,s_k=1}^n \alpha^i_{\gamma_k(\mu),s_1,\ldots,s_k} x_{s_1i_i} \cdots x_{s_ki_k} \\
			&\stackrel{(\ref{thm_rel_struc_const_a_b})}{=}&\sum_{i=1}^n~ a_i \hspace{0.2cm} \otimes \sum_{u\in I_{\widetilde{\gamma}_k(\mu),i_1,\ldots,i_k}} \beta^u_{\widetilde{\gamma}_k(\mu),i_1,\ldots,i_k} x_{iu}\\
			&=&
			\sum_{u\in I_{\widetilde{\gamma}_k(\mu),i_1,\ldots,i_k}} \beta^u_{\widetilde{\gamma}_k(\mu),i_1,\ldots,i_k} \Big(\sum_{i=1}^n a_i \otimes x_{iu}\Big) \\
			&\stackrel{(\ref{thm_def_eta_b})}{=}&
			\sum_{u\in I_{\widetilde{\gamma}_k(\mu),i_1,\ldots,i_k}} \beta^u_{\widetilde{\gamma}_k(\mu),i_1,\ldots,i_k} ~\eta_\mathfrak{b}(b_u)\\
			&=&
			\eta_\mathfrak{b}~\Big(\sum_{u\in I_{\widetilde{\gamma}_k(\mu),i_1,\ldots,i_k}} \beta^u_{\widetilde{\gamma}_k(\mu),i_1,\ldots,i_k} ~b_u\Big) \\
			&\stackrel{(\ref{struc_const_rel2})}{=}&
			\eta_\mathfrak{b} \big(\widetilde{\gamma}_k(\mu)(b_{i_1}, \ldots, b_{i_k})\big).
  		\end{eqnarray*} 
		Thus, $\eta_{\mathfrak{b}}$ is $\p$-algebra morphism. Let $C \in \mathrm{ComAlg}$ and $f:\mathfrak{b}\rightarrow \fa\otimes C$ be a $\p$-algebra morphism, then we show that there exists a unique algebra morphism $\Phi: \mathcal{C}(\fa,\mathfrak{b})\rightarrow C$ for which the following diagram commutes

		\begin{equation}\label{universal prop}
			\begin{tikzcd}
				{\mathfrak{b }} & {\fa \otimes \mathcal{C}(\fa, \mathfrak{b})} \\
				& {\fa \otimes C.}
				\arrow["{\eta_\mathfrak{b}}", from=1-1, to=1-2]
				\arrow["f"', from=1-1, to=2-2]
				\arrow["{id \otimes \Phi}", from=1-2, to=2-2]
			\end{tikzcd}
		\end{equation}
		Let $\{c_{si}|~ s=1,2,\ldots,n, ~i\in I\}$ be a subset of $C$ such that for any $i \in I$, we have
		\begin{equation}
			f(b_i)=\sum_{s=1}^n a_s\otimes c_{si}. 
		\end{equation}
		Since $f:\mathfrak{b}\rightarrow \fa\otimes C$ is a morphism of $\p$-algebras, we get
		\begin{equation}\label{thm_morph_f}
			f\big(\widetilde{\gamma}_k(\mu)(b_{i_1},\ldots,b_{i_k})\big) ~=~ \overline{\gamma}_k(\mu) \big(f(b_{i_1}),\ldots,f(b_{i_k})\big), \mbox{ for any } ~\mu\in \p(k),~ i_1,\ldots,i_k \in I.
		\end{equation}
		Simplifying the left hand side of Equation (\ref{thm_morph_f}), 
		\begin{equation*}
			f\big(\widetilde{\gamma}_k(\mu)(b_{i_1},\ldots,b_{i_k})\big) ~=~ \sum_{s=1}^n a_s \otimes 
			\Big(\sum_{u\in I_{\widetilde{\gamma}_k(\mu),i_1,\ldots,i_k}} \beta^u_{\widetilde{\gamma}_k(\mu),i_1,\ldots,i_k} c_{su}\Big).
		\end{equation*}
		Similarly, simplifying the right hand side of Equation (\ref{thm_morph_f}), we obtain
		\begin{eqnarray*}
			\overline{\gamma}_k(\mu) \big(f(b_{i_1}),\ldots,f(b_{i_k})\big) 
			&=& 
			\sum_{s_1,\ldots,s_k=1}^n \gamma_{k}(\mu) (a_{s_1},\ldots,a_{s_k}) \otimes c_{s_1 i_1}\cdots~ c_{s_k i_k} \\
			&=& 
			\sum_{s=1}^n a_s \otimes ~\Big(\sum_{s_1,\ldots,s_k=1}^n \alpha^s_{\gamma_k(\mu),s_1,\ldots,s_k}~
			c_{s_1 i_1}\cdots~ c_{s_k i_k}\Big), ~\mbox{for any }~ i_1,\ldots,i_k \in I.
		\end{eqnarray*}
		 Therefore, the elements of the set $\{c_{si}|~ ~s=1,2,\ldots,n,~ i\in I\}$ satisfy the following equation 
		\begin{equation}\label{relations on csi}
			\sum_{u\in I_{\widetilde{\gamma}_k(\mu),i_1,\ldots,i_k}} \beta^u_{\widetilde{\gamma}_k(\mu),i_1,\ldots,i_k} c_{su}
			\hspace{0.2cm} =
			\sum_{s_1,\ldots, s_k=1}^n 	\alpha^s_{\gamma_k(\mu),s_1,\ldots,s_k}~c_{s_1 i_1}\cdots~ c_{s_k i_k},
		\end{equation}
		for any $\mu \in \p(k)$, $i_1,\ldots, i_k\in I$, and $s=1,2,\ldots,n$. By defining $\phi(X_{si})=c_{si}$, we obtain a unique algebra morphism $\phi: \mathbb{K}[X_{si}]\rightarrow C$. Equation \eqref{relations on csi} implies that $J \subseteq \mathrm{Ker}(\phi)$. Thus, inducing an algebra morphism on the quotient algebra, which we denote by the map ${\Phi}:\mathcal{C}(\fa,\mathfrak{b})\rightarrow C$. Note that
		\begin{equation}
			f(b_i)=\sum_{s=1}^n a_s\otimes c_{si}=\sum_{s=1}^n a_s\otimes \Phi(x_{si})=(\mathrm{id}\otimes \Phi)\Big(\sum_{s=1}^n a_s\otimes x_{si}\Big)=(\mathrm{id}\otimes \Phi)\circ \eta_\mathfrak{b}(b_i),\quad \mbox{for all }i\in I.
		\end{equation}
		Hence, Diagram \eqref{universal prop} commutes. One can show easily that the obtained map $\Phi$ is unique. Therefore, for any $\p$-algebra $\mathfrak{b}$ and commutative algebra $C$, we have the following bijection
		\begin{equation}\label{bijection1}
			\Omega_{\mathfrak{b},C}:\mathrm{Hom}_{\mathrm{ComAlg}}(\mathcal{C}(\fa,\mathfrak{b}),C)\longrightarrow \mathrm{Hom}_{\p\text{-Alg}}(\mathfrak{b},\fa\otimes C) \quad \mbox{defined by }~ \Omega_{\mathfrak{b},C}(\Phi)=(\mathrm{id}\otimes \Phi)\circ \eta_\mathfrak{b}.
		\end{equation}

		\medskip
		Now, one can verify that assigning to each $\p$-algebra $\mathfrak{b}$ the commutative algebra $\mathcal{C}(\fa,\mathfrak{b})$, defines a functor $$\mathcal{C}(\fa,-): \p\text{-Alg} \longrightarrow \mathrm{ComAlg}.$$ 
		Furthermore, for any $\p$-algebra $\mathfrak{b}^\prime$ with a $\p$-algebra morphism $\alpha:\mathfrak{b}\rightarrow \mathfrak{b}^\prime$ and for any commutative algebra $C$ with an algebra morphism $\beta:C\rightarrow C^\prime$, we obtain a commutative diagram as follows
		\begin{equation}
			\begin{CD}
				\mathrm{Hom}_{\mathrm{ComAlg}}(\mathcal{C}(\fa,\mathfrak{b}^\prime),C) @> \mathcal{C}(\alpha)^* >>
				\mathrm{Hom}_{\mathrm{ComAlg}}(\mathcal{C}(\fa,\mathfrak{b}),C) @> \beta_{*} >> \mathrm{Hom}_{\mathrm{ComAlg}}(\mathcal{C}(\fa,\mathfrak{b}),C^\prime)\\
				@V\Omega_{\mathfrak{b}^\prime,C} VV @V\Omega_{\mathfrak{b},C} VV @V\Omega_{\mathfrak{b},C^\prime} VV\\
				\mathrm{Hom}_{\p\text{-Alg}}(\mathfrak{b}^\prime,\fa\otimes C) @> \alpha^* >>
				\mathrm{Hom}_{\p\text{-Alg}}(\mathfrak{b},\fa\otimes C) @> \fa\otimes \beta_{*} >> \mathrm{Hom}_{\p\text{-Alg}}(\mathfrak{b},\fa\otimes C^\prime).
			\end{CD}
		\end{equation}
		Thus, $\Omega_{\mathfrak{b},C}$ is natural in both $\mathfrak{b}$ and $C$. Consequently, $\mathcal{C}(\fa,-):\p\text{-Alg}\rightarrow \mathrm{ComAlg}$ is left adjoint to the functor $\fa\otimes-:\mathrm{ComAlg} \to \p$-Alg. 

		\medskip\noindent
		($\implies$)
		Before proving the converse part, 
		we show that the category $\p$-Alg is closed under arbitrary product.
		Let $(\fa_i)_{i \in I}$ be a family of objects in $\p$-Alg with the $\p$-algebra structures on $\fa_i$ given by $\gamma^i: \p \to \mathrm{End}_{\fa_i}$. 
		Since the category $\mathrm{Vect}$ is closed under arbitrary product, we obtain the product of $(\fa_i)_{i \in I}$ in $\mathrm{Vect}$, given by 
		\begin{equation}\label{arb_product_P_alg}
			\prod_{i \in I} \fa_i := \big\{(a_i)_{i \in I} :a_i \in \fa_i\big\}. 
		\end{equation}
		along with projection maps $\pi_j: \prod_{i \in I} \fa_i \to \fa_j$ for each $j \in I$. 
		Now, to show that the product of $(\fa_i)_{i \in I}$ in $\p$-Alg is also given by the vector space $\prod_{i \in I} \fa_i$ we must show that the following things hold:
		\begin{itemize}
			\item There exists a $\p$-algebra structure on $\prod_{i \in I} \fa_i$. 
			\item Each projection maps $\pi_j: \prod_{i \in I} \fa_i \to \fa_j$ are $\p$-algebra morphisms. 
			\item For an arbitrary $\p$-algebra $\mathfrak{b}$ along with $\p$-algebra morphisms $\phi_j: \mathfrak{b} \to \fa_j$ for each $j \in I$, there exists a unique $\theta:\mathfrak{b}\to \prod_{i \in I}{\fa_i} $ such that the following diagram commutes for every $j\in I$.
			\begin{equation}\label{universality_prod}
				\begin{tikzcd}
				& {\mathfrak{b}} \\
				& {\prod_{i \in I} \mathfrak{a}_{i}} \\
				{\mathfrak{a}_j}
				\arrow["\theta", dashed, from=1-2, to=2-2]
				\arrow["{\phi_j}"', bend right=35, from=1-2, to=3-1]
				\arrow["{\pi_j}", from=2-2, to=3-1]
			\end{tikzcd}
		\end{equation} 
 		\end{itemize} 
		We note that the $\p$-algebra structure, given by $\gamma^i: \p \to \mathrm{End}_{\fa_i}$, on each $\fa_i$ induces a $\p$-algebra structure on $\prod_{i \in I } \fa_i$ which is denoted by $\psi:\p \to \mathrm{End}_{\prod_{i \in I} \fa_i}$ and is defined as follows:
		\begin{equation}\label{arb_product_P_alg_structure}
			\psi_k(\mu)\big((a^1_{i})_{i \in  I},\ldots,(a^k_{i})_{i \in I}\big)  
			:= 
			\big(\gamma^i_k(\mu)(a^1_{i},\ldots,a^k_{i})\big)_{i \in I}	\quad \text{ for all } \mu \in \p(k). 
		\end{equation}		 
		Thus, $\prod_{i \in I} \fa_i$ is an object in $\p$-Alg. 
		Next, to show that each projection map $\pi_j : \prod_{i \in I} \fa_i \to \fa_j$ is a $\p$-algebra morphism we show the commutativity the diagram given below: for each $k \in \mathbb{N}$ and $\mu \in \p(k)$
		\begin{equation}\label{proj_p_alg_mor_diag}
			\begin{tikzcd}
				{(\prod \fa_i)^{\otimes k}} & {\prod\fa_i} \\
				{\fa_j^{\otimes k}} & {\fa_j}
				\arrow["{\psi_k(\mu)}", from=1-1, to=1-2]
				\arrow["{\pi^{\otimes k}_j}"', from=1-1, to=2-1]
				\arrow["{\pi_j}", from=1-2, to=2-2]
				\arrow["{\gamma^{j}_k(\mu)}", from=2-1, to=2-2]
			\end{tikzcd}
		\end{equation}
		The commutativity of the above diagram follows from the following computation:
		\begin{eqnarray*}
			\big(\pi_j \circ \psi_k(\mu)\big)\big((a^1_{i})_{i \in I},\ldots,(a^k_{i})_{i \in I}\big) 
			&\stackrel{\eqref{proj_p_alg_mor_diag}}{=}& \pi_j\big(\big(\gamma^i_{k}(\mu)(a^1_{i},\ldots,a^k_{i})\big)_{i\in I}\big)\\
			&=& \gamma^j_{k}(\mu)\big(a^1_{j},\ldots,a^k_{j}\big)\\
			&=& \gamma^j_{k}(\mu)\big(\pi_j((a^1_{i})_{i\in I}),\ldots,\pi_j((a^k_{i})_{i \in I})\big)\\
			&=& \big(\gamma^j_{k}(\mu)\circ \pi_j^{\otimes k}\big)\big((a^1_{i})_{i \in I},\ldots,(a^k_{i})_{i \in I}\big).
		\end{eqnarray*}
		Hence, we obtain that each projection maps $\pi_j : \prod_{i \in I} \fa_i \to \fa_j$ are $\p$-algebra morphisms. 
		Finally, for an arbitrary $\p$-algebra $\mathfrak{b}$, given by $\beta :\p \to \text{End}_{\mathfrak{b}}$, along with $\p$-algebra morphism $\phi_{j} : \mathfrak{b}\to \fa_j$ for each $j \in I$, we show the existence of an unique $\p$-algebra morphism $\theta:\mathfrak{b}\to \prod_{i \in I}{\fa_i} $ for which Diagram \eqref{universality_prod} commutes for every $j\in I$.
		At first we note that since $\phi_j: \mathfrak{b} \to \mathfrak{a}_j$ is a $\p$-algebra morphism we have the following equality:
		\begin{equation}
			(\phi_j\circ\beta_k(\mu))(b^1,\ldots,b^k) ~=~ \gamma^j_{k}(\mu)(\phi_j(b^1),\ldots,\phi_j(b^k))
		\end{equation}
		for any $b^1,\cdots, b^k \in \mathfrak{b}$. We define a map $\theta: \mathfrak{b} \to \prod_{i \in I} \fa_i$ as follows:
		\begin{equation}
			\theta(b) := \big(\phi_i(b)\big)_{i \in I} \quad \text{for all } b \in \mathfrak{b}.  
		\end{equation}
		From the definition of $\theta$ it is clear that Diagram \eqref{universality_prod} commutes, since we have the following equality: 
		\begin{equation}
			(\pi_j\circ\theta)(b) ~=~ \pi_j((\phi_i(b))_{i \in I}) ~=~ \phi_j(b), \quad \text{for all } b \in \mathfrak{b}. 
		\end{equation}
		Thus, it only remains to show that $\theta: \mathfrak{b} \to \prod_{i \in I} \fa_i$ is $\p$-algebra morphism, which follows from the computation below: for any $b^1,\cdots,b^k\in \mathfrak{b}$
		\begin{eqnarray*}
			\theta \circ \beta_k(\mu)\big(b^1,\ldots,b^k\big)
			&=&\big(\phi_i\big(\beta_k(\mu)(b^1,\ldots,b^k)\big)\big)_{i\in I}\\
			&=&\big(\gamma^{i}_k(\mu)\big(\phi_i(b^1),\ldots,\phi_i(b^k)\big)\big)_{i\in I}\\
			&=&\psi_k(\mu)\big((\phi_i(b^1))_{i\in I},\ldots ,(\phi_i(b^k))_{i\in I}\big)\\
			&=&\psi_k(\mu)\big(\theta(b^1),\ldots,\theta(b^k)\big)\\
			&=&\psi_k(\mu)\circ\theta^{\otimes k}\big(b^1,\ldots,b^k\big).
		\end{eqnarray*}
		The uniqueness of $\theta$ is easy to verify. 
		Hence, we obtain that $\prod_{i \in I} \fa_i$ is the product of $\big(\fa_i\big)_{i \in I}$ is the $\p$-Alg.

		\medskip
		Now, following the arguments in the proof of \cite[Theorem 2.1]{Ag-Mil} we prove the converse part of this theorem. Assuming the functor $\fa \otimes-$ admits a left adjoint, we aim to show that $\fa$ is finite-dimensional. Since $\fa \otimes -$ admits a left adjoint it preserves all the limits that exists in the category $\mathrm{ComAlg}$ (cf. \cite[pg. 118]{MacLane}). Therefore, it preserves arbitrary products in $\mathrm{ComAlg}$. Furthermore, Equation \eqref{arb_product_P_alg} and \eqref{arb_product_P_alg_structure}, tells us that in $\p$-Alg products are constructed as the products of the underlying vector spaces. 
		Imposing the condition that $\fa \otimes -$ preserves the product of countable copies of the base field $\K$ in $\mathrm{ComAlg}$, we get $\fa$ is finite-dimensional. 
	\end{proof} 

	\begin{corollary}
		Let $\fa$ and $\mathfrak{b}$ be two $\p$-algebras with $\fa$ being finite-dimensional. Then the following map is bijective
		\begin{equation}
			\Omega:\mathrm{Hom}_{\mathrm{ComAlg}}(\mathcal{C}(\fa,\mathfrak{b}),\K)\longrightarrow \mathrm{Hom}_{\p\text{-Alg}}(\mathfrak{b},\fa) \quad \mbox{defined by }~ \Omega(\Phi)=(\mathrm{id}\otimes \Phi)\circ \eta_\mathfrak{b}.
		\end{equation}
	\end{corollary}

	\begin{definition}\label{def_universal_algebra}
		Let $\fa$ be a finite-dimensional $\mathcal{P}$-algebra with basis $\{a_1,\ldots,a_n\}$. We say that the commutative algebra $\mathcal{C}(\fa,\fa)$ (cf. Equation (\ref{C(a,b)})) is said to be the \textbf{universal algebra of $\fa$}, and is denoted by $\mathcal{C}(\fa)$. Recall that 
		\begin{equation}\label{C(a)}
			\mathcal{C}(\fa) := \mathbb{K}\big[X_{si}|~s,i=1,2,\ldots,n\big] \big/ J,
		\end{equation}
		where $J$ is the ideal generated by the polynomials of the form
		\begin{equation}\label{def_universal_polynomial_a}
			\p^{(\fa)}_{(\mu,a,i_1,\ldots,i_k)} := \sum_{u=1}^n \alpha^u_{\gamma_k(\mu),i_1,\ldots,i_k} X_{au}
			\hspace{0.2cm} - \sum_{s_1,s_2,\ldots, s_k=1}^n \alpha^a_{\gamma_k(\mu),s_1,\ldots,s_k}X_{s_1 i_1}\cdots X_{s_k i_k}
		\end{equation} 
		for any $k \in \mathbb{N}$ with $\mu \in \p(k)$ and $a,i_1,\ldots,i_k =1,\ldots,n$. The polynomials defined above are called the {\bf universal polynomials of $\fa$}. 
		%Now, let $\gamma: \fa \to \mathrm{End}_\fa$ denote the $\p$-algebra structure of $\fa$, then from Equation (\ref{struc_const_rel1}), we get the structure constants of $\fa$:
		%\begin{equation}
		%	\big\{\alpha^s_{\gamma_k(\mu),i_1,\ldots,i_k}~|~s,i_1,\ldots,i_k=1,\ldots,n,~\mu\in \p(k)~\mbox{for }k\in\mathbb{N}\big\}
		%\end{equation} 
	\end{definition}

 	For any finite-dimensional $\p$-algebra $\fa$, we now state as a corollary the universal property of $\mathcal{C}(\fa)$, that was obtained in the proof of Theorem \ref{thm_left_adjoint}.

	\begin{corollary}\label{cor_univ_prop}
		Let $\fa$ be a finite-dimensional $\p$-algebra. Then for any commutative algebra $C$ and any $\p$-algebra morphism $f: \fa \to \fa \otimes C$, there exists a unique commutative algebra morphism $\Phi: \mathcal{C}(\fa) \to C$ such that $f = (\mathrm{id} \otimes \Phi) \circ \eta_{\fa}$, i.e., the following diagram is commutative: 
		\begin{equation}\label{cor_diag_universal_property}
			\begin{tikzcd}
				{\mathfrak{a}} & {\fa \otimes \mathcal{C}(\fa)} \\
				& {\fa \otimes C}
				\arrow["{\eta_\mathfrak{a}}", from=1-1, to=1-2]
				\arrow["f"', from=1-1, to=2-2]
				\arrow["{id \otimes \Phi}", from=1-2, to=2-2]
			\end{tikzcd}
		\end{equation}   
	\end{corollary}

	\begin{proof}
		The proof follows directly from the bijection provided in Equation (\ref{bijection1}), for the case $\mathfrak{b} = \fa$. 
	\end{proof}

	\begin{remark}
	In the next section, we prove that the construction in Theorem \ref{thm_left_adjoint} yield an enrichment of the category of finite-dimensional $\mathcal{P}$-algebras over the category dual to the category $\mathrm{ComAlg}$ of commutative algebras. Subsequently, we obtain a natural universal coacting bi/Hopf algebra for any finite dimensional $\mathcal{P}$-algebra.
	\end{remark}

\medskip
\subsection{Algebras over a Graded Operad}\label{sub3.2}~~\\

	\vspace{-0.4cm}
	In this subsection, we present the construction of a universal graded algebra associated with an algebra over a graded operad. Our aim is to demonstrate that the results obtained for algebras over an operad extends in a natural way to the setting of graded operads.  

	\medskip
	Let $\mathcal{P}$ be a graded operad and $\mathfrak{A}$ be an arbitrary $\mathcal{P}$-algebra.  
	Recall that a {$\mathcal{P}$-algebra} structure on $\mathfrak{A}$ is given by a morphism of graded operads $\gamma: \mathcal{P} \to \mathrm{End}_\mathfrak{A}$. 
	%We note that, Proposition \ref{funct_com_to_p-alg} extends naturally to algebras over graded operads. More precisely, 
Similar to the proof of Proposition \ref{funct_com_to_p-alg}, one can verify that  for any $\mathfrak{A} \in \mathcal{P}$-Alg, the map $\mathfrak{A}  \otimes - : \mathrm{g}$-$\mathrm{ComAlg} \to  \mathcal{P}$-Alg defines a functor. In particular, if $C \in \mathrm{g}\text{-}\mathrm{ComAlg}$, then the $\mathcal{P}$-algebra structure on $\mathfrak{A} \otimes C$ is given by the graded operad morphism $\overline{\gamma}: \mathcal{P} \to \mathrm{End}_{\mathfrak{A}\otimes C}$, which is
	defined as 
	\begin{equation}\label{graded_case_gamma_bar}
		\overline{\gamma}_k(\mu)(a_{p_1i_1} \otimes c_{q_1j_1},\ldots,a_{p_ki_k} \otimes c_{q_kj_k}) ~:=~ 
		(-1)^{\varrho}~\gamma_{k}(\mu) (a_{p_1i_1}, \ldots, a_{p_ki_k}) \otimes c_{q_1j_1} \cdots c_{q_kj_k},
	\end{equation} 
	where $\varrho = (-1)^{p_kq_{k-1} + (p_{k-1} + p_k)q_{k-2} + \cdots + (p_2+\cdots+p_k)q_1}$ if $k \ge 2$, (the sign is obtained by following the Koszul sign convention) otherwise $\varrho = 0$. 

	\medskip
	Let $\mathfrak{A} = \oplus_{p \ge 0} \mathfrak{A}_p$  be a $\mathcal{P}$-algebra such that each component $\mathfrak{A}_p$ ($p \ge 0$) is finite-dimensional. 
	Then, we construct a universal graded algebra of $\mathfrak{A}$. Let  $$\{a_{01},\ldots,a_{0d_0};a_{11},\ldots,a_{1d_1};\ldots;a_{p1},\ldots,a_{pd_p};\ldots\}$$
	be a vector space basis of $\mathfrak{A}$, 
	where $\{a_{p1},\ldots,a_{p{d_p}}\}$ denotes a basis of the $p$-degree component $\mathfrak{A}_p$. If the $\mathcal{P}$-algebra structure on $\mathfrak{A}$ is given by $\gamma:\mathcal{P}\rightarrow \mathrm{End}_\mathfrak{A}$, then 
	\begin{equation}\label{struc_const_graded}
		\gamma_k(\mu)(a_{p_1i_1},\ldots,a_{p_ki_k})
		~=~\sum_{s=1}^{d_{\theta}} \alpha^{\theta,s }_{\gamma_k(\mu),p_1i_1,\ldots,p_ki_k} a_{\theta s}\quad \text{for any } \mu \in \mathcal{P}(k),
	\end{equation}
	where $\theta = p_1+\cdots+p_k+|\mu|$, $|\mu|$ denotes the degree of $\mu$ in the graded operad, $a_{p_ri_r} \in \mathfrak{A}_{p_r}$ for any $1 \le r \le k$. The set of scalars 
	\begin{equation*}
		\bigcup_{k \ge 1} \bigcup_{\mu \in \mathcal{P}(k)}\bigcup_{p_1,\ldots,p_k \ge 0}\Big\{
		\alpha^{\theta,s }_{\gamma_k(\mu),p_1i_1,\ldots,p_ki_k} ~\big|~ 1 \le i_r \le d_{p_r} \text{ for any } r=1,\ldots,k, \mbox{ and } 1 \le s \le d_{p_1 + \cdots + p_k + |\mu|}\Big\}
	\end{equation*}
 	yields the structure constants of $\mathfrak{A}$.
	Let $\mathbb{K}\left[X^{(\pi)}_{si}~\big|~s,i,\pi \ge 0 \right]$ be the graded commutative polynomial algebra, 
	with indeterminates $X^{(\pi)}_{si}$ of cohomological degree $\pi$. We define 
	\begin{equation}\label{C(A)}
		\mathcal{C}(\mathfrak{A}) := \mathbb{K}\big[X^{(\pi)}_{si}~\big|~s,i,\pi\geq 0 \big] \Big/ J,
	\end{equation}
	where $J$ is the ideal generated by graded polynomials (of cohomological degree $\omega \geq 0$) given by  
	\begin{multline}\label{graded universal poly}
		P^{(\mathfrak{A},\omega)}_{(\mu,a,p_1i_1,\ldots,p_ki_k)} 
		:=
		\sum_{u=1}^{d_{\theta}} \alpha^{\theta,u}_{\gamma_k(\mu),p_1i_1,\ldots,p_ki_k} ~X^{(\omega)}_{au}
		\\
		-
		\sum_{\substack{\varepsilon_1+\cdots+\varepsilon_k
		=\theta-\omega-|\mu|, \\ 0\leq \varepsilon_i \le p_i,~1\leq i\leq k.}}~
		\sum_{s_1=1}^{d_{p_1}} 
		\cdots 
		\sum_{s_k=1}^{d_{p_k}}	
		%\sum_{\substack{t_j=1 \\  1 \le j \le k}}^{d_{q_j}} 
		(-1)^\varrho
		\alpha^{\theta-\omega,a }_{\gamma_k(\mu),\varepsilon_1s_1,\ldots,\varepsilon_ks_k}X_{s_1 i_1}^{(p_1-\varepsilon_1)}\cdots X_{s_k i_k}^{(p_k-\varepsilon_k)},
	\end{multline}
	where $\mu \in \mathcal{P}(k)$, $p_1,\ldots,p_k \ge 0$, $\theta=p_1 + \cdots + p_k+|\mu|$, $0 \le \omega \le \theta$, $a=1,\ldots,d_{\theta-\omega}$, and $1\leq i_r\leq d_{p_r}$ for any $1\leq r\leq k$. Here, $\varrho$ in the second term of the right hand side of the expression \eqref{graded universal poly} is given by the sum 
	\begin{equation}\label{koszul_sign}
		\varrho =  \sum_{j=1}^{k-1}(\varepsilon_{j+1}+\cdots+\varepsilon_k)(p_j -\varepsilon_j) \mbox{ for any }k \ge 2,
	\end{equation}
	otherwise $\varrho = 0$. The polynomials in Equation \eqref{graded universal poly} are called the \textbf{universal graded polynomials of $\mathfrak{A}$}. We denote by $x^{(\pi)}_{si}$ the class of $X_{si}^{(\pi)}$ in the graded algebra $\mathcal{C}(\mathfrak{A})$.
	Next, we define a map 
	$\eta_{\mathfrak{A}}:\mathfrak{A}\rightarrow \mathfrak{A}\otimes \mathcal{C}(\mathfrak{A})$ by 
	\begin{equation} \label{def_eta_A}
		\eta_\mathfrak{A}(a_{pi}):=\sum_{\varepsilon =0}^p\sum_{s=1}^{d_\varepsilon} a_{\varepsilon s} \otimes x^{(p - \varepsilon)}_{si}\quad \mbox{for any } p \geq 0 ,~ i=1,2,\ldots,d_p.
	\end{equation}
	In the lemma below we show that the map $\eta_\mathfrak{A}: \mathfrak{A} \to \mathfrak{A} \otimes \mathcal{C}(\mathfrak{A})$ is a $\p$-algebra morphism. 

	\begin{lemma}\label{lemma_graded_eta_A}
		The map $\eta_\mathfrak{A}: \mathfrak{A} \to \mathfrak{A} \otimes \mathcal{C}(\mathfrak{A})$ is a $\mathcal{P}$-algebra morphism. 
	\end{lemma}

	\begin{proof}
		For any $k \ge 1$, let $a_{p_1i_1},\ldots,a_{p_ki_k} \in \mathfrak{A}$ of degree $p_1,\ldots,p_k$, respectively. To show that $\eta_\mathfrak{A}$ is a $\mathcal{P}$-algebra morphism, one needs to verify the commutativity of the following diagram for all $\mu \in \mathcal{P}(k)$.
		\begin{equation}
			\begin{tikzcd}
				{\mathfrak{A}^{\otimes k}} & {\mathfrak{A}} \\
				{(\mathfrak{A} \otimes \mathcal{C}(\mathfrak{A}))^{\otimes k}} & {\mathfrak{A} \otimes \mathcal{C}(\mathfrak{A}).}
				\arrow["{\gamma_{k}(\mu)}", from=1-1, to=1-2]
				\arrow["{\eta_{\mathfrak{A}}^{\otimes k}}"', from=1-1, to=2-1]
				\arrow["{\eta_{\mathfrak{A}}}", from=1-2, to=2-2]
				\arrow["{\overline{\gamma}_{k}(\mu)}", from=2-1, to=2-2]
			\end{tikzcd}
		\end{equation}
		Commutativity of the above diagram is obtained from the following computation:
		\begin{eqnarray*}
			\overline{\gamma}_k(\mu)
			\hspace{-0.7cm}&~&\hspace{-0.7cm} 
			\big(\eta_\mathfrak{A}(a_{p_1i_1}), \ldots
			,\eta_\mathfrak{A}(a_{p_ki_k})\big) \\
			&\stackrel{\eqref{def_eta_A}}{=}& 
			\overline{\gamma}_k(\mu) 
			\Big(\sum_{\varepsilon_1 = 0}^{p_1}\sum_{s_1=1}^{d_{\varepsilon_1}} a_{\varepsilon_1 s_1} \otimes x_{s_1i_1}^{(p_1-\varepsilon_1)}
			,\ldots, 
			\sum_{\varepsilon_k = 0}^{p_k}\sum_{s_k=1}^{d_{\varepsilon_k}} a_{\varepsilon_k s_k} \otimes x_{s_ki_k}^{(p_k-\varepsilon_k)}\Big) \\
			&\stackrel{\eqref{graded_case_gamma_bar}}{=}& 
			\sum_{\varepsilon_1=0}^{p_1} \cdots \sum_{\varepsilon_k=0}^{p_k}
			\sum_{s_1=1}^{d_{p_1}} \cdots 
			\sum_{s_k=1}^{d_{p_k}} 
			(-1)^{\varrho} \gamma_k(\mu) (a_{\varepsilon_1s_1},\ldots,a_{\varepsilon_ks_k}) 
			\otimes 
			x_{s_1i_1}^{(p_1-\varepsilon_1)}
			\cdots 
			~x_{s_ki_k}^{(p_k-\varepsilon_k)} \\
			&\stackrel{\eqref{struc_const_graded}}{=}& 
			\sum_{\varepsilon_1=0}^{p_1} \cdots \sum_{\varepsilon_k=0}^{p_k}
			\sum_{s_1=1}^{d_{p_1}} \cdots 
			\sum_{s_k=1}^{d_{p_k}}
			\sum_{r=1}^{d_{\varepsilon_1 + \cdots + \varepsilon_k + |\mu|}} 
			(-1)^\varrho
			\alpha_{\gamma_k(\mu),\varepsilon_1s_1,\ldots,\varepsilon_ks_k}^{\varepsilon_1 + \cdots + \varepsilon_k + |\mu|,r} 
			a_{(\varepsilon_1 + \cdots + \varepsilon_k + |\mu|)r}
			\otimes
			x_{s_1i_1}^{(p_1-\varepsilon_1)}
			\cdots 
			~x_{s_ki_k}^{(p_k-\varepsilon_k)} \\
			&=& 
			\sum_{\lambda = |\mu|}^{p_1+\cdots+p_k+|\mu|}
			\sum_{\substack{\varepsilon_1 + \cdots + \varepsilon_k = \lambda - |\mu|,\\
			0 \le \varepsilon_i \le p_i,~
			1 \le i \le k.}} 
			~\sum_{s_1=1}^{d_{p_1}} \cdots 
			\sum_{s_k=1}^{d_{p_k}}
			\sum_{r=1}^{d_{\lambda}} 
			(-1)^\varrho
			\alpha_{\gamma_k(\mu),\varepsilon_1s_1,\ldots,\varepsilon_ks_k}^{\lambda, r}
			a_{\lambda r}
			\otimes 
			x_{s_1i_1}^{(p_1-\varepsilon_1)}
			\cdots 
			~x_{s_ki_k}^{(p_k-\varepsilon_k)} \\
			&=& 
			\sum_{\lambda=|\mu|}^{p_1+\cdots+p_k+|\mu|}
			\sum_{r=1}^{d_{\lambda}}
			a_{\lambda r}~
			\otimes
			\sum_{\substack{\varepsilon_1 + \cdots		+\varepsilon_k = \lambda - |\mu|,\\
			0 \le \varepsilon_i \le p_i,~
			1 \le i \le k.}} 
			~\sum_{s_1=1}^{d_{p_1}} \cdots 
			\sum_{s_k=1}^{d_{p_k}}
			(-1)^\varrho
			\alpha_{\gamma_k(\mu),\varepsilon_1s_1,\ldots,\varepsilon_ks_k}^{\lambda, r}
			x_{s_1i_1}^{(p_1-\varepsilon_1)}
			\cdots 
			~x_{s_ki_k}^{(p_k-\varepsilon_k)} \\
			&\stackrel{\eqref{graded universal poly}}{=}&
			\sum_{\lambda = |\mu|}^{\theta}
			\sum_{r=1}^{d_{\lambda}}
			a_{\lambda r}
			~\otimes~
			\sum_{u=1}^{d_{\theta}} \alpha_{\gamma_k(\mu),p_1i_1,\ldots,p_ki_k}^{\theta,u} x_{ru}^{(\theta-\lambda)}   
			\\
			&=& 
			\sum_{\lambda = 0}^{\theta}
			\sum_{r=1}^{d_{\lambda}}
			a_{\lambda r}
			\otimes 
			\sum_{u=1}^{d_{\theta}} \alpha_{\gamma_k(\mu),p_1i_1,\ldots,p_ki_k}^{\theta,u} x_{ru}^{(\theta-\lambda)}
			\quad 
			\Big(\sum_{u=1}^{d_{\theta}} \alpha^{\theta,u}_{\gamma_k(\mu),p_1i_1,\ldots,p_ki_k} ~x^{( \theta-\lambda)}_{ru}=0,~ \mbox{for any }~ 0\leq \lambda \leq |\mu|-1 \Big)\\
			&=& 
			\sum_{u = 1}^{d_{\theta}} \alpha_{\gamma_k(\mu),p_1i_1,\ldots,p_ki_k}^{\theta,u}
			\Big(
			\sum_{\lambda = 0}^{\theta}
			\sum_{r=1}^{d_{\lambda}}
			a_{\lambda r}
			\otimes 
			x_{ru}^{(\theta-\lambda)}
			\Big) \\
			&\stackrel{\eqref{def_eta_A}}{=}& 
			\sum_{u = 1}^{d_{\theta}} \alpha_{\gamma_k(\mu),p_1i_1,\ldots,p_ki_k}^{\theta,u}
			~\eta_{\mathfrak{A}}\big(a_{\theta u}\big) \qquad 
			\\
			&=& 
			\eta_\mathfrak{A}
			\Big(\sum_{u = 1}^{d_{\theta}} \alpha_{\gamma_k(\mu),p_1i_1,\ldots,p_ki_k}^{\theta,u} ~a_{\theta u}\Big) 
			~\stackrel{\eqref{struc_const_graded}}{=}~
			\eta_\mathfrak{A} \big(\gamma_k(\mu)(a_{p_1i_1},\ldots,a_{p_ki_k})\big).
		\end{eqnarray*}
		Hence, the map $\eta_\mathfrak{A}:\mathfrak{A} \to \mathfrak{A} \otimes \mathcal{C}(\mathfrak{A})$ is a $\p$-algebra morphism. 
	\end{proof}

	Next, in the proposition below we show that the graded algebra $\mathcal{C}(\mathfrak{A})$ satisfies the following universal property. Thus, making $\mathcal{C}(\mathfrak{A})$ the \textbf{universal graded algebra of $\mathfrak{A}$}.

	\begin{prop}\label{Thm_univ_prop_graded_algebras}
		%Let $\g$ be a graded operad and $\mathfrak{A}=\oplus_{p \ge 0} \mathfrak{A}_p$ be a $\g$-algebra with $\mathrm{dim} \mathfrak{A}_p < \infty$, for each $p \ge 0$. Then, 
		For any graded commutative algebra $C$ and a $\mathcal{P}$-algebra morphism $f: \mathfrak{A} \to \mathfrak{A} \otimes C$, there exists a unique graded commutative algebra morphism $\Phi: \mathcal{C}(\mathfrak{A}) \to C$ such that $f = (\mathrm{id} \otimes \Phi) \circ \eta_{\mathfrak{A}}$. In other words, the following diagram commutes. 
		\begin{equation}\label{Com-diag-graded-case}
			\begin{tikzcd}
				{\mathfrak{A}} & {\mathfrak{A} \otimes \mathcal{C}(\mathfrak{A})} \\
				& {\mathfrak{A} \otimes C.}
				\arrow["{\eta_\mathfrak{A}}", from=1-1, to=1-2]
				\arrow["f"', from=1-1, to=2-2]
				\arrow["{\mathrm{id} \otimes \Phi}", from=1-2, to=2-2]
			\end{tikzcd}
		\end{equation}
	\end{prop}

	\begin{proof}		
		For any homogeneous element $a_{pi} \in \mathfrak{A}$, there exists a finite subset $\cup_{0 \le \varepsilon \le p}\big\{c^{(p-\varepsilon)}_{si} \in C_{p-\varepsilon}~\big|~ s = 1 ,\ldots,d_{\varepsilon}\big\} \subset C$ such that the following equation holds: 
		\begin{equation}
		f(a_{p i}) =
		\sum_{\varepsilon =0}^p
		\sum_{s=1}^{d_\varepsilon} 
		a_{\varepsilon s} 
		\otimes 
		c^{(p - \varepsilon )}_{si}.
		\end{equation}
		Now, since the map $f:\mathfrak{A}\rightarrow \mathfrak{A}\otimes C$ is a graded $\mathcal{P}$-algebra morphism, for any homogeneous elements $a_{p_1i_1},\ldots,a_{p_ki_k} \in \mathfrak{A}$, and $\mu \in \mathcal{P}(k)$ we obtain,
		\begin{equation*}
			f\big(\gamma_k(\mu)(a_{p_1i_1},\ldots,a_{p_ki_k})\big) ~=~ \gamma_k(\mu)\big(f(a_{p_1i_1}),\ldots,f(a_{p_ki_k})\big).
		\end{equation*} 
		%the elements of the set $\big\{c^{(\kappa)}_{st} ~\big|~ \kappa,s,t\geq 0\big\} \subset C$ satisfy the following expressions 
		Evaluating the above equation we get 
		\begin{equation}\label{relations_graded_on_csi}
			\sum_{u=1}^{d_\theta} \alpha^{\theta,u}_{\gamma_k(\mu),p_1i_1,\ldots,p_ki_k} c^{(\theta - \lambda)}_{au}
		\hspace{0.2cm} =
		\sum_{\substack{\varepsilon_1+\cdots+\varepsilon_k=\lambda-|\mu|, \\ 0\leq \varepsilon_i \le p_i,~1\leq i\leq k.}}~
		\sum_{s_1=1}^{d_{p_1}}\cdots
		\sum_{s_k=1}^{d_{p_k}} 	
		%\sum_{\substack{t_j=1 \\  1 \le j \le k}}^{d_{q_j}} 
		(-1)^\varrho \alpha^{\lambda,a }_{\gamma_k(\mu),\varepsilon_1s_1,\ldots,\varepsilon_ks_k}c_{s_1 i_1}^{(p_1-\varepsilon_1)}\cdots c_{s_k i_k}^{(p_k-\varepsilon_k)},
		\end{equation}
		where $\theta=p_1 + \cdots + p_k+|\mu|$, $0 \le \lambda \le \theta$, and $a=1,\ldots,d_\theta$. Subsequently, the association $x^{(\pi)}_{si}\mapsto c^{(\pi)}_{si}$ induces a unique graded commutative algebra morphism ${\Phi}:\mathcal{C}(\mathfrak{A})\rightarrow C$ for which Diagram \eqref{Com-diag-graded-case} commutes. Thereby, the proof is complete. 
	\end{proof}

 We now prove the Theorem \ref{thm_left_adjoint} in the graded context. 

	\begin{theorem}\label{thm_graded_left_adjoint}
		Let $\p$ be a graded operad and $\mathfrak{A}=\oplus_{p \ge 0}\mathfrak{A}_p \in \p$-algebra. The functor $\mathfrak{A}\otimes -: \mathrm{g}$-$\mathrm{ComAlg} \to \mathcal{P}$-Alg admits a left adjoint if and only if $\mathfrak{A}_p$ is finite-dimensional for each $p \ge 0$.
	\end{theorem}

	\begin{proof}
Let $\p$ be a graded operad and $\mathfrak{A}=\oplus_{p \ge 0}\mathfrak{A}_p \in \p$-algebra such that $\mathfrak{A}_p$ is finite-dimensional for each $p \ge 0$.	Similar to the construction of the universal graded algebra $\mathcal{C}(\mathfrak{A})$, one can construct a functor $\mathcal{C}(\mathfrak{A},-):\mathcal{P}$-Alg $\to \mathrm{g}$-$\mathrm{ComAlg}$.

Conversely, assume that the functor $\mathfrak{A}\otimes -: \mathrm{g}$-$\mathrm{ComAlg} \to \mathcal{P}$-Alg admits a left adjoint. Let us first observe that the product of a family of graded vector spaces $\{\mathfrak{A}^i,~i\in I\}$ is given by a graded vector space $\prod_{i \in I} \mathfrak{A}^i$ with the homogeneous component of degree $p$ defined as $$\big(\prod_{i \in I} \mathfrak{A}^i\big)_p:=\{(a^i)_{i \in I} : |a^i|=p \mbox{ in } \mathfrak{A}^i, \text{ for all } i \in I\}.$$
Furthermore, it easily follows that in the category $\p$-Alg for a graded operad $\p$, the products are same as the products of the underlying graded vector spaces. Since the functor $\fa \otimes-$ admits a left adjoint,  it preserves arbitrary products in $\mathrm{g}$-$\mathrm{ComAlg}$.  Let us consider $\mathbb{K}$ as a graded commutative algebra concentrated in degree zero. 
Then by assumption $\mathfrak{A} \otimes -$ preserves the product of countable copies of $\K$ in $\mathrm{g}$-$\mathrm{ComAlg}$. By the definition of the product of graded vector spaces, we have 
$$\big( \mathfrak{A}\otimes \prod_{i \geq 0}\mathbb{K}^i\big)_p= \prod_{i \geq 0} (\mathfrak{A}_p\otimes \mathbb{K}^i). $$  
Hence, $\mathfrak{A} \otimes -$ preserves the product of countable copies of $\K$ in $\mathrm{g}$-$\mathrm{ComAlg}$ only if $\mathfrak{A}$ is finite-dimensional in each homogeneous component. 
	\end{proof}

