\section{\large An Enrichment of the category $\p$-$\mathrm{FinAlg}$ over the dual category of $\mathrm{ComAlg}$} \label{sec-4}

	In this section, we prove that the category $\p$-FinAlg of all finite-dimensional $\p$-algebras is enriched over the monoidal category $(\mathrm{ComAlg}^{\mathrm{op}},\otimes, \mathbb{K},\alpha,l,r)$, where $\mathrm{ComAlg}^{\mathrm{op}}$ the dual category of $\mathrm{ComAlg}$. Subsequently, we show that $\mathcal{C}(\mathfrak{a})$ possesses a unique bialgebra structure, making it the initial object in the category of all the commutative bialgebras coacting on the $\p$-algebra $\mathfrak{a}$.
	Before proceeding, we recall the notion of enriched category.
	\begin{definition}\cite[Section 1.2, pg 8]{Kelly}
		Let $(\mathcal{M},\otimes, I, \alpha,l,r)$ be a monoidal category. 
		Then an $\mathcal{M}$-category (or a category enriched over $\mathcal{M}$) is a category $\mathcal{C}$ consisting of
		\begin{itemize}
			\item a class $ob(\mathcal{C})$ of objects, 
			\item a hom-object $\mathcal{M}(\fa,\mathfrak{b}) \in \mathcal{M}$ for each pair of objects $\fa,\mathfrak{b}$ in $\mathcal{C}$,
			\item a composition morphism  $\circ_{\fa,\mathfrak{b},\mathfrak{c}}: \mathcal{M}(\mathfrak{b},\mathfrak{c}) \otimes \mathcal{M}(\mathfrak{a},\mathfrak{b}) \to \mathcal{M}(\mathfrak{a},\mathfrak{c})$ in $\mathcal{M}$ for each triple of objects $\fa,\mathfrak{b},\mathfrak{c} \in \mathcal{C}$. Additionally, for any $\fa,\mathfrak{b},\mathfrak{c},\mathfrak{d} \in \mathcal{C}$ the composition morphisms should the associativity condition as described by the commutative diagram below:
			\begin{equation}\label{diag4.1}
				\begin{tikzcd}
					& 	{\mathcal{M}(\mathfrak{a},\mathfrak{d})} \\
					{\mathcal{M}(\mathfrak{b},\mathfrak{d}) 	\otimes \mathcal{M}(\mathfrak{a},\mathfrak{b})} && {\mathcal{M}(\mathfrak{c},\mathfrak{d}) \otimes \mathcal{M}(\mathfrak{a},\mathfrak{c})} \\
					{\big(\mathcal{M}(\mathfrak{c},\mathfrak{d})\otimes\mathcal{M}(\mathfrak{b},\mathfrak{c})\big)\otimes \mathcal{M}(\mathfrak{a},\mathfrak{b})} && {\mathcal{M}(\mathfrak{c},\mathfrak{d}) \otimes \big(\mathcal{M}(\mathfrak{b},\mathfrak{c}) \otimes \mathcal{M}(\mathfrak{a},\mathfrak{b})\big).}
					\arrow["{{\circ_{\mathfrak{a},\mathfrak{b},\mathfrak{d}}}}"', from=2-1, to=1-2]
					\arrow["{{\circ_{\mathfrak{a},\mathfrak{c},\mathfrak{d}}}}", from=2-3, to=1-2]
					\arrow["{{\circ_{\mathfrak{b},\mathfrak{c},\mathfrak{d}} \otimes \mathrm{id}}}"', from=3-1, to=2-1]
					\arrow["\alpha", from=3-1, to=3-3]
					\arrow["{{\mathrm{id} \otimes \circ_{\mathfrak{a},\mathfrak{b},\mathfrak{c}}}}", from=3-3, to=2-3]
				\end{tikzcd} 
			\end{equation}  

			\item an identity morphism $\varepsilon_\fa:I \to \mathcal{M}(\fa,\fa)$ for each object $\fa \in \mathcal{C}$ there exists such that the following diagrams commute:
			\begin{equation}\label{diag4.2}
					\begin{tikzcd}
					{\mathcal{M}(\mathfrak{a},\mathfrak{b})} & {\mathcal{M}(\mathfrak{a},\mathfrak{b}) \otimes \mathcal{M}(\mathfrak{a},\mathfrak{a})} && {\mathcal{M}(\mathfrak{a},\mathfrak{b})} & {\mathcal{M}(\mathfrak{b},\mathfrak{b}) \otimes \mathcal{M}(\mathfrak{a},\mathfrak{b})} \\
					& 	{\mathcal{M}(\mathfrak{a},\mathfrak{b}) \otimes \mathbb{K}} &&& {\mathbb{K}\otimes \mathcal{M}(\mathfrak{a},\mathfrak{b}).}
					\arrow["{{\circ_{\mathfrak{a},\mathfrak{a},\mathfrak{b}}}}"', from=1-2, to=1-1]
					\arrow["{{\circ_{\mathfrak{a},\mathfrak{b},\mathfrak{b}}}}"', from=1-5, to=1-4]
					\arrow["r", from=2-2, to=1-1]
					\arrow["{{\mathrm{id} \otimes 	\varepsilon_\mathfrak{a} }}"', from=2-2, to=1-2]
					\arrow["l", from=2-5, to=1-4]
					\arrow["{{\varepsilon_\mathfrak{b} 	\otimes  \mathrm{id} }}"', from=2-5, to=1-5]
				\end{tikzcd}
			\end{equation}
		\end{itemize}  
	\end{definition}

	\begin{theorem}
		Let $\mathrm{ComAlg}^{\mathrm{op}}$ be the dual category of $\mathrm{ComAlg}$. The category of all finite-dimensional $\p$-algebras is enriched over the monoidal category $(\mathrm{ComAlg}^{\mathrm{op}},\otimes, \mathbb{K},\alpha,l,r)$.
	\end{theorem}

	\begin{proof}
		In order to show that the category $\p$-FinAlg is enriched over the monoidal category $(\mathrm{ComAlg}^{\mathrm{op}},\otimes, \mathbb{K},\alpha,l,r)$, we need to find a hom-object $\mathcal{M}(\mathfrak{a},\mathfrak{b})$ in $\mathrm{ComAlg}^{\mathrm{op}}$ for any $\mathfrak{a},\mathfrak{b}\in \p$-FinAlg such that 
		\begin{itemize}
			\item[(1)]  morphisms $f: \mathfrak{a} \to \mathfrak{b}$ in the enriched category structure on $\p$-FinAlg are given by morphisms $f: \K \to \mathcal{M}(\mathfrak{a},\mathfrak{b})$ in  $\mathrm{ComAlg}^{\mathrm{op}}$.

			\item[(2)] for each object $\mathfrak{a}$ in $\p$-FinAlg, we must have a morphism $\varepsilon_\mathfrak{a}: \K \to \mathcal{M}(\mathfrak{a},\mathfrak{a})$ in $\mathrm{ComAlg}^{\mathrm{op}}$ which is called the identity morphism.

			\item[(3)] for any object $\fa,\mathfrak{b},\mathfrak{c}$ there exists a  composition morphism $\circ_{\mathfrak{a},\mathfrak{b},\mathfrak{c}}: \mathcal{M}(\mathfrak{b},\mathfrak{c}) \otimes \mathcal{M}(\mathfrak{a},\mathfrak{b})\to \mathcal{M}(\mathfrak{a},\mathfrak{c})$ in $\mathrm{ComAlg}^{\mathrm{op}}$ for $\mathfrak{a},\mathfrak{b},\mathfrak{c}\in \p$-FinAlg for which Diagram \eqref{diag4.1} commutes. 
			%\begin{equation}\label{diag4.1}
			%	\begin{tikzcd}
			%		& 	{\mathcal{M}(\mathfrak{a},\mathfrak{d})} \\
			%		{\mathcal{M}(\mathfrak{b},\mathfrak{d}) 	\otimes \mathcal{M}(\mathfrak{a},\mathfrak{b})} && {\mathcal{M}(\mathfrak{c},\mathfrak{d}) \otimes \mathcal{M}(\mathfrak{a},\mathfrak{c})} \\
			%		{\big(\mathcal{M}(\mathfrak{c},\mathfrak{d})\otimes\mathcal{M}(\mathfrak{b},\mathfrak{c})\big)\otimes \mathcal{M}(\mathfrak{a},\mathfrak{b})} && {\mathcal{M}(\mathfrak{c},\mathfrak{d}) \otimes \big(\mathcal{M}(\mathfrak{b},\mathfrak{c}) \otimes \mathcal{M}(\mathfrak{a},\mathfrak{b})\big).}
			%		\arrow["{{\circ_{\mathfrak{a},\mathfrak{b},\mathfrak{d}}}}"', from=2-1, to=1-2]
			%		\arrow["{{\circ_{\mathfrak{a},\mathfrak{c},\mathfrak{d}}}}", from=2-3, to=1-2]
			%		\arrow["{{\circ_{\mathfrak{b},\mathfrak{c},\mathfrak{d}} \otimes \mathrm{id}}}"', from=3-1, to=2-1]
			%		\arrow["\alpha", from=3-1, to=3-3]
			%		\arrow["{{\mathrm{id} \otimes \circ_{\mathfrak{a},\mathfrak{b},\mathfrak{c}}}}", from=3-3, to=2-3]
			%	\end{tikzcd}
			%\end{equation}
			Additionally, for $\mathfrak{a},\mathfrak{b}\in \p$-FinAlg the composition morphisms $\circ_{\mathfrak{a},\mathfrak{a},\mathfrak{b}},\circ_{\mathfrak{a},\mathfrak{b},\mathfrak{b}}$ and the identity morphisms $\varepsilon_{\mathfrak{a}},\varepsilon_{\mathfrak{b}}$  makes Diagram \eqref{diag4.2} commutative.
			%\begin{equation}\label{diag4.2}
			%	\begin{tikzcd}
			%		{\mathcal{M}(\mathfrak{a},\mathfrak{b})} & {\mathcal{M}(\mathfrak{a},\mathfrak{b}) \otimes \mathcal{M}(\mathfrak{a},\mathfrak{a})} && {\mathcal{M}(\mathfrak{a},\mathfrak{b})} & {\mathcal{M}(\mathfrak{b},\mathfrak{b}) \otimes \mathcal{M}(\mathfrak{a},\mathfrak{b})} \\
			%		& 	{\mathcal{M}(\mathfrak{a},\mathfrak{b}) \otimes \mathbb{K}} &&& {\mathbb{K}\otimes \mathcal{M}(\mathfrak{a},\mathfrak{b}).}
			%		\arrow["{{\circ_{\mathfrak{a},\mathfrak{a},\mathfrak{b}}}}"', from=1-2, to=1-1]
			%		\arrow["{{\circ_{\mathfrak{a},\mathfrak{b},\mathfrak{b}}}}"', from=1-5, to=1-4]
			%		\arrow["r", from=2-2, to=1-1]
			%		\arrow["{{\mathrm{id} \otimes 	\varepsilon_\mathfrak{a} }}"', from=2-2, to=1-2]
			%		\arrow["l", from=2-5, to=1-4]
