			%		\end{tikzcd}
			%\end{equation}
 		\end{itemize}	

 		\medskip
		Now, we step-by-step show that the universal construction done in Section \ref{sec-3} leads to an enrichment of $\p$-FinAlg. First, for any two objects $\mathfrak{a}$ and $\mathfrak{b}$ in $\p$-FinAlg, we fix the required object $\mathcal{M}(\mathfrak{a},\mathfrak{b})$ to be the universal object $\mathcal{C}(\mathfrak{b},\mathfrak{a})$ constructed in the proof of Theorem \ref{thm_left_adjoint}. Then, the morphism set from $\mathfrak{a}$ to $\mathfrak{b}$ in the enriched category structure on $\p$-FinAlg is defined to be $\mathrm{Hom}_{\mathrm{ComAlg^{\mathrm{op}}}}(\K,\mathcal{C}(\mathfrak{b},\mathfrak{a}))$. Note that using the universal property of $\mathcal{C}(\mathfrak{a},\mathfrak{b})$ obtained from the  proof of Theorem \ref{thm_left_adjoint} we get a bijective correspondence
		\begin{equation*}
			\mathrm{Hom}_{\p\text{-}\mathrm{FinAlg}}(\mathfrak{a},\mathfrak{b})  \longleftrightarrow \mathrm{Hom}_{\mathrm{ComAlg^{\mathrm{op}}}}\big(\K,\mathcal{C}(\mathfrak{b},\mathfrak{a})\big).
		\end{equation*}

		Next, for any object $\fa \in \p$-FinAlg, the $\p$-algebra morphism 
		$\eta_{\fa,\fa}:\fa \to \fa \otimes \mathcal{C}(\fa)$ (cf. Equation \eqref{thm_def_eta_b}) uniquely determines an algebra morphism $\varepsilon_\fa: \mathcal{C}(\fa) \to \K$ making the following diagram commutative 
		\begin{equation}\label{diag_coidentity}
			\begin{tikzcd}
				{\mathfrak{a}} & {\fa \otimes \mathcal{C}(\fa)} \\
				& {\fa \otimes \mathbb{K}}
				\arrow["{\eta_{\mathfrak{a},\fa}}", from=1-1, to=1-2]
				\arrow["\mathrm{i}"', from=1-1, to=2-2]
				\arrow["{id \otimes \varepsilon_{\fa}}", from=1-2, to=2-2]
			\end{tikzcd}
		\end{equation} 
		where $\mathrm{i}:\fa \to \fa \otimes \mathbb{K}$ is the canonical isomorphism from $\mathfrak{a}$ to $\fa \otimes \mathbb{K}$.  
		Evaluating the above diagram we get 
		\begin{equation}\label{def_epsilon_id}
			\varepsilon_\fa(x_{st})=\delta_{s,t} \quad \text{for all }s,t=1,2,\ldots,\mathrm{dim}~\fa.
		\end{equation}
		Thus, for any object $\fa$ in $\p$-FinAlg there exists a morphism $\varepsilon_\fa \in \mathrm{Hom}_{\mathrm{ComAlg}^{\mathrm{op}}}\big(\mathbb{K},\mathcal{C}(\mathfrak{a})\big)$ which serves as the identity morphism for $\fa$ in the enriched category.

		\medskip
		Finally, for any objects $\fa$, $\mathfrak{b}$, and $\mathfrak{c}$ in $\p$-FinAlg, 
		consider the linear map $f_\mathfrak{c}:\mathfrak{c}\rightarrow \fa\otimes \mathcal{C}(\fa,\mathfrak{b})\otimes \mathcal{C}(\mathfrak{b},\mathfrak{c})$ defined by
		\begin{equation}
			f_\mathfrak{c}:\mathfrak{c}
			\xrightarrow{\eta_{\mathfrak{c},\mathfrak{b}}}\mathfrak{b}\otimes \mathcal{C}(\mathfrak{b},\mathfrak{c}) \xrightarrow{\eta_{\mathfrak{b},\fa}\otimes \mathrm{id}} \fa\otimes \mathcal{C}(\fa,\mathfrak{b})\otimes \mathcal{C}(\mathfrak{b},\mathfrak{c}). 
			%\xrightarrow{\mathrm{id} \otimes \mathrm{tw}} 
			%\mathfrak{a} \otimes \mathcal{C}(\mathfrak{b},\mathfrak{c}) \otimes \mathcal{C}(\mathfrak{a},\mathfrak{b}),
		\end{equation}
		One can verify that $f_\mathfrak{c}$ is a $\p$-algebra morphism. Using the universal property of $\eta_{\mathfrak{c},\mathfrak{a}}: \mathfrak{c} \to \mathfrak{a} \otimes \mathcal{C}(\mathfrak{a},\mathfrak{c})$ we get an algebra morphism $\Delta_{\mathfrak{a},\mathfrak{b},\mathfrak{c}}: \mathcal{C}(\mathfrak{a}, \mathfrak{c}) \to \mathcal{C}(\fa,\mathfrak{b})\otimes \mathcal{C}(\mathfrak{b},\mathfrak{c})$ for which the following diagram is commutative
		\begin{equation}\label{diag_coen_id2}
			\begin{tikzcd}
				{\mathfrak{c}} & {\mathfrak{a} \otimes \mathcal{C}(\mathfrak{a},\mathfrak{c})} \\
				& {\mathfrak{a} 
					\otimes \mathcal{C}(\mathfrak{a},\mathfrak{b}) \otimes \mathcal{C}(\mathfrak{b},\mathfrak{c}).}
				\arrow["{\eta_{\mathfrak{c},\mathfrak{a}}}", from=1-1, to=1-2]
				\arrow["{f_\mathfrak{c}}"', from=1-1, to=2-2]
				\arrow["{\mathrm{id} \otimes \Delta_{\mathfrak{a},\mathfrak{b},\mathfrak{c}}}", from=1-2, to=2-2]
			\end{tikzcd}
		\end{equation}
		Let $x_{ij},~x_{ij}^\prime,$ and $x_{ij}^{\prime\prime}$ denote the equivalence classes in the algebras $\mathcal{C}(\mathfrak{a},\mathfrak{c}),$ $\mathcal{C}(\mathfrak{a},\mathfrak{b}),$ and $\mathcal{C}(\mathfrak{b},\mathfrak{c}),$ respectively. Then, evaluating the above diagram, the map $\Delta_{\fa,\mathfrak{b},\mathfrak{c}}$ can be described by the following expression:
		\begin{equation}\label{def_delta_abc}
			\Delta_{\fa,\mathfrak{b},\mathfrak{c}} (x_{st}) ~=~ \sum_{i=1}^{m} x_{si}^\prime \otimes x_{it}^{\prime\prime}, 
		\end{equation}
		for any $s=1,\ldots,\mathrm{dim}~\fa$ and $t = 1,\ldots, \mathrm{dim}~\mathfrak{c}$, where $m=\mathrm{dim}~\mathfrak{b}$. 
		Using Equation \eqref{def_delta_abc} we get, for any objects $\mathfrak{a}$, $\mathfrak{b}$, $\mathfrak{c}$, $\mathfrak{d}$ in $\p$-FinAlg the Diagram \eqref{diag4.1} is commutative, where we define the composition $\circ_{a,b,c}:=\Delta_{c,b,a}^{op}$. Similarly, using Equation \eqref{def_epsilon_id} and \eqref{def_delta_abc} one can also verify that Diagram \eqref{diag4.2} commutes. Therefore, the category $\p$-FinAlg is enriched over the  monoidal category $(\mathrm{ComAlg}^{\mathrm{op}}, \otimes, \mathbb{K},\alpha,l,r)$.
	\end{proof}

	\begin{theorem}
		Let $\fa$ be an object in $\p$-FinAlg. Then there exists a unique bialgebra structure on $\mathcal{C}(\fa)$ such that the $\p$-algebra morphism $\eta_\fa : \fa \to \fa \otimes \mathcal{C}(\fa)$ defines a right $\mathcal{C}(\fa)$-comodule structure on $\fa$.
	\end{theorem}

	\begin{proof}
		Taking $\fa=\mathfrak{b}=\mathfrak{c}$ in Diagram \eqref{diag_coen_id2}, we get a unique algebra morphism $\Delta_{\fa}:\mathcal{C}(\fa)\rightarrow\mathcal{C}(\fa)\otimes\mathcal{C}(\fa)$ defined as 
		\begin{equation}
			\Delta_\fa(x_{st})=\sum_{i=1}^n x_{si}\otimes x_{it} \quad \text{for all}~ s,t=1,2,\ldots, n.
		\end{equation}
		Using it we get that the following diagram is commutative 
		\begin{equation}\label{comodule action 1}
			\begin{CD}
				\fa @>\eta_\fa>> \fa\otimes \mathcal{C}(\fa)\\
				@V \eta_\fa VV @V \mathrm{id}\otimes \Delta_\fa VV\\
				\fa\otimes \mathcal{C}(\fa)@>\eta_\fa\otimes \mathrm{id}>> \fa\otimes \mathcal{C}(\fa)\otimes\mathcal{C}(\fa).
			\end{CD}
		\end{equation}
		Furthermore, note that Diagram \eqref{diag_coidentity} guarantees the existence of coidentity map 
		$\varepsilon_\fa:\mathcal{C}(\fa)\rightarrow \mathbb{K}$ given by
		\begin{equation}
			\varepsilon_\fa(x_{st})=\delta_{s,t} \quad \text{for all }s,t=1,2,\ldots,n.
		\end{equation}
		Thus, making $\mathcal{C}(\fa)$ a bialgebra with coproduct $\Delta_\fa$ and counit $\varepsilon_\fa$. Also note that, Diagram \eqref{comodule action 1} implies that $\eta_\fa:\fa\rightarrow \fa\otimes \mathcal{C}(\fa)$ defines a right $\mathcal{C}(\fa)$-comodule structure on $\fa$. 
	\end{proof}

	\begin{remark}\label{universal bialgebra const}
		The universal property of $\eta_\fa: \fa \to \fa \otimes \mathcal{C}(\fa)$ stated in Corollary \ref{cor_univ_prop} extends to bialgebras in the following way: For any commutative bialgebra $C$ with $C$-comodule action $\psi:\fa\rightarrow \fa\otimes C,$ there exists a unique bialgebra homomorphism $\Phi:\mathcal{C}(\fa)\rightarrow C$ such that the following diagram commutes
 		\begin{equation}\label{universal bialgebra prop}
 			\begin{tikzcd}
 				\fa & {\fa \otimes \mathcal{C}(\fa)} \\
 				& C.
 				\arrow["{\eta_\fa}", from=1-1, to=1-2]
 				\arrow["\psi"', from=1-1, to=2-2]
 				\arrow["{\mathrm{id} \otimes \Phi}", from=1-2, to=2-2]
 			\end{tikzcd} 
		\end{equation}
	\end{remark}

	We recall from \cite{Takeuchi} that, one can construct a free commutative Hopf algebra from a commutative bialgebra. The construction defines a functor $L: \operatorname{ComBiAlg} \to \operatorname{ComHopf}$ that is left adjoint to the forgetful functor $U:\operatorname{ComHopf} \to \operatorname{ComBiAlg}$. We denote by $\mu:\mathds{1}_{\operatorname{ComBiAlg}} \to UL,$ the unit of the adjunction $L \dashv U$. More precisely, for any $\p$-algebra $\fa$, the associated Hopf algebra $\mathcal{H}(\fa)$ and the comodule action $\lambda_\fa:\fa\rightarrow\fa\otimes \mathcal{H}(\fa)$ is defined as follows: 
	$$\mathcal{H}(\fa):=L(\mathcal{C}(\fa)),\quad\text{and}\quad\lambda_\fa:=(\mathrm{id}\otimes \mu_{\mathcal{C}(\fa)})\circ \eta_\fa.$$
	Furthermore, there exists an initial object $(\mathcal{H}(\fa),\lambda_\fa)$ in the category of all commutative Hopf algebras coacting on the finite-dimensional $\p$-algebra $\fa$. With the above discussion in mind, we state our next result.

	\begin{theorem}
		Let $H$ be a commutative Hopf algebra with right $H$-comodule action $\psi:\fa\rightarrow \fa\otimes H,$ then there exists a unique Hopf algebra homomorphism $\Phi:\mathcal{H}(\fa)\rightarrow H$ such that 
 		\begin{equation}\label{universal hopf prop}
 			\xymatrix{
			\mathfrak{a} \ar[r]^-{\lambda_\mathfrak{a}}\ar[rd]_\psi 
			&\fa\otimes \mathcal{H}(\fa)\ar[d]^{\mathrm{id}\otimes \Phi}\\
			&\fa\otimes H} 
		\end{equation}
	\end{theorem}

	\begin{proof}
		The proof is straightforward and similar to the proof given in \cite[Theorem 2.13]{Ag-Mil}.
	\end{proof}

