			~=~
			\overbrace{\sum_{u=1}^n \alpha^u_{\gamma_3(\mu \circ_1 \nu),i_{\sigma(1)},i_{\sigma(2)},i_{\sigma(3)}} X_{iu}}^{(A)} 
			\quad - ~
			\underbrace{\sum_{s_{1},s_{2},s_{3}=1}^n 
				\alpha^i_{\gamma_3(\mu\circ_1 \nu),s_1,s_2,s_3} X_{s_1i_{i_{\sigma(1)}}} X_{s_2i_{i_{\sigma(2)}}} X_{s_3i_{i_{\sigma(3)}}}}_{(B)}
		\end{equation*}
		Expanding $(A)$ we get: 
		\begin{eqnarray*}
			\sum_{u=1}^n \alpha^u_{\gamma_3(\mu \circ_1 \nu),i_{\sigma(1)},i_{\sigma(2)},i_{\sigma(3)}} X_{iu} 
			&=& 
			\sum_{u=1}^n \Big(\sum_{p=1}^n 	\alpha^p_{\gamma_2(\nu),i_{\sigma(1)},i_{\sigma(2)}}
			~ \alpha^u_{\gamma_{2}(\mu),p,i_{\sigma(3)}}\Big)X_{iu} \\
			&=&
			\sum_{p=1}^n \alpha^p_{\gamma_2(\nu),i_{\sigma(1)},i_{\sigma(2)}}
			\Big(\sum_{u=1}^n \alpha^u_{\gamma_{2}(\mu),p,i_{\sigma(3)}} X_{iu}\Big) \\
			&\stackrel{(\ref{freeOperad_eqn_univ_poly_rel_P2})}{=}& 
			\sum_{p=1}^n \alpha^p_{\gamma_2(\nu),i_{\sigma(1)},i_{\sigma(2)}}
			\Big(\sum_{s_1,s_2=1}^n 
			\alpha^i_{\gamma_2(\mu),s_1,s_2} X_{s_1p}X_{s_2i_{\sigma(3)}}\Big)
		\end{eqnarray*}
		Expanding $(B)$ we get: 
		\begin{eqnarray*}
			\sum_{s_1,s_2,s_3=1}^n \alpha^i_{\gamma_3(\mu \circ_1 \nu),s_1,s_2,s_3} X_{s_1i_{\sigma(1)}} X_{s_2i_{\sigma(2)}} X_{s_3i_{\sigma(3)}} 
