			\sum_{s_1,s_2,s_3=1}^n \Big(\sum_{p=1}^n \alpha^p_{\gamma_2(\nu),s_1,s_2} \alpha^i_{\gamma_2(\mu),p,s_3}\Big)X_{s_1i_{\sigma(1)}}X_{s_2i_{\sigma(2)}}X_{s_3i_{\sigma(3)}} \\
			&=&
			\sum_{s_1,s_2,s_3=1}^n \Big(\sum_{p=1}^n \alpha^p_{\gamma_2(\nu),s_1,s_2} X_{s_1i_{\sigma(1)}}X_{s_2i_{\sigma(2)}} ~\alpha^i_{\gamma_2(\mu),p,s_3}X_{s_3i_{\sigma(3)}}\Big)\\
			&=&
			\sum_{p=1}^n \Big(\Big(\sum_{s_1,s_2=1}^n \alpha^p_{\gamma_2(\nu),s_1,s_2}X_{s_1i_{\sigma(1)}}X_{s_2i_{\sigma(2)}}\Big)\Big(\sum_{s_3=1}^n\alpha^i_{\gamma_2(\mu),p,s_3}X_{s_3i_{\sigma(3)}}\Big)\Big) \\
			&\stackrel{(\ref{freeOperad_eqn_univ_poly_rel_P2})}{=}&
			\sum_{p=1}^n \Big(\Big(\sum_{u=1}^n\alpha^u_{\gamma_2(\nu),i_{\sigma(1)},i_{\sigma(2)}}X_{pu}\Big)\Big(\sum_{s_3=1}^n\alpha^i_{\gamma_2(\mu),p,s_3}X_{s_3i_{\sigma(3)}}\Big)\Big) \\
			&=& 
			\sum_{u=1}^n \alpha^u_{\gamma_2(\mu),i_{\sigma(1)},i_{\sigma(2)}} \Big(\sum_{p,s_3=1}^n \alpha^i_{\gamma_2(\mu),p,s_3} X_{pu} X_{s_3i_{\sigma(3)}}\Big) \\
			\text{Changing}~ u \to r; p \to s; s_3 \to t 
			&=&
			\sum_{r=1}^n
			\alpha^r_{\gamma_{2}(\nu),i_{\sigma(1)},i_{\sigma(2)}}
			\Big(
			\sum_{s,t=1}^n \alpha^i_{\gamma_{2}(\mu),s,t} X_{sr}X_{ti_{\sigma(3)}}\Big)
		\end{eqnarray*} 
		Looking at the RHS of both the expansion we get $(A) = (B)$, i.e.,  $P^{(\mathfrak{a})}_{((\mu \circ_1 \nu)^\sigma;i,i_1,i_2,i_3)} = 0$ for all $\mu,\nu \in E$ and $\sigma \in \Sm_3$. Thus proving the theorem. 
	\end{proof}
