\subsubsection{\it The operad $\mathcal{C}om$}~~\\

	\vspace{-0.4cm}
	Algebras over the operad $\mathcal{C}om$ are (non-unital) commutative, associative algebras. 
	The quadratic data given by $(E_{\mathcal{C}om}, R_{\mathcal{C}om})$ defines the operad $\mathcal{C}om := \T(E_{\mathcal{C}om})/(R_{\mathcal{C}om})$, where $E_{\mathcal{C}om}$ is the $\mathbb{S}$-module concentrated in arity $2$ with trivial $\Sm_2$-action
	\begin{equation*}
		E_{\mathcal{C}om} := (0, 0, \mathbb{K}\mu, 0, \ldots),
	\end{equation*}
	and $(R_{\mathcal{C}om})$ is the operadic ideal generated by $R_{\mathcal{C}om}$, which is a  $\mathbb{S}_3$-submodule of $\mathbb{T}(E_{\mathcal{C}om})(3)$ generated by the associator $\mu \circ_1 \mu - \mu \circ_2 \mu$.

	\medskip 
	Let $\mathfrak{c}$ be a finite-dimensional $\mathcal{C}om$-algebra. Also, let the set of scalars $\{\alpha^s_{i,j} ~|~ s,i,j = 1,\ldots,n\}$ denotes the structure constants of $\mathfrak{c}$ corresponding to $\mu$. Now, using Definition \ref{def_universal_algebra} and Theorem \ref{thm_2_gen_rest_all} we get that the universal algebra $\mathcal{C}(\mathfrak{c})$ of $\mathfrak{c}$ is given by:   
	\begin{equation*}
		\mathcal{C}(\mathfrak{c}):= \K[X_{si}:s,i=1,\ldots,n] \big/ J,
	\end{equation*}
 	where $J$ is the ideal generated by the universal polynomials of $\mathfrak{c}$ corresponding to the basis element $\mu \in \K\mu = \mathcal{C}om(2)$:
 	\begin{equation}
 		P^{(\mathfrak{c})}_{(a,i_1,i_2)} = \sum_{u=1}^n \alpha^u_{i_1, i_2} X_{au} - \sum_{s_1, s_2 = 1}^n \alpha^a_{s_1, s_2} X_{s_1 i_1} X_{s_2 i_2},
 	\end{equation}
 	for any $a, i_1, i_2 = 1, \ldots, n$. 

\bigskip	
\subsubsection{\it The operad $\mathcal{A}ss$}~~\\

	\vspace{-0.4cm}
	Algebras over the operad $\mathcal{A}ss$ are (non-unital) associative algebras. The quadratic data $(E_{\mathcal{A}ss},R_{\mathcal{A}ss})$, describing the operad $\mathcal{A}ss := \T(E_{\mathcal{A}ss})/(R_{\mathcal{A}ss})$, is defined as follows. $E_{\mathcal{A}ss}$ is the $\Sm$-module 
	$(0,0,\K[\Sm_2],0,\ldots)$
	%where we denote by $\mu$ and $\mu^{(12)}$ the basis elements $\mathrm{id}_{\Sm_2}$ and $(12)$, respectively. 
	and the space of relations $R_{\mathcal{A}ss}$ is the $\Sm_3$-submodule of $\mathbb{T}(E_{\mathcal{A}ss})(3)$ generated by the following element: 
	$$\mu \circ_1 \mu - \mu \circ_2 \mu.$$ 
	Note that, a $\K$-linear basis $\mathbb{T}(E_{\mathcal{A}ss})(3)$ is given by $\{(\mu \circ_1 \mu)^\sigma,(\mu \circ_2 \mu)^\sigma: \sigma \in \Sm_3\}$ and a $\K$-linear basis of $R_{\mathcal{A}ss}$ is given by $\{(\mu \circ_1 \mu - \mu \circ_2 \mu)^\sigma : \sigma \in \Sm_3\}$. For further details, see \cite[Section 7.6.4]{Loday-Vallette}. Now, taking the operad to be $\mathcal{A}ss$ in Theorem \ref{thm_left_adjoint} we obtain the following corollary.
	\begin{corollary}{\cite[Theorem 1.1]{Mil}}
		Let $A$ be a (non-unital) associative algebra. Then the functor $A \otimes - : \mathrm{ComAlg} \to \mathrm{Alg}$ admits a left adjoint if and only if $A$ is finite-dimensional. 
	\end{corollary}

	Furthermore, using Theorem \ref{thm_2_gen_rest_all} we obtain the following definition.
	\begin{definition}
		Let $A$ be a finite-dimensional associative algebra with structure constants $\{\alpha_{i,j}^s~|~ s,i,j = 1,\ldots,n\}$. Then, the universal polynomials of $A$ are of the form: 
		\begin{equation}
			P^{(A)}_{(a,i_1,i_2)} = \sum_{u=1}^n \alpha^u_{i_1, i_2} X_{au} - \sum_{s_1, s_2 = 1}^n \alpha^a_{s_1, s_2} X_{s_1 i_1} X_{s_2 i_2},
		\end{equation} 
		for any $a, i_1, i_2 = 1, \ldots, n$. The universal algebra $\mathcal{C}(A)$ of $A$ is given by 
		$\mathcal{C}(A) := \K[X_{si}~|~ s,i=1,\ldots,n] \big/J,$
		where $J$ is the ideal generated by the universal polynomials of $A$. 
	\end{definition}

	\begin{remark}
		Note that the universal algebra $\mathcal{C}(A)$ described above coincides with the ``quantum symmetry semigroup" $a(A)$ of $A$, which was introduced by G. Militaru in \cite[Definition 1.3]{Mil}.
	\end{remark}

\smallskip
\subsubsection{\it The operad $\mathcal{L}eib$}~~\\

	\vspace{-0.4cm}
	Any algebra over the operad $\mathcal{L}eib := \mathbb{T}(E_{\mathcal{L}eib})/(R_{\mathcal{L}eib})$ is a Leibniz algebras. The $\Sm$-module $E_{\mathcal{L}eib}$ is given by
	$E_{\mathcal{L}eib} := (0,0,\K[\Sm_2],0,\ldots)$
	%Similarly as above the basis elements $\mathrm{id}_{\Sm_2}$ and $(12)$ of  $\K[\Sm_2]$ are denote by $\mu$ and $\mu^{(12)}$, respectively. 
	and the space of relations $R_{\mathcal{L}eib}$ is the $\Sm_3$-submodule of $\mathbb{T}(E_{\mathcal{L}eib})(3)$ generated by 
	\begin{equation}\label{quad_rel_lbz}
		\mu \circ_1 \mu -\mu \circ_2 \mu - (\mu \circ_1 \mu)^{(23)}.
	\end{equation}
	Now, taking the operad $\mathcal{L}eib$ in Theorem \ref{thm_left_adjoint} we obtain the following corollary. 

	\begin{corollary}{\cite[Theorem 2.1]{Ag-Mil}}\label{cor_leib}
		Let $\mathfrak{h}$ be a Leibniz algebra. Then the functor $\mathfrak{h} \otimes - : \mathrm{ComAlg} \to \mathrm{Lbz}$ admits a left adjoint if and only if $\mathfrak{h}$ is finite-dimensional.  
	\end{corollary}
 	Furthermore, using Theorem \ref{thm_2_gen_rest_all} we obtain the following description of the universal algebra of a finite-dimensional Leibniz algebra. 
 	\begin{definition}
 		Let $\mathfrak{h}$ be a finite-dimensional Leibniz algebra with structure constants $\{\alpha_{i,j}^s~|~s,i,j=1,\ldots,n\}$. Then, universal algebra $\mathcal{C}(\mathfrak{h})$ of $\mathfrak{h}$ is given by $\mathcal{C}(\mathfrak{h}):= \K[x_{si} : s,i =1\ldots,n]/J$ of $\mathfrak{h}$, where $J$ is the ideal generated by the following universal polynomials: 
 		\begin{equation}\label{univ_poly_lbz}
 			P^{(\mathfrak{h})}_{(a,i_1,i_2)} = \sum_{u=1}^n \alpha^u_{i_1, i_2} X_{au} - \sum_{s_1, s_2 = 1}^n \alpha^a_{s_1, s_2} X_{s_1 i_1} X_{s_2 i_2},
 		\end{equation} 
 		for any $a, i_1, i_2 = 1, \ldots, n$. 
 	\end{definition}

 	\begin{remark}
 		Note that the universal algebra and the universal polynomials of $\mathfrak{h}$ described above are identical with the ones introduced in \cite[Definition 2.6]{Ag-Mil}.
 	\end{remark}

\smallskip	
\subsubsection{\it The operad $\mathcal{L}ie$}~~\\

	\vspace{-0.4cm} 
	The operad $\mathcal{L}ie :=  \mathbb{T}(E_{\mathcal{L}ie})/(R_{\mathcal{L}ie})$ corresponds to the category of Lie algebras. The $\Sm$-module $E_{\mathcal{L}ie}$ is defined as
	$E_{\mathcal{L}ie} := (0,0,\K c, 0, \ldots),$	
	where the right $\Sm_2$-action on $\K c$ is given by $c^{(12)} = - c$ (this means that $c$ is an antisymmetric operation). The space of relations $R_{\mathcal{L}ie}$ is the $\Sm_3$-submodule of $\T(E_{\mathcal{L}ie})(3)$ generated by the Jacobiator 
	$$c \circ_1 c ~+~ (c \circ_1 c)^{(123)} + (c \circ_1 c)^{(132)}.$$ 
	Note that a $\K$-linear basis of $\T(E_{\mathcal{L}ie})(3)$ is given by $\{c \circ_1 c, (c \circ_1 c)^{(123)}, (c \circ_1 c)^{(132)}\}$. We refer the reader to \cite[Section 7.6.2]{Loday-Vallette} for further details. 

	\medskip
	Let $\mathfrak{g}$ be a finite-dimensional Lie algebra with structure constants $\{\alpha_{i,j}^s ~|~ s,i,j=1,\ldots,n\}$. Then, the universal polynomials of $\mathfrak{g}$ are the same as described in Equation \eqref{univ_poly_lbz}. However, here the polynomials take a rather simplified form, because of the following restrictions on the structure constants: 
	\begin{equation*}
		\alpha_{i,i}^s = 0 \quad \alpha_{i,j}^s = - \alpha_{j,i}^s \quad \text{for all } s,i,j = 1,\ldots,n.
	\end{equation*} 
	Note that Corollary \ref{cor_leib} remains valid in the case of Lie algebras. Additionally, using Theorem \ref{thm_2_gen_rest_all} we obtain that the universal algebra $\mathcal{C}(\mathfrak{g})$ coincides with the ``universal algebra of $\mathfrak{g}$" as constructed in \cite[Definition 2.6]{Ag-Mil}.

\bigskip
\subsubsection{\it The operad $\mathcal{Z}inb$}~~\\

	\vspace{-0.4cm}
	The operad $\mathcal{Z}inb := \mathbb{T}(E_{\mathcal{Z}inb})/(R_{\mathcal{Z}inb})$ is the Koszul dual of the operad $\mathcal{L}eib$. It encodes the category of Zinbiel algebras. The $\Sm$-module $E_{\mathcal{Z}inb}$ is given by
	$E_{\mathcal{Z}inb} := (0,0,\K[\Sm_2],0,\ldots)$	
	and the space of relations $R_{\mathcal{Z}inb}$ is an $\Sm_3$-submodule of $\mathbb{T}(E_{\mathcal{Z}inb})(3)$ generated by 
	\begin{equation}\label{quad_rel_zinb}
		\mu \circ_1 \mu -\mu \circ_2 \mu - (\mu \circ_2 \mu)^{(23)}. 
	\end{equation}
	It is worth noting that the generators of \( R_{\mathcal{L}ieb} \) and \( R_{\mathcal{Z}inb} \), as specified in Equations \eqref{quad_rel_lbz} and \eqref{quad_rel_zinb}, respectively, are distinct from one another.

	\medskip
	Now, using Theorems \ref{thm_left_adjoint} and \ref{thm_2_gen_rest_all}, we present the following result and definition in the context of Zinbiel algebras. 
	\begin{corollary}
		Let $\mathfrak{z}$ be a Zinbiel algebra. Then the functor $\mathfrak{z} \otimes - : \mathrm{ComAlg} \to \mathrm{Zinb}$ admits a left adjoint if and only if $\mathfrak{z}$ is finite-dimensional.  
	\end{corollary}

	\begin{definition}
		Let $\mathfrak{z}$ be a finite-dimensional Zinbiel algebra with structure constants $\{\alpha_{i,j}^s~|~s,i,j=1,\ldots,n\}$. Then, the universal polynomials of $\mathfrak{z}$ are of the form
		\begin{equation}\label{univ_poly_zinb}
			P^{(\mathfrak{z})}_{(\mu,a,i_1,i_2)} = \sum_{u=1}^n \alpha^u_{i_1,i_2} X_{au}
			\hspace{0.2cm} - \sum_{s_1,s_2=1}^n \alpha^a_{s_1,s_2}X_{s_1 i_1} X_{s_2 i_2},
		\end{equation}
		for all $a,i_1,i_2 = 1,\ldots, n$. And the universal algebra $\mathcal{C}(\mathfrak{z})$ of $\mathfrak{z}$ is given by $\K[X_{si}~|~s,i=1,\ldots,n]\big/J$, where $J$ is the ideal generated by the universal polynomials of $\mathfrak{z}$ described in Equation \eqref{univ_poly_zinb}.  
	\end{definition}

\smallskip	
\subsubsection{\it The operad $\mathcal{P}ois$}~~\\

	\vspace{-0.4cm}
	The operad encoding Poisson algebras is denoted by $\mathcal{P}ois$. It can be constructed from two operads, $\mathcal{L}ie$ and $\mathcal{C}om$, using the ``distributive law" (cf. \cite[Section 8.6]{Loday-Vallette}). The quadratic presentation of $\mathcal{P}ois$ is given by 
	\begin{equation}\label{def_operad_pois}
		\mathcal{P}ois := \mathbb{T}(E_{\mathcal{L}ie} \oplus E_{\mathcal{C}om})/ (R_{\mathcal{L}ie} \oplus R_{\mathcal{C}om} \oplus D)
	\end{equation} 
	where $D$ is an $\Sm_3$-submodule of $\mathbb{T}(E_{\mathcal{L}ie} \oplus E_{\mathcal{C}om})(3)$ generated by $c \circ_1 \mu - (\mu \circ_1 c)^{(23)} - \mu \circ_2 c$. 
	Now, as a corollary of Theorem \ref{thm_left_adjoint} we obtain the result proved by Agore and Militaru for Poisson algebras. 
	\begin{corollary}\cite[Theorem 2.2]{Ag-Mil2}
		Let $\mathfrak{p}$ be a Poisson algebra. Then the functor $\mathfrak{p} \otimes - : \mathrm{ComAlg} \to \mathrm{Pois}$ admits a left adjoint if and only if $\mathfrak{p}$ is finite-dimensional.  
	\end{corollary}

	Let $\mathfrak{p}$ be a finite-dimensional $\mathcal{P}ois$-algebra with structure constants $\{\alpha_{i,j}^s ~|~ s,i,j=1,\ldots,n\}$ and $\mathcal{C}(\mathfrak{p}) := \K[X_{si}~|~ s,i=1,\ldots,n]/J$ be its universal algebra. Using Theorem \ref{thm_2_gen_rest_all}, we get that the ideal $J$ is generated by the universal polynomials of $\mathfrak{p}$ corresponding to $c$ and $\mu \in \K c \oplus \K \mu = \mathcal{P}ois(2)$:
	\begin{equation}\label{eqn_pois_1}
		P^{(\mathfrak{p})}_{(c,a,i_1,i_2)} = \sum_{u=1}^n \alpha^u_{\gamma_2(c),i_1,i_2} X_{au}
		\hspace{0.2cm} - \sum_{s_1,s_2=1}^n \alpha^a_{\gamma_2(c),s_1,s_2}X_{s_1 i_1}X_{s_2 i_2}
	\end{equation} 
	\begin{equation}\label{eqn_pois_2}
		P^{(\mathfrak{p})}_{(\mu,a,i_1,i_2)} = \sum_{u=1}^n \alpha^u_{\gamma_2(\mu),i_1,i_2} X_{au}
		\hspace{0.2cm} - \sum_{s_1,s_2=1}^n \alpha^a_{\gamma_2(\mu),s_1,s_2}X_{s_1 i_1}X_{s_2 i_2}
	\end{equation} 
	for all $a,i_1,i_2 = 1,\ldots,n$. Note that, the universal polynomials described in Equation (\ref{eqn_pois_1}) and (\ref{eqn_pois_2}) coincides with the universal polynomials given in \cite[Equation (8) and (9), pg. 39]{Ag-Mil2}. Hence, the universal algebra $\mathcal{C}(\mathfrak{p})$ defined here is the same as the ``universal algebra of $\mathfrak{p}$" constructed in \cite[pg. 39]{Ag-Mil2}.

\bigskip
\subsubsection{\it The operad $pre\mathcal{L}ie$}~~\\

	\vspace{-0.4cm}
	The notion of pre-Lie algebras appeared first in the study of Hochschild cohomology and in studying flat affine connections on a given manifold. The operad $pre\mathcal{L}ie := \mathbb{T}(E_{pre\mathcal{L}ie})/(R_{pre\mathcal{L}ie})$ encodes the category of pre-Lie algebras. The $\Sm$-module $E_{pre\mathcal{L}ie}$ is given by 
	$E_{pre\mathcal{L}ie} := (0,0,\K[\Sm_2],0,\ldots)$	
	%Similar to $\mathcal{L}eib$, we denote the basis elements of $\K[\Sm_2]$ by $\mu$ and $\mu^{(12)}$. 
	and the space of relations $R_{pre\mathcal{L}ie}$ is an $\Sm_3$-submodule of $\mathbb{T}(E_{pre\mathcal{L}ie})(3)$ generated by 
	$$\mu \circ_1 \mu -\mu \circ_2 \mu - (\mu \circ_1 \mu)^{(23)} + (\mu \circ_2 \mu)^{(23)}.$$ 

	\begin{corollary}
		Let $\mathfrak{l}$ be a pre-Lie algebra. Then the functor $\mathfrak{l} \otimes - : \mathrm{ComAlg} \to \mathrm{pre}\text{-}\mathrm{Lie}$ admits a left adjoint if and only if $\mathfrak{p}$ is finite-dimensional.
	\end{corollary}

	The universal polynomials of a finite-dimensional pre-Lie algebra $\mathfrak{l}$ is of the same form as described in Equation \eqref{univ_poly_lbz}.
	And The universal algebra of $\mathfrak{l}$ is given by $\mathcal{C}(\mathfrak{l}):=\K[X_{si}: s,i=1,\ldots,n]/J$,where $J$ is the ideal generated by the universal polynomials of $\mathfrak{l}$ corresponding to $\mu \in \K[\Sm_2] = pre\mathcal{L}ie(2)$.
	%\begin{equation}
	%	P^{(\mathfrak{l})}_{(\mu,a,i_1,i_2)} = \sum_{u=1}^n \alpha^u_{i_1,i_2} X_{au}
	%	\hspace{0.2cm} - \sum_{s_1,s_2=1}^n \alpha^a_{s_1,s_2}X_{s_1 i_1} X_{s_2 i_2}
	%\end{equation} 
	%for all $a,i_1,i_2 = 1,\ldots, n$.

\bigskip
\subsubsection{\it The operad $\mathcal{P}erm$}~~\\

	\vspace{-0.4cm}
	The Koszul dual of the operad $pre\mathcal{L}ie$ is the operad $\mathcal{P}erm$. It is defined as $\mathcal{P}erm := \mathbb{T}(E_{\mathcal{P}erm})/(R_{\mathcal{P}erm})$ which encodes the category of Perm algebras. The $\Sm$-module $E_{\mathcal{P}erm}$ is defined as 
	$E_{\mathcal{P}erm} := (0,0,\K[\Sm_2],0,\ldots).$	
	The space of relations $R_{\mathcal{P}erm}$ is an $\Sm_3$-submodule of $\mathbb{T}(E_{\mathcal{P}erm})(3)$ generated by 
	$$\mu \circ_1 \mu -\mu \circ_2 \mu,~\mu \circ_1 \mu - (\mu \circ_2 \mu)^{(23)}, \text{ and } \mu \circ_2 \mu - (\mu \circ_1 \mu)^{(23)}.$$ 

	\begin{corollary}
		Let $\mathfrak{q}$ be a Perm algebra. Then the functor $\mathfrak{q} \otimes - : \mathrm{ComAlg} \to \mathrm{Perm}$ admits a left adjoint if and only if $\mathfrak{q}$ is finite-dimensional.
	\end{corollary}

	Let $\mathfrak{q}$ be a finite-dimensional Perm-algebra and $\mathcal{C}(\mathfrak{q})$ be its universal algebra.  Then the ideal $J$ is generated by the universal polynomials of $\mathfrak{q}$ corresponding to $\mu \in \K[\Sm_2] = \mathcal{P}erm(2)$, which is of the same form as described in Equation \eqref{univ_poly_lbz}.

