\subsection{Algebras over $k$-ary quadratic operads}~~\\

	\vspace{-0.4cm}
	Here we focus on algebras over certain $k$-ary quadratic operads. More precisely, we describe the universal algebra and the universal polynomials for finite-dimensional totally associative $k$-ary algebras, partially associative $k$-ary algebras, Leibniz $k$-algebras, and Lie $k$-algebras. Before proceeding, we fix some notation. For any $k \in \mathbb{N}$, the basis elements of $\K[\Sm_k]$ are denoted as follows: $\mu$ denotes $\mathrm{id}_{\Sm_k}$ and $\mu^{\sigma}$ denotes the element $\sigma \in \Sm_k$. 

	\medskip
	Similar to binary quadratic operads, any $k$-ary quadratic operad $\mathcal{P}$ can be described in terms of quadratic data as follows: 
	$\mathcal{P}:= \T(E_\mathcal{P})\big/(R_\mathcal{P}),$
	where $$\overline{E}_\mathcal{P} := \big(0,0,\ldots,\overbrace{E_\mathcal{P}}^{k^{th}\text{-term}},0\big),$$
	is an $\Sm$-module concentrated in arity $k$.
	We noted in Remark \ref{remark_5.3} that Theorem \ref{thm_2_gen_rest_all}, initially proven for binary quadratic operads, naturally extends to $k$-ary quadratic operads. This gives us the following theorem.

	\begin{theorem}\label{thm_k-ary}
		Let $\mathcal{P} = \T(E_\p)/(R_\p)$ be a $k$-ary quadratic operad. Consider a finite-dimensional $\mathcal{P}$-algebra $\mathfrak{a}$ with its universal algebra $\mathcal{C}(\mathfrak{a})$. Then, the ideal $J$, as described in Equation \eqref{C(a)}, is generated by the universal polynomials corresponding to the basis elements of $\mathcal{P}(k) = E_\p$. 
	\end{theorem} 

	This extension enables us to describe the universal algebras for algebras over $k$-ary operads. Below, we present examples of such operads, which include several well-known $k$-ary algebras. 

\bigskip
\subsubsection{\it Totally associative $k$-ary algebras}~~\\

	\vspace{-0.4cm}
	A totally associative $k$-ary algebra is a vector space $A$ equipped with a linear map $\mu: A^{\otimes k} \to A$ such that for any $1 \le i,j \le k$ the following equality holds
	\begin{equation*}
		\mu \big(\mathrm{id}^{\otimes i-1} \otimes \mu \otimes \mathrm{id}^{\otimes k-i}\big) 
		= \mu \big(\mathrm{id}^{\otimes j-1} \otimes \mu \otimes \mathrm{id}^{\otimes k-j}\big).		
	\end{equation*}
	The operad $t\mathcal{A}ss := \T(E_{t\mathcal{A}ss})/ (R_{t\mathcal{A}ss})$ encodes the category of totally associative $k$-ary algebras, where the $\Sm$-module $E_{t\mathcal{A}ss}$ is given by 
	\begin{equation*}
		E_{t\mathcal{A}ss} := (0,\ldots,\overbrace{\K[\Sm_k]}^{k^{th}},0,\ldots).
	\end{equation*}
	The space of relations $R_{t\mathcal{A}ss}$ is the $\Sm_{2k-1}$-submodule of $\T(E_{t\mathcal{A}ss})(2k-1)$ generated by $\{\mu \circ_i \mu - \mu \circ_j \mu : \text{for all}~ i,j = 1,\ldots,k\}$. Now, as a corollary of Theorem \ref{thm_left_adjoint} we obtain the following result. 

	\begin{corollary}
		Let $A$ be a totally associative $k$-ary algebra. Then the functor $A \otimes - : \mathrm{ComAlg} \to \mathrm{tAss}$ admits a left adjoint if and only if $A$ is finite-dimensional.
	\end{corollary}

	Let $A$ be a finite dimensional totally associative $k$-ary algebra. Also, let the set of scalars  $\{\alpha_{i_1,\ldots,i_k}^s~|~s,i_1,\ldots,i_k=1,\ldots,n\}$ denote the structure constants of $A$. Then, the universal polynomials of $A$ are given by 
	\begin{equation}\label{univ_poly_tAss}
		P^{(A)}_{(\mu,a,i_1,\ldots,i_k)} = \sum_{u=1}^n \alpha^u_{i_1,\ldots,i_n} X_{au}
		\hspace{0.2cm} - \sum_{s_1,\ldots,s_k=1}^n \alpha^a_{s_1,\ldots,s_k}X_{s_1 i_1} \cdots X_{s_k i_k}
	\end{equation} 
	for all $a,i_1,\ldots, i_k = 1,\ldots, n$. The universal algebra of $A$ is defined as $\mathcal{C}(A) := \K[X_{si} ~|~ s,i=1,\ldots,n]\big/J$, where $J$ is the ideal generated by the universal polynomials of $A$, as described in Equation \eqref{univ_poly_tAss}. 

\bigskip
\subsubsection{\it Partially associative $k$-ary algebras}~~\\

	\vspace{-0.4cm}
	A partially associative $k$-ary algebra is a vector space $A$ equipped with a linear map $\mu: A^{\otimes k} \to A$ such that the following equality holds
	\begin{equation*}
		\sum_{i=1}^{k} (-1)^{(i+1)(k-1)} \mu \big(\mathrm{id}^{\otimes i-1} \otimes \mu \otimes \mathrm{id}^{\otimes k-i}\big) 
		= 0.		
	\end{equation*}
	The operad $p\mathcal{A}ss := \T(E_{p\mathcal{A}ss})/(R_{p\mathcal{A}ss})$ encodes the category of partially associative $k$-ary algebras, where $\Sm$-module $E_{p\mathcal{A}ss}$ is defined as follows 
	\begin{equation*}
		E_{p\mathcal{A}ss} := (0,\ldots,\overbrace{\K[\Sm_k]}^{k^{th}},0,\ldots).
	\end{equation*}
	The space of relations $R_{p\mathcal{A}ss}$ is an $\Sm_{2k-1}$-submodule of $\T(E_{p\mathcal{A}ss})(2k-1)$ generated by $\sum_{i=1}^k (-1)^{(i+1)(k-1)} \mu \circ_i \mu$. Now, as a corollary of Theorem \ref{thm_left_adjoint} we obtain the following result. 

	\begin{corollary}
		Let $A$ be a partially associative $k$-ary algebra. Then the functor $A \otimes - : \mathrm{ComAlg} \to \mathrm{pAss}$ admits a left adjoint if and only if $A$ is finite-dimensional.
	\end{corollary} 

	Let $A$ be a finite dimensional partially associative $k$-ary algebra. The universal polynomials of $A$ takes the same form as described in Equation \eqref{univ_poly_tAss}. 
	%The $\mathcal{C}(A):=\K[X_{si}~|~s,i=1,\ldots,n]\big/J$ be its universal algebra. Similarly, using Theorem \ref{thm_k-ary} we get that the ideal $J$ is generated by the universal polynomials of $A$ corresponding to the basis elements $\mu \in \K[\Sm_k] = p\mathcal{A}ss(k)$:
	%\begin{equation}
	%	P^{(A)}_{(\mu,a,i_1,\ldots,i_k)} = \sum_{u=1}^n \alpha^u_{i_1,\ldots,i_n} X_{au}
	%	\hspace{0.2cm} - \sum_{s_1,\ldots,s_k=1}^n \alpha^a_{s_1,\ldots,s_k}X_{s_1 i_1} \cdots X_{s_k i_k},
	%\end{equation} 
	%for all $a,i_1,\ldots, i_k = 1,\ldots, n$.

\bigskip	
\subsubsection{\it Lie $k$-algebras}~~\\

	\vspace{-0.4cm}
	A Lie $k$-algebra is a vector space $L$ equipped with a linear map $\mu: L ^{\otimes k} \to L$ which satisfies the following equalities: 
	\begin{equation}
		\mu (\mu \otimes\mathrm{id}^{k-1})
		= \sum_{i=1}^{k} \mu \big(\mathrm{id}^{\otimes i-1} \otimes \mu \otimes \mathrm{id}^{\otimes k-i}\big)^{\sigma_i}
		\quad \text{and} \quad 
		\mu^\sigma = \mathrm{sgn}(\sigma) \mu \text{ for all } \sigma \in \Sm_k, 
	\end{equation}	
	where $\sigma_i \in \Sm_{2k-1}$ is given by 
	$\sigma_i := \left[\underbrace{1,\ldots,i-1},\overbrace{i,k+1,k+2,\ldots,k+k-1},\underbrace{i+1,\ldots,k}\right].$
	The permutation $\sigma_i$ is described using the notation given by J. L. Loday and B. Vallete in \cite[Introduction, pg xxiv]{Loday-Vallette}. The operad $k$-$\mathcal{L}ie := \T(E_{k\text{-}\mathcal{L}ie})/(R_{k\text{-}\mathcal{L}ie})$ is described in terms of the quadratic data $(E_{k\text{-}\mathcal{L}ie},R_{k\text{-}\mathcal{L}ie})$ where the $\Sm$-module $E_{k\text{-}\mathcal{L}ie}$ is given by 
	\begin{equation}
		E_{k\text{-}\mathcal{L}ie} := (0,\ldots,\overbrace{\K[\Sm_k]}^{k^{th}},0,\ldots)
	\end{equation}
 	and the space of relations $R_{k\text{-}\mathcal{L}ie}$ is an $\Sm_{2k-1}$-submodule of $\T(E_{k\text{-}\mathcal{L}ie})(2k-1)$ generated by 
 	\begin{equation*}
 		\mu (\mu \otimes\mathrm{id}^{k-1})
 		- \sum_{i=1}^{k} \mu \big(\mathrm{id}^{\otimes i-1} \otimes \mu \otimes \mathrm{id}^{\otimes k-i}\big)^{\sigma_i}
 		\quad \text{and} \quad 
 		\mu^\sigma - \mathrm{sgn}(\sigma)\mu = 0 \text{ for any } \sigma \in \Sm_k.
 	\end{equation*}	 
 	Again, as a corollary of Theorem \ref{thm_left_adjoint} we obtain the following result. 

 	\begin{corollary}
 		Let $L$ be a Lie $k$-algebra. Then the functor $L \otimes - : \mathrm{ComAlg} \to k\text{-}\mathrm{Lie}$ admits a left adjoint if and only if $L$ is finite-dimensional.
 	\end{corollary} 

 	Let $L$ be a finite dimensional Lie $k$-algebra and $\mathcal{C}(L)$ be its universal algebra. Then, the ideal $J$ is generated by the universal polynomials of $L$ associated with $\mu \in \K[\Sm_k] = k\text{-}\mathcal{L}ie(k)$:
 	\begin{equation}\label{univ_poly_Lie_k}
 		P^{(L)}_{(\mu,a,i_1,\ldots,i_k)} = \sum_{u=1}^n \alpha^u_{i_1,\ldots,i_n} X_{au}
 		\hspace{0.2cm} - \sum_{s_1,\ldots,s_k=1}^n \alpha^a_{s_1,\ldots,s_k}X_{s_1 i_1} \cdots X_{s_k i_k},
 	\end{equation} 
 	for all $a,i_1,\ldots, i_k = 1,\ldots, n$.

\bigskip	
\subsubsection{\it Leibniz $k$-algebras}~~\\

	\vspace{-0.4cm}
	A Leibniz $k$-algebra is a vector space $L$ equipped with a linear map $\mu: L^{\otimes k} \to L$ for which the following equality holds
	\begin{equation}
		\mu (\mu \otimes\mathrm{id}^{k-1})
		= \sum_{i=1}^{k} \mu \big(\mathrm{id}^{\otimes i-1} \otimes \mu \otimes \mathrm{id}^{\otimes k-i}\big)^{\sigma_i},	
	\end{equation}
	where $\sigma_i \in \Sm_{2k-1}$ is the same as defined in the case of Lie $k$-algebras.
	The operad $k\text{-}\mathcal{L}eib := \T(E_{k\text{-}\mathcal{L}eib})/(R_{k\text{-}\mathcal{L}eib})$ encodes the category of Leibniz $k$-algebras, The $\Sm$-module $E_{k\text{-}\mathcal{L}eib}$ is defined as 
	\begin{equation}
		E_{k\text{-}\mathcal{L}eib} := (0,\ldots,\overbrace{\K[\Sm_k]}^{k^{th}},0,\ldots).
	\end{equation}
	The space of relations $R_{k\text{-}\mathcal{L}eib}$ is an $\Sm_{2k-1}$-submodule of $\T(E_{k\text{-}\mathcal{L}eib})(2k-1)$ generated by 
	\begin{equation}
		\mu (\mu \otimes\mathrm{id}^{k-1})
		- \sum_{i=1}^{k} \mu \big(\mathrm{id}^{\otimes i-1} \otimes \mu \otimes \mathrm{id}^{\otimes k-i}\big)^{\sigma_i}.
	\end{equation}	 
	Again, as a corollary of Theorem \ref{thm_left_adjoint} we obtain the following result. 
	\begin{corollary}
		Let $L$ be a Leibniz $k$-algebra. Then the functor $L \otimes - : \mathrm{ComAlg} \to k\text{-}\mathrm{Leib}$ admits a left adjoint if and only if $L$ is finite-dimensional.
	\end{corollary} 

	For any finite dimensional Leibniz $k$-algebra $L$. The universal polynomials of $L$ is of the same form, as described in Equation \eqref{univ_poly_Lie_k}. 
	%Again, using Theorem \ref{thm_k-ary} we get that the ideal $J$ is generated by the universal polynomials of $L$ associated with $\mu \in \K[\Sm_k] = k\text{-}\mathcal{L}eib(k)$:
	%\begin{equation}
	%	P^{(L)}_{(\mu,a,i_1,\ldots,i_k)} = \sum_{u=1}^n \alpha^u_{i_1,\ldots,i_n} X_{au}
	%	\hspace{0.2cm} - \sum_{s_1,\ldots,s_k=1}^n \alpha^a_{s_1,\ldots,s_k}X_{s_1 i_1} \cdots X_{s_k i_k},
	%\end{equation} 
	%for all $a,i_1,\ldots, i_k = 1,\ldots, n$.

\bigskip
\subsection{Algebras over non-symmetric operads}~~\\

	\vspace{-0.4cm}
	Any given non-symmetric operad $\mathcal{P} = (\mathcal{P}(0),\mathcal{P}(1),\ldots)$, one can construct a symmetric operad $\widetilde{\mathcal{P}}$ given as follows:
	\begin{equation*}
		\widetilde{\mathcal{P}}(n) := \mathcal{P}(n) \otimes \K[\Sm_n],
	\end{equation*}
	where the action of the symmetric group $\Sm_n$ on $\widetilde{\mathcal{P}}(n)$ is given by the regular representation $\K[\Sm_n]$. The association $\mathcal{P} \mapsto \widetilde{\mathcal{P}}$ is refer to as ``symmetrization". Furthermore, we note that the category of algebras over the non-symmetric operad $\mathcal{P}$ and over its associated symmetric operad $\widetilde{\mathcal{P}}$ are the same. See \cite[Section 5.9.11]{Loday-Vallette} for further details. Thus, using symmetrization our universal constructions also holds for algebras over non-symmetric operads. 

	%Any non-symmetric operad can be turned into a symmetric operad through a process called symmetrization, which keeps the category of algebras over the non-symmetric operad unchanged (see \cite[Section 5.9.11]{Loday-Vallette}). More precisely, 

	\medskip	
	We refer the readers to \cite{Apurba-Da} for examples of non-symmetric operads that encode various Loday-type algebras such as dialgebras, associative trialgebras, dendriform algebras, dendriform trialgebras, quadri algebras, and ennea algebras. Consequently, using symmetrization to obtain the associated symmetric operads for the operads encoding Loday-type algebras, we can construct the universal algebras for these Loday-type algebras using the results obtained in Section \ref{sec-3}.

\bigskip
\subsection{Algebras over graded operads}~~\\

	\vspace{-0.4cm}
	Here, we consider examples of graded algebras and operads encoding them. Precisely, we give the construction of universal coacting algebras for graded Lie/Leibniz algebras, graded Poisson algebras, Garstenhaber algebras, and  Batalin-Vilkovisky algebras. 

\bigskip
\subsubsection{\it Graded Leibniz algebras}~~\\

	\vspace{-0.4cm}
	A graded Leibniz algebra is a graded vector space $\mathfrak{H} = \oplus_{p \ge 0}\mathfrak{H_p}$ equipped with a degree $0$ binary bracket ``$[\cdot, \cdot]$",  called the graded Leibniz bracket. It satisfies the following identity
	\[
	[x, [y, z]] = [[x, y], z] + (-1)^{|x||y|} [y, [x, z]],
	\]
	where $|x|$ and $|y|$ denotes the degree of the homogeneous elements $x$ and $y$, respectively. This identity is known as the graded Leibniz identity.

	\medskip
	The operad $\mathcal{L}eib$ encodes the category of graded Leibniz algebras. Note that we can consider the operad $\mathcal{L}eib$ as a graded operad concentrated at degree zero in every arity. Then, a graded Leibniz algebra structure on a graded vector space $\mathfrak{H} = \oplus_{p \ge 0}\mathfrak{H_p}$ is given by a graded operad morphism $\gamma : \mathcal{L}eib \rightarrow \mathrm{End}_{\mathfrak{H}}$.  

	\medskip 
 	The following corollary to Theorem \ref{thm_graded_left_adjoint} naturally extends the universal construction of A. L. Agore and G. Militaru \cite[Theorem 2.1]{Ag-Mil} to the graded context. 

	\begin{corollary}\label{cor_graded_Leib}
		Let $\mathfrak{H} = \oplus_{p \ge 0} \mathfrak{H}_p$ be a graded Leibniz algebra over $\K$. Then the functor $\mathfrak{H} \otimes - : \mathrm{g}\text{-}\mathrm{ComAlg} \to \mathrm{g}\text{-}\mathrm{Leib}$ admits a left adjoint if and only if each component $\mathfrak{H}_p$ of $\mathfrak{H}$ is finite-dimensional. 
	\end{corollary}

	\begin{proof}
		($\implies$)
		Since each component $\mathfrak{H}_p$ of $\mathfrak{H}=\oplus_{p \ge 0} \mathfrak{H}_p$ is finite-dimensional, let   
		\begin{equation*}
			\{a_{01},\ldots,a_{0d_0};a_{11},\ldots,a_{1d_1}; \ldots;a_{p1},\ldots,a_{pd_p};\ldots\}
		\end{equation*}
		be a vector space basis of $\mathfrak{H}$, where $\{a_{p1},\ldots,a_{pd_p}\}$ denotes a vector space basis of the $p$-degree component $\mathfrak{H}_p$. The structure constants of $\mathfrak{H}$ are obtained as follows: for any $p,q \ge 0$
		\begin{equation}\label{graded_case_struct_const_h}
			[a_{pi},a_{qj}] = \sum_{s=1}^{d_{p+q}} \alpha_{pi,qj}^{\theta,s}~a_{(p+q)s} 
		\end{equation} 
		where $\theta = p+q$, $1 \le i \le d_p$, and $1 \le j \le d_q$. Consequently, the set of scalars given below yields the structure constants of $\mathfrak{H}$:
		$$\bigcup_{p,q \ge 0}\{\alpha_{pi,qj}^{\theta,s}~|~ \theta = p+1;~ 1 \le i \le d_p;~ 1 \le j \le d_q;~ 1 \le s \le d_{\theta}\}.$$ 
		Now, for any object $\mathfrak{G} \in \mathrm{g}\text{-}\mathrm{Leib}$ we shall construct a graded commutative algebra $\mathcal{C}(\mathfrak{H},\mathfrak{G})$. 
		Let $\{b_{pi}: p \ge 0, i \in I_p\}$ be a basis of $\mathfrak{G}$. Then, for any $p,q \ge 0$, $i \in I_p$, and $j \in I_q$ there exists a finite set $B_{pi,qj} \subset I_{p+q}$ for which
		\begin{equation}\label{graded_case_struc_const_g}
			[b_{pi},b_{qj}] ~= \sum_{u \in B_{pi,qj}} \beta_{pi,qj}^{\theta,u} ~b_{(p+q)u}, 
		\end{equation}
		where $\theta = p+q$.
