		\mathcal{C}(\mathfrak{P}) := \mathbb{K}\big[X^{(\pi)}_{ij}|~i,j,\pi\geq 0 \big] \big/ J,
	\end{equation*}
	where, due to Remark \ref{remark_5.3}, $J$ is the ideal generated by universal graded  polynomials defined in Equation \eqref{graded_uni1} and \eqref{graded_uni2}.


\bigskip
\subsubsection{\it Gerstenhaber algebras}~~\\

	\vspace{-0.4cm}
	A Gerstenhaber algebra is an algebra over the graded operad $\mathcal{G}erst$ with the quadratic presentation $(E_{\mathcal{G}erst},R_{\mathcal{G}erst})$. Here, the space of generators is given by 
	\begin{equation*}
		E_{\mathcal{G}erst} :=  \big(0,0,\K m \oplus \K c,0,\ldots\big)
	\end{equation*} 
	which is a direct sum of two one-dimensional trivial representations of $\Sm_2$ concentrated in arity $2$, one in degree $0$ denoted by $m$ and one in degree $1$ denoted by $c$. The space of relations $R_{\mathcal{G}erst}$ is the graded $\K[\Sm_3]$-module generated by the following relations  
	\begin{equation*}
		c \circ_1 c + (c \circ_1 c)^{(123)} + (c \circ_1 c)^{(321)}, \quad c \circ_1 m - m \circ_2 c - (m \circ_1 c)^{(23)}, \quad m \circ_1 m - m \circ_2 m.
	\end{equation*}
	Now, as a corollary of Theorem \ref{thm_graded_left_adjoint} we obtain the following result. 
	\begin{corollary}\label{cor_gerstenhaber}
		Let $\mathfrak{G} = \oplus_{p \ge 0} \mathfrak{G}_p$ be a Gerstenhaber algebra. Then the functor $\mathfrak{G} \otimes - : \mathrm{g}\text{-}\mathrm{ComAlg} \to \mathrm{Gerst}$ admits a left adjoint if and only if each component $\mathfrak{G}_p$ of $\mathfrak{G}$ is finite-dimensional. 
	\end{corollary}

	Let $\mathfrak{G} = \oplus_{p \ge 0} \mathfrak{G}_p$ be a Gerstenhaber algebra with each component $\mathfrak{G}_p$ being finite-dimensional. Also, let the set $\big\{g_{01},\ldots,g_{0d_0};g_{11},\ldots,g_{1d_1};\ldots;g_{p1},\ldots,g_{pd_p};\ldots\big\}$ denote a  vector space basis of $\mathfrak{G}$, where $\{g_{p1},\ldots,g_{pd_p}\}$ denotes the basis of $\mathfrak{G}_p$. Then, the set of scalars 
	\begin{equation*}
		\bigcup_{p_1,p_2 \ge 0}\Big\{\alpha^{\theta,s}_{\gamma_2(c),p_1i_1,p_2i_2},~\alpha^{\theta,s}_{\gamma_2(m),p_1i_1,p_2i_2}~|~ \theta = p_1 + p_2;~ i_r = 1,\ldots,d_{p_r} \text{ for any } r = 1,2;~ 1 \le s \le d_{p_1+p_2}\Big\}
	\end{equation*}    
	gives us the structure constants of $\mathfrak{G}$. Hence, the universal graded polynomials of $\mathfrak{G}$ are described as follows: 
	\begin{equation}\label{gerst_graded_uni1}
		P^{(\mathfrak{G},\omega )}_{(m,r,p_1i_1,p_2i_2)} 
		:=
		\sum_{u=1}^{d_\theta} \alpha^{\theta,u}_{\gamma_2(m),p_1i_1,p_2i_2} X^{(\omega)}_{ru}
		\hspace{0.2cm} -
		\sum_{\substack{\epsilon_1 + \epsilon_2 = \theta-\omega \\ 0 \le \epsilon_k \le p_k}}	
		\Bigg(
		\sum_{s_1=1}^{d_{p_1}}\sum_{s_2=1}^{d_{p_2}} \alpha^{\theta-\omega,r}_{\gamma_2(m),\epsilon_1 s_1,\epsilon_2 s_2}X_{s_1 i_1}^{(p_1-\epsilon_1)} X_{s_2 i_2}^{(p_2-\epsilon_2)}\Bigg),
	\end{equation}
	\begin{equation}\label{gerst_graded_uni2}
		P^{(\mathfrak{G},\omega )}_{(c,r,p_1i_1,p_2i_2)} 
		:=
		\sum_{u=1}^{d_\theta} \alpha^{\theta,u}_{\gamma_2(c),p_1i_1,p_2i_2} X^{(\omega)}_{ru}
		\hspace{0.2cm} -
		\sum_{\substack{\epsilon_1 + \epsilon_2 = \theta-\omega-1 \\ 0 \le \epsilon_k \le p_k}}	
		\Bigg(
		\sum_{s_1=1}^{d_{p_1}}\sum_{s_2=1}^{d_{p_2}} \alpha^{\theta-\omega,r}_{\gamma_2(c),\epsilon_1 s_1,\epsilon_2 s_2}X_{s_1 i_1}^{(p_1-\epsilon_1)} X_{s_2 i_2}^{(p_2-\epsilon_2)}\Bigg),
	\end{equation}
	where $\theta = p_1 + p_2$, $0 \le \omega \le \theta$, and $r = 1, \ldots, d_\omega$. Consequently, the universal graded algebra $\mathcal{C}(\mathfrak{G})$ is given by 
	\begin{equation*}
		\mathcal{C}(\mathfrak{G}) := \mathbb{K}\big[X^{(\pi)}_{ij}|~i,j,\pi\geq 0 \big] \big/ J,
	\end{equation*}
	where, due to Remark \ref{remark_5.3}, $J$ is the ideal generated by universal graded  polynomials defined in Equation \eqref{gerst_graded_uni1} and \eqref{gerst_graded_uni2}.

\bigskip
\subsubsection{\it Batalin-Vilkovisky algebras}~~\\

	\vspace{-0.4cm}
	The notion of Batalin-Vilkovisky (BV)  algebras appear in diverse places of mathematics, such as they appear in differential geometry of polyvector fields, on the Hochschild cohomology of unital cyclic associative algebras, on the homology of free loop spaces, on vertex operator algebras, etc. A BV algebra structure is given by a data $(\mathfrak{G},\cdot,\Delta)$ where $\mathfrak{G}$ is a graded vector space equipped with a graded commutative product $``\cdot"$ of degree $0$, and a unary operation $\Delta$ of degree $1$ satisfying $\Delta \circ \Delta = 0$. Furthermore, these two operation satisfy the following compatibility relation:  	
	\begin{multline*}
		\Delta(x \cdot y \cdot z) 
		- \Delta(x \cdot y) \cdot z 
		- (-1)^{|y|(|x| + |z|)} \Delta(z \cdot x) \cdot y 
		- (-1)^{|x|(|y|+|z|)} \Delta(y \cdot z) \cdot x \\
		+ \Delta(a) \cdot b \cdot c 
		+ (-1)^{|y|(|x| + |z|)} \Delta(z) \cdot x \cdot y 
		+ (-1)^{|x|(|y|+|z|)} \Delta(y) \cdot z \cdot x
		= 0,
 	\end{multline*}
 	for any homogeneous elements $x,y,z \in \mathfrak{G}$. Note that, the data of a BV algebra structure $(\mathfrak{G},\cdot,\Delta)$ is equivalent to that of a Garstenhaber algebra structure $(\mathfrak{G},\cdot,[-,-])$ endowed with a square zero unary operation $\Delta$ of degree $1$ such that the following equality holds:
 	\begin{equation*}
 		[-,-] = \Delta(- \cdot -) - \big(\Delta(-) \cdot -\big) - \big(- \cdot \Delta(-)\big).
 	\end{equation*}

 	\medskip
 	The operad corresponding the category of all BV algebras is denoted by $\mathcal{BV} := \T(E_{\mathcal{BV}})/ (R_{\mathcal{BV}})$. The graded $\Sm$-module is given as follows, $E_\mathcal{BV} := (0,\K\Delta,\K m, \ldots)$, where $\K \Delta$ is a one-dimensional graded vector space ($\Sm_1$-module) concentrated in degree $1$ and $\K m$ is a one-dimensional graded vector space ($\Sm_2$-module) concentrated in degree $0$. The space of relations $R_{\mathcal{BV}}$ is the $\K[\Sm_3]$-module generated by 
 	\begin{equation*}
 		\begin{cases}
 			m \circ_1 m - m \circ_2 m, ~ \Delta \circ_1 \Delta, \\
 			\Delta \circ_1 m \circ_1 m 
 			- \big((\Delta \circ_1 m) \circ_1 m\big)^{\mathrm{id} + (123) + (132)} 
 			+ \big(\Delta \circ_1 (m \circ_1 m)\big)^{\mathrm{id} + (123) + (132)}. 
 		\end{cases}
 	\end{equation*}   
 	Finally, as a corollary of Theorem \ref{thm_graded_left_adjoint} we obtain the following result. 
 	\begin{corollary}
 		Let $\mathfrak{G} = \oplus_{p \ge 0} \mathfrak{G}_p$ be a BV algebra over $\K$. Then the functor $\mathfrak{G} \otimes - : \mathrm{g}\text{-}\mathrm{ComAlg} \to \mathcal{BV}$ admits a left adjoint if and only if each component $\mathfrak{G}_p$ of $\mathfrak{G}$ is finite-dimensional.
 	\end{corollary}

 	\begin{remark}
 			The existence and description of universal (co)acting bialgebras and Hopf algebras, within the category of unital associative algebras, have been studied in the setting of $\Omega$-algebras in \cite{Agore-omega}. While $\mathcal{P}$-algebras considered in this work can be seen as a special case of $\Omega$-algebras (by forgetting the symmetries of the generating operations and the S-module structure spanned by the generating operations of a $\mathcal{P}$-algebra), the existence of the universal algebra $\mathcal{C}(\mathfrak{a}, \mathfrak{b})$, associated to two $\mathcal{P}$-algebras $\mathfrak{a}$ and $\mathfrak{b}$ as introduced here, does not follow from the results of \cite{Agore-omega}.
 			This is primarily because the algebra $\mathcal{C}(\mathfrak{a}, \mathfrak{b})$ is required to be universal within the category of commutative algebras. Our focus on this category is motivated by its significance in understanding the automorphism groups of $\mathcal{P}$-algebras and in the classification of abelian group gradings on such algebras, as discussed in Section~\ref{sec-6}.
 			The structured framework of $\mathcal{P}$-algebras is also useful to accommodate a wide range of important examples, including graded Lie and Leibniz algebras, graded Poisson algebras, Gerstenhaber algebras, and Batalin–Vilkovisky (BV) algebras by using graded operads instead of operads.
 			%Our choice to work in the framework of $\p$-algebras, rather than the more general setting of $\Omega$-algebras, is motivated by the presence of extensive and well-established body of literature surrounding $\p$-algebras, which we believe offers a richer structural and conceptual foundation for the developments in this paper.
 	\end{remark}

