\smallskip
\section{\large Applications} \label{sec-6}
	In this section, we give two applications of the construction of the universal coacting bialgebra of a finite-dimensional $\mathcal{P}$-algebra. First, we describe group of $\mathcal{P}$-algebra automorphisms of $\mathfrak{a}$ in the Theorem \ref{App-bijection}. Second, we characterize the abelian group gradings on a finite-dimensional $\mathcal{P}$-algebra $\mathfrak{a}$ in Theorem \ref{App-gradings}.

\bigskip
\subsection{Automorphism group of a finite-dimensional $\mathcal{P}$-algebra}~~\\
	Let $\fa$ be a finite-dimensional $\p$-algebra and $\mathcal{C}(\fa)$ be its universal coacting bialgebra. We denote the set of automorphisms of the $\p$-algebra $\fa$ by $\mathrm{Aut}_{\p\text{-}\mathrm{Alg}}(\fa)$. For the bialgebra $\mathcal{C}(\fa)$, denote the set of group-like elements 
	$$G(\mathcal{C}(\fa))=\{P\in \mathcal{C}(\fa) ~|~\Delta_\fa(P)=P\otimes P, ~\varepsilon (P)=1\}.$$
	The set $G(\mathcal{C}(\fa))$ is a monoid with respect to the multiplication on $\mathcal{C}(\fa)$. Let $\mathcal{C}(\fa)^\times$ be the finite dual bialgebra of the bialgebra $\mathcal{C}(\fa)$, defined by
	$$\mathcal{C}(\fa)^\times:=\{\chi\in \mathcal{C}(\fa)^*~|~\chi(I)=0, ~\mbox{for some ideal } I \text{ in }\mathcal{C}(\fa) \text{ with } \text{dim}_\mathbb{K}(\mathcal{C}(\fa)/I)<\infty\}.$$
	Then, let us denote the group of  all invertible group-like elements by $U(G(\mathcal{C}(\fa)^\times))$. With these notations, we get the following result generalizing Agore's and Militaru's result \cite[Theorem 3.1]{Ag-Mil} for finite-dimensional $\p$-algebras. 

	\begin{theorem}\label{App-bijection}
		Let $\fa$ be a finite-dimensional $\p$-algebra and $\mathcal{C}(\fa)$ be its universal coacting bialgebra. Then, the group of $\p$-algebra automorphisms of $\mathfrak{a}$ is isomorphic to the group of all invertible group-like elements $U(G(\mathcal{C}(\fa)^\times))$.
	\end{theorem}

	\begin{proof}
		It follows that the set $G(\mathcal{C}(\fa)^\times)$ is the same as the set of algebra homomorphisms from $\mathcal{C}(\fa)$ to $\mathbb{K}$. 
 		The bijection given in Equation \eqref{bijection1} implies that we have a bijection 
		$$\Theta:\mathrm{Hom}_{\mathrm{ComAlg}}(\mathcal{C}(\fa),\mathbb{K})\rightarrow \mathrm{Hom}_{\p\text{-Alg}}(\mathfrak{a},\fa), \quad \mbox{defined by } \Theta(\Phi)=(\mathrm{id}\otimes \Phi)\circ \eta_\mathfrak{a}.$$
		The vector space $\mathrm{Hom}_{\mathrm{ComAlg}}(\mathcal{C}(\fa),\mathbb{K})$ is a monoid with respect to the composition of maps. A monoid structure on $\mathrm{Hom}_{\mathrm{ComAlg}}(\mathcal{C}(\fa),\mathbb{K})=G(\mathcal{C}(\fa)^\times)$ is given by the convolution product, i.e., 
		$$\Phi_1\star \Phi_2(x_{ij}):=\sum_{s=1}^n\Phi_1(x_{is})\Phi_2(x_{sj}).$$
		It immediately follows that $\Theta$ is an isomorphism of monoids and thus it induces an isomorphism between the invertible elements in the monoids. If $\{a_1,a_2,\ldots,a_n\}$ is a basis of the vector space $\mathfrak{a}$, then the isomorphism between the invertible elements in the monoids is given by the map $$\zeta:U(G(\mathcal{C}(\fa)^\times))\rightarrow \mathrm{Aut}_{\p\text{-Alg}}(\fa),\quad\zeta(\Phi)(a_i):=\sum_{j=1}^n \Phi(x_{ji})a_j.$$
		Thus, the proof of the theorem is complete.
	\end{proof}

\smallskip
\subsection{Classification of abelian group gradings on  a finite-dimensional $\mathcal{P}$-algebra}

	\begin{definition}
		Let $G$ be an abelian group and $\fa$ be a $\p$-algebra given by the operad map $\gamma:\p\rightarrow \mathrm{End}_\fa$. Then, a $G$-grading on the $\p$-algebra is a collection of vector spaces $\{\fa_\sigma~|~\sigma\in G \}$ such that 
		$$\fa=\oplus_{\sigma\in G} \fa_\sigma,\quad\text{and}\quad \gamma(\mu)(x_{\sigma_1},x_{\sigma_2},\ldots,x_{\sigma_k})\in \fa_{\sigma_1\sigma_2\cdots\sigma_k},$$
		for homogeneous elements $x_{\sigma_i}\in \fa_{\sigma_i}$, $i=1,2,\ldots, k$, and $\mu\in \p(k)$.
	\end{definition}

	Let $\mathbb{K}[G]$ be the group algebra of $G$. Then, by Remark \ref{universal bialgebra const} and Diagram \eqref{universal bialgebra prop} we obtain a bijection
	\begin{equation}\label{App-bijection1}
		\mathrm{Hom}_{\mathrm{ComBiAlg}}(\mathcal{C}(\fa),\mathbb{K}[G])\longleftrightarrow 
		\big\{f\in \mathrm{Hom}_{\p\text{-Alg}}(\fa,\fa\otimes \mathbb{K}[G])~|~\fa \text{ becomes} 
		\text{ a right } \mathbb{K}[G]\text{-comodule}\big\}
	\end{equation}

	We now recall that there is a bijection between between the set of $G$-gradings on a vector space $\fa$ and the set of all right $\mathbb{K}[G]$-module structures $f:\fa\rightarrow \fa\otimes \mathbb{K}[G]$. Let $\fa=\oplus_{\sigma\in G}\fa_\sigma$ be a $G$-grading on the vector space $\fa$. The bijection is given as follows: $x\in \fa_{\sigma}$ then $f(x_\sigma)=x_\sigma\otimes \sigma$. Now, we show that the map $f:\fa\rightarrow \fa\otimes \mathbb{K}[G]$ is a $\p$-algebra morphism if and only if it corresponds to a $G$-grading on the $\p$-algebra. The map $f:\fa\rightarrow \fa\otimes \mathbb{K}[G]$ is a $\p$-algebra morphism if the following diagram is commutative
	\begin{equation}\label{diag-app2}
		\begin{CD}
			\p(k)\otimes (\mathfrak{a})^{\otimes k}@>{\gamma}>> \mathfrak{a}\\
  			@V \mathrm{id}\otimes f^{\otimes k}VV @VV f V\\
			\p(k)\otimes (\mathfrak{a}\otimes \mathbb{K}[G])^{\otimes k}@>\overline{\gamma}>> \fa\otimes \mathbb{K}[G].
		\end{CD} 
	\end{equation}
	Diagram \eqref{diag-app2} commutes if and only if for any $\sigma_1,\sigma_2,\ldots,\sigma_k\in G$ and $x_{\sigma_1},x_{\sigma_2},\ldots,x_{\sigma_k}\in \fa$, we have 
	$$\gamma(\mu)(x_{\sigma_1},x_{\sigma_2},\ldots,x_{\sigma_k})\in \fa_{\sigma_1\sigma_2\cdots\sigma_k}.$$
	Consequently, there is a bijection between the following sets
	\begin{equation}\label{App-bijection2}
		\begin{tikzcd}
			\begin{array}{c} \big\{f \in \mathrm{Hom}_{\p\text{-Alg}}(\fa,\fa\otimes \mathbb{K}[G])~|~\text{the vector} \\ \qquad \text{space } \mathfrak{a} \text{ becomes a right } \K[G]\text{-module}\big\} \end{array} && \begin{array}{c} \text{The set of all } G\text{-gradings on the } \\\p\text{-algebra } \mathfrak{a}.  \end{array}
			\arrow[<->, from=1-1, to=1-3]
		\end{tikzcd}
	\end{equation}	

	\begin{prop}\label{App-bijection3}
		There exists a bijection between the set of all $G$-gradings on the finite-dimensional $\p$-algebra $\mathfrak{a}$ and the set $\mathrm{Hom}_{\mathrm{ComBiAlg}}(\mathcal{C}(\fa),\mathbb{K}[G])$. 
	\end{prop}

	\begin{proof}
		The proof follows from the bijections given by  \eqref{App-bijection1} and \eqref{App-bijection2}.
	\end{proof}

	\begin{definition}\label{equivalence of gradings}
		Let $\fa=\oplus_{\sigma\in G}\fa_\sigma$ and $\fa=\oplus_{\sigma\in G}\fa_\sigma^\prime$ be two $G$-gradings on the finite-dimensional $\p$-algebra $\fa$. Then the two gradings are said to be isomorphic if we have a $\p$-algebra automorphism $\phi: \fa\rightarrow \fa$ such that $\phi(\fa_\sigma)=\fa_\sigma^\prime$.
	\end{definition}

	Next, we define a equivalence relation on the set $\mathrm{Hom}_{\mathrm{ComBiAlg}}(\mathcal{C}(\fa),\mathbb{K}[G])$. 

	\begin{definition}\label{conjugates}
		The morphisms $\Phi_1,\Phi_2\in \mathrm{Hom}_{\mathrm{ComBiAlg}}(\mathcal{C}(\fa),\mathbb{K}[G])$ are called conjugates if there exists an element $g\in U(G(\mathcal{C}(\fa)^\times))$ such that $\Phi_2=g\star\Phi_1\star g^{-1}$. 
		Note that 
		%here $g$ is identified with Here, 
		here $``\star"$ is the convolution product in $\mathrm{Hom}_{\mathrm{ComBiAlg}}(\mathcal{C}(\fa),\mathbb{K}[G])$, given by $\Phi_1\star \Phi_2(x)=\sum \Phi_1(x_{(1)})\Phi_2(x_{(2)})$. 
	\end{definition}
	The conjugacy defined in the Definition \ref{conjugates} gives an equivalence relation on the set of bialgebra morphisms from $\mathcal{C}(\fa)$ to $\mathbb{K}[G]$. Let us denote the set of equivalence classes by $\mathrm{Hom}_{\mathrm{ComBiAlg}}(\mathcal{C}(\fa),\mathbb{K}[G])/\sim$. Then, using a similar argument as in the proof of \cite[Theorem 3.5]{Ag-Mil}, we can conclude the following result:

	\begin{theorem}\label{App-gradings}
		Let $G$ be an abelian group and $\fa$ be a finite-dimensional $\p$-algebra. Then, the isomorphism classes of $G$-gradings on $\fa$ bijectively corresponds to the equivalence classes in the set $\mathrm{Hom}_{\mathrm{ComBiAlg}}(\mathcal{C}(\fa),\mathbb{K}[G])/\sim$.
	\end{theorem}

