      \field{journaltitle}{ACM Trans. Multimedia Comput. Commun. Appl.}
      \field{month}{12}
      \field{number}{2}
      \field{title}{VRVul-Discovery: BiLSTM-based Vulnerability Discovery for Virtual Reality Devices in Metaverse}
