\section{Proofs} \label{ap:proof}

\textbf{Proof of Theorem \ref{theorem:efficiency}} \\
We follow the approach used in \cite{Byambadalai2024} to prove the efficiency gain of the adjusted estimation. For completeness of the proof, we first present a variant of Lagrange's identity and Bergstr\"{o}m's inequality in the below lemma, which is useful to prove the efficiency gain of the regression adjustment. 

%% Lemma =====================================
\vspace{0.2cm}
\begin{lemma}
    \label{lemma:L-ind}
    For any 
    $(a_{1}, \dots, a_{K}) \in \mathbb{R}^{K}$
    and 
    $(b_{1}, \dots, b_{K}) \in \mathbb{R}^{K}$
    with $b_{k} > 0 $ for all $k=1, \dots, K$,
    we can show that 
    \begin{align*}
     \sum_{k=1}^{K} \frac{a_{k}^{2}}{b_{k}}   
     - 
     \frac{
     \big (
     \sum_{k=1}^{K} a_{k}
     \big )^2 
    }{
     \sum_{k=1}^{K} b_{k}
    }
    = 
     \frac{
     1
    }{
     \sum_{k=1}^{K} b_{k}
    }
    \cdot 
    \frac{1}{2}
    \sum_{k=1}^{K}
    \sum_{\substack{\ell =1 \\ \ell \neq k}}^K 
    \frac{
    (a_{k} b_{\ell} 
    - 
    a_{\ell} b_{k}
    )^2      
    }{
    b_{k} b_{\ell}
    } ,
    \end{align*}
    which implies 
    Bergstr\"{o}m's inequality, given by 
  \begin{align*}
     \sum_{k=1}^{K} \frac{a_{k}^{2}}{b_{k}}   
     \geq 
     \frac{
     \big (
     \sum_{k=1}^{K} a_{k}
     \big )^2 
    }{ 
     \sum_{k=1}^{K} b_{k}
    }
    . 
    \end{align*}


\end{lemma}
\begin{proof}
    Lagrange's identity is that, 
    for any 
    $(c_{1}, \dots, c_{K}) \in \mathbb{R}^{K}$
    and 
    $(d_{1}, \dots, d_{K}) \in \mathbb{R}^{K}$, 
    \begin{align}
    \label{eq:L-ind}
        \bigg (\sum_{k=1}^{K} c_{k}^2
        \bigg)
        \bigg(\sum_{k=1}^{K} d_{k}^2
        \bigg)
        - 
        \bigg(\sum_{k=1}^{K} c_{k}d_{k}
        \bigg)^2
        =
    \frac{1}{2}
    \sum_{k=1}^{K}
    \sum_{\substack{\ell =1 \\ \ell \neq k}}^K 
     (c_{k} d_{\ell} 
    - 
    c_{\ell} d_{k}
    )^2   .
    \end{align}
    Fix arbitrary 
    $(a_{1}, \dots, a_{K}) \in \mathbb{R}^{K}$
    and 
    $(b_{1}, \dots, b_{K}) \in \mathbb{R}^{K}$
    with $b_{k} > 0 $ for all $k=1, \dots, K$. 
    Then, 
    taking 
    $c_{k} = a_{k} / \sqrt{b_{k}}$ 
    and 
    $d_{k} = \sqrt{b_{k}}$
    for all $k=1, \dots, K$
    in (\ref{eq:L-ind}), we can show that 
    \begin{align*}
        \bigg (
        \sum_{k=1}^{K} 
        \frac{a_{k}^2}{b_{k}}
        \bigg)
        \bigg(\sum_{k=1}^{K} b_{k}
        \bigg)
        - 
        \bigg(\sum_{k=1}^{K} a_{k}
        \bigg)^2
     &   =
    \frac{1}{2}
    \sum_{k=1}^{K}
    \sum_{\substack{\ell =1 \\ \ell \neq k}}^K 
     \bigg (
     \frac{a_{k}}{ \sqrt{b_{k}}}
     \sqrt{b_{\ell}} 
     - 
     \frac{a_{\ell}}{ \sqrt{b_{\ell}}}
     \sqrt{ b_{k}} 
     \bigg )^2   \\ 
     & = 
         \frac{1}{2}
    \sum_{k=1}^{K}
    \sum_{\substack{\ell =1 \\ \ell \neq k}}^K 
    \frac{
    (a_{k} b_{\ell} 
    - 
    a_{\ell} b_{k}
    )^2      
    }{
    b_{k} b_{\ell}
    },
    \end{align*}
    which leads to the desired equality. 
    Also, the last expression in the math display above 
    is non-negative, which leads to Bergstr\"{o}m's inequality. 
\end{proof}
\vspace{0.5cm}
%%================================================================

To establish Theorem \ref{theorem:efficiency}, we first introduce additional notation. Specifically, we define the empirical probability measures of $X$ as 
\begin{align*}
    \widehat{\mathbb{F}}_{X} :=   
    \frac{1}{n}
    \sum_{i=1}^{n} 
    \delta_{X_i}
    \ \ \mathrm{and} \ \ 
    \widehat{\mathbb{F}}_{X}^{(w)} :=   
    \frac{1}{n_{w}}
    \sum_{i=1}^{n} 
    \mathbf{1}_{\{ W_{i} = w \} } \cdot 
    \delta_{X_i},
\end{align*}
for all observations and observations in the treatment group $w \in \mathcal{W}$, respectively. 
Here, $\delta_{x}$ is the measure that assigns mass 1 at $x \in \mathcal{X}$
and thus $\widehat{\mathbb{F}}_{X}$ and $\widehat{\mathbb{F}}_{X}^{(w)}$ can be interpreted as the random discrete
probability measures, which put mass $1/n$  and $1/n_{w}$ at each of the $n$ and $n_{w}$ points $\{X_{i}\}_{i=1}^{n}$
and 
$\{X_{i}:W_{i} =w\}_{i=1}^{n}$, respectively. 
Given a real-valued function $f: \mathcal{X} \to \mathbb{R}$, we denote by 
\begin{align*}
    \widehat{\mathbb{F}}_{X} f 
    = \int f d \widehat{\mathbb{F}}_{X} 
    = \frac{1}{n} \sum_{i=1}^{n}f(X_{i}) 
\end{align*}
and 
\begin{align*}
    \widehat{\mathbb{F}}_{X}^{(w)} f 
    = \int f d \widehat{\mathbb{F}}_{X}^{(w)} 
    = \frac{1}{n_{w}} \sum_{i=1}^{n} \mathbf{1}_{\{ W_{i} = w \} } \cdot f(X_{i}) . 
\end{align*}

Given that the true conditional distribution $\gamma_{y}^{(w)}(X) \equiv F_{Y(w)|X}(y|X)$, 
the infeasible version of regression-adjusted distribution function for treatment $w \in \mathcal{W}$ is written as
\begin{align*}
  \widetilde{\mathbf{F}}_{Y(w)}(y)
  = 
  \widehat{\mathbf{F}}_{Y(w)}^{empirical}(y)
  - 
  (\widehat{\mathbb{F}}_{X}^{(w)} - \widehat{\mathbb{F}}_{X})
  \gamma_{y}^{(w)}. 
\end{align*}




