        \big). 
    \end{align}
    Fix any two distinct treatment statuses $w, w' \in \mathcal{W}$. 
    We can write 
  $
  \widetilde{\mathbf{F}}_{Y(w)}(y)
  = 
  \big (\widehat{\mathbf{F}}_{Y(w)}^{empirical}(y)
  - \widehat{\mathbb{F}}_{X}^{(w)}\gamma_{y}^{(w)}
  \big ) 
  +
  \widehat{\mathbb{F}}_{X} \gamma_{y}^{(w)} 
  $
  and also  
  $\widehat{\mathbb{F}}_{X}  \gamma_{y}^{(w)} = \sum_{v\in \mathcal{W}} 
  \hat{\pi}_{v} \widehat{\mathbb{F}}_{X}^{(v)}  \gamma_{y}^{(w)} 
  $.   
  Given random sample and the bi-linear property of the covariance function, 
  we can show that 
  \begin{align*}
        \text{Cov} \Big(
        \widetilde{\mathbf{F}}_{Y(w)}(y), 
        \widetilde{\mathbf{F}}_{Y(w')}(y) 
        \Big)
        =&
        \text{Cov}
        \Big(
        \widehat{\mathbf{F}}_{Y(w)}^{empirical}(y)
        - \widehat{\mathbb{F}}_{X}^{(w)} \gamma_{y}^{(w)} ,
        \hat{\pi}_{w'}\widehat{\mathbb{F}}_{X}^{(w')}  \gamma_{y}^{(w')} 
        \Big ) 
        \\ 
        & + \text{Cov}
        \big(
        \hat{\pi}_{w}\widehat{\mathbb{F}}_{X}^{(w)}  \gamma_{y}^{(w)}, 
        \widehat{\mathbf{F}}_{Y(w')}^{empirical}
        - \widehat{\mathbb{F}}_{X}^{(w')} \gamma_{y}^{(w')}
        \big ) \\
        & + \text{Cov}
        \big(
        \widehat{\mathbb{F}}_{X}  \gamma_{y}^{(w)}, 
        \widehat{\mathbb{F}}_{X}  \gamma_{y}^{(w')}
        \big ) 
    , 
    \end{align*}
    where it can be shown that the first and second terms on the right-hand side are equal zero, due to the fact that
    $     E \big [   \widehat{\mathbf{F}}_{Y(w)}^{empirical}(y)
        - \widehat{\mathbb{F}}_{X}^{(w)}\gamma_{y}^{(w)}|X_{1}, \dots, X_{n}
        \big ] = 0
    $. 
    Furthermore, under the random sample assumption, we can show that 
    \begin{align*}
    \text{Cov}
        \big(
        \widehat{\mathbb{F}}_{X}  \gamma_{y}^{(w)}, 
        \widehat{\mathbb{F}}_{X}  \gamma_{y}^{(w')}
        \big ) =
        n^{-1}
      \text{Cov}
        \big(
         \gamma_{y}^{(w)}(X), 
         \gamma_{y}^{(w')}(X)
        \big )
        \end{align*}. 
        Thus, we can prove the equality in (\ref{eq:cov-A}).

    % variance- covariance 
    Next, we compare the variance-covariance matrices of the simple and regression-adjusted estimators.
    By applying the result from part (a) of this theorem and the one in (\ref{eq:cov-A}), we are able to show that
    \begin{align*}
    & n 
    \big \{
     \text{Var} \big (
    \widehat{\theta}_{y}^{empirical}
    \big ) 
    -
    \text{Var} \big (
    \widetilde{\theta}_{y}
    \big )  
    \big \} \\ 
    & \ \ \ \ \ \ 
    = 
    \left [
    \begin{array}{cccc}
     \frac{1-\pi_{1}}{\pi_{1}}
    \text{Var}
      \big (
      \gamma_{y}^{(1)}(X)       
      \big ),
    & 
    -\text{Cov}
        \big(
         \gamma_{y}^{(1)}(X), 
         \gamma_{y}^{(2)}(X)
        \big ),   
        & 
        \dots,  
        & 
        -\text{Cov}
        \big(
         \gamma_{y}^{(1)}(X), 
         \gamma_{y}^{(K)}(X)
        \big )  \\
        -\text{Cov}
        \big(
         \gamma_{y}^{(2)}(X), 
         \gamma_{y}^{(1)}(X)
        \big ),   
        &     
        \frac{1-\pi_{2}}{\pi_{2}}
    \text{Var}
      \big (
      \gamma_{y}^{(2)}(X)    
      \big ), 
        & \dots,  
        & 
        -\text{Cov}
        \big(
         F_{Y(2)|X}, 
         F_{Y(K)|X}
        \big ) 
        \\ 
          \vdots &\vdots&\ddots & \vdots\\ 
        -\text{Cov}
        \big(
         \gamma_{y}^{(K)}(X), 
         \gamma_{y}^{(1)}(X)
        \big ),   
        &     
        -\text{Cov}
        \big(
         \gamma_{y}^{(K)}(X), 
         \gamma_{y}^{(2)}(X)
        \big ), 
        & \dots,  
        & 
        \frac{1-\pi_{K}}{\pi_{K}}
    \text{Var}
      \big (
      \gamma_{y}^{(K)}(X)       
      \big )
    \end{array}
    \right ]  + o(1),
 \end{align*}
which can be written as  
\begin{align*}
       n 
    \big \{
     \text{Var} \big (
    \widehat{\theta}_{y}^{empirical}
    \big ) 
    -
    \text{Var} \big (
    \widetilde{\theta}_{y}
    \big )  
    \big \}
    = 
    E 
    \Big [
     \big (\gamma_{y}(X) - E[\gamma_{y}(X)]\big) 
     A
     \big(\gamma_{y}(X) - E[\gamma_{y}(X)]\big)^{\top} 
    \Big ] + o(1),
\end{align*}
where 
$\gamma_{y}(X) = [\gamma_{y}^{(1)}(X), \dots, \gamma_{y}^{(K)}(X)]^{\top}$ and  
\begin{align*}
    A:= 
        \left [
    \begin{array}{cccc}
    {\pi}_{1}^{-1} - 1,
    & 
    -1,   
        & 
        \dots,  
        & 
        -1 \\
        -1,   
        &     
    {\pi}_{2}^{-1} - 1,
        & \dots,  
        & 
        -1 
        \\ 
          \vdots &\vdots&\ddots & \vdots\\ 
        -1,   
        &     
        -1, 
        & \dots,  
        & 
    {\pi}_{K}^{-1} - 1
    \end{array}
    \right ] .
    \end{align*}
    The variant of 
    Lagrange's identity
    in 
    Lemma \ref{lemma:L-ind}
    with $\sum_{w \in \mathcal{W}} \pi_{w} =1$
    shows that, 
    for an arbitrary vector $v:=(v_{1}, \dots, v_{K})^{\top} \in \mathbb{R}^{k}$,  
    \begin{align*}
     & v^{\top}
     \big (\gamma_{y}(X) - E[\gamma_{y}(X)]\big) 
     A
     \big(\gamma_{y}(X) - E[\gamma_{y}(X)]\big)^{\top} 
     v \\ 
      & \ \ = 
     \sum_{w \in \mathcal{W}}
     \frac{
     v_{w}^{2}
     \big ( 
     \gamma_{y}^{(w)}(X)
     -
     E[\gamma_{y}^{(w)}(X)]
     \big )^{2}
     }{
        \pi_{w}
     } 
      - 
     \bigg (
     \sum_{w \in \mathcal{W}}
     v_{w}
     \big ( 
     \gamma_{y}^{(w)}(X)
     -
     E[\gamma_{y}^{(w)}(X)]
     \big )
     \bigg )^{2} \\ 
     & \ \ \  = 
     \frac{1}{2}
    \sum_{w \in \mathcal{W}} 
    \sum_{\substack{w' \in \mathcal{W} \\ w' \neq w}}
     \frac{
     \big \{ 
         v_{w}
         \big ( 
         \gamma_{y}^{(w)}(X)
         -
         E[\gamma_{y}^{(w)}(X)]
         \big )
         {\pi}_{w'}
         -
         v_{w'}
         \big ( 
         \gamma_{y}^{(w')}(X)
         -
         E[\gamma_{y}^{(w')}(X)]
         \big )
         {\pi}_{w}     \big \} ^{2}
     }{
     {\pi}_{w}
     {\pi}_{w'}
     } . 
    \end{align*}
    It follows that 
    \begin{align*} 
       v^{\top}
    \big \{
     \text{Var} \big (
    \widehat{\theta}_{y}^{empirical}
    \big ) 
    -
    \text{Var} \big (
    \widetilde{\theta}_{y}
    \big )  
    \big \}
    v
    = 
    \frac{1}{2}
    \sum_{w \in \mathcal{W}} 
    \sum_{\substack{w' \in \mathcal{W} \\ w' \neq w}}
     \frac{
     \text{Var} 
     \Big (
         v_{w}
         \gamma_{y}^{(w)}(X)
         {\pi}_{w'}
         -
         v_{w'}
         \gamma_{y}^{(w')}(X)
         {\pi}_{w}     
         \Big )
     }{
     {\pi}_{w}
     {\pi}_{w'}
     } 
    + o(n^{-1}). 
    \end{align*}
  The above equality implies the desired positive semi-definiteness result, because $ \text{Var} 
     \big (
         v_{w}
         \gamma_{y}^{(w)}(X)
         {\pi}_{w'}
         -
         v_{w'}
         \gamma_{y}^{(w')}(X)
         {\pi}_{w}     
         \big )
         \geq  0$
         for any 
         $w, w' \in \mathcal{W}$ with $ w \neq w'$.

  Furthermore, the positive definite result holds when 
    $ \text{Var} 
     \big (
         v_{w}
         \gamma_{y}^{(w)}(X)
         {\pi}_{w'}
         -
         v_{w'}
         \gamma_{y}^{(w')}(X)
         {\pi}_{w}     
         \big )
         > 0$
         for any $v \in \mathbb{R}^{k}$ with $v \neq 0$
         and 
         for any 
         $w, w' \in \mathcal{W}$ with $ w \neq w'$. 
         Because 
        $v \in \mathbb{R}^{k}$ is chosen arbitrarily except  $v \neq 0$
        and $\pi_{w} \in (0,1)$ for all $w \in \mathcal{W}$, 
        the condition for the positive definiteness can be written as  
         $
             \text{Var} 
         \big (
         \gamma_{y}^{(w)}(X)
         -
         r
         \cdot 
         \gamma_{y}^{(w')}(X)
         \big )
         > 0
         $
         for any  $r \in \mathbb{R}$
         and 
         for any 
         $w, w' \in \mathcal{W}$ with $ w \neq w'$. 
\end{proof}



\section{Multiplier Bootstrap Procedure} \label{app:multiplier-bootstrap} 
We obtain pointwise confidence bands for distributional parameters, which are functionals of distribution functions, using multiplier bootstrap following \cite{chernozhukov2013inference} and \cite{belloni2017program}. We outline the procedure to obtain pointwise confidence bands in Algorithm \ref{alg:uniform-band} where $\phi((\theta_y)_{y\in\mathcal Y})$ is some functional of $(\theta_y)_{y\in\mathcal Y}$.

As a prerequisite, letting $\pi:=(\pi_1, \dots, \pi_K)^{\top}$, define moment functions
\begin{align*}
\psi_y(Z; \theta_y, \gamma_y, \pi):= 
    \big (\psi_y^{(1)}(Z; \theta_y, \gamma_y, \pi_1), \dots, 
    \psi_y^{(K)}(Z; \theta_y, \gamma_y, \pi_K) \big) ^{\top},    
\end{align*}
where, for each $w \in \mathcal{W}$,  
\begin{align} 
\label{eq:phi-def}
    \psi_y^{(w)}(Z; \theta_y, \gamma_y, \pi_w)
     := & 
    \frac{\mathbf{1}_{\{W=w\}} \cdot (\mathbf{1}_{\{Y\leq y\}}-\gamma_{y}^{(w)}(X))}{\pi_{w}} + \gamma_y^{(w)}(X) - \theta_y^{(w)}.
\end{align}

\begin{algorithm}[!h]
   \caption{Multiplier bootstrap procedure to obtain pointwise confidence bands}
   \label{alg:uniform-band}
\begin{algorithmic}
\State
\State {\bfseries Input:} Data $\{(X_i, W_i, Y_i)\}_{i=1}^{n}$; point estimates $\hat\theta_y$; influence functions $\hat \psi_y(Z_i):=\psi_y(Z_i; \hat\theta_y, \hat\gamma_y, \hat\pi)$

\State
   \begin{enumerate}
    \item[(1)] Draw multipliers $\{\xi_i\}_{i=1}^{n}= \{m_{1,i}/\sqrt{2} + ((m_{2,i})^2-1)/2\}_{i=1}^{n}$ independently from the data $\{Z_i\}_{i=1}^{n}$, where $m_{1,i}$ and $m_{2,i}$ are i.i.d. draws from two independent standard normal random variables.
    \item[(2)] For each $y\in\mathcal Y$, obtain the bootstrap draws $\phi^b(\hat\theta_y)$ of $\phi(\hat\theta_y)$ as 
    \begin{equation*}
    \phi^b(\hat\theta_y) =\phi(\hat\theta_y^b) \text{ where } \hat\theta_y^b=\hat\theta_y + \frac{1}{n}\sum_{i=1}^{n} \xi_i \hat \psi_y(Z_i).
    \end{equation*}
    \item[(3)] Repeat (1)-(2) $B$ times and index the bootstrap draws by $b=1, \dots, B$.
    \item[(4)] Obtain bootstrap standard error estimates for $\phi(\hat\theta_y)$ for each $y\in\mathcal Y$ as 
    \begin{equation*}
        \hat \Sigma(y) = \sum_{b=1}^{B}\frac{(\phi^b(\hat\theta_y) - \bar\phi(\hat\theta_y))^2}{B-1},
    \end{equation*}
    where $\bar\phi(\hat\theta_y)=\sum_{b=1}^{B}\frac{\phi^b(\hat\theta_y)}{B}$.
    \item[(5)] Construct $(1-\alpha)\times 100\%$ pointwise confidence band for $\phi((\theta_y)_{y\in\mathcal Y})$ as 
    \begin{equation*}
        I^{1-\alpha} := \{[\phi(\hat\theta_y) \pm \hat z_{1-\alpha} \times \hat\Sigma(y)]: y\in\mathcal Y\}.
    \end{equation*} 
\end{enumerate}
%\ENDFOR

\State {\bfseries Result:} $(1-\alpha)\times 100\%$ confidence band $I^{1-\alpha}$ for $\phi((\theta_y)_{y\in\mathcal Y})$
\end{algorithmic}
\end{algorithm}



