\section{Validity of Sub-linear Assumption}
\label{appendix:sub-linear}

\subsection{Computational Analysis of Linear Regression}

Consider the following notation:
\begin{itemize}
    \item $X \in \mathbb{R}^{n \times d}$: input matrix
    \item $Y \in \mathbb{R}^{n \times p}$: output matrix with $p$ target dimensions  
    \item $B \in \mathbb{R}^{d \times p}$: parameter matrix
\end{itemize}
We assume $n \gg d, p$.

\vspace{0.5cm}
\textbf{Joint Multivariate Linear Regression.} 
The closed-form solution for joint multivariate linear regression is given by
\begin{align*}
% \label{eq:joint-solution}
B = (X^\top X)^{-1} X^\top Y .
\end{align*}

The computational complexity consists of the following components:
\begin{itemize}
    \item $\mathcal{O}(nd^2)$ for computing $X^\top X$
    \item $\mathcal{O}(d^3)$ for matrix inversion  
    \item $\mathcal{O}(ndp)$ for computing $X^\top Y$
    \item $\mathcal{O}(d^2p)$ for the final matrix multiplication
\end{itemize}

Therefore, the total computational cost of joint multivariate linear regression is 
\begin{align}
\label{eq:joint-complexity}
\mathcal{O}(nd^2 + d^3 + ndp + d^2p) .
\end{align}

\textbf{Separate Univariate Linear Regression.} 
For training univariate linear regression separately, 
we compute the regression coefficient for each output dimension $y^{(i)} \in \mathbb{R}^n$:
\begin{align*}
% \label{eq:separate-solution}
\beta^{(i)} = (X^\top X)^{-1} X^\top y^{(i)} .
\end{align*}

The computational cost per output dimension $y^{(i)}$ is $\mathcal{O}(nd^2 + d^3)$. 
Consequently, the total computational cost over all $p$ outputs is 
\begin{align}
\label{eq:separate-complexity}
\mathcal{O}(pnd^2 + pd^3) .
\end{align}

\textbf{Efficiency Comparison.} 
Given that $n \gg d, p$, we observe that
\begin{align}
\label{eq:complexity-comparison}
\mathcal{O}(nd^2 + d^3 + ndp + d^2p) \ll \mathcal{O}(pnd^2 + pd^3) ,
\end{align}
which demonstrates that linear regression satisfies the sub-linear computational scaling property outlined in Assumption 3, 
confirming that joint estimation provides significant computational advantages over separate univariate approaches.

\subsection{Empirical Computation Complexity Analysis of Neural Networks}
We hypothesize that deeper architectures, such as ResNet can achieve substantially higher computational cost reduction under our proposed framework. To empirically validate this hypothesis, we analyze the computational complexity of several neural network architectures by measuring multiply-accumulate (MAC) operations for models with single versus multiple outputs using the \texttt{ptflop} Python library.

\begin{table}[h!]
    \centering
    \begin{tabular}{|l|c|c|}
        \hline
        Model & 1 output & 20 outputs \\
        \hline
        Our Dense NN & 11.2 K & 12.4 K \\
        BERT & 852.23 M & 852.24 M \\
        ResNet-18 & 1.82 G & 1.82 G \\
        \hline
    \end{tabular}
    \caption{Computational complexity comparison across different neural network architectures measured in MAC operations}
    \label{tab:computational_complexity}
\end{table}

These results demonstrate that complex models satisfy the sub-linear scaling property outlined in Assumption \ref{assumption:computation}. Notably, the computational complexity of both BERT and ResNet-18 remains virtually unchanged when scaling from single to multiple outputs, confirming near-constant computational overhead. This behavior arises because modern deep architectures such as convolutional neural networks (CNNs) and Transformers typically employ deep encoding layers that extract shared representations, making them particularly well-suited for our multi-task learning approach.



